const STATS_KEY="rex_quiz_stats_v2",EXAM_COURSE={"115-1":"medsurg","114-2":"medsurg","114-1":"medsurg","113-3":"medsurg","113-2":"medsurg","113-1":"medsurg","112-3":"medsurg","112-2":"medsurg","112-1":"medsurg","114-3":"medsurg","111-2":"medsurg","111-1":"medsurg","110-2":"medsurg","110-1":"medsurg","109-1":"medsurg","109-2":"medsurg","108-1":"medsurg","108-2":"medsurg"},QS=[{n:1,subj:"神經系統",q:"陳先生T3～T5脊髓損傷，目前血壓250/140 mmHg，心跳50～55次／分，有大量出汗情形，主訴頭部嚴重疼痛、看東西模糊，超過6小時以上未解尿，陳先生可能發生何種現象？",opts:["A.神經性休克","B.自主神經過度反射","C.脊髓自動症","D.脊髓休克"],ans:[1],expl:"自主神經過度反射（Autonomic Dysreflexia）好發於T6以上脊髓損傷。觸發因素最常見為膀胱過度膨脹（>6小時未解尿）。表現：高血壓、反射性心跳變慢、大量出汗、頭痛、視力模糊。處理：立即坐起、導尿排除誘因。"},{n:2,subj:"神經系統",q:"有關重症肌無力之敘述，下列何者正確？①屬於自體免疫疾病，體內產生攻擊Ach接受器的抗體 ②第一型僅侵犯眼肌，造成複視和眼瞼下垂 ③四肢肌肉的無力發生在遠端和下肢且為不對稱 ④當侵犯肋間肌，通氣容積會減少，嚴重呼吸困難致死",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[1],expl:"重症肌無力是自體免疫疾病，抗體攻擊Ach受器（①✓）。第一型僅侵犯眼肌（②✓）。四肢無力為近端、對稱性（③✗）。侵犯肋間肌→呼吸衰竭（④✓）。答案①②④=B。"},{n:3,subj:"神經系統",q:"有關腦膜炎病人接受腰椎穿刺檢查，下列敘述何者錯誤？",opts:["A.懷疑顱內壓升高時不宜執行腰椎穿刺","B.腰椎穿刺是將穿刺針由第三與第四腰椎椎間垂直穿入","C.腦脊髓液分析會出現總蛋白質減少及葡萄糖增加","D.正常之腦脊髓液壓力為70～180 mmH₂O"],ans:[2],expl:"腦膜炎CSF：蛋白質↑、葡萄糖↓（細菌消耗）。選項C說「蛋白質減少及葡萄糖增加」完全相反，C為錯誤。顱內壓升高禁穿✓；L3-L4穿刺✓；正常CSF壓力70-180 mmH₂O✓。"},{n:4,subj:"神經系統",q:"有關不同類型腦中風發作之比較，下列敘述何者錯誤？",opts:["A.暫時性缺血發作是血栓型腦中風之警訊","B.栓塞型腦中風的臨床症狀會突然發生","C.出血性腦中風會有劇烈頭痛前驅症狀","D.缺血性腦中風通常發作於活動時"],ans:[3],expl:"缺血性腦中風（血栓型）通常發生在「安靜休息或睡眠時」，因血流緩慢易形成血栓，D錯誤。出血性才是在活動或情緒激動時發作。"},{n:5,subj:"神經系統",q:"病人跌倒造成腦部枕葉受損時出現的症狀，下列何者正確？",opts:["A.無法控制情緒","B.無法辨識本體感受","C.無法解析所看見的東西","D.近、遠期記憶受損"],ans:[2],expl:"枕葉（Occipital lobe）= 視覺皮質。枕葉受損→視覺失認症，看得見但無法理解所見之物（C✓）。情緒=額葉；本體感受=頂葉；記憶=顳葉。"},{n:6,subj:"消化系統",q:"有關急性胰臟炎的敘述，下列何者正確？",opts:["A.因膽道疾病導致膽汁與胰液逆流而引起","B.穆菲氏徵象（Murphy's sign）是常見表徵","C.康復期應採高脂飲食","D.血清中鈣濃度通常會升高"],ans:[0],expl:"急性胰臟炎最常見病因：①膽道疾病（膽石阻塞→膽汁逆流入胰管）②酒精（A✓）。Murphy's sign是膽囊炎的表徵。低血鈣（脂肪皂化）而非高血鈣。康復後應低脂飲食。"},{n:7,subj:"消化系統",q:"有關口服膽囊攝影檢查（oral cholecystography）的敘述，下列何者正確？",opts:["A.檢查前需採低脂飲食","B.急性膽囊炎為適應症之一","C.檢查前30分鐘服下含碘顯影劑","D.檢查後若排尿有燒灼感代表出現泌尿道感染"],ans:[0],expl:"口服膽囊攝影：檢查前採低脂飲食（A✓），讓膽囊充分儲存膽汁。顯影劑應在8-12小時前服用。急性膽囊炎是禁忌症。排尿燒灼是含碘顯影劑由腎排出的正常現象。"},{n:8,subj:"消化系統",q:"有關口腔癌的敘述，下列何者正確？",opts:["A.發生部位以上顎黏膜最多","B.以鱗狀上皮細胞癌最常見","C.咀嚼不順為常見早期徵象","D.口腔有無痛且不易癒合的潰瘍為常見晚期徵象"],ans:[1],expl:"口腔癌最常見部位是舌頭；組織學以鱗狀上皮細胞癌最常見（B✓，占90%以上）；無痛潰瘍是早期警訊（不是晚期）。"},{n:9,subj:"消化系統",q:"肝性腦病變可能出現的臨床表徵，下列何者錯誤？",opts:["A.深腱反射消失","B.肌肉僵直、抽搐發作","C.巴賓斯基反射（Babinski's sign）陽性","D.非昏迷期會出現手掌撲翼樣震顫（asterixis）"],ans:[0],expl:"肝性腦病變早期：深腱反射「亢進」（不是消失）。撲翼樣震顫是典型早期表徵✓；肌肉僵直✓；Babinski陽性✓。A描述的「消失」是晚期昏迷才出現。"},{n:10,subj:"消化系統",q:"因闌尾炎破裂而懷疑有腹膜炎病人之臨床表徵，下列何者正確？①觸診腹部僵硬 ②強烈的反彈痛 ③腸蠕動音增加 ④腹部叩診為實音",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[0],expl:"腹膜炎三大徵象：腹肌僵硬（板狀腹）①✓、反彈痛②✓、腸蠕動音減少（腸麻痺）③✗。答案①②=A。"},{n:11,subj:"骨骼肌肉",q:"病人因左側股骨骨折而接受石膏制動之治療，下列敘述何者錯誤？",opts:["A.上石膏前，部位皮膚要用石膏襪套及棉墊包覆","B.石膏乾燥過程中，左側上石膏處不要覆蓋衣物","C.左側肢體如果出現6P，表示可能有腔隙症候群","D.皮膚如果出現瘀斑，表示可能有低血容性休克"],ans:[3],expl:"石膏護理：上前先用棉墊✓；乾燥中不覆蓋（散熱）✓；6P=腔隙症候群✓。皮膚瘀斑→代表皮膚受壓或骨折處出血，不代表低血容性休克（D✗）。"},{n:12,subj:"骨骼肌肉",q:"有關不同關節炎之比較，下列何者正確？",opts:["A.類風濕性關節炎是一種與老化有關的疾病","B.退化性關節炎是一種嘌呤代謝異常的疾病","C.痛風性關節炎好發於男性四肢遠端關節","D.退化性關節炎好發於55歲以上女性周邊小關節"],ans:[2],expl:"痛風（嘌呤代謝異常）好發男性，最常侵犯足部大拇趾（遠端關節）（C✓）。RA=自體免疫；退化性=退化（非嘌呤）；退化性好發承重關節（膝、髖）非小關節。"},{n:13,subj:"感官系統",q:"有關急性中耳炎的醫療處置，下列何者錯誤？",opts:["A.抗生素的使用要持續3～5天","B.疼痛發燒可使用解熱鎮痛劑","C.鼓膜腫脹時可行鼓膜切開術（myringotomy）","D.使用減輕鼻充血藥物，幫助耳咽管功能恢復"],ans:[0],expl:"急性中耳炎抗生素療程應持續「10～14天」（不是3～5天），確保完全清除細菌防止復發。A錯誤。"},{n:14,subj:"其他",q:"下列何種病毒與罹患鼻咽癌有關？",opts:["A.EB病毒（Epstein-Barr virus）","B.COVID-19病毒（Coronavirus Disease-2019）","C.A型流感病毒（Influenza A virus）","D.B型流感病毒（Influenza B virus）"],ans:[0],expl:"EB病毒（Epstein-Barr virus）是鼻咽癌（NPC）的重要致病因子。記憶：EB→鼻咽癌；HPV→子宮頸癌；HBV/HCV→肝癌；H. pylori→胃癌。"},{n:15,subj:"感官系統",q:"有關病人使用青光眼用藥Timolol的護理指導，下列何者錯誤？",opts:["A.是一種縮瞳劑","B.可減少眼球內房水量","C.氣喘病人禁止使用","D.給藥前需評估是否有心搏徐緩"],ans:[0],expl:"Timolol是β-阻斷劑，減少房水生成→降眼壓。它「不是縮瞳劑」（縮瞳劑是Pilocarpine）。氣喘禁用✓；心搏徐緩要評估✓。A錯誤。"},{n:16,subj:"心臟血管",q:"有關心包膜炎照護之敘述，下列何者不適宜？",opts:["A.鼓勵病人採平躺及深呼吸，以減緩胸痛","B.發燒時應臥床休息，以減少心肌耗氧量","C.退燒藥可使用阿斯匹靈（Aspirin）","D.提供高蛋白、高醣飲食"],ans:[0],expl:"心包膜炎疼痛在「坐起身前傾」時減輕（心包減少摩擦），平躺會加重疼痛。故A不適宜。Aspirin有抗發炎作用✓；臥床休息✓；高蛋白高醣✓。"},{n:17,subj:"心臟血管",q:"有關血栓性靜脈炎之評估與照護原則，下列敘述何者錯誤？",opts:["A.病人足背屈曲時，腓腸肌會產生疼痛","B.口服Coumadin可預防及治療靜脈血栓","C.應定期按摩病人患肢，以促進靜脈循環","D.協助病人抬高患肢，可減輕炎症及疼痛"],ans:[2],expl:"按摩患肢「禁止」（C✗），可能使血栓脫落造成肺栓塞。Homans'sign✓；Coumadin抗凝✓；抬高促靜脈回流✓。"},{n:18,subj:"心臟血管",q:"有關慢性靜脈功能不全引起的鬱滯性潰瘍（stasis ulcer）的肢體評估，下列敘述何者正確？①潰瘍部位多發生於足踝內側 ②皮膚出現色素沉著 ③肢體呈現凹陷性水腫 ④趾甲變厚 ⑤腳趾潰瘍",opts:["A.①②③","B.①④⑤","C.②③⑤","D.③④⑤"],ans:[0],expl:"靜脈性潰瘍：足踝內側①✓；含鐵血黃素沉積→色素沉著②✓；靜脈回流不佳→凹陷性水腫③✓。趾甲變厚、腳趾潰瘍是動脈性（缺血性）的表徵。答案①②③=A。"},{n:19,subj:"心臟血管",q:"有關心因性休克護理重點之敘述，下列何者錯誤？",opts:["A.依醫囑使用促進心臟幫浦之藥物","B.使用溫熱療法（如電毯）提高全身周邊循環血量","C.為提高心輸出量，必要時協助放置主動脈內氣球幫浦（IABP）","D.給予氧氣使用"],ans:[1],expl:"心因性休克不可使用溫熱療法，血管擴張會加重低血壓。應使用血管收縮藥或IABP輔助。B錯誤。"},{n:20,subj:"心臟血管",q:"下列何者為右心衰竭的臨床表徵？",opts:["A.呼吸困難","B.粉紅色泡沫痰","C.下肢水腫","D.少尿或無尿"],ans:[2],expl:"右心衰→體循環鬱血：頸靜脈怒張、肝腫大、腹水、下肢凹陷性水腫（C✓）。左心衰→肺循環鬱血：呼吸困難、粉紅色泡沫痰。記憶：右=下半身水腫；左=肺水腫。"},{n:21,subj:"腫瘤血液",q:"惡性腫瘤細胞與正常細胞的不同特性之比較，下列何者正確？①細胞缺乏接觸抑制 ②細胞可快速增殖 ③細胞未分化狀態 ④當需要更多細胞時會發生增殖 ⑤黏著性低而活動力高",opts:["A.①②③","B.①③④","C.①③⑤","D.②④⑤"],ans:[2],expl:"惡性腫瘤：缺乏接觸抑制①✓；未分化③✓；黏著性低→容易轉移⑤✓。快速增殖②也正確但標準答案選C=①③⑤。④是正常細胞特性。"},{n:22,subj:"腫瘤血液",q:"王老太太背部骨骼疼痛就醫，醫生懷疑是多發性骨髓瘤，下列何者為確定診斷的主要標準？",opts:["A.骨髓內漿細胞比例為40%","B.血清IgG 為2 gm/dL","C.X光檢查發現有骨頭侵蝕現象","D.IgA＜0.1 gm/dL"],ans:[0],expl:"多發性骨髓瘤主要診斷標準：骨髓漿細胞≥10%（A的40%符合，A✓）。IgG>3.5 g/dL才達標（B的2gm/dL未達）。X光骨侵蝕是輔助標準。"},{n:23,subj:"腫瘤血液",q:"王老太太因便秘、意識不清，家屬送至急診求治，發現有心律不整的問題，下列何者是王老太太最有可能發生的問題？",opts:["A.高血磷","B.高血鈣","C.高血鉀","D.高尿酸"],ans:[1],expl:"多發性骨髓瘤→骨骼破壞→大量鈣釋放→高血鈣。高血鈣症狀：便秘、意識改變（Bones, Groans, Stones, Psychic Moans）、心律不整。答案B。"},{n:24,subj:"腫瘤血液",q:"王老太太意識恢復後，針對其目前的問題，下列護理措施何者正確？",opts:["A.鼓勵多喝牛奶","B.限制水份補充","C.給與Allopurinol藥物治療","D.給與Zometa藥物治療"],ans:[3],expl:"高血鈣治療：Zometa（雙磷酸鹽）→抑制破骨細胞→降血鈣、預防骨折（D✓）。牛奶含鈣→禁止；應大量補水促鈣排出；Allopurinol用於高尿酸。"},{n:25,subj:"腫瘤血液",q:"有關病人接受靜脈輸注化學藥物時，若不慎藥物外滲之護理措施，下列何者正確？",opts:["A.停止輸注並立即拔除針頭","B.應予以放低注射部位","C.以彈繃加壓注射部位","D.注射解毒劑於滲漏部位四周"],ans:[3],expl:"化療藥外滲：①停止輸注②保留針頭（不要拔，需由原針抽吸及注入解毒劑）③抬高患肢④注射解毒劑（D✓）。標準答案D。"},{n:26,subj:"腫瘤血液",q:"有關成年惡性淋巴瘤病人接受骨髓穿刺抽吸術檢查之敘述，下列何者錯誤？",opts:["A.穿刺部位宜選擇肋骨、脊椎或脛骨","B.檢查結果有助於了解造血組織有無異常","C.穿刺部位以紗布敷蓋並至少直接加壓5分鐘以上","D.檢查後要注意是否有出血或感染"],ans:[0],expl:"成人骨髓穿刺選擇：後上腸骨脊（最常用）、胸骨。脛骨只用於嬰幼兒，肋骨和脊椎不是常用部位（A✗）。加壓應至少10-15分鐘（C也有爭議但標準答案A）。"},{n:27,subj:"其他",q:"王先生常年受過敏所苦，想要知道那種過敏原引起過敏反應，下列何項診斷檢查最合適？",opts:["A.伍氏燈檢查（Wood's light test）","B.免疫螢光試驗（immunofluorescence test）","C.刮畫試驗（scratch test）","D.皮膚切片檢查（skin biopsy）"],ans:[2],expl:"找過敏原→皮膚刮畫試驗（scratch test）：將懷疑過敏原滴在刮傷皮膚上，觀察風疹反應（C✓）。伍氏燈=黴菌；免疫螢光=自體免疫；切片=組織病理。"},{n:28,subj:"其他",q:"長期臥床病人採仰臥姿勢時，下列何者是皮膚壓力性損傷較不常發生的部位？",opts:["A.肩胛骨","B.尾骶骨","C.坐骨結節","D.腳跟"],ans:[2],expl:"仰臥位常見壓傷：枕骨、肩胛骨、肘部、尾骶骨、腳跟。坐骨結節是「坐姿」時的好發部位，仰臥時較不常見（C✓）。標準答案C。"},{n:29,subj:"腫瘤血液",q:"吳太太因腫瘤接受化學治療，口腔出現疱疹性齒齦口腔炎（herpetic gingivostomatitis），下列敘述何者正確？",opts:["A.由單純性疱疹第一型病毒（HSV-I）感染所致","B.抗濾過性病毒藥物，如Acyclovir，於症狀嚴重時使用，以免副作用產生","C.患處水泡可擠壓排除液體後應立即清潔乾淨","D.進食後待口腔潰瘍處不痛後再進行口腔護理"],ans:[0],expl:"本題原為送分題（答案更正為#），但A（HSV-I感染）是正確敘述。Acyclovir應儘早使用；水泡不可擠壓；口腔護理每餐後執行不論是否疼痛。"},{n:30,subj:"骨骼肌肉",q:"有關類風濕性關節炎藥物治療之敘述，下列何者正確？",opts:["A.Aspirin能改變疾病的過程或防止關節的破壞","B.選擇性COX-2抑制劑適用於有腸胃道潰瘍病史的高危險病人","C.疾病調節抗風濕藥（DMARDs）為第一線用藥","D.抗瘧疾藥物（奎寧類）主要副作用在聽力損傷"],ans:[1,2],expl:"第30題雙重正確（B或C均給分）。COX-2抑制劑對胃腸道影響小，適用有消化道潰瘍者（B✓）。DMARDs是RA基礎治療（C✓）。Aspirin只能止痛，不能改變病程；奎寧副作用在視網膜毒性（非聽力）。"},{n:31,subj:"其他",q:"有關全身性紅斑性狼瘡（SLE）之臨床表徵，下列敘述何者錯誤？",opts:["A.關節症狀包括發炎、疼痛、腫脹、僵硬等","B.心肺症狀，如心包炎、肋膜炎的發生，對病人預後影響很大","C.中樞神經不受侵犯，不必擔心病人認知問題","D.腎功能下降，應限制蛋白質、水分、鹽分的攝取"],ans:[2],expl:"SLE是全身性自體免疫疾病，幾乎所有器官都可受侵犯。中樞神經確實會受侵犯，可出現神經精神性狼瘡（頭痛、癲癇、認知障礙），C「中樞神經不受侵犯」錯誤。"},{n:32,subj:"呼吸系統",q:"王先生剛接受支氣管鏡檢查後返回病室，下列護理措施何者最適當？",opts:["A.在接下來的8小時內大量補充液體","B.進食前須先確認作嘔反射恢復","C.協助身體躺向健側以利肺擴張","D.靜脈注射Atropine以減少分泌物"],ans:[1],expl:"支氣管鏡使用局部麻醉（噴喉），抑制咽喉反射。檢查後需確認「作嘔反射恢復」才能進食，防嗆咳（B✓）。通常禁食2小時；躺向患側引流分泌物；Atropine術前用。"},{n:33,subj:"呼吸系統",q:"王先生使用呼吸器，突然呼吸器出現壓力過高警報，下列何者為可能的原因？",opts:["A.呼吸器管路積水","B.呼吸器管路鬆脫","C.氣管氣囊漏氣","D.氣胸"],ans:[0,3],expl:"第33題雙重正確（A或D均給分）。壓力過高原因：管路積水（阻力↑）→A✓；氣胸（肺順應性↓，需更高壓力）→D✓。管路鬆脫或氣囊漏氣→空氣洩漏→低壓警報（非高壓）。"},{n:34,subj:"呼吸系統",q:"有關早期氧合不足會出現的徵象或症狀，下列何者最可能？",opts:["A.皮膚發紺","B.躁動不安","C.低血壓","D.心搏過緩"],ans:[1],expl:"早期缺氧：大腦最敏感→躁動、不安、焦慮、判斷力下降（B✓）。發紺是晚期嚴重缺氧（SpO2<85%）。記憶：缺氧先有腦症狀→躁動。"},{n:35,subj:"呼吸系統",q:"李先生因肺結核服用ethambutol（EMB）治療，下列敘述何者正確？",opts:["A.需注意視力模糊及紅綠色盲等副作用","B.尿液會呈現橘紅色","C.補充Vitamin B₆可預防藥物副作用","D.必須與制酸劑併用"],ans:[0],expl:"Ethambutol（EMB）最重要副作用：視神經毒性→視力模糊、紅綠色盲（A✓）。尿液橘紅=Rifampicin；補充B6=Isoniazid（INH）副作用預防；EMB不需制酸劑。"},{n:36,subj:"呼吸系統",q:"有關肺栓塞造成的通氣與灌流比失衡（ventilation and perfusion mismatch）之敘述，下列何者正確？",opts:["A.肺泡與血管間的隔膜增厚，使得氧氣無法擴散進入血流中","B.細小氣管內有大量濃稠的痰液，阻礙肺泡的通氣","C.大部分的肺中有充分的血流灌注，但肺泡中未能有足夠的氣體可進行交換","D.肺泡中有足夠的通氣，但肺中有部分區域血流灌注受阻下降"],ans:[3],expl:"肺栓塞：血栓阻塞肺動脈→灌流（Q）↓，但通氣（V）正常→V/Q比值升高（生理死腔增加）=「有通氣但沒有灌流」→D✓。A=ARDS；B=氣道阻塞；C相反。"},{n:37,subj:"泌尿系統",q:"提供腎絲球過濾率為17 mL/min/1.73m²的病人之護理指導，下列何者正確？",opts:["A.應攝取高鉀食物，以預防因低血鉀導致肌無力","B.鼓勵多攝取蛋白質，以維持體力提升免疫力","C.若皮膚乾燥導致搔癢可用calamine lotion減緩","D.鼓勵病人每日補充水份3,000 mL，以維持腎臟灌流"],ans:[2],expl:"GFR 17→CKD第4期：限鉀（腎排鉀↓→高血鉀）；限蛋白（減少含氮廢物）；限水。皮膚搔癢（尿毒症）可用calamine lotion（爐甘石）局部止癢（C✓）。"},{n:38,subj:"泌尿系統",q:"有關感染性膀胱炎導因之敘述，下列何者最不適當？",opts:["A.常見致病菌之一為大腸桿菌","B.男性因為尿道較長易致膀胱細菌滋生","C.膀胱炎導因常見為上行性細菌感染","D.前列腺肥大影響排尿易致膀胱細菌滋生"],ans:[1],expl:"男性尿道較長（約20cm），細菌不易上行，男性發生率低於女性。「較長易致細菌滋生」邏輯錯誤，B最不適當。大腸桿菌最常見✓；上行感染最常見途徑✓。"},{n:39,subj:"泌尿系統",q:"有關泌尿道檢查之敘述，下列何者正確？",opts:["A.尿流速檢查的病人，須於檢查前禁食","B.腎動脈攝影術檢查的病人，檢查後應多喝水","C.靜脈腎盂攝影術檢查的病人，檢查中採俯臥姿勢","D.經皮腎臟組織切片檢查的病人，檢查中採截石臥姿"],ans:[1],expl:"腎動脈攝影使用含碘顯影劑，檢查後需「多喝水」促排出（B✓）。尿流速不需禁食；靜脈腎盂攝影採仰臥；腎臟切片採俯臥位（不是截石位）。"},{n:40,subj:"泌尿系統",q:"預防腎功能不全病人血鉀過高之飲食護理指導，下列何者正確？",opts:["A.避免熱量攝取不足或長期饑餓","B.建議多攝取雞精用來補充營養","C.需要多使用低鈉鹽或薄鹽醬油","D.建議多吃水果乾減少水分攝取"],ans:[0],expl:"熱量不足→分解肌肉→釋放鉀→高血鉀，要確保足夠熱量（A✓）。雞精含高鉀（B✗）；低鈉鹽含鉀（C✗）；水果乾含鉀量高（D✗）。"},{n:41,subj:"泌尿系統",q:"趙小姐，45歲，無特殊疾病，近來健檢時發現有輸尿管結石約1.8公分，醫師建議行輸尿管鏡碎石術，下列敘述何者錯誤？",opts:["A.沒有傷口但術後要放置導尿管 24～72小時","B.此為門診手術，但必須接受全身麻醉","C.若無特殊限制，術後鼓勵多喝水以利碎石排出","D.術後有嚴重發燒或是嚴重血尿的病人應速回診"],ans:[1],expl:"輸尿管鏡碎石術是「住院手術」（不是門診），需要脊椎或全身麻醉（B中「門診手術」錯誤）。術後放置導尿管✓；多喝水✓；發燒或血尿需回診✓。"},{n:42,subj:"內分泌系統",q:"有關副甲狀腺功能低下之敘述，下列何者正確？",opts:["A.因高血鈣出現沃斯特克氏（Chvostek's）徵象，導致肌肉痙攣","B.因低血磷導致手指顫抖","C.可能會有急性抽搐，導致咬傷舌頭及呼吸道阻塞","D.因身體出現酸中毒，導致手足抽搐症狀惡化"],ans:[2],expl:"副甲狀腺功能低下→PTH↓→低血鈣→神經肌肉興奮性↑→手足抽搐、Chvostek徵象。抽搐可致呼吸道阻塞（C✓）。注意：是「低血鈣」引起，A說高血鈣錯誤。"},{n:43,subj:"內分泌系統",q:"有關嗜鉻細胞瘤切除手術後之護理措施，下列何者錯誤？",opts:["A.注意有無腎上腺功能不全的徵象，必要時由靜脈輸注皮質醇","B.監測每小時尿量，維持尿量在20～25 c.c./小時","C.觀察術後出血情況與腸蠕動狀態","D.依醫囑給與靜脈輸液，以維持體液容積"],ans:[1],expl:"術後尿量應維持≥30 mL/小時（不是20-25 mL/小時），B描述的標準偏低，代表腎灌流不足（B✗）。補充皮質醇✓；觀察出血✓；補充輸液✓。"},{n:44,subj:"內分泌系統",q:"有關腦下垂體前葉功能低下之敘述，下列何者錯誤？",opts:["A.席漢氏症候群（Sheehan's syndrome）發生於腦下垂體切除的病人","B.以生長素（growth hormone）缺乏最常見","C.病人可能會有軟弱無力、血糖偏低等臨床表徵","D.病人可能會有黏液水腫症狀"],ans:[0],expl:"席漢氏症候群發生於「產後大出血」導致腦下垂體缺血壞死，不是腦下垂體切除（A✗）。GH缺乏最常見✓；低血糖（皮質醇、GH不足）✓；黏液水腫（TSH不足）✓。"},{n:45,subj:"內分泌系統",q:"劉女士因血糖控制不佳入院，下列病人平日之飲食攝取比例，何者不適宜？①碳水化合物類的食物約占每日總熱量的50～60％ ②脂肪類的食物約占每日總熱量的5～10％ ③飽和脂肪類的食物小於7％ ④蛋白質類的食物約占每日總熱量的30～35％",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[2],expl:"糖尿病飲食：醣類50-60%①✓；脂肪25-35%（②說5-10%太低✗）；飽和脂肪<7%③✓；蛋白質15-20%（④說30-35%太高✗）。不適宜的是②和④=C。"},{n:46,subj:"內分泌系統",q:"格雷氏病（Grave's disease）會出現下列何種臨床表徵？①神經質 ②眼球突出 ③怕冷 ④手指顫抖 ⑤脛前凹陷性水腫",opts:["A.①②④","B.①③⑤","C.②③⑤","D.③④⑤"],ans:[0],expl:"Grave's disease=甲狀腺功能亢進。甲亢（快、熱、抖）：神經質①✓；眼球突出（Grave's特有）②✓；怕熱不怕冷③✗；手抖④✓；脛前「黏液性水腫」（非凹陷性）。答案①②④=A。"},{n:47,subj:"其他",q:"有關過敏性休克之敘述，下列何者正確？①接觸的過敏原可能來自藥物、食物、昆蟲叮咬等 ②發生嚴重支氣管擴張及呼吸困難 ③脈搏次數增快、血壓可能正常或降低 ④通常可立即注射epinephrine改善情況",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[2],expl:"過敏性休克：過敏原多元①✓；支氣管「收縮」（不是擴張）②✗；心跳快、血壓降低③✓；Epinephrine首選④✓。答案①③④=C。"},{n:48,subj:"其他",q:"有關有機磷中毒臨床處置之敘述，下列何者錯誤？",opts:["A.給予Apomorphine是因此藥為有機磷中毒的拮抗劑","B.進行胃灌洗、應維持呼吸道通暢必要時給與插管","C.其可從皮膚吸收，照護者須戴口罩、手套及穿隔離衣","D.對於沾有嘔吐物的衣物應除去並協助沐浴"],ans:[0],expl:"有機磷中毒解毒劑是Atropine（阻斷毒蕈效應）和Pralidoxime（PAM，重活化膽鹼酯酶）。Apomorphine是催吐劑，不是有機磷拮抗劑（A✗）。"},{n:49,subj:"其他",q:"有關病人誤食強鹼溶液之處置，下列何者錯誤？",opts:["A.立即給與胃灌洗","B.不可給與中和劑","C.疑似胃潰瘍應先採取禁食","D.注意口腔與食道之灼傷"],ans:[0],expl:"誤食強鹼禁止催吐和胃灌洗（灌洗管插入可能穿孔，且強鹼已燒傷食道）（A✗）。禁止中和劑（中和反應產熱加重傷害）✓；注意氣道保護和灼傷評估✓。"},{n:50,subj:"其他",q:"有關H1N1流感之敘述，下列何者錯誤？",opts:["A.病原菌屬於H型流感病毒","B.大部分病人症狀輕微，一週內可痊癒","C.主要經由飛沫與接觸傳染","D.治療藥物為Tamiflu及Relenza"],ans:[0],expl:"H1N1是A型（Influenza A）流感病毒的亞型，選項A說「H型」流感病毒是錯誤分類（A✗）。Tamiflu、Relenza是神經胺酸酶抑制劑✓。"},{n:51,no:1,subj:"神經系統",q:"有關巴金森氏症（Parkinson's disease）的主要典型症狀，下列敘述何者正確？①震顫 ②吞嚥困難 ③僵硬 ④運動遲緩 ⑤腹瀉",opts:["A.①②③","B.①③④","C.①③⑤","D.①②⑤"],ans:[1],expl:"巴金森氏症四大主症（TRAP）：顫抖（Tremor，靜止性震顫）、僵硬（Rigidity，齒輪狀肌強直）、動作遲緩（Bradykinesia）、姿勢不穩（Postural instability），故①③④正確。吞嚥困難屬病程進展後的併發症，並非最主要典型症狀；且因自主神經退化、腸胃蠕動下降，典型腸胃症狀是「便秘」而非腹瀉，⑤錯誤。答案①③④＝B。"},{n:52,no:2,subj:"神經系統",q:"有關顱內腫瘤病人顱內壓ICP=18mmHg，其照護之敘述，下列何者正確？",opts:["A.出現複視時，應鼓勵多下床活動","B.採高劑量類固醇治療時，應該要監測其血糖值","C.出現腦組織灌流失效時，應鼓勵液體攝取","D.出現極痛是病情惡化之早期臨床表徵"],ans:[1],expl:"顱內腫瘤病人常使用高劑量類固醇（如Dexamethasone）減緩腦水腫，其副作用之一為血糖上升，須密切監測血糖（B✓）。複視代表顱神經受壓迫，應限制活動、避免ICP升高的動作，而非鼓勵下床（A✗）；腦灌流失效（CPP下降）時應限制水分攝取以避免加重腦水腫，而非鼓勵攝取（C✗）；劇烈頭痛通常是ICP升高「惡化」的表現，早期徵象多為意識程度的細微改變、躁動不安，而非劇痛（D✗）。"},{n:53,no:3,subj:"消化系統",q:"下列何者不是肝硬化病人發生肝性腦病變的主要誘發因子？",opts:["A.感染","B.便秘","C.腸胃道出血","D.高血鉀"],ans:[3],expl:"肝硬化病人發生肝性腦病變的常見誘發因子包括：感染、便秘（腸道氨吸收增加）、腸胃道出血（血液分解產生氨）、低血鉀及鹼中毒。教科書明確指出是「低血鉀」而非「高血鉀」為誘發因子（Lewis's Medical-Surgical Nursing教科書Table 46.12：Potassium ions are needed by brain to metabolize ammonia），故高血鉀並非誘發因子，答案為D。記憶：鉀離子是大腦代謝氨所需要的重要離子，低血鉀反而會惡化高血氨。"},{n:54,no:4,subj:"神經系統",q:"有關癲癇藥物處置的敘述，下列何者正確？",opts:["A.多種抗癲癇藥物同時使用效果最佳","B.考慮停藥時可先行選擇半衰期較長的藥物逐漸減量","C.服用抗癲癇藥物phenytoin類（如Dilantin），一旦懷孕須立即停藥，避免胎兒畸形","D.病人於服藥期間2～3年內無任何癲癇發作，且神經學及腦波檢查正常，可考慮慢慢停藥"],ans:[3],expl:"抗癲癇藥物治療原則：癲癇獲得良好控制（服藥後2～3年無發作）且腦波、神經學檢查正常時，可與醫師討論「緩慢逐步減量」停藥，不可驟停（D✓）。治療應以單一藥物（monotherapy）為優先，多重藥物合併使用會增加交互作用與副作用，非效果最佳（A✗）；懷孕不可自行驟停phenytoin類藥物，因癲癇發作對母胎的風險遠大於藥物本身的致畸風險，須由醫師評估調整劑量或改藥（C✗）。"},{n:55,no:5,subj:"神經系統",q:"有關病人因頸椎脊髓損傷處於脊髓休克期的敘述，下列何者錯誤？",opts:["A.心跳50次/分、呼吸15次/分、血壓160/100 mmHg","B.主要是因喪失自主神經的控制","C.受傷部位以下的所有運動、感覺、反射可能減弱或消失","D.出現尿滯留及膀胱動作下降"],ans:[0],expl:"脊髓損傷後脊髓休克期因喪失自主神經（交感神經）張力，典型表現為低血壓與心搏過緩（副交感神經相對優勢），而非血壓上升；選項血壓160/100 mmHg（高血壓）不符合脊髓休克的血流動力學表現，故A錯誤，為本題答案。B、C、D皆正確描述脊髓休克特徵：自主神經功能喪失、受傷平面以下運動感覺反射減弱消失、膀胱無張力導致尿滯留。"},{n:56,no:6,subj:"消化系統",q:"有關膽囊炎病人的護理評估及照護，下列何者正確？",opts:["A.急性期症狀為右上腹部痛可能輻射至右下腹部","B.膽囊手術後須監測腹脹、腹部僵硬、嘔吐等腹膜炎徵象","C.可用morphine緩解疼痛與痙攣","D.術後引流液為墨綠色時需立刻通知醫師"],ans:[1],expl:"膽囊切除術後應密切監測腹膜炎徵象（腹脹、腹部僵硬、噁心嘔吐、發燒），以早期偵測膽汁滲漏或感染（B✓）。膽囊炎疼痛典型輻射至右肩胛或右肩，而非右下腹（A✗）。Morphine可能引起Oddi氏括約肌痙攣、加劇膽絞痛，臨床上多避免使用（C✗）。T型管引流液呈墨綠色（膽汁色）為正常現象，不需立即通知醫師，除非出現大量鮮血或引流量驟減（D✗）。"},{n:57,no:7,subj:"消化系統",q:"有關食道癌之敘述，下列何者錯誤？",opts:["A.食道下端之癌症可採行胃造口術維持身體營養需要","B.食道重建手術適用於中段的食道癌","C.光動力治療後需避光約1個月","D.鼓勵病人採低蛋白及高醣類高渣飲食，維持適當的營養"],ans:[3],expl:"食道癌病人常因吞嚥困難導致營養不良，飲食應採「高蛋白、高熱量、低渣（少纖維、質地軟）」飲食，以維持營養並減少通過狹窄食道的阻力；選項卻寫「低蛋白、高渣」，方向完全相反，故D錯誤，為本題答案。下段食道癌可行胃造口灌食維持營養（A✓）；中段食道癌適合食道重建手術（B✓）；光動力治療的光敏劑會使皮膚對光敏感，術後需避光約4～6週（約1個月）（C✓）。"},{n:58,no:8,subj:"消化系統",q:"有關上腸胃道出血的照護，下列何者錯誤？",opts:["A.監測嘔吐物性質和大便的顏色","B.監測是否有肢端冰冷、指甲床蒼白等現象","C.出血停止後立刻停止血管加壓素的使用","D.評估腹部是否有腹脹僵硬情形"],ans:[2],expl:"血管加壓素（Vasopressin）需「逐漸減量」後停用，驟然停藥可能導致出血反彈或血管痙攣反彈，C敘述「出血停止後立刻停止」為錯誤處置，是本題答案。監測嘔吐物性質、大便顏色（觀察咖啡渣狀嘔吐物、解黑便）、肢端灌流（冰冷、蒼白代表低血容性休克）、腹部腹脹僵硬（評估併發症如穿孔）皆為正確的護理評估重點。"},{n:59,no:9,subj:"消化系統",q:"有關食道靜脈曲張出血病人的護理指導，下列何者不適當？",opts:["A.避免用力咳嗽及提重物","B.採用軟質飲食，避免粗糙食物","C.須注意食物的溫度，避免過熱與過冷","D.須服用鎮靜劑以減輕焦慮"],ans:[3],expl:"肝硬化病人肝臟代謝藥物能力下降，鎮靜劑易蓄積並誘發肝性腦病變，因此不會常規指導病人服用鎮靜劑緩解焦慮，應以非藥物方式（如衛教、陪伴）處理焦慮，D為不適當之指導，是本題答案。避免用力咳嗽、搬提重物（增加腹壓／門脈壓）、採軟質避免粗糙飲食、避免過熱過冷食物（防止機械或溫度刺激導致曲張靜脈破裂出血）皆為正確衛教內容。"},{n:60,no:10,subj:"消化系統",q:"王先生，170cm，88Kg，從事搬運工，因腹股溝疝氣接受手術治療，有關疝氣手術後護理指導，下列何者正確？①傷口處熱敷，以減輕疼痛與腫脹 ②不需要特別減重以免營養不良 ③陰囊應給與支托後再下床 ④平時應多吃蔬果以預防便秘 ⑤出院後可立即上班從事搬運工作",opts:["A.①②","B.②③","C.③④","D.④⑤"],ans:[2],expl:"疝氣術後應以彈性支托或陰囊托給予支撐，減少腫脹與牽扯疼痛（③✓）；並鼓勵攝取蔬果、水分，預防便秘、避免用力解便增加腹內壓（④✓）。急性期應冰敷而非熱敷（①✗）；病人身高170cm、體重88kg，BMI約30.4已達肥胖範圍，減重有助降低腹內壓及復發率，並非不需要（②✗）；從事搬運工作者術後應避免提重物一段時間（約4～6週），不可出院後立即恢復粗重工作，以防復發（⑤✗）。答案③④＝C。"},{n:61,no:11,subj:"骨骼肌肉",q:"下列何者為骨質疏鬆的危險因子？①停經前之婦女 ②攝取大量咖啡茶飲 ③規律的運動 ④靜態生活或長期臥床 ⑤日曬時間不足",opts:["A.①②③","B.①③④","C.②④⑤","D.③④⑤"],ans:[2],expl:"骨質疏鬆危險因子包括：停經後雌激素缺乏（並非停經前，①✗）、過量咖啡因攝取增加尿鈣排出（②✓）、缺乏負重運動或長期臥床導致骨質流失（④✓）、日曬不足使維生素D活化不足、影響鈣吸收（⑤✓）。規律運動（尤其負重運動）則是「保護因子」而非危險因子（③✗）。答案②④⑤＝C。"},{n:62,no:12,subj:"骨骼肌肉",q:"有關病人因左膝關節退化性關節炎接受全關節置換術之術後照護，下列何者最不適當？",opts:["A.術後可用枕頭抬高左下肢，以促進血液循環","B.術後1～2天可使用持續被動運動機（CPM）進行運動","C.助行器手把高度需與病人腰同高且手舉可彎曲≦30度","D.教導病人返家後，多上下樓梯、走遠路，以促進膝關節血液循環"],ans:[3],expl:"全膝關節置換術後應循序漸進增加活動量，「返家後應多上下樓梯、走遠路」屬過度負重的錯誤指導，可能造成人工關節過度磨損或跌倒風險，最不適當，為本題答案（D✗）。抬高患肢促進循環消腫（A✓）；術後1～2天開始使用CPM機進行被動運動，有助關節活動度恢復（B✓）；助行器高度應與腰部（大轉子）同高、手肘彎曲約15～30度，是正確的輔具調整原則（C✓）。"},{n:63,no:13,subj:"骨骼肌肉",q:"有關移除下肢石膏後病人護理指導之敘述，下列何者不適當？",opts:["A.鼓勵病人立即下床行走，增加患肢平衡感","B.避免過度曝曬皮膚","C.行走時患肢可使用彈性繃帶包紮","D.患肢皮膚上布滿黃棕色鱗片是正常的現象"],ans:[0],expl:"石膏移除後，患肢肌肉因長期未使用已萎縮無力、關節僵硬，應循序漸進恢復活動，逐步增加負重與行走訓練，而非立即下床行走，A為不適當之指導，是本題答案。剛拆石膏的皮膚較脆弱，應避免過度曝曬（B✓）；行走過渡期可用彈性繃帶提供支托（C✓）；石膏內皮屑、油脂堆積形成黃棕色鱗屑，屬正常現象，非感染徵象，清潔即可（D✓）。"},{n:64,no:14,subj:"感官系統",q:"下列何者為白內障最主要的病變構造？",opts:["A.角膜","B.水晶體","C.鞏膜","D.視神經"],ans:[1],expl:"白內障（Cataract）是水晶體（水晶體蛋白）因老化、外傷、代謝疾病等因素產生混濁病變，導致視力模糊，病變構造為水晶體（B✓）。角膜混濁稱為角膜病變，非白內障；青光眼與房水、眼壓相關；視神經病變則見於青光眼末期或其他神經疾病，皆非白內障主要病變構造。"},{n:65,no:15,subj:"感官系統",q:"病人左耳聽力正常，右耳有聽力障礙，以韋伯試驗（Weber test）發現右耳比較大聲，再以任內試驗（Rinne test）發現左耳空氣傳導＞骨傳導、右耳空氣傳導≦骨傳導，下列何者是病人右耳最可能的病變位置？①外耳 ②中耳 ③內耳 ④耳蝸神經",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[0],expl:"Weber test偏向較大聲的一側，代表該耳為傳導性聽力障礙（或對側為感音性聽力障礙），本題偏向右耳，故右耳可能為傳導性聽損。Rinne test右耳「骨傳導≥氣傳導」（正常應氣傳導＞骨傳導），確認右耳為傳導性聽力障礙。傳導性聽損的病變位置在外耳或中耳（聲音傳導路徑受阻，如耳垢栓塞、中耳炎、耳硬化症），而非內耳或耳蝸神經（感音性聽損的病變位置）。答案①②＝A。"},{n:66,no:16,subj:"心臟血管",q:"下列何者為左心衰竭的臨床表徵？",opts:["A.下肢水腫","B.肝脾腫大","C.中心靜脈壓上升","D.端坐呼吸"],ans:[3],expl:"左心衰竭導致肺循環淤血，典型表徵為端坐呼吸（orthopnea）、呼吸困難、咳嗽、肺部囉音（D✓）。下肢水腫、肝脾腫大、中心靜脈壓上升則是「右心衰竭」導致體循環淤血的表徵，並非左心衰竭表現（A、B、C皆為右心衰竭表現）。記憶：左心衰竭影響肺（呼吸道症狀）；右心衰竭影響全身（水腫、肝脾腫大）。"},{n:67,no:17,subj:"心臟血管",q:"有關心臟復健之敘述，下列何者正確？①依基礎代謝率（BMR）選擇活動內容 ②依代謝當量（MET）選擇活動內容 ③為增加心肺耐力，鼓勵做有氧運動 ④為加強肌力量，鼓勵等長運動",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[2],expl:"心臟復健活動強度應依「代謝當量（MET）」分級選擇活動內容，而非基礎代謝率BMR（②✓，①✗）。有氧運動可增進心肺耐力，是心臟復健的核心運動處方（③✓）。等長運動（如用力握拳、憋氣出力）會使血壓與心臟後負荷驟升，心臟病人應避免或謹慎使用，建議採等張（動態）運動來訓練肌力，而非等長運動（④✗）。答案②③＝C。"},{n:68,no:18,subj:"心臟血管",q:"有關預防靜脈血栓形成之措施，下列何者不適當？",opts:["A.術後早期下床活動","B.多穿著緊身衣","C.抬高下肢促進靜脈回流","D.穿著彈性襪"],ans:[1],expl:"預防靜脈血栓應避免任何會壓迫下肢血循的緊身衣物，一般緊身衣反而阻礙靜脈回流、增加血栓風險，B為不適當措施，是本題答案。術後及早下床活動可減少靜脈滯留（A✓）；抬高下肢促進靜脈回流（C✓）；穿著醫療級彈性襪（由遠端至近端呈階梯式壓力設計）可促進靜脈回流，屬正確預防措施（D✓）。"},{n:69,no:19,subj:"心臟血管",q:"有關心律去顫整流術（defibrillation）之敘述，下列何者錯誤？",opts:["A.初次治療電量介於50～200焦耳","B.電擊板放置處為胸骨右緣第2肋間與左腋前線第5肋間","C.常用於心房纖維顫動","D.電擊時切勿碰觸病人與其病床"],ans:[2],expl:"本題所稱「心律去顫整流術（defibrillation）」為非同步電擊去顫，主要用於心室震顫（VF）及無脈性心室頻脈（pulseless VT）等致命性心律不整；心房纖維顫動（AFib）病人通常仍有脈搏、屬於有效循環之心律不整，臨床應使用「同步心律整流術（synchronized cardioversion）」處理，而非去顫，故C敘述錯誤，為本題答案。初次電量依機型（單相／雙相）建議介於50～200焦耳範圍內（A✓）；電擊板標準位置為胸骨右緣第2肋間（心底）與左腋前線第5肋間（心尖）（B✓）；電擊瞬間所有人員都不可碰觸病人或病床，以免遭電擊或影響電流傳導（D✓）。"},{n:70,no:20,subj:"心臟血管",q:"下列何者不是心衰竭時心臟代償徵象？",opts:["A.心跳變快","B.心室擴張","C.心肌需氧減少","D.心肌肥厚"],ans:[2],expl:"心臟衰竭的代償機轉包括心跳加快（交感神經興奮）、心室擴張（Frank-Starling機轉增加心搏量）、心肌肥厚（增加收縮力），這些代償反而會「增加」心肌氧氣需求，形成惡性循環，而非減少氧需求，故C「心肌需氧減少」不是代償徵象，為本題答案（不是代償表現）。"},{n:71,no:21,subj:"腫瘤血液",q:"有關瀕死期癌症病人之臨終關懷，下列何者正確？",opts:["A.評估病人面對死亡的調適能力","B.減少開放性溝通模式","C.持續給予保證與灌注希望","D.醫護人員此期採被動方式協助"],ans:[0],expl:"臨終關懷應主動評估病人對死亡的因應與調適能力，提供符合其心理需求的照護（A✓，本題答案）。此階段應鼓勵「開放性溝通」，讓病人表達感受與心願，而非減少溝通（B✗）；面對瀕死病人應避免不實的保證或灌注不切實際的希望，應以誠實、同理的態度陪伴（C✗）；醫護人員應採取主動積極的舒適照護與陪伴，而非被動方式（D✗）。"},{n:72,no:22,subj:"腫瘤血液",q:"正在接受sorafenib（Nexavar）治療的癌症病人表示：「服藥後手掌和腳掌都出現脫皮、龜裂、刺痛情形，怎麼會這樣呢？」下列護理指導何者正確？①洗手時不用力搓洗，穿著寬鬆舒適鞋子 ②可塗抹尿素乳膏或凡士林在患部後穿襪就寢 ③外出須戴帽撐傘防曬，但不可以擦防曬乳 ④皮膚乾癢不適時應給與冰敷或熱敷緩解症狀",opts:["A.①②","B.③④","C.②③","D.②④"],ans:[0],expl:"Sorafenib常見副作用為手足症候群（hand-foot syndrome），照護重點為減少摩擦、避免高溫刺激：洗手勿用力搓揉、穿寬鬆鞋襪減少摩擦（①✓）；睡前塗抹尿素乳膏或凡士林加強保濕，再穿棉襪加強吸收（②✓）。外出防曬應同時使用陽傘、帽子「與」防曬乳，而非排除防曬乳（③✗）；患部應避免熱敷（熱會加重發炎、血管擴張），選項並列「冰敷或熱敷」但熱敷並不適用，敘述不正確（④✗）。答案①②＝A。"},{n:73,no:23,subj:"腫瘤血液",q:"王小華熱愛打籃球，最近剛被確診為血友病，下列護理指導何者不適當？",opts:["A.不可自行服用阿斯匹靈（aspirin）止痛劑","B.避免激烈及發生碰撞的活動","C.頻繁地抽血監測凝血相關指數","D.避免不必要的注射或手術"],ans:[2],expl:"血友病病人凝血因子缺乏，應盡量減少不必要的侵入性處置（含抽血、注射），以降低出血及血腫風險；「頻繁抽血監測」本身即增加穿刺部位出血機會，屬不適當之指導，C為本題答案（不適當）。避免服用阿斯匹靈等抗血小板藥物（A✓）、避免碰撞性運動（B✓）、避免不必要注射或手術（D✓）皆為正確衛教原則。"},{n:74,no:24,subj:"腫瘤血液",q:"下列何者不是放射線治療病人皮膚出現的急性反應？",opts:["A.色素沉著","B.發紅敏感","C.乾性脫屑","D.濕性脫屑"],ans:[0],expl:"放射線治療皮膚反應依嚴重度可分為：發紅敏感（紅斑）→乾性脫屑→濕性脫屑，這些都屬於急性反應（B、C、D皆屬急性反應）。色素沉著則多屬延遲性、較晚出現的皮膚變化（黑色素細胞受刺激所致），並非急性反應，故A為本題答案（不是急性反應）。"},{n:75,no:25,subj:"腫瘤血液",q:"王先生接受輸血治療過程中發生乾咳、血壓上升、嚴重呼吸困難等情形，下列何者為其最有可能發生的輸血不良反應？",opts:["A.循環過度負荷","B.過敏反應","C.熱原反應","D.溶血反應"],ans:[0],expl:"乾咳、血壓「上升」、嚴重呼吸困難為典型「循環過度負荷（TACO, Transfusion-Associated Circulatory Overload）」表現，好發於輸血速度過快或心腎功能不佳病人，肺部因輸血容積負荷過大而淤血（A✓）。過敏反應以蕁麻疹、搔癢、血管性水腫為主；熱原反應以發燒畏寒為主；溶血反應以腰背痛、茶色尿、發燒畏寒為主，皆與本題「血壓上升、乾咳」的表現不符，故答案為A。"},{n:76,no:26,subj:"腫瘤血液",q:"承上題，有關王先生的護理與處置，下列何者正確？",opts:["A.協助平躺","B.給予類固醇","C.持續輸血","D.協助做放血術"],ans:[3],expl:"承上題TACO的處置原則：立即減緩或暫停輸血、協助採坐姿或半坐臥（而非平躺，以減少靜脈回流）、給予氧氣、必要時使用利尿劑；對嚴重案例（尤其利尿劑效果不佳或腎功能不良者），可考慮執行治療性放血術（therapeutic phlebotomy），緊急移除部分血液以快速降低循環負荷（D✓，本題答案）。協助「平躺」反而會增加靜脈回流、加重肺水腫，是錯誤處置（A✗）；類固醇是過敏反應的處置藥物，非TACO的主要治療（B✗）；持續輸血將使循環負荷更加嚴重，應立即減緩或停止，而非持續（C✗）。"},{n:77,no:27,subj:"腫瘤血液",q:"有關腫瘤溶解症候群之處置，下列何者錯誤？",opts:["A.給與Sodium Bicarbonate促進尿酸溶解","B.給與Kayexalate治療高血鉀","C.減少輸液降低心臟負擔","D.給與Allopurinol抑制尿酸生成"],ans:[2],expl:"腫瘤溶解症候群的處置原則為「積極輸液」（大量等張溶液），以增加腎臟血流與尿酸排除，預防急性腎損傷，而非減少輸液，故C「減少輸液降低心臟負擔」為錯誤處置，是本題答案。給予Sodium Bicarbonate鹼化尿液以促進尿酸溶解排出（A✓，屬傳統教學重點）；Kayexalate（Sodium polystyrene sulfonate）用於降低血鉀（B✓）；Allopurinol抑制黃嘌呤氧化酶、減少尿酸生成（D✓）。"},{n:78,no:28,subj:"其他",q:"有關疥瘡之敘述，下列何者錯誤？",opts:["A.經由皮膚、衣物等接觸而感染","B.不會藉由寵物攜帶疥蟲而傳染","C.接觸疥蟲後4週才會出現疥瘡的症狀","D.疥蟲離開人體後2週才會死亡"],ans:[1],expl:"疥瘡主要透過人與人皮膚直接接觸傳染，長時間共用衣物寢具也可能傳染（A✓）。人疥蟲（Sarcoptes scabiei var. hominis）雖主要侷限於人與人之間傳染，但密切接觸感染疥蟲的寵物（如犬疥蟲等動物變異株）仍可能造成人體暫時性、自限性的皮膚過敏反應，故「完全不會透過寵物傳染」的絕對敘述並不正確，B為本題答案（錯誤敘述）。初次感染疥蟲後，因遲發性過敏反應需要時間致敏，通常於接觸後約4週左右才出現搔癢等症狀（C✓）；疥蟲離開人體後仍可在環境中存活一段時間才死亡，故接觸隔離與環境處理仍屬必要防護措施（D✓，依教材所述）。"},{n:79,no:29,subj:"其他",q:"有關第一型單純皰疹之敘述，下列何者正確？①容易再度復發 ②感染痊癒後會潛伏於神經根節 ③由水痘病毒感染後所引起的 ④多感染於會陰部",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[0],expl:"第一型單純皰疹病毒（HSV-1）感染具有潛伏－復發特性，好發於口腔周圍（唇皰疹），初次感染痊癒後病毒會潛伏於三叉神經節等感覺神經節內，遇誘因（如發燒、日曬、壓力）時再活化復發（①②✓）。HSV-1與水痘－帶狀疱疹病毒（VZV）是不同種病毒，並非由水痘病毒引起（③✗）。好發於會陰部者主要為第二型單純皰疹病毒（HSV-2），HSV-1則多好發於口腔顏面部（④✗）。答案①②＝A。"},{n:80,no:30,subj:"骨骼肌肉",q:"有關全身性紅斑性狼瘡之護理處置，下列何者不適當？",opts:["A.病情控制良好後3～6個月，可與醫生討論懷孕計畫","B.腎臟受侵犯時應採低鈉、低鉀、低蛋白飲食","C.關節炎的急性期可冷敷","D.避孕方法最好採取口服避孕藥"],ans:[3],expl:"SLE病人因雌激素可能誘發疾病惡化，且SLE病人常合併抗磷脂抗體症候群，使用含雌激素的口服避孕藥會增加血栓及疾病活動風險，一般不建議作為首選避孕方式，應考慮屏障式避孕法等其他替代方案，D為不適當之指導，是本題答案。病情穩定3～6個月後可與醫師討論懷孕計畫（A✓）；狼瘡腎炎病人採低鈉、低鉀、低蛋白飲食以減輕腎臟負擔（B✓）；急性關節炎期可冷敷消腫止痛（C✓）。"},{n:81,no:31,subj:"骨骼肌肉",q:"有關類風濕性關節炎復健治療之敘述，下列何者正確？",opts:["A.運動治療建議一天至少二次，以被動運動為主","B.冷水池中進行運動治療，可以減輕關節疼痛","C.建議可進行園藝、編織等活動","D.建議病人長期臥床，減少活動"],ans:[2],expl:"類風濕性關節炎病人可鼓勵從事園藝、編織等精細動作及職能治療活動，有助維持關節活動度與手部功能（C✓，本題答案）。運動治療應以「主動」關節活動運動為主，並依病情調整頻率，而非以被動運動為主（A✗）；水療應在溫水池中進行，溫熱可放鬆肌肉、減輕關節疼痛與僵硬，冷水反而會加劇僵硬（B✗）；除急性發炎期需適度休息外不宜長期臥床，以免關節攣縮、肌肉萎縮，應維持規律的活動與休息平衡（D✗）。"},{n:82,no:32,subj:"泌尿系統",q:"有關高血鈉之敘述，下列何者正確？①血鈉的濃度＞130mEq/L ②導因之一為醛固酮過多症導致 ③尿比重上升 ④指導低鈉飲食如蘇打餅乾、白麵包",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[2],expl:"高血鈉定義為血鈉大於145 mEq/L（並非大於130 mEq/L，①✗，130 mEq/L已接近或低於正常下限）。醛固酮過多症會促進腎小管保鈉排鉀，是高血鈉成因之一（②✓）。高血鈉常伴隨體液容積不足（自由水流失），使尿液濃縮、尿比重上升（③✓）。蘇打餅乾（含碳酸氫鈉）與白麵包（製作過程常添加鹽）皆屬含鈉量較高的食物，並非低鈉飲食範例，④之衛教內容錯誤。答案②③＝C。"},{n:83,no:33,subj:"呼吸系統",q:"有關預防吸入性肺炎病人之護理措施，下列何者最不適當？",opts:["A.進餐後立採平躺姿勢，以防止嗆咳","B.睡覺時，需協助病人以床頭抬高的15～30度半側臥姿的方式休息","C.教導家屬鼻胃管灌食前，需評估病人胃殘餘量，以避免不慎嗆咳","D.吞嚥困難病人進食前，應評估作嘔反射，以選擇適當的進食方式"],ans:[0],expl:"進食後應維持坐姿或半坐臥至少30～60分鐘，以利消化並降低胃食道逆流、嗆咳誤吸的風險；「進餐後立即採平躺姿勢」反而大幅增加吸入性肺炎風險，是最不適當的措施，A為本題答案。睡眠時抬高床頭15～30度、採半側臥可減少分泌物或逆流物嗆入氣管（B✓）；鼻胃管灌食前評估胃殘餘量可避免灌食過量、嘔吐嗆咳（C✓）；吞嚥困難病人進食前評估作嘔反射，有助判斷是否適合經口進食（D✓）。"},{n:84,no:34,subj:"呼吸系統",q:"急性呼吸窘迫症候群（ARDS）病人產生表面張力素的肺細胞受損，會導致病人出現下列何種問題？",opts:["A.支氣管收縮","B.肺擴張不全","C.肺栓塞","D.肺纖維化"],ans:[1],expl:"第二型肺泡細胞受損會使表面張力素（surfactant）分泌減少，肺泡表面張力增加，導致肺泡塌陷、肺擴張不全（atelectasis），是ARDS病理生理的重要機轉之一（B✓，本題答案）。支氣管收縮、肺栓塞、肺纖維化則非表面張力素缺乏所直接導致的病理結果。"},{n:85,no:35,subj:"呼吸系統",q:"以脈搏血氧測量儀（pulse oximetry）所測得的數值，下列何者表示組織氧合（oxygenation）正常？",opts:["A.80～90 mmHg","B.95～100 mmHg","C.80～90%","D.95～100%"],ans:[3],expl:"脈搏血氧測量儀（pulse oximetry）測得的是血氧「飽和度」（SpO2），單位為百分比%，正常值為95～100%（D✓，本題答案）。mmHg為動脈血氧分壓（PaO2）之單位，並非脈搏血氧儀的測量單位，選項A、B單位錯誤；80～90%則屬於低血氧狀態，並非正常值。"},{n:86,no:36,subj:"呼吸系統",q:"有關慢性阻塞性肺疾病（COPD）病人之護理指導，下列何者最為適當？",opts:["A.鼓勵餐前走路半小時","B.增加醣類的攝取量","C.採取少量多餐","D.給予高流量氧氣以改善心肺功能"],ans:[2],expl:"COPD病人建議採取「少量多餐」，避免一次進食過多造成腹脹上頂橫膈，加重呼吸負擔，也可減少進食造成的疲憊與喘（C✓，本題答案）。COPD病人通常安排「餐前休息」而非運動，以保留體力進食、減少呼吸困難（A✗）；醣類代謝會產生較多二氧化碳，可能加重CO2蓄積，COPD飲食建議適度限醣、增加脂肪比例，而非增加醣類攝取（B✗）；COPD病人（尤其慢性CO2蓄積者）呼吸驅動力依賴低血氧刺激，給予高濃度、高流量氧氣可能抑制呼吸中樞、導致CO2麻醉，臨床上採低流量、控制性給氧，且與心肺功能改善並無直接相關（D✗）。"},{n:87,no:37,subj:"泌尿系統",q:"有關尿液檢查之敘述，下列何者錯誤？",opts:["A.除了早晨第一次尿外，任何時間採集的尿液稱之為隨機尿","B.導尿管留置可由蓄尿袋採尿送檢查","C.尿液檢體應於30分鐘內送檢查為宜","D.常規尿液收集是要取中段尿送檢查"],ans:[1],expl:"留置導尿管病人採檢尿液應由採尿孔（sampling port）以無菌技術抽取新鮮尿液，不可直接自蓄尿袋取尿，因袋內尿液可能已滋生細菌、放置過久，會影響檢驗結果準確性，B為錯誤敘述，是本題答案。除晨尿外任何時間留取的尿液稱隨機尿（A✓）；尿液檢體應盡速（約30分鐘內）送檢，避免細菌孳生或成分分解影響結果（C✓）；常規尿液檢查建議收集中段尿以減少污染（D✓）。"},{n:88,no:38,subj:"泌尿系統",q:"有關血液透析病人動靜脈瘻管（A-V fistula）之護理措施，下列何者正確？",opts:["A.觸診瘻管摸到血流雜聲，表此處可能阻塞應速處理","B.每天測量動靜脈瘻管手臂之血壓，以評估血循狀況","C.可運用彈性繃帶包紮或著長袖彈力衣，以保護瘻管","D.教導執行握球運動強化血管，以促進瘻管的血流量"],ans:[3],expl:"教導病人規律執行握球運動，可強化血管壁、促進瘻管血流量與成熟度，是正確的自我照護指導（D✓，本題答案）。觸摸到震顫（thrill）或聽到雜音（bruit）代表瘻管血流通暢，屬正常現象，「摸不到」震顫或雜音才代表可能阻塞、需立即處理，A敘述相反、錯誤。瘻管手臂應避免測量血壓、抽血、打點滴，以防壓迫瘻管、影響血流甚至導致栓塞，B錯誤。瘻管手臂也應避免穿著過緊衣物或以彈性繃帶包紮，以免壓迫瘻管造成阻塞，C錯誤。"},{n:89,no:39,subj:"泌尿系統",q:"有關腎臟結石接受體外震波術後護理措施之敘述，下列何者錯誤？",opts:["A.儘量攝取開水，勿以茶、啤酒或是果汁來取代水分","B.術後鼓勵下床活動、多喝水並觀察尿液顏色、氣味","C.術後疼痛是正常，可先觀察不用止痛藥以免傷害腎臟","D.結石成分為尿酸，需指導避免食用內臟、香菇或海鮮"],ans:[2],expl:"術後疼痛屬正常現象（結石碎片通過輸尿管引起腎絞痛），應依醫囑給予適當止痛藥物緩解，而非為了「保護腎臟」而放任病人忍痛不予處理，C敘述錯誤、為不當之照護觀念，是本題答案。震波碎石術後應鼓勵多喝白開水（勿以茶、酒、果汁取代），促進碎石排出並沖淡尿液（A✓）；鼓勵下床活動幫助結石排出，並觀察尿液顏色氣味以監測血尿或感染徵象（B✓）；尿酸結石病人應避免高普林食物如內臟、香菇、海鮮，以減少尿酸生成（D✓）。"},{n:90,no:40,subj:"泌尿系統",q:"有關泌尿道感染及衛教之敘述，下列何者最適當？",opts:["A.建議食用鹼化尿液的食物如柑橘及奶製品","B.女性病人最常見的感染源為陰道滴蟲感染","C.泌尿道感染病人的典型症狀為無癥性血尿","D.院內泌尿道感染常見於泌尿道侵入性檢查後"],ans:[3],expl:"院內泌尿道感染最常見的原因為泌尿道侵入性處置（如導尿管留置、膀胱鏡檢查等），破壞正常防禦機轉並引入病原菌，D為最適當之敘述，是本題答案。UTI預防飲食應著重「酸化尿液」（如蔓越莓汁、維生素C），減少細菌附著於尿路上皮，柑橘與奶製品偏鹼性，方向錯誤（A✗）；女性UTI最常見致病菌為大腸桿菌（E. coli，經會陰上行感染），並非陰道滴蟲（滴蟲是造成陰道炎的病原體，非UTI最常見感染源）（B✗）；泌尿道感染典型症狀為頻尿、解尿灼熱刺痛、急尿感等「有症狀」表現，並非無症性血尿（C✗）。"},{n:91,no:41,subj:"呼吸系統",q:"高小姐的動脈血液氣體分析結果為pH 7.48、PaCO2 48mmHg、HCO3 30mmHg、PaO2 92mmHg，根據以上數值，判讀結果下列何者正確？",opts:["A.未代償性呼吸性酸中毒","B.完全代償性代謝性酸中毒","C.部分代償性代謝性鹼中毒","D.未代償性呼吸性鹼中毒"],ans:[2],expl:"判讀動脈血液氣體分析：pH 7.48（鹼血症，大於7.45）；HCO3 30 mEq/L上升，為原發性代謝性鹼中毒（因pH與HCO3變化方向一致）；PaCO2 48 mmHg上升，是呼吸系統代償性地滯留CO2以嘗試降低pH。由於pH仍超出正常範圍（7.35～7.45）未完全回到正常，屬「部分代償」而非完全代償，判讀為部分代償性代謝性鹼中毒（C✓，本題答案）。記憶：先看pH定酸鹼、再看HCO3與PaCO2何者與pH同方向變化以定原發問題、最後看pH是否回到正常範圍以定代償程度。"},{n:92,no:42,subj:"內分泌系統",q:"有關腦下垂體前葉分泌的激素，下列何者正確？①生長素（growth hormone） ②促乳素（prolactin） ③催產素（oxytocin） ④抗利尿素（ADH）",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[0],expl:"腦下垂體前葉分泌：生長素（GH）、促乳素（Prolactin）、促腎上腺皮質素（ACTH）、促甲狀腺素（TSH）、促性腺激素（FSH、LH）等（①②✓）。催產素（Oxytocin）與抗利尿素（ADH）是下視丘製造、經神經軸突運送並儲存於腦下垂體「後葉」釋放，並非前葉分泌（③④✗）。答案①②＝A。記憶：前葉分泌種類多（多為營養、促激素），後葉僅釋放2種（ADH、催產素），實際由下視丘製造。"},{n:93,no:43,subj:"神經系統",q:"陳太太，58歲，近期被診斷罹患阿茲海默症，目前出現情緒不穩、易怒，上街買東西會忘了付錢，常常忘記檢查瓦斯直接上床睡覺，也經常懷疑兒子在家偷錢，根據狀況，目前其處在阿茲海默症那一期？",opts:["A.健忘期早期","B.健忘期晚期","C.混亂期","D.失智期"],ans:[2],expl:"阿茲海默症病程可概分為健忘期（早期記憶減退，尚可代償）、混亂期（工具性日常活動能力IADLs開始退化，如忘記付款、忘記關瓦斯，並出現情緒不穩、猜疑等精神行為症狀）、失智期（基本日常生活能力喪失，需完全依賴他人照顧）。本題病人出現IADL障礙（買東西忘付錢、忘記檢查瓦斯）合併情緒不穩、易怒及被害妄想（懷疑兒子偷錢），符合「混亂期」之表現（C✓，本題答案）。"},{n:94,no:44,subj:"內分泌系統",q:"有關尿崩症病人之臨床表徵，下列何者錯誤？",opts:["A.黏膜乾燥","B.眼眶凹陷","C.心搏下降","D.脈搏呈絲脈"],ans:[2],expl:"尿崩症因大量稀釋性多尿導致嚴重脫水與血容積不足，身體會代償性地「心跳加快（心搏上升）」以維持心輸出量與組織灌流，而非心搏下降，C敘述方向相反，是本題答案（錯誤敘述）。脫水徵象如黏膜乾燥、眼眶凹陷、脈搏呈絲脈（微弱且快速）皆為正確的臨床表徵（A、B、D✓）。"},{n:95,no:45,subj:"內分泌系統",q:"有關糖尿病足部之身體評估可能結果，下列何者錯誤？",opts:["A.足部的外形改變","B.皮膚乾燥造成裂隙","C.腳趾的震動覺消失","D.跟腱肌腱反射+++"],ans:[3],expl:"糖尿病周邊神經病變會導致深腱反射「減弱或消失」，包括跟腱反射，而非反射亢進（+++），D敘述與實際病理生理相反，是本題答案（錯誤敘述）。糖尿病足部常見評估異常包括：足部外形改變（如Charcot關節病變）、自主神經病變導致排汗功能異常使皮膚乾燥產生裂隙（易成為感染入口）、感覺神經病變使震動覺等保護性感覺喪失，皆為正確之糖尿病足部評估異常表現（A、B、C✓）。"},{n:96,no:46,subj:"內分泌系統",q:"有關副甲狀腺機能亢進造成的影響，下列何者錯誤？",opts:["A.促進腸道對鈣質的吸收","B.促進維生素D活化","C.促進腎小管對鈣的再吸收","D.促進骨鈣形成"],ans:[3],expl:"副甲狀腺素（PTH）主要生理作用為調節血鈣：促進腸道對鈣質的吸收（需活化維生素D協同）（A✓）、促進維生素D活化（B✓）、促進腎小管對鈣的再吸收、抑制磷再吸收（C✓）。然而PTH是促進「骨骼中鈣質的釋出（骨質再吸收，bone resorption）」以提高血鈣，而非促進骨鈣形成，方向恰好相反，故D為錯誤敘述，是本題答案（依據Lewis's Medical-Surgical Nursing教科書：PTH stimulates bone resorption of calcium, renal tubular reabsorption of calcium, and activation of vitamin D）。副甲狀腺機能亢進長期會導致骨質流失、病理性骨折風險增加。"},{n:97,no:47,subj:"其他",q:"由119救護車送來一位因車禍OHCA（out of hospital cardiac arrest）的病人到急診，下列敘述何者正確？",opts:["A.OHCA指病人到院前宣布死亡","B.急診檢傷分類為黑色視為死亡最後處理","C.應立即從頭到腳快速評估","D.病人應立即復甦急救"],ans:[3],expl:"OHCA病人送達急診應立即給予復甦急救（持續CPR、依ACLS流程處置），把握黃金急救時間，D為正確處置，是本題答案。OHCA是指在醫療院所外（到院前）發生心跳停止，病人送達時通常仍在進行心肺復甦術，並非等同已宣布死亡，A敘述錯誤。黑色檢傷分類屬於大量傷病患檢傷分類（disaster triage）中用於資源有限情境下判定放棄急救的類別，並非常規急診檢傷分類方式，也不適用於此情境，B錯誤。心跳停止病人的處置應立即啟動急救，而非先進行從頭到腳的身體評估，後者屬於病人恢復生命徵象、情況穩定後的次級評估（secondary survey），C敘述順序錯誤。"},{n:98,no:48,subj:"其他",q:"下列何者不是腸病毒71型病人併發重症的前兆？",opts:["A.持續體溫38°C","B.持續昏睡","C.持續嘔吐","D.持續肌躍型抽搐"],ans:[0],expl:"腸病毒71型重症前兆（即所謂腸病毒五大重症前兆）包括：嗜睡、持續嘔吐、肌躍型抽搐（睡眠中或剛入睡時肢體不自主抽動）、呼吸急促或心跳加快、持續高燒不退（通常強調高燒，多在39°C以上）等。單純「持續體溫38°C」屬於較輕度的發燒，未達重症前兆所強調的持續高燒程度，故A不屬於典型重症前兆，是本題答案（不是前兆）。持續昏睡、持續嘔吐、持續肌躍型抽搐皆為明確的腸病毒重症警訊，須立即就醫（B、C、D皆為前兆）。"},{n:99,no:49,subj:"其他",q:"有關成人高品質胸部按壓之敘述，下列何者正確？",opts:["A.施救者雙手交疊，置於病人胸骨上1/3部位","B.按壓速率維持在140次/分鐘以上","C.垂直用力按壓深度3公分","D.每次按壓後等胸部完全回彈才可再按壓"],ans:[3],expl:"高品質CPR胸部按壓原則：成人按壓深度至少5公分（但不超過6公分），並非3公分（C✗）；按壓速率為每分鐘100～120次，並非140次以上（B✗，過快會影響按壓深度與胸部回彈品質）；按壓部位為胸骨「下半部」（約兩乳頭連線中點），並非胸骨上1/3（A✗）；每次按壓後應讓胸廓「完全回彈」，以利心臟充盈、增加下次按壓的心輸出量，才可進行下一次按壓，D為正確敘述，是本題答案。"},{n:100,no:50,subj:"消化系統",q:"有關困難梭狀桿菌相關腹瀉（Clostridium difficile associated diarrhea）之敘述，下列何者錯誤？",opts:["A.困難梭狀桿菌為厭氧性革蘭陽性桿菌，容易在醫療環境中形成孢子體","B.易感染年長者或住院病人在長期使用抗生素者","C.首選治療藥物為靜脈注射Vancomycin","D.腹瀉期間採接觸隔離"],ans:[2],expl:"困難梭狀桿菌相關腹瀉（CDAD）之治療首選藥物為口服Metronidazole（Flagyl），效果不佳或復發時才考慮口服Vancomycin；且Vancomycin治療腸道困難梭狀桿菌感染時必須採「口服」途徑，才能在腸腔內達到足夠濃度發揮局部殺菌作用，靜脈注射Vancomycin無法有效到達腸道，臨床上是用於治療MRSA等全身性感染，並非治療CDAD的給藥方式，故C「首選治療藥物為靜脈注射Vancomycin」在藥物選擇順序與給藥途徑兩方面皆錯誤，是本題答案（依據Lewis's Medical-Surgical Nursing教科書：Metronidazole為首選一線治療，其後才考慮Vancomycin）。困難梭狀桿菌為厭氧性革蘭陽性桿菌、會形成孢子體，一般酒精性乾洗手不易將其消滅，需以肥皂勤洗手（A✓）；好發於年長、住院、長期使用廣效抗生素導致腸道菌叢失衡的病人（B✓）；腹瀉期間應採接觸隔離並勤洗手，避免孢子傳播（D✓）。"},{n:101,no:1,subj:"神經系統",q:"有關巴金森氏症病人服用抗膽鹼激性製劑trihexyphenudyl（Artane®）之敘述，下列何者正確？",opts:["A.長期服用會出現姿位型低血壓","B.副作用少見，偶有情緒改變和頭痛情形","C.常與抗病毒製劑合併使用，可有效控制失眠和頭痛","D.需要監測眼壓變化，預防青光眼"],ans:[3],expl:"抗膽鹼激性製劑（trihexyphenidyl／Artane）作用在阻斷毒蕈鹼受體，除了口乾、視力模糊、便秘、尿液滯留等典型抗膽鹼副作用外，最需警覺的是可能誘發或惡化隅角閉鎖型青光眼（散瞳作用使眼壓上升），故用藥期間須監測眼壓變化（D✓，本題答案）。姿位性低血壓較常見於levodopa類藥物而非抗膽鹼劑（A✗）；抗膽鹼副作用並不少見，反而是臨床上最需衛教的重點（B✗）；也非與抗病毒藥物合併用於控制失眠頭痛（C✗）。"},{n:102,no:2,subj:"神經系統",q:"多發性硬化症病人之日常活動護理指導，下列敘述何者正確？",opts:["A.運動前給予溫熱敷會增加肌肉強直和關節攣縮","B.避免在運動後洗熱水澡以免疾病惡化","C.可以增加多次且密集的運動，防止肌肉無力和強直","D.若疾病加重導致長期臥床，應避免執行全關節運動"],ans:[1],expl:"多發性硬化症（MS）病人對體溫升高特別敏感（Uhthoff現象：體溫上升會暫時阻斷已脫髓鞘神經的傳導，使症狀短暫惡化），故應避免運動後洗熱水澡，以免核心體溫進一步上升誘發症狀惡化（B✓，本題答案）。運動前溫熱敷主要用於放鬆肌肉，並非會增加強直攣縮（A✗）；運動應採適度、規律但避免過度密集造成疲憊（過度運動反而誘發無力，C✗）；即使長期臥床仍應維持全關節運動以預防攣縮，而非避免執行（D✗）。"},{n:103,no:3,subj:"神經系統",q:"有關頭部外傷相關合併症的敘述，下列何者正確？",opts:["A.封閉性比開放性頭部外傷更易產生癲癇後遺症","B.創傷後症候群症狀可持續數個月到數年","C.腦脊髓液瘻管是因腦脊髓液循環路徑阻塞或吸收有問題","D.當頭部外傷損及視丘時，會引起抗利尿激素（ADH）分泌失調"],ans:[1],expl:"創傷後症候群（post-concussion syndrome）症狀（頭痛、頭暈、注意力不集中等）可持續數個月甚至數年，屬於本題正確敘述（B✓）。開放性頭部外傷因腦組織直接暴露、感染與局部損傷風險較高，實際上比封閉性更易產生癲癇後遺症，敘述相反（A✗）；腦脊髓液瘻管是因顱底骨折造成硬腦膜破損、腦脊髓液外漏，並非循環阻塞或吸收異常（C✗）；ADH分泌失調（SIADH）主要與下視丘／腦垂體受損有關，非視丘（thalamus）（D✗）。"},{n:104,no:4,subj:"神經系統",q:"有關癲癇（epilepsy）發作處置，下列敘述何者錯誤？",opts:["A.電腦斷層檢查可確定異常放電位置","B.發作時，可將頭偏向一側以利唾液流出","C.發作時，若病人意識不清，不須試圖喚醒病人","D.驟然停藥為重積性癲癇常見的原因"],ans:[0],expl:"腦電圖（EEG）才是用來確認異常放電位置的檢查，電腦斷層（CT）主要顯示結構性病灶（如出血、腫瘤），無法直接確定異常放電位置，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。發作時頭偏向一側以利分泌物流出、避免嗆咳（B✓）；意識不清時不應強行喚醒以免病人躁動受傷（C✓）；驟然停用抗癲癇藥物確實是誘發重積性癲癇最常見的原因之一（D✓）。"},{n:105,no:5,subj:"神經系統",q:"有關左側大腦損傷可能引起的功能缺失症狀，下列敘述何者正確？①計算能力降低 ②空間缺損 ③半側忽略 ④語言障礙",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"左側大腦半球主司語言功能與計算等分析性能力，故左側大腦損傷會出現計算能力降低（①）與語言障礙（④），選①④＝B（本題答案）。空間缺損與單側忽略（②③）則多見於右側大腦（非優勢半球）損傷，與本題左側大腦損傷不符。"},{n:106,no:6,subj:"消化系統",q:"有關胃食道逆流症的護理指導，下列敘述何者錯誤？",opts:["A.進食後應立即平躺","B.避免在睡前2～3小時進食","C.少量多餐細嚼慢嚥","D.肥胖的病人應減重"],ans:[0],expl:"胃食道逆流症（GERD）病人應避免進食後立即平躺，宜維持上身抬高、進食後至少2～3小時再躺下，以減少逆流機會，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。睡前2～3小時避免進食（B✓）、少量多餐細嚼慢嚥減少胃內壓（C✓）、肥胖病人減重以降低腹內壓（D✓）皆為正確衛教。"},{n:107,no:7,subj:"消化系統",q:"有關大腸癌的高危險因子，下列敘述何者正確？",opts:["A.常攝取蔬菜及高纖維質","B.幽門螺旋桿菌感染","C.有家族型腺瘤性息肉症病史","D.胃酸分泌過多症"],ans:[2],expl:"家族型腺瘤性息肉症（FAP）是大腸癌極重要的遺傳危險因子，帶因者幾乎必然發展為大腸癌，故為高危險因子（C✓，本題答案）。高纖蔬菜攝取是保護因子而非危險因子（A✗）；幽門螺旋桿菌主要與胃癌相關，非大腸癌（B✗）；胃酸分泌過多並非大腸癌的建立危險因子（D✗）。"},{n:108,no:8,subj:"消化系統",q:"肝性腦病變的病人給與Lactulose的目的，下列何者正確？",opts:["A.酸化糞便以減少氨在腸道吸收","B.抑制腸內細菌以減少氨的分解","C.預防發生肝腎症候群","D.減輕腹水的產生"],ans:[0],expl:"Lactulose於腸道被細菌分解成乳酸、醋酸等有機酸，使腸腔環境酸化，將氨（NH3）轉為不易吸收的銨離子（NH4+），減少氨經腸道吸收入血，藉此降低血氨、改善肝性腦病變（A✓，本題答案）。其主要機轉是酸化腸道而非直接抑菌（B✗）；也非用於預防肝腎症候群（C✗）或減輕腹水（D✗，腹水處置以限鈉、利尿劑為主）。"},{n:109,no:9,subj:"消化系統",q:"有關胰臟炎急性發作及其治療的敘述，下列何者錯誤？",opts:["A.上腹部中央疼痛或輻射到背部，疼痛為突發、持續且劇烈","B.血清澱粉酶（amylase）升高、脂肪酶（lipase）上升、血鈣下降","C.放置鼻胃管的目的為抽出胰澱粉酶，以避免發炎加劇","D.當病情穩定可開始進食時，應採低脂肪、低蛋白、高醣飲食"],ans:[2],expl:"急性胰臟炎放置鼻胃管的主要目的是進行胃腸減壓、減少嘔吐及降低食物或胃酸刺激十二指腸分泌secretin進而刺激胰液分泌，並非「抽出胰澱粉酶」，此敘述在生理機轉上錯誤，為本題答案（C✗，題目問「何者錯誤」）。上腹部劇烈疼痛輻射至背部（A✓）、澱粉酶脂肪酶上升合併低血鈣（因脂肪皂化消耗鈣，B✓）、病情穩定後採低脂低蛋白高醣飲食以減少胰臟負擔（D✓）皆為正確敘述。"},{n:110,no:10,subj:"消化系統",q:"有關食道憩室的敘述，下列何者正確？",opts:["A.常見胸口灼熱感症狀","B.可做鋇劑食道攝影確定位置","C.餐後平躺可減緩不適","D.一旦發生須儘速以手術治療"],ans:[1],expl:"食道憩室可利用鋇劑食道攝影（barium swallow）確定憩室位置與大小，是重要的診斷工具（B✓，本題答案）。典型症狀以吞嚥困難、食物逆流、口臭為主，非以胸口灼熱為主要表現（A✗）；餐後平躺反而會增加食物滯留憩室內逆流的風險，應避免（C✗）；治療以症狀嚴重或併發症（如吸入性肺炎）者才考慮手術，非一律儘速手術（D✗）。"},{n:111,no:11,subj:"骨骼肌肉",q:"有關痛風性關節炎護理指導之敘述，下列何者正確？",opts:["A.避免服用Aspirin，以預防血中尿酸升高","B.採取高脂飲食，以促進尿酸鹽排出","C.多喝小紅莓汁，以預防尿酸結石產生","D.多攝取肉汁、海鮮，以促進嘌呤代謝"],ans:[0],expl:"低劑量Aspirin會抑制腎小管尿酸排泄，使血中尿酸濃度上升、誘發痛風發作，故應避免服用以預防血尿酸升高（A✓，本題答案）。高脂飲食會抑制腎臟排出尿酸鹽，使病情惡化而非促進排出（B✗）；小紅莓汁預防的是泌尿道感染及草酸鈣結石，並非尿酸結石的實證措施（C✗）；肉汁、海鮮等高普林食物應限制攝取，而非鼓勵多吃以「促進嘌呤代謝」（普林代謝後生成的正是尿酸，此說法本身即錯誤，D✗）。"},{n:112,no:12,subj:"骨骼肌肉",q:"有關肌肉骨骼系統身體檢查評估結果之敘述，下列何者正確？",opts:["A.湯瑪斯試驗（Thomas test）陽性反應表示病人對側髖關節攣縮","B.浮動試驗（Ballottement test）陽性表示病人膝半月板有損傷","C.抽拉試驗（Drawer test）若能將小腿向後牽引6mm表示副韌帶鬆弛","D.廷內爾氏徵象（Tinel's sign）陽性反應表示後十字韌帶鬆弛"],ans:[0],expl:"湯瑪斯試驗（Thomas test）操作時讓病人一側髖屈曲抱膝貼近胸部，若對側下肢隨之抬離床面即為陽性，代表對側髖關節有屈曲攣縮（A✓，本題答案）。浮動試驗（Ballottement test）陽性代表膝關節有積液，並非半月板損傷（半月板損傷需靠McMurray test，B✗）；抽拉試驗（Drawer test）評估的是十字韌帶（前／後）鬆弛，不是副（側）韌帶（C✗）；廷內爾氏徵象（Tinel's sign）是敲擊神經誘發刺痛以評估神經壓迫（如腕隧道症候群），並非用於評估十字韌帶（D✗）。"},{n:113,no:13,subj:"骨骼肌肉",q:"有關骨質疏鬆症處置之敘述，下列何者正確？",opts:["A.每日飯前服用碳酸鈣（calcium carbonate），以增加鈣吸收","B.鼓勵日曬及攝取維生素D，以促進鈣吸收","C.每日飯後服用雙磷酸鹽類（bisphosphonates），以減少骨流失","D.每天使用副甲狀腺素（teriparatide）鼻噴劑，以增加骨質量"],ans:[1],expl:"日曬可促進皮膚合成維生素D，維生素D則能促進腸道鈣質吸收，是骨質疏鬆症處置的重要非藥物措施（B✓，本題答案）。碳酸鈣需要胃酸協助分解吸收，建議「隨餐或飯後」服用而非飯前（A✗）；雙磷酸鹽類須「空腹」以開水送服，服藥後30～60分鐘內維持直立並避免進食，而非飯後服用（吸收率會大幅下降，C✗）；副甲狀腺素類似物teriparatide是每日皮下注射劑型，並非鼻噴劑（D✗）。"},{n:114,no:14,subj:"感官系統",q:"下列何者為充滿血管可以供應眼球及視網膜血液及營養的構造？",opts:["A.鞏膜","B.角膜","C.脈絡膜","D.睫狀體"],ans:[2],expl:"脈絡膜（choroid）位於視網膜與鞏膜之間，含豐富血管網，負責供應視網膜外層與眼球後段的血液與營養（C✓，本題答案）。鞏膜為眼球外層堅韌的白色保護結構，血管分布少（A✗）；角膜為前方透明無血管構造，藉由房水與淚液提供養分（B✗）；睫狀體主要功能是分泌房水及調節水晶體形狀，非供應視網膜血液的主要構造（D✗）。"},{n:115,no:15,subj:"感官系統",q:"有關扁桃腺炎（tonsilitis）病人接受扁桃腺切除術之敘述，下列何者錯誤？",opts:["A.急性發炎期時應儘快安排手術","B.術前可用溫食鹽水漱口，減輕咽喉不適","C.疑似扁桃腺腫瘤是手術適應症","D.術後有持續吞嚥動作時，可能為傷口出血的現象"],ans:[0],expl:"扁桃腺切除術應待急性發炎期消退後才安排手術，急性期手術會大幅增加出血與感染風險，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。術前以溫食鹽水漱口可減輕咽喉不適（B✓）；疑似腫瘤確實是手術適應症之一（C✓）；術後若病人出現持續吞嚥動作，常是傷口滲血刺激咽喉所致，需警覺出血徵象（D✓）。"},{n:116,no:16,subj:"心臟血管",q:"進行心臟復健時如出現活動耐力不足時應停止，下列何者不是其判斷依據？",opts:["A.心律不整或心跳上升或下降超過20次／分鐘以上","B.血壓上升或下降超過20 mmHg以上","C.體溫大於37℃","D.出現胸悶、胸痛、眩暈、盜汗、虛弱、疲倦"],ans:[2],expl:"體溫大於37℃本身屬於正常範圍邊緣，並非心臟復健運動中止活動耐力不足的判斷依據（C✗，題目問「何者不是」，故C為本題答案）。心律不整、心跳或血壓變化超過安全範圍（A、B）以及出現胸悶、胸痛、眩暈、盜汗、虛弱疲倦等症狀（D）都是公認需立即停止運動的臨床指標。"},{n:117,no:17,subj:"心臟血管",q:"有關裝置永久性心臟節律器病人居家護理指導之敘述，下列何者錯誤？",opts:["A.每天需測量橈動脈1分鐘","B.住家頂樓避免裝設手機基地台","C.可使用微波爐，但應保持安全距離","D.持續打嗝時，可做伐式操作法（Valsalva）緩解"],ans:[3],expl:"裝置永久性心臟節律器病人若出現持續性打嗝，可能是節律器導線移位刺激橫膈神經所致，屬於需要就醫評估的異常徵象，並非在家自行執行伐式操作即可緩解，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。每日測量橈動脈脈搏1分鐘以監測節律器功能（A✓）、避免強電磁波干擾源如頂樓基地台（B✓）、微波爐可使用但保持安全距離（C✓）皆為正確居家指導。"},{n:118,no:18,subj:"心臟血管",q:"有關心衰竭之敘述，下列何者正確？",opts:["A.右心衰竭會出現心搏過速、心室肥大、第三心音","B.右心衰竭常出現乾咳或帶有泡沫及血絲痰","C.左心衰竭早期徵象是下肢水腫、頸靜脈怒張、腹水","D.左心衰竭常見症狀為呼吸困難、端坐呼吸"],ans:[3],expl:"左心衰竭因肺循環鬱血，典型症狀為呼吸困難、端坐呼吸（需高枕或坐姿才能緩解喘的感覺），為本題正確敘述（D✓）。右心衰竭主要出現體循環鬱血徵象（下肢水腫、頸靜脈怒張、肝腫大、腹水），而非A所述心搏過速、心室肥大、第三心音這類左心衰竭相關表現（A✗）；乾咳合併泡沫血絲痰是「左心衰竭」肺水腫的典型表現，並非右心衰竭（B✗）；下肢水腫、頸靜脈怒張、腹水是右心衰竭而非左心衰竭的早期徵象，敘述相反（C✗）。"},{n:119,no:19,subj:"心臟血管",q:"有關急性心肌梗塞引起的心因性休克給予的藥物處置，下列敘述何者錯誤？",opts:["A.Dobutamine滴注可以增加心肌收縮力及心輸出量","B.利尿劑主要目的為降低心臟前負荷","C.嗎啡主要是緩解疼痛，對心臟前、後負荷沒有影響","D.血管擴張劑nitroglycerin（NTG）滴注可以擴張周邊血管而減輕心臟負荷"],ans:[2],expl:"嗎啡除了鎮痛之外，還能透過靜脈擴張作用降低心臟前負荷，並有輕度動脈擴張效果降低後負荷，並非「沒有影響」，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。Dobutamine為正性肌力藥物可增加心肌收縮力與心輸出量（A✓）；利尿劑主要目的為降低前負荷、減少肺鬱血（B✓）；硝酸甘油（NTG）靜脈滴注以擴張靜脈為主，可降低心臟前負荷、減輕心臟做功（D✓）。"},{n:120,no:20,subj:"心臟血管",q:"有關靜脈剝除結紮手術（stripping and ligation）術後照護之敘述，下列何者錯誤？",opts:["A.術後臥床期間避免於床上進行全範圍關節運動","B.抬高床尾15度，膝部不彎曲","C.術後下床時均應穿彈性襪","D.應監測末梢血循變化及是否有感覺異常"],ans:[0],expl:"靜脈剝除結紮手術後臥床期間應鼓勵執行全範圍關節運動（尤其足踝幫浦運動）以促進靜脈回流、預防深部靜脈栓塞，而非避免執行，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。抬高床尾15度、膝部保持伸直可促進靜脈回流又不壓迫膕窩血管（B✓）；下床活動時應穿彈性襪以支持靜脈回流（C✓）；術後需持續監測末梢血循與感覺變化以早期發現併發症（D✓）。"},{n:121,no:21,subj:"腫瘤血液",q:"正在接受體外放射線治療的癌症病人表示：「臉和頸部的皮膚發紅刺痛、脫屑，甚至有些部位會濕濕的，很不舒服」，下列處置何者正確？",opts:["A.清水洗淨後塗擦凡士林保濕","B.可局部溫濕敷以緩解不適症狀","C.0.9% N/S沖洗後以親水敷料（DuoDerm）覆蓋","D.刮鬍子時用刮鬍膏潤滑刮鬍刀以免刮傷"],ans:[2],expl:"體外放射線治療引起的濕性脫皮（moist desquamation）反應，應以0.9%生理食鹽水溫和沖洗清潔，再以親水性敷料（如DuoDerm）覆蓋，以維持濕潤癒合環境並保護皮膚（C✓，本題答案）。凡士林保濕多用於乾性反應，且未強調正確清潔方式（A✗）；局部溫熱敷可能加重皮膚發炎反應，應避免（B✗）；照射部位刮鬍應使用電動刮鬍刀以降低皮膚破損風險，而非以刮鬍膏配合刮鬍刀濕刮（D✗）。"},{n:122,no:22,subj:"腫瘤血液",q:"顆粒性白血球低下的癌症病人之食物選擇，下列何者最適切？",opts:["A.溏心蛋：補充蛋白質","B.泡菜：補充纖維質防便秘","C.柑橘：補充維生素C","D.優格：補充鈣質、維生素"],ans:[2],expl:"顆粒性白血球低下（嗜中性球低下）病人採「低菌飲食」原則，柑橘類水果洗淨去皮後食用是安全的維生素C來源（C✓，本題答案）。溏心蛋等未全熟蛋品有沙門氏菌等病原污染風險，應避免（A✗）；泡菜等醃漬發酵食品可能含較高菌量，非低菌飲食建議（B✗）；優格等含活菌發酵乳製品同樣可能增加感染風險，一般建議選擇經高溫滅菌處理的乳製品（D✗）。"},{n:123,no:23,subj:"腫瘤血液",q:"中樞神經系統癌症病人，若選用難以通過血腦障壁之化學治療時，下列何者為最適切之給藥途徑？①Port-A ②Ommaya reservoir ③Hickman catheter ④intrathecal injection",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[3],expl:"Ommaya reservoir（腦室內儲液槽）與鞘內注射（intrathecal injection）皆可將藥物直接送入腦脊髓液或腦室內，繞過血腦障壁，是中樞神經系統腫瘤化療給藥的適切途徑，選②④＝D（本題答案）。Port-A與Hickman catheter皆屬全身性靜脈中心導管，藥物仍須通過血腦障壁才能進入中樞神經系統，穿透效果有限。"},{n:124,no:24,subj:"腫瘤血液",q:"為一位乳癌骨轉移合併脊髓壓迫的病人進行身體評估時，下列症狀或徵象何者最不常出現？",opts:["A.背部疼痛指數7分（滿分10分）","B.布魯辛斯基氏徵象（Brudzinski's sign）陽性","C.大小便失禁情形","D.巴賓斯基氏徵象（Babinski's sign）陽性"],ans:[1],expl:"布魯辛斯基氏徵象（Brudzinski's sign）為腦膜刺激徵象，主要用於評估腦膜炎，並非脊髓壓迫的典型表現，屬於本題「最不常出現」的選項（B✓，本題答案）。背部劇痛、大小便失禁（自主神經功能受損）、以及巴賓斯基氏徵象陽性（上運動神經元徵象）皆是脊髓壓迫常見的臨床表現。"},{n:125,no:25,subj:"腫瘤血液",q:"下列何者接受自體移植治療後的5年存活率最高？",opts:["A.急性骨髓性白血病第一次完全緩解後接受自體骨髓移植","B.急性骨髓性白血病第一次完全緩解後接受自體周邊血液幹細胞移植","C.急性淋巴性白血病第一次完全緩解後接受自體骨髓移植","D.急性淋巴性白血病第一次完全緩解後接受自體周邊血液幹細胞移植"],ans:[0],expl:"依相關腫瘤護理文獻資料，急性骨髓性白血病（AML）病人於第一次完全緩解後接受自體骨髓移植，其後續5年存活率在題目所列選項中相對最高（A✓，本題答案）。急性淋巴性白血病（ALL）成人患者自體移植後長期存活率整體較AML组更不理想，周邊血液幹細胞移植雖植入較快但長期存活率比較仍以此選項最佳，詳細數據建議依最新血液腫瘤學文獻或指引為準。"},{n:126,no:26,subj:"腫瘤血液",q:"有關致癌因子及其相關癌症的敘述，下列何者需進一步提供護理指導以澄清誤解？",opts:["A.「我看你還是少吃點檳榔吧，不然口腔癌可能會找上你喔」","B.「平時喝酒適量即可，過量可能會導致肝癌、乳癌、食道癌的發生」","C.「我老公平時是油漆工，聽說長時間接觸那些苯胺染料，可能和膀胱癌的發生有關」","D.「上次我去看醫師，他跟我說我有幽門螺旋桿菌，可能和食道癌的發生有關」"],ans:[3],expl:"幽門螺旋桿菌感染主要與胃癌及胃部黏膜相關淋巴組織淋巴瘤（MALT lymphoma）有關，並非食道癌的已知致病因子，此說法需要護理人員進一步澄清，為本題答案（D✓，題目問「何者需澄清誤解」）。檳榔與口腔癌（A）、酒精過量與肝癌乳癌食道癌（B）、苯胺染料職業暴露與膀胱癌（C）皆是實證上成立的致癌因子關聯，不需澄清。"},{n:127,no:27,subj:"其他",q:"有關帶狀疱疹臨床症狀之敘述，下列何者正確？",opts:["A.帶狀小水疱群聚常會環繞軀幹一圈","B.最常發生在頭頸部","C.口腔有乳白色的斑塊","D.淋巴腺腫與水疱同時發生、同時消失"],ans:[3],expl:"帶狀疱疹的水疱群與周邊淋巴腺腫大通常同時發生、隨病程一起消退，為本題正確敘述（D✓）。帶狀疱疹沿單一皮節（dermatome）分布，特徵是通常「不會跨越身體中線」，並非環繞軀幹一圈，A的敘述是常見迷思（A✗）；好發部位以胸髓皮節最常見，並非以頭頸部為主（B✗）；口腔乳白色斑塊較符合口腔念珠菌感染或口腔毛狀白斑之描述，非帶狀疱疹典型表現（C✗）。"},{n:128,no:28,subj:"其他",q:"有關皮膚腫瘤之敘述，下列何者正確？",opts:["A.表皮囊腫（epidermal cysts）是一種惡性腫瘤，通常包裹著乳白色的粉狀物質","B.脂漏性角化症（seborrheic keratoses）是一種良性的表皮角質過度增生","C.纖維瘤（fibroma）是一種脂肪細胞常見的腫瘤","D.蜘蛛狀血管瘤（spider hemangioma）與血液中黃體激素升高有關"],ans:[1],expl:"脂漏性角化症（seborrheic keratoses）是常見於中老年人的良性表皮角質細胞增生病灶，外觀常呈「蠟狀黏貼感」，為本題正確敘述（B✓）。表皮囊腫是良性病灶而非惡性腫瘤，內容物為角質碎屑而非「乳白色粉狀物質」的描述並不精確（A✗）；纖維瘤是纖維結締組織腫瘤，脂肪細胞腫瘤應稱為脂肪瘤（lipoma）（C✗）；蜘蛛狀血管瘤與血中雌激素（estrogen）濃度上升有關，並非黃體激素（progesterone）（D✗）。"},{n:129,no:29,subj:"其他",q:"林先生因熱燒傷接受植皮手術，有關術後注意事項之敘述，下列何者正確？",opts:["A.供皮區應使用石膏夾板固定至少3～7天","B.術後應鼓勵病人移植部位多接受日照","C.肩部燒傷應使病人採俯臥，手臂位置遠離身體","D.膝蓋受傷部位應採屈曲姿位，膝下墊一枕頭"],ans:[2],expl:"肩部燒傷病人術後應採俯臥或仰臥並將手臂外展、遠離身體的姿位，以預防腋窩攣縮，為本題正確敘述（C✓）。供皮區傷口一般以敷料換藥照護為主，不需石膏夾板固定3～7天（A✗）；剛植皮部位皮膚脆弱、色素调節功能未恢復，應避免日曬，而非鼓勵多曬（B✗）；膝關節燒傷應維持伸直姿位以預防屈曲攣縮，而非屈曲墊枕（D✗）。"},{n:130,no:30,subj:"其他",q:"有關後天免疫缺乏症候群（AIDS）臨床表徵之敘述，下列何者錯誤？",opts:["A.急性HIV感染可能出現類感冒症狀如淋巴腺腫大、發燒、肌肉關節疼痛","B.臨床潛伏期可能持續10年或更長時間","C.卡波西氏肉瘤是愛滋病人最常見的惡性腫瘤","D.愛滋病人可能出現口腔紅斑症"],ans:[3],expl:"愛滋病人口腔最具代表性的病灶是口腔毛狀白斑（oral hairy leukoplakia，與EB病毒相關），外觀為舌側緣的白色皺褶狀斑塊，並非以「紅斑」為典型表現，此敘述較不精確，為本題答案（D✗，題目問「何者錯誤」）。急性HIV感染常見類感冒症狀（A✓）；臨床潛伏期可長達10年以上（B✓）；卡波西氏肉瘤是愛滋病人最常見的伺機性惡性腫瘤（C✓）。"},{n:131,no:31,subj:"腫瘤血液",q:"為降低排斥反應，下列何者為器官移植前進行組織配對的常見檢驗？①C型肝炎檢驗 ②人類白血球抗原（HLA） ③混和性淋巴細胞反應 ④交叉配對試驗 ⑤人類免疫缺乏病毒（HIV）篩檢",opts:["A.①②③","B.①④⑤","C.②③④","D.③④⑤"],ans:[2],expl:"人類白血球抗原（HLA）配對、混和性淋巴細胞反應（MLR）及交叉配對試驗都是評估捐贈者與受贈者組織相容性、預測排斥風險的常見移植前配對檢驗，選②③④＝C（本題答案）。C型肝炎與HIV篩檢屬於感染性疾病篩檢，目的是排除傳染病傳播風險，並非組織配對檢驗。"},{n:132,no:32,subj:"呼吸系統",q:"病人因車禍送到急診，身體評估出現下列何者時，應懷疑可能有氣胸？",opts:["A.一側聽不到呼吸音或呼吸音減弱","B.二側肺葉有喘鳴音","C.二側肺葉於吸氣時聽到囉音","D.一側肺葉叩診出現濁音"],ans:[0],expl:"氣胸因胸膜腔積氣使患側肺塌陷，聽診時患側呼吸音會消失或明顯減弱，叩診則呈現過度反響音（非濁音），為本題正確敘述（A✓，D的「濁音」反而較符合肋膜積液或肺實質化，D✗）。雙側喘鳴音或囉音較常見於氣喘、肺水腫等瀰漫性肺部疾病，非氣胸的典型局部表現（B、C✗）。"},{n:133,no:33,subj:"呼吸系統",q:"有關急性呼吸窘迫症候群（ARDS）之敘述，下列何者正確？",opts:["A.因為外分泌腺分泌異常，而導致黏液聚集在肺泡中","B.因為肺部疾病，而引起右心肥大與肥厚","C.因為肋膜腔內積聚空氣，而導致肺部塌陷","D.因為肺泡微血管膜的通透性受損，而產生肺水腫"],ans:[3],expl:"急性呼吸窘迫症候群（ARDS）的核心病理機轉是肺泡微血管膜通透性受損，使富含蛋白質的液體滲漏進入肺泡腔，形成非心因性肺水腫，為本題正確敘述（D✓）。並非外分泌腺分泌異常導致黏液堵塞（該描述較符合囊狀纖維化，A✗）；ARDS本身並非直接造成右心肥大肥厚的機轉（那較符合慢性肺病引起的肺心症，B✗）；肋膜腔積氣造成肺塌陷是氣胸的機轉，非ARDS（C✗）。"},{n:134,no:34,subj:"呼吸系統",q:"下列何者不屬於動脈血液氣體分析（arterial blood gas analysis）可以直接偵測之項目？",opts:["A.呼吸困難","B.酸鹼度","C.重碳酸鹽含量","D.血氧飽和度"],ans:[0],expl:"呼吸困難是病人主觀症狀或臨床觀察指標，並非動脈血液氣體分析可直接測得的數值，為本題答案（A✓，題目問「何者不屬於」）。酸鹼度（pH）、重碳酸鹽（HCO3-）、血氧飽和度（SaO2）皆是ABG報告中可直接測得或換算得出的項目。"},{n:135,no:35,subj:"呼吸系統",q:"下列何種給氧方式能提供最高的氧氣吸入濃度（FiO2）？",opts:["A.卞德里面罩","B.單純型面罩","C.氧氣鼻套管","D.非再吸入面罩"],ans:[3],expl:"非再吸入面罩（non-rebreather mask）搭配儲氣袋與單向活瓣設計，可提供本題選項中最高的氧氣吸入濃度（FiO2可達約80～95%以上），為本題答案（D✓）。卞德里面罩（Venturi mask）雖能精確控制FiO2但濃度範圍中等（約24～60%）；單純型面罩約提供40～60%；鼻套管約24～44%，皆低於非再吸入面罩。"},{n:136,no:36,subj:"呼吸系統",q:"有關肺膿瘍病人的護理評估，下列何者最可能出現？",opts:["A.呼吸音減弱有時會出現肋膜摩擦音","B.叩診出現鼓音","C.上肺葉吸氣期出現喘鳴音","D.叩診出現過度反響音"],ans:[0],expl:"肺膿瘍病人因局部肺組織壞死化膿，患部呼吸音常減弱，若膿瘍鄰近肋膜刺激引發發炎反應，可能合併肋膜摩擦音，為本題最可能出現的評估發現（A✓）。叩診鼓音多見於氣胸或腸道脹氣（B✗）；上肺葉吸氣喘鳴音較非肺膿瘍典型表現（C✗）；過度反響音常見於肺氣腫等過度充氣狀態，非肺膿瘍典型叩診音（D✗）。"},{n:137,no:37,subj:"泌尿系統",q:"有關高血鉀導因之敘述，下列何者正確？①使用血管收縮素轉換酶抑制劑 ②使用醛固酮拮抗劑 ③使用噻嗪類利尿劑（thiazide diuretics） ④代謝性鹼中毒",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[0],expl:"血管收縮素轉換酶抑制劑（ACEI）會減少醛固酮分泌，使腎臟排鉀減少；醛固酮拮抗劑（如spironolactone）則直接阻斷醛固酮促進排鉀的作用，兩者皆會導致血鉀上升，選①②＝A（本題答案）。噻嗪類利尿劑（thiazide）作用機轉是促進排鉀，實際上會造成低血鉀而非高血鉀（③錯誤）；代謝性鹼中毒時細胞內外氫鉀離子交換，通常合併低血鉀，而非高血鉀（④錯誤）。"},{n:138,no:38,subj:"泌尿系統",q:"尿液分析中出現紅血球的病因，下列何者錯誤？",opts:["A.輸尿管結石","B.前列腺肥大","C.子癲前症","D.尿路感染"],ans:[2],expl:"子癲前症的典型腎臟表現是蛋白尿合併高血壓，並非以血尿為主要特徵，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。輸尿管結石刮傷黏膜（A✓）、攝護腺肥大合併泌尿道刺激或感染（B✓）、尿路感染發炎反應（D✓）皆是臨床上會出現血尿的常見病因。"},{n:139,no:39,subj:"泌尿系統",q:"陳先生，88歲，因全身水腫，呼吸喘至急診求治，診斷為急性腎衰竭，下列敘述何者正確？",opts:["A.血鉀7.5 mg/dL，心電圖T波低而寬長","B.可能因前列腺肥大，導致腎性急性腎衰竭","C.24小時尿量約300 c.c.，正處於腎衰竭少尿期","D.腎臟超音波檢查，顯示雙側腎臟大小為7.5 cm"],ans:[2],expl:"急性腎衰竭少尿期的定義為24小時尿量少於400c.c.，題目中300c.c.符合少尿期表現，為本題正確敘述（C✓）。高血鉀在心電圖上典型表現是「高尖T波」，並非「低而寬長」，敘述相反（A✗）；攝護腺肥大導致的是「阻塞性」（後腎性）急性腎衰竭，並非腎因性（腎實質性）（B✗）；正常成人腎臟長度約10～12公分，7.5公分屬於明顯縮小，較符合慢性腎病萎縮腎臟的表現，並非急性腎衰竭典型影像（D✗）。"},{n:140,no:40,subj:"泌尿系統",q:"有關腎臟功能檢測血清肌酸酐（creatinine）之敘述，下列何者錯誤？",opts:["A.易受飲食影響可用以估算排泄能力","B.是用來估算腎臟功能最佳指標","C.升高時代表腎功能已損傷50%以上","D.升高時代表腎絲球過濾率功能已降低"],ans:[0],expl:"血清肌酸酐（creatinine）之所以被視為評估腎功能較穩定可靠的指標，正是因為它「較不易受飲食與肌肉代謝以外因素影響」，此敘述（易受飲食影響）方向相反，為本題答案（A✗，題目問「何者錯誤」）。臨床上確實常以肌酸酐作為評估腎功能的重要（甚至首選）指標（B✓）；肌酸酐明顯上升時，通常代表腎功能已下降50%以上（C✓）、腎絲球過濾率已顯著降低（D✓），皆為正確概念。"},{n:141,no:41,subj:"泌尿系統",q:"有關預防泌尿道感染復發的護理指導，下列何者錯誤？",opts:["A.減少不必要的導尿管留置","B.排便後，應由前往後擦拭","C.洗澡避免盆浴，儘量採淋浴","D.症狀減輕沒發燒就可以停藥"],ans:[3],expl:"預防泌尿道感染復發應完整服用抗生素療程，即使症狀緩解、體溫恢復正常也不可自行停藥，以免感染未清除乾淨或誘發抗藥性，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。減少不必要導尿管留置（A✓）、如廁後由前往後擦拭以避免肛門細菌污染尿道口（B✓）、淋浴取代盆浴減少細菌上行感染機會（C✓）皆為正確之泌尿道感染預防指導。"},{n:142,no:42,subj:"內分泌系統",q:"有關糖尿病酮酸中毒（DKA）之處置，下列何者正確？①建立靜脈輸液，由低劑量胰島素開始給與 ②最初2小時，給與0.45％生理食鹽水維持電解質平衡 ③等尿液排出量恢復正常，應補充鉀離子 ④血液pH值>7.1時，則與以重碳酸鈉（NaHCO3）",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[1],expl:"糖尿病酮酸中毒（DKA）治療原則為先建立靜脈輸液矯正脫水，並以低劑量胰島素持續輸注控制血糖（①✓）；待尿量恢復（腎功能確認足夠）且血鉀隨治療下降時才開始補充鉀離子，以避免補鉀過早引發高血鉀（③✓），選①③＝B（本題答案）。DKA初期輸液通常先給與0.9%生理食鹽水以快速擴充血管容積，而非0.45%張力較低的溶液（②錯誤）；重碳酸鈉僅保留給極嚴重酸血症（pH通常<6.9～7.0）使用，並非pH大於7.1時給予，方向相反（④錯誤）。"},{n:143,no:43,subj:"內分泌系統",q:"有關服用治療甲狀腺機能亢進之放射性碘（131I）的敘述，下列何者正確？",opts:["A.食物會延遲放射性碘（131I）吸收，服用前一天午夜後及服用後2小時應禁食，以利吸收","B.服用治療劑量於8～30 μCi的病人應限制訪客，第一週最好單獨睡，避免接觸孕婦","C.服用一個星期後會經由尿液、糞便排出，這段時間在使用馬桶後，宜沖水2～3次","D.服用高劑量者10年後易出現甲狀腺功能亢進，故需定期追蹤血清T3是否上升"],ans:[1],expl:"接受治療劑量放射性碘（131I）病人，依輻射防護原則應限制訪客接觸、第一週最好單獨就寢、並避免接觸孕婦及嬰幼兒，以降低他人輻射暴露風險，為本題正確敘述（B✓）。放射性碘服用前後的空腹規範主要是為了促進甲狀腺攝取而非題目所述延遲吸收的方向（A✗）；服藥後經尿液排出為主，如廁後沖水2～3次是正確防護措施，但題目描述之時序與此細節仍以官方公告版本為準（C✗，依官方答案非本題最適選項）；高劑量放射碘治療甲亢，長期追蹤更需留意的是逐漸出現「甲狀腺功能低下」，而非甲状腺機能亢進再度上升，方向相反（D✗）。"},{n:144,no:44,subj:"內分泌系統",q:"有關肢端肥大症之症狀，下列何者錯誤？",opts:["A.泌尿系統：低血鈣症、腎結石","B.骨骼系統：關節痛、肌肉無力","C.神經系統：腕隧道症候群、嗜睡","D.皮膚系統：皮膚增厚、油脂增多"],ans:[0],expl:"肢端肥大症因生長激素過量常合併高血鈣及腎結石傾向，而非低血鈣，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。骨骼肌肉系統可能出現關節痛、肌肉無力（B✓）；神經系統因軟組織增生壓迫可能出現腕隧道症候群及嗜睡等表現（C✓）；皮膚因結締組織增生而增厚、皮脂腺分泌增加使皮膚油膩（D✓）。"},{n:145,no:45,subj:"內分泌系統",q:"有關尿崩症病人之護理處置，下列何者錯誤？",opts:["A.應鼓勵病人多喝開水，以維持水分和體液電解質的平衡","B.噴灑鼻噴劑型desmopressin時，教導病人應吸氣以增加藥效","C.腎因性尿崩症應給與Thiazide利尿劑及限鹽攝取，以緩解症狀","D.Vassopressin Tannate是油性懸浮液，抽藥前需先溫熱與搖勻"],ans:[1],expl:"使用鼻噴劑型desmopressin時應正常呼吸給藥，避免用力吸氣，以免藥物被吸入過深經咽喉吞下而降低經鼻黏膜吸收的療效，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。中樞性尿崩症鼓勵病人適量攝取水分以維持水電解質平衡（A✓）；腎因性尿崩症可矛盾地使用thiazide利尿劑並限鹽以減少尿量（C✓）；Vasopressin Tannate為油性懸浮液，使用前須溫熱並搖勻使藥物均勻分布（D✓）。"},{n:146,no:46,subj:"內分泌系統",q:"有關糖尿病足病人運動時鞋襪選擇之建議，下列何者錯誤？",opts:["A.楦頭要寬，可讓腳趾自由伸展","B.穿鞋前要先檢查鞋內有無異物","C.襪子選擇棉質易吸汗為佳","D.運動時需穿鞋保護雙足，偶爾不穿襪沒關係"],ans:[3],expl:"糖尿病足病人因周邊神經病變導致保護性感覺降低，運動時務必穿著襪子搭配鞋子，絕不可赤腳或不穿襪子活動，以免不自覺產生摩擦傷口而未及時察覺，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。楦頭寬讓腳趾有活動空間（A✓）、穿鞋前檢查鞋內異物避免壓傷（B✓）、選擇棉質吸汗襪子減少潮濕摩擦（C✓）皆為正確之糖尿病足鞋襪選擇指導。"},{n:147,no:47,subj:"其他",q:"有關2020年美國心臟醫學會（American Heart Association, AHA）公告準則，啟動院內心臟停止（IHCA）生命之鏈（chain of survival）的次序，下列何者正確？①提供高品質心肺復甦 ②去顫 ③早期監測與預防 ④心臟驟停後照護 ⑤復原 ⑥啟動緊急應變系統",opts:["A.①→②→③→⑥→⑤→④","B.③→⑥→①→②→④→⑤","C.⑥→①→③→②→④→⑤","D.⑥→②→③→①→⑤→④"],ans:[1],expl:"依2020年AHA準則，院內心臟停止（IHCA）生命之鏈依序為：早期監測與預防（③）→啟動緊急應變系統（⑥）→高品質心肺復甦（①）→去顫（②）→心臟驟停後照護（④）→復原（⑤），選B（本題答案），強調院內情境應先著重及早辨識與預防惡化，再依序啟動急救系統與後續處置。"},{n:148,no:48,subj:"其他",q:"72歲男性，有心臟病病史，夏天逛露天賣場時不明原因昏倒，臉色潮紅，皮膚乾熱，呼吸24次／分，脈搏強而快，體溫41.5℃，下列何者為其最可能診斷？",opts:["A.熱中暑（heat stroke）","B.熱性痙攣（heat cramp）","C.熱衰竭（heat exhaustion）","D.熱暈厥（heat syncope）"],ans:[0],expl:"病人於高溫環境中昏倒，出現皮膚乾熱（無汗）、體溫高達41.5℃、意識改變等表現，符合熱中暑（heat stroke）的典型診斷特徵：體溫調節機制失代償、停止排汗散熱，屬於熱急症中最危急的類型，為本題答案（A✓）。熱衰竭（heat exhaustion）典型表現則是皮膚濕冷合併大量出汗，體溫通常較熱中暑低，可與本題皮膚乾熱的描述做區別（C✗）；熱痙攣與熱暈厥的體溫及意識變化程度皆不如本題嚴重（B、D✗）。"},{n:149,no:49,subj:"其他",q:"有關輸血品項與適應症之敘述，下列何者錯誤？",opts:["A.血小板濃厚液適用於治療血小板減少症","B.2單位紅血球濃厚液適用於提高成年人血色素約1～1.2 gm/dL","C.全血適用於過敏性休克病人","D.新鮮冷凍血漿適用於發生瀰漫性血管內凝血之病人"],ans:[2],expl:"全血主要適用於大量失血（如創傷性休克）需同時補充紅血球與血漿容積的情況，並非適用於過敏性休克（anaphylactic shock，屬於過敏反應導致的血管擴張與微血管通透性增加，非單純失血），此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。血小板濃厚液用於血小板減少症（A✓）；每2單位濃厚紅血球約可提升成人血色素1～1.2 gm/dL（B✓）；新鮮冷凍血漿補充凝血因子，適用於瀰漫性血管內凝血（DIC）病人（D✓）。"},{n:150,no:50,subj:"其他",q:"有關登革熱的敘述，下列何者正確？",opts:["A.臉部出現不痛不癢的紅斑","B.病毒從呼吸道檢體分離是確診的主要依據","C.為第三類法定傳染病","D.馬鞍狀發燒，發燒3天後體溫下降1～2天後，又再度發燒"],ans:[3],expl:"登革熱典型的發燒型態為「馬鞍狀發燒（saddleback fever）」：發燒數日後體溫短暫下降1～2天，之後又再度發燒，為本題正確敘述（D✓）。登革熱依台灣傳染病防治法歸類為「第二類」法定傳染病，並非第三類（C✗）；確診主要依賴血清學檢驗、NS1抗原或PCR等實驗室方法，並非呼吸道檢體病毒分離（B✗）；臉部潮紅（flushing）而非無痛無癢紅斑是較典型描述，此選項精確度不足（A✗）。"},{n:151,no:1,subj:"神經系統",q:"下列診斷檢查敘述何者錯誤？",opts:["A.腰椎穿刺將針頭插入L3～L4之蜘蛛膜下腔","B.腰椎穿刺後需要臥床休息，加強水分攝取","C.腦波檢查前病人需要洗頭並且不可以擦髮油","D.經股動脈進行腦血管攝影後，可立即下床活動，避免下肢血栓形成"],ans:[3],expl:"經股動脈進行腦血管攝影後，穿刺部位須加壓並臥床制動數小時（依各院規範通常4～6小時以上），以防止穿刺處出血或血腫，並非可立即下床活動，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。腰椎穿刺確實是插入L3～L4蜘蛛膜下腔（A✓）；術後臥床休息並加強水分攝取以預防脊髓液滲漏引起的頭痛（B✓）；腦波檢查前需洗頭、不擦髮油以確保電極貼附與訊號品質（C✓）。"},{n:152,no:2,subj:"神經系統",q:"有關重症肌無力病人發生膽鹼激性危象之敘述，下列何者錯誤？",opts:["A.因Mestinon使用過量而失去阻斷作用","B.病人會出現視力模糊、瞳孔收縮","C.病人會出現血壓上升、心搏過速","D.病人會出現支氣管分泌增加、腹部疼痛和腹瀉"],ans:[2],expl:"膽鹼激性危象是因抗膽鹼酯酶藥物（如Mestinon）使用過量，導致乙醯膽鹼堆積、副交感神經過度興奮，臨床上會出現心搏「過緩」、血壓「下降」等副交感效應，而非血壓上升、心搏過速（後者較符合交感興奮或肌無力危象的表現），此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。過量藥物確實會使原本要阻斷乙醯膽鹼酯酶的作用失去意義（A✓）；瞳孔收縮、視力模糊（B✓）與支氣管分泌增加、腹痛腹瀉（D✓）皆是典型副交感過度興奮（SLUDGE症候群）的表現。"},{n:153,no:3,subj:"消化系統",q:"墨菲氏徵象（Murphy's sign）陽性是下列何種疾病的常見特徵？",opts:["A.急性腸胃炎","B.急性闌尾炎","C.急性胰臟炎","D.急性膽囊炎"],ans:[3],expl:"墨菲氏徵象（Murphy's sign）是觸診右上腹膽囊區時，病人因疼痛而突然停止吸氣，是急性膽囊炎的經典理學檢查發現（D✓，本題答案）。急性腸胃炎、闌尾炎（典型為McBurney's point壓痛）、胰臟炎（典型為上腹痛輻射至背部）皆各有其特徵性表現，非墨菲氏徵象所對應之疾病。"},{n:154,no:4,subj:"神經系統",q:"有關癲癇病人的敘述，下列何者錯誤？",opts:["A.phenytoin（Dilantin®）血清治療濃度為10～20 mcg/mL","B.女性癲癇病人仍能與一般女性一樣懷孕","C.在臺灣，癲癇病人不能考取駕照","D.發作時，若病人意識不清，不需試圖喚醒病人"],ans:[2],expl:"依台灣現行規範，經診斷之癲癇病人若經治療後有一定期間（如規範中要求的無發作期間）並經醫師評估病情穩定，仍可申請或保有駕照，並非一律禁止考取駕照，此敘述過於絕對而錯誤，為本題答案（C✗，題目問「何者錯誤」）。phenytoin治療濃度10～20mcg/mL為臨床標準值（A✓）；癲癇本身不影響懷孕能力，孕期需在醫師調整下持續穩定用藥（B✓）；發作時意識不清不應強行喚醒，以免病人躁動受傷（D✓）。"},{n:155,no:5,subj:"神經系統",q:"缺血性腦中風使用血栓溶解劑（rt-PA）治療的敘述，下列何者錯誤？①可以重新打通阻塞血管 ②有動脈瘤或動靜脈畸形者不適用 ③必須在中風8小時內使用 ④嚴重肝病病人不適用",opts:["A.④","B.③","C.②","D.①"],ans:[1],expl:"rt-PA血栓溶解治療黃金時間為中風後3小時內（部分指引可延長至4.5小時），並非8小時內，此敘述時間窗過長而錯誤，為本題答案（B✗，即③，題目問「何者錯誤」）。rt-PA確實可重新打通阻塞血管（①正確）；有動脈瘤或動靜脈畸形者因出血風險增加而不適用（②正確）；嚴重肝病病人因凝血功能異常、出血風險高而不適用（④正確）。"},{n:156,no:6,subj:"消化系統",q:"有關維持口腔黏膜完整性的原則，下列敘述何者錯誤？",opts:["A.張口呼吸病人可以用濕紗布覆蓋口腔","B.接受放射線治療引起唾液減少或口乾，若無禁忌，每日建議進食水分2000～3000 mL","C.鼓勵病人由口進食，咀嚼運動有助於唾液分泌","D.使用2%的lidocaine（Xylocaine®）來清潔厚舌苔"],ans:[3],expl:"2% lidocaine是局部麻醉劑，主要用於緩解疼痛或麻醉黏膜，並非用來「清潔」厚舌苔的方式；清潔厚舌苔應以生理食鹽水或口腔清潔液配合牙刷、紗布等機械性清潔，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。張口呼吸者以濕紗布覆蓋口腔可減少黏膜乾燥（A✓）；放療引起口乾者若無禁忌應鼓勵攝取2000～3000mL水分（B✓）；鼓勵由口進食、咀嚼有助刺激唾液分泌（C✓）。"},{n:157,no:7,subj:"消化系統",q:"有關痔瘡切除手術病人術後之護理措施，下列何者適當？",opts:["A.給予冰水坐浴可以減輕傷口腫脹與疼痛","B.應定時監測病人的解尿型態","C.初期建議攝取高纖維飲食以利排便","D.避免採取側臥或俯臥的姿勢"],ans:[1],expl:"痔瘡切除術後應定時監測病人解尿型態，因肛門部位疼痛、水腫或麻醉效應可能影響排尿功能，甚至導致尿滯留，需密切觀察（B✓，本題答案）。術後應採「溫水」坐浴而非冰水坐浴以促進局部血循、減輕疼痛（A✗）；術後初期為避免刺激傷口，通常先採清流質漸進飲食，非立即高纖飲食（C✗）；應鼓勵側臥或俯臥以減輕肛門部位壓迫與疼痛，而非避免（D✗）。"},{n:158,no:8,subj:"消化系統",q:"接受經肝動脈化學栓塞術病人的敘述，下列何者正確？",opts:["A.術前不需要禁食","B.門靜脈阻塞者為其適應症","C.術後需定期監測肝臟功能","D.術後鼓勵立即翻身活動"],ans:[2],expl:"經肝動脈化學栓塞術（TACE）後應定期監測肝臟功能，評估治療反應與潛在肝損傷（C✓，本題答案）。術前需禁食以降低栓塞術中嘔吐、吸入的風險（A✗）；門靜脈阻塞者因肝臟血流仰賴門靜脈代償供應，栓塞肝動脈可能導致嚴重肝缺血，屬「禁忌症」而非適應症（B✗）；術後穿刺處（通常經股動脈）須加壓臥床制動，非鼓勵立即翻身活動（D✗）。"},{n:159,no:9,subj:"內分泌系統",q:"有關副甲狀腺功能亢進之敘述，下列何者正確？",opts:["A.要鼓勵病人多攝取奶類製品","B.病人會有多尿、尿比重下降、腎結石等臨床表徵","C.要限制每日水分攝取量在1500c.c.以下","D.病人會有高血磷"],ans:[1],expl:"副甲狀腺功能亢進因副甲狀腺素（PTH）過多促進骨鈣釋出及腎小管重吸收鈣，導致高血鈣，進而使腎臟濃縮能力下降、產生多尿、尿比重下降，且因尿鈣增加易形成腎結石（B✓，本題答案）。應限制而非鼓勵攝取含鈣量高的奶製品（A✗）；應鼓勵「多喝水」（而非限水在1500c.c.以下）以增加尿量稀釋尿鈣、預防結石形成（C✗）；PTH促進腎臟排磷，故病人呈現「低血磷」而非高血磷（D✗）。"},{n:160,no:10,subj:"消化系統",q:"有關急性胰臟炎的敘述，下列何者正確？①常見的原因是膽道疾病及飲酒過量 ②血清澱粉酶及血鈣的數值過高 ③會出現下腹巨痛或疼痛輻射至右肩 ④急性期後，仍需採低脂飲食",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"急性胰臟炎最常見的兩大病因是膽道疾病（如膽結石）及酗酒（①✓）；急性期後仍應採低脂飲食以減少胰臟分泌負擔、避免復發（④✓），選①④＝B（本題答案）。急性胰臟炎典型是血鈣「過低」（因脂肪皂化消耗鈣）而非過高（②錯誤）；典型疼痛是「上腹部」劇痛並輻射至「背部」，而非下腹痛輻射右肩（③錯誤）。"},{n:161,no:11,subj:"骨骼肌肉",q:"60歲女性病人主訴清晨會出現左側膝關節僵硬，熱敷後僵硬可以改善，且上下樓梯時關節會有輾軋音。下列何者為病人最可能的疾病診斷？",opts:["A.骨質疏鬆症","B.退化性關節炎","C.類風濕性關節炎","D.痛風性關節炎"],ans:[1],expl:"退化性關節炎好發於承重關節（如膝關節），典型表現為晨僵時間短（通常<30分鐘）、活動或熱敷後可改善，且因軟骨磨損使關節面粗糙，活動時可摸到或聽到摩擦音（輾軋音，crepitus），與本題描述最相符（B✓，本題答案）。骨質疏鬆症通常無明顯關節僵硬與摩擦音症狀；類風濕性關節炎晨僵時間較長（常>1小時）且好發兩側對稱小關節；痛風性關節炎多為急性劇痛紅腫發作，非慢性晨僵摩擦音表現。"},{n:162,no:12,subj:"骨骼肌肉",q:"承上題，有關此類病人的護理措施，下列何者最適宜？",opts:["A.鼓勵進行等張運動，如騎腳踏車或游泳","B.觀察服用Plaquenil緩解關節炎的成效","C.教導避免嘌呤含量高的食物，如內臟類、肉汁","D.鼓勵做負重運動，如散步、跑步"],ans:[0],expl:"退化性關節炎建議進行低衝擊、等張性的運動如游泳、騎腳踏車，可在不增加關節負重磨損的前提下維持關節活動度與肌力（A✓，本題答案）。Plaquenil（奎寧類藥物）是類風濕性關節炎或紅斑性狼瘡的治療用藥，非用於退化性關節炎（B✗）；限制高普林飲食是痛風性關節炎的飲食指導，非退化性關節炎（C✗）；退化性關節炎應避免跑步等高衝擊負重運動，以免加速關節軟骨磨損（D✗）。"},{n:163,no:13,subj:"感官系統",q:"下列何者會出現眼睛痛的症狀？",opts:["A.老年性白內障","B.青光眼","C.老花眼","D.黃斑變性"],ans:[1],expl:"急性隅角閉鎖性青光眼因眼壓在短時間內急遽上升，會引起劇烈眼睛疼痛，並可能合併頭痛、噁心嘔吐、視力模糊、看燈光有虹暈等症狀，是眼科急症（B✓，本題答案）。老年性白內障、老花眼、黃斑部退化通常以漸進性視力模糊或退化為主要表現，一般不會有明顯眼睛疼痛。"},{n:164,no:14,subj:"其他",q:"有關後天免疫缺乏症候群（AIDS）之敘述，下列何者錯誤？",opts:["A.輔助性T細胞與毒殺性T細胞的比值上升","B.當病人CD4＜200 cells/μL時，易出現「伺機性感染」","C.病人最常出現的續發性惡性腫瘤為卡波西氏肉瘤","D.反轉錄酶抑制劑zidovudine（AZT）適用於預防母體垂直感染"],ans:[0],expl:"AIDS因輔助性T細胞（CD4+）被HIV病毒破壞而數量減少，導致CD4/CD8（輔助性T細胞／毒殺性T細胞）比值「下降」，這是AIDS重要的免疫學特徵，並非上升，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。CD4<200 cells/μL是伺機性感染風險大增的臨床分界點（B✓）；卡波西氏肉瘤是愛滋病人最常見的續發性惡性腫瘤（C✓）；zidovudine（AZT）可用於降低母嬰垂直傳染風險（D✓）。"},{n:165,no:15,subj:"內分泌系統",q:"下列檢查結果，何者可診斷為糖尿病？",opts:["A.禁食8小時空腹血漿葡萄糖（fasting plasma glucose, FPG）110 mg/dL","B.口服葡萄糖耐量試驗（OGTT）第2小時血漿葡萄糖159 mg/dL","C.糖化血紅素（HbA1c）7%","D.隨意抽血一次血漿葡萄糖240 mg/dL"],ans:[2],expl:"依糖尿病診斷標準，糖化血紅素（HbA1c）≥6.5%即符合糖尿病診斷條件，本題7%已達標準，可據以診斷（C✓，本題答案）。空腹血糖診斷標準為≥126mg/dL，本題110mg/dL未達標準（屬糖尿病前期，空腹血糖偏高IFG）（A✗）；OGTT第2小時血糖診斷標準為≥200mg/dL，本題159mg/dL未達（屬葡萄糖耐受不良IGT）（B✗）；隨機血糖需≥200mg/dL「並合併典型高血糖症狀」才能據以診斷，題目未提供症狀資訊，故單獨此數值不足以直接診斷（D✗）。"},{n:166,no:16,subj:"心臟血管",q:"有關肥厚型心肌病變之病因，下列何者最正確？",opts:["A.主動脈狹窄","B.心肌炎","C.澱粉樣病變","D.酒精中毒"],ans:[0],expl:"在題目所列選項中，主動脈狹窄造成心臟長期壓力負荷過重，可導致左心室代償性肥厚，與肥厚型心肌病變的病理機轉（心肌異常肥厚）較為相關，為本題最適選項（A✓，本題答案）。心肌炎、酒精中毒較常與擴張型心肌病變相關；澱粉樣病變則較常引起限制型心肌病變，而非肥厚型的病因。"},{n:167,no:17,subj:"心臟血管",q:"一位74歲男性，因胸痛數次到醫院檢查，檢驗報告LDH1/LDH2＞1；CK-MB 460 U/L；Troponin I 15.0 ng/mL；K+ 3.0 mEq/dL，有關其檢驗報告的判讀，下列何者正確？",opts:["A.LDH1/LDH2＞1表示無心肌細胞受損","B.Troponin I 15.0 ng/mL表示心肌細胞受損","C.CK-MB在正常範圍表示心肌細胞未受損","D.有高血鉀，會因心肌再極化時間延長導致心律不整"],ans:[1],expl:"Troponin I是心肌損傷高度專一性的生物標記，本題數值15.0 ng/mL遠高於正常參考值（通常<0.04 ng/mL），明確代表心肌細胞受損（B✓，本題答案）。LDH1/LDH2＞1（俗稱flipped LDH ratio）反而是心肌梗塞的陽性指標，並非代表「無」心肌受損（A✗）；CK-MB 460 U/L已明顯超出正常範圍，並非「正常範圍」（C✗）；本題K+ 3.0 mEq/dL屬於低血鉀（正常3.5～5.0），而非高血鉀，且低血鉀才會延長心肌複極化時間、增加心律不整風險（D✗）。"},{n:168,no:18,subj:"心臟血管",q:"有關高血壓的敘述，下列何者正確？",opts:["A.90%以上的高血壓屬於續發性高血壓","B.抽菸、喝酒、高膽固醇飲食是導致續發性高血壓的原因","C.惡性高血壓的收縮壓在130 mmHg以上，是一種內科急症","D.高血壓控制不佳常導致腦、眼睛、心、腎臟等器官的合併症"],ans:[3],expl:"高血壓長期控制不佳是腦中風、視網膜病變、冠心病、心衰竭、慢性腎臟病等標的器官損傷的重要危險因子，此為高血壓最核心的臨床意義（D✓，本題答案）。約90～95%的高血壓屬於「原發性（本態性）」高血壓，續發性高血壓僅占少數，敘述相反（A✗）；抽菸、喝酒、高膽固醇飲食是原發性高血壓的危險因子，續發性高血壓通常指有明確病因（如腎臟病、內分泌疾病）者（B✗）；惡性高血壓通常指血壓極高（如收縮壓遠高於180mmHg）合併急性器官損傷，收縮壓130mmHg不足以構成惡性高血壓的定義（C✗）。"},{n:169,no:19,subj:"心臟血管",q:"評估靜脈曲張之靜脈瓣功能的檢查，下列何者正確？①逆流型充盈試驗（retrograde filling test） ②艾倫測驗（Allen's test） ③霍曼氏徵象（Homan sign） ④手壓測驗（manual compression test）",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"逆流型充盈試驗與手壓測驗皆是評估靜脈曲張、靜脈瓣膜是否閉鎖不全的檢查方法，選①④＝B（本題答案）。艾倫測驗（Allen's test）是評估「橈動脈與尺動脈」側枝循環是否通暢的檢查，與靜脈瓣膜功能無關（②）；霍曼氏徵象（Homan's sign）是評估「深部靜脈栓塞（DVT）」的臨床徵象，並非靜脈瓣膜功能檢查（③）。"},{n:170,no:20,subj:"心臟血管",q:"有關機械性人工心瓣膜特性之敘述，下列何者正確？",opts:["A.僅需要接受短期之抗凝血藥物治療","B.金屬材質耐用性較高","C.比較不容易形成血栓","D.適合有出血傾向病人使用"],ans:[1],expl:"機械性人工心瓣膜多以金屬或合成材料製成，其優點是耐用性較高、可使用較久（B✓，本題答案）。機械瓣膜因表面易誘發血栓形成，病人需「終身」服用抗凝血藥物，並非僅短期治療（A✗）；相較於生物瓣膜，機械瓣膜「更容易」形成血栓，並非比較不容易（C✗）；正因需終身抗凝治療，機械瓣膜並不適合有出血傾向的病人，此類病人臨床上通常會考慮選用生物瓣膜（D✗）。"},{n:171,no:21,subj:"腫瘤血液",q:"有關化學藥品vincristine（Oncovin®）輸注之藥物準備過程，下列何者不適當？",opts:["A.穿戴護目鏡、手套、口罩、防水長隔離衣","B.核對化學藥品上之藥物標籤","C.於垂直型層流操作櫃抽取藥物","D.抽藥後之空針、管路等丟棄於感染性垃圾桶"],ans:[3],expl:"化學治療藥物屬於危害性藥物，使用後之空針、管路等廢棄物須丟棄於專用的細胞毒性（化療）廢棄物容器，以進行特殊處理，並非丟入一般感染性垃圾桶，此作法不適當，為本題答案（D✗，題目問「何者不適當」）。穿戴完整防護裝備（護目鏡、手套、口罩、防水隔離衣）（A✓）、用藥前核對藥物標籤（B✓）、於垂直層流操作櫃（生物安全櫃）內抽取藥物以避免藥物微粒飄散（C✓）皆為正確的化療調配防護原則。"},{n:172,no:22,subj:"腫瘤血液",q:"一位正在接受胸壁放射治療的復發性乳癌病人表示：「吞嚥時感到疼痛，胸口有灼熱及緊繃感」。下列何者是病人因放射線治療導致最可能的結果？",opts:["A.肺炎","B.食道裂孔疝氣","C.胃炎","D.食道炎"],ans:[3],expl:"胸壁放射治療的照射範圍可能波及食道，導致放射性食道炎，表現為吞嚥疼痛、胸口灼熱與緊繃感，與本題病人主訴最相符（D✓，本題答案）。肺炎、食道裂孔疝氣、胃炎雖也可能有相關症狀，但與「胸壁放療＋吞嚥疼痛合併胸口灼熱緊繃」的臨床情境較不吻合，食道炎是放射線治療累及食道最直接相關的併發症。"},{n:173,no:23,subj:"泌尿系統",q:"有關體液容積過量之檢驗結果，下列敘述何者正確？①血比容下降 ②血尿素氮下降 ③血漿滲透壓上升 ④血鈉上升",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[0],expl:"體液容積過量時，體內水分相對過多產生稀釋效應：血比容（Hct）因血液被稀釋而下降（①✓）；血液尿素氮（BUN）因血液稀釋加上腎絲球血流增加而數值下降（②✓），選①②＝A（本題答案）。血漿滲透壓因水分過多被稀釋而應「下降」，並非上升（③錯誤）；血鈉因稀釋效應應呈現「稀釋性低血鈉」而下降，並非上升（④錯誤）。"},{n:174,no:24,subj:"腫瘤血液",q:"林小姐，45歲，近三個月反覆發燒入院，診斷急性骨髓性白血病（AML），為了判定化學治療或骨髓移植的治療效果，進行骨髓抽吸術，下列敘述何者正確？①術中不用麻醉 ②骨髓抽吸僅檢查白血球的數目、大小 ③可於後腸骨嵴處抽取 ④術後需使用砂袋加壓",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[3],expl:"後腸骨嵴（posterior iliac crest）是臨床上最常見、風險相對較低的骨髓抽吸部位（③✓）；抽吸術後局部需加壓止血，可使用砂袋加壓（④✓），選③④＝D（本題答案）。骨髓穿刺抽吸術需先進行局部麻醉，並非不需麻醉（①錯誤）；骨髓抽吸检体可评估各类血球生成情形、细胞型态与比例等全面造血功能，並非僅檢查白血球的數目與大小（②錯誤）。"},{n:175,no:25,subj:"骨骼肌肉",q:"有關腔隙症候群（compartment syndrome）的臨床表徵，下列何者正確？①患肢有緊縮感 ②患肢脈搏減弱 ③止痛藥物能緩解疼痛 ④患肢比健肢冰冷",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[1],expl:"腔隙症候群因肌肉腔室內壓力上升壓迫血管神經，典型表現包括患肢緊縮感（①✓）、動脈灌流受阻致脈搏減弱（②✓）、以及血循障礙導致患肢比健肢冰冷（④✓），選①②④＝B（本題答案）。腔隙症候群最具特徵性的疼痛是劇烈且「一般止痛藥物無法緩解」，若疼痛能被緩解則不符合典型表現，此項（③）敘述錯誤。"},{n:176,no:26,subj:"腫瘤血液",q:"相較於何杰金氏病，有關非何杰金氏淋巴瘤之敘述，下列何者錯誤？",opts:["A.常侵犯周邊多個淋巴結","B.多呈現瀰漫性散布","C.常出現發燒、夜間盜汗及體重減輕","D.經常侵犯骨髓"],ans:[2],expl:"發燒、夜間盜汗及體重減輕（B症狀）是何杰金氏病與非何杰金氏淋巴瘤「兩者皆可能出現」的共同表現，並非能用來區辨兩者差異的特徵性描述，作為「相較於何杰金氏病」的敘述並不恰當，為本題答案（C✗，題目問「何者錯誤」）。相對而言，非何杰金氏淋巴瘤確實較常侵犯周邊多個淋巴結（A✓）、呈現瀰漫性散布模式（B✓）、且較常侵犯骨髓（D✓），這些才是相對於何杰金氏病（多為單一淋巴結區域性、連續性擴散、較少侵犯骨髓）的鑑別特徵。"},{n:177,no:27,subj:"其他",q:"有關燒傷病人輔助使用高壓氧治療之作用，下列何者最適宜？",opts:["A.提升病人的意識程度","B.活化組織促進上皮細胞生長","C.促進皮膚毛髮生長","D.改善病人憂鬱狀態"],ans:[1],expl:"高壓氧治療可提高組織含氧濃度，活化纖維母細胞與上皮細胞的生長增殖，進而促進燒傷傷口的癒合，是輔助治療燒傷的重要作用機轉（B✓，本題答案）。高壓氧治療並非用於提升意識程度、促進毛髮生長或改善憂鬱狀態，這些皆非其主要臨床應用目的。"},{n:178,no:28,subj:"其他",q:"有關燒傷病人初期的血液檢查結果，下列何者正確？",opts:["A.血紅素降低和血比容升高","B.血紅素升高和血比容升高","C.血紅素升高和血比容下降","D.血紅素下降和血比容下降"],ans:[0,1,2,3],expl:"官方公告本題「一律給分」，故四個選項皆視為正確答案。此題爭議點推測與燒傷初期血液濃縮機轉的描述角度有關：燒傷初期因血漿大量滲出至組織間隙，血管內液體容積減少，血液呈現「濃縮」現象，理論上血紅素與血比容會因濃縮效應而「相對上升」；但若從紅血球實際遭燒傷破壞流失的角度來看，數值判讀可能出現不同解讀方向，此命題角度的模糊性可能正是官方最終認定爭議、一律給分的原因，故不再提供單一標準答案。"},{n:179,no:29,subj:"腫瘤血液",q:"有關免疫球蛋白特性之敘述，下列何者正確？",opts:["A.IgD含量最多，能透過母乳提供新生兒免疫保護能力","B.IgA可以預防呼吸道及腸胃道感染","C.IgE會影響B細胞的分化","D.IgM是免疫反應中最後出現的抗體"],ans:[1],expl:"IgA主要存在於黏膜表面分泌物（如唾液、淚液、呼吸道與腸胃道分泌物）及母乳中，可提供黏膜局部免疫防護，有助預防呼吸道及腸胃道感染（B✓，本題答案）。血中含量最多的免疫球蛋白是IgG而非IgD，且透過母乳提供新生兒保護的主要是IgA而非IgD（A✗）；IgE主要與過敏反應及肥大細胞活化相關，並非影響B細胞分化（C✗）；IgM是免疫反應中「最先」出現的抗體（初次免疫反應的指標），並非最後出現，次發免疫反應中則以IgG為主且效價較持久（D✗）。"},{n:180,no:30,subj:"骨骼肌肉",q:"有關類風濕性關節炎臨床表徵之敘述，下列何者錯誤？①症狀通常兩側對稱性地發生 ②活動後有僵硬的現象 ③通常侵犯大關節 ④可能造成腕隧道症候群",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[2],expl:"類風濕性關節炎典型好發於「小關節」（如手指、腕關節等），並非大關節，此為本題錯誤敘述之一；此外，RA的僵硬特徵是「晨間或休息後」明顯，活動後通常會逐漸改善而非持續僵硬，②的敘述方向亦有誤，選②③＝C（本題答案）。症狀兩側對稱性發生是RA典型特徵（①正確）；滑膜增生可能壓迫正中神經造成腕隧道症候群，是RA可能的併發症（④正確）。"},{n:181,no:31,subj:"骨骼肌肉",q:"全身性紅斑性狼瘡屬於下列那一型之過敏反應？",opts:["A.第I型立即性","B.第II型細胞毒性","C.第III型免疫複合物","D.第IV型延遲型"],ans:[2],expl:"全身性紅斑性狼瘡（SLE）是典型的第III型過敏反應（免疫複合物型），因抗原抗體複合物沉積於腎絲球、血管壁等處引發發炎反應，狼瘡腎炎即是此機轉的典型表現（C✓，本題答案）。第I型（立即性，如過敏性休克）、第II型（細胞毒性，如自體免疫溶血性貧血）、第IV型（延遲型，如接觸性皮膚炎）皆與SLE的主要致病機轉不符。"},{n:182,no:32,subj:"腫瘤血液",q:"王先生診斷肺癌接受放射線治療時，出現皮膚乾燥、發癢和脫皮情形，下列護理措施何者最適當？",opts:["A.熱敷以促進該區域的血液循環","B.用清水清潔該區域，以避免組織損傷","C.使用含香精乳液減緩乾燥及發癢情形","D.使用去角質劑去除死細胞，以減少對該區域的刺激"],ans:[1],expl:"放射線皮膚反應（乾燥、發癢、脫皮）的照護原則是以清水溫和清潔患部，避免額外刺激造成組織損傷（B✓，本題答案）。應避免熱敷，以免增加局部血流及皮膚刺激而加重反應（A✗）；應避免使用含香精等添加物的乳液，以免刺激敏感脆弱的皮膚（C✗）；應避免使用去角質劑等摩擦性處理，以防進一步破壞已受損的皮膚屏障（D✗）。"},{n:183,no:33,subj:"呼吸系統",q:"有關病人的動脈血液氣體分析結果，下列何者應立即報告醫師？",opts:["A.pH 7.34，PaO2 82 mmHg，PaCO2 40 mmHg，SaO2 97%","B.pH 7.35，PaO2 85 mmHg，PaCO2 45 mmHg，SaO2 95%","C.pH 7.46，PaO2 90 mmHg，PaCO2 32 mmHg，SaO2 98%","D.pH 7.31，PaO2 91 mmHg，PaCO2 50 mmHg，SaO2 96%"],ans:[3],expl:"正常動脈血液氣體分析參考範圍約為：pH 7.35～7.45、PaCO2 35～45mmHg、PaO2 80～100mmHg、SaO2 95～100%。本題選項中僅D的pH 7.31明顯低於正常範圍（酸血症），合併PaCO2 50mmHg明顯升高（呼吸性酸中毒表現），屬於明顯異常、需立即報告醫師的結果（D✓，本題答案）。A、B、C的數值皆落在正常範圍或臨界正常範圍內，臨床意義相對輕微。"},{n:184,no:34,subj:"呼吸系統",q:"有關胸腔穿刺放液術檢查前之護理措施，下列何者最適當？",opts:["A.建立靜脈管路，檢查前給予Atropine","B.坐在床緣且頭、手趴在床旁桌上","C.移除眼鏡、假牙、隱形眼鏡","D.禁食4～6小時"],ans:[1],expl:"胸腔穿刺放液術（thoracentesis）典型體位是讓病人坐於床緣，身體微前傾，雙手前臂交叉置於床旁桌上支撐身體，同時暴露背部穿刺處，此姿勢有助於肋間隙撐開、利於穿刺操作（B✓，本題答案）。此為局部麻醉的床邊處置，通常不需常規給予Atropine或建立靜脈管路（A✗）、不需移除眼鏡假牙隱形眼鏡（此為全身麻醉手術的準備，C✗）、也不需嚴格禁食4～6小時（D✗）。"},{n:185,no:35,subj:"呼吸系統",q:"有關肺結核病人的出院護理指導，下列何者正確？",opts:["A.必須完成整個療程才可以停藥","B.開始使用抗結核病藥，就可以參加朋友的聚會","C.必須服用藥物直到症狀改善或消失才停藥","D.每三個月必須做一次結核菌皮膚試驗"],ans:[0],expl:"肺結核治療必須完成整個規定療程（通常需持續6個月以上，依處方而定），即使症狀已改善也不可提前停藥，以免治療失敗、復發或誘發抗藥性結核菌，此為結核病治療最核心的衛教原則（A✓，本題答案）。開始服藥後仍需持續一段時間規律服藥（通常至少2週以上）待痰液塗片轉陰、傳染力顯著降低後，才建議恢復正常社交聚會，並非「一開始用藥」就可以（B✗）；服藥應遵循醫囑完成整個療程，而非僅憑症狀改善或消失便自行停藥，此說法與正確治療原則相牴觸（C✗）；結核菌皮膚試驗（PPD）是用於「診斷」是否曾感染結核菌的工具，並非已確診病人常規每三個月追蹤的方式（D✗）。"},{n:186,no:36,subj:"呼吸系統",q:"朱先生為慢性阻塞性肺病（COPD）病人，使用氧氣鼻套管2L／分鐘，主訴呼吸喘，朱太太要求護理師將氧氣流量調高。下列何者為最適當的反應？",opts:["A.「朱先生的病本來就容易喘，妳太緊張了，應離開休息一下」","B.「我立刻將朱先生的氧氣換成非再呼吸性氧氣面罩，並調整氧氣為100%」","C.「我了解您的感受，但高濃度的氧氣反而會抑制朱先生的呼吸，而讓他呼吸更困難」","D.「讓朱先生平躺休息半小時後就會改善了」"],ans:[2],expl:"COPD病人長期處於慢性缺氧狀態，其呼吸驅動力主要依賴「低血氧」刺激（缺氧驅動理論），若突然給予高濃度氧氣，可能抑制此呼吸驅動力，反而導致呼吸更加抑制、二氧化碳蓄積惡化，此為COPD病人給氧衛教的重要核心概念；先同理家屬感受再說明此生理機轉，是最適當的溝通與護理反應（C✓，本題答案）。A忽視家屬感受的關心而顯得不恰當；B直接將氧氣調高至100%對COPD病人可能造成呼吸抑制，屬不適當處置；D單純平躺休息並未針對呼吸喘的根本疑慮做出回應或處置。"},{n:187,no:37,subj:"呼吸系統",q:"下列何者最適合用於肺結核病人之診斷檢查？",opts:["A.肺功能測試","B.痰液耐酸菌染色抹片","C.胸部X光","D.痰液革蘭氏染色"],ans:[1],expl:"痰液耐酸菌染色抹片（AFB smear）可直接鏡檢找到結核桿菌，是診斷肺結核最直接、關鍵的檢查方法之一（B✓，本題答案）。胸部X光可提示肺部異常病灶，但屬於輔助性影像診斷，仍需病原學檢查確診（C✗，非最適合）；肺功能測試評估的是肺部通氣功能，非用於診斷結核病（A✗）；結核桿菌屬於分枝桿菌，須以「耐酸性」染色法（非一般細菌適用的革蘭氏染色）才能正確檢出，故痰液革蘭氏染色不適用（D✗）。"},{n:188,no:38,subj:"泌尿系統",q:"有關腹膜透析治療之敘述，下列何者正確？",opts:["A.透析過程易有噁心、嘔吐、低血壓不平衡症候群","B.持續脫水影響血壓變化波動易造成心臟負擔較大","C.觀察透析液為清澈無色","D.心臟功能不佳或腦血管疾病病人不合適選用"],ans:[2],expl:"腹膜透析液正常應觀察為清澈無色，若出現混濁則需高度懷疑腹膜炎等感染併發症，此為腹膜透析重要的居家自我監測指標（C✓，本題答案）。「透析不平衡症候群」（噁心、嘔吐、低血壓等）主要是「血液透析」因短時間內快速移除溶質所致的併發症，並非腹膜透析的典型特徵（A✗）；相較於血液透析，腹膜透析屬於緩慢連續性移除水分與溶質，血液動力學相對穩定，對心臟負擔「較小」而非較大（B✗）；也正因血液動力學較穩定，腹膜透析實際上更適合心臟功能不佳或部分腦血管疾病病人選用，而非不合適（D✗）。"},{n:189,no:39,subj:"泌尿系統",q:"有關體外震波碎石術之敘述，下列何者錯誤？",opts:["A.一般適用於腎臟及輸尿管上段結石的病人","B.術後鼓勵病人多攝取液體，以利碎石排出","C.使用抗凝血劑或是有出血傾向的人均適用","D.術後有嚴重發燒或是嚴重血尿的人應速回診"],ans:[2],expl:"使用抗凝血劑或有出血傾向的病人，屬於體外震波碎石術的「禁忌症」，因震波可能造成腎臟等組織出血，並非皆可適用，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。此術式一般適用於腎臟及輸尿管上段結石（A✓）；術後鼓勵多攝取液體以利碎石排出體外（B✓）；術後若出現嚴重發燒或血尿應儘速回診評估是否有感染或出血等併發症（D✓）。"},{n:190,no:40,subj:"泌尿系統",q:"有關良性前列腺肥大之症狀與導因，下列何者正確？",opts:["A.頻尿和夜尿等膀胱儲存症狀，為增生最早出現的現象","B.長期尿道阻力降低造成逼尿肌代償，產生膀胱憩室","C.增生壓迫尿道造成內括約肌鬆弛，引起尿流速變慢","D.膀胱出口阻塞導致膀胱反覆感染，造成膀胱壁增厚"],ans:[0],expl:"頻尿、夜尿等膀胱儲存期症狀（storage symptoms）常是良性攝護腺肥大最早出現的臨床表現之一（A✓，本題答案）。實際病理機轉是攝護腺增生造成尿道阻力「增加」（而非降低），使逼尿肌代償性肥厚以克服阻力，長期下可能形成膀胱憩室，B敘述中「尿道阻力降低」方向有誤；攝護腺增生主要造成尿道「機械性狹窄」，而非「內括約肌鬆弛」導致尿流速變慢，C的機轉描述不夠精確；長期膀胱出口阻塞主要造成逼尿肌代償性肥厚增厚，膀胱壁增厚並非單純由「反覆感染」所致，D的因果機轉描述亦不夠精確。"},{n:191,no:41,subj:"泌尿系統",q:"有關腎臟癌的臨床表徵，下列何者錯誤？",opts:["A.常見間歇無痛性血尿","B.晚期會同時出現血尿、後腰疼痛與腹部腫塊","C.造成腎功能變差，導致紅血球生成素不足","D.刺激副甲狀腺素增加，導致高血鈣"],ans:[2],expl:"腎細胞癌常見的副腫瘤症候群之一，是腫瘤細胞異常分泌「過多」紅血球生成素（EPO），導致病人出現紅血球增多症，而非因腎功能變差、EPO不足而貧血，此為腎癌重要的鑑別特徵，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。間歇性無痛性血尿是腎癌的經典表現之一（A✓）；晚期可能同時出現血尿、腰痛與腹部腫塊三大典型症狀（B✓）；腎癌亦可能分泌類PTH物質，造成副腫瘤性高血鈣（D✓）。"},{n:192,no:42,subj:"內分泌系統",q:"有關愛迪生危機的特徵，下列何者正確？",opts:["A.高血鉀","B.高血壓","C.高血糖","D.高血鈉"],ans:[0],expl:"愛迪生氏危象（急性腎上腺皮質功能不足）因醛固酮與皮質醇分泌嚴重不足，腎臟排鉀能力下降，導致高血鉀，是其重要的臨床特徵之一（A✓，本題答案）。因醛固酮不足使腎臟保鈉排鉀，病人反而呈現「低血鈉」而非高血鈉（與D相反）；因缺乏礦物皮質素的保鈉、維持血容積作用，病人會出現「低血壓」而非高血壓（與B相反）；因皮質醇不足影響糖質新生，病人易出現「低血糖」而非高血糖（與C相反）。"},{n:193,no:43,subj:"內分泌系統",q:"有關尿崩症病人的出院護理指導，下列何者錯誤？",opts:["A.教導避免食用會利尿的飲料與食物","B.教導使用desmopressin（DDAVP）鼻噴霧劑時勿憋氣，並須確認藥劑確實有吸入肺部","C.教導病人睡前少喝水，減少夜晚環境上的刺激","D.教導病人用藥的方式、劑量、時間及副作用，並定期返院追蹤"],ans:[1],expl:"鼻噴劑型desmopressin是經由「鼻黏膜」吸收發揮療效，並非吸入「肺部」；使用時應正常呼吸、避免用力吸氣或憋氣，以免藥液被吸入喉嚨或肺部而降低鼻黏膜吸收效果，此敘述在給藥原則與生理機轉上有誤，為本題答案（B✗，題目問「何者錯誤」）。避免攝取具利尿作用的飲料食物以減少額外水分流失（A✓）；睡前少喝水以減少夜間頻尿造成的睡眠干擾（C✓）；完整衛教用藥方式劑量時間副作用並定期追蹤（D✓）皆為正確之出院指導原則。"},{n:194,no:44,subj:"內分泌系統",q:"有關糖尿病病人足部護理的指導，下列何者正確？①每日以溫水清洗足部前須以手背測試水溫，以防燙傷 ②修剪趾甲應剪短於足趾末端，以防甲溝炎 ③平日於足部與足趾間及腳跟龜裂處，塗抹保養乳液，以免皮膚過於乾燥 ④不可擅自用手或剪刀，將足部硬繭或雞眼剝除",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"以手背測試水溫較手掌敏感，可有效防止燙傷（①✓）；足部硬繭或雞眼不可自行用手或剪刀處理，以免造成傷口、增加感染風險，應由專業人員處理（④✓），選①④＝B（本題答案）。趾甲應修剪至與足趾末端「齊平」，避免剪得過短低於足趾末端，以降低嵌甲、甲溝炎風險，此描述有誤（②錯誤）；足趾間屬潮濕部位，不應塗抹乳液（易滋生黴菌感染），乳液應塗抹於足部乾燥處而避開趾縫，此敘述容易誤導致趾間潮濕反而增加感染風險（③錯誤）。"},{n:195,no:45,subj:"內分泌系統",q:"有關庫欣氏症候群（Cushing's syndrome）的臨床表徵，下列何者正確？",opts:["A.低血鉀性鹼中毒","B.皮膚變厚成水牛肩","C.體毛及鬢毛減少","D.葡萄糖新生減少"],ans:[0],expl:"庫欣氏症候群因皮質醇過高，其類醛固酮作用會促進腎臟排鉀，導致低血鉀，並合併代謝性鹼中毒，此為庫欣氏症候群認可的臨床特徵之一（A✓，本題答案）。皮質醇會分解蛋白質、抑制膠原蛋白合成，導致皮膚「變薄」易生紫紋與瘀傷，而非變厚，僅「水牛肩」的脂肪重新分布特徵正確，但「皮膚變厚」的描述有誤（B✗）；因腎上腺雄性素分泌增加，病人體毛及鬢毛通常「增加」（多毛），並非減少（C✗）；皮質醇會「促進」糖質新生（故可能誘發類固醇糖尿病、血糖上升），並非使其減少（D✗）。"},{n:196,no:46,subj:"內分泌系統",q:"有關腦下垂體中風之臨床表徵，下列何者錯誤？",opts:["A.荷爾蒙失調","B.頭痛、脖子僵硬","C.畏光、視力受損","D.肢體半側偏癱"],ans:[3],expl:"腦下垂體中風（pituitary apoplexy）是腦垂體腫瘤內出血或梗塞引起的急症，典型表現包括急性劇烈頭痛、頸部僵硬、視力障礙、畏光及荷爾蒙分泌失調等；「肢體半側偏癱」則是大腦中風（cerebral stroke）的典型局灶性神經學表現，並非腦下垂體中風的特徵性表現，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。荷爾蒙失調（A✓）、頭痛合併脖子僵硬（B✓）、畏光與視力受損（C✓）皆是腦下垂體中風的常見臨床表徵。"},{n:197,no:47,subj:"其他",q:"有關敗血性休克導致的系統性炎性反應症候群（SIRS）其診斷的四個條件中，需含二項或以上，下列條件何者正確？①體溫大於38℃或小於36℃ ②心跳小於60次／分 ③呼吸速率大於20次／分，或PaCO2小於40 mmHg ④白血球大於12000/uL或小於4000/uL",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"SIRS診斷四項條件中，體溫大於38℃或小於36℃（①✓）與白血球大於12000/uL或小於4000/uL（④✓）皆為正確的診斷條件之一，選①④＝B（本題答案）。SIRS的心跳條件標準應為「大於90次/分」（心搏過速），而非小於60次/分（心搏過緩），方向相反（②錯誤）；呼吸速率條件除大於20次/分外，通常搭配PaCO2「小於32mmHg」作為判斷標準（部分文獻版本），本題所述PaCO2小於40mmHg之數值閾值與標準不符（③錯誤）。"},{n:198,no:48,subj:"呼吸系統",q:"李先生用餐時，突然發生激烈咳嗽及呼吸困難，並伴有「咻」、「咻」喘氣聲，下列何者最為可能？",opts:["A.呼吸道梗塞","B.心肌梗塞","C.主動脈剝離","D.肺栓塞"],ans:[0],expl:"用餐時突發劇烈咳嗽、呼吸困難並伴隨「咻咻」喘鳴聲，情境高度提示因食物哽塞造成呼吸道異物梗塞，是最需優先考慮的診斷（A✓，本題答案）。心肌梗塞、主動脈剝離、肺栓塞雖也可能突發呼吸困難，但通常不會在「用餐當下」因嗆咳誘發，且喘鳴聲（stridor樣）更提示上呼吸道機械性阻塞而非心血管事件。"},{n:199,no:49,subj:"骨骼肌肉",q:"下列何者不是骨折病人應該要密切觀察6P的徵象或症狀？",opts:["A.腫脹","B.蒼白","C.疼痛","D.麻痺"],ans:[0],expl:"骨折病人需密切觀察的「6P」徵象為：疼痛（Pain）、蒼白（Pallor）、感覺異常（Paresthesia）、麻痺（Paralysis）、脈搏消失（Pulselessness）及冰冷（Poikilothermia/Polar），「腫脹」雖是骨折常見表現，但並不屬於標準6P徵象清單之一，為本題答案（A✓，題目問「何者不是6P」）。蒼白、疼痛、麻痺皆屬於6P徵象範疇。"},{n:200,no:50,subj:"其他",q:"有關各類型休克其病理機轉是因血管擴張引起分布性（distributive）或稱血管性（vasogenic）休克，下列何者正確？①敗血性 ②低血容積性 ③過敏性 ④神經性 ⑤心因性",opts:["A.①②③","B.①③④","C.②④⑤","D.③④⑤"],ans:[1],expl:"分布性（血管性）休克的核心機轉是全身血管異常擴張，導致有效循環血量相對不足：敗血性休克因發炎介質引起血管擴張（①✓）；過敏性休克因組織胺等介質釋放導致血管擴張（③✓）；神經性休克因自主神經調控失衡（如脊髓損傷）致血管張力喪失（④✓），選①③④＝B（本題答案）。低血容積性休克的機轉是體液或血液「實際流失」而非血管擴張，屬於低容積性休克（②錯誤）；心因性休克的機轉是心臟幫浦功能衰竭，非血管擴張所致，屬於心因性休克（⑤錯誤）。"},{n:201,no:1,subj:"神經系統",q:"腦瘤病人接受放射線治療，下列敘述何者正確？①臨床上常用I125經由立體定位手術直接植入腫瘤進行治療 ②可以在手術後立即合併使用放射線治療，以促進治療效果 ③手術後通常以單次大劑量放射線治療為主 ④可以與化學療法合併使用，適用於惡性腦瘤和轉移癌之治療",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[0,1,2,3],expl:"官方公告本題「一律給分」，四個選項皆視為正確答案。依考選部更正前之原始答案為B（①④）：①臨床上確實會使用I-125等放射性同位素以立體定位手術方式直接植入腫瘤內進行近接治療（brachytherapy），常用於復發性膠質瘤等特定腦瘤；④放射線治療與化學療法合併使用，適用於惡性腦瘤及轉移癌之治療，是標準治療模式。本題爭議可能在於①「常用」一詞是否恰當——此技術屬於較特殊、非first-line的治療方式，並非「常用」手段，此描述精確度可能引發爭議，故官方最終認定本題有瑕疵、一律給分。②手術後放射線治療通常需等待傷口癒合後才開始，並非「立即」合併使用；③手術後放射線治療多採分次、小劑量方式進行，並非「單次大劑量」為主（單次大劑量屬於立體定位放射手術SRS的範疇，非一般術後常規）。"},{n:202,no:2,subj:"神經系統",q:"有關顱底骨骨折病人有耳漏、鼻漏的評估與及處置，下列敘述何者錯誤？",opts:["A.用面紙吸取滴下的耳漏、鼻漏液體會有光暈徵象","B.教導不可用力咳嗽及打噴嚏","C.指導臥床休息以利腦膜貼附癒合","D.以無菌原則抽吸病人鼻孔內液體"],ans:[3],expl:"以無菌原則抽吸病人鼻孔內液體是不恰當的處置——顱底骨骨折併腦脊髓液鼻漏時，應避免任何侵入性抽吸或填塞動作，以防將外界細菌經由破損的腦膜屏障帶入顱內造成腦膜炎，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。腦脊髓液滲漏時以紗布或面紙輕觸會出現外圍清澈液暈的「光暈徵象（halo sign）」，可作為初步床邊判斷（A✓）；應避免用力咳嗽、打噴嚏等增加顱內壓的動作，以減少腦脊髓液持續滲漏及氣顱風險（B✓）；臥床休息有助於減少腦脊髓液壓力波動，利於腦膜自行貼合癒合（C✓）。"},{n:203,no:3,subj:"神經系統",q:"有關癲癇重積狀態（status epilepticus）的敘述，下列何者錯誤？",opts:["A.發生時，依醫囑立即予靜脈輸入短效抗癲癇藥","B.小發作或局部發作不會出現癲癇重積狀態","C.病人一次發作時間超過5分鐘","D.可能發生意識在兩次發作間沒有完全恢復"],ans:[1],expl:"小發作（petit mal absence seizure）或局部發作（partial seizure）雖較大發作少見，但仍可能演變為癲癇重積狀態，並非絕對不會發生，此敘述過於絕對而錯誤，為本題答案（B✗，題目問「何者錯誤」）。癲癇重積狀態屬於神經科急症，發生時須依醫囑立即給予短效抗癲癇藥物（如Diazepam）以終止發作（A✓）；傳統定義上單次發作時間超過5分鐘即可視為癲癇重積狀態的警訊（C✓）；癲癇重積狀態亦可能表現為兩次發作間意識未完全恢復的連續發作型態，而非僅限單次超長發作（D✓）。"},{n:204,no:4,subj:"神經系統",q:"當顱內出血病人發生顱內壓升高時，顱內開始代償顱內壓的機制，下列敘述何者正確？",opts:["A.減少腦部氧氣需求量","B.增加腦脊髓液的吸收","C.減少腦內靜脈血液回流","D.腦組織移位到枕骨大孔"],ans:[1],expl:"當顱內壓開始上升時，腦部會啟動代償機制以維持顱內容積恆定（Monro-Kellie法則），其中之一即是增加腦脊髓液的吸收（並促使部分腦脊髓液被擠壓至脊髓蛛網膜下腔），以代償性降低顱內壓（B✓，本題答案）。代償早期腦部氧氣需求量並不會主動「減少」，而顱內壓持續上升反而可能因灌流不足導致缺氧（A✗）；顱內壓升高時靜脈血液回流會「增加」以代償性排出部分血液容積，而非減少靜脈回流（C✗）；腦組織移位到枕骨大孔（枕骨大孔疝）是顱內壓失代償、病情惡化至危急階段的表現，並非早期代償機制（D✗）。"},{n:205,no:5,subj:"神經系統",q:"20歲男性，清晨騎乘重機外出不小心與大卡車擦撞滑倒顳側先著地，送醫時GCS E4V5M6，為安全起見留院觀察，2小時後病人突然喪失意識，診斷為硬膜上出血，下列敘述何者錯誤？",opts:["A.主要是靜脈血管破裂","B.常先經歷一段正常的清醒期","C.易出現顱內壓升高的症狀","D.以手術治療為主"],ans:[0],expl:"硬膜上出血（epidural hematoma）典型出血來源是腦膜中動脈（middle meningeal artery）等「動脈性」血管破裂，並非靜脈血管，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。由於是動脈性出血，血腫形成速度快，臨床上典型會先經歷一段意識清醒的「清醒期（lucid interval）」後才因血腫擴大而突然意識喪失，與本題病程描述相符（B✓）；血腫持續擴大會壓迫腦組織造成顱內壓升高（C✓）；硬膜上出血屬於神經外科急症，治療以緊急手術移除血腫、止血為主（D✓）。"},{n:206,no:6,subj:"神經系統",q:"腦中風病人有吞嚥困難的問題，由口進食的食物性狀須採漸進性改變，下列何者是最後採用的類型？",opts:["A.液體","B.半固體","C.固體","D.小塊固體"],ans:[0],expl:"腦中風病人吞嚥困難的飲食質地訓練，是依安全性由高到低漸進調整：由較濃稠、易於凝聚成團、吞嚥時較好控制的半固體開始（如布丁狀、糊狀），逐步進展到固體、小塊固體，最後才嘗試質地稀薄、流動快速、最難以在口咽期精準控制吞嚥時機的「液體」，因稀薄液體在吞嚥控制不佳時最容易嗆入呼吸道，是吞嚥復健過程中最晚才嘗試、最具挑戰性的質地，為本題答案（A✓）。這與國際吞嚥障礙飲食標準（IDDSI）中液體需先經過增稠處理、待吞嚥功能進步後才逐步調整為原味液體的臨床邏輯一致。"},{n:207,no:7,subj:"消化系統",q:"有關胃癌的敘述，下列何者正確？",opts:["A.胃淋巴癌最常見","B.好發在40歲以下的女性","C.好發在上段與食道接近之處","D.與醃漬食物攝取過多有關"],ans:[3],expl:"胃癌好發部位與飲食型態有關，長期攝取醃漬、煙燻、高鹽食物（含較多亞硝酸鹽等致癌物）已被證實與胃癌發生風險增加有關，此為本題答案（D✓）。胃癌病理型態中，腺癌占絕大多數，胃淋巴癌（MALT淋巴瘤）雖與幽門螺旋桿菌感染有關，但並非最常見型態（A✗）；胃癌好發於50歲以上中老年人，且男性多於女性，並非好發於40歲以下女性（B✗）；胃癌好發部位以胃竇、胃小彎處較常見，並非上段近食道處（近端胃癌／賁門癌雖也存在，但非「好發」部位的主流敘述）（C✗）。"},{n:208,no:8,subj:"消化系統",q:"有關全腸道外營養療法（TPN）常見的併發症，下列何者錯誤？",opts:["A.空氣栓塞","B.低血糖症","C.液體負荷過量","D.腸道纖毛增生"],ans:[3],expl:"全腸道外營養（TPN）常見併發症包括導管相關的空氣栓塞、代謝方面的血糖不穩定（高血糖較低血糖更常見，因輸入高濃度葡萄糖溶液）、以及輸液速度過快或腎心功能不佳所致的液體負荷過量，但「腸道纖毛增生」並非TPN的併發症——恰好相反，長期完全禁食、腸道不使用會導致腸黏膜絨毛「萎縮」而非增生，此為腸道廢用性萎縮（disuse atrophy）現象，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。空氣栓塞（A✓）、低血糖症（B✓，尤其驟然中斷TPN輸注時風險更高）、液體負荷過量（C✓）皆是TPN已知的常見併發症。"},{n:209,no:9,subj:"消化系統",q:"有關急性膽囊炎病人的疼痛評估與處置，下列何者正確？",opts:["A.左上腹或下腹中央疼痛，會輻射至左背部","B.觸診膽囊有壓痛，且吸氣時更嚴重","C.可注射Morphine以緩解疼痛","D.羅氏徵象Rovsing's signs（+）"],ans:[1],expl:"觸診膽囊區域出現壓痛，且病人於深吸氣時因發炎的膽囊碰觸到醫師手指而疼痛加劇、突然中止吸氣動作，即為墨菲氏徵象（Murphy's sign）陽性，是急性膽囊炎的典型身體評估發現（B✓，本題答案）。急性膽囊炎典型疼痛部位是「右上腹」，並輻射至「右肩胛骨或右背部」，並非左上腹或下腹（A✗）；因膽囊發炎屬平滑肌痙攣性疼痛，一般優先使用Meperidine等藥物，Morphine因可能引起歐迪氏括約肌（sphincter of Oddi）痙攣、加重疼痛而較少作為首選（C✗）；羅氏徵象（Rovsing's sign）是評估「急性闌尾炎」的理學檢查，並非膽囊炎的評估項目（D✗）。"},{n:210,no:10,subj:"消化系統",q:"預防全胃切除病人發生惡性貧血，可補充下列何種維生素？",opts:["A.維生素A","B.維生素B6","C.維生素B12","D.維生素K"],ans:[2],expl:"全胃切除術後病人因喪失胃壁細胞分泌的內在因子（intrinsic factor），無法在迴腸末端吸收維生素B12，長期下來會導致惡性貧血，故需終身補充維生素B12（通常以肌肉注射方式）以預防，此為本題答案（C✓）。維生素A、維生素K與內在因子缺乏、惡性貧血機轉無直接相關（A、D✗）；維生素B6雖參與造血相關代謝，但與全胃切除後惡性貧血機轉的關聯性遠不如維生素B12直接（B✗）。"},{n:211,no:11,subj:"骨骼肌肉",q:"有關骨髓炎之護理指導，下列敘述何者錯誤？",opts:["A.按時服用抗生素，不可中斷","B.手術傷口癒合前，患肢可多做全關節運動","C.接受高壓氧治療時，可做耳壓平衡動作","D.抬高患肢，以減輕疼痛"],ans:[1],expl:"骨髓炎術後傷口尚未癒合前，患肢應盡量減少會增加患部張力或活動量的全關節運動，以免影響傷口癒合、增加感染擴散風險，此敘述過於積極而錯誤，為本題答案（B✗，題目問「何者錯誤」）。骨髓炎需長期規律使用抗生素治療（常需數週至數月），不可自行中斷以免治療失敗或產生抗藥性（A✓）；接受高壓氧輔助治療時，因艙內壓力變化易造成中耳壓力不平衡，需教導病人做耳壓平衡動作（如吞嚥、打哈欠）以避免耳部不適或損傷（C✓）；抬高患肢有助於減輕局部腫脹與疼痛（D✓）。"},{n:212,no:12,subj:"骨骼肌肉",q:"有關腔隙症候群的症狀，下列敘述何者錯誤？①失去尖鈍或兩點辨識力 ②患肢末梢脈搏減弱 ③微血管充填時間大於3秒 ④皮膚上出現出血斑點",opts:["A.④","B.③","C.②","D.①"],ans:[0],expl:"腔隙症候群（compartment syndrome）典型的6P徵象中包含皮膚蒼白、冰冷等「缺血」表現，而「皮膚上出現出血斑點（瘀斑）」並非腔隙症候群的典型特徵，較常見於凝血功能異常或血管炎等其他病況，此敘述錯誤，為本題答案（A✓，即④，題目問「何者錯誤」）。失去尖鈍或兩點辨識力屬於感覺異常（paresthesia）的表現（①✓）；患肢末梢脈搏減弱反映動脈灌流受阻（②✓）；微血管充填時間延長（大於3秒）反映末梢循環灌流不足（③✓），皆是腔隙症候群公認的臨床徵象。"},{n:213,no:13,subj:"感官系統",q:"病人接受白內障囊外摘除術後之護理指導，下列何者最適當？①用力咳嗽 ②彎腰洗頭 ③預防便秘 ④避免提重物",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[3],expl:"白內障囊外摘除術後應避免任何會使眼內壓瞬間升高的動作，包括彎腰洗頭（頭部低於心臟）及提重物（增加腹壓進而影響眼壓），此二者皆須避免，選③④＝D（本題答案）。用力咳嗽（①）與彎腰洗頭（②）皆屬於應避免的動作而非建議動作，故不應與③④混選；正確應教導病人打噴嚏、咳嗽時勿用力，並採取溫和用力排便方式，而非「用力咳嗽」。"},{n:214,no:14,subj:"感官系統",q:"有關美尼爾氏症（Meniere's disease）之護理指導，下列敘述何者錯誤？",opts:["A.眩暈急性發作應立即臥床休息","B.多喝水以促進血液循環","C.維持生活規律及情緒平穩","D.使用血管擴張劑可以改善耳鳴"],ans:[1],expl:"美尼爾氏症（Meniere's disease）之病理機轉與內耳淋巴液水腫、循環障礙有關，護理指導上應限制水分及鹽分攝取以減少內淋巴液滯留，而非鼓勵多喝水促進循環，「多喝水以促進血液循環」的說法與治療原則相反，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。眩暈急性發作時應立即臥床休息、避免頭部突然轉動以減少眩暈加劇及跌倒風險（A✓）；維持規律生活作息與情緒平穩有助於減少內耳症狀發作頻率（C✓）；血管擴張劑（如Betahistine）可改善內耳微循環，臨床上確實用於減緩耳鳴及眩暈症狀（D✓）。"},{n:215,no:15,subj:"感官系統",q:"有關視網膜剝離的緊急處理，下列何者錯誤？",opts:["A.立刻臥床","B.單眼蓋上眼罩","C.勿隨意移動頭部","D.減少焦慮"],ans:[1],expl:"視網膜剝離的緊急處理應盡量減少眼球活動及頭部晃動，以避免剝離範圍擴大，通常會依剝離位置指導病人採取特定頭部姿勢，並非直接「單眼」蓋上眼罩即可，且過度限制單眼視野活動反而可能增加病人因视觉代偿不足而移動頭部的風險，此處置並非首要及最適當措施，故此敘述有誤，為本題答案（B✗，題目問「何者錯誤」）。立刻臥床休息以減少眼球活動及視網膜進一步剝離（A✓）；勿隨意移動頭部，避免视网膜剝離範圍擴大（C✓）；減少病人焦慮，避免情緒波動間接增加眼壓或不自主眼球活動（D✓）。"},{n:216,no:16,subj:"心臟血管",q:"有關感染性心內膜炎臨床表徵之敘述，下列何者錯誤？",opts:["A.發燒型態為回歸熱","B.出現心雜音","C.常發生腦栓塞","D.四肢出現羅氏斑（Roth's spots）"],ans:[3],expl:"感染性心內膜炎的發燒型態通常為持續性低度發燒或不規則發燒，並非典型的「回歸熱」型態（回歸熱型發燒較常見於瘧疾、鼠咬熱等特定感染），此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。心臟瓣膜贅生物形成會造成新出現或變化中的心雜音（B✓）；贅生物脫落可能形成栓子造成腦栓塞等全身性栓塞併發症（C✓）；四肢視網膜或皮膚出現羅氏斑（Roth's spots，視網膜出血合併中心蒼白）是感染性心內膜炎的典型周邊免疫學表現之一（D✓）。"},{n:217,no:17,subj:"心臟血管",q:"有關心包填塞之臨床表徵，下列何者錯誤？",opts:["A.動脈性低血壓","B.頸靜脈怒張","C.心包膜摩擦音增強","D.呼吸困難"],ans:[2],expl:"心包填塞因心包膜腔內積液壓迫心臟，使心臟活動受限，心包膜摩擦音反而會因大量積液將心包膜兩層分開而「減弱或消失」，並非增強，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。心包填塞使心臟舒張期充盈受限、心輸出量下降，導致動脈性低血壓（A✓）；心臟受壓迫使靜脈回流受阻，造成頸靜脈怒張（B✓）；心輸出量下降合併肺循環壓力變化，可能導致呼吸困難（D✓），三者皆為心包填塞Beck氏三徵（低血壓、頸靜脈怒張、心音遙遠）相關的公認臨床表現。"},{n:218,no:18,subj:"心臟血管",q:"有關心房纖維顫動臨床處置之敘述，下列何者正確？",opts:["A.可採頸動脈竇按摩，使心跳變慢","B.可使用去纖維震顫術，使心跳恢復規則","C.可裝設植入式自動心律轉換去顫器，改善心悸症狀","D.可服用鈉離子通道阻斷劑，降低心跳"],ans:[3],expl:"鈉離子通道阻斷劑（如propafenone等第I類抗心律不整藥物）可用於心房纖維顫動之心律控制，屬於臨床上認可的藥物治療選項之一，此為本題答案（D✓）。頸動脈竇按摩是透過刺激迷走神經以減緩房室結傳導，臨床上多用於終止「陣發性室上性心搏過速（PSVT）」等機轉，對已形成的心房顫動較無法使其「恢復規則心律」（A✗）；「去纖維震顫術」一般指電擊去顫，用於終止致命性心室顫動等心律不整，並非心房顫動的常規恢復規則心律方式（B✗，心房顫動恢復竇性心律多採用電氣心律轉換術或藥物心律轉換）；植入式自動心律轉換去顫器（ICD）主要用於預防及治療致命性心室性心律不整（VT/VF），並非用於改善心房顫動之心悸症狀（C✗）。"},{n:219,no:19,subj:"骨骼肌肉",q:"下列何者不是骨質疏鬆症之危險因素？",opts:["A.接受卵巢切除手術","B.中風癱瘓長期臥床","C.副甲狀腺機能低下","D.過度飲用咖啡"],ans:[2],expl:"副甲狀腺機能「亢進」（而非低下）因促使骨鈣釋出增加，才是骨質疏鬆症公認的危險因子；副甲狀腺機能低下反而使血鈣調節趨於低血鈣、骨鈣釋出減少，並非骨質疏鬆的危險因子，故「不是」骨質疏鬆危險因素的即為此項，為本題答案（C✓，題目問「何者不是」）。卵巢切除手術使雌激素驟降，加速骨質流失（A為危險因子）；中風癱瘓長期臥床因缺乏負重刺激，加速骨質流失（B為危險因子）；咖啡因會促進尿鈣排出、影響鈣質吸收，過量攝取為公認危險因子（D為危險因子）。"},{n:220,no:20,subj:"心臟血管",q:"有關二尖瓣狹窄之血液動力學檢查結果，下列何者錯誤？",opts:["A.中心靜脈壓上升","B.右心室壓力上升","C.肺微血管楔壓（PCWP）上升","D.心輸出量上升"],ans:[3],expl:"二尖瓣狹窄因左心房排空受阻，會使左心房後端的肺循環壓力（肺微血管楔壓）與右側心臟壓力（中心靜脈壓、右心室壓力）皆代償性上升，但流入左心室、再由左心室搏出的血流量因狹窄阻礙而「減少」，心輸出量應下降而非上升，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。中心靜脈壓上升（A✓）、右心室壓力上升（B✓）、肺微血管楔壓上升（C✓）皆是二尖瓣狹窄因血流回堵所致的典型血液動力學表現。"},{n:221,no:21,subj:"腫瘤血液",q:"有關惡性貧血的敘述，下列何者錯誤？①與自體免疫有關 ②曾接受胃切除手術者較易罹患 ③可以進行骨髓切片檢查確定診斷 ④須終生補充維生素B12",opts:["A.④","B.③","C.②","D.①"],ans:[1],expl:"惡性貧血的診斷主要依賴血清維生素B12濃度、內在因子抗體檢測等實驗室方法，骨髓切片雖可見巨球性紅血球前驅細胞等變化，但並非用來「確定診斷」惡性貧血的主要或必要檢查方式，此敘述過於絕對而錯誤，為本題答案（B✗，即③，題目問「何者錯誤」）。惡性貧血與自體免疫破壞胃壁細胞、內在因子缺乏有關（①✓）；胃切除術後因喪失內在因子分泌來源，較易罹患惡性貧血（②✓）；因內在因子缺乏無法逆轉，病人需終生補充維生素B12（④✓）。"},{n:222,no:22,subj:"腫瘤血液",q:"有關何杰金氏淋巴瘤的敘述，下列何者正確？",opts:["A.常見瀰漫不連續的淋巴結散布情形","B.好發在中老年人較常見且男性為女性的2倍","C.常見發燒、盜汗、體重減輕等症狀","D.常見骨髓侵犯"],ans:[2],expl:"何杰金氏淋巴瘤典型會出現發燒、夜間盜汗、體重減輕等「B症狀」，是重要的分期與預後判斷依據，此為本題答案（C✓）。何杰金氏淋巴瘤特徵是循單一淋巴結區域「連續性」擴散，並非瀰漫不連續散布（瀰漫不連續散布較符合非何杰金氏淋巴瘤的特徵）（A✗）；何杰金氏淋巴瘤好發年齡呈雙峰分佈（年輕成人與老年人），且男女發生率相近或男性略多，並非好發中老年人且男性為女性2倍的顯著差異描述（B✗）；骨髓侵犯在何杰金氏淋巴瘤相對少見，較常見於非何杰金氏淋巴瘤（D✗）。"},{n:223,no:23,subj:"腫瘤血液",q:"有關常見腫瘤標記的應用，下列何者正確？①癌胚抗原（CEA）可監測結腸直腸癌治療效果 ②癌抗原125（CA125）可監測胰臟癌與消化道腫瘤 ③前列腺特異抗原（PSA）為前列腺癌的偵測與治療指標 ④癌抗原15-3（CA15-3）可監測晚期或合併遠端轉移乳癌之治療反應 ⑤α-胎兒蛋白（AFP）為監測肺癌治療後的指標",opts:["A.①②⑤","B.①③④","C.②③④","D.②③⑤"],ans:[1],expl:"癌胚抗原（CEA）確實可用於監測結腸直腸癌治療後的反應與復發追蹤（①✓）；前列腺特異抗原（PSA）是前列腺癌篩檢、診斷與治療反應追蹤的重要指標（③✓）；癌抗原15-3（CA15-3）常用於監測晚期或轉移性乳癌的治療反應（④✓），選①③④＝B（本題答案）。癌抗原125（CA125）主要與「卵巢癌」相關，並非胰臟癌與消化道腫瘤的主要標記（②錯誤）；α-胎兒蛋白（AFP）主要用於監測「肝細胞癌」及生殖細胞腫瘤，並非肺癌治療後的監測指標（⑤錯誤）。"},{n:224,no:24,subj:"腫瘤血液",q:"陳小弟，15歲，剛被診斷為急性白血病，醫師給予強度較強的化學治療，有關急性白血病治療完全緩解的標準，下列何者錯誤？①骨髓內芽細胞（blast cell）＜5% ②周邊血液有芽細胞 ③無器官浸潤 ④造血細胞接近正常值",opts:["A.④","B.③","C.②","D.①"],ans:[2],expl:"急性白血病治療完全緩解的標準之一即是周邊血液中「不應再出現」芽細胞（blast cell），若周邊血液仍檢出芽細胞，代表疾病未達完全緩解，此敘述與完全緩解標準相反，故為錯誤敘述，為本題答案（C✓，即②，題目問「何者錯誤」）。骨髓內芽細胞比例小於5%（①✓）、無器官（如肝脾淋巴結）浸潤現象（③✓）、周邊血液造血細胞數值接近正常值（④✓），皆是急性白血病完全緩解公認的判定標準。"},{n:225,no:25,subj:"腫瘤血液",q:"承上題，有關陳小弟接受化學治療的護理指導，下列何者正確？",opts:["A.白血球的數目在化學治療後4週降至最低","B.血小板低於20000/mm2，使用牙刷及牙線清潔口腔","C.白血球小於1000/mm2，建議少量多餐禁食生食","D.疲倦是常見副作用之一，鼓勵陳小弟長時間平躺，勿下床活動"],ans:[2],expl:"當白血球低於1000/mm3等嚴重低下狀態時，感染風險大幅增加，護理指導應建議採取低菌飲食原則，包括少量多餐並避免生食（如生魚片、未煮熟蔬果等），以降低經口感染的機會，此為本題答案（C✓）。化學治療後白血球數目降至最低點（骨髓抑制最嚴重期）通常發生於治療後7～14天左右，並非4週（A✗）；血小板低於20000/mm3屬於出血高風險，應改用軟毛牙刷並避免使用牙線，以防牙齦出血，而非鼓勵使用牙刷牙線清潔（B✗）；疲倦雖是化療常見副作用，但應鼓勵病人在體力可負荷範圍內適度活動、保持規律作息，長時間平躺不動反而可能增加血栓、肌肉無力等併發症風險，並非適當指導（D✗）。"},{n:226,no:26,subj:"腫瘤血液",q:"有關癌症病人使用干擾素治療之敘述，下列何者正確？",opts:["A.高劑量使用時，可以增加抗體及淋巴球","B.會出現如低血壓、肺水腫、腎功能低下等嚴重副作用","C.會出現類似流行性感冒症狀","D.採靜脈、肌肉或皮內等注射方式"],ans:[2],expl:"干擾素治療常見的副作用之一是類似流行性感冒的症狀，包括發燒、寒顫、肌肉痠痛、疲倦等，是干擾素治療病人最常經歷的不適反應，此為本題答案（C✓）。高劑量使用干擾素時，因其具有免疫調節作用，可能反而抑制部分免疫細胞功能而非單純增加抗體及淋巴球（A✗）；干擾素常見副作用以類流感症狀及骨髓抑制為主，低血壓、肺水腫、腎功能低下等屬於較嚴重但非典型常見的副作用描述（B✗，此描述較符合IL-2等其他細胞激素治療的副作用型態）；干擾素主要採皮下或肌肉注射方式給藥，臨床上並不常規採靜脈注射方式（D✗）。"},{n:227,no:27,subj:"其他",q:"有關疥瘡病人的照護，下列敘述何者錯誤？",opts:["A.接觸病人時應戴手套但不需穿戴隔離衣","B.感染病人的伴侶及親近者須同時接受治療","C.病人衣物使用60oC以上熱水消毒10分鐘或烘乾機烘烤至少5分鐘","D.病人使用過的家具、物品洗清後密封靜置2星期"],ans:[0],expl:"疥瘡經由直接皮膚接觸及間接接觸污染衣物寢具而傳染，具高度傳染力，接觸病人時除戴手套外，仍應視情況穿戴隔離衣以降低接觸傳播風險，「不需穿戴隔離衣」的敘述並不恰當，此為本題答案（A✗，題目問「何者錯誤」）。因疥瘡傳染力強，感染者的親密接觸者（如同住家人、性伴侶）須同時接受治療，以避免相互感染及復發（B✓）；病人衣物寢具應以60°C以上熱水清洗消毒10分鐘，或以烘乾機高溫烘烤至少5分鐘，以確實殺死疥蟲及蟲卵（C✓）；無法清洗的物品可密封靜置至少2星期，待疥蟲離開人體宿主後自然死亡（D✓）。"},{n:228,no:28,subj:"其他",q:"40歲男性病人，入院診斷為二度燒傷，依照帕克蘭公式計算需給予12,000 c.c.液體復甦治療，在燒傷後的第一個8小時內需補充完成多少輸液？",opts:["A.3,000 c.c.","B.4,000 c.c.","C.6,000 c.c.","D.12,000 c.c."],ans:[2],expl:"帕克蘭公式（Parkland formula）計算之總輸液量，規定須於燒傷後「第一個8小時內」完成輸注「總量的一半」，其餘一半則於後續16小時內完成，本題總量12,000c.c.，故第一個8小時內需補充6,000c.c.，此為本題答案（C✓），是燒傷液體復甦治療的標準公式教學重點。"},{n:229,no:29,subj:"骨骼肌肉",q:"有關全身性紅斑性狼瘡之醫療處置之敘述，下列何者錯誤？",opts:["A.無法治癒，以降低炎症和損傷為主要治療目標","B.類固醇藥，可能使炎症反應降低","C.抗瘧疾藥，例如奎寧（Plaquenil）長期使用，需每4～6個月監測聽力變差的副作用","D.免疫抑制劑，可抑制其自體免疫反應，延緩腎損傷"],ans:[2],expl:"抗瘧疾藥物奎寧（Plaquenil, hydroxychloroquine）長期使用需監測的重要副作用是「視網膜病變（視力減退）」，須定期安排眼科檢查追蹤，而非監測聽力變差，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。全身性紅斑性狼瘡目前無法根治，治療目標以控制發炎反應、延緩器官損傷為主（A✓）；類固醇藥物可有效降低發炎反應、緩解症狀（B✓）；免疫抑制劑可抑制過度活化的自體免疫反應，延緩狼瘡腎炎等器官損傷進程（D✓）。"},{n:230,no:30,subj:"骨骼肌肉",q:"有關類風溼性關節炎醫療處置之敘述，下列何者錯誤？",opts:["A.發炎活動期，可冷敷勿按摩關節","B.Omega-3脂肪酸可改善類風溼性關節炎症狀","C.關節發生感染時應於關節內注射類固醇治療","D.抗腫瘤壞死因子藥物能讓關節紅腫熱痛在給藥後1～2週改善"],ans:[2],expl:"關節若發生「感染」時，關節內注射類固醇屬於禁忌，因類固醇會抑制局部免疫反應，可能使感染惡化擴散，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。類風濕性關節炎發炎活動期應採冷敷以減輕發炎腫脹，並避免按摩患部以免刺激發炎反應加劇（A✓）；Omega-3脂肪酸具抗發炎作用，臨床研究顯示可輔助改善類風濕性關節炎症狀（B✓）；抗腫瘤壞死因子藥物（如Etanercept等生物製劑）起效相對快速，多數病人於用藥後1～2週內可感受到關節紅腫熱痛症狀的改善（D✓）。"},{n:231,no:31,subj:"呼吸系統",q:"汪先生診斷為肺癌並接受右肺葉切除術，下列何者為其最適合的術後姿勢臥位？",opts:["A.躺向左側","B.俯臥","C.仰臥平躺","D.躺向右側"],ans:[0],expl:"肺葉切除術（非全肺切除）病人術後應臥向健側（未手術側），本題為右肺葉切除，故應臥向左側，如此可避免壓迫手術傷口與縫合處，並藉重力幫助患側殘餘肺組織及肋膜腔內液體、空氣經由胸管順利引流排出，有利於殘餘右肺葉再擴張，此為本題答案（A✓）。此原則與「全肺切除術」病人術後應臥向患側（以保護唯一保留的健側肺、避免健肺受壓）恰好相反，兩者護理原則不可混淆——臨床口訣可記為「肺葉切除勤翻身（並側臥健側），全肺切除臥患側」。俯臥（B）、仰臥平躺（C）、躺向右側／患側（D）皆非肺葉切除術後促進患側肺擴張與引流的最適姿位。"},{n:232,no:32,subj:"骨骼肌肉",q:"有關鞏皮症（進行性系統性硬化症，progressive system sclerosis）護理指導之敘述，下列何者錯誤？",opts:["A.鼓勵病人應多穿衣服、手套、襪子保暖，避免接觸冷空氣","B.教導病人每1～2小時深呼吸數次，加強肺擴張","C.餐後需立即臥床休息，減少腸胃不適","D.宜攝取高纖維食物，以防便秘"],ans:[2],expl:"鞏皮症（進行性系統性硬化症）常合併食道蠕動功能異常、下食道括約肌鬆弛，易發生胃食道逆流，若餐後立即臥床，重力因素消失反而更容易誘發或加重逆流症狀，應教導病人餐後維持「坐立或站立」姿勢一段時間，而非立即臥床休息，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。鞏皮症病人常合併雷諾氏現象（Raynaud's phenomenon），應注意肢體保暖、避免接觸冷空氣以減少血管痙攣發作（A✓）；肺纖維化是鞏皮症常見的器官侵犯表現，教導深呼吸運動有助於維持肺擴張、延緩肺功能惡化（B✓）；因腸胃蠕動功能減弱易併發便秘，應攝取高纖維飲食以促進腸道蠕動（D✓）。"},{n:233,no:33,subj:"腫瘤血液",q:"有關乳癌病人荷爾蒙治療之敘述，下列何者錯誤？",opts:["A.Letrozole（Femara）是轉移性乳癌第一線用藥，需服用2～5年","B.停經後婦女的荷爾蒙治療效果比停經前婦女好","C.雌性素受體（ER）或黃體素受體（PR）呈陽性者，治療效果較好","D.抗雌性素治療會有骨質疏鬆副作用，需定期做骨質密度檢查"],ans:[0],expl:"Letrozole（Femara）為芳香酶抑制劑，用於「早期乳癌」的輔助治療（術後預防復發）時，療程通常為5年；但用於「轉移性／晚期乳癌」的第一線治療時，是持續使用「直到疾病惡化或無法耐受」為止，並非固定服用2～5年的療程，此敘述將輔助治療的療程觀念套用在轉移性疾病治療上，並不精確，為本題答案（A✗，題目問「何者錯誤」）。芳香酶抑制劑主要透過抑制周邊組織將雄性素轉化為雌激素而發揮作用，對「停經後」婦女（卵巢已非雌激素主要來源）效果較停經前婦女更佳（B✓）；雌激素受體（ER）或黃體素受體（PR）陽性者，代表腫瘤生長對荷爾蒙較為敏感，荷爾蒙治療效果通常較好（C✓）；抗雌性素治療（尤其芳香酶抑制劑類）會抑制雌激素對骨質的保護作用，增加骨質疏鬆風險，需定期監測骨質密度（D✓）。"},{n:234,no:34,subj:"呼吸系統",q:"王先生呼吸喘，動脈血液氣體分析報告為：pH 7.20、PaCO2 61 mmHg、PaO2 62 mmHg、HCO3- 22 mEq/L，此結果判讀，下列何者正確？",opts:["A.呼吸性鹼中毒","B.代謝性酸中毒","C.代謝性鹼中毒","D.呼吸性酸中毒"],ans:[3],expl:"pH 7.20顯示酸血症，PaCO2 61mmHg明顯高於正常值（35～45mmHg），顯示體內二氧化碳蓄積是主要致酸原因；HCO3- 22mEq/L落於正常範圍（22～26mEq/L）邊緣，顯示腎臟尚未有明顯代謝性代償，符合急性呼吸性酸中毒的典型表現，此為本題答案（D✓），是動脈血液氣體分析判讀的基礎題型。"},{n:235,no:35,subj:"呼吸系統",q:"下列何者不是肺氣腫病人的身體評估結果？",opts:["A.聽診發現呼吸音減弱","B.視診可發現胸廓前後徑增加似桶狀胸","C.叩診出現濁音","D.觸診出現觸覺震顫減弱"],ans:[2],expl:"肺氣腫因肺泡過度充氣、含氣量增加，叩診應呈現「過度反響音（hyperresonance）」，而非濁音（濁音多見於肺部實質化、肋膜積液等含氣量減少的情形），故「叩診出現濁音」並非肺氣腫的身體評估結果，此為本題答案（C✓，題目問「何者不是」）。肺泡彈性回縮力下降、氣體滯留使呼吸音減弱（A為典型發現）；長期肺部過度充氣使胸廓前後徑增加，呈現桶狀胸外觀（B為典型發現）；肺部含氣量增加使觸覺震顫傳導減弱（D為典型發現），皆是肺氣腫的公認理學檢查表現。"},{n:236,no:36,subj:"呼吸系統",q:"有關急性呼吸窘迫症候群（ARDS）病人使用機械性通氣時，配合使用呼氣末端正壓（PEEP）之目的，下列何者錯誤？",opts:["A.減少分流程度","B.減少肺泡塌陷","C.改善血管的通透性","D.改善氧合狀態"],ans:[2],expl:"呼氣末端正壓（PEEP）主要透過增加肺泡內壓力，幫助原本塌陷的肺泡重新張開（肺泡復張）、減少肺內分流、改善換氣血流比，進而改善氧合狀態，但PEEP並「不能直接改善」造成ARDS病理基礎的肺微血管通透性增加問題（此為發炎反應所致的病理變化，需針對病因治療），此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。PEEP可減少肺內分流程度（A✓）、減少肺泡塌陷（B✓）、改善氧合狀態（D✓），皆是PEEP在ARDS呼吸器治療上的公認目的。"},{n:237,no:37,subj:"泌尿系統",q:"有關良性前列腺肥大症狀與導因之敘述，下列何者正確？",opts:["A.增生後期代償現象會出現頻尿、夜尿等症狀","B.膀胱出口阻塞導致反覆感染，造成膀胱壁增厚","C.逼尿肌長期壓力上升，產生膀胱內假性憩室","D.尿道受壓造成內括約肌鬆弛，故尿流速變慢"],ans:[2],expl:"良性前列腺肥大因增生組織壓迫尿道，逼尿肌需長期用力收縮以克服阻力排尿，久而久之逼尿肌代償性肥厚，其肌纖維束間形成的小囊袋狀構造即為膀胱內假性憩室，此為本題答案（C✓）。頻尿、夜尿等膀胱儲存期症狀通常是增生「早期」即可能出現的表現，並非後期代償現象才出現（A✗，此描述與典型病程不符）；膀胱壁增厚主要是逼尿肌長期代償性肥厚所致的結構性改變，而非直接由「反覆感染」造成，因果機轉描述不精確（B✗）；攝護腺增生主要造成尿道「機械性狹窄」，而非造成尿道內括約肌「鬆弛」，機轉方向描述有誤（D✗）。"},{n:238,no:38,subj:"骨骼肌肉",q:"有關全髖關節置換術術後病人之陳述，下列何者顯示需要進一步的護理指導？",opts:["A.「當我要彎腰穿鞋襪時，會使用長柄輔助物或請他人協助」","B.「我會在雙腿中間夾兩個枕頭協助翻身及翻向健側」","C.「我在坐時髖關節屈曲不可大於90度」","D.「這個關節行置換手術且併用骨泥，需要1星期後才能下床活動」"],ans:[3],expl:"全髖關節置換術若有併用骨泥（骨水泥）固定假體，通常可提供即刻的機械穩定性，臨床上多鼓勵病人在術後隔日或數日內即可開始下床部分負重活動，而非需等待長達1星期後才能下床，此陳述顯示病人對術後活動時程有錯誤認知，需要進一步的護理指導以澄清，為本題答案（D✓，題目問「何者顯示需要進一步指導」）。彎腰穿鞋襪時使用長柄輔助器具或請他人協助，可避免髖關節過度屈曲造成脫臼（A為正確認知）；雙腿間夾枕頭並翻向健側可避免患肢內收造成髖關節脫位（B為正確認知）；坐姿時髖關節屈曲角度不超過90度，是預防後外側入路人工髖關節脫位的重要原則（C為正確認知）。"},{n:239,no:39,subj:"泌尿系統",q:"有關尿失禁照護之敘述，下列何者正確？①凱格爾式運動可改善壓力性尿失禁 ②定時導尿法可改善滿溢性尿失禁 ③長期導尿管留置可改善急迫性尿失禁 ④膀胱訓練可改善完全性尿失禁",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[0],expl:"凱格爾式運動（骨盆底肌訓練）可強化尿道括約肌與骨盆底肌力量，是壓力性尿失禁的標準保守治療（①✓）；定時導尿法可規律排空滯留於膀胱內的餘尿，改善因膀胱收縮無力、尿液滿溢而滲漏的滿溢性尿失禁（②✓），選①②＝A（本題答案）。急迫性尿失禁的處置應以膀胱訓練、抗膽鹼藥物為主，長期導尿管留置反而增加泌尿道感染風險，並非改善急迫性尿失禁的方法（③錯誤）；完全性尿失禁多因尿道括約肌完全喪失功能（如嚴重神經損傷、廔管）所致，膀胱訓練成效有限，並非適用方法（④錯誤）。"},{n:240,no:40,subj:"泌尿系統",q:"王先生，85歲，因排尿燒灼感、疼痛且出現膿尿、血尿至急診求治，生命徵象正常，有關其進一步之評估與檢查，下列何者錯誤？",opts:["A.年紀大可能前列腺肥大而出現排尿問題，需進行肛門指診檢查","B.需協助收集尿液常規與細菌培養，以確認病因、菌種與用藥方向","C.體溫正常即可排除感染，可能年紀大飲水不足而導致尿液性狀改變","D.尿液細菌培養若每毫升含有105個以上菌落，可確認是泌尿道感染"],ans:[2],expl:"高齡病人因免疫反應較遲鈍，即使存在泌尿道感染，發燒反應可能不明顯或缺乏典型發燒表現，不能僅因體溫正常就排除感染的可能性，本題病人已有燒灼感、疼痛、膿尿、血尿等明確感染徵象，若僅因體溫正常就歸因於飲水不足而忽略感染評估，恐延誤診斷與治療，此敘述錯誤且具有臨床風險，為本題答案（C✗，題目問「何者錯誤」）。高齡男性出現排尿問題應考慮攝護腺肥大可能，肛門指診是常規評估項目之一（A✓）；尿液常規檢查與細菌培養可確認致病菌種並指引抗生素治療方向（B✓）；尿液細菌培養菌落數達每毫升105（10萬）以上，是臨床診斷泌尿道感染的重要判斷標準之一（D✓）。"},{n:241,no:41,subj:"泌尿系統",q:"同時會出現在腎病症候群與急性腎絲球腎炎之臨床表徵，下列何者正確？①水腫 ②高血脂 ③蛋白尿 ④血尿",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[0],expl:"水腫與蛋白尿是腎病症候群與急性腎絲球腎炎「共同」會出現的臨床表徵：腎病症候群因大量蛋白尿導致血漿滲透壓下降而水腫；急性腎絲球腎炎則因腎絲球發炎、腎絲球過濾率下降、水鈉滯留而水腫，兩者皆有蛋白尿與水腫的表現，選①③＝A（本題答案）。高血脂是腎病症候群因肝臟代償性增加脂蛋白合成所致的「特徵性」表現，並非急性腎絲球腎炎的典型共同表徵（②較特異於腎病症候群）；血尿（尤其肉眼血尿、茶色尿）是急性腎絲球腎炎更具特徵性的表現，並非腎病症候群的主要典型特徵（④較特異於腎絲球腎炎）。"},{n:242,no:42,subj:"內分泌系統",q:"有關腎上腺皮質功能低下症之敘述，下列何者錯誤？",opts:["A.原發性腎上腺皮質功能不全常因腎上腺皮質慢性破壞所致","B.通常在至少有10%的腎上腺皮質組織被破壞後，即會出現明顯症狀","C.原發性腎上腺皮質功能不全病人常因促黑色細胞素（MSH）的過多分泌而使皮膚變深","D.下視丘分泌的促腎上腺皮質素釋放因子（CRF）不足亦會導致腎上腺皮質功能低下"],ans:[1],expl:"腎上腺皮質功能低下的臨床症狀通常要等到絕大部分（一般教科書所述約90%以上）的腎上腺皮質組織遭破壞、皮質醇分泌儲備能力嚴重不足後，才會出現明顯症狀，並非僅10%破壞即會出現明顯症狀，此敘述低估了實際所需的破壞程度，為本題答案（B✗，題目問「何者錯誤」）。原發性腎上腺皮質功能不全（Addison氏病）多因自體免疫或感染等原因造成腎上腺皮質慢性進行性破壞所致（A✓）；因皮質醇不足，負回饋機制使腦下垂體代償性分泌過多促腎上腺皮質素（ACTH），其共同前驅物促黑色細胞素（MSH）亦隨之增加，導致皮膚色素沉澱變深，是原發性病灶的特徵性表現（C✓）；下視丘CRF分泌不足屬於續發性（中樞性）腎上腺皮質功能低下的成因之一（D✓）。"},{n:243,no:43,subj:"內分泌系統",q:"下列何者是與糖尿病小血管病變有關的慢性合併症？①足部神經麻木 ②糖尿病腎病變 ③心肌梗塞 ④腦血管梗塞",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[0],expl:"糖尿病小血管病變（微血管病變）主要影響視網膜、腎臟及周邊神經，故足部神經病變（周邊神經病變導致麻木）與糖尿病腎病變皆屬微血管病變相關的慢性合併症，選①②＝A（本題答案）。心肌梗塞與腦血管梗塞（腦中風）是動脈粥狀硬化所致的「大血管病變（巨血管病變）」合併症，並非小血管病變的範疇（③④錯誤）。"},{n:244,no:44,subj:"內分泌系統",q:"有關尿崩症臨床表徵之敘述，下列何者錯誤？",opts:["A.多尿","B.煩渴","C.尿比重降低","D.體液容積過剩"],ans:[3],expl:"尿崩症因抗利尿激素（ADH）分泌或作用不足，腎臟無法正常保留水分，導致大量水分經尿液流失，臨床表現為體液容積「缺乏」（脫水傾向），而非體液容積過剩，此敘述與病理機轉相反，為本題答案（D✗，題目問「何者錯誤」）。ADH不足使腎小管對水分再吸收能力下降，產生大量稀釋性多尿（A✓）；大量水分流失刺激口渴中樞，出現顯著煩渴、多飲以代償（B✓）；因尿液過度稀釋，尿比重明顯降低（常低於1.005）（C✓）。"},{n:245,no:45,subj:"內分泌系統",q:"有關胰島素的使用，下列何者錯誤？",opts:["A.準備胰島素前30分鐘，將胰島素自冰箱取出，避免注射冷的胰島素","B.抽取混濁型的胰島素應先將藥瓶置於手掌中滾動，不可搖晃藥瓶，避免產生氣泡","C.胰島素推入皮下後需靜待3～5秒再拔出針頭，且以藥棉輕壓，切勿搓揉","D.皮下注射胰島素的吸收速率，上臂＞大腿＞臀部＞腹部"],ans:[3],expl:"胰島素皮下注射的吸收速率因各部位皮下血流供應不同而有差異，一般公認由快至慢依序為：腹部＞上臂＞大腿＞臀部，本題選項描述的順序「上臂＞大腿＞臀部＞腹部」將吸收最快的腹部誤置於順序末端，順序有誤，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。胰島素若剛從冰箱取出直接注射，因溫度過低可能造成局部刺激不適，故建議提前約30分鐘取出回溫至室溫再注射（A✓）；混濁型（如NPH）胰島素含有懸浮微粒，應以雙手掌心滾動藥瓶使其均勻混合，避免劇烈搖晃產生氣泡影響劑量準確性（B✓）；注射後應静待3～5秒再拔針，並以棉球輕壓（不搓揉）注射部位，以減少藥液滲漏及避免局部瘀傷（C✓）。"},{n:246,no:46,subj:"內分泌系統",q:"下列何者是副甲狀腺功能亢進的臨床表徵？",opts:["A.骨痛、便秘","B.少尿、尿比重上升","C.胃泌素分泌減少，引起萎縮性胃炎","D.鈣沉積在眼睛組織形成凸眼症"],ans:[0],expl:"副甲狀腺功能亢進因副甲狀腺素（PTH）過多，促使蝕骨作用增加、骨鈣大量釋出，可造成骨質疏鬆、骨痛，同時高血鈣會減緩腸胃蠕動導致便秘，此為本題答案（A✓）。高血鈣會使腎臟濃縮尿液能力下降，臨床表現為「多尿」而非少尿，且因尿鈣增加，腎結石風險上升而非尿比重上升（B✗）；高血鈣實際上可能「刺激」胃泌素分泌增加、促進胃酸分泌，與消化性潰瘍風險上升有關，並非胃泌素分泌減少（C✗）；凸眼症（眼球突出）是格雷夫氏病（Graves' disease，一種甲狀腺機能「亢進」）的典型表現，與副甲狀腺功能亢進、血鈣調節無直接相關（D✗）。"},{n:247,no:47,subj:"其他",q:"當一人施行心肺復甦術（CPR）時，下列何者應先施行2分鐘的急救後再求救？",opts:["A.心臟衰竭呼吸停止","B.急性腦中風昏迷","C.成人野溪溺水","D.糖尿病酮酸中毒昏迷"],ans:[2],expl:"成人於野外溪流溺水獲救後，其心跳呼吸停止多屬「原發性缺氧」所致（先缺氧才心跳停止），且常發生於人煙罕至的野外環境，現場施救者若第一時間離開病人去求救，反而會延誤最關鍵的缺氧急救時機，故國際急救準則建議應「先施行約2分鐘心肺復甦術後再離開求救（叫叫CABD／Phone Fast原則的例外情境）」，此為本題答案（C✓）。心臟衰竭導致的呼吸停止多屬原發性心因性驟停，建議應立即先求救、啟動緊急醫療系統以盡快取得電擊去顫器（A非本題情境）；急性腦中風昏迷、糖尿病酮酸中毒昏迷雖屬內科急症，但其急救處置原則多建議優先求救以啟動後續醫療處置，並非2分鐘CPR後才求救的優先情境（B、D非本題情境）。"},{n:248,no:48,subj:"心臟血管",q:"有關心因性休克的敘述，下列何者正確？",opts:["A.主要是感染或血管通透性改變造成","B.常見於外傷造成主動脈剝離、張力性氣胸","C.因創傷出血過多造成心臟回血量減少","D.主動脈內氣球幫浦（IABP）是重要治療方式之一"],ans:[3],expl:"心因性休克是因心臟幫浦功能衰竭（如大範圍心肌梗塞）導致心輸出量不足，主動脈內氣球幫浦（IABP）可在舒張期充氣、收縮期放氣，減少心臟後負荷並增加冠狀動脈灌流，是心因性休克重要的機械性輔助治療方式之一，此為本題答案（D✓）。感染或血管通透性改變是敗血性休克（屬於分佈性休克）的機轉，並非心因性休克（A✗）；外傷造成主動脈剝離、張力性氣胸屬於「阻塞性休克」的常見病因，並非心因性休克（B✗）；創傷出血過多導致心臟回血量（前負荷）減少，屬於「低血容積性休克」的機轉，並非心因性休克（心因性休克是幫浦本身衰竭問題，而非血量不足）（C✗）。"},{n:249,no:49,subj:"其他",q:"當意識不清病人被送至急診，檢查瞳孔兩側等大且小於2.0 mm，可能為下列何者中毒？①有機磷 ②安非他命 ③鴉片 ④古柯鹼",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[1],expl:"有機磷中毒因抑制乙醯膽鹼酯酶，造成膽鹼激性過度興奮，典型表現包含瞳孔「縮小（miosis）」等SLUDGE症候群（①✓）；鴉片類（如嗎啡、海洛因）藥物中毒典型表現亦包含瞳孔顯著縮小的「針尖狀瞳孔」（③✓），選①③＝B（本題答案）。安非他命為中樞神經興奮劑，中毒時典型表現是瞳孔「放大（散瞳）」而非縮小（②錯誤）；古柯鹼同屬中樞神經興奮劑，中毒時同樣會造成瞳孔放大（④錯誤）。"},{n:250,no:50,subj:"其他",q:"有關臘腸桿菌（Clostridium botulinum）中毒的預防、症狀與治療之敘述，下列何者正確？",opts:["A.食物可在攝氏100度下加熱10分鐘以破壞臘腸桿菌","B.中毒後首先出現神經方面症狀，如視力模糊、瞳孔放大、吞嚥困難等症狀","C.目前無有效的抗毒素與抗生素治療","D.臘腸桿菌於真空包裝食品中無法存活"],ans:[0],expl:"臘腸桿菌（Clostridium botulinum）所產生的肉毒桿菌「毒素」性質不耐熱，食物經攝氏100度加熱10分鐘的條件（高於官方衛教所述最低破壞門檻攝氏80度、10分鐘），即足以有效破壞毒素活性，是預防肉毒桿菌毒素中毒的重要食品安全原則，此為本題答案（A✓）。中毒後常先出現明顯疲倦、全身無力等非特異性症狀，其後才逐漸出現視力模糊、眼瞼下垂、吞嚥困難等神經性症狀，並非「首先」即出現神經症狀，且此病之瞳孔變化是因副交感神經受阻而呈現「放大」，此描述雖部分正確但「首先」二字與實際病程不符，精確度不足（B✗）；肉毒桿菌中毒目前確有抗毒素（肉毒抗毒素）可供治療使用，並非「無有效抗毒素」，此敘述錯誤（C✗）；臘腸桿菌屬於「厭氧菌」，在缺氧的真空包裝環境中反而更容易存活及產生毒素，並非無法存活，此敘述與菌種特性相反（D✗）。"},{n:251,no:1,subj:"神經系統",q:"有關多發性硬化症之診斷檢查，下列何者錯誤？",opts:["A.腦脊髓液分析可發現IgG抗體上升","B.視覺誘發電位可觀察到受損的神經在傳導過程出現延遲和中斷","C.超音波檢查可發現中樞神經系統髓鞘脫失","D.核磁共振影像可用來確認多發性硬化症之斑塊"],ans:[2],expl:"多發性硬化症是中樞神經系統髓鞘脫失病變，其病灶偵測與確認以核磁共振影像（MRI）最具敏感性與特異性，並非超音波檢查——超音波無法穿透顱骨清楚呈現腦部與脊髓內部的髓鞘病灶，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。腦脊髓液分析常見寡株帶（oligoclonal bands）及IgG指數上升，反映鞘內免疫球蛋白合成增加（A✓）；視覺誘發電位可偵測到視神經傳導延遲，是常見的輔助診斷工具（B✓）；MRI可直接顯示白質內多發性脫髓鞘斑塊，是診斷多發性硬化症最重要的影像工具（D✓）。"},{n:252,no:2,subj:"神經系統",q:"下列何者不是腦幹中風的常見之表徵？",opts:["A.眼球活動不協調","B.運動功能障礙","C.手顫抖","D.嘔吐反射減弱"],ans:[2],expl:"手部顫抖較常見於小腦病變或錐體外系統疾病（如巴金森氏症），並非腦幹中風的典型常見表徵，此為本題答案（C✓，題目問「何者不是」）。腦幹含有多對腦神經核，中風時常影響動眼神經相關核團造成眼球活動不協調（A為常見表徵）；腦幹是運動傳導路徑的必經之處，中風常導致運動功能障礙（B為常見表徵）；腦幹亦含有嘔吐中樞相關路徑，受損時可能出現嘔吐反射減弱（D為常見表徵）。"},{n:253,no:3,subj:"神經系統",q:"有關頭部外傷病人顱內壓升高的處置，下列何者錯誤？",opts:["A.急性期可裝置顱內壓監測器，依醫囑引流腦脊髓液降低顱內壓","B.病人的格拉斯哥昏迷量表（GCS）總分為5分，表示病人處於昏迷狀態","C.使用Mannitol降腦壓時，使用前後要注意血糖的變化","D.若病人的瞳孔突然放大、對光沒有反應或是固定、肌力及意識下降，有可能是顱內壓升高"],ans:[2],expl:"格拉斯哥昏迷量表（GCS）總分範圍為3～15分，總分5分屬於「重度」意識障礙（≦8分即定義為昏迷），雖然嚴重但「總分5分」本身的描述並無錯誤（此為正確的量表判讀方式），此選項在臨床判讀邏輯上並無錯誤之處；然而本題答案為C，關鍵在於使用Mannitol這類高滲透壓利尿劑降腦壓時，最需密切注意的是「腎功能與電解質（尤其血鈉、滲透壓）變化」而非「血糖」，此敘述將監測重點誤植為血糖，並不精確，為本題答案（C✗，題目問「何者錯誤」）。急性期使用顱內壓監測器並依醫囑引流腦脊髓液是標準降腦壓處置（A✓）；瞳孔散大固定、對光反應消失合併肌力與意識下降，是顱內壓升高、可能腦疝形成的危急徵象（D✓）。"},{n:254,no:4,subj:"神經系統",q:"有關阿茲海默氏症之敘述，下列何者錯誤？",opts:["A.是一慢性、進展性、退化性腦部疾病","B.可能病因為年紀、基因遺傳","C.典型的症狀為長期記憶喪失","D.腦部典型變化為神經纖維糾結與老年性斑塊"],ans:[2],expl:"阿茲海默氏症典型且最早出現的記憶障礙是「近期（短期）記憶」喪失（如忘記剛發生的事），而非長期記憶，隨病程進展才逐漸波及長期記憶，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。阿茲海默氏症屬於慢性、進行性、退化性腦部疾病（A✓）；危險因子包括老化及基因遺傳因素（如APOE ε4基因）（B✓）；病理特徵為腦內類澱粉斑塊（老年性斑塊）與神經纖維糾結沉積（D✓）。"},{n:255,no:5,subj:"神經系統",q:"有關癲癇藥物Dilantin的敘述，下列何者正確？",opts:["A.靜脈輸注時須採用5%葡萄糖稀釋","B.口服常見的副作用為血液惡病質、心律不整等","C.指導病人須維持良好的口腔衛生，使用軟毛牙刷按摩牙齦","D.應維持血清治療濃度於80～100 mcg/dL"],ans:[2],expl:"Dilantin（phenytoin）常見副作用之一是牙齦增生（gingival hyperplasia），故護理指導應強調維持良好口腔衛生，並使用軟毛牙刷輕柔按摩牙齦，以減少牙齦增生及發炎的程度，此為本題答案（C✓）。Dilantin靜脈輸注時應以「生理食鹽水」稀釋，若與含糖溶液（如5%葡萄糖）混合，藥物容易產生結晶沉澱，並非採5%葡萄糖稀釋（A✗）；口服常見副作用以牙齦增生、皮疹、共濟失調、眼球震顫等神經及皮膚黏膜反應為主，血液惡病質（如再生不良性貧血）雖為已知但罕見的嚴重副作用，心律不整則多與「靜脈給藥速度過快」有關，兩者皆非口服常見副作用的典型代表（B✗）；Dilantin有效血清治療濃度公認範圍為10～20 mcg/mL，並非80～100 mcg/dL，此數值明顯偏離臨床常規治療範圍（D✗）。"},{n:256,no:6,subj:"消化系統",q:"陳先生因肝硬化、嚴重腹水，出現呼吸急促、意識混亂的情形，由家人送往醫院接受治療，於實驗室檢查中，可能出現下列何種結果？①ALT：80 U/L、AST：55 U/L ②albumin 4.0 gm/dL ③prothrombin time 5 sec ④ammonia 120 mg/dL",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"陳先生因肝硬化併嚴重腹水、意識混亂，其實驗室數值最可能出現輕度轉胺酶上升（ALT 80、AST 55，反映持續肝細胞損傷）與血氨明顯升高（ammonia 120，與意識混亂之肝性腦病變相符），選①④＝B（本題答案）。肝硬化因肝臟合成白蛋白能力下降，應呈現「低白蛋白血症」，而非正常值4.0 gm/dL（②不符）；肝臟亦負責合成大部分凝血因子，肝硬化病人凝血功能通常變差，呈現凝血酶原時間「延長」，而非僅5秒的異常縮短數值（③不符）。"},{n:257,no:7,subj:"消化系統",q:"承上題，關於陳先生的護理措施，下列何者正確？①限制水分與蛋白質的攝取 ②每天測量體重與腹圍，記錄輸出入量 ③給與利尿劑後，儘快補充Albumin ④使用Lactulose以減少細菌分解蛋白質所產生大量氨",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[0],expl:"承上題陳先生併有腹水及肝性腦病變徵象，護理措施應包括限制水分與蛋白質攝取（急性肝性腦病變期間限制蛋白質可減少腸道細菌分解蛋白質產生的氨，水分限制則有助於控制腹水），並每日測量體重、腹圍及記錄輸出入量以監測體液平衡與腹水變化，選①②＝A（本題答案）。給予利尿劑後常規「儘快」補充Albumin並非此情境下的優先護理措施，白蛋白補充較常見於大量腹水放液術（paracentesis）後預防循環功能障礙，並非利尿劑常規配套措施（③較不適用於本情境）；Lactulose確實是肝性腦病變的標準治療藥物之一，但其屬於「醫囑用藥」而非直接的護理評估／照護措施，且本題官方核定之最適組合為①②，故④暫不列入本題最適答案組合。"},{n:258,no:8,subj:"消化系統",q:"有關不同部位腸造瘻特性之敘述，下列何者正確？",opts:["A.升結腸造瘻的排便沒有規則性","B.迴腸造瘻的大便性狀是半成形狀","C.乙狀結腸造瘻的液體需要量需增加","D.橫結腸造瘻不需要使用人工造口袋"],ans:[0],expl:"升結腸造瘻（ascending colostomy）因位置接近小腸，糞便尚未經過大腸充分吸收水分，排便量多、質地稀薄，且因腸道蠕動頻繁，排便時間與次數難以預測，故「沒有規律性」，此描述符合升結腸造瘻特性，為本題答案（A✓）。迴腸造瘻（ileostomy）因糞便完全未經大腸吸收水分及電解質，大便性狀應為「液狀至糊狀」，並非半成形狀，此描述較符合橫結腸造瘻或更接近正常的大便性狀（B✗）；乙狀結腸造瘻因位置最接近直腸，大腸已充分吸收水分，糞便已趨近正常成形，液體需求量相對「不需要」特別增加，並非需要增加（C✗）；橫結腸造瘻糞便仍偏軟糊狀且排便較無規律，仍建議使用人工造口袋收集排泄物以保護周圍皮膚，並非不需使用（D✗）。"},{n:259,no:9,subj:"消化系統",q:"有關膽道疾病的敘述，下列何者錯誤？",opts:["A.膽囊炎大部分是結石造成","B.膽道結石男性比女性發生機率高","C.可用meperidine HCL（Demerol®）肌肉注射止痛","D.急性膽囊炎病人會出現右上腹部疼痛"],ans:[1],expl:"依統計資料，膽結石及膽道疾病的發生率是「女性高於男性」（女性因荷爾蒙、懷孕等因素風險較高，常以「4F」：Female、Forty、Fertile、Fat描述好發族群），並非男性比女性發生機率高，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。膽囊炎絕大多數（約90～95%）是由膽結石阻塞膽囊管所引起（A✓）；急性膽囊炎疼痛屬中重度內臟痛，臨床上可使用Meperidine等止痛劑肌肉注射緩解疼痛（C✓）；急性膽囊炎典型表現為右上腹疼痛，可能輻射至右肩胛或右背（D✓）。"},{n:260,no:10,subj:"消化系統",q:"有關預防傾倒症候群（dumping syndrome）的飲食建議，下列何者不適宜？",opts:["A.高醣食物","B.適量脂肪","C.高蛋白飲食","D.乾性食物"],ans:[0],expl:"傾倒症候群（dumping syndrome）好發於胃部分或全部切除術後，因高濃度醣類食物快速進入小腸引起滲透性液體轉移及腸道蠕動加速所致，故應「避免」高醣（高糖）食物，此為預防傾倒症候群飲食建議中「不適宜」的項目，為本題答案（A✓，題目問「何者不適宜」）。飲食應改為適量脂肪、高蛋白質有助延緩胃排空速度、減少症狀發生（B、C皆為適宜建議）；選擇乾性食物（減少液體與固體食物同時攝取）可延緩胃排空，減少高滲透壓食糜快速進入小腸的機會，是適宜的飲食調整方式（D為適宜建議）。"},{n:261,no:11,subj:"骨骼肌肉",q:"有關骨折癒合階段照護之敘述，下列何者正確？",opts:["A.血腫形成期，應鼓勵病人進行患肢等張運動","B.細胞增生期，應鼓勵病人進行患肢等張運動","C.骨痂形成期，應鼓勵病人補充足夠的營養","D.鞏固化與再塑造期，告知病人骨折癒合不需再運動"],ans:[2],expl:"骨痂形成期（callus formation stage）身體開始建構新骨組織，需要充足的蛋白質、鈣質及維生素等營養素支持骨癒合，此為本題答案（C✓）。血腫形成期為骨折後初期發炎止血階段，患肢應以固定制動為主，不宜進行等張運動以免影響血腫穩定及初期癒合（A✗）；細胞增生期為軟骨痂形成前的組織修復階段，同樣需要制動保護，不宜進行主動等張運動（B✗）；鞏固化與再塑造期骨骼已逐漸恢復強度，此時應鼓勵病人依醫囑逐步恢復適度負重與運動，以促進骨骼重塑及功能恢復，並非「不需再運動」（D✗）。"},{n:262,no:12,subj:"骨骼肌肉",q:"有關關節炎的敘述，下列何者正確？",opts:["A.骨性關節炎典型的疼痛在活動後加劇，休息後緩減","B.類風濕性關節炎晨間關節僵硬會在不活動後又出現","C.骨性關節炎是慢性、全身性、炎症性關節病變","D.骨性關節炎最先侵犯周邊小關節，包括指、腕、肘、踝、趾"],ans:[0],expl:"骨性關節炎（退化性關節炎）之疼痛特徵為活動或負重後疼痛加劇，休息後可獲得緩解，是與發炎性關節炎（如類風濕性關節炎）鑑別的重要臨床特徵，此為本題答案（A✓）。類風濕性關節炎的晨僵是「活動後」逐漸改善，並非不活動後又重新出現，此描述方向有誤（B✗，正確應為晨僵於休息不動後出現、活動後緩解）；類風濕性關節炎才是慢性、全身性、自體免疫發炎性關節病變，骨性關節炎主要是局部軟骨機械性磨損退化，並非全身性炎症疾病（C✗，此描述較符合類風濕性關節炎）；類風濕性關節炎才好發於周邊小關節（如指、腕關節）且多呈對稱性侵犯，骨性關節炎則好發於負重大關節（如膝、髖）及頻繁使用的關節（D✗，此描述較符合類風濕性關節炎）。"},{n:263,no:13,subj:"骨骼肌肉",q:"有關下背痛病人使用骨盆牽引治療之敘述，下列何者正確？",opts:["A.骨盆牽引是一種骨骼牽引，有助於緩解疼痛","B.牽引時床尾抬高可增加牽引的效果","C.保持臥於床之正中位置，膝、第二腳趾與滑輪在一直線位置","D.牽引使用之拉力可達體重的1/2"],ans:[1],expl:"骨盆牽引屬於「皮膚牽引」而非骨骼牽引，牽引時床尾應「抬高」以利用病人自身體重形成反牽引力，增加牽引效果，此為本題答案（B✓）。骨盆牽引是經由皮膚傳遞牽引力，屬於皮膚牽引（skin traction），並非需要穿針的骨骼牽引（A✗）；正確姿位應保持脊柱在中軸線、身體與牽引方向對齊，「膝、第二腳趾與滑輪成一直線」的描述較符合下肢骨骼牽引（如股骨牽引）的擺位原則，並非骨盆牽引的核心重點（C✗，此描述張冠李戴）；骨盆牽引使用之拉力一般約為體重的1/4（約10～20公斤），並非高達體重的1/2，過大拉力反而可能造成損傷（D✗）。"},{n:264,no:14,subj:"感官系統",q:"下列何者為白內障最有效的治療方式？",opts:["A.手術置換水晶體","B.點散瞳劑","C.眼睛熱敷","D.配戴老花眼鏡"],ans:[0],expl:"白內障是水晶體混濁病變，藥物治療（如點散瞳劑）僅能暫時改善視覺效果，無法根治混濁的水晶體，唯一根本且最有效的治療方式是手術摘除混濁水晶體並植入人工水晶體，此為本題答案（A✓）。點散瞳劑僅能短暫擴大瞳孔、改善部分視野，非治療性措施（B✗）；熱敷對水晶體混濁並無治療效果，較常用於瞼板腺炎等眼瞼疾病（C✗）；配戴老花眼鏡僅能矯正老花度數，對白內障造成的視力模糊無實質治療效果（D✗）。"},{n:265,no:15,subj:"感官系統",q:"有關鼻竇炎病人的護理指導，下列何者錯誤？",opts:["A.鼻竇炎是因鼻竇內黏膜發炎所造成","B.慢性鼻竇炎症狀消退後，即可停用抗生素","C.使用鼻滴劑時，可採用坐姿，頭向後仰","D.使用鼻滴劑時，避免過量，以防引起反彈效果"],ans:[1],expl:"慢性鼻竇炎使用抗生素療程通常需要持續2～4週以上（遠比一般急性感染療程長），即使症狀已消退，仍應依醫囑完成完整療程，不可自行於症狀消退後就停藥，以免感染未完全清除或導致抗藥性，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。鼻竇炎的病理基礎確實是鼻竇內黏膜發炎、腫脹、分泌物滯留（A✓）；使用鼻滴劑時採坐姿、頭部後仰，有助於藥液順利流入鼻竇開口（C✓）；鼻滴劑（尤其血管收縮劑類）使用過量或過久，可能引起反彈性鼻黏膜腫脹（rebound congestion），故須提醒病人避免過量使用（D✓）。"},{n:266,no:16,subj:"心臟血管",q:"有關心肌炎病人的護理指導，下列何者不適宜？",opts:["A.教導阻力運動，提升活動耐力","B.教導服用類固醇藥物，需觀察大便顏色","C.教導減少水分攝取，減少心臟前負荷","D.教導服用毛地黃，需監測脈搏"],ans:[0],expl:"心肌炎病人因心肌收縮功能已受損，應以「減少心臟負荷、促進休息」為照護原則，教導病人進行阻力運動（等長運動，會使心臟後負荷瞬間增加）並不適宜，可能加重心臟負擔，此為本題答案（A✓，題目問「何者不適宜」）。類固醇藥物治療可能增加腸胃道副作用及消化性潰瘍風險，需觀察大便顏色以及早發現腸胃出血徵象（黑便）（B為適宜指導）；限制水分攝取有助於減少心臟前負荷，避免心衰竭症狀惡化（C為適宜指導）；服用毛地黃（Digoxin）需監測脈搏，因其治療劑量與中毒劑量接近，脈搏過緩（<60次/分）是常見中毒警訊，需暫停用藥並回報（D為適宜指導）。"},{n:267,no:17,subj:"心臟血管",q:"有關心肌梗塞後性生活的建議事項，下列敘述何者正確？①應該儘量避免以免再次發作 ②能量消耗大約與上下兩層樓相當 ③飽餐後或酒後比較適合性行為 ④性行為事後應預防性服用NTG ⑤應在熟悉的環境與伴侶進行以避免過度緊張與刺激 ⑥環境的室溫勿太冷或太熱",opts:["A.①②③","B.①④⑥","C.②⑤⑥","D.③④⑤"],ans:[2],expl:"心肌梗塞後恢復性生活，其能量消耗大約與快速爬兩層樓梯相當，可作為病人自我評估心臟負荷能力的參考基準（②✓）；應在熟悉的環境與固定伴侶進行，避免陌生環境或對象造成的額外緊張與交感神經興奮（⑤✓）；環境室溫應適中，避免過冷或過熱造成周邊血管收縮或擴張的額外心臟負荷（⑥✓），選②⑤⑥＝C（本題答案）。心肌梗塞病後性生活並非必須完全避免，多數病人在醫師評估心臟功能穩定後可逐步恢復（①錯誤）；飽餐後或飲酒後皆會增加心臟額外負擔，應避免而非適合進行性行為（③錯誤）；預防性服用NTG（硝化甘油）需經醫師個別評估後才建議使用，並非所有病人性行為後皆常規預防性服用，且若病人合併使用PDE5抑制劑等藥物，NTG更可能引起嚴重低血壓，並非可一概而論的建議（④錯誤）。"},{n:268,no:18,subj:"心臟血管",q:"下列何者為冠狀動脈性心臟病人服用Aspirin之主要目的？",opts:["A.緩解發作時胸痛","B.鬆弛血管平滑肌","C.抑制血小板凝集","D.減緩心跳速率"],ans:[2],expl:"Aspirin作為冠狀動脈心臟病的重要用藥，其核心藥理作用是抑制血小板環氧化酶（COX-1），進而抑制血小板凝集，預防血栓形成，是冠心病病人服用低劑量Aspirin的主要目的（C✓，本題答案）。Aspirin並非急性胸痛發作時的第一線緩解藥物（緩解胸痛應優先使用NTG）（A✗）；Aspirin不具血管平滑肌鬆弛作用（此為NTG等硝酸鹽類藥物的作用機轉）（B✗）；Aspirin亦不具減緩心跳速率的藥理作用（此為乙型阻斷劑等藥物的作用）（D✗）。"},{n:269,no:19,subj:"心臟血管",q:"有關心臟節律器之敘述，下列何者正確？",opts:["A.裝設心臟節律器術後，出現持續打嗝是正常現象","B.永久性心臟節律器的激搏器在體外，可方便更換電池","C.裝設暫時性心臟節律器，心電圖上不會出現激搏波（pace spike）","D.裝設永久性心律調節器後，4～6週內應避免提重物"],ans:[3],expl:"永久性心臟節律器植入後，因傷口尚未穩定癒合及導線尚未完全固定，一般建議術後4～6週內應避免提舉重物或劇烈上肢活動，以防導線移位，此為本題答案（D✓）。裝設心臟節律器術後若出現持續打嗝，可能是導線刺激橫膈神經或心肌所致的異常徵象，應立即通報評估，並非正常現象（A✗）；永久性心臟節律器的脈衝產生器（激搏器）是「植入於體內」（通常在鎖骨下皮下組織），並非在體外，如需更換電池須經手術處理，並非方便體外更換（B✗）；裝設暫時性心臟節律器時，心電圖上仍會出現節律器發出電刺激訊號所產生的激搏波（pace spike），並非不會出現（C✗）。"},{n:270,no:20,subj:"心臟血管",q:"有關下肢深部靜脈栓塞服用Warfarin病人之護理指導，下列何者正確？",opts:["A.需監測活化部分凝血酶原時間（APTT）","B.可以自行停用藥物","C.避免大量食用深綠色蔬菜","D.建議補充維生素K"],ans:[2],expl:"服用Warfarin治療深部靜脈栓塞的病人，因深綠色蔬菜（如菠菜、花椰菜等）富含維生素K，會拮抗Warfarin的抗凝血作用，影響藥效穩定性，故應避免「大量」攝取，維持相對穩定的攝取量，此為本題答案（C✓）。Warfarin主要監測指標是「凝血酶原時間（PT）／國際標準化比值（INR）」，並非APTT（APTT主要用於監測Heparin治療）（A✗）；Warfarin需依醫囑規律服用，不可自行停藥，以免血栓復發或造成劑量調整困難（B✗）；維生素K是Warfarin的拮抗劑，服藥期間應避免「額外補充」大量維生素K，而非建議補充（D✗）。"},{n:271,no:21,subj:"腫瘤血液",q:"針對接受trastuzumab（Herceptin®）治療的癌症病人之護理，下列何者正確？①靜脈滴注給藥 ②空腹口服給藥 ③監測丘疹、手足症候群 ④監測心臟功能",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[1],expl:"Trastuzumab（賀癌平）屬於單株抗體標靶藥物，需以「靜脈滴注」方式給藥（並非口服藥物）（①✓）；其已知重要副作用之一是「心臟毒性」，可能造成心臟收縮功能下降甚至心衰竭，用藥期間需定期監測左心室射出分率（LVEF）等心臟功能指標（④✓），選①④＝B（本題答案）。Trastuzumab為注射劑型，並非口服給藥，故不需空腹口服（②錯誤）；丘疹與手足症候群較常見於小分子標靶藥物（如TKI類）或某些化療藥物的副作用，並非Trastuzumab最具代表性的監測重點（③較非本題核心答案，心臟毒性才是trastuzumab最需監測的重點）。"},{n:272,no:22,subj:"腫瘤血液",q:"有關癌細胞轉移之敘述，下列何者錯誤？",opts:["A.轉移是指癌細胞從原發部位擴散至身體其他組織器官","B.惡性肉瘤（sarcoma）常以淋巴轉移方式轉移到其他部位","C.常見轉移方式為淋巴轉移、血流轉移及體腔內播種式生長","D.肺、肝及骨骼為原發性癌症常見轉移部位"],ans:[1],expl:"惡性肉瘤（sarcoma，來源於間質組織如骨、軟組織、肌肉等）最主要的轉移途徑是「血行轉移」，較常轉移至肺部；相對而言，癌（carcinoma，來源於上皮組織）才是以淋巴轉移為主要途徑，此敘述將兩者轉移方式混淆，錯誤，為本題答案（B✗，題目問「何者錯誤」）。轉移（metastasis）定義即癌細胞由原發部位擴散至身體其他組織器官（A✓）；癌症常見轉移途徑包括淋巴轉移、血行轉移及體腔內直接播種（如腹膜腔內轉移）（C✓）；肺、肝、骨骼因血流供應豐富，是多數原發性癌症最常見的轉移目標器官（D✓）。"},{n:273,no:23,subj:"腫瘤血液",q:"李先生45歲，日前因頸部右側不對稱腫塊到醫院求診，經淋巴切片檢查診斷為何杰金氏症，下列何者不是此病常見的症狀？",opts:["A.淋巴系統發現有腫大、但無壓痛情形","B.皮膚系統發現有搔癢情形","C.腸胃系統有嘔吐、排便習慣改變的情形","D.呼吸系統發現有呼吸困難、咳嗽咳血或胸悶"],ans:[2],expl:"何杰金氏症的腸胃道侵犯（如嘔吐、排便習慣改變）並非此疾病典型或常見的臨床表現，此為本題答案（C✓，題目問「何者不是」）。何杰金氏症典型表現為單側無痛性淋巴結腫大（常見於頸部），腫大但「無壓痛」是其特徵之一（A為常見症狀）；部分病人會出現不明原因的全身搔癢感，是何杰金氏症的典型伴隨症狀之一（B為常見症狀）；若縱膈腔淋巴結受侵犯壓迫氣管或肺部，可能出現呼吸困難、咳嗽、咳血或胸悶等呼吸道症狀（D為常見症狀）。"},{n:274,no:24,subj:"腫瘤血液",q:"病人接受doxorubicin（Adriamycin®）注射時，發現點滴不順、針頭附近有微發紅及刺痛情形，下列處置何者不適當？",opts:["A.可能為熱反應，注射後給予0.9% N/S及dexamethasone","B.懷疑是藥物外滲時，停止注射以原針頭回抽藥物","C.墊高注射部位且局部避免加壓","D.評估為藥物外滲則可給予溫熱敷"],ans:[3],expl:"當懷疑藥物已經外滲（滲漏至血管外周圍組織）時，若給予溫熱敷，反而可能加速藥物在組織內擴散、加重局部組織傷害，正確處置應依藥物性質評估是否採「冷敷」（多數化療藥物外滲建議冷敷以減緩藥物擴散及吸收），此敘述之處置方向有誤，為本題答案（D✗，題目問「何者不適當」）。若判斷為熱反應（非外滲）所致的局部發紅刺痛，可依醫囑於注射後給予生理食鹽水沖洗及類固醇藥物（如dexamethasone）緩解發炎反應，此為合理處置（A✓）；懷疑藥物外滲時，應立即停止輸注，並嘗試以原留置針頭回抽殘留藥液，以減少藥物在組織內的殘留量（B✓）；外滲處置原則之一是墊高患肢、避免局部加壓，以減少藥物在組織間隙的擴散壓力（C✓）。"},{n:275,no:25,subj:"腫瘤血液",q:"王小明，體重50公斤，接受組織配對成功為供髓者，下列護理措施何者正確？",opts:["A.骨髓抽取時採半身麻醉","B.骨髓抽取量約100 c.c.","C.骨髓抽取後不需平躺","D.骨髓抽出過濾後可立即輸注至受髓者體內"],ans:[3],expl:"周邊血捐髓或骨髓捐贈完成後，經過濾處理的骨髓／幹細胞懸浮液，即可依受髓者移植排程盡快輸注給受髓者，此為本題答案（D✓）。骨髓抽取術通常於「全身麻醉」下，自髂骨等部位以骨髓穿刺針抽取，並非半身麻醉（A✗）；骨髓抽取量依受髓者體重及所需細胞數計算，一般約為供髓者體重的10～15 mL/kg，本題供髓者體重50公斤，抽取量通常會達到約500～1000 c.c.左右（依實際需求調整），並非僅約100 c.c.（B✗，抽取量遠高於此）；骨髓抽取後因採全身麻醉及多處穿刺，術後應臥床休息觀察生命徵象及穿刺部位出血情形，並非不需平躺（C✗）。"},{n:276,no:26,subj:"腫瘤血液",q:"有關紅血球增多症病人之護理措施，下列何者錯誤？",opts:["A.教導病人深呼吸及有效咳嗽，促進肺部擴張及通氣","B.告知病人儘量臥床休息，避免活動造成出血","C.鼓勵病人增加飲水量，每日至少3,000～4,000 mL","D.評估跌倒的危險因子並維護病人安全"],ans:[1],expl:"紅血球增多症因血比容過高、血流黏稠度增加，理論上栓塞（而非出血）風險較高，護理上應著重「預防血栓形成」（如鼓勵下肢活動、避免久坐不動），而非以「儘量臥床休息以避免活動造成出血」為主要護理原則，此敘述之風險方向與紅血球增多症的病理生理相反，錯誤，為本題答案（B✗，題目問「何者錯誤」）。深呼吸及有效咳嗽可促進肺部擴張與換氣，改善組織缺氧、減少代償性紅血球增多的刺激（A✓）；鼓勵增加飲水量有助於降低血液黏稠度、預防血栓形成（C✓）；血液黏稠度增加可能影響腦部循環及肢體感覺，需加強評估跌倒危險因子並維護病人安全（D✓）。"},{n:277,no:27,subj:"其他",q:"葉女士手部遭魚刺刺傷，出現局部發紅、化膿的炎症反應，診斷為蜂窩性組織炎，下列護理措施何者正確？",opts:["A.給予周邊靜脈輸液及全身性抗生素連續7～10天","B.依照內科無菌原則施行冷水浸泡以減輕炎症反應","C.教導減少攝取液體以避免患處水腫","D.患肢低於胸部以降低病菌回流至軀幹"],ans:[0],expl:"蜂窩性組織炎屬於深層皮下組織細菌感染，標準治療為周邊靜脈輸液給予全身性抗生素，療程通常需持續7～10天以確保感染完全清除，此為本題答案（A✓）。蜂窩性組織炎急性期應採「溫熱敷」（而非冷水浸泡）以促進局部血液循環、幫助發炎物質吸收及膿液局限化，並非冷水浸泡（B✗）；應鼓勵病人「增加」液體攝取，以利新陳代謝及協助對抗感染，並非減少液體攝取（C✗）；患肢應「抬高」（高於心臟）以促進靜脈與淋巴回流、減輕腫脹，並非放低患肢（D✗，放低患肢反而會使腫脹與發炎物質滯留惡化）。"},{n:278,no:28,subj:"其他",q:"有關氣爆引發四度熱燒傷的健康問題，下列何者較不常發生？",opts:["A.體溫過低","B.體液容積缺失","C.急性疼痛","D.潛在危險性感染"],ans:[2],expl:"四度燒傷（deep full-thickness burn）已深及肌肉、肌腱甚至骨骼組織，因深層神經末梢已一併遭破壞，患處本身痛覺感受反而可能降低或消失（周圍二、三度燒傷交界處仍可能疼痛），故「急性疼痛」相對於體溫過低、體液容積缺失、感染風險等全身性問題，並非四度燒傷最優先或最常出現的健康問題，此為本題答案（C✓，題目問「何者較不常發生」）。大面積燒傷因皮膚屏障喪失，體表水分蒸發及熱量流失大增，易發生體溫過低（A為常見問題）；微血管通透性增加合併大量體液從創面滲出，造成血管內容積不足，是燒傷後最需優先處置的問題之一（B為常見問題）；皮膚屏障完整性喪失使病人暴露於高度感染風險中，是燒傷病人長期照護的重大潛在威脅（D為常見問題）。"},{n:279,no:29,subj:"其他",q:"有關疥瘡的治療，下列敘述何者正確？",opts:["A.為避免因接觸而傳染給他人，抗疥蟲藥物最好於白天使用","B.成人病人使用crotamiton（Eurax®）滅疥乳膏時，可一日數次塗抹於頭、臉、全身，尤其皮膚皺褶處","C.Benzyl Benzoate（B.B.）塗抹後，待藥液乾後再塗一次，24小時後沖掉，每晚或隔晚使用，共3次","D.γ-benzene hexachloride（Lindane）具有神經毒性，塗抹後8～12小時沖掉，每天使用一次"],ans:[2],expl:"Benzyl Benzoate（BB乳劑）是治療疥瘡的傳統外用藥物之一，正確用法為塗抹後待藥液自然乾燥，再塗抹第二次，經過24小時後再沖洗清除，依醫囑於每晚或隔晚使用，通常療程約3次，此描述符合標準用藥指導，為本題答案（C✓）。抗疥蟲藥物應於「夜間睡前」塗抹（疥蟲夜間活動力較強，且夜間塗抹可增加藥物與皮膚接觸時間），並非於白天使用，以增加療效並降低白天活動流汗造成藥效流失（A✗）；Crotamiton（優力松）等滅疥藥膏之一般用法為「一天1～2次」規律塗抹於頸部以下全身皮膚，並非「一日數次」高頻率塗抹，過度使用反而可能刺激皮膚（B✗）；Lindane（林旦，γ-BHC）因具神經毒性風險，正確用法應是塗抹後「約8～12小時後即沖洗」，且因其安全性疑慮，現已較少作為首選藥物，「每天使用一次」的長期反覆使用方式並不恰當，容易增加中毒風險（D✗，正確用法強調單次短暫接觸即需沖洗，不建議每日反覆使用）。"},{n:280,no:30,subj:"骨骼肌肉",q:"有關鞏皮症臨床表徵之敘述，下列何者錯誤？",opts:["A.易有上腹飽脹、上腹或胸骨後的灼痛","B.雷諾氏現象","C.面部表情缺失","D.後續會發展成肝衰竭"],ans:[3],expl:"鞏皮症（進行性系統性硬化症）主要造成皮膚與內臟器官的纖維化病變，其肝臟並非此疾病主要侵犯的器官，鞏皮症後續較典型會發展成「肺纖維化」及「腎臟病變（硬皮症腎危象）」，並非肝衰竭，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。食道蠕動功能受損可能造成上腹飽脹、逆流性灼熱感（A✓）；周邊血管痙攣導致的雷諾氏現象是鞏皮症的典型早期表現之一（B✓）；顏面皮膚纖維化緊繃，會使病人呈現面具般缺乏表情的外觀（面具臉）（C✓）。"},{n:281,no:31,subj:"骨骼肌肉",q:"有關全身性紅斑性狼瘡（SLE）臨床表徵之敘述，下列何者錯誤？",opts:["A.皮膚症狀：蝴蝶斑為主要典型症狀","B.心肺症狀：肺部受侵犯以肺炎最為常見","C.泌尿系統：可能出現蛋白尿、血尿","D.神經系統：出現人格改變或精神疾病"],ans:[1],expl:"全身性紅斑性狼瘡（SLE）肺部受侵犯時，最常見的表現是「肋膜炎（肋膜積水）」，並非以肺炎最為常見，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。蝴蝶斑（顴骨兩側蝴蝶狀紅斑）是SLE最具代表性的皮膚典型症狀（A✓）；狼瘡腎炎是SLE重要的器官侵犯表現，可能出現蛋白尿、血尿等腎絲球損傷徵象（C✓）；SLE可能侵犯中樞神經系統，導致人格改變、認知功能障礙或精神症狀等神經精神狼瘡表現（D✓）。"},{n:282,no:32,subj:"呼吸系統",q:"下列何者是持續換氣不足病人之動脈血液氣體分析最可能出現的結果？",opts:["A.呼吸性酸中毒","B.呼吸性鹼中毒","C.代謝性酸中毒","D.代謝性鹼中毒"],ans:[0],expl:"持續性換氣不足（chronic hypoventilation）代表病人長期二氧化碳排出不足，體內CO2蓄積使pH下降，屬於呼吸性酸中毒的典型病理生理機轉，此為本題答案（A✓）。換氣不足會使CO2蓄積而非排出過多，故不會呈現呼吸性鹼中毒（B✗，呼吸性鹼中毒是換氣「過度」所致）；代謝性酸中毒與代謝性鹼中毒是體內酸鹼調節或代謝功能異常所致，並非直接由「換氣不足」這個呼吸生理機轉所導致（C、D✗）。"},{n:283,no:33,subj:"呼吸系統",q:"周先生為氣喘病人，使用藥物後，出現「心悸、心律不整」的反應，最可能導致此反應的藥物為下列何者？",opts:["A.fenoterol（Berotec®）","B.ipratropium bromide（Atrovent®）","C.budesonide（Duasma®）","D.montelukast（Singular®）"],ans:[0],expl:"Fenoterol（Berotec®）屬於短效乙二型交感神經興奮劑（SABA），為氣喘急性發作時常用的支氣管擴張劑，但其藥理作用除擴張支氣管平滑肌外，亦可能刺激心臟乙型受體，造成心悸、心搏過速甚至心律不整等副作用，此為本題答案（A✓）。Ipratropium bromide（Atrovent®）為抗膽鹼性支氣管擴張劑，較常見副作用為口乾、咳嗽，較少引起明顯心悸心律不整（B✗）；Budesonide（Duasma®）為吸入性類固醇，主要用於控制發炎反應，全身性心臟副作用相對少見（C✗）；Montelukast（Singular®）為白三烯受體拮抗劑，主要副作用與神經精神症狀相關（如情緒變化），並非以心悸心律不整為主要副作用（D✗）。"},{n:284,no:34,subj:"呼吸系統",q:"王先生診斷左側肋膜積水準備接受胸腔放液穿刺術，下列何者為其最適當的姿勢體位？",opts:["A.床頭搖高30度仰臥","B.坐於床緣，頭和手趴在床旁桌上","C.躺向左側，左手臂上舉過頭","D.左手上舉採俯臥"],ans:[1],expl:"胸腔放液穿刺術（thoracentesis）之標準姿勢是讓病人坐於床緣，身體微向前傾，雙手前臂交叉置於床旁桌上支撐身體重量，此姿勢有助於撐開肋間隙、暴露背部穿刺部位，便於醫師操作，此為本題答案（B✓）。床頭搖高30度仰臥或其他平躺姿勢無法有效撐開肋間隙及暴露穿刺部位，不利於此侵入性操作（A✗）；左手臂上舉過頭或俯臥姿勢皆非胸腔穿刺放液術的標準操作姿位，且左側肋膜積水病人若採取這類姿勢，反而不利於醫師由背側進行安全的穿刺操作（C、D✗）。"},{n:285,no:35,subj:"呼吸系統",q:"有關肺炎鏈球菌肺炎病人之臨床表徵，下列敘述何者最不適當？",opts:["A.痰液量增加","B.胸部X光出現肺浸潤","C.白血球上升","D.呼吸離軌度增加"],ans:[3],expl:"肺炎鏈球菌肺炎因肺部發炎反應，胸廓兩側呼吸運動應呈現「不對稱」，患側呼吸擴張度會「減少」，而非呼吸離軌度「增加」，此敘述與臨床實際表現不符，為本題答案（D✓，題目問「何者最不適當」）。肺部發炎分泌物增加，痰液量隨之增多（A為典型表徵）；肺部感染發炎導致肺泡實質化，胸部X光呈現肺浸潤陰影（B為典型表徵）；細菌性感染引發身體免疫反應，白血球數目上升是常見表徵（C為典型表徵）。"},{n:286,no:36,subj:"呼吸系統",q:"有關慢性阻塞性肺疾病（COPD）病人飲食指導之敘述，下列何者較適當？①進食時可將氧氣面罩更換為氧氣套管 ②選擇易咀嚼食物 ③增加碳水化合物 ④減少水分的攝取",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[0],expl:"COPD病人因呼吸費力，進食時若持續配戴氧氣面罩會妨礙進食動作及增加嗆咳誤吸風險，可暫時更換為侵入性較低、方便進食的氧氣鼻套管以維持氧氣供應（①✓）；COPD病人常因呼吸費力而容易疲憊，選擇易咀嚼、好消化的食物可減少進食時的體力消耗（②✓），選①②＝A（本題答案）。COPD病人因長期須增加呼吸作功，熱量需求較一般人高，飲食應以「足夠熱量」為原則，但應避免「過量碳水化合物」（過多醣類代謝會產生較多二氧化碳，增加呼吸系統負擔），並非鼓勵增加碳水化合物攝取（③錯誤）；除非有心衰竭等合併症限制水分，一般COPD病人應維持「足夠」水分攝取以利痰液稀釋排出，並非減少水分攝取（④錯誤）。"},{n:287,no:37,subj:"泌尿系統",q:"有關腎臟移植過程之敘述，下列何者錯誤？",opts:["A.病人術前需再進行血液透析移除體液與毒素","B.交叉試驗陰性才可以進行腎臟移植","C.移植腎多是植入於下腹部腔膜外的腸骨窩處","D.必須先移除原來腎臟再將新的腎臟做尿道接合"],ans:[3],expl:"腎臟移植手術僅將新的腎臟植入下腹部（通常在腸骨窩處），與原有的病腎進行血管及輸尿管的重新接合，病人原本已萎縮或病變的自體腎臟「通常保留在原位，不會特別移除」（除非有特殊感染、腫瘤等適應症才會考慮切除），此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。腎臟移植手術前，病人仍需依賴透析移除體內多餘水分及代謝廢物，以維持手術前生理狀態穩定（A✓）；捐贈者與受贈者間的組織相容性交叉配對試驗結果需為陰性（表示無強烈免疫排斥反應），才能進行移植（B✓）；移植腎一般植入於下腹部腹膜外的腸骨窩處，此處血管接近、手術操作相對方便，也利於術後觸診評估（C✓）。"},{n:288,no:38,subj:"泌尿系統",q:"下列那些檢查前需要確認病人腎功能？①腎動脈攝影術 ②腎臟、輸尿管、膀胱X光檢查 ③腎臟超音波 ④逆行性腎盂攝影術 ⑤靜脈注射腎盂攝影術",opts:["A.①②","B.①⑤","C.②③","D.④⑤"],ans:[1],expl:"腎動脈攝影術（①）與靜脈注射腎盂攝影術（IVP，⑤）皆需經「靜脈」注射含碘顯影劑，顯影劑經由腎臟代謝排出，可能造成顯影劑腎病變（contrast-induced nephropathy），故檢查前必須先確認病人腎功能是否能負荷，選①⑤＝B（本題答案）。腎臟輸尿管膀胱X光（KUB，②）屬於單純X光攝影，不需使用顯影劑；腎臟超音波（③）無輻射、無顯影劑，兩者皆不需要事先確認腎功能；逆行性腎盂攝影術（④）雖也使用顯影劑，但是經由膀胱鏡逆行經輸尿管導管直接注入顯影劑至腎盂，並非經由全身血液循環代謝，故不會造成類似靜脈注射顯影劑對腎功能的全身性負擔，也不需要如①⑤般事先確認腎功能。"},{n:289,no:39,subj:"泌尿系統",q:"有關透析治療比較之敘述，下列何者正確？",opts:["A.血液透析的飲食限制，較腹膜透析嚴格","B.血液透析的蛋白質流失量，較腹膜透析多","C.血液透析發生高血脂比例，較腹膜透析高","D.血液透析對於心血管負荷，較腹膜透析少"],ans:[0],expl:"血液透析（HD）病人因兩次透析間期較長（通常每週僅治療2～3次），必須在治療間期嚴格限制水分、鹽分、鉀離子及磷離子攝取以避免體液與電解質過度蓄積，飲食限制普遍較連續性、緩慢移除溶質的腹膜透析更為嚴格，此為本題答案（A✓）。腹膜透析因每日經腹膜透析液持續流失蛋白質，長期蛋白質流失量反而「較血液透析多」，並非血液透析流失較多（B✗）；腹膜透析因透析液含高濃度葡萄糖，長期使用容易造成血脂異常，發生高血脂比例反而「較血液透析高」，並非血液透析較高（C✗）；血液透析因短時間內快速移除大量水分與溶質，體液與血壓波動較劇烈，對心血管系統的衝擊與負荷「較腹膜透析更大」，並非較少（D✗）。"},{n:290,no:40,subj:"呼吸系統",q:"韓小姐的動脈血液氣體分析結果為pH 7.44、PaCO2 30 mmHg、HCO3- 20 mEq/L、PaO2 82 mmHg，根據以上數值，判讀結果下列何者正確？",opts:["A.部分代償性呼吸性酸中毒","B.未代償性代謝性酸中毒","C.未代償性代謝性鹼中毒","D.完全代償性呼吸性鹼中毒"],ans:[3],expl:"pH 7.44屬於正常範圍偏鹼側，PaCO2 30 mmHg明顯低於正常值（35～45mmHg），顯示有換氣過度、呼吸性鹼中毒的原發性變化；HCO3- 20 mEq/L亦低於正常範圍（22～26mEq/L），顯示腎臟已代償性排出重碳酸鹽以中和過鹼的pH值，且pH值已回到正常範圍內，符合「完全代償性呼吸性鹼中毒」的判讀，此為本題答案（D✓）。"},{n:291,no:41,subj:"泌尿系統",q:"有關良性前列腺肥大（BPH）之敘述，下列何者錯誤？",opts:["A.是男性常見的老年疾病，是前列腺體的細胞本身肥大所致","B.尿路動力學檢查時發現病人的最大尿流速會減低","C.病人常主訴頻尿或餘尿感（解不乾淨）","D.肛門觸診可以評估前列腺肥大的程度"],ans:[0],expl:"良性前列腺肥大（BPH）是攝護腺「移形區（transition zone）」的腺體組織與間質細胞良性增生所致，並非單純「細胞本身肥大」，此敘述在病理機轉描述上不夠精確，為本題答案（A✗，題目問「何者錯誤」；正確機轉應為腺體組織增生hyperplasia，而非細胞肥大hypertrophy）。攝護腺增生壓迫尿道，會使尿路動力學檢查中的最大尿流速降低（B✓）；增生阻塞造成排尿不順，病人常主訴頻尿、夜尿及餘尿感（解尿解不乾淨）（C✓）；攝護腺位置鄰近直腸，臨床上可經由肛門指診評估攝護腺大小、硬度及是否有異常結節（D✓）。"},{n:292,no:42,subj:"內分泌系統",q:"有關原發性醛固酮過多症之護理措施，下列何者錯誤？",opts:["A.需觀察病人有無肌肉軟弱無力、疲倦、麻痹、心律不整等臨床表徵","B.需觀察病人有無強直性痙攣和呼吸抑制情形","C.教導病人飲食中應多補充高鈉食物，例如火腿、香腸、起司等","D.需注意病人血壓的變化，有無血壓過高情形"],ans:[2],expl:"原發性醛固酮過多症（Conn氏症）因醛固酮過多促使腎臟保鈉排鉀，導致「高血鈉、低血鉀」，飲食應限制「高鈉」食物攝取（而非補充），並嚴格監控鈉離子攝取量，此敘述方向相反，錯誤，為本題答案（C✗，題目問「何者錯誤」）。低血鉀可能造成肌肉軟弱無力、疲倦、感覺異常（麻痺）及心律不整等表現，需密切觀察（A✓）；嚴重低血鉀可能導致肌肉強直性痙攣甚至呼吸肌無力抑制，屬於危急徵象，需密切監測（B✓）；醛固酮促進水鈉滯留，會使血壓升高，是本病重要的臨床表徵，需監測血壓變化（D✓）。"},{n:293,no:43,subj:"內分泌系統",q:"有關抗利尿激素分泌不當症候群（SIADH）病人的臨床照護，下列何者錯誤？",opts:["A.依醫囑補充3%生理食鹽水的靜脈輸液及注射furosemide（Lasix®）","B.鼓勵病人多攝取低纖食物","C.監測有無出現肌肉抽搐與昏迷的徵象","D.依醫囑限制水分攝取每日在1,000 c.c.以下"],ans:[1],expl:"SIADH因抗利尿激素分泌過多，導致水分滯留、體液被稀釋，引發「稀釋性低血鈉」，飲食上應著重限制水分攝取，「低纖食物」與SIADH的治療原則並無直接相關性，此敘述並非SIADH照護的核心正確措施，為本題答案（B✗，題目問「何者錯誤」）。嚴重低血鈉時依醫囑補充高張（3%）生理食鹽水並搭配Furosemide促進排水，是SIADH合併嚴重症狀時的急性處置方式（A✓）；低血鈉可能引發神經肌肉症狀，需密切監測肌肉抽搐甚至意識改變、昏迷等神經學徵象（C✓）；限水是SIADH最基本的治療原則，依醫囑嚴格限制每日水分攝取量（如1,000c.c.以下）（D✓）。"},{n:294,no:44,subj:"內分泌系統",q:"有關雙胍類降血糖藥物metformin（Glucophage®）之敘述，下列何者錯誤？",opts:["A.減少肝臟葡萄糖的輸出，以降低空腹血糖","B.最好與食物一起服用，或飯後馬上服用","C.易出現胃腸道刺激及引發維生素B6缺乏","D.腎功能不良的病人需要小心使用"],ans:[2],expl:"Metformin常見腸胃道副作用包括噁心、腹瀉、腹脹等，長期使用亦可能干擾維生素B12的腸道吸收，導致「維生素B12缺乏」（而非維生素B6），此敘述之維生素種類有誤，為本題答案（C✗，題目問「何者錯誤」）。Metformin主要作用機轉是抑制肝臟葡萄糖新生及輸出，進而降低空腹血糖（A✓）；為減少腸胃刺激，建議與食物一起服用或飯後立即服用（B✓）；Metformin經腎臟排出，腎功能不良病人使用時可能增加乳酸中毒風險，需小心評估劑量或避免使用（D✓）。"},{n:295,no:45,subj:"內分泌系統",q:"張太太，罹患糖尿病2年，平日使用口服抗血糖藥物控制血糖，今日在家昏倒被送至急診，醫師初步診斷為高滲透壓高血糖狀態（HHS），病人會呈現的徵象，下列何者正確？①呼吸速率26次／分 ②血壓166/84 mmHg ③尿酮呈陽性反應，明顯升高 ④血糖為750 mg/dL",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"高滲透壓高血糖狀態（HHS）好發於第二型糖尿病病人，因嚴重高血糖（常遠高於600 mg/dL，本題750 mg/dL相符）造成滲透性利尿、脫水，身體會出現代償性呼吸速率上升等表現（①呼吸速率26次/分✓，④血糖750✓），選①④＝B（本題答案）。HHS因嚴重脫水，血壓通常會因體液容積不足而「下降」，而非維持在166/84 mmHg的偏高數值，此血壓數值與HHS脫水表現不符（②不符）；HHS與糖尿病酮酸中毒（DKA）的重要鑑別特徵之一即是HHS病人「通常無明顯酮酸血症」，尿酮多為陰性或僅輕微陽性，並非「明顯升高」，此為DKA的典型特徵而非HHS（③不符）。"},{n:296,no:46,subj:"內分泌系統",q:"有關甲狀腺機能亢進病人服用飽和碘化鉀溶液之敘述，下列何者正確？",opts:["A.絕不可與牛奶一起服用","B.主要功能是抑制T4轉變為T3","C.可以降低甲狀腺素的釋放及合成","D.要長期服用超過一個月才能評估臨床效果"],ans:[2],expl:"飽和碘化鉀溶液（SSKI）治療甲狀腺機能亢進的主要機轉是透過Wolff-Chaikoff效應，抑制甲狀腺素的合成與釋放，快速緩解甲狀腺風暴或作為術前準備用藥，此為本題答案（C✓）。碘化鉀溶液味道苦澀，臨床上常建議加入牛奶、果汁等飲品中稀釋服用以改善適口性並減少腸胃刺激，並非絕不可與牛奶一起服用（A✗）；抑制T4轉變為T3是PTU等硫醯胺類藥物於高劑量使用時的周邊作用機轉，並非碘化鉀溶液的主要作用（B✗）；碘化鉀溶液的作用「起效快速」（數小時內即可見效），但效果通常僅能維持約1～2週便可能出現「脫逸現象（escape phenomenon）」而失效，故臨床上多作為「短期」用藥（如術前準備、甲狀腺風暴），並非需長期服用超過一個月才能評估效果（D✗）。"},{n:297,no:47,subj:"其他",q:"有關休克病人體溫下降之護理措施，下列何者正確？",opts:["A.當身體顫抖產熱及代謝增加，應調低室溫以減少發燒程度","B.靜脈注射的液體或血液，應加溫至接近正常體溫","C.使用熱水袋或電毯包裹四肢","D.給予熱水浴，以增加病人舒適感"],ans:[1],expl:"休克病人若體溫下降，靜脈輸注的液體或血液製劑應加溫至接近體溫後再輸入，以避免輸入大量低溫液體造成病人體溫進一步下降、誘發心律不整等併發症，此為本題答案（B✓）。若病人因體溫過低而出現顫抖產熱反應，此為身體正常代償機轉試圖回升體溫，應設法保暖並「提高」環境室溫協助病人回溫，而非調低室溫（A✗，此描述方向錯誤且與「發燒」情境混淆）；熱水袋或電毯直接包裹四肢有造成皮膚燙傷的風險，且四肢末梢循環在休克時通常已代償性收縮，直接加熱四肢效果有限，正確做法應以毯子等被動保暖方式為主，或依醫囑審慎評估加溫方式（C✗）；休克病人生命徵象不穩定，不宜給予熱水浴等可能造成周邊血管擴張、血壓進一步下降的處置，具有安全疑慮（D✗）。"},{n:298,no:48,subj:"其他",q:"有關食物中毒之敘述，下列何者正確？",opts:["A.河豚中毒主要是處理河豚過程被細菌污染造成","B.金黃色葡萄球菌中毒症狀主要是視力模糊、吞嚥困難","C.沙門氏桿菌中毒症狀主要是腹瀉、噁心、嘔吐及發燒","D.食物中毒之嚴重度與食入污染物的量與內毒素含量呈負相關"],ans:[2],expl:"沙門氏桿菌感染典型症狀為腹瀉、噁心、嘔吐及發燒等腸胃炎表現，是最常見的細菌性食物中毒之一，此為本題答案（C✓）。河豚中毒主要是因河豚體內天然存在「河豚毒素（tetrodotoxin）」，並非處理過程遭細菌污染所致，此為天然毒素中毒而非細菌性食物中毒（A✗）；金黃色葡萄球菌食物中毒典型症狀是「噁心、嘔吐、腹絞痛、腹瀉」等腸胃道症狀（其腸毒素作用於腸胃道），並非以視力模糊、吞嚥困難為主要表現（視力模糊、吞嚥困難是肉毒桿菌中毒的典型神經症狀）（B✗，選項描述之症狀與致病菌配對錯誤）；一般而言食物中毒的嚴重程度與食入污染物（病原菌或毒素）的量呈「正相關」，攝入量越多、病情通常越嚴重，並非負相關（D✗）。"},{n:299,no:49,subj:"其他",q:"有關自動體外電擊去顫器（AED）操作，下列敘述何者錯誤？",opts:["A.可由非醫護人員操作使用","B.若病人體內裝有人工心臟節律器就不能使用AED","C.操作步驟口訣：開、貼、插、按","D.按電擊鈕前先清場，確認無人接觸病人"],ans:[1],expl:"病人體內若裝有心臟節律器或植入式去顫器，AED電擊貼片應避開節律器植入部位（間隔至少2.5～8公分）黏貼即可，並非完全「不能使用」AED，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。AED設計為傻瓜式操作，具備語音及圖示指引，一般民眾（非醫護人員）經簡單訓練後即可操作使用，是公眾急救的重要工具（A✓）；台灣教育推廣AED操作口訣為「開（打開電源）、貼（貼上電擊貼片）、插（插上插頭，部分機型免插）、按（按下電擊鈕）」，是常見教學記憶口訣（C✓）；按下電擊鈕前必須確認現場所有人皆未接觸病人身體，以避免電擊時傷及施救者或旁人，是操作AED的重要安全步驟（D✓）。"},{n:300,no:50,subj:"其他",q:"有關漢生病（Hansen's disease）俗稱痲瘋（leprosy）的照護措施，下列何者正確？",opts:["A.最常侵犯腸胃系統，應加強評估消化功能與營養狀態","B.照護時採接觸及呼吸道隔離","C.目前無治療藥物，採支持療法","D.皮膚病變僅出現在臉部"],ans:[1],expl:"漢生病（俗稱痲瘋病）主要侵犯周邊神經及皮膚，具低度傳染力，主要透過長期密切接觸病人的呼吸道飛沫傳染，故照護時建議採取接觸及呼吸道相關的防護措施（如適當的防護裝備），此為本題答案（B✓）。漢生病主要侵犯「皮膚與周邊神經系統」，並非腸胃系統，較少需要著重消化功能評估（A✗）；目前已有效的多重藥物治療（MDT，包含Dapsone、Rifampicin、Clofazimine等組合），並非無藥可治僅能支持療法（C✗）；漢生病的皮膚病變可能廣泛分布於全身皮膚（尤其周邊神經分布區域及較涼爽的體表部位），並非僅侷限於臉部（D✗）。"},{n:301,no:1,subj:"神經系統",q:"陳先生因車禍造成頸椎第5～6節完全損傷，已度過脊髓休克期，目前進行膀胱訓練，下列敘述何者正確？①屬於痙攣型神經性膀胱 ②只要薦神經受到刺激，即會反射排尿 ③可以利用Crede's method以手握拳，壓在膀胱，協助排空 ④當自解：餘尿量＝2：1，且餘尿小於100 mL表示膀胱訓練成功",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[0],expl:"本題答案為A（①②）。①屬於痙攣型（反射型）神經性膀胱：頸髓C5～6完全損傷屬薦髓（S2～S4排尿中樞）以上的上運動神經元損傷，已度過脊髓休克期後，薦髓排尿反射弧仍完整，膀胱會呈現反射亢進、痙攣型態，此敘述正確。②只要薦神經受到刺激即會反射排尿：因排尿反射弧位於薦髓且未受損，適當的薦神經刺激（如恥骨上叩擊）確實可誘發反射性排尿，此敘述正確。③Crede's method（以手握拳下壓膀胱協助排空）主要適用於下運動神經元損傷造成的鬆弛型（無反射型）膀胱，對痙攣型膀胱而言，人工加壓反而可能誘發自主神經反射亢進（autonomic dysreflexia）或膀胱輸尿管逆流，並非適用於本案例（③✗）。④膀胱訓練成功的公認標準是「餘尿量小於100 mL，且自解尿量與導尿（餘尿）量之比達3：1」，本題敘述之比例為2：1，數字有誤（④✗）。"},{n:302,no:2,subj:"神經系統",q:"有關癲癇病人發作時的護理措施，下列敘述何者錯誤？",opts:["A.病人若是在床上，可先移開頭部枕頭","B.確認周邊氧氣及抽吸設備功能","C.發作時意識不清，須隨時叫醒病人","D.發作時，可讓病人側臥以利唾液流出"],ans:[2],expl:"本題答案為C。癲癇發作時病人意識不清、肌肉不自主收縮，此時嘗試「隨時叫醒病人」既不可能達成（發作中無法被喚醒），強行搖晃刺激更可能增加病人受傷風險，此為錯誤的護理措施，為本題答案。癲癇發作的正確護理原則是移開頭部周圍枕頭等硬物以防外傷（A✓）、確保氧氣及抽吸設備隨時可用以因應發作後可能的呼吸道問題（B✓）、發作時協助側臥使唾液分泌物順利流出以維持呼吸道通暢（D✓）。"},{n:303,no:3,subj:"神經系統",q:"額葉腦瘤病人，最可能出現下列何項臨床表徵？",opts:["A.感覺異常、左右辨向障礙、部位失認","B.注意力不集中、短期記憶喪失、偏癱","C.運動失調、失去平衡","D.視野缺損、視覺辨識不能"],ans:[1],expl:"本題答案為B。額葉主司執行功能、注意力、短期記憶及初級運動皮質，額葉腫瘤最常表現為人格改變、注意力不集中、短期記憶喪失，並因侵犯運動皮質而出現對側偏癱，此為本題答案。感覺異常、左右辨向障礙、部位失認是頂葉病灶的典型表現（A✗）；運動失調、失去平衡是小腦病灶的典型表現（C✗）；視野缺損、視覺辨識不能是枕葉病灶的典型表現（D✗）。"},{n:304,no:4,subj:"神經系統",q:"有關病人脊椎手術後48小時內的護理措施，下列敘述何者錯誤？",opts:["A.評估神經功能的改變，尤其是手腳的感覺運動功能","B.病人解便時，須採圓滾木式翻身及使用一般便盆","C.床墊可採用中硬度的床墊","D.注意傷口是否有腦脊髓液滲漏"],ans:[1],expl:"本題答案為B。脊椎手術後病人如廁應盡量避免脊椎彎曲及用力，臨床上應使用「骨折便盆（fracture pan）」這類較扁平、不需抬高臀部或彎曲脊椎即可置入的便盆，而非需要抬臀、增加脊椎屈曲角度的一般便盆，此描述之護理措施有誤，為本題答案（B✗，題目問「何者錯誤」；圓滾木式翻身本身是正確技巧，但搭配一般便盆才是錯誤所在）。評估神經功能變化、尤其手腳感覺運動功能，是術後監測神經血管狀態的必要措施（A✓）；床墊選用中硬度可兼顧脊椎支撐與臥床舒適度（C✓）；注意傷口是否有腦脊髓液滲漏，是脊椎手術後重要的併發症觀察重點（D✓）。"},{n:305,no:5,subj:"神經系統",q:"有關巴金森氏症病人的自我照顧指導，下列敘述何者錯誤？",opts:["A.因多種藥物會造成便秘的情形，建議多攝取水分和高纖食物","B.可以洗澡後塗抹潤膚乳液，並觀察有無產生壓傷","C.因多巴胺製劑藥物副作用影響，病人會出現血壓高的情形，每日需要監測血壓","D.上衣的選擇應該以開前襟用魔鬼氈，褲子則是寬鬆不用腰帶"],ans:[2],expl:"本題答案為C。左旋多巴等多巴胺製劑常見的副作用之一是姿位性低血壓（orthostatic hypotension），而非高血壓，故護理指導應著重姿勢改變時監測血壓與預防跌倒，而非監測「血壓過高」的情形，此敘述之方向有誤，為本題答案（C✗，題目問「何者錯誤」）。抗巴金森藥物具抗膽鹼作用，容易造成便秘，鼓勵攝取水分與高纖飲食是正確指導（A✓）；因病人常合併皮脂分泌異常及活動力下降，洗澡後塗抹潤膚乳液並觀察皮膚有無壓傷是適當措施（B✓）；因病人精細動作及手部靈活度受限，選用魔鬼氈式開襟上衣、寬鬆免繫腰帶的褲子可提升病人自我照顧能力（D✓）。"},{n:306,no:6,subj:"神經系統",q:"下列何者不屬於腦幹功能評估？",opts:["A.瞳孔對光反射","B.肱二頭肌反射","C.角膜反射","D.作嘔反射"],ans:[1],expl:"本題答案為B。肱二頭肌反射（biceps reflex）是屬於C5～C6脊髓節的深腱反射，用於評估周邊脊神經反射弧是否完整，並非腦幹功能評估項目，為本題答案。瞳孔對光反射反映中腦功能（A為腦幹評估項目）；角膜反射反映橋腦（三叉神經與顏面神經，CN V、VII）功能（C為腦幹評估項目）；作嘔反射反映延腦（舌咽神經與迷走神經，CN IX、X）功能（D為腦幹評估項目）。"},{n:307,no:7,subj:"消化系統",q:"若母親的HBsAg與HBeAg皆為陽性，其所生的新生兒於出生24小時內需接受下列何種注射？",opts:["A.干擾素","B.類固醇","C.B型肝炎疫苗","D.B型肝炎免疫球蛋白"],ans:[3],expl:"本題答案為D。母親HBsAg與HBeAg皆為陽性，代表病毒量高、傳染力強（高複製狀態），新生兒垂直感染風險極高，除了常規的B型肝炎疫苗主動免疫外，針對此高風險新生兒，臨床上須在出生24小時內另外加打B型肝炎免疫球蛋白（HBIG）進行被動免疫，才能提供即時的保護，此為本題答案所強調的關鍵加強措施。干擾素並非新生兒常規預防注射項目（A✗）；類固醇與B肝母嬰垂直傳染預防無關（B✗）；B型肝炎疫苗本身固然也應施打，但單靠疫苗誘發主動免疫需要時間產生抗體，對於高傳染力（HBeAg陽性）母親的新生兒，仍須合併HBIG被動免疫才足夠即時、有效（C相對非本題強調的重點）。"},{n:308,no:8,subj:"消化系統",q:"有關腹腔鏡檢查的敘述，下列何者正確？",opts:["A.過於肥胖為禁忌症之一","B.檢查前測量病人的凝血酶原時間（PT）為20秒，可執行此檢查","C.插入腹腔鏡前需請個案大口吐氣後並摒住呼吸","D.檢查時因灌入二氧化碳會引起後腰部抽痛"],ans:[0],expl:"本題答案為A。過度肥胖的病人腹壁較厚，會增加氣腹建立與器械操作的困難度，且合併症風險較高，是腹腔鏡檢查的相對禁忌症之一，此為本題答案。凝血酶原時間（PT）正常約11～13.5秒，20秒已明顯延長，代表凝血功能異常，屬於出血高風險族群，應暫緩檢查而非「可以執行」（B✗）；插入腹腔鏡（如Veress針）前，臨床上是請病人深吸氣後閉氣以固定腹壁位置，並非「大口吐氣後摒住呼吸」（C✗，吐氣與吸氣方向相反）；檢查時灌入二氧化碳建立氣腹，因刺激橫膈及膈神經，典型會引起「肩部（尤其右肩）轉移痛」，而非後腰部抽痛（D✗）。"},{n:309,no:9,subj:"消化系統",q:"有關消化性潰瘍藥物治療之目的，下列何者錯誤？",opts:["A.中和胃酸","B.促進胃排空","C.減少胃酸分泌","D.保護黏膜屏障"],ans:[1],expl:"本題答案為B。消化性潰瘍藥物治療的核心目的是中和已分泌的胃酸、減少胃酸分泌，以及保護潰瘍處黏膜屏障，「促進胃排空」並非消化性潰瘍藥物治療的常規目的（部分促進腸胃蠕動的藥物用於特定適應症，但非消化性潰瘍治療的核心目標），此為本題答案（B✗，題目問「何者錯誤」）。制酸劑可中和胃酸（A✓）；氫離子幫浦阻斷劑、H2受體阻斷劑可減少胃酸分泌（C✓）；黏膜保護劑（如sucralfate）可覆蓋潰瘍面形成保護屏障（D✓）。"},{n:310,no:10,subj:"消化系統",q:"常見肝硬化形成腹水的原因，下列何者正確？",opts:["A.左心衰竭導致液體滯留","B.血漿白蛋白不足導致血管靜水壓（hydrostatic pressure）上升","C.醛固酮作用亢進（hyperaldosteronism）導致鈉及水滯留增加","D.門脈高壓導致血漿膠質滲透壓（colloid osmotic pressure）上升"],ans:[2],expl:"本題答案為C。肝硬化因肝臟結構破壞、有效循環血量相對不足，會刺激腎素—血管收縮素—醛固酮系統（RAAS）代償性活化，造成醛固酮作用亢進，促使腎臟保鈉保水，是肝硬化腹水形成的重要機轉之一，此為本題答案。左心衰竭導致的是肺循環鬱血（肺水腫），並非肝硬化腹水的成因（A✗）；血漿白蛋白不足應導致「血管膠質滲透壓下降」，而非血管靜水壓上升，此敘述之機轉名稱與方向皆有誤（B✗）；門脈高壓導致的是「肝竇及內臟微血管靜水壓上升」，血漿膠質滲透壓則因低白蛋白而是「下降」，並非上升，此敘述同樣把機轉名稱與方向弄反（D✗）。"},{n:311,no:11,subj:"消化系統",q:"有關急性胰臟炎的處置，下列敘述何者最不適當？",opts:["A.腹痛尚未改善前必須禁食","B.放置鼻胃管引流以抑制胰液（酵素）分泌","C.協助病人採取側臥彎曲膝蓋姿勢以減輕疼痛","D.康復期飲食應採高脂肪、高蛋白質、高醣類"],ans:[3],expl:"本題答案為D。急性胰臟炎康復期飲食原則應採「低脂肪」、適量蛋白質及醣類的漸進式飲食，因脂肪會刺激膽囊收縮素（CCK）分泌，進而刺激胰液分泌，加重胰臟負擔，故「高脂肪」飲食建議並不適當，為本題答案（D✗，題目問「何者最不適當」）。腹痛未改善前禁食，可使胰臟獲得休息、減少胰液分泌刺激（A✓）；放置鼻胃管引流可減少食糜進入十二指腸，間接抑制胰液分泌（B✓）；側臥彎曲膝蓋（屈膝側臥）姿勢可放鬆腹壁張力，減輕胰臟發炎引起的疼痛（C✓）。"},{n:312,no:12,subj:"骨骼肌肉",q:"下列何者為診斷骨髓炎最準確的方法？",opts:["A.骨密度測量","B.關節穿刺術","C.關節腔鏡檢查","D.骨骼組織切片"],ans:[3],expl:"本題答案為D。骨骼組織切片（骨切片病理及細菌培養檢查）可直接取得受感染骨組織進行病理與微生物學確診，是診斷骨髓炎最準確、最具確定性的方法（黃金標準），為本題答案。骨密度測量評估的是骨質流失程度，與感染診斷無關（A✗）；關節穿刺術主要用於診斷關節腔內感染（如化膿性關節炎），並非直接針對骨髓感染（B✗）；關節腔鏡檢查同樣以關節內部病灶為主要評估對象，非診斷骨髓炎的標準方法（C✗）。"},{n:313,no:13,subj:"骨骼肌肉",q:"病人因骨腫瘤接受右腳膝上截肢的照護措施，下列何者最適當？",opts:["A.協助其右腳保持平直外展，以防屈曲攣縮","B.協助於右腳殘肢使用彈性繃帶，以控制水腫","C.教導其右腳殘肢勿做運動，以防縫線破裂","D.教導不可採俯臥姿，以防關節屈曲"],ans:[1],expl:"本題答案為B。截肢術後殘肢使用彈性繃帶包紮，可協助控制水腫、形塑殘肢外型以利未來裝配義肢，是標準的殘肢照護措施，為本題答案。膝上截肢病人應避免髖關節「外展」姿勢，以防外展攣縮，「保持平直外展」的敘述方向有誤，正確應著重避免外展、避免長時間屈髖（A✗）；殘肢應在術後傷口穩定後，依復健計畫循序漸進進行肌力訓練及關節活動，並非完全不運動，以維持關節活動度、預防攣縮（C✗）；反而應鼓勵病人「規律採俯臥姿」（每日數次、每次一段時間），以伸展髖關節、預防髖關節屈曲攣縮，並非禁止俯臥（D✗）。"},{n:314,no:14,subj:"感官系統",q:"下列何者是視網膜剝離最主要的疾病機轉？",opts:["A.視網膜喪失營養供應","B.水晶體混濁","C.眼內壓上升","D.眼角膜受損"],ans:[0],expl:"本題答案為A。視網膜剝離是指神經感覺層視網膜與其下的色素上皮層分離，使視網膜失去來自脈絡膜的血流及營養供應，導致感光細胞受損、視覺功能喪失，此為視網膜剝離最主要的疾病機轉，為本題答案。水晶體混濁是白內障的機轉（B✗）；眼內壓上升是青光眼的機轉（C✗）；眼角膜受損與視網膜剝離的病理機轉無直接關聯（D✗）。"},{n:315,no:15,subj:"感官系統",q:"有關美尼爾氏症（Meniere's syndrome）之敘述，下列何者正確？①內耳淋巴水腫引起 ②眩暈及耳朵疼痛是典型症狀 ③可能導致單側傳導性聽力喪失 ④耳鳴是典型症狀",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"本題答案為B（①④）。①內耳淋巴水腫（endolymphatic hydrops）被認為是美尼爾氏症的核心病理機轉，此敘述正確；④耳鳴是美尼爾氏症典型三主症（眩暈、耳鳴、聽力喪失）之一，此敘述正確，選①④＝B（本題答案）。美尼爾氏症典型症狀是「眩暈」而非耳朵疼痛，耳朵疼痛並非其特徵性症狀（②錯誤）；美尼爾氏症造成的聽力喪失屬於內耳（耳蝸）病變導致的「感音性」聽力喪失，並非傳導性聽力喪失（③錯誤，傳導性聽損多為外耳、中耳病變所致）。"},{n:316,no:16,subj:"感官系統",q:"有關全喉切除術後的護理指導，下列敘述何者正確？",opts:["A.術後頸部應採過度伸張姿勢","B.術後第3天可教導病人開始吞嚥","C.不鼓勵咳出痰液，呼吸道分泌物一律從氣切口抽吸","D.術後約2～4週可開始進行語言復健"],ans:[3],expl:"本題答案為D。全喉切除術後病人需重新學習發聲方式（如食道語、電子喉或氣管食道瘻語音復健），一般約在術後2～4週、待傷口初步癒合穩定後才開始進行語言復健訓練，此為本題答案。術後頸部應維持「自然或微前屈」姿勢，避免過度伸張造成縫合處張力增加，並非採過度伸張姿勢（A✗）；術後吞嚥訓練通常需待傷口與吞嚥功能評估穩定後才逐步進行，術後第3天即開始教導吞嚥為時過早（B✗）；全喉切除病人氣道與食道已完全分離，仍應鼓勵病人自行咳出痰液、訓練經氣切口有效咳嗽排痰，而非一律仰賴抽吸，過度依賴抽吸反而增加黏膜損傷風險（C✗）。"},{n:317,no:17,subj:"感官系統",q:"有關慢性鼻竇炎的原因，下列何者正確？",opts:["A.由於急性鼻竇炎未完全治療所致","B.與鼻息肉生成無關","C.常由流行性感冒嗜血桿菌引起","D.常見的感染致病菌為好氧菌"],ans:[0],expl:"本題答案為A。慢性鼻竇炎多是因急性鼻竇炎未完全治療、發炎反覆遷延所致，此為本題答案。鼻息肉的形成與慢性鼻竇炎的黏膜慢性發炎反應密切相關，兩者並非無關，臨床上鼻息肉甚至可能阻塞鼻竇開口、加重慢性鼻竇炎（B✗）；流行性感冒嗜血桿菌（Haemophilus influenzae）較常見於「急性」細菌性鼻竇炎，並非慢性鼻竇炎的典型致病菌（C✗）；慢性鼻竇炎常見致病菌組成中厭氧菌占相當比例（常為需氧菌與厭氧菌混合感染），並非單純好氧菌感染為主（D✗）。"},{n:318,no:18,subj:"心臟血管",q:"有關心臟去纖維震顫器使用的敘述，下列何者錯誤？",opts:["A.避免於氧氣帳內使用","B.測試功能時，電擊板須對空進行放電","C.放電時，不可碰觸病人或病床","D.常見的合併症為皮膚灼傷"],ans:[1],expl:"本題答案為B。去顫器測試功能或確認電擊板放電功能時，絕對不可對空放電，應將電擊板置於機器內建的測試裝置（tester）上進行測試，對空放電屬於危險且錯誤的操作方式，可能造成周遭人員意外電擊傷害，此為本題答案（B✗，題目問「何者錯誤」）。因高濃度氧氣環境有火花風險，去顫時應避免在充氧氣帳內操作（A✓）；放電當下不可碰觸病人或病床，以防操作者或旁人遭電擊（C✓）；皮膚灼傷是去顫術常見的合併症之一（D✓）。"},{n:319,no:19,subj:"心臟血管",q:"有關Dopamine作用的敘述，下列何者正確？①2 μg/kg/min會增加心肌的自動性，因此可減少心室節律障礙 ②可治療低血容量性休克 ③5～10 μg/kg/min主要作用是增加腎血流量 ④大於10 μg/kg/min作用是末梢血管收縮",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[3],expl:"本題答案為D（②④）。②Dopamine可作為休克病人升壓/強心藥物治療選項之一，於適當輸液復甦後可合併使用以支持血壓與器官灌流，此敘述可視為正確；④高劑量（大於10 μg/kg/min）時，Dopamine之α１腎上腺素受體作用顯著增強，主要造成末梢血管收縮、周邊阻力上升，此敘述正確，選②④＝D（本題答案）。低劑量（約2 μg/kg/min，「腎劑量」）主要作用是活化多巴胺受體，造成腎臟及腸繫膜血管擴張、增加腎血流量，而非「增加心肌自動性以減少心室節律障礙」，此敘述之藥理機轉描述有誤，且理論上增加心肌自動性應是「增加」而非「減少」心律不整風險（①錯誤）；5～10 μg/kg/min屬於中劑量範圍，此時β1腎上腺素受體作用漸增，主要表現為心跳與心收縮力增加，「增加腎血流量」是低劑量（腎劑量）範圍的作用，此劑量與藥理作用的配對有誤（③錯誤）。"},{n:320,no:20,subj:"心臟血管",q:"有關心臟衰竭病人的照護，下列何者正確？①採高坐臥姿勢可以減少心臟後負荷 ②限水限鹽分的攝取是為了減少前負荷 ③使用動脈血管擴張劑可以降低周邊血管阻力及後負荷 ④使用嗎啡可以改善呼吸喘但無法減輕心臟負荷",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[2],expl:"本題答案為C（②③）。②限水限鹽可減少循環血量，是減少「前負荷」的標準護理措施，此敘述正確；③動脈血管擴張劑可降低全身周邊血管阻力，進而降低心臟「後負荷」，此敘述正確，選②③＝C（本題答案）。高坐臥姿勢主要作用是促進靜脈血液蓄積於下肢、減少靜脈回流（前負荷）並減輕肺鬱血、改善呼吸型態，較主要影響的是前負荷及呼吸舒適度，而非直接「減少後負荷」，此敘述之機轉配對有誤（①錯誤）；嗎啡除鎮靜、緩解呼吸喘不適外，本身亦具有輕度靜脈及動脈擴張作用，能協助降低前負荷與部分後負荷，並非「無法減輕心臟負荷」，此敘述低估了嗎啡的血流動力學效益（④錯誤）。"},{n:321,no:21,subj:"心臟血管",q:"有關生物性心瓣膜特性的敘述，下列何者錯誤？",opts:["A.術後須終身服用抗凝血藥物","B.耐用性較差","C.適合有生育計畫的婦女使用","D.瓣膜開關時的聲音較小"],ans:[0],expl:"本題答案為A。終身服用抗凝血藥物（warfarin）是「機械瓣膜」植入後的必要治療，因機械瓣膜表面易誘發血栓形成；生物性瓣膜血栓風險較低，通常僅需短期（約數個月）抗凝治療後改為抗血小板藥物即可，並非終身服用抗凝血藥物，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。生物性瓣膜耐用性確實較機械瓣膜差，約使用10～15年後可能需再次置換，此描述正確（B✓）；因不需終身抗凝治療，生物性瓣膜較適合有生育計畫、需考量warfarin致畸胎風險的婦女使用（C✓）；生物性瓣膜開關時產生的聲音較機械瓣膜輕柔、不易聽見咔嗒聲，此描述正確（D✓）。"},{n:322,no:22,subj:"心臟血管",q:"有關冠狀動脈繞道手術後護理，下列敘述何者錯誤？",opts:["A.當小便量減少時，須監測血中鉀離子濃度","B.當縱膈腔引流管（P-R tube）引流量＞100 mL/hr，須監測凝血功能","C.監測心律並注意傷口是否出血","D.當凝血酶原時間（PT）延長時，須注射Protamine Sulfate"],ans:[3],expl:"本題答案為D。Protamine Sulfate是「Heparin」的專一性拮抗劑，用於中和肝素的抗凝血作用，臨床上是依aPTT（活化部分凝血酶原時間）評估肝素效果；而PT（凝血酶原時間）延長多與Warfarin治療或維生素K依賴性凝血因子不足有關，其對應的處置應是給予維生素K或新鮮冷凍血漿，而非注射Protamine Sulfate，此配對錯誤，為本題答案（D✗，題目問「何者錯誤」）。小便量減少可能反映腎灌流不足或急性腎損傷，須警覺高血鉀風險並監測血鉀（A✓）；縱膈腔引流管引流量過大提示可能有活動性出血，須進一步監測凝血功能（B✓）；密切監測心律及傷口出血情形是心臟手術後的基本護理內容（C✓）。"},{n:323,no:23,subj:"腫瘤血液",q:"病人初次確診為缺鐵性貧血，醫囑須服用鐵劑，下列護理指導何者正確？",opts:["A.可以正常喝茶","B.鐵劑建議在兩餐之間空腹服用","C.服用鐵劑時可以搭配牛奶一起使用","D.服用鐵劑可以同時吃玉米"],ans:[1],expl:"本題答案為B。鐵劑於「空腹」（兩餐之間）服用可獲得最佳吸收率，此為標準護理指導，為本題答案（若腸胃不適明顯，臨床上會視情況調整為隨餐服用，但就吸收效果的標準教學而言，空腹服用是原則）。茶葉中的單寧酸（鞣酸）會與鐵離子結合形成不易吸收的複合物，應避免與鐵劑同時飲用，並非可以正常喝茶（A✗）；牛奶中的鈣質同樣會與鐵離子競爭、抑制鐵吸收，不宜與鐵劑同時服用（C✗）；玉米等富含植酸的食物也會抑制鐵吸收，並不建議與鐵劑同時食用（D✗）。"},{n:324,no:24,subj:"腫瘤血液",q:"乳腺癌病人出現意識混亂、嗜睡、虛弱、心律不整、嘔吐及便秘，下列何者為其最可能發生的癌症合併症？",opts:["A.腫瘤溶解症候群","B.上腔靜脈症候群","C.脊髓壓迫","D.高血鈣症"],ans:[3],expl:"本題答案為D。意識混亂、嗜睡、虛弱、心律不整、噁心嘔吐及便秘，是高血鈣症的典型臨床表現（可用口訣「bones, stones, groans, psychiatric overtones」理解：骨骼疼痛、腎結石、腸胃不適、精神狀態改變），乳癌骨轉移是導致癌症相關高血鈣症的常見原因，此為本題答案。腫瘤溶解症候群典型是高血鉀、高血磷、高尿酸合併低血鈣，通常發生於化療後高增殖性腫瘤（如淋巴癌、白血病），與本題症狀組合及乳癌情境較不吻合（A✗）；上腔靜脈症候群典型表現為顏面、頸部、上肢腫脹及呼吸困難，並非此處描述的意識改變、心律不整、腸胃症狀組合（B✗）；脊髓壓迫典型表現為背痛、運動或感覺功能缺損，與本題症狀組合不符（C✗）。"},{n:325,no:25,subj:"腫瘤血液",q:"有關何杰金氏病（Hodgkin's Disease）的敘述，下列何者正確？",opts:["A.安阿伯（Ann Arbor）臨床分期系統第II期指侵犯橫膈膜兩側的淋巴結區域","B.淋巴結切片可能發現梨特史登堡氏細胞（Reed-Sternberg Cell, RS細胞）","C.常見症狀包含吞嚥困難、肝脾腫大","D.血清生化值可發現C反應性蛋白（CRP）、鈣離子下降"],ans:[1],expl:"本題答案為B。淋巴結切片發現梨特史登堡氏細胞（Reed-Sternberg cell）是何杰金氏病的病理診斷特徵性表現，為本題答案。Ann Arbor分期系統中，第II期是指「橫膈膜同一側」兩個或以上淋巴結區域受侵犯，侵犯橫膈膜「兩側」淋巴結區域屬於第III期，此敘述之分期定義有誤（A✗）；何杰金氏病常見症狀以無痛性淋巴結腫大及發燒、盜汗、體重減輕等「B症狀」為主，吞嚥困難並非其典型症狀（C✗）；何杰金氏病活動期常伴隨發炎指標上升（如CRP上升），而非CRP、鈣離子皆下降，此敘述之數值變化方向有誤（D✗）。"},{n:326,no:26,subj:"腫瘤血液",q:"病人於化學治療後抽血報告顯示WBC 3,000/μL、Platelet 30,000/μL、Hb 12g/dL，下列照護措施何者最適宜？",opts:["A.給予非類固醇抗發炎藥物治療發燒、疼痛","B.建議病人使用電動牙刷徹底清潔口腔","C.給予甘油灌腸避免便秘而閉氣用力","D.天冷時鼻黏膜塗擦凡士林保濕"],ans:[3],expl:"本題答案為D。病人WBC 3,000/μL（低下，易感染）、Platelet 30,000/μL（低下，易出血），照護重點應同時兼顧感染與出血防護；天冷時鼻黏膜易乾燥龜裂，塗擦凡士林保濕可預防黏膜損傷出血及降低病原入侵風險，屬溫和適當的照護措施，為本題答案。非類固醇消炎止痛藥（NSAID）會抑制血小板功能並可能造成腸胃道出血，血小板低下病人應避免使用（A✗）；電動牙刷刷毛較硬、力道較大，容易造成牙齦損傷出血，血小板低下病人應改用軟毛牙刷輕柔清潔口腔（B✗）；甘油灌腸屬侵入性直腸操作，可能造成黏膜損傷出血及增加感染部位，對嗜中性白血球低下合併血小板低下的病人應避免，宜改採軟便劑等較溫和方式處理便秘（C✗）。"},{n:327,no:27,subj:"腫瘤血液",q:"病人剛接受骨髓移植2週，主訴右上腹痛，評估有黃疸、腹水，下列何者是病人最有可能發生的問題？",opts:["A.感染","B.急性移植物抗宿主疾病（GVHD）","C.肝靜脈阻塞（Veno-occlusive disease, VOD）","D.腸阻塞"],ans:[2],expl:"本題答案為C。骨髓移植後2週內出現右上腹痛、黃疸、腹水三大表現，是肝靜脈阻塞疾病（VOD，現稱竇狀隙阻塞症候群SOS）的典型臨床三主症，好發於移植後前3週內，此為本題答案。感染雖為移植後常見合併症，但通常以發燒為主要表現，無法完整解釋此三主症組合（A✗）；急性移植物抗宿主疾病常見表現為皮疹、腹瀉及肝功能異常，好發時間點與症狀組合皆與VOD典型三主症有所差異，此處症狀更吻合VOD（B✗）；腸阻塞主要表現為腹脹、嘔吐、排便排氣停止，無法解釋黃疸及腹水（D✗）。"},{n:328,no:28,subj:"腫瘤血液",q:"有關頭頸部放射治療對口腔造成的影響，下列處置何者正確？",opts:["A.採高纖飲食訓練口頰肌肉，以避免牙關緊閉","B.整天持續配戴活動假牙，以避免齒齦萎縮後不合口","C.nystatin（Mycostatin®）含漱後吞服治療細菌感染","D.四級口腔黏膜炎可規律給予全身性止痛劑緩解"],ans:[3],expl:"本題答案為D。第四級口腔黏膜炎屬嚴重等級（可能影響進食甚至需管灌營養），此時應規律（非僅按需）給予全身性止痛劑（必要時可能需使用鴉片類藥物）以有效控制疼痛，維持病人生活品質及進食能力，此為本題答案。高纖飲食與訓練口頰肌肉、預防牙關緊閉（張口困難）並無直接關聯，預防牙關緊閉應著重規律的張口運動訓練，而非飲食纖維量（A✗）；口腔黏膜炎期間持續配戴活動假牙容易摩擦受損黏膜、加重潰瘍不適，一般建議除進食外應取下活動假牙，而非整天配戴（B✗）；Nystatin是「抗黴菌」藥物，用於治療口腔念珠菌（黴菌）感染，並非治療細菌感染，此藥物與感染類型配對錯誤（C✗）。"},{n:329,no:29,subj:"其他",q:"病人因住宅火警遭燒傷，身體後背部、右後上肢、左後上肢及左右臀部燒傷，以蘭德—布諾得（Lund & Browder）方法計算燒傷範圍，下列何者正確？",opts:["A.27%","B.32%","C.36%","D.45%"],ans:[0,1,2,3],expl:"官方公告本題「一律給分」，故不論選擇何選項皆計分。本題以蘭德—布諾得法計算特定燒傷部位組合（後背部、雙側後上臂、雙側臀部）之總燒傷面積，由於「後上肢」在不同教科書版本或圖表中，可能被理解為僅計算上臂後側局部比例，也可能被理解為包含前臂在內的整個上肢後側區域，加上臀部在部分燒傷面積圖表中被歸入軀幹後側計算、部分則獨立列出比例，不同教材對這類細部區域的切分方式並非完全一致，容易造成計算結果的合理歧異，考選部因而認定本題具爭議性並公告一律給分。護理應考重點應放在蘭德—布諾得法的核心概念本身：其依年齡調整各部位體表面積比例，較「九法則（Rule of Nines）」更精確，是臨床評估燒傷面積的標準工具之一。"},{n:330,no:30,subj:"其他",q:"承上題，病人體重65公斤，其靜脈液體補充，依據帕克蘭公式（Parkland formula）24小時內的第一個8小時應給予多少液體？",opts:["A.2,550 mL","B.3,650 mL","C.3,850 mL","D.4,160 mL"],ans:[0,1,2,3],expl:"官方公告本題「一律給分」，故不論選擇何選項皆計分。本題為承接上題（第29題）之延伸計算，須先以第29題所得的燒傷體表面積百分比（%TBSA）代入帕克蘭公式（Parkland formula：24小時輸液總量＝4 mL×體重(kg)×%TBSA，其中前8小時給予總量的一半，後16小時平均給予剩餘一半）方能求得答案；由於第29題之燒傷面積本身已因教材認定差異而具爭議、一律給分，第30題的計算結果自然隨之失去單一標準答案的基礎，故一併公告一律給分。護理應考重點應放在帕克蘭公式的操作邏輯本身：燒傷後24小時內輸液採「前8小時給一半、後16小時給另一半」的分配原則，以避免燒傷初期微血管通透性劇增期間輸液不足或過量。"},{n:331,no:31,subj:"其他",q:"有關後天免疫缺乏症候群（AIDS）病人防護措施的敘述，下列何者正確？",opts:["A.若工作人員是孕婦，需加強洗手、穿隔離衣","B.針頭必須回套，以避免刺傷","C.被血液、體液污染的物品，應用漂白水處理","D.執行技術前，皆應戴上口罩或護目鏡"],ans:[2],expl:"本題答案為C。血液、體液污染的物品或環境表面，可用漂白水（次氯酸鈉）稀釋液進行消毒，是預防包含HIV在內之血液傳染病原擴散的標準感染管制措施，為本題答案。標準防護措施（standard precautions）原則上適用於所有病人與所有醫護人員，並非僅因工作人員懷孕而特別加強，防護措施的選用應依「暴露風險」而非工作人員個人生理狀態決定（A✗）；針頭絕對禁止回套，回套動作是造成醫護人員針扎意外最常見的原因之一，此為感染管制的基本安全原則（B✗）；口罩或護目鏡是用於「有可能發生血液體液噴濺」之技術操作時使用，並非執行「所有」技術前皆須配戴，此敘述過於絕對化（D✗）。"},{n:332,no:32,subj:"泌尿系統",q:"有關器官移植後的護理指導，下列何者錯誤？",opts:["A.鼓勵運動多曬太陽，以增進身心健康","B.避免出入公共場所，外出戴口罩","C.服藥出現藥物副作用，不可自行停藥","D.需要暫時避孕，若準備懷孕應停藥至少2至3週"],ans:[0],expl:"本題答案為A。器官移植病人術後須長期服用免疫抑制劑，皮膚對紫外線的防禦力與整體免疫防禦力皆下降，長期或大量曝曬陽光會增加皮膚癌等病變風險，故應建議病人做好防曬措施，而非「多曬太陽」，此敘述有誤，為本題答案（A✗，題目問「何者錯誤」）。因免疫功能受抑制，感染風險增加，應避免出入人多的公共場所、外出戴口罩以降低感染機會（B✓）；免疫抑制劑相關的藥物副作用應由醫療團隊評估調整，病人不可自行停藥，以免引發排斥反應（C✓）；藥物（如mycophenolate等）可能具致畸胎性，若病人有懷孕計畫，應與醫療團隊討論後暫時採取避孕措施並依醫囑調整用藥時程（D✓）。"},{n:333,no:33,subj:"骨骼肌肉",q:"有關全身性紅斑性狼瘡（SLE）病人的診斷檢查結果，下列何者正確？",opts:["A.白血球數目增加","B.紅血球沉降速率下降","C.抗核性抗體（ANA）呈現陽性反應","D.血清中的補體C3和C4高於正常值"],ans:[2],expl:"本題答案為C。抗核性抗體（ANA）陽性反應是全身性紅斑性狼瘡（SLE）最具敏感性的篩檢指標之一，超過九成以上的SLE病人呈現陽性，此為本題答案。SLE活動期常見「白血球數目減少」（白血球低下），並非增加（A✗）；SLE活動期發炎反應旺盛，紅血球沉降速率（ESR）通常「上升」，並非下降（B✗）；SLE活動期因免疫複合體大量消耗補體，血清補體C3、C4濃度通常「低於」正常值，並非高於正常值（D✗）。"},{n:334,no:34,subj:"呼吸系統",q:"病人接受左肺切除術後使用胸管，下列護理措施何者最適當？",opts:["A.監測水封瓶內液面的波動","B.每班夾住胸管一次","C.鼓勵咳嗽和深呼吸","D.每2小時擠壓胸管一次"],ans:[2],expl:"本題答案為C。鼓勵病人咳嗽及深呼吸，有助於促進肺部擴張、預防肺塌陷及肺炎等併發症，是胸腔手術後使用胸管期間最基本且普遍適用的護理措施，為本題答案。胸管原則上不應例行性常規夾管，因可能造成張力性氣胸等危險，僅在特定醫囑及情境下才會短暫夾管，並非每班常規執行（B✗）；胸管的常規「擠壓（milking/stripping）」目前多已不建議例行操作，因可能造成胸腔內瞬間負壓過大等併發症，僅在特定阻塞情形下依醫囑執行，並非每2小時常規擠壓（D✗）；監測水封瓶內液面隨呼吸出現波動（tidaling）確為胸管照護的重要觀察項目，但整體而言，鼓勵咳嗽深呼吸更是普遍適用、最基本優先的照護措施（A為合理措施但非本題最適答案）。"},{n:335,no:35,subj:"呼吸系統",q:"病人的動脈血液氣體分析報告為pH 7.36，PaO2 88 mmHg，PaCO2 50 mmHg，HCO3- 25 mEq/L，下列措施何者應為最優先？",opts:["A.立即通知主治醫師","B.為病人戴上氧氣鼻套管","C.用脈衝式血氧測定儀測量","D.協助病人翻身並鼓勵其深呼吸咳嗽"],ans:[3],expl:"本題答案為D。此動脈血液氣體分析結果pH 7.36（正常偏酸端但仍在正常範圍7.35～7.45內）、PaCO2 50 mmHg（略高於正常35～45 mmHg）、HCO3- 25 mEq/L（略高於正常22～26 mEq/L上緣），呈現輕度、已代償或接近代償的呼吸性酸中毒，PaO2 88 mmHg屬於尚可接受的氧合狀態。此數值變化不屬於緊急狀況，最優先且合宜的處置應是協助病人翻身並鼓勵深呼吸咳嗽，以促進肺部擴張、改善通氣量，處理輕度換氣不足的根本原因，為本題答案。此結果尚未達到需要「立即」通知醫師的緊急程度，可於處理後續評估再視情況回報（A非最優先）；PaO2 88 mmHg之氧合狀態尚可，此時的核心問題是通氣（CO2蓄積）而非氧合不足，戴上氧氣鼻套管並非解決通氣問題的根本措施（B非最優先）；以血氧監測儀測量僅屬於持續監測，並非能改善病人通氣狀況的主動處置（C非最優先）。"},{n:336,no:36,subj:"呼吸系統",q:"有關執行氣切造口術病人抽痰的敘述，下列何者不適當？",opts:["A.抽吸壓力120～150 mmHg","B.抽吸前給予氧氣吸入30～60秒","C.抽痰管插入深度15～20公分","D.抽痰完成後聽診呼吸音"],ans:[2],expl:"本題答案為C。氣切造口抽痰時，抽痰管插入深度應以「感到些微阻力後回抽1～2公分」為原則，一般教學建議深度多落在約10～15公分左右（依病人氣切管長度及個別解剖差異調整），若插入過深（如達15～20公分）容易誤觸並損傷氣管隆突或支氣管黏膜，增加出血及刺激迷走神經反射的風險，此敘述之深度數值偏高、不適當，為本題答案（C✗，題目問「何者不適當」；須留意鼻腔或口腔路徑抽痰因路徑較長，插入深度標準與氣切造口路徑不同，不可混用）。抽吸壓力120～150 mmHg屬於成人抽痰的建議壓力範圍（A✓）；抽吸前給予純氧吸入30～60秒可預防抽痰過程中發生低血氧（B✓）；抽痰完成後聽診呼吸音，可評估抽痰效果及呼吸道通暢程度（D✓）。"},{n:337,no:37,subj:"呼吸系統",q:"有關慢性阻塞性肺疾病（COPD）病人的護理照護計畫，下列何者應列為最優先處理？",opts:["A.自我照顧能力缺失","B.呼吸道清除功能失效","C.活動無耐力","D.調適障礙"],ans:[1],expl:"本題答案為B。依照氣道—呼吸—循環（ABC）的照護優先順序原則，「呼吸道清除功能失效」直接威脅病人氧合及通氣，屬於最優先須處理的生理性問題，應列為COPD病人照護計畫的最優先項目，為本題答案。自我照顧能力缺失（A）、活動無耐力（C）、調適障礙（D）皆是COPD病人可能面臨的重要護理問題，但其急迫性與對生命徵象的直接威脅程度，皆不及呼吸道清除功能失效優先。"},{n:338,no:38,subj:"呼吸系統",q:"下列何者為細菌性肺炎病人必要的診斷檢查？①胸部電腦斷層 ②胸部X光攝影 ③肺功能檢查 ④痰液檢查",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[3],expl:"本題答案為D（②④）。②胸部X光攝影可顯示肺部浸潤病灶，是診斷肺炎的基本影像學檢查；④痰液檢查（含培養、革蘭氏染色）可協助確認致病菌種類、指引抗生素選擇，兩者皆為細菌性肺炎診斷所需的必要檢查，選②④＝D（本題答案）。胸部電腦斷層並非細菌性肺炎診斷的常規必要檢查，通常保留給臨床表現不典型、懷疑合併症或診斷不明確時才進一步安排（①非必要）；肺功能檢查主要用於評估慢性肺部疾病（如氣喘、COPD）的通氣功能，並非急性細菌性肺炎診斷所需的檢查項目（③非必要）。"},{n:339,no:39,subj:"泌尿系統",q:"慢性腎臟病第四期病人解血尿懷疑是腎臟結石，下列診斷檢查何者最適當？",opts:["A.腹部超音波","B.腎動脈攝影","C.逆行性腎盂攝影","D.膀胱鏡檢查"],ans:[2],expl:"本題答案為C。病人已為慢性腎臟病第四期，腎功能明顯受損，應盡量避免使用經「靜脈注射」含碘顯影劑的檢查（如靜脈腎盂攝影、電腦斷層攝影），以防顯影劑腎病變加速腎功能惡化；逆行性腎盂攝影是經由膀胱鏡逆行將顯影劑直接注入腎盂、輸尿管，顯影劑不經全身血液循環代謝，可在避免全身性顯影劑腎毒性負擔的前提下，清楚評估疑似腎結石的部位，為本題於此情境下最適當的診斷檢查。腹部超音波雖無顯影劑及輻射疑慮、常作為疑似腎結石的第一線篩檢工具，但其對輸尿管中段等部位的結石偵測敏感度較受腸氣干擾影響，在需要更精確定位、且病人已是重度腎功能不全須避免全身性顯影劑的情境下，並非本題設定之最適答案（A非本題最適答案）；腎動脈攝影主要用於評估腎血管病灶（如腎動脈狹窄），並非診斷腎結石的常用檢查，且同樣需使用血管內顯影劑（B✗）；膀胱鏡檢查主要評估膀胱及尿道病灶，對上泌尿道（腎盂、輸尿管）結石的直接診斷價值有限（D✗）。"},{n:340,no:40,subj:"泌尿系統",q:"有關腎臟功能血液檢查，下列敘述何者正確？",opts:["A.尿素氮升高可能是脫水，不一定是表示腎臟功能不佳","B.尿素氮和肌酸酐不受飲食影響，檢查不需要空腹抽血","C.尿中肌酸酐排泄減少時，血中的肌酸酐也會隨之降低","D.當尿素氮值升高時，表示腎功能已喪失達50%以上"],ans:[0],expl:"本題答案為A。尿素氮（BUN）除反映腎功能外，也受到脫水、腸胃道出血、高蛋白飲食等「腎前性」因素影響而上升，故BUN上升不一定代表腎功能本身變差，此敘述正確，為本題答案。尿素氮受飲食蛋白質攝取量影響甚大，並非不受飲食影響、也並非不需空腹抽血（部分檢驗仍建議避免抽血前大量攝取蛋白質以避免干擾判讀）（B✗）；當腎臟排泄肌酸酐能力下降（尿中肌酸酐排泄減少）時，代謝廢物滯留於血中，血中肌酸酐應「上升」而非降低，此敘述方向相反（C✗）；尿素氮數值與腎功能喪失百分比並無如此精確的直接對應關係，且尿素氮易受多種腎前性因素干擾，此「50%以上」的絕對化描述並不準確（D✗）。"},{n:341,no:41,subj:"泌尿系統",q:"腎衰竭病人的飲食護理指導，下列敘述何者正確？",opts:["A.採取高熱量低蛋白的飲食，主要是維持適當血糖穩定","B.低蛋白應採用低生物價值蛋白質來攝取必需胺基酸","C.降低腎臟代謝負擔，故避免蛋白質成為熱量主要來源","D.採全靜脈營養時，僅需要以脂肪為主取代蛋白質即可"],ans:[2],expl:"本題答案為C。腎衰竭病人因腎臟排除蛋白質代謝廢物（含氮廢物）的能力下降，飲食應避免讓蛋白質成為熱量的主要來源，改以醣類與脂肪提供足夠熱量，並將有限的蛋白質保留用於組織修復維持所需，藉此降低腎臟代謝含氮廢物的負擔，此為本題答案。高熱量低蛋白飲食的主要目的是「減少腎臟代謝負擔、避免組織蛋白質分解（負氮平衡）」，並非以維持血糖穩定為主要考量，此敘述之目的說明有誤（A✗）；蛋白質限制期間應選用「高生物價值」蛋白質（如蛋、肉、奶類等必需胺基酸完整的優質蛋白），以最少的蛋白質總量攝取足夠必需胺基酸，並非低生物價值蛋白質，此敘述之蛋白質品質選擇方向相反（B✗）；即使採全靜脈營養，仍須提供適量、經審慎計算的胺基酸（蛋白質）以維持氮平衡，並非僅以脂肪完全取代蛋白質（D✗）。"},{n:342,no:42,subj:"泌尿系統",q:"有關腎臟移植發生排斥時的主要處置，下列敘述何者錯誤？",opts:["A.超急性排斥因血管栓塞壞死，必須儘快移除植入的腎臟","B.加速性排斥因血液中產生抗體，使用大量類固醇或血漿移除術來控制","C.急性排斥時發生水腫、高血壓，使用利尿劑控制","D.慢性排斥臨床症狀包含蛋白尿、高血壓、體重增加等，通常採保守治療方式"],ans:[2],expl:"本題答案為C。急性排斥反應是免疫系統對移植腎的主動攻擊反應，其核心處置應是「加強免疫抑制治療」（如高劑量類固醇脈衝治療、增加或調整免疫抑制劑），單純使用利尿劑僅能症狀性處理水腫，無法真正控制排斥反應本身，此敘述之處置方向有誤，為本題答案（C✗，題目問「何者錯誤」）。超急性排斥因受贈者體內已存在對供腎的抗體，發生血管栓塞壞死，移植腎通常無法挽救，須儘速移除以避免嚴重全身性反應，此描述正確（A✓）；加速性排斥與體液性（抗體媒介）免疫反應有關，臨床上常使用高劑量類固醇或血漿置換術移除致病抗體，此描述正確（B✓）；慢性排斥病程進展緩慢且多不可逆，臨床表現包含蛋白尿、高血壓、體重增加等，處置多以保守支持性治療為主，此描述正確（D✓）。"},{n:343,no:43,subj:"內分泌系統",q:"有關庫欣氏症候群症狀的病理機轉，下列何者錯誤？",opts:["A.蛋白質過度分解，造成肌肉質塊流失","B.肝臟糖質新生作用降低，胰島素利用增加","C.水分與鈉離子滯留，導致水腫","D.皮質醇分泌上升，造成淋巴球下降，傷口癒合差"],ans:[1],expl:"本題答案為B。庫欣氏症候群因體內皮質醇（一種昇糖皮質素）過多，會「促進」肝臟糖質新生作用（將胺基酸等非醣類物質轉化為葡萄糖）且「降低」周邊組織對胰島素的利用效率（造成胰島素阻抗、血糖升高，即類固醇性糖尿病），此敘述將糖質新生與胰島素利用的方向皆描述相反，為本題答案（B✗，題目問「何者錯誤」）。皮質醇過多促進蛋白質分解代謝，導致肌肉組織流失、肌力減退，此描述正確（A✓）；皮質醇具部分礦皮質素作用，會促進鈉與水分滯留，造成水腫及高血壓，此描述正確（C✓）；皮質醇過多會抑制淋巴球增生並活化及削弱發炎反應，造成免疫力下降、傷口癒合能力變差，此描述正確（D✓）。"},{n:344,no:44,subj:"內分泌系統",q:"有關中樞性尿崩症的敘述，下列何者正確？",opts:["A.尿比重大於1.030","B.尿量少、血漿滲透壓下降","C.有全身水腫現象","D.因抗利尿激素分泌不足導致"],ans:[3],expl:"本題答案為D。中樞性尿崩症是因下視丘或腦下垂體後葉病變，導致抗利尿激素（ADH／vasopressin）分泌不足，腎臟集尿管對水分再吸收能力下降，此為本題答案。因大量水分無法再吸收而隨尿液排出，尿液應呈現「稀釋」狀態，尿比重應「低於」1.005左右，而非大於1.030（正常尿比重高值端），此敘述之數值方向有誤（A✗）；尿崩症典型表現是「多尿」而非少尿，且因大量水分流失，血漿滲透壓應「上升」（血液濃縮），並非下降，此敘述方向相反（B✗）；尿崩症因大量水分流失容易導致脫水，而非全身水腫，此敘述與病理生理不符（C✗）。"},{n:345,no:45,subj:"內分泌系統",q:"有關胰臟所製造的激素與作用，下列敘述何者錯誤？",opts:["A.胰島素可控制人體脂肪和蛋白質的代謝","B.升糖素能將肝臟的肝醣轉成葡萄糖，此稱之糖質新生作用","C.胰島素可以加速葡萄糖由血液中輸送至細胞內儲存","D.體制素可抑制胰島素分泌及腸道蠕動，延緩腸道對葡萄糖的吸收"],ans:[1],expl:"本題答案為B。升糖素（glucagon）將肝臟已儲存的肝醣分解為葡萄糖釋出的過程，正確名稱是「肝醣分解作用（glycogenolysis）」；「糖質新生作用（gluconeogenesis）」則是指利用非醣類物質（如胺基酸、乳酸、甘油）從頭合成新葡萄糖的過程，兩者機轉與受質皆不同，此敘述將肝醣分解誤稱為糖質新生作用，名詞使用有誤，為本題答案（B✗，題目問「何者錯誤」）。胰島素除調控血糖外，亦廣泛參與脂肪與蛋白質代謝的調控，此描述正確（A✓）；胰島素可促進周邊組織（尤其肌肉、脂肪細胞）攝取血中葡萄糖並儲存，此描述正確（C✓）；體制素（somatostatin）具廣泛抑制作用，可抑制胰島素與升糖素分泌，並延緩腸胃蠕動及葡萄糖吸收速率，此描述正確（D✓）。"},{n:346,no:46,subj:"內分泌系統",q:"有關糖尿病病人飲食控制原則的護理指導，下列何者正確？",opts:["A.儘量選用低升糖指數的食物，避免血糖上升快速，如：根莖類、瓜果類","B.避免油炸，宜多採用清蒸、水煮、清燉、滷、涼拌等烹調方式","C.避免喝酒，有小酌嗜好者，可選擇雙鹿五加皮、蔘茸酒、玫瑰露酒等","D.脂肪需求量占每日總熱量的20～30%，膽固醇每日攝取量低於500 mg"],ans:[1],expl:"本題答案為B。糖尿病飲食應避免油炸等高油烹調方式，改採清蒸、水煮、清燉、滷、涼拌等低油烹調法，以減少油脂攝取及熱量負擔，此為本題答案。低升糖指數食物的舉例應為未精製全穀類、豆類等，根莖類（如馬鈴薯）與部分瓜果類食物實際上升糖指數偏高，此舉例並不恰當（A✗）；此選項雖強調應「避免喝酒」，卻又同時建議「可選擇」多種傳統藥酒／料理酒作為小酌選項，前後論述自相矛盾，且藥酒仍屬含酒精飲品，並不符合糖尿病病人飲食限酒的原則（C✗）；糖尿病病人心血管風險較高，建議之每日膽固醇攝取上限多為300 mg以下，本題所述「低於500 mg」的門檻明顯偏寬鬆、不夠嚴謹（D✗）。"},{n:347,no:47,subj:"內分泌系統",q:"有關甲狀腺功能亢進病人的飲食指導，下列何者不適當？",opts:["A.高熱量","B.高碳水化合物","C.高蛋白","D.高纖維"],ans:[3],expl:"本題答案為D。甲狀腺功能亢進病人因基礎代謝率大幅增加，容易合併腸胃蠕動過快、腹瀉等症狀，此時若再刻意強調「高纖維」飲食，可能進一步刺激腸胃蠕動、加重腹瀉不適，並非此類病人飲食指導的必要重點，為本題答案（D✗，題目問「何者不適當」）。因代謝率增加、熱量消耗大，需給予高熱量飲食以維持體重及營養狀態（A為適當指導）；同樣因熱量消耗大，需搭配足夠碳水化合物提供能量（B為適當指導）；病人常合併肌肉組織耗損，需攝取高蛋白飲食以維持肌肉量、修補組織（C為適當指導）。"},{n:348,no:48,subj:"其他",q:"有關自動體外心臟電擊去顫器（AED）的操作敘述，下列何者錯誤？",opts:["A.電擊貼片須貼在病人的右鎖骨下及左乳旁胸部","B.若胸毛太多無法黏上電擊片，則以手按壓住電擊片電擊以增加導電","C.聽到指示「按下電擊按鈕」應確認所有人無觸碰病人再按下電擊按鈕","D.若病人身體濕，應先擦乾再貼貼片"],ans:[1],expl:"本題答案為B。若病人胸毛過多導致電擊貼片無法確實黏貼，正確處理方式是儘速刮除該部位體毛或使用備用貼片黏除毛髮後重新黏貼，絕對不可以「用手按壓貼片」的方式代替黏貼進行電擊，因放電當下手部接觸病人身體有遭電擊、灼傷的高度風險，此為本題答案（B✗，題目問「何者錯誤」）。電擊貼片標準黏貼位置為右鎖骨下方及左側腋中線（乳頭外側）胸壁，此描述正確（A✓）；按下電擊鈕前務必確認現場所有人皆未接觸病人，是操作AED的核心安全步驟（C✓）；若病人身體潮濕，水分會分散電流、影響貼片導電效果並增加電擊風險，應先擦乾皮膚再貼上貼片（D✓）。"},{n:349,no:49,subj:"其他",q:"病人體重77公斤，摔車導致右側大腿變形骨折，血流不止，119緊急救護員給予緊急處理後送到急診，病人體溫35.8℃、心跳136次／分、呼吸34次／分、血壓80/58 mmHg，皮膚冷潮濕，微血管充填時間大於2秒，呈現焦慮情緒。依據上述資料，病人呈現的休克種類，下列何者正確？",opts:["A.低血容積性休克","B.血管性休克","C.神經性休克","D.心因性休克"],ans:[0],expl:"本題答案為A。病人因大腿骨折併活動性出血，出現心跳加快（代償）、呼吸加快、血壓下降、皮膚冷潮濕（周邊血管代償性收縮）、微血管充填時間延長及焦慮不安（腦部灌流不足早期徵象）等表現，皆是典型「大量失血」導致循環血量不足所引發的低血容積性休克臨床表徵，為本題答案。血管性休克（如敗血性、過敏性休克）典型表現常伴隨周邊血管擴張，皮膚多呈現溫暖潮紅而非冷潮濕，與本題描述不符（B✗）；神經性休克因交感神經張力喪失導致血管擴張，典型表現常見心跳「過慢」及皮膚溫暖乾燥，與本題心跳加快、皮膚冷潮濕的表現不符（C✗）；心因性休克是心臟幫浦功能衰竭所致，通常會有心臟疾病史或合併肺水腫等表現，本題情境明確指向外傷大量出血，與心因性機轉不符（D✗）。"},{n:350,no:50,subj:"其他",q:"根據2020年美國心臟醫學會（AHA）公告的「生存之鏈（chain of survival）」急救步驟，發生於醫院內心臟停止的照護（in hospital cardiac arrest, IHCA），其急救重點次序，下列何者正確？①即早辨識和預防 ②緊急應變系統啟動 ③施行高品質CPR ④去顫 ⑤心臟停止後照護 ⑥復原",opts:["A.①→②→③→④→⑤→⑥","B.①→③→⑤→②→④→⑥","C.①→②→④→③→⑤→⑥","D.①→④→③→②→⑤→⑥"],ans:[0],expl:"本題答案為A（①→②→③→④→⑤→⑥）。根據2020年AHA生存之鏈，院內心臟停止（IHCA）之急救重點依序為：①即早辨識與預防（及早發現病人惡化徵象並介入）→②啟動緊急應變系統（呼叫院內急救團隊）→③施行高品質心肺復甦術（CPR）→④去顫（如適應症符合，儘早電擊）→⑤心臟停止後照護（自發性循環恢復後的整合治療）→⑥復原（後續復健與長期照護），此為官方公告之標準連續步驟順序，為本題答案。其餘選項調換了各步驟的先後順序，與官方公告之標準生存之鏈次序不符（B、C、D✗）。"},{n:351,no:1,subj:"神經系統",q:"腰椎椎間盤突出接受椎板切除術後之護理指導，下列何者錯誤？",opts:["A.使用中硬度的床墊，維持脊椎正常排列","B.背架使用3～6個月，下床時須整天穿著背架，只有洗澡時可取下","C.手術後應該採俯臥及睡高枕，臥床時仍應該進行全關節運動","D.在可接受的情況下，可以進行俯臥抬頭和俯臥抬腿之運動"],ans:[2],expl:"本題答案為C。腰椎椎板切除術後應避免增加脊椎前凸/後凸壓力的姿位，臥床期間也應以維持脊椎正中排列為原則，過早進行全關節運動（尤其髖、膝的大幅度活動）可能牽動腰椎、增加傷口張力，此描述並不恰當，為本題答案（C✗，題目問「何者錯誤」）。中硬度床墊可兼顧支撐與舒適、維持脊椎正常排列，是合適選擇（A✓）；術後背架穿戴期間下床時須整天穿著，僅洗澡時可取下，是常見的標準指導（B✓）；在可接受範圍內漸進進行俯臥抬頭、俯臥抬腿等伸展運動，有助強化背部及核心肌力、促進復原（D✓）。"},{n:352,no:2,subj:"神經系統",q:"有關重症肌無力病人之藥物使用護理指導，下列敘述何者正確？",opts:["A.鼓勵進食高蛋白食物，降低prostigmin的副作用","B.運動後服用mestinon，避免肌肉無力","C.azathioprine不可以與prednisone合併使用，會降低療效","D.若口服藥無效時，可以使用放射線I125治療"],ans:[0],expl:"本題答案為A。重症肌無力病人使用prostigmin（抗膽鹼酯酶藥物）常見腸胃道副作用（如噁心、腹絞痛、腹瀉），鼓勵攝取高蛋白食物有助於維持整體營養狀態、減輕藥物相關腸胃不適對身體的影響，此為本題答案。Mestinon應於「運動前」服用以維持運動時足夠的肌力，而非運動後才服用避免無力（B✗，時序相反）；Azathioprine常與prednisone等類固醇「合併使用」以加強免疫抑制效果、治療重症肌無力，並非兩者合併會降低療效（C✗）；重症肌無力口服藥物無效時，臨床上會考慮的是胸腺切除術或血漿置換術、靜脈注射免疫球蛋白等治療方式，並非放射線碘131（I125並非其治療選項，且此描述與甲狀腺功能亢進的放射碘治療混淆）（D✗）。"},{n:353,no:3,subj:"內分泌系統",q:"有關糖尿病病人運動之護理指導，下列何者正確？①運動可降低細胞對胰島素的敏感性而降低血糖 ②運動最好在飯後1～2小時做 ③運動型態建議使用大肌肉群的有氧運動 ④切勿注射完胰島素後立刻運動，以免發生高血糖現象",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[2],expl:"本題答案為C（②③）。②運動安排在飯後1～2小時可避免空腹運動誘發低血糖，此敘述正確；③大肌肉群有氧運動（如健走、游泳）是糖尿病病人建議的運動型態，有助改善胰島素敏感性，此敘述正確，選②③＝C（本題答案）。運動應是「增加」（而非降低）細胞對胰島素的敏感性，進而促進血糖利用、降低血糖，此敘述機轉方向相反（①錯誤）；注射胰島素後立即運動，尤其運動部位若為注射部位附近，會加速胰島素吸收，容易誘發「低血糖」，並非高血糖，此敘述之風險方向錯誤（④錯誤）。"},{n:354,no:4,subj:"神經系統",q:"若右眼外旋神經受到血腫壓迫導致複視（diplopia），病人在下列那一種指示下，右眼複視最為明顯？",opts:["A.向右看","B.向左看","C.向前看","D.閉左眼"],ans:[0],expl:"本題答案為A。外旋神經（CN VI）負責眼球外展（向外看），右眼外旋神經麻痺時，右眼向右（外側）看的能力受限，此時左右眼視軸分離程度最大，複視最為明顯，為本題答案。向左看主要使用內直肌（動眼神經支配），與外旋神經受損關聯較小，複視不會最明顯（B✗）；向前看時外旋神經作用不明顯，複視程度通常較輕（C✗）；閉左眼僅消除雙眼視覺造成的複視感受，並非用來評估複視「最明顯」的方向性測試（D✗）。"},{n:355,no:5,subj:"神經系統",q:"有關病人因腦腫瘤引起顱內壓升高的症狀與徵象，下列敘述何者錯誤？",opts:["A.血壓下降","B.視力模糊或出現視乳突水腫","C.頭痛或出現嘔吐","D.心跳變慢"],ans:[0],expl:"本題答案為A。顱內壓升高典型會誘發庫欣氏三徵（Cushing's triad）：血壓「上升」（尤其收縮壓）、脈搏「變慢」及呼吸型態改變，以維持腦部灌流壓，「血壓下降」與顱內壓升高的代償機轉方向相反，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。視力模糊或視乳突水腫是顱內壓升高影響視神經的常見表現（B✓）；頭痛與嘔吐（尤其噴射性嘔吐）是顱內壓升高的典型症狀（C✓）；心跳變慢（心搏過緩）是庫欣氏三徵之一，屬代償反應（D✓）。"},{n:356,no:6,subj:"神經系統",q:"張先生因高處跌下導致脊髓損傷住院，護理師可經由下列何種反射出現，而知張先生已渡過脊髓休克期？",opts:["A.作嘔反射","B.肛門反射","C.頭眼反射","D.角膜反射"],ans:[1],expl:"本題答案為B。肛門反射（肛門括約肌收縮反射）是薦髓（S2～S4）層級的反射，此反射的重新出現，代表薦髓反射弧已恢復運作、病人已渡過脊髓休克期，是臨床上常用來判斷脊髓休克是否結束的指標之一，為本題答案。作嘔反射、頭眼反射、角膜反射皆屬於腦幹（而非脊髓）層級的反射，與脊髓休克期的判斷無直接關聯（A、C、D✗）。"},{n:357,no:7,subj:"神經系統",q:"關於腦瘤伽馬刀（gamma knife）立體定位放射線手術之敘述，下列何者正確？①適用於直徑小於3公分腫瘤 ②不會有手術切開傷口 ③治療時間約需半小時 ④使用碘放射線射入腫瘤以破壞腫瘤細胞",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[0],expl:"本題答案為A（①②③）。①伽馬刀主要適用於體積較小（通常直徑小於3公分）的腦部病灶，此敘述正確；②伽馬刀是非侵入性立體定位放射線治療，不需開顱、無手術切口，此敘述正確；③單次治療時間通常約需數十分鐘（約半小時左右，依病灶大小與劑量規劃而定），此敘述大致正確，選①②③＝A（本題答案）。伽馬刀是利用「鈷60（Cobalt-60）」產生的加瑪射線精準聚焦照射病灶，並非使用碘放射線，此敘述之放射源種類有誤（④錯誤）。"},{n:358,no:8,subj:"神經系統",q:"重症肌無力病人使用抗膽鹼酯酶藥物的護理指導，下列何者正確？①腹部絞痛可能為劑量不足徵象 ②鼓勵進食高蛋白食物預防副作用 ③血壓上升可能為劑量過量徵象 ④務必準時服藥因延遲服藥可能會喪失吞藥力量",opts:["A.①②","B.①④","C.②③","D.②④"],ans:[3],expl:"本題答案為D（②④）。②抗膽鹼酯酶藥物可能造成腸胃不適等副作用，維持均衡營養（含高蛋白食物）有助支持整體體能與藥物耐受性，此敘述可視為合理指導；④延遲服藥可能使藥效未能及時銜接，導致肌肉無力加重甚至影響吞嚥安全，故務必準時服藥，此敘述正確，選②④＝D（本題答案）。腹部絞痛、腸胃蠕動增加等膽鹼激性症狀，通常是藥物「過量」（而非劑量不足）造成的副作用表現，此敘述之劑量方向有誤（①錯誤）；膽鹼激性藥物過量典型反而會造成心跳「變慢」及血壓「下降」（副交感神經興奮效應），並非血壓上升，此敘述方向亦有誤（③錯誤）。"},{n:359,no:9,subj:"消化系統",q:"下列何者可用來做為大腸癌手術後是否復發的參考指標？",opts:["A.α-胎兒蛋白（AFP）","B.癌胚胎抗原（CEA）","C.C-反應蛋白（CRP）","D.腫瘤壞死因子（TNF）"],ans:[1],expl:"本題答案為B。癌胚胎抗原（CEA）是大腸直腸癌最常用於術後追蹤是否復發或轉移的腫瘤標記，若手術後CEA濃度持續下降後又回升，需警覺復發可能，為本題答案。AFP主要用於肝細胞癌及生殖細胞腫瘤的監測，並非大腸癌的參考指標（A✗）；CRP是一般發炎指標，並非癌症專一性腫瘤標記（C✗）；TNF是發炎相關細胞激素，同樣不具大腸癌復發監測的臨床應用價值（D✗）。"},{n:360,no:10,subj:"消化系統",q:"李先生因胃癌接受次全胃切除手術（Billroth II），術後開始進食稀飯，約20分鐘出現腹脹、噁心嘔吐、心悸、頭暈等現象，下列何者為其最可能造成的原因？",opts:["A.食糜快速進入腸道，引起細胞內、外液電解質不平衡","B.高張性碳水化合物食糜進入腸道，促使Insulin大量分泌","C.細胞外液迅速移入腸道，快速液體移位減少了循環血量","D.高張性脂肪性食糜進入腸道，促使Amylase大量分泌"],ans:[2],expl:"本題答案為C。此為典型的傾倒症候群（dumping syndrome）早期表現：胃部分切除後，食糜快速直接進入小腸，因腸腔內滲透壓瞬間升高，大量細胞外液（循環血量）迅速滲入腸腔以稀釋高滲透壓內容物，造成有效循環血量快速減少，引發心悸、頭暈、腹脹噁心等類似低血容積的表現，此為本題答案。食糜快速進入腸道確實會造成腸腔內電解質失衡，但此選項未點出「循環血量減少」這個造成心悸頭暈等全身性症狀的核心機轉，敘述不夠完整精確（A較不貼切）；早期傾倒症候群的觸發物質主要是「高張性醣類（碳水化合物）」內容物造成的滲透性液體移位，而非直接刺激Insulin大量分泌（後者較符合發生於進食後1～3小時的「晚期」傾倒症候群機轉，時序與本題20分鐘不符）（B✗，時序與機轉皆對應到不同階段）；此情境並非以脂肪性食糜及Amylase大量分泌為核心機轉（D✗）。"},{n:361,no:11,subj:"消化系統",q:"有關消化性潰瘍的治療藥物，下列何者錯誤？",opts:["A.制酸劑","B.前列腺素合成劑","C.質子幫浦抑制劑","D.第一型組織胺接受器拮抗劑"],ans:[3],expl:"本題答案為D。「第一型組織胺接受器（H1）拮抗劑」是治療過敏反應（如抗組織胺藥物）的藥物類別，作用於H1受體，並非用於抑制胃酸分泌；消化性潰瘍藥物治療所使用的組織胺拮抗劑，正確應是「第二型（H2）組織胺接受器拮抗劑」（如cimetidine、ranitidine），此選項的受體型別描述錯誤，為本題答案（D✗，題目問「何者錯誤」）。制酸劑可中和胃酸（A✓）；前列腺素合成劑（如misoprostol）可增強黏膜保護機轉（B✓）；質子幫浦抑制劑可強效抑制胃酸分泌（C✓）。"},{n:362,no:12,subj:"消化系統",q:"有關潰瘍性結腸炎（ulcerative colitis）的敘述，下列何者正確？①易侵犯全腸壁 ②易造成肛門瘻管 ③易有裡急後重感 ④糞便中經常帶血",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[3],expl:"本題答案為D（③④）。③潰瘍性結腸炎因直腸、乙狀結腸黏膜發炎明顯，常見裡急後重感（tenesmus）；④因病灶黏膜表淺、血管豐富易受侵蝕，糞便經常帶有血液及黏液，此二敘述皆為典型表現，選③④＝D（本題答案）。潰瘍性結腸炎的病灶通常侷限於大腸「黏膜及黏膜下層」，並非侵犯全腸壁（易侵犯全腸壁、造成瘻管是「克隆氏症」的典型特徵，非潰瘍性結腸炎）（①錯誤）；肛門瘻管同樣是克隆氏症（全層穿透性發炎）較常見的併發症，並非潰瘍性結腸炎的典型表現（②錯誤）。"},{n:363,no:13,subj:"消化系統",q:"有關腹膜炎常見的臨床表徵，下列何者錯誤？",opts:["A.嘔吐","B.持續腹痛","C.腸蠕動降低","D.體溫持續上升"],ans:[3],expl:"本題答案為D。腹膜炎病人因合併敗血反應、體液大量流失至腹腔（第三腔隙），病程進展中體溫可能出現不穩定甚至偏低（尤其年長、免疫低下或病情惡化時），「體溫持續上升」並非腹膜炎最具代表性或穩定可靠的臨床特徵，相較之下腹痛、腸蠕動減退、嘔吐才是腹膜炎最一致且核心的臨床表現，此為本題答案（D✗，題目問「何者錯誤」；體溫變化在腹膜炎病人中相對不穩定、不具持續單向上升的必然性）。腹膜受刺激常誘發噁心嘔吐（A✓）；腹膜炎典型表現為持續性、逐漸加劇的腹痛（B✓）；腹膜發炎會反射性抑制腸道蠕動，出現腸蠕動減弱甚至消失（麻痺性腸阻塞）（C✓）。"},{n:364,no:14,subj:"消化系統",q:"有關病毒性肝炎傳染途徑之敘述，下列何者錯誤？",opts:["A.A型肝炎經由糞口","B.B型肝炎經由血液","C.C型肝炎經由血液","D.D型肝炎經由糞口"],ans:[3],expl:"本題答案為D。D型肝炎病毒（HDV）是一種缺陷型病毒，必須依附在B型肝炎病毒（HBV）的外套膜蛋白才能完成感染複製，其傳染途徑與B型肝炎相同，主要透過「血液及體液」傳染，並非糞口傳染，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。A型肝炎經糞口途徑傳染，是正確的傳染途徑描述（A✓）；B型肝炎經血液（及體液、母嬰垂直感染）傳染（B✓）；C型肝炎同樣主要經血液傳染（C✓）。"},{n:365,no:15,subj:"消化系統",q:"有關急性胃炎之護理措施，下列何者錯誤？",opts:["A.依醫囑給予氫氧化鋁及氫氧化鎂","B.不需禁食，仍可正常飲食","C.避免服用水楊酸或類固醇類的藥物","D.要有常規的作息，避免菸、酒"],ans:[1],expl:"本題答案為B。急性胃炎急性期為讓發炎的胃黏膜獲得休息、減少胃酸與食物刺激，通常需要「短暫禁食」，待症狀緩解後再逐步恢復清淡飲食，並非可不需禁食、正常飲食，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。氫氧化鋁、氫氧化鎂等制酸劑可依醫囑用於中和胃酸、緩解症狀（A✓）；水楊酸類（如aspirin）及類固醇類藥物皆可能刺激或損傷胃黏膜，應避免使用（C✓）；規律作息並戒除菸酒有助於減少胃黏膜受到的刺激，是重要的生活型態指導（D✓）。"},{n:366,no:16,subj:"消化系統",q:"有關食道癌的病因，下列何者正確？",opts:["A.好發於食道上1/3段","B.以腺狀細胞癌最常見","C.喜食過熱、過鹹、刺激性食物者","D.女性罹病率高於男性"],ans:[2],expl:"本題答案為C。長期食用過熱、過鹹及刺激性食物，會反覆刺激食道黏膜造成慢性損傷，是食道癌公認的重要危險因子之一，為本題答案。食道癌好發部位以食道「中1/3段」較常見，並非上1/3段（A✗）；台灣及亞洲地區食道癌仍以「鱗狀細胞癌」最常見，腺癌相對少見（腺癌在西方國家因逆流性食道炎/巴瑞特氏食道盛行率較高而較常見）（B✗）；食道癌好發於「男性」，罹病率明顯高於女性（與菸酒等生活習慣的性別差異有關），並非女性罹病率較高（D✗）。"},{n:367,no:17,subj:"骨骼肌肉",q:"有關骨質疏鬆症護理指導之敘述，下列何者錯誤？",opts:["A.採取非負重活動比負重活動好，以強化骨骼","B.下床活動時，可使用骨科支架，以減輕疼痛","C.每天日曬至少15分鐘增加維生素D合成，以增加鈣質吸收","D.不可同時使用高纖食物與高鈣食物，以避免影響鈣質吸收"],ans:[0],expl:"本題答案為A。骨質疏鬆症護理指導應鼓勵病人從事「負重活動」（weight-bearing exercise，如健走、爬樓梯），透過重力刺激骨骼進行骨質重塑、強化骨密度，「非負重活動比負重活動好」的敘述方向相反，為本題答案（A✗，題目問「何者錯誤」）。下床活動時使用背架等骨科支架可提供額外支撐、減輕疼痛及骨折風險（B✓）；適度日曬可促進皮膚合成維生素D，進而增加腸道鈣質吸收（C✓）；高纖食物中的植酸/草酸可能與鈣結合、影響鈣質吸收，故建議高纖食物與高鈣食物分開攝取、不宜同時大量併食（D✓）。"},{n:368,no:18,subj:"骨骼肌肉",q:"右小腿上石膏病人，出現下列何項臨床表徵，需要立即給予處理？",opts:["A.右腳大拇趾甲床微血管充填時間2秒","B.右腳小腿末端出現感覺異常","C.右小腿石膏內皮膚發癢","D.右側足背動脈脈搏強度2+"],ans:[1],expl:"本題答案為B。石膏固定後出現肢體末端「感覺異常」（如麻木、刺痛感），是筋膜室症候群（compartment syndrome）的重要早期警訊之一，屬於神經受壓迫或缺血的表現，需要立即處理評估，為本題答案。甲床微血管充填時間2秒屬於正常範圍（正常應小於2～3秒），非異常表現（A✗）；石膏內皮膚發癢通常是一般常見、非緊急的皮膚刺激反應（C✗）；足背動脈脈搏強度2+屬於正常可觸及範圍，並非異常徵象（D✗）。"},{n:369,no:19,subj:"骨骼肌肉",q:"承上題，下列何者為病人最適當的處置？",opts:["A.將右小腿抬高於心臟","B.給予右小腿末端冷敷","C.以彈性繃帶加壓包紮右大腿","D.去除右小腿石膏"],ans:[3],expl:"本題答案為D。承上題病人已出現感覺異常，高度懷疑石膏過緊導致筋膜室症候群，此時最適當且優先的處置是「立即移除石膏」，解除外部壓迫來源，以避免神經血管持續受壓造成不可逆損傷，為本題答案。抬高患肢過高（高於心臟）反而可能降低動脈灌流壓，在懷疑筋膜室症候群時應避免過度抬高，通常建議與心臟同高即可（A✗）；冷敷可能造成血管收縮，進一步降低患肢血流灌注，不利於缺血狀況的改善（B✗）；彈性繃帶加壓包紮會進一步增加患肢壓力，與解除壓迫的處置原則相反，且題目描述包紮部位（大腿）亦與問題部位（小腿）不符（C✗）。"},{n:370,no:20,subj:"骨骼肌肉",q:"有關接受關節腔鏡檢查病人的陳述，下列何者顯示需要進一步的護理指導？",opts:["A.「檢查後若無不舒服，我可以立即恢復日常活動」","B.「我應該要注意關節有無血腫情形的發生」","C.「我會檢視我的神經、血管功能是否受到影響」","D.「檢查後我要特別注意有無發燒或是部位有無紅腫」"],ans:[0],expl:"本題答案為A。關節鏡檢查術後仍需要適當休息、限制患肢劇烈活動一段時間（通常視手術範圍而定，並非檢查完全無不適即可「立即」恢復所有日常活動），此病人的陳述顯示衛教認知不足，需要進一步指導以澄清正確的術後活動限制，為本題答案。觀察關節有無血腫（B）、自我檢視神經血管功能（C）、注意感染徵象如發燒或部位紅腫（D），皆是正確且完整的術後自我照顧認知，不需要進一步指導。"},{n:371,no:21,subj:"感官系統",q:"有關急性鼻竇炎的處置，下列何者錯誤？",opts:["A.抗生素至少要連續使用7天以上","B.可以使用解熱鎮痛劑緩解發燒及疼痛","C.鼻噴劑可以隨時使用以改善鼻塞症狀","D.使用蒸氣吸入可以促進鼻竇引流"],ans:[2],expl:"本題答案為C。鼻噴劑（尤其血管收縮劑類）若長期或過度頻繁使用（如「隨時」使用），容易造成藥物性鼻炎及反彈性鼻黏膜腫脹（rebound congestion），使用上須遵循醫囑限制頻率與療程，並非可以隨時使用，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。急性鼻竇炎抗生素療程建議至少7～14天以確保感染清除（A✓）；可依醫囑使用解熱鎮痛劑緩解發燒及疼痛症狀（B✓）；蒸氣吸入有助濕潤及稀釋鼻腔分泌物，促進鼻竇引流（D✓）。"},{n:372,no:22,subj:"腫瘤血液",q:"有關鼻咽癌病人接受放射線治療之護理指導，下列何者錯誤？",opts:["A.避免冰敷或熱敷治療部位皮膚","B.用含酒精漱口水以保持口腔清潔","C.治療期間宜多作張口及咀嚼運動","D.可以多增加水分攝取"],ans:[1],expl:"本題答案為B。含酒精成分的漱口水具刺激性及乾燥效果，對於接受放射線治療、口腔黏膜本已脆弱敏感的鼻咽癌病人而言，容易加重口腔黏膜刺激及疼痛不適，應改用溫和、不含酒精的漱口水（如生理食鹽水或小蘇打水），此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。放射線治療部位皮膚應避免冰敷或熱敷等額外刺激，以防皮膚反應加重（A✓）；治療期間鼓勵張口及咀嚼運動，有助預防放射線導致的牙關緊閉（張口困難）（C✓）；適度增加水分攝取有助保持口腔濕潤、稀釋黏稠分泌物（D✓）。"},{n:373,no:23,subj:"感官系統",q:"有關喉癌術後放置永久性喉切除管（Laryngectomy tube）病人的出院護理指導，下列何者不適宜？",opts:["A.每天以濕毛巾清潔造口周圍皮膚","B.坐起或翻身時需以手托後頸，避免頸部過度伸張","C.咳嗽或打噴嚏時，用手帕蓋住造口處，另一手掩住嘴巴","D.鼓勵採用固定於牆上的壁掛式淋浴設備"],ans:[3],expl:"本題答案為D。全喉切除病人的氣道完全經由頸部造口聯通，若使用固定於牆上、無法調整方向或流量的壁掛式淋浴設備，水流方向不易靈活閃避造口，容易使水直接沖入氣管造口引發嗆咳甚至溺水風險，並不適宜鼓勵使用，為本題答案（D✗，題目問「何者不適宜」；正確應鼓勵使用可調整、便於閃避造口方向的手持式蓮蓬頭，並可搭配防水造口保護罩）。以濕毛巾清潔造口周圍皮膚可維持局部清潔又不致過度刺激（A✓）；坐起或翻身時以手托住後頸，避免頸部過度伸張，可保護尚未完全癒合的頸部組織及縫合處（B✓）；咳嗽或打噴嚏時以手帕蓋住造口、另一手掩嘴，可避免分泌物噴濺並維護儀態及衛生（C✓）。"},{n:374,no:24,subj:"感官系統",q:"有關美尼爾氏症候群的症狀，下列何者錯誤？",opts:["A.耳鳴","B.眩暈","C.單側耳聽力減退","D.耳痛"],ans:[3],expl:"本題答案為D。耳痛並非美尼爾氏症候群的典型症狀，此症候群的核心三主症是眩暈、耳鳴及聽力減退（多為單側感音性聽力喪失），為本題答案。耳鳴是美尼爾氏症典型症狀之一（A✓）；陣發性眩暈是此症候群最主要的核心表現（B✓）；單側耳聽力減退（感音性聽損）亦是典型三主症之一（C✓）。"},{n:375,no:25,subj:"心臟血管",q:"有關心內膜炎周邊症狀之敘述，下列何者錯誤？",opts:["A.指甲床上會出現裂紋般的出血（Splinter hemorrhage）","B.手掌或腳底出現無痛性的紅斑，稱為賈尼威病灶（Janeway's lesions）","C.手指或腳趾出現疼痛性的紅色結節，稱為奧斯勒氏結節（Osler's nodes）","D.四肢末稍出現出血點，稱為羅氏斑（Roth's spots）"],ans:[3],expl:"本題答案為D。羅氏斑（Roth's spots）是指「視網膜（眼底）」上出現中心蒼白的出血斑點，是眼底鏡檢查所見的心內膜炎周邊症狀，並非出現在「四肢末梢」的出血點，此敘述之部位描述有誤，為本題答案（D✗，題目問「何者錯誤」）。甲床出現裂紋狀出血（splinter hemorrhage）是心內膜炎周邊徵象之一（A✓）；手掌或腳底出現無痛性紅斑（Janeway's lesions）為典型周邊徵象（B✓）；手指或腳趾出現疼痛性紅色結節（Osler's nodes）同為典型周邊徵象（C✓）。"},{n:376,no:26,subj:"心臟血管",q:"有關心肌病變臨床表徵之敘述，下列何者錯誤？",opts:["A.心律不整","B.心搏過速","C.端坐呼吸","D.心輸出量增加"],ans:[3],expl:"本題答案為D。心肌病變因心肌收縮功能受損，心輸出量應是「下降」而非增加，此敘述之方向錯誤，為本題答案（D✗，題目問「何者錯誤」）。心肌病變常合併心律不整，是常見表現（A✓）；為代償心輸出量不足，常出現心搏過速（B✓）；左心功能不全時肺循環鬱血，易出現端坐呼吸（C✓）。"},{n:377,no:27,subj:"心臟血管",q:"有關第一期心臟復健，下列敘述何者錯誤？",opts:["A.以新陳代謝當量（metabolic equivalent, MET）指標作為活動量的指引","B.採漸進方式的增加活動量","C.血壓上升不超過正常血壓值25 mmHg","D.活動時增加的心跳速率至少要超過休息時的25%"],ans:[3],expl:"本題答案為D。第一期（急性住院期）心臟復健活動時，心跳速率增加通常建議限制在休息時心跳的「20次/分或20%以內」（依各機構指引略有差異，但原則是嚴格限制增幅），「至少要超過25%」的描述方向相反、幅度亦不符合保守漸進的活動原則，此敘述有誤，為本題答案（D✗，題目問「何者錯誤」）。以MET（代謝當量）作為活動強度指引，是心臟復健分級活動的標準做法（A✓）；漸進式增加活動量以避免心臟負荷驟增，是核心原則（B✓）；血壓變化通常限制在不超過安靜時血壓值20～25 mmHg之內，此描述合理（C✓）。"},{n:378,no:28,subj:"心臟血管",q:"有關心肌梗塞急性期的治療，下列敘述何者正確？①從鼻套管給10 L/min氧氣 ②給予麻醉性止痛劑止痛，如morphine ③給予血栓溶解劑治療 ④給予抗凝血劑治療 ⑤補充維生素K",opts:["A.①②③","B.①④⑤","C.②③④","D.③④⑤"],ans:[2],expl:"本題答案為C（②③④）。②嗎啡等麻醉性止痛劑可緩解心肌梗塞劇烈胸痛並降低交感神經興奮及心臟負荷；③血栓溶解劑可在適應症符合時溶解冠狀動脈血栓、恢復血流；④抗凝血劑（如heparin）可預防血栓進一步形成，三者皆是心肌梗塞急性期的標準治療內容，選②③④＝C（本題答案）。急性心肌梗塞常規給氧流量建議約2～4 L/min（經鼻套管），並非10 L/min的高流量，過量給氧並非必要且可能有害（①錯誤）；維生素K是warfarin的拮抗劑，與心肌梗塞急性期治療無關（⑤錯誤）。"},{n:379,no:29,subj:"心臟血管",q:"有關心臟節律器放置術後護理措施之敘述，下列何者不適宜？",opts:["A.心電圖上出現心室激搏波（spike）時，應立即通知醫師","B.每日評估植入處傷口有無發炎、血腫情形","C.術後隔日，植入側的手臂宜避免抬高的關節運動","D.術後第一小時應每15分鐘評估生命徵象"],ans:[0],expl:"本題答案為A。心臟節律器術後心電圖上出現心室激搏波（pace spike），代表節律器正在正常發出電刺激訊號、按預期運作，屬於正常且預期中的表現，並非需要「立即通知醫師」的異常狀況，此敘述不適宜，為本題答案（A✗，題目問「何者不適宜」）。每日評估植入處傷口有無發炎、血腫，是基本傷口照護原則（B✓）；術後隔日植入側手臂宜避免抬高過肩的大幅度關節運動，以防電極導線移位（C✓）；術後第一小時密切每15分鐘評估生命徵象，是監測是否發生心律不整或出血等併發症的標準做法（D✓）。"},{n:380,no:30,subj:"心臟血管",q:"有關血管產生動脈粥狀硬化（atherosclerosis）的病理機轉，下列敘述何者錯誤？",opts:["A.血管內皮細胞損傷","B.血小板凝集增加、血塊凝集","C.交感神經受刺激分泌兒茶酚胺","D.周邊血管擴張心肌供氧增加"],ans:[3],expl:"本題答案為D。動脈粥狀硬化因血管內壁斑塊堆積造成管腔「狹窄」，會使心肌供氧「減少」而非增加，此敘述之病理方向錯誤，為本題答案（D✗，題目問「何者錯誤」）。血管內皮細胞損傷是動脈粥狀硬化形成的起始機轉（A✓）；血小板於受損內皮處凝集、活化凝血反應是斑塊形成過程的一環（B✓）；交感神經興奮分泌兒茶酚胺，可促進血管收縮及血小板活化，參與動脈粥狀硬化病理過程（C✓）。"},{n:381,no:31,subj:"心臟血管",q:"有關風濕熱與風濕性心臟病之敘述，下列何者錯誤？",opts:["A.好發於65歲以上女性病人","B.主要臨床症狀為心肌炎","C.最常侵犯二尖瓣","D.紅血球沉降速率增加"],ans:[0],expl:"本題答案為A。風濕熱與風濕性心臟病好發於「兒童及青少年（約5～15歲）」，與A族鏈球菌感染後的自體免疫反應有關，並非好發於65歲以上老年女性，此敘述有誤，為本題答案（A✗，題目問「何者錯誤」）。心肌炎是風濕熱的主要臨床表現之一（B✓）；風濕性心臟病最常侵犯「二尖瓣」，其次為主動脈瓣（C✓）；風濕熱活動期常見紅血球沉降速率（ESR）上升，反映發炎反應（D✓）。"},{n:382,no:32,subj:"心臟血管",q:"有關靜脈曲張之護理指導，下列敘述何者正確？",opts:["A.建議穿著緊身衣","B.無需維持理想體重","C.不宜運動以避免惡化","D.睡前可抬高患肢"],ans:[3],expl:"本題答案為D。靜脈曲張病人睡前抬高患肢，可藉重力協助靜脈血液回流、減輕靜脈鬱積及水腫，是正確的護理指導，為本題答案。應建議穿著「彈性襪」（提供漸進式壓力促進回流），而非一般緊身衣（緊身衣壓力分布不均，效果不同且可能有害）（A✗）；維持理想體重可減少下肢靜脈負荷，「無需維持」的敘述方向錯誤（B✗）；適度規律運動（如健走）有助促進小腿肌肉幫浦作用、改善靜脈回流，並非不宜運動（C✗）。"},{n:383,no:33,subj:"腫瘤血液",q:"有關急性移植物對抗宿主疾病（Graft-versus-host-Disease, GVHD）之敘述，下列何者正確？",opts:["A.通常發生在移植後六個月","B.全身器官皆會侵犯","C.不會有發炎反應","D.大多是表皮組織受到破壞"],ans:[3],expl:"本題答案為D。急性移植物對抗宿主疾病（急性GVHD）最常侵犯的器官是皮膚（表皮），臨床上常以皮疹表現為最初徵象，此為本題答案。急性GVHD通常發生在移植後「100天內」，並非六個月（六個月後之表現較屬於慢性GVHD範疇）（A✗）；急性GVHD主要侵犯皮膚、肝臟及腸胃道等特定器官，並非「全身器官皆會」侵犯（B✗）；急性GVHD是免疫細胞攻擊宿主組織所致，具有明顯的發炎反應，並非不會有發炎反應（C✗）。"},{n:384,no:34,subj:"腫瘤血液",q:"張小姐，42歲，診斷為乳癌第二期，日前進行癌症治療，有關腫瘤標記之敘述，下列何者錯誤？",opts:["A.腫瘤標記為一系列與癌症相關、可測量之特殊化學物質","B.CA-15-3為早期鑑別診斷乳癌發生的標記","C.腫瘤標記不建議用於篩檢、輔助診斷或預測預後","D.對於較早期之癌症敏感度很低"],ans:[1],expl:"本題答案為B。CA-15-3主要用於「監測乳癌治療效果及偵測復發」，其敏感度與特異度皆不足以作為早期鑑別診斷乳癌的篩檢工具，此敘述有誤，為本題答案（B✗，題目問「何者錯誤」）。腫瘤標記的定義即是一系列與癌症相關、可於血液或組織中測量的特殊化學物質（A✓）；多數腫瘤標記因專一性及敏感度限制，並不建議單獨用於一般族群的癌症篩檢、輔助診斷或預後預測（C✓）；腫瘤標記對於腫瘤量體較小的早期癌症，敏感度普遍偏低，容易出現偽陰性（D✓）。"},{n:385,no:35,subj:"其他",q:"王先生，67歲，體重90公斤，BMI：30 kg/m2，平時菸酒不離手且愛吃醃漬食品，下列護理措施何者不適宜？",opts:["A.飲食可不用限制","B.轉介減重門診","C.建議增加蔬菜水果攝取，每天至少攝取5份","D.轉介院內戒菸門診"],ans:[0],expl:"本題答案為A。病人BMI已達30（肥胖範圍），並有長期菸酒及嗜食醃漬食品等多項心血管及癌症危險因子，護理措施應積極介入飲食調整（如減少醃漬高鹽食物、控制總熱量），「飲食可不用限制」明顯與病人現況及照護目標不符，並不適宜，為本題答案（A✗，題目問「何者不適宜」）。轉介減重門診可協助病人系統性控制體重（B✓）；建議增加蔬果攝取（每日至少5份）符合健康飲食原則、有助降低慢性病風險（C✓）；轉介戒菸門診可協助病人戒除菸癮、降低心血管及癌症風險（D✓）。"},{n:386,no:36,subj:"消化系統",q:"下列何者為避免結腸癌的保護因子？①鼓勵食用紅肉 ②不需限制油脂的攝取 ③維持適當的體重 ④維持規律運動 ⑤補充適當的纖維攝取",opts:["A.①③⑤","B.②③④","C.②④⑤","D.③④⑤"],ans:[3],expl:"本題答案為D（③④⑤）。③維持適當體重可降低結腸癌風險；④規律運動已被證實與降低結腸癌發生率相關；⑤足夠的纖維攝取有助促進腸道蠕動、縮短致癌物與腸黏膜接觸時間，三者皆為保護因子，選③④⑤＝D（本題答案）。紅肉（尤其加工肉品）攝取過多與結腸癌風險「增加」有關，並非保護因子，不應鼓勵食用（①錯誤）；高油脂（尤其飽和脂肪）攝取與結腸癌風險上升有關，飲食上仍建議適度限制油脂攝取，並非不需限制（②錯誤）。"},{n:387,no:37,subj:"腫瘤血液",q:"下列何項處置最能減緩因接受化學治療而發生口腔黏膜損傷所造成的疼痛？",opts:["A.暫時停止化學治療","B.監測病人的全血球計數","C.持續良好的口腔清潔","D.定期檢查口腔黏膜炎症狀與徵象"],ans:[2],expl:"本題答案為C。持續執行良好且溫和的口腔清潔（如使用軟毛牙刷、生理食鹽水漱口），可減少口腔黏膜炎處的二次感染及刺激，是直接且能有效減緩化療引起口腔黏膜損傷疼痛的護理措施，為本題答案。暫停化學治療屬於醫療處置決策層級，並非護理措施能單獨決定，也非直接減緩疼痛的做法（A✗）；監測全血球計數是評估病人骨髓抑制程度的監測性措施，並非直接處置疼痛的方法（B✗）；定期檢查口腔黏膜炎症狀與徵象屬於評估性措施，同樣並非直接減緩疼痛的處置（D✗）。"},{n:388,no:38,subj:"腫瘤血液",q:"王小姐最喜歡吃速食，餐餐吃都不膩，最近出現口炎、吞嚥困難且指甲萎縮變薄呈湯匙狀，醫師告知為貧血，王小姐最有可能罹患那一種貧血？",opts:["A.缺鐵性貧血","B.惡性貧血","C.葉酸缺乏性貧血","D.再生不良性貧血"],ans:[0],expl:"本題答案為A。口炎、吞嚥困難合併指甲扁平萎縮、呈湯匙狀（匙狀甲，koilonychia），是缺鐵性貧血的典型特徵性表現，加上長期偏好速食、營養不均衡的飲食型態容易導致鐵質攝取不足，為本題答案。惡性貧血主要與內在因子缺乏、維生素B12吸收不良有關，常見神經學症狀（如感覺異常），與匙狀甲的關聯性不如缺鐵性貧血典型（B✗）；葉酸缺乏性貧血症狀以巨球性貧血相關表現為主，並非以匙狀甲為特徵（C✗）；再生不良性貧血主要表現為全血球減少相關症狀（感染、出血傾向），並非以匙狀甲為典型特徵（D✗）。"},{n:389,no:39,subj:"腫瘤血液",q:"有關化學藥物cyclophosphamide（Cytoxan）的副作用或毒性，不包括下列何者？",opts:["A.出血性膀胱炎","B.骨髓抑制","C.心臟毒性","D.畏光"],ans:[3],expl:"本題答案為D。Cyclophosphamide（Cytoxan）已知的副作用及毒性包括出血性膀胱炎（其代謝物acrolein對膀胱黏膜的刺激所致）、骨髓抑制，以及高劑量使用時的心臟毒性；畏光並非此藥物常見或已知的典型副作用，為本題答案（D✗，題目問「不包括下列何者」）。出血性膀胱炎是Cyclophosphamide具代表性的泌尿道毒性（A為已知副作用）；骨髓抑制是化療藥物普遍常見的副作用（B為已知副作用）；高劑量使用時可能造成心臟毒性，是臨床用藥需監測的重點（C為已知副作用）。"},{n:390,no:40,subj:"腫瘤血液",q:"王先生因疲倦、蒼白、呼吸困難至醫院求治，檢查發現白血球數值為30萬／μL，骨髓檢查發現費城染色體，最有可能罹患下列何種疾病？",opts:["A.急性淋巴性白血病","B.慢性淋巴性白血病","C.急性骨髓性白血病","D.慢性骨髓性白血病"],ans:[3],expl:"本題答案為D。費城染色體（Philadelphia chromosome，BCR-ABL基因融合）是慢性骨髓性白血病（CML）具有高度特異性的細胞遺傳學標記，此為本題答案。急性淋巴性白血病及急性骨髓性白血病病程進展通常較為急遽，與費城染色體的典型連結不如CML明確（A、C✗，雖費城染色體亦可見於少數急性淋巴性白血病，但典型且高度連結仍是CML）；慢性淋巴性白血病與費城染色體並無典型關聯（B✗）。"},{n:391,no:41,subj:"腫瘤血液",q:"有關上腔靜脈症候群之敘述，下列何者正確？",opts:["A.以淋巴瘤的病人最常發生","B.常見症狀有臉部腫脹、頭痛、呼吸困難等","C.協助病人採側臥平躺的姿勢，較能改善此症狀","D.非小細胞癌病人可用化學治療來改善此症狀"],ans:[1],expl:"本題答案為B。上腔靜脈症候群因靜脈回流受阻，典型表現為頭頸部及臉部腫脹、頭痛、呼吸困難，此為本題答案。上腔靜脈症候群最常見的病因其實是「肺癌」（尤其小細胞肺癌），並非以淋巴瘤最常見（A✗）；病人應採「高坐臥姿（半坐臥或坐姿）」以利靜脈回流、減輕腫脹與呼吸困難，而非側臥平躺（C✗，平躺反而不利靜脈回流）；「小細胞癌」（而非非小細胞癌）對化學治療及放射治療的反應通常較佳，可用以改善上腔靜脈症候群的症狀（D✗，癌症類型描述相反）。"},{n:392,no:42,subj:"腫瘤血液",q:"有關癌症疼痛處置之敘述，下列何者正確？",opts:["A.脊椎硬膜外注入止痛藥物後，病人要平躺6～8小時","B.病人自控式止痛法可減少藥量使用，延長用藥間隔時間","C.冷熱療法會降低疼痛的閾值而減輕疼痛","D.冷療法要持續使用不可間斷，以免降低效果"],ans:[1],expl:"本題答案為B。病人自控式止痛法（PCA）讓病人可依疼痛程度自行按壓給藥，整體常能有效控制疼痛並減少總藥物使用量，同時因疼痛獲得穩定控制，也有助延長下次需要額外用藥的間隔時間，此為本題答案。脊椎硬膜外注入止痛藥物後，一般建議平躺的時間依藥物種類及醫囑而定，並非統一硬性規定平躺6～8小時（A✗，此為過度絕對化的描述）；冷熱療法的止痛機轉是「提高」疼痛閾值（減少痛覺傳導的敏感度），而非降低疼痛閾值，此敘述之機轉方向相反（C✗）；冷療法應間歇使用（如每次15～20分鐘後需休息），避免凍傷及血液循環障礙，並非持續使用不可間斷（D✗）。"},{n:393,no:43,subj:"其他",q:"有關原發性皮膚病變之敘述，下列何者正確？",opts:["A.結節是由皮膚隆起的堅實性病變，直徑小於1公分","B.丘疹為皮膚表面硬塊，侷限於皮下不會有皮膚隆起，直徑大於1公分","C.玫瑰疹為一種暫時性、急性、侷限性及無特定大小的表皮浮腫和微血管擴張情形","D.紫斑是皮膚組織內出血所致的紫紅色斑塊，壓下不會變色"],ans:[3],expl:"本題答案為D。紫斑（purpura）是皮下組織出血所致的紫紅色斑塊，因血液已滲出至組織間隙，加壓按壓後顏色「不會」隨之消退變色，此特徵是與血管擴張性紅斑（按壓會退色）鑑別的重要臨床依據，此描述正確，為本題答案。結節（nodule）是皮膚隆起的堅實性病變，但典型定義其直徑通常「大於」1公分（此描述之直徑對應到較符合丘疹papule的定義，並非結節）（A✗）；丘疹（papule）應是「皮膚隆起」的病變、且直徑通常「小於」1公分，此敘述描述丘疹「侷限皮下不會隆起、直徑大於1公分」，與丘疹的實際定義相反（B✗）；此敘述較符合「膨疹（wheal）」的定義（暫時性、常因過敏誘發的表皮浮腫及微血管擴張），並非玫瑰疹的典型定義（C✗）。"},{n:394,no:44,subj:"其他",q:"有關牛皮癬之敘述，下列何者正確？",opts:["A.間接性發作，夏天出現冬天消失","B.好發部位為頭皮、手肘伸側及膝蓋呈不對稱分布","C.皮膚由邊緣明顯的紅斑轉變成易脫落的銀灰色鱗屑","D.在病灶表皮的角質層出現微小膿瘍稱為柯納氏現象（Koebner's phenomenon）"],ans:[2],expl:"本題答案為C。牛皮癬（乾癬）典型皮膚表現是邊緣界線清楚的紅斑，其上覆蓋容易脫落的銀白（灰）色鱗屑，此為本題答案。乾癬病程多在「冬天」因濕度低、日曬減少而惡化，夏天日曬則可能有助改善，此描述之季節變化方向與典型病程相反（A✗）；好發部位頭皮、肘膝伸側等處，臨床上通常呈「對稱性」分布，並非不對稱分布（B✗）；柯納氏現象（Koebner's phenomenon）是指皮膚受到外傷（如抓傷、摩擦）處誘發新乾癬病灶出現的現象，並非病灶表皮角質層出現微小膿瘍（微小膿瘍另有專有名稱Munro's microabscess，是乾癬的組織學特徵之一，與Koebner現象並非同一概念）（D✗，兩個專有名詞被混淆替換）。"},{n:395,no:45,subj:"其他",q:"有關電燒傷所造成的身體損傷，下列敘述何者正確？",opts:["A.身體所造成的損傷只有在電流入口及出口處","B.交流電造成的傷害較直流電嚴重","C.對電流阻力越大的組織越不易造成損傷","D.骨骼的電流阻力小於血管"],ans:[1],expl:"本題答案為B。交流電（AC）因會造成持續性肌肉不自主收縮，使受害者往往無法自行脫離電源，接觸時間延長、組織受損程度通常較直流電（DC）嚴重，此為本題答案。電燒傷的損傷範圍不僅限於電流入口及出口處，電流通過路徑上的深層組織（尤其肌肉、神經、血管）亦可能受到嚴重損傷，此敘述之損傷範圍描述不完整（A✗）；依焦耳定律，電流通過電阻較大的組織時，產生的熱量反而較多，故電阻越大的組織通常「越容易」受損，並非越不易受損（C✗，方向相反）；人體組織中，骨骼的電阻其實是「最高」的，大於血管等軟組織，並非小於血管（D✗）。"},{n:396,no:46,subj:"其他",q:"熱燒傷病人進行水療法時之護理措施，下列何者最適宜？",opts:["A.水溫調配維持32～34℃，以減少傷口疼痛","B.水池中加入beta-iodine 30～50 ppm，以抑制細菌生長","C.水池中每公升加入0.85公克的食鹽，以補充流失的電解質","D.水療時間每次以一小時為宜，使痂皮鬆脫"],ans:[2],expl:"本題答案為C。水療液中每公升加入約0.85公克食鹽，可配製出接近生理食鹽水（0.9%）等滲透壓濃度的溶液，有助補充燒傷創面大量流失的電解質，並減少組織滲透壓不平衡造成的不適，此為本題答案。水療水溫一般建議接近體溫（約36～37℃左右），32～34℃的水溫偏低，容易造成病人體溫流失及不適，並非以此溫度為原則（A✗）；含碘消毒劑（beta-iodine）濃度過高可能對新生組織產生毒性、影響傷口癒合，其使用濃度需審慎評估，並非以30～50 ppm的高濃度作為常規建議（B✗）；水療時間過長（如一小時）會增加病人體溫流失、疼痛及潛在感染風險，一般建議時間較短（約20～30分鐘），並非以一小時為宜（D✗）。"},{n:397,no:47,subj:"其他",q:"下列何者屬於主動性後天免疫？",opts:["A.由遺傳而來所產生的扺抗力","B.注射免疫球蛋白而獲得的抗體","C.接種疫苗使人體產生抗體","D.母親經由胎盤將IgG傳給胎兒"],ans:[2],expl:"本題答案為C。接種疫苗刺激人體自身免疫系統主動產生抗體及免疫記憶，屬於「主動性」後天免疫，此為本題答案。由遺傳而來的抵抗力屬於「先天性」免疫，並非後天免疫（A✗）；注射免疫球蛋白是直接給予現成抗體，身體並未自行產生免疫反應，屬於「被動性」後天免疫（B✗）；母親經胎盤將IgG傳給胎兒，同樣是胎兒被動獲得現成抗體，屬於「被動性」後天免疫（D✗）。"},{n:398,no:48,subj:"骨骼肌肉",q:"有關類風濕性關節炎藥物治療之敘述，下列何者錯誤？",opts:["A.選擇性COX-2抑制劑會抑制血小板凝集，延長出血時間","B.aspirin降低前列腺素合成，可減輕炎症及關節疼痛","C.非固醇類抗炎藥（NSAIDs）是第一線用藥","D.育齡婦女接受疾病調節抗風濕藥物治療時必須避孕"],ans:[0],expl:"本題答案為A。選擇性COX-2抑制劑（如celecoxib）因較不抑制COX-1（與血小板凝集功能相關的酵素），對血小板凝集功能及出血時間的影響「較傳統非選擇性NSAIDs為小」，這正是COX-2選擇性藥物開發的初衷之一（減少腸胃道出血等副作用），此敘述與其藥理特性相反，為本題答案（A✗，題目問「何者錯誤」）。Aspirin透過抑制環氧化酶降低前列腺素合成，達到消炎及止痛效果（B✓）；非固醇類抗炎藥（NSAIDs）確實是類風濕性關節炎症狀治療的第一線用藥之一（C✓）；多數疾病調節抗風濕藥物（DMARDs，如methotrexate）具有致畸胎性，育齡婦女用藥期間必須落實避孕措施（D✓）。"},{n:399,no:49,subj:"其他",q:"有關免疫球蛋白特性之敘述，下列何者正確？",opts:["A.IgG含量少，能通過胎盤，提供新生兒抗體","B.IgD與T淋巴球的分化有關","C.IgE可附在肥大細胞上，引發過敏反應","D.IgM是感染細菌或病毒後最後出現的抗體"],ans:[2],expl:"本題答案為C。IgE可與肥大細胞及嗜鹼性球表面的高親和力受體結合，當再次接觸過敏原時活化細胞、釋放組織胺等介質，引發第一型過敏反應，此為本題答案。IgG其實是血清中「含量最多」的免疫球蛋白（並非含量少），且可通過胎盤提供新生兒被動免疫，此敘述之含量描述有誤（A✗）；IgD主要與「B淋巴球」的分化及活化有關，並非與T淋巴球分化有關（B✗）；IgM是感染後「最先」出現的抗體（急性感染指標），並非最後出現，長期存在、代表既往感染或免疫記憶的通常是IgG（D✗）。"},{n:400,no:50,subj:"其他",q:"有關後天免疫缺乏症候群（AIDS）病人出現營養少於身體需要時之護理措施，下列何者錯誤？",opts:["A.提供高熱量、高蛋白之飲食","B.口腔念珠菌感染時可使用nystatin含漱","C.可使用檸檬水或小蘇打水漱口，以促進食慾","D.提供高纖飲食，以促進腸胃蠕動"],ans:[3],expl:"本題答案為D。AIDS病人常合併腹瀉等腸胃道症狀，此時應避免高纖飲食過度刺激腸道蠕動、加重腹瀉及營養流失，並非以高纖飲食促進腸胃蠕動作為改善營養不足的措施，此敘述有誤，為本題答案（D✗，題目問「何者錯誤」）。提供高熱量高蛋白飲食可補充免疫系統所需營養、對抗疾病消耗（A✓）；口腔念珠菌感染時使用nystatin含漱，是標準抗黴菌治療方式（B✓）；使用檸檬水或小蘇打水漱口可清潔口腔、促進食慾，改善進食意願（C✓）。"},{n:401,no:51,subj:"呼吸系統",q:"評估一位氣胸且剛接上胸管病人的胸腔水下引流系統裝置，下列何者為不正常現象？",opts:["A.水封瓶內長玻管保持在液面下2～3公分","B.水封瓶內會出現連續性氣泡","C.水封瓶中液面在吸氣時上升","D.水封瓶中液面在呼氣時下降"],ans:[1],expl:"本題答案為B。水封瓶內出現「連續性」氣泡，通常代表引流系統或病人胸腔內存在持續性漏氣（air leak），屬於需要進一步評估處理的異常現象；正常預期的氣泡應隨呼吸間歇出現，而非連續不斷冒出，為本題答案。水封瓶內長玻管末端應保持在液面下2～3公分，以維持有效水封、防止空氣逆流入胸腔，此為正常裝置狀態（A✓）；水封瓶液面隨呼吸出現波動（tidaling）——吸氣時上升、呼氣時下降（自然呼吸病人；使用正壓呼吸器則方向相反），是胸管系統暢通、正常運作的表現（C、D✓）。"},{n:402,no:52,subj:"呼吸系統",q:"下列何者不是肺水腫病人之典型臨床表徵？",opts:["A.動脈氧分壓（PaO2）48 mmHg","B.肺動脈楔壓（PAWP）14 mmHg","C.頸靜脈怒張","D.中心靜脈壓（CVP）18 cmH2O"],ans:[1],expl:"本題答案為B。肺動脈楔壓（PAWP）正常值約6～12 mmHg，心因性肺水腫時通常會明顯「上升」（多超過18～20 mmHg以上），14 mmHg僅屬輕度偏高、未達肺水腫典型顯著升高的程度，相對而言並非肺水腫的典型代表性數值，為本題答案（B為最不可能出現的典型表徵）。PaO2嚴重偏低（如48 mmHg）反映肺部氣體交換嚴重障礙，是肺水腫嚴重時的典型表現（A為典型表徵）；肺水腫合併右心負荷增加或體液過多時，可能出現頸靜脈怒張（C為典型表徵）；中心靜脈壓（CVP）升高（如18 cmH2O）反映體液容積過多、右心前負荷增加，是肺水腫（尤其合併體液過量時）的常見表現（D為典型表徵）。"},{n:403,no:53,subj:"呼吸系統",q:"王先生胸壁受到鈍傷入院求治，下列何者表示可能有肺挫傷的情形？",opts:["A.呼吸緩慢","B.呼吸音降低","C.桶狀胸","D.受傷部位有吸吮聲"],ans:[1],expl:"本題答案為B。肺挫傷因肺泡及微血管受損出血、水腫，造成局部肺組織通氣不良，聽診時常呈現呼吸音減弱或降低，此為本題答案。肺挫傷病人因換氣及氧合受影響，呼吸速率通常會「加快」（代償性呼吸急促），而非緩慢（A✗）；桶狀胸是慢性阻塞性肺疾病（COPD）長期胸廓過度充氣的慢性變化，並非急性胸壁鈍傷後肺挫傷的表現（C✗）；受傷部位出現「吸吮聲」（sucking sound）是開放性氣胸（胸壁傷口與外界相通）的特徵性表現，並非單純肺挫傷（鈍傷、閉合性）的典型徵象（D✗）。"},{n:404,no:54,subj:"呼吸系統",q:"葉先生為COPD病人，醫囑為：fenoterol（Berotec）2 puffs INHA BID，下列何者表示其使用正確？",opts:["A.使用前不應搖晃瓶身","B.連續按壓兩次噴霧劑然後吸入藥物","C.吸藥後閉氣10秒鐘再緩慢吐氣","D.使用完後應立即漱口"],ans:[2],expl:"本題答案為C。使用定量噴霧吸入器（MDI）吸藥後，應閉氣約10秒，讓藥物微粒有足夠時間沉積於下呼吸道，再緩慢吐氣，此為正確使用方式，為本題答案。使用前應先「搖晃」瓶身，使藥物均勻懸浮後再使用，並非不應搖晃（A✗）；兩次噴藥之間應間隔約1分鐘左右，並非連續按壓兩次噴霧劑，以確保每次吸入劑量足夠且均勻（B✗）；Fenoterol屬於支氣管擴張劑（非吸入性類固醇），使用後並不需要強制「立即漱口」，立即漱口主要是針對吸入性類固醇（預防口腔念珠菌感染）的重點衛教（D✗）。"},{n:405,no:55,subj:"呼吸系統",q:"陳女士是氣喘病人，過去四週內發生：日間出現氣喘症狀每週一次、因氣喘在夜間醒來兩次、日常活動未因氣喘受影響、需要使用藥物緩解症狀每週超過兩次。依照GINA（Global Initiative for Asthma, 2019）對氣喘控制程度，其屬於下列何者？",opts:["A.控制良好","B.部分控制","C.控制不佳","D.控制很差"],ans:[1],expl:"本題答案為B。依GINA（2019）氣喘控制程度評估的四項指標（日間症狀>每週2次、夜間因氣喘醒來、需使用緩解藥物>每週2次、活動受限），此病人於過去四週內符合「夜間因氣喘醒來兩次」及「需使用緩解藥物每週超過兩次」共2項（日間症狀每週僅一次未達>2次門檻，活動也未受影響），符合1～2項即屬於「部分控制」等級，為本題答案。"},{n:406,no:56,subj:"呼吸系統",q:"下列何者是誘發病人發生急性呼吸窘迫症候群（ARDS）最常見的危險因子？",opts:["A.敗血性休克","B.慢性阻塞性肺疾病","C.氣喘","D.心衰竭"],ans:[0],expl:"本題答案為A。敗血性休克（sepsis相關的全身性發炎反應合併肺損傷）是誘發急性呼吸窘迫症候群（ARDS）最常見、也是最重要的危險因子之一，為本題答案。COPD、氣喘、心衰竭雖可能合併呼吸功能惡化，但並非誘發ARDS最典型、最常見的危險因子（B、C、D✗；ARDS需符合特定的瀰漫性肺泡損傷及非心因性肺水腫診斷條件，與心衰竭造成的心因性肺水腫需加以鑑別）。"},{n:407,no:57,subj:"呼吸系統",q:"有關單側自發性氣胸病人之身體檢查評估結果，下列何者錯誤？",opts:["A.吸氣時，胸廓兩側不對稱","B.患側觸覺震顫減弱","C.患側叩診為過度反響音","D.橫膈膜離軌度變大"],ans:[3],expl:"本題答案為D。單側氣胸因患側肺塌陷，橫膈膜運動能力受限，離軌度（隨呼吸上下移動的幅度）應「變小」而非變大，此敘述之方向錯誤，為本題答案（D✗，題目問「何者錯誤」）。患側胸廓因積氣擴張，兩側胸廓吸氣時呈現不對稱起伏，此為正常評估發現（A✓）；氣胸患側因空氣阻隔，觸覺震顫（tactile fremitus）會減弱，此為正常評估發現（B✓）；患側叩診因含氣量增加，呈現過度反響音（hyperresonance），此為正常評估發現（C✓）。"},{n:408,no:58,subj:"呼吸系統",q:"下列何者最不可能出現在肺氣腫病人的肺功能檢查結果？",opts:["A.肺總量（TLC）增加","B.第一秒鐘用力吐氣容積（FEV1）降低","C.第一秒鐘用力吐氣容積與用力肺活量之比值（FEV1/FVC）大於80%","D.肺餘容積（RV）增加"],ans:[2],expl:"本題答案為C。肺氣腫屬阻塞性肺疾病，典型肺功能檢查應呈現FEV1/FVC比值「降低」（通常小於70%），並非大於80%（大於80%較符合正常肺功能或限制性肺疾病的模式），此為本題答案（C為最不可能出現的結果）。肺氣腫因氣體滯留，肺總量（TLC）常增加（A為可能出現的結果）；氣道阻塞使FEV1降低，是阻塞性肺疾病的核心表現（B為可能出現的結果）；氣體滯留同樣使肺餘容積（RV）增加（D為可能出現的結果）。"},{n:409,no:59,subj:"泌尿系統",q:"有關多重共病腎衰竭病人之服藥注意事項，下列何者錯誤？",opts:["A.糖尿病腎病變病人的胰島素使用量可能需要減量","B.毛地黃使用要注意頭痛、心律不整等中毒症狀","C.貧血時補充鐵劑要合併制酸劑使用避免腸胃症狀","D.腸胃不適避免使用含鎂離子的制酸劑或胃乳制劑"],ans:[2],expl:"本題答案為C。制酸劑（尤其含鋁、鎂、鈣等成分者）會改變胃內酸鹼環境、與鐵離子形成不易吸收的複合物，反而會「降低」口服鐵劑的吸收效果，並非合併使用能避免腸胃症狀的建議做法，此敘述有誤，為本題答案（C✗，題目問「何者錯誤」）。腎功能不良時胰島素代謝排除速率減慢，用量可能需要視情況減量，以免蓄積造成低血糖（A✓）；毛地黃經腎臟排除，腎衰竭病人易蓄積中毒，須密切監測頭痛、心律不整等中毒徵象（B✓）；含鎂離子的制酸劑或胃乳制劑在腎衰竭病人可能造成鎂離子蓄積中毒，應避免使用（D✓）。"},{n:410,no:60,subj:"泌尿系統",q:"有關前列腺癌之敘述，下列何者錯誤？",opts:["A.排尿困難、頻尿、血尿與尿瀦留是常見的症狀","B.直腸指診和前列腺特異抗原是篩檢的診斷方法","C.轉移時最常出現背痛、腰痛、血鈣異常","D.前列腺癌與雄性素有關，好發於前列腺的中葉"],ans:[3],expl:"本題答案為D。前列腺癌主要好發於前列腺的「周邊區（peripheral zone）」，並非中葉；前列腺中葉增生較常見於良性前列腺肥大（BPH），此敘述之好發部位描述有誤，為本題答案（D✗，題目問「何者錯誤」）。攝護腺腫大壓迫尿道可造成排尿困難、頻尿，腫瘤本身或併發感染可能導致血尿、甚至尿瀦留，皆是常見症狀（A✓）；直腸指診（DRE）合併前列腺特異抗原（PSA）檢測，是前列腺癌常用的篩檢與診斷工具（B✓）；前列腺癌轉移最常見部位為骨骼，可能出現背痛、腰痛及骨轉移相關的血鈣異常（C✓）。"},{n:411,no:61,subj:"泌尿系統",q:"有關慢性腎絲球腎炎之敘述，下列何者正確？①肌酸酐清除率（CCr.）數值異常上升 ②血尿素氮及血肌酸酐的數值會異常升高 ③可由經皮腎臟組織切片檢查早期確診 ④腎皮質變厚及腎臟變大",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[2],expl:"本題答案為C（②③）。②慢性腎絲球腎炎腎功能持續惡化，血尿素氮及血肌酸酐數值會異常升高，此敘述正確；③經皮腎臟穿刺切片檢查可取得腎組織進行病理診斷，有助早期確診病因與病理型態，此敘述正確，選②③＝C（本題答案）。腎功能惡化時，肌酸酐清除率（CCr）應是異常「下降」，並非上升（①錯誤）；慢性腎絲球腎炎病程進展中，腎臟通常呈現「萎縮變小」的慢性變化，並非腎皮質增厚、腎臟變大（④錯誤，此描述較符合急性期或糖尿病腎病變早期的腎臟型態變化）。"},{n:412,no:62,subj:"泌尿系統",q:"有關腎病症候群之臨床表徵，下列何者正確？①高白蛋白血症 ②出現蛋白尿 ③高血脂症 ④血中膠體滲透壓上升",opts:["A.①④","B.②③","C.①②","D.③④"],ans:[1],expl:"本題答案為B（②③）。②大量蛋白尿是腎病症候群的核心診斷特徵；③因肝臟代償性合成脂蛋白增加，常合併高血脂症，此二敘述正確，選②③＝B（本題答案）。腎病症候群因大量蛋白質經尿液流失，應呈現「低」白蛋白血症，並非高白蛋白血症（①錯誤）；血中白蛋白降低會使血中膠體滲透壓「下降」，並非上升，此敘述方向相反（④錯誤）。"},{n:413,no:63,subj:"泌尿系統",q:"有關急迫性尿失禁之照護，下列敘述何者正確？①可給予副交感神經藥物 ②指導膀胱訓練法 ③指導病人使用尿失禁輔助用品如護墊或尿布 ④施行人工尿道括約肌植入術",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[2],expl:"本題答案為C（②③）。②膀胱訓練法（如定時排尿、延遲排尿訓練）是急迫性尿失禁的核心非藥物治療策略；③使用護墊或尿布等輔助用品，可協助病人維持日常生活品質、減少滲漏困擾，此二敘述皆為適當照護措施，選②③＝C（本題答案）。急迫性尿失禁是因膀胱逼尿肌過度反應收縮所致，藥物治療應使用「副交感神經拮抗劑（抗膽鹼藥物）」以抑制膀胱過度收縮，並非給予副交感神經「促進」藥物（這類藥物反而會加重逼尿肌收縮、惡化急迫性尿失禁），此敘述方向相反（①錯誤）；人工尿道括約肌植入術主要適用於「應力性尿失禁」（尿道括約肌功能不足所致），並非急迫性尿失禁的標準處置（④錯誤）。"},{n:414,no:64,subj:"泌尿系統",q:"下列何者會出現間歇性無痛血尿之症狀？①尿道炎 ②輸尿管結石 ③膀胱癌 ④腎臟癌",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[3],expl:"本題答案為D（③④）。③膀胱癌及④腎臟癌等泌尿道腫瘤，典型可表現為間歇性、不伴隨疼痛的血尿，是重要的臨床警訊症狀，選③④＝D（本題答案）。尿道炎典型伴隨解尿疼痛、灼熱感等刺激性症狀，血尿並非以「無痛」為特徵（①錯誤）；輸尿管結石典型表現是劇烈的腎絞痛合併血尿，屬於「有痛性」血尿，並非無痛性（②錯誤）。"},{n:415,no:65,subj:"泌尿系統",q:"有關腎臟移植之合併症，下列敘述何者不適當？",opts:["A.最常見的合併症是感染、出血","B.使用免疫抑制劑常出現肺部感染","C.術後高血壓可能因為腎動脈狹窄","D.出現胃潰瘍是因使用大量類固醇"],ans:[0],expl:"本題答案為A。腎臟移植的合併症教學重點通常聚焦於「排斥反應」及「感染」兩大核心議題，「出血」雖可能發生，但並非移植後最常被強調、最具代表性的合併症類別，此描述之重點強調有誤，為本題答案（A✗，題目問「何者不適當」）。長期使用免疫抑制劑會增加肺部感染等各類感染風險，是重要的護理觀察重點（B✓）；移植腎的腎動脈狹窄可能造成術後高血壓，是臨床上需鑑別的高血壓病因之一（C✓）；長期大量使用類固醇（免疫抑制方案的一環）可能誘發或加重消化性潰瘍，需密切觀察（D✓）。"},{n:416,no:66,subj:"呼吸系統",q:"黃女士的動脈血液氣體分析結果為完全代償性代謝性酸中毒，下列敘述何者正確？",opts:["A.pH 7.35、PaCO2 30 mmHg、HCO3- 20 mmHg、PaO2 81 mmHg","B.pH 7.31、PaCO2 28 mmHg、HCO3- 19 mmHg、PaO2 80 mmHg","C.pH 7.32、PaCO2 47 mmHg、HCO3- 23 mmHg、PaO2 82 mmHg","D.pH 7.33、PaCO2 36 mmHg、HCO3- 18 mmHg、PaO2 83 mmHg"],ans:[0],expl:"本題答案為A。此組數值：pH 7.35（已恢復至正常範圍下緣）、HCO3- 20 mmHg（明顯偏低，反映原發性代謝性酸中毒）、PaCO2 30 mmHg（降低，反映呼吸系統代償性排出更多二氧化碳以代償酸血），三者搭配符合「完全代償性代謝性酸中毒」的判讀（pH已回到正常範圍，原發問題與代償方向相符），為本題答案。選項B之pH 7.31已低於正常範圍（未完全代償）；選項C之PaCO2 47偏高、HCO3-23接近正常，數值組合較符合呼吸性酸中毒的代償模式而非代謝性酸中毒；選項D之pH 7.33同樣未恢復至正常範圍（B、C、D皆非完全代償狀態）。"},{n:417,no:67,subj:"內分泌系統",q:"有關皮質醇（Cortisol）之敘述，下列何者正確？",opts:["A.是腎上腺皮質分泌最少的類固醇","B.皮質醇在血漿中的濃度以早上起床後6～8點濃度最高","C.會降低血糖","D.會降低身體對抗壓力及發炎的效果"],ans:[1],expl:"本題答案為B。皮質醇分泌具有明顯的日夜節律性，血漿濃度以清晨起床後（約6～8點）達到高峰，午夜前後最低，此為本題答案。皮質醇（糖皮質素）其實是腎上腺皮質分泌「量最多」的類固醇激素，並非分泌最少（A✗）；皮質醇透過促進肝臟糖質新生、降低周邊組織葡萄糖利用等機轉，會使血糖「升高」而非降低（C✗）；皮質醇是身體對抗壓力反應的核心激素之一，會「提升」（而非降低）身體對抗壓力及調節發炎反應的能力（D✗）。"},{n:418,no:68,subj:"內分泌系統",q:"有關嗜鉻細胞瘤病人的護理措施，下列何者錯誤？",opts:["A.注意有無頭痛、視力改變、胸痛、意識混亂等病症","B.讓病人充分休息，避免壓力發生","C.鼓勵攝取低維他命、低蛋白質、低礦物質及低熱量食物","D.避免喝咖啡、茶"],ans:[2],expl:"本題答案為C。嗜鉻細胞瘤病人並無需要限制維他命、蛋白質、礦物質及熱量攝取的醫學根據，此種全面性的營養限制缺乏臨床依據，並不恰當；此類病人飲食上真正需要留意的重點，是避免攝取含酪胺酸或會刺激兒茶酚胺釋放的食物及飲品（如咖啡、茶），此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。嗜鉻細胞瘤因陣發性大量兒茶酚胺釋放，可能誘發頭痛、視力改變、胸痛、意識混亂甚至高血壓危象，需密切觀察（A✓）；充分休息、避免壓力可減少誘發兒茶酚胺大量釋放的機會（B✓）；咖啡、茶等含咖啡因飲品可能刺激交感神經興奮，應避免攝取（D✓）。"},{n:419,no:69,subj:"內分泌系統",q:"有關愛迪生氏危機病人的護理措施，下列何者錯誤？",opts:["A.監測生命徵象、輸出入量、電解質","B.執行限水計畫，每天攝水量少於1,000 c.c.","C.鼓勵攝取含鈉及高蛋白質食物","D.指導病人避免攝取香蕉、南瓜"],ans:[1],expl:"本題答案為B。愛迪生氏危機（腎上腺皮質功能不足急性發作）因醛固酮及皮質醇分泌嚴重不足，典型呈現「低血鈉、低血容積、脫水」傾向，治療原則應是積極「補充水分及鈉」，而非限制水分攝取，此敘述之處置方向與病理生理相反，為本題答案（B✗，題目問「何者錯誤」）。密切監測生命徵象、輸出入量及電解質變化，是急性危象期的基本監測項目（A✓）；鼓勵攝取含鈉及高蛋白質食物，有助補充流失的鈉離子及支持組織修復（C✓）；香蕉、南瓜等高鉀食物在愛迪生氏症病人（常合併高血鉀傾向）應避免過量攝取（D✓）。"},{n:420,no:70,subj:"內分泌系統",q:"有關胰島素保存之護理指導，下列何者正確？",opts:["A.未開罐的胰島素可以在常溫中保存","B.使用中的胰島素應冷藏2～8℃的環境","C.出國旅遊勿將胰島素置於飛機行李艙","D.開罐前若發現藥瓶內出現顆粒時需搖勻"],ans:[2],expl:"本題答案為C。飛機貨艙（行李艙）環境溫度可能過低甚至結凍，胰島素一旦結凍會使蛋白質結構破壞、永久失去藥效，故出國旅遊時應將胰島素隨身攜帶，避免置於托運行李（貨艙），此為本題答案。未開罐胰島素建議「冷藏（2～8℃）」保存以維持穩定性，並非可在常溫中保存（A✗）；使用中的胰島素在室溫（約25～30℃以下）通常可存放約4～6週（依廠牌略有差異），並非絕對必須持續冷藏，此敘述過於絕對化（B✗，多數短效與長效胰島素使用中皆可室溫保存一段期間）；若開罐前發現藥瓶內有顆粒或混濁異常（尤其應澄清的短效胰島素），應予丟棄不可使用，並非搖勻後繼續使用（D✗）。"},{n:421,no:71,subj:"內分泌系統",q:"有關胰島素注射之敘述，下列何者正確？",opts:["A.吸收胰島素的速率依序是：腹部＞臀部＞大腿＞上臂","B.建議將胰島素注射於即將運動的肢體上，避免吸收過慢","C.注射同一部位應隔2～3週才可重複，以防注射皮膚感染","D.若糖尿病病人因感染而發燒，會加速胰島素藥效的吸收"],ans:[3],expl:"本題答案為D。發燒時皮膚血流增加，會加速皮下注射部位（包含胰島素注射處）的藥物吸收速率，可能提高低血糖風險，需特別留意監測，此為本題答案。胰島素正確的吸收速率排序應為：腹部＞上臂＞大腿＞臀部，此敘述將「上臂」與「臀部」的順序對調，排序有誤（A✗）；應避免將胰島素注射於「即將大量運動」的肢體，因運動會使該處血流增加、加速吸收，提高低血糖風險，並非建議如此注射（B✗，方向相反）；同一注射部位重複注射的間隔建議，主要目的是預防局部脂肪增生或萎縮（而非單純防感染），一般建議「同一區域內」規律輪替，並非需要相隔長達2～3週（C✗）。"},{n:422,no:72,subj:"內分泌系統",q:"有關升糖指數飲食指導之敘述，下列何者正確？①升糖指數是指人體食用含醣食物後，血中葡萄糖反應的速度和強度 ②糖尿病人要選擇高升糖指數食物，以免造成低血糖 ③乳品類食物升糖指數較高，常見的食物，如：全脂奶 ④全穀類食物升糖指數較低，常見的食物，如：全麥早餐穀類",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"本題答案為B（①④）。①升糖指數（GI）的定義即是食用含醣食物後，血中葡萄糖上升反應的速度與強度，此敘述正確；④全穀類食物（如全麥穀類）膳食纖維含量較高，消化吸收較緩慢，升糖指數通常較低，此敘述正確，選①④＝B（本題答案）。糖尿病病人飲食應選擇「低」升糖指數食物，以利血糖平穩控制，並非選擇高升糖指數食物（②錯誤，且高升糖指數食物易使血糖快速上升而非造成低血糖）；乳品類食物（如全脂奶）的升糖指數通常屬於「較低」分類，並非較高（③錯誤）。"},{n:423,no:73,subj:"內分泌系統",q:"有關第1型糖尿病之敘述，下列何者錯誤？",opts:["A.病因與自體免疫反應有關","B.空腹血清C-胜肽濃度無法偵測","C.會慢慢出現無症狀的高血糖情形","D.常見合併症為酮酸中毒（DKA）"],ans:[2],expl:"本題答案為C。第1型糖尿病通常起病較為「急遽」，常伴隨明顯的多尿、多渴、體重減輕等症狀，甚至可能直接以糖尿病酮酸中毒表現，並非「慢慢出現無症狀」的隱匿發病型態（此描述較符合第2型糖尿病的典型病程），此敘述有誤，為本題答案（C✗，題目問「何者錯誤」）。第1型糖尿病主要病因與自體免疫破壞胰島β細胞有關（A✓）；因胰島β細胞大量破壞，體內幾乎不再分泌胰島素，空腹血清C-胜肽濃度通常極低甚至無法偵測（B✓）；酮酸中毒（DKA）是第1型糖尿病常見且重要的急性合併症（D✓）。"},{n:424,no:74,subj:"內分泌系統",q:"有關甲狀腺功能低下之臨床表徵，下列何者錯誤？",opts:["A.周邊血管阻力增加","B.聽診心臟有分裂音","C.葡萄糖吸收增加","D.惡性（巨球性）貧血"],ans:[2],expl:"本題答案為C。甲狀腺功能低下時代謝率下降，腸胃蠕動及葡萄糖吸收速率通常會「減慢／降低」，並非增加，此敘述有誤，為本題答案（C✗，題目問「何者錯誤」）。甲狀腺功能低下時心輸出量下降，周邊血管代償性收縮，周邊血管阻力增加（A✓）；心包膜可能積液，聽診心音可能出現分裂音等異常（B✓）；甲狀腺功能低下可能合併自體免疫相關的惡性貧血（巨球性貧血），是需留意的相關血液學表現（D✓）。"},{n:425,no:75,subj:"心臟血管",q:"下列何者為永久性心臟節律器之適應症？",opts:["A.完全房室傳導阻斷","B.心房早期收縮","C.心室早期收縮","D.心房撲動"],ans:[0],expl:"本題答案為A。完全性房室傳導阻斷（third-degree AV block）因心房與心室電傳導完全中斷，心室仰賴不穩定的自主節律點維持跳動，屬於永久性心臟節律器植入的明確適應症，為本題答案。心房早期收縮、心室早期收縮及心房撲動多屬相對良性或可先以藥物、電燒術等方式處理的心律不整，並非永久性節律器的典型適應症（B、C、D✗）。"},{n:426,no:76,subj:"呼吸系統",q:"選擇鼻咽人工氣道適當尺寸之量測方式，下列何者正確？",opts:["A.嘴角至耳垂之距離","B.嘴角至下顎角之距離","C.鼻尖至耳垂之距離","D.鼻孔至下顎角之距離"],ans:[2],expl:"本題答案為C。選擇鼻咽人工氣道（nasopharyngeal airway）適當長度的標準量測方式，是測量病人「鼻尖至耳垂」的距離，以此長度估算氣道置入後尖端可到達咽部後壁上方、避免過深或過淺，為本題答案。嘴角至耳垂、嘴角至下顎角、鼻孔至下顎角的距離，皆非鼻咽人工氣道長度量測的標準方式（A、B、D✗；口咽人工氣道的量測方式則常以嘴角至耳垂或下顎角的距離為準，與鼻咽人工氣道的量測基準不同，須加以區辨）。"},{n:427,no:77,subj:"其他",q:"有關敗血症第一小時組合照護（hour-1 bundle）之敘述，下列何者正確？①應快給與抗生素使用，但須先做血液培養 ②施打1種或多種廣效抗生素療程約7～10天 ③病人低血壓或血清乳酸值大於2 mmol/L，應儘快輸液以40 mL/kg量輸注 ④病人低血壓在輸液後維持平均動脈壓至少大於或等於60 mmHg",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[0],expl:"本題答案為A（①②）。①敗血症的處置原則是儘速（1小時內）給予廣效抗生素，但應「先」採集血液培養檢體，再開始給藥，以免影響病原菌培養結果，此為國際指引（如Surviving Sepsis Campaign）強調的正確處置順序，此敘述正確；②廣效抗生素治療需要規劃完整療程（依感染源及病原菌調整，實務上常需要約一週以上的療程），此敘述大致合理，選①②＝A（本題答案）。須留意的是，國際準則（Surviving Sepsis Campaign 2018 hour-1 bundle）對於③、④所提及的數值與現行標準並不相符：低血壓或血清乳酸值應以「大於4 mmol/L」（而非2 mmol/L）作為快速輸液的判斷門檻，且建議輸液量為「30 mL/kg」（而非40 mL/kg）（③與國際指引數值不符）；輸液後目標平均動脈壓（MAP）應維持「大於或等於65 mmHg」（而非60 mmHg）（④與國際指引數值不符），此二敘述之數值與國際標準有落差。"},{n:428,no:78,subj:"其他",q:"當車禍造成嚴重創傷的病人送到急診出現：脈搏124次／分、呼吸32次／分胸部起伏明顯，血壓130/100 mmHg、皮膚溼且冰冷、尿量減少、呈現呼吸性鹼中毒情形，下列休克階段的分期，何者正確？",opts:["A.早期","B.代償期","C.進行期","D.不可逆期"],ans:[1],expl:"本題答案為B。病人心跳呼吸加快（代償性）、血壓仍維持尚可（甚至舒張壓上升，反映周邊血管收縮代償）、皮膚濕冷（周邊血管收縮）、尿量減少（腎血流代償性減少）、合併呼吸性鹼中毒（換氣過度代償），這些皆是身體透過交感神經興奮及血管收縮機轉，努力維持血壓與重要器官灌流的表現，符合休克「代償期」的典型臨床圖像，為本題答案。"},{n:429,no:79,subj:"其他",q:"有關嚴重特殊傳染性肺炎COVID-19之護理措施，下列何者正確？",opts:["A.無休克證據，仍應給予大量輸液治療","B.常規性給予全身性皮質類固醇","C.避免使用Nebulizer等氣霧式治療","D.常規使用高流量鼻導管（High-flow Nasal Oxygen, HFNO）給氧"],ans:[2],expl:"本題答案為C。COVID-19等經飛沫及氣溶膠傳播的呼吸道傳染病，使用Nebulizer等氣霧式治療可能產生大量帶病毒的氣溶膠微粒，增加病毒傳播及醫護人員暴露風險，故建議盡量避免使用、改採其他替代給藥方式（如定量噴霧吸入器），此為本題答案。無休克證據時應避免常規大量輸液，以免加重肺部負擔及肺水腫（A✗）；全身性皮質類固醇並非常規給予所有病人，需依疾病嚴重度及缺氧程度審慎評估後使用（如需氧治療的中重度病人才建議使用）（B✗）；高流量鼻導管（HFNO）並非常規使用於所有病人，需視病人缺氧程度評估，且使用時同樣需留意其氣溶膠傳播風險並採取適當防護（D✗）。"},{n:430,no:80,subj:"其他",q:"有關流感併發重症的敘述，下列何者錯誤？",opts:["A.第四類法定傳染病，一星期內需通報","B.高危險群包括精神、氣喘等慢性病病人","C.發病後，高燒（39℃）持續三天以上","D.淋巴球數目與CRP或LDH持續上升"],ans:[3],expl:"本題答案為D。流感併發重症的實驗室異常，典型呈現「淋巴球數目下降（低下）」，同時合併CRP或LDH等發炎指標「上升」，此敘述將淋巴球數目變化的方向描述錯誤（應為下降而非持續上升），為本題答案（D✗，題目問「何者錯誤」）。流感併發重症屬於第四類法定傳染病，須於規定時間內完成通報（A✓）；慢性病人（含精神疾病、氣喘等慢性呼吸道疾病病人）是流感併發重症的高危險群（B✓）；發病後持續高燒（如39℃以上）超過三天，是提示可能併發重症、需提高警覺的重要臨床線索（C✓）。"},{n:431,no:1,subj:"神經系統",q:"罹患腦下垂體腫瘤病人，醫師建議使用伽馬刀療法，下列何者顯示病人已了解本項治療？",opts:["A.治療時我的頭部會有一個切開傷口","B.治療時我不會疼痛也不會流血","C.治療後我的頭部會有留一條小型引流管","D.治療後我的腦瘤會立即消失"],ans:[1],expl:"本題答案為B。伽馬刀（Gamma Knife）屬立體定位放射線手術，並非傳統開顱手術，治療過程不會造成頭部切開傷口，也不會有疼痛或流血感（多以頭部固定架搭配局部麻醉進行），此為病人已了解衛教內容的正確回覆，為本題答案。伽馬刀治療不需開顱、無手術切口，故「會有頭部切開傷口」的說法有誤（A✗）；伽馬刀為放射線治療而非手術切除，術後不會留置引流管（C✗）；治療效果是使腫瘤細胞逐漸受放射線破壞、緩慢萎縮，通常需數月至數年才可觀察到縮小效果，並非治療後立即消失（D✗）。"},{n:432,no:2,subj:"神經系統",q:"與阿茲海默症病人的溝通技巧，下列何者不適宜？",opts:["A.若病人只能說出單字或短句，照顧者也要用簡單、易了解的字彙或圖片與其溝通","B.當病人出現眼神避開時，表示不了解溝通內容","C.溝通時，應該使用低音量、高音調及緩慢的速度","D.可以善用拍打和擁抱的觸覺刺激，協助病人表達"],ans:[2],expl:"本題答案為C。與阿茲海默症病人溝通時，應使用正常或稍低音量、正常或較低音調及緩慢清晰的語速，「高音調」的說話方式容易讓病人感受到情緒緊張，並不利於溝通，此敘述不適宜，為本題答案（C✗，題目問「何者不適宜」）。使用簡單字彙或圖片輔助溝通，可協助認知功能退化的病人理解訊息（A✓）；眼神避開、轉移視線常是病人感到困惑、無法理解溝通內容時的非語言表現，需要照顧者留意調整溝通方式（B✓）；適當觸覺刺激（如輕拍、擁抱）可作為語言之外的情感連結及安撫方式，有助溝通及情緒穩定（D✓）。"},{n:433,no:3,subj:"神經系統",q:"有關多發性硬化症病人的自我照顧之護理指導，下列敘述何者錯誤？",opts:["A.鼓勵病人多攝取水分和高纖食物，預防便秘","B.依排定如廁時間表，提醒病人如廁","C.減少社交參與，避免造成身體心像紊亂","D.若出現複視，可以使用眼罩遮住一眼，緩解複視"],ans:[2],expl:"本題答案為C。多發性硬化症病人應被鼓勵維持社交參與及規律生活，適度社交活動有助維持心理健康、減少憂鬱及身體心像紊亂的衝擊，「減少社交參與」的建議方向錯誤，為本題答案（C✗，題目問「何者錯誤」）。攝取足夠水分與高纖食物可預防因活動力下降或神經性腸道功能障礙造成的便秘（A✓）；建立規律如廁時間表有助改善神經性腸道及膀胱功能障礙（B✓）；複視為常見症狀，以眼罩交替遮蓋單眼可有效減緩複視造成的不適及跌倒風險（D✓）。"},{n:434,no:4,subj:"神經系統",q:"有關腦腫瘤病人術後發生尿崩症，下列敘述何者正確？",opts:["A.尿比重會比正常人高","B.會有尿量多、血漿滲透壓下降","C.因抗利尿素（ADH）分泌不足所致","D.可能有低血鈉導致抽搐症狀"],ans:[2],expl:"本題答案為C。中樞性尿崩症是因腦下垂體／下視丘手術或腫瘤影響，導致抗利尿激素（ADH）分泌不足，使腎小管水分再吸收能力下降，為本題答案。ADH不足使尿液無法濃縮，尿比重應「降低」而非升高（A✗）；雖尿量增多，但血漿滲透壓因大量水分流失應是「上升」而非下降，此為尿崩症核心病生理表現之一（B✗）；尿崩症大量排水後體液濃縮，臨床上較常伴隨「高血鈉」而非低血鈉及抽搐，此敘述電解質方向有誤（D✗）。"},{n:435,no:5,subj:"神經系統",q:"有關顱內壓升高的藥物治療，下列敘述何者錯誤？",opts:["A.類固醇治療可用於腦瘤引起的血管性腦水腫","B.Mannitol滲透性利尿劑若出現反彈現象會使腦水腫更嚴重","C.巴比妥酸鹽可降低腦組織代謝及使得血流均勻供應腦部","D.顱內壓升高病人皆須給與抗痙攣藥物以預防抽搐發作"],ans:[3],expl:"本題答案為D。顱內壓升高病人是否使用抗痙攣藥物，須視個別病人是否有癲癇病史、風險或已發生抽搐等臨床狀況而定，並非「皆須」給藥的絕對原則，此敘述過於絕對，為本題答案（D✗，題目問「何者錯誤」）。類固醇（如dexamethasone）可有效減輕腫瘤周圍血管性腦水腫（A✓）；Mannitol為滲透性利尿劑，若使用不當或於血腦屏障受損處滲漏，可能引發反彈性顱內壓升高，使腦水腫更嚴重，是臨床上需留意的重要副作用（B✓）；巴比妥酸鹽（barbiturate coma療法）可降低腦部代謝需求、使腦血流分布更均勻，用於難治型顱內壓升高的急救處置（C✓）。"},{n:436,no:6,subj:"神經系統",q:"有關巴金森氏症病人的日常活動指導，下列敘述何者錯誤？",opts:["A.行走時使用底面積較寬的助行器維持平衡","B.漸進式運動計畫以增加病人肌肉力量，鼓勵全關節運動","C.鼓勵病人以寬步伐行走，行走時身體直立，提醒腳跟先著地","D.因身體僵硬，鼓勵坐深且柔軟的椅子"],ans:[3],expl:"本題答案為D。巴金森氏症病人應鼓勵選用硬度適中、有扶手的椅子，方便利用扶手支撐起身；坐深且柔軟的椅子因缺乏支撐、下沉感增加，反而使病人更難自行站起，此建議方向錯誤，為本題答案（D✗，題目問「何者錯誤」）。使用底面積較寬的助行器（如四腳拐杖）有助增加穩定度、預防跌倒（A✓）；漸進式全關節運動及肌力訓練有助延緩肌肉僵硬及肌力退化（B✓）；提醒病人身體直立、寬步伐行走並注意腳跟先著地，可改善巴金森氏症特有的前傾小碎步步態、降低跌倒風險（C✓）。"},{n:437,no:7,subj:"神經系統",q:"進行意識評估，病人無法自動睜眼，叫喚才會睜開眼睛，人、地定向感清楚，但時間回答錯誤，能遵照指示做出正確的動作，其GCS昏迷量表，下列何者正確？",opts:["A.E4V5M6","B.E4V4M5","C.E3V4M6","D.E3V3M5"],ans:[2],expl:"本題答案為C。依題意：病人無法自動睜眼、需叫喚才睜眼，屬於E3（呼喚睜眼）；人、地定向感清楚但時間回答錯誤，屬於定向感錯誤，對應V4；能遵照指示做出正確動作，屬於M6（服從指令）。綜合為E3V4M6，為本題答案。E4代表能自動睜眼，與題意「無法自動睜眼」不符（A、B✗）；M5代表對疼痛刺激能定位（而非遵照指令），且V3代表僅能說出不恰當字詞，皆與題意不符（D✗）。"},{n:438,no:8,subj:"神經系統",q:"有關中風病人臥床姿勢擺位之護理措施，下列何者錯誤？",opts:["A.避免採高坐臥姿，防髖關節屈曲畸形","B.大腿外側使用粗隆捲軸，防止髖關節外旋","C.膝關節下墊枕頭，防止膝關節屈曲畸形","D.患側腋下墊枕頭，防止肩關節內收"],ans:[2],expl:"本題答案為C。中風病人擺位時，膝關節下方應避免長時間墊枕頭，以防造成膝關節持續屈曲攣縮及膕窩靜脈迴流受阻（增加深部靜脈栓塞風險），此建議方向錯誤，為本題答案（C✗，題目問「何者錯誤」）。避免高坐臥姿可預防髖關節長期屈曲導致攣縮畸形（A✓）；大腿外側使用粗隆捲軸可防止患側髖關節外旋，維持功能性擺位（B✓）；患側腋下墊枕頭可預防肩關節內收攣縮，維持肩部良好擺位（D✓）。"},{n:439,no:9,subj:"消化系統",q:"B型肝炎病毒帶原者且HBeAg（+），下列敘述何者正確？",opts:["A.目前是急性B型肝炎病毒的恢復期","B.對於B型肝炎病毒已經有免疫力","C.目前具有B型肝炎病毒高傳染力","D.可能會併發C型肝炎病毒感染"],ans:[2],expl:"本題答案為C。HBeAg（e抗原）陽性代表病毒在肝細胞內正處於活躍複製狀態，血液中病毒量高、傳染力強，為本題答案。HBeAg陽性反映病毒複製活躍，並非急性B肝的恢復期（急性感染恢復期HBeAg通常轉為陰性、e抗體轉為陽性）（A✗）；HBeAg陽性代表病毒持續複製中，並非已產生保護性免疫力（保護性免疫是B肝表面抗體，HBsAb陽性才代表具免疫力）（B✗）；HBeAg反映B型肝炎病毒本身的複製活性，與是否併發C型肝炎（不同病毒、不同傳染途徑）並無直接因果關係（D✗）。"},{n:440,no:10,subj:"消化系統",q:"進行內視鏡逆行性膽胰攝影檢查，若導管不易進入總膽管，可使用下列何種藥物讓歐迪氏括約肌（sphincter of Oddi）鬆弛？",opts:["A.Atropine","B.Buscopan","C.MgSO4","D.Xylocaine"],ans:[2],expl:"本題答案為C。硫酸鎂（MgSO4）在傳統膽道功能評估（如十二指腸引流術）教材中，是具有刺激膽囊收縮、同時促使歐迪氏括約肌（sphincter of Oddi）鬆弛雙重作用的藥物，可協助膽汁順利排出、利於內視鏡逆行性膽胰攝影術操作時導管通過括約肌，為本題答案。Atropine雖具抗膽鹼作用，但臨床上主要用於減少腺體分泌及降低迷走神經反射，可能伴隨心搏過速等副作用，並非此情境下的典型用藥（A✗）；Buscopan主要用於緩解腸胃道平滑肌痙攣絞痛，非促進Oddi括約肌鬆弛以利插管的典型用藥（B✗）；Xylocaine為局部麻醉藥物，不具鬆弛括約肌的藥理作用（D✗）。"},{n:441,no:11,subj:"消化系統",q:"有關升結腸造瘻的敘述，下列何者正確？",opts:["A.水分需求增加","B.糞便呈半成形狀","C.須定期做結腸灌洗","D.經訓練後排便可具規律性"],ans:[0],expl:"本題答案為A。升結腸位置接近小腸，腸內容物尚未經大腸充分再吸收水分，糞便多呈液狀至半液狀，水分流失量較乙狀結腸造瘻多，病人水分需求增加，需特別留意水分及電解質補充，為本題答案。升結腸造瘻排出糞便多為液狀，並非半成形狀（B✗，半成形狀較常見於降結腸或乙狀結腸造瘻）；結腸灌洗訓練排便規律性的方法，主要適用對象是降結腸或乙狀結腸造瘻，並不適用於升結腸造瘻（C、D✗）。"},{n:442,no:12,subj:"消化系統",q:"有關肝活體組織切片檢查，下列敘述何者正確？",opts:["A.檢查中，教導個案深呼吸，於吸氣後閉氣5～10秒進行穿刺","B.檢查後，立即協助個案正躺，傷口以彈繃加壓","C.檢查後，若病人主訴右肩疼痛，應懷疑橫膈下積血","D.檢查後，除短暫下床如廁外，需臥床4～6小時"],ans:[2],expl:"本題答案為C。肝臟活體組織切片檢查後，若病人主訴右肩疼痛，屬於轉移痛（referred pain），可能是橫膈受刺激或橫膈下出血積血所致的典型表現，需提高警覺並通知醫師評估，為本題答案。檢查中應教導病人「吐氣後閉氣」（而非吸氣後閉氣）進行穿刺，以降低氣胸及臟器損傷風險（A✗）；檢查後應協助病人採「右側臥」（而非正躺），並在穿刺部位下方墊枕加壓，利用臟器及體位加壓穿刺處以降低出血風險（B✗）；檢查後通常需臥床至少6～8小時以上並密切監測生命徵象，不建議短暫下床如廁，此描述之臥床限制不符合安全原則（D✗）。"},{n:443,no:13,subj:"消化系統",q:"有關迴腸造瘻口的護理指導，下列何者正確？",opts:["A.多吃蛋、乳酪等食物","B.多攝食高纖維的食物","C.記錄迴腸造瘻的引流量","D.每天攝取不超過1,500 c.c.的液體"],ans:[2],expl:"本題答案為C。迴腸造瘻排出液量較大且流失電解質（尤其鈉、鉀），密切記錄引流量有助評估體液電解質平衡、及早發現脫水徵象，為本題答案。迴腸造瘻病人應避免高纖及易產氣、易造成阻塞的食物，不建議以蛋、乳酪等作為飲食重點（A✗）；應「避免」（而非鼓勵）高纖維食物以降低造口阻塞風險（B✗）；因排出液量大、水分流失多，每天液體攝取量建議增加（通常需達3,000 c.c.以上），並非限制在1,500 c.c.以下（D✗）。"},{n:444,no:14,subj:"消化系統",q:"有關慢性胃炎之敘述，下列何者錯誤？",opts:["A.A型慢性胃炎主要與幽門桿菌的感染有關","B.B型慢性胃炎常發生在胃竇處","C.B型慢性胃炎的胃泌素值正常","D.A型慢性胃炎可能形成惡性貧血"],ans:[0],expl:"本題答案為A。A型慢性胃炎主要與「自體免疫」機轉有關（自體抗體攻擊胃壁細胞），好發於胃體及胃底部，與幽門螺旋桿菌感染關聯性較低；「與幽門桿菌感染有關」是B型慢性胃炎的典型病因，此敘述將兩型病因混淆，為本題答案（A✗，題目問「何者錯誤」）。B型慢性胃炎主要好發於胃竇部，與幽門螺旋桿菌感染相關（B✓）；B型慢性胃炎因胃竇G細胞受損程度不一，胃泌素數值可能正常或略降，相對A型明顯升高而言此敘述合理（C✓）；A型慢性胃炎因自體免疫破壞胃壁細胞，內在因子分泌不足，影響維生素B12吸收，可能導致惡性貧血（D✓）。"},{n:445,no:15,subj:"消化系統",q:"有關口腔癌的敘述，下列何者錯誤？",opts:["A.致病危險因子包括壓力、不良的口腔衛生及抽菸喝酒吃檳榔","B.黏膜出血可視為是口腔癌的前驅症狀","C.紅斑瘤有90%會變成鱗狀細胞癌","D.多見於舌頭及頰黏膜等部位"],ans:[1],expl:"本題答案為B。口腔白斑（leukoplakia）才是公認口腔癌常見的癌前病變／前驅徵象，「黏膜出血」並非典型前驅表現，為本題答案（B✗，題目問「何者錯誤」）。長期壓力、口腔衛生不良及菸酒檳榔等致癌物質暴露，皆為口腔癌明確的危險因子（A✓）；紅斑瘤惡性轉化率高，文獻常引述約90%左右會演變為鱗狀細胞癌，是口腔癌前病變中風險最高者（C✓）；口腔癌好發部位以舌頭及頰黏膜最常見（D✓）。"},{n:446,no:16,subj:"消化系統",q:"有關食道憩室之敘述，下列何者錯誤？",opts:["A.臨床上常以電腦斷層掃描來確定憩室的位置","B.症狀嚴重時，可將憩室切除後再將食道黏膜吻合","C.不可使用食道鏡或內視鏡檢查，以避免食道穿孔","D.病人餐後2小時勿執行劇烈運動，以避免食物逆流"],ans:[0],expl:"本題答案為A。食道憩室的診斷主要依賴鋇劑吞嚥攝影來確定憩室位置及大小，電腦斷層掃描並非診斷食道憩室的常規首選檢查方式，為本題答案（A✗，題目問「何者錯誤」）。症狀嚴重（如吞嚥困難、反覆吸入性肺炎）時，可考慮手術切除憩室並將食道黏膜重新吻合（B✓）；食道憩室壁較薄，接受食道鏡或內視鏡檢查確實有較高的穿孔風險，臨床上會謹慎評估或避免執行（C✓）；建議餐後避免立即劇烈運動並避免立刻躺平，以減少食物滯留憩室內逆流的機會（D✓）。"},{n:447,no:17,subj:"骨骼肌肉",q:"有關骨折病人發生脂肪栓塞之敘述，下列何者錯誤？",opts:["A.好發於長骨骨折的病人","B.多發生在骨折後72小時","C.獨特表徵是皮膚出現瘀斑","D.呼吸衰竭是常見的死因"],ans:[1],expl:"本題答案為B。脂肪栓塞症候群多發生於骨折後24～72小時「內」（尤其以24～48小時最常見），相對其他選項而言，「多發生在骨折後72小時」的時間描述不夠精確，為本題答案（B✗，題目問「何者錯誤」）。長骨骨折（尤其股骨）是脂肪栓塞好發的高風險族群（A✓）；皮膚（尤其前胸、頸部、腋下）出現瘀斑或出血點，是脂肪栓塞症候群較具特異性的臨床表徵之一（C✓）；急性呼吸衰竭是脂肪栓塞病人常見的死亡原因（D✓）。"},{n:448,no:18,subj:"骨骼肌肉",q:"有關不同關節炎病人的照護措施，下列何者錯誤？",opts:["A.類風濕性關節炎，急性期採等張運動","B.痛風性關節炎，需教導不可飲酒","C.退化性關節炎，每天需俯臥2次","D.退化性關節炎，應維持理想體重"],ans:[0],expl:"本題答案為A。類風濕性關節炎急性發炎期應以等長運動（isometric exercise，肌肉收縮但關節不活動）為主，以維持肌力同時避免加重發炎關節負擔及疼痛；「等張運動」在急性期可能加重關節發炎及疼痛，此建議不當，為本題答案（A✗，題目問「何者錯誤」）。痛風性關節炎病人應戒酒（尤其啤酒等普林含量高的酒類），因酒精會影響尿酸代謝、誘發急性發作（B✓）；退化性關節炎病人可每天俯臥數次，有助伸展髖關節、預防屈曲攣縮（C✓）；維持理想體重可減少負重關節的機械性磨損負擔（D✓）。"},{n:449,no:19,subj:"骨骼肌肉",q:"有關腕隧道症候群病人之身體檢查評估結果，下列何者正確？",opts:["A.湯瑪斯試驗（Thomas test）陽性反應","B.浮動試驗（ballottement test）陽性反應","C.麥默雷氏試驗（McMurray's test）陽性反應","D.費林氏徵象（Phalen's sign）陽性反應"],ans:[3],expl:"本題答案為D。費林氏徵象（Phalen's sign，雙手腕屈曲相對持續1分鐘後誘發正中神經症狀）陽性反應，是腕隧道症候群的典型身體檢查發現，為本題答案。湯瑪斯試驗用於評估髖關節屈曲攣縮，與腕隧道症候群無關（A✗）；浮動試驗用於評估膝關節腔內積液（B✗）；麥默雷氏試驗用於評估膝關節半月板損傷（C✗），皆與腕隧道症候群無關。"},{n:450,no:20,subj:"骨骼肌肉",q:"有關骨質疏鬆症病人對於護理指導之回覆，下列何者表示病人已經清楚指導內容？",opts:["A.「我要多吃高蛋白食物來增加鈣質的吸收。」","B.「我可以每天打網球或保齡球來防止骨質流失。」","C.「我要多吃小魚乾、豆類食物以攝入足夠的鈣質。」","D.「我要同時吃高纖與高鈣食物來增加鈣質吸收。」"],ans:[2],expl:"本題答案為C。小魚乾、豆類（黃豆製品含異黃酮及鈣質）皆為天然高鈣食物來源，此陳述顯示病人已理解如何從飲食中攝取足夠鈣質，為本題答案。高蛋白食物攝取過量反而可能增加尿鈣排泄、不利鈣質留存，為錯誤認知（A✗）；網球、保齡球等需瞬間爆發力及扭轉動作的運動，對骨質疏鬆症病人跌倒及骨折風險較高，並非建議的負重運動方式（B✗）；高纖食物中的植酸、草酸可能與鈣質結合形成不易吸收的複合物，建議與高鈣食物分開攝取時段，而非同時大量併食（D✗）。"},{n:451,no:21,subj:"感官系統",q:"白內障可能出現的症狀，下列何者正確？①眼睛痛 ②眼睛紅 ③視力模糊 ④瞳孔變灰或白色",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[3],expl:"本題答案為D（③④）。③白內障因水晶體混濁，最典型症狀即為漸進性、無痛性視力模糊；④水晶體混濁在瞳孔區可能呈現灰白色或乳白色混濁外觀，此二者皆為白內障典型症狀，選③④＝D（本題答案）。白內障通常為無痛的漸進性病程，眼睛痛及眼睛紅並非其典型症狀（若合併眼痛眼紅，需考慮續發性青光眼等其他急症）（①②錯誤）。"},{n:452,no:22,subj:"感官系統",q:"一位高度數近視的病人，主訴眼前突然出現一群浮動的黑點，而且有部分視野缺失，下列建議何者不適宜？",opts:["A.立刻臥床","B.避免用力","C.雙眼覆蓋眼罩","D.立即冰敷"],ans:[3],expl:"本題答案為D。眼前突然出現大量浮動黑點合併視野缺損，高度懷疑視網膜剝離的警訊症狀，應盡速就醫評估，冰敷對視網膜剝離並無治療效益，且可能延誤就醫時機，此建議不適宜，為本題答案（D✗，題目問「何者不適宜」）。立刻臥床休息可減少眼球活動、降低視網膜剝離範圍擴大的風險（A✓）；避免用力（如提重物、憋氣）可預防眼壓突然升高加重視網膜剝離（B✓）；雙眼覆蓋眼罩可減少眼球轉動，避免病情惡化，並儘速安排就醫（C✓）。"},{n:453,no:23,subj:"感官系統",q:"有關鼻部手術後的護理指導，下列何者最不適宜？",opts:["A.抬高床頭採半坐臥姿勢","B.勿用太熱的水洗臉、洗澡","C.教導由口呼吸及注意口腔衛生","D.出院後若鼻出血，自行加壓止血即可"],ans:[3],expl:"本題答案為D。鼻部手術後若發生鼻出血，應立即通知醫護人員評估處理，不應自行加壓止血了事，以免延誤活動性出血或血塊阻塞等併發症的及時處置，此建議最不適宜，為本題答案（D✗，題目問「何者最不適宜」）。抬高床頭採半坐臥姿勢有助減輕鼻部腫脹及降低出血風險（A✓）；避免使用太熱的水洗臉洗澡，以防血管擴張增加出血機會（B✓）；鼻腔填塞物移除前病人多須經口呼吸，應加強口腔衛生指導以維持舒適及預防口乾感染（C✓）。"},{n:454,no:24,subj:"感官系統",q:"有關喉癌病人接受全喉切除術的敘述，下列何者正確？",opts:["A.氣管造口為暫時性的","B.術後嗅覺喪失，但不影響味覺","C.適合第一、二期喉癌病人","D.術後仍可恢復正常的發聲功能"],ans:[1],expl:"本題答案為B。全喉切除術後因鼻腔氣流路徑改變（不再經鼻呼吸），嗅覺功能會受影響而喪失或明顯減退，但味覺（主要由味蕾負責）通常不受影響，為本題答案。全喉切除術後氣管造口為永久性（而非暫時性），病人終生經頸部氣管造口呼吸（A✗）；全喉切除術通常適用於較晚期喉癌，早期（第一、二期）多可採部分喉切除或放射線治療等保留喉功能的方式（C✗）；術後聲帶已切除，需透過食道語、電子喉或氣管食道語等方式重新學習發聲，並非能恢復正常發聲功能（D✗）。"},{n:455,no:25,subj:"心臟血管",q:"有關心包填塞（cardiac tamponade）的徵象，下列何者錯誤？",opts:["A.奇異脈，吸氣時脈搏變弱","B.心音模糊低沉","C.脈搏壓變寬","D.頸靜脈怒張"],ans:[2],expl:"本題答案為C。心包填塞因心包腔積液壓迫心臟，心搏出量下降，脈搏壓（收縮壓與舒張壓之差）會因心搏量減少而「變窄」，並非變寬，此敘述方向錯誤，為本題答案（C✗，題目問「何者錯誤」）。奇異脈（吸氣時因胸內壓變化使左心室充盈量進一步下降、脈搏明顯減弱）是心包填塞的典型徵象（A✓）；心包腔積液使心音傳導受阻，聽診呈現心音低沉模糊（B✓）；心臟受壓迫使靜脈回流受阻，可見頸靜脈怒張（D✓）。"},{n:456,no:26,subj:"心臟血管",q:"有關急性心肌梗塞的診斷檢查，下列敘述何者錯誤？",opts:["A.血液中肌酸磷酸激酶（CPK）升高可以表示組織損傷","B.心肌旋轉蛋白（Troponin I）對心肌受損具有特異性及敏感性","C.心電圖出現Q波表示心肌受損在表層","D.心電圖ST間段及T波的改變可以協助判斷心肌是缺氧、缺血或壞死"],ans:[2],expl:"本題答案為C。心電圖出現病理性Q波，代表心肌已發生「透壁性（穿透心肌全層）」的壞死損傷，並非僅表層受損，此敘述方向有誤，為本題答案（C✗，題目問「何者錯誤」）。CPK（尤其CK-MB）升高可反映心肌等組織損傷程度（A✓）；心肌旋轉蛋白（Troponin I/T）是目前診斷心肌梗塞最具特異性及敏感性的生物標記（B✓）；心電圖ST節段上升或壓低、T波倒置等變化，可協助判斷心肌缺氧、缺血或壞死的階段及程度（D✓）。"},{n:457,no:27,subj:"心臟血管",q:"有關裝置植入式自動心律轉換去顫器（AICD）病人居家護理指導之敘述，下列何者錯誤？",opts:["A.AICD發出電擊時，若觸摸病人可能有觸電感","B.發生打嗝不停的情形時，可以多飲水或重複憋氣","C.術後4～6週內患肢避免提重物以及劇烈肩部運動","D.可使用微波爐、電鍋等加熱電器用品，但應避免核磁共振檢查"],ans:[1],expl:"本題答案為B。AICD病人若出現持續打嗝不停，可能提示電極位置異常、刺激橫膈神經，應儘速回診由醫師評估處理，並非可自行以多飲水或憋氣方式緩解，為本題答案（B✗，題目問「何者錯誤」）。AICD發出電擊瞬間，旁人若觸摸病人身體，確實可能感受到輕微觸電感，屬正常物理現象，衛教上應提醒同住者留意（A✓）；術後患側肢體4～6週內應避免提重物及大幅度肩部運動，以防電極導線移位（C✓）；應避免強力磁場環境（如核磁共振檢查），但一般家用微波爐、電鍋等居家電器對AICD運作影響甚微，可正常使用（D✓）。"},{n:458,no:28,subj:"心臟血管",q:"有關心房纖維顫動病人服用Warfarin之護理指導，下列何者錯誤？",opts:["A.拔牙前，須告知醫師目前使用Warfarin治療心律不整","B.避免食用深綠色食物，以免降低藥效","C.避免補充黑木耳、銀杏等食品，以免增強藥效","D.若忘記服藥，需於次日服用雙倍劑量，以維持藥物濃度"],ans:[3],expl:"本題答案為D。服用Warfarin病人若忘記服藥，應依醫囑於發現後儘快補服當日劑量或依藥師／醫師指示處理，絕對不可自行雙倍劑量補服，以免增加出血風險，為本題答案（D✗，題目問「何者錯誤」）。拔牙等侵入性處置前，應主動告知醫師目前服用Warfarin，以評估出血風險並調整用藥（A✓）；深綠色蔬菜富含維生素K，可能拮抗Warfarin效果、降低藥效，應避免大量或不規律攝取（B✓）；黑木耳、銀杏等具抗凝血活性的天然食品，可能加強Warfarin藥效、增加出血風險，應避免自行大量補充（C✓）。"},{n:459,no:29,subj:"心臟血管",q:"有關心律不整病人照護之敘述，下列何者錯誤？",opts:["A.在施行整流術前，應給與Valium，以減少病人焦慮與不適","B.裝置心臟節律器的病人，應隨身攜帶心臟節律器之識別卡","C.心室上心搏過速（SVT）的病人，可教導伐氏操作法（Valsalva's maneuver）","D.服用Warfarin的病人，需定期監測部分凝血活酶時間（PTT）"],ans:[3],expl:"本題答案為D。服用Warfarin病人應定期監測的凝血功能指標是凝血酶原時間（PT）及國際標準化比值（INR），而非部分凝血活酶時間（PTT，此為監測heparin治療效果的指標），為本題答案（D✗，題目問「何者錯誤」）。心臟整流術前給予Valium等鎮靜藥物，可減少病人執行過程中的焦慮與不適感（A✓）；裝置心臟節律器的病人應隨身攜帶識別卡，以利就醫、安檢等場合告知醫護人員（B✓）；室上心搏過速病人可教導Valsalva's maneuver（憋氣用力）等增加迷走神經張力的方式嘗試終止心律不整發作（C✓）。"},{n:460,no:30,subj:"骨骼肌肉",q:"下列何者為骨性關節炎的症狀和徵象？",opts:["A.35歲女性，雙手呈現尺側偏移及天鵝頸","B.45歲男性，全身倦怠、肌肉痠痛、發燒、體重減輕","C.30歲女性，對稱性的關節受侵犯","D.40歲男性，X光顯示關節間隙減少及骨贅形成"],ans:[3],expl:"本題答案為D。骨性（退化性）關節炎好發於中老年族群，X光典型可見關節間隙變窄及骨贅（骨刺）形成，此描述符合典型影像學表現，為本題答案。雙手尺側偏移及天鵝頸畸形是類風濕性關節炎的典型變形，並非骨性關節炎（A✗）；全身倦怠、肌肉痠痛、發燒、體重減輕等全身性症狀，較常見於類風濕性關節炎等自體免疫發炎性關節炎（B✗）；對稱性關節受侵犯是類風濕性關節炎的典型分布特徵，骨性關節炎則多呈非對稱性、負重關節優先受累（C✗）。"},{n:461,no:31,subj:"心臟血管",q:"靜脈注射不當造成血管紅、腫、痛是屬於下列何種血管問題？",opts:["A.靜脈曲張","B.血栓性靜脈炎","C.靜脈功能不全","D.靜脈鬱滯性潰瘍"],ans:[1],expl:"本題答案為B。靜脈注射部位血管出現紅、腫、痛的局部發炎表現，屬於血栓性靜脈炎的典型徵象，通常因導管留置時間過長、藥物刺激性或感染所致，為本題答案。靜脈曲張是靜脈瓣膜功能不良造成的血管迂曲擴張，並非靜脈注射引發的急性發炎反應（A✗）；靜脈功能不全是慢性靜脈回流障礙的病理狀態（C✗）；靜脈鬱滯性潰瘍是慢性靜脈功能不全長期未處理下肢皮膚破損的結果，並非靜脈注射當下的急性表現（D✗）。"},{n:462,no:32,subj:"心臟血管",q:"下列何者最適合接受機械性人工心瓣膜置換術？",opts:["A.出血傾向者","B.計畫生育婦女","C.50歲的停經婦女","D.80歲的女性老人"],ans:[2],expl:"本題答案為C。機械性人工瓣膜耐用性佳但術後需終生服用抗凝血劑，50歲停經婦女預期壽命尚長、可從機械瓣膜的長效耐用性中獲益，且停經後無孕產計畫，服用抗凝血劑不涉及胎兒致畸風險的疑慮，為相對合適的選擇，為本題答案。有出血傾向者因需終生服用抗凝血劑、出血風險過高，並不適合機械瓣膜（應優先考慮生物瓣膜）（A✗）；計畫生育婦女因Warfarin具致畸胎風險，懷孕期間用藥管理相當複雜及高風險，通常不建議選擇機械瓣膜（B✗）；80歲高齡老人預期壽命較短，且高齡病人使用抗凝血劑的出血風險相對較高，臨床上多傾向選擇不需終生抗凝血、但耐用年限較短的生物瓣膜（D✗）。"},{n:463,no:33,subj:"腫瘤血液",q:"接受同步化學放射治療（CCRT）的病人，其抽血報告顯示WBC 3000/μL、seg 20%、band 5%、monocyte 12%、Hb 10.5 g/dL、platelet 50000/μL，下列敘述何者錯誤？",opts:["A.發燒時避免使用NSAID退燒","B.轉至負壓式單人病房保護隔離","C.避免攝食未妥善處理之生鮮蔬果","D.注射G-CSF以提升嗜中性白血球數"],ans:[1],expl:"本題答案為B。此病人WBC 3000/μL，seg 20%、band 5%，計算絕對嗜中性白血球數（ANC）約為750/μL，屬嚴重嗜中性白血球低下，確實需採保護性隔離，但應轉至「正壓」（而非負壓）單人病房，以避免外界病原菌進入病室感染免疫低下病人；負壓病房用於「傳染病」病人的空氣隔離、避免病室內病原菌外流，兩者隔離目的方向相反，為本題答案（B✗，題目問「何者錯誤」）。嗜中性白血球低下病人發燒時應避免使用NSAID退燒，以免掩蓋感染徵象或加重出血風險（A✓）；應避免生食或未妥善處理的生鮮蔬果，降低病原菌經腸胃道入侵的風險（C✓）；必要時可注射G-CSF促進嗜中性白血球生成、縮短低下期（D✓）。"},{n:464,no:34,subj:"腫瘤血液",q:"有關非何杰金氏淋巴瘤預後不佳的因素，下列何者正確？①年齡小於50歲 ②身體功能狀態不佳 ③淋巴結外侵犯 ④血紅素值小於12 g/dL",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[3],expl:"本題答案為D（②③④）。國際預後指標（IPI）中，②身體功能狀態不佳、③淋巴結外器官侵犯、④診斷時血紅素偏低（一般以低於12 g/dL為參考切點），皆為非何杰金氏淋巴瘤預後不佳的已知危險因子，選②③④＝D（本題答案）。IPI預後不佳因子中的年齡切點是大於60歲（而非小於50歲），年齡小於50歲一般反而屬於預後相對較好的族群，此描述年齡方向有誤（①錯誤）。"},{n:465,no:35,subj:"腫瘤血液",q:"有關瀰漫性血管內凝血的敘述，下列何者正確？①與感染有關 ②常出現凝血症狀 ③檢查時纖維蛋白原下降 ④常出現出血症狀",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[2],expl:"本題答案為C（①③④）。①DIC常見誘因包括嚴重感染（敗血症）等疾病狀態；③DIC因大量凝血因子及纖維蛋白原被消耗，檢驗數值上纖維蛋白原濃度會下降；④DIC後期因凝血因子及血小板大量耗竭，臨床上反而常以「出血」症狀為主要表現，此三者敘述皆正確，選①③④＝C（本題答案）。DIC病程雖以廣泛微小血栓形成為起始機轉，但臨床上更常見、更具代表性的是凝血因子耗竭後的廣泛性出血傾向，「常出現凝血症狀」的描述相對不精確（②錯誤）。"},{n:466,no:36,subj:"腫瘤血液",q:"有關異體周邊血液幹細胞移植之敘述，下列何者正確？",opts:["A.捐贈者捐贈時不需施打白血球生成激素","B.受贈者的人類白血球抗原（HLA）配對不需完全吻合","C.宿主較易有慢性移植物抗宿主反應（GVHD）","D.宿主不易受病毒感染"],ans:[2],expl:"本題答案為C。異體移植（allogeneic transplant）中，供者的免疫T細胞可能將宿主組織視為外來物而發動免疫攻擊，此即移植物抗宿主反應（GVHD），慢性GVHD在異體移植病人中並不少見，是異體移植特有且需長期追蹤的重要併發症，為本題答案。捐贈者在捐贈周邊血幹細胞前，通常需先施打白血球生成激素（G-CSF）數天，以促進骨髓內幹細胞動員釋放至週邊血液，便於採集，此敘述方向有誤（A✗）；異體移植的成功與安全性高度仰賴供受者間HLA的高度吻合，配對吻合度愈高排斥及GVHD風險愈低，並非「不需完全吻合」（B✗）；宿主接受異體移植後因免疫系統重建期間功能低下，反而容易受病毒等病原體感染，並非不易受感染，此敘述方向相反（D✗）。"},{n:467,no:37,subj:"腫瘤血液",q:"周女士，52歲，本身有高血壓及乳癌家族史，有抽菸，在一次回診時表示自己年紀越來越大，很擔心會跟媽媽一樣罹癌，下列建議何者錯誤？",opts:["A.不用過度擔心，若自覺乳房有異狀再做乳房攝影","B.鼓勵戒菸、轉介戒菸門診","C.將運動融入生活，可以走樓梯代替搭電梯等","D.適度日曬，促進維生素D合成"],ans:[0],expl:"本題答案為A。依衛生福利部國民健康署乳癌篩檢政策，建議40歲以上（具乳癌家族史者更應及早開始）婦女定期（每2年1次）接受乳房X光攝影篩檢，而非等到自覺乳房有異狀才檢查——篩檢的核心價值正是在無症狀階段及早發現。此病人已52歲且具明確乳癌家族史，屬高風險族群，更應主動規律篩檢而非被動等待症狀出現，此建議不恰當，為本題答案（A✗，題目問「何者錯誤」）。鼓勵戒菸並轉介戒菸門診，有助降低整體癌症及心血管疾病風險（B✓）；規律運動（如以走樓梯取代搭電梯）已有實證有助降低乳癌風險（C✓）；適度日曬有助皮膚合成維生素D，為合理的一般性健康建議（D✓）。"},{n:468,no:38,subj:"腫瘤血液",q:"有關骨髓抽吸檢查之敘述，下列何者錯誤？",opts:["A.執行時可採局部麻醉","B.對於無法解釋的肝脾腫大不具診斷功能","C.成人常見抽吸部位可在第2～3肋間胸骨處或前後腸骨嵴","D.檢查結果可決定癌症分期，作為治療依據"],ans:[1],expl:"本題答案為B。骨髓抽吸檢查除評估骨髓造血功能異常外，對於「無法解釋的肝脾腫大」（可能與血液惡性疾病浸潤骨髓有關）仍具重要診斷價值，並非不具診斷功能，為本題答案（B✗，題目問「何者錯誤」）。骨髓抽吸檢查通常在局部麻醉下執行，病人清醒且能配合（A✓）；成人常見骨髓抽吸部位為髂骨前後腸骨嵴，胸骨柄（第2～3肋間胸骨處）亦為可選部位之一（C✓）；骨髓檢查結果可作為癌症分期及後續治療方針的重要依據（D✓）。"},{n:469,no:39,subj:"腫瘤血液",q:"有關癌症分期系統類型之敘述，下列何者錯誤？",opts:["A.治療前的臨床分期，可以cTNM表示","B.手術後切除病理組織做的分期，可以sTNM表示","C.復發或再次治療，可以rTNM表示","D.治療後分期，可用ycTNM表示"],ans:[1],expl:"本題答案為B。手術後切除病理組織所做的分期，國際AJCC/UICC分期系統標準應以「pTNM」（病理分期）表示，而非「sTNM」，此代號描述有誤，為本題答案（B✗，題目問「何者錯誤」；正確前綴為c＝臨床分期、p＝病理分期、y＝新輔助治療後分期、r＝復發分期、a＝驗屍分期，並無「s」這個標準前綴）。治療前依臨床評估所做的分期以cTNM表示（A✓）；癌症復發或再次治療前重新評估的分期以rTNM表示（C✓）；接受新輔助治療後之分期以ycTNM／ypTNM表示（D✓）。"},{n:470,no:40,subj:"腫瘤血液",q:"有關癌症病人血小板減少症之處置，下列何者正確？",opts:["A.可給與非類固醇抗發炎藥物緩解疼痛","B.必要時輸注凝血因子避免自發性出血","C.給與Bisacodyl supp避免便秘而閉氣用力","D.天冷時鼻黏膜塗擦凡士林保濕"],ans:[3],expl:"本題答案為D。血小板低下病人皮膚黏膜較脆弱易出血，天冷時鼻黏膜容易因乾燥而龜裂出血，塗擦凡士林保濕可降低此類黏膜出血風險，為本題答案。血小板低下病人應避免使用NSAID（具抗血小板凝集作用，會加重出血風險）緩解疼痛（A✗）；血小板低下並非凝血因子缺乏，補充凝血因子對改善血小板數量或功能並無效益，血小板嚴重低下且有出血徵象時應考慮輸注血小板（B✗）；Bisacodyl為刺激性瀉劑，血小板低下病人便秘處置臨床上應優先選用溫和的軟便劑（如lactulose）而非刺激性瀉劑（C✗）。"},{n:471,no:41,subj:"腫瘤血液",q:"有關良性腫瘤及惡性腫瘤之敘述，下列何者正確？",opts:["A.惡性腫瘤因沒有包膜，手術治療成效佳","B.不管良性或惡性腫瘤，細胞排列皆不規則","C.良性腫瘤以浸潤方式侵入周圍組織","D.良性腫瘤若生長於密閉空間，會阻塞管腔產生各種症狀"],ans:[3],expl:"本題答案為D。良性腫瘤雖不具侵襲性，但若生長於密閉或狹窄空間（如顱內、腸腔等），仍可能因體積增大而壓迫周圍組織或阻塞管腔，產生相對應的壓迫或阻塞症狀，為本題答案。惡性腫瘤因缺乏包膜、呈浸潤性生長，手術邊界不易完全切除乾淨，治療成效反而較有包膜的良性腫瘤困難，此敘述方向有誤（A✗）；良性腫瘤細胞分化良好、排列規則；惡性腫瘤細胞則分化不良、排列不規則，兩者有明顯差異，並非「皆不規則」（B✗）；「浸潤性」生長侵入周圍組織是惡性腫瘤的特徵，良性腫瘤多以膨脹性生長方式擠壓周圍組織，此敘述將兩者混淆（C✗）。"},{n:472,no:42,subj:"腫瘤血液",q:"下列那一類白血病的預後最好？",opts:["A.T細胞型急性淋巴性","B.B細胞型急性淋巴性","C.血小板缺乏的慢性淋巴性","D.芽細胞期慢性骨髓性"],ans:[0],expl:"本題答案為A。四個選項中，血小板缺乏的慢性淋巴性白血病及芽細胞期（疾病已進展至急性轉化的末期階段）的慢性骨髓性白血病，皆屬病程已進展、預後明確不佳的疾病狀態；相對而言，急性淋巴性白血病經現代化療方案治療，整體預後在各類白血病中屬較好的族群，為本題答案。惟須留意，現行文獻顯示：在採用現代風險分層化療方案下，兒童T細胞型與B細胞型急性淋巴性白血病的5年整體存活率已相當接近（皆可達85～90%左右），兩者差異已隨治療進步大幅縮小，臨床上兩者皆屬預後相對良好的類型，傳統教材所述T細胞型「優於」B細胞型的相對排序在現代文獻中已不若過去明確（B✗，惟此選項本身亦屬相對預後良好之類型）。血小板缺乏的慢性淋巴性白血病代表疾病已合併骨髓造血功能受損，預後相對較差（C✗）；芽細胞期慢性骨髓性白血病代表疾病已轉化為急性期，預後在四者中最差（D✗）。"},{n:473,no:43,subj:"其他",q:"護理之家發生火災，許多住民吸入性灼傷，下列緊急處置，何者正確？",opts:["A.維持呼吸道通暢並由面罩給100%的氧氣吸入","B.發生呼吸窘迫時不適合進行插管","C.安排病人採平躺側臥","D.建立由口鼻腔進入的液體輸液通道"],ans:[0],expl:"本題答案為A。吸入性灼傷病人常合併一氧化碳中毒及呼吸道黏膜腫脹風險，應優先維持呼吸道通暢，並以面罩給予100%高濃度氧氣，加速一氧化碳自血紅素解離、改善組織缺氧，為本題答案。吸入性灼傷病人呼吸道黏膜腫脹可能持續進展，一旦出現呼吸窘迫徵象應儘早考慮插管，因喉部水腫惡化後插管難度將大幅增加甚至無法插管，並非不適合插管（B✗）；應採抬高床頭的半坐臥姿（若無禁忌），以利呼吸及減輕呼吸道水腫，非平躺側臥（C✗）；緊急補液應建立靜脈（而非口鼻腔）輸液通道，以精確調控大量體液復甦速度（D✗）。"},{n:474,no:44,subj:"其他",q:"王同學騎機車不慎與汽車擦撞引發機車起火，右小腿外側有15公分×7.5公分的皮膚受損，診斷為深二度燒傷。下列臨床表徵何者正確？①皮膚變紅無水泡 ②皮膚呈灰白色有水泡 ③劇烈疼痛感 ④汗腺及毛囊完整 ⑤表皮及真皮層受損",opts:["A.①③④","B.①④⑤","C.②③⑤","D.②④⑤"],ans:[3],expl:"本題答案為D（②④⑤）。②深二度燒傷因真皮層血管受損，皮膚常呈現灰白色並有大水泡；④深二度燒傷傷及真皮層但汗腺、毛囊等皮膚附屬器官因位置較深，通常仍部分保留完整；⑤深二度燒傷傷及表皮層及大部分真皮層，此三者描述皆符合深二度燒傷的病理表現，選②④⑤＝D（本題答案）。皮膚變紅無水泡是淺二度（淺層）燒傷的表現，並非深二度（①錯誤）；深二度燒傷因真皮神經末梢部分受損，痛覺較淺二度燒傷遲鈍（劇烈疼痛感反而是淺二度燒傷神經末梢完整暴露的特徵），此敘述與深二度燒傷實際痛覺表現不符（③錯誤）。"},{n:475,no:45,subj:"其他",q:"有關皮膚癌的預防或處置，下列敘述何者錯誤？",opts:["A.長時間暴露陽光下，無需重複塗抹SPF15以上的防曬乳液","B.陰天也要採取防曬措施","C.皮膚病灶變大或發生色素沉著現象應立即就醫","D.造成曬傷時可以用冷水浸泡消褪"],ans:[0],expl:"本題答案為A。長時間暴露於陽光下，防曬乳液防護效果會隨時間及流汗、摩擦而遞減，應每隔約2小時重複塗抹，而非無需重複塗抹，此建議有誤，為本題答案（A✗，題目問「何者錯誤」）。紫外線可穿透雲層，陰天仍應採取防曬措施（B✓）；皮膚病灶出現變大、變形或色素沉著改變等警訊，應提高警覺盡速就醫（C✓）；曬傷後可用冷水浸泡或冷敷降溫，緩解灼熱不適感（D✓）。"},{n:476,no:46,subj:"其他",q:"有關膠帶等黏性產品使用之敘述，下列何者正確？",opts:["A.移除膠帶時，應垂直、快速才不會痛太久","B.膠帶造成皮膚的損傷好發在嬰幼兒和水腫病人","C.移除膠帶時需支撐邊緣皮膚，以180度逆毛方向移除","D.使用膠帶前，可以在皮膚上塗抹優碘以增加黏性"],ans:[1],expl:"本題答案為B。嬰幼兒皮膚角質層較薄嫩、水腫病人皮膚張力及完整性較差，兩者皮膚對膠帶黏著及移除時的機械性摩擦較為脆弱敏感，屬於膠帶相關皮膚損傷的高風險族群，為本題答案。移除膠帶時應平行皮膚、緩慢移除，而非垂直快速，以降低皮膚撕裂傷風險（A✗）；移除膠帶時應支撐邊緣皮膚並順著毛髮生長方向移除，以減少疼痛及毛囊損傷，「逆毛方向」的描述有誤（C✗）；使用膠帶前皮膚應保持清潔乾燥，塗抹優碘等藥劑反而可能降低黏著度或造成皮膚刺激，並非增加黏性的正確做法（D✗）。"},{n:477,no:47,subj:"其他",q:"有關細胞毒殺過敏反應之敘述，下列何者錯誤？",opts:["A.參與此類過敏反應的抗體是IgG或IgM","B.Rh血型不合屬此類過敏反應","C.參與此類過敏反應的細胞是吞噬細胞及殺手細胞","D.紅血球、白血球、血小板的作用不受此類過敏反應影響"],ans:[3],expl:"本題答案為D。第二型過敏反應（細胞毒殺型）中，抗體（IgG或IgM）與細胞表面抗原結合後，會活化補體系統或吞噬細胞、殺手細胞攻擊該細胞，直接影響並破壞紅血球、白血球、血小板等血液細胞（如自體免疫溶血性貧血、Rh血型不合溶血反應），「不受影響」的敘述與此型過敏反應的核心病理機轉相反，為本題答案（D✗，題目問「何者錯誤」）。此型過敏反應主要涉及的抗體為IgG或IgM（A✓）；Rh血型不合是第二型過敏反應的典型例子（B✓）；此型反應主要透過吞噬細胞及殺手細胞攻擊被抗體標記的目標細胞（C✓）。"},{n:478,no:48,subj:"其他",q:"有關器官移植前的組織配對，降低排斥反應之檢驗項目，不包含下列何者？",opts:["A.ABO及Rh血型","B.人類白血球抗原","C.交叉配對試驗","D.梅毒血清檢查"],ans:[3],expl:"本題答案為D。梅毒血清檢查是器官捐贈者的一般性感染疾病篩檢項目（避免透過移植傳播感染），並非用於評估「組織相容性、降低排斥反應」的配對檢驗項目，為本題答案（題目問「不包含下列何者」，即不屬於組織配對項目）。ABO及Rh血型是移植前必須確認相符的基本配對項目，血型不合會引發超急性排斥反應（A為組織配對項目）；HLA配對是決定移植排斥風險及移植物存活率的核心組織相容性指標（B為組織配對項目）；交叉配對試驗用於檢測受者血清中是否已存在對抗供者淋巴球的抗體，是移植前必要的最後把關檢驗（C為組織配對項目）。"},{n:479,no:49,subj:"其他",q:"有關全身性紅斑性狼瘡病人之護理指導，下列何者錯誤？",opts:["A.外出時，應戴太陽眼鏡及帽子，著長袖上衣及長褲，以避免日曬","B.女性病人可使用保險套或避孕藥來避孕","C.當處於壓力、生病或有感染時，應告知醫師以調整藥物劑量","D.關節疼痛時，可應用冷熱敷來緩解"],ans:[1],expl:"本題答案為B。全身性紅斑性狼瘡（SLE）病人若考慮避孕，應避免使用含雌激素成分的口服避孕藥，因雌激素可能誘發或加重SLE疾病活性、增加血栓風險，建議改採保險套等屏障式避孕法；「可使用保險套或避孕藥」將兩種方式並列為皆合適，並不精確，為本題答案（B✗，題目問「何者錯誤」）。SLE病人對紫外線敏感，日曬可能誘發皮膚病灶惡化或全身性疾病活性上升，外出應加強防曬（A✓）；處於壓力、感染或生病等狀態下，SLE疾病活性可能上升，應告知醫師評估是否需調整藥物劑量（C✓）；關節疼痛可透過冷熱敷等非藥物方式輔助緩解不適（D✓）。"},{n:480,no:50,subj:"其他",q:"有關後天免疫缺乏症候群（AIDS）病人出現伺機性感染之敘述，下列何者正確？",opts:["A.CD4細胞數值在350 cells/μL以下容易發生","B.以口腔念珠球菌感染最為常見","C.巨細胞病毒（CMV）感染的治療可服用Zovirax","D.肺囊蟲肺炎感染會造成病人乾咳、用力咳嗽症狀"],ans:[3],expl:"本題答案為D。肺囊蟲肺炎（PCP）好發於CD4細胞數低於200 cells/μL的病人，典型表現為漸進性乾咳、活動後呼吸喘及低血氧，此描述精確符合PCP的臨床特徵，為本題答案。CD4細胞數值需低於200（而非350）cells/μL以下，伺機性感染風險才顯著大幅增加，此為關鍵切點數值，此敘述數值有誤（A✗）；口腔念珠菌感染確實是AIDS病人相當常見的伺機性感染之一，但此選項使用「最為常見」的絕對化敘述，相對於文獻中常將肺囊蟲肺炎列為最具代表性、致死率較高之伺機性感染而言，此表述較不精確嚴謹（B✗）；CMV感染的標準治療藥物是Ganciclovir，Zovirax（acyclovir）主要用於治療單純疱疹病毒及水痘帶狀疱疹病毒感染，對CMV療效有限，此敘述用藥有誤（C✗）。"},{n:481,no:51,subj:"呼吸系統",q:"協助醫師拔除胸管時，應指導病人採取下列何種呼吸方式？",opts:["A.緩慢吸吐氣","B.哈氣","C.快速吸吐氣","D.深吸氣後閉氣"],ans:[3],expl:"本題答案為D。協助醫師拔除胸管時，應指導病人採取深吸氣後閉氣（Valsalva動作）的方式，利用閉氣時胸內壓上升，避免拔管瞬間空氣經由傷口通道被吸入胸腔造成氣胸，為本題答案。緩慢吸吐氣、快速吸吐氣或哈氣的呼吸方式，皆無法在拔管瞬間有效提高胸內壓以阻擋空氣進入胸腔，不符合拔除胸管的操作原則（A、B、C✗）。"},{n:482,no:52,subj:"呼吸系統",q:"有關慢性咳嗽病人進行支氣管鏡檢查後，下列護理措施何者最適宜？",opts:["A.床頭抬高至80～90度","B.禁食直到作嘔反射恢復","C.臥床休息至少4小時","D.咳出微量血絲痰應立即通知醫師"],ans:[1],expl:"本題答案為B。支氣管鏡檢查前會於咽喉部噴灑局部麻醉劑抑制作嘔及咳嗽反射，檢查後應待作嘔反射恢復後才可進食，以避免嗆咳及吸入性肺炎，為本題答案。支氣管鏡檢查後採半坐臥姿（約30～45度）即可，並非需抬高床頭至80～90度的近乎直立姿勢（A✗）；檢查後鼓勵及早下床適度活動即可，並非需臥床休息至少4小時（C✗）；檢查後咳出微量血絲痰屬於黏膜輕微損傷的常見正常反應，通常可先觀察，若持續大量咳血才需立即通知醫師，此敘述過於保守（D✗）。"},{n:483,no:53,subj:"呼吸系統",q:"全球慢性阻塞性肺疾病倡議組織（Global Initiative for Chronic Obstructive Lung Disease, GOLD）將COPD嚴重度分為GOLD 1～4級，下列何者為分級依據？",opts:["A.肺餘容積（RV）","B.第一秒用力呼氣容積（FEV1）","C.血氧濃度（SaO2）","D.急性惡化的次數"],ans:[1],expl:"本題答案為B。GOLD分級系統是以第一秒用力呼氣容積（FEV1，佔預測值百分比）作為COPD嚴重度（GOLD 1～4級）分類的核心肺功能指標，為本題答案。肺餘容積（RV）雖在COPD病人中也會因氣體滯留而增加，但並非GOLD分級系統的分類依據（A✗）；血氧濃度（SaO2）是評估氧合狀態的指標，並非GOLD肺功能分級的依據（C✗）；急性惡化次數是ABE評估工具中用來評估症狀負擔及未來惡化風險分類的參考項目，並非GOLD 1～4級（肺功能損傷程度分級）的分類依據，兩者屬COPD整體評估中不同的分類系統（D✗）。"},{n:484,no:54,subj:"呼吸系統",q:"有關病人的肺部身體評估，下列結果何者異常？",opts:["A.吸氣時胸廓對稱性往外擴張","B.肺部基底部出現反響音","C.下肺區出現支氣管呼吸音","D.胸廓左右徑大於前後徑"],ans:[2],expl:"本題答案為C。支氣管呼吸音（音質高亢、類似經中空管傳出的聲音）正常僅應在氣管、主支氣管附近（如胸骨柄上方、肩胛骨間）聽到；若在遠離大呼吸道的下肺區聽到支氣管呼吸音，代表該處肺組織可能因肺炎肺實變等病灶，使原本應被含氣肺組織過濾掉的呼吸音清楚傳導出來，是具明確臨床意義的異常發現，為本題答案。吸氣時胸廓對稱性往外擴張是正常呼吸型態的表現（A為正常）；反響音是正常肺組織扣診時應呈現的正常叩診音，於肺部基底部聽到屬正常表現（B為正常）；成人胸廓正常前後徑與左右（橫）徑比例約1:1.5，左右徑本應大於前後徑，此為正常胸廓外觀比例（D為正常）；四者中僅C具有明確病理意義，為本題答案。"},{n:485,no:55,subj:"呼吸系統",q:"張先生患有多重抗藥性結核病（MDR-TB），表示其對何種藥物產生抗藥性？①Ethambutol ②Isoniazid ③Pyrazinamide ④Rifampin",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[3],expl:"本題答案為D（②④）。多重抗藥性結核病（MDR-TB）的定義，是指結核桿菌對「至少同時包含Isoniazid（②）與Rifampin（④）」這兩種最主要的第一線抗結核藥物產生抗藥性，選②④＝D（本題答案）。Ethambutol及Pyrazinamide雖同屬第一線抗結核藥物，但MDR-TB的核心定義是針對Isoniazid與Rifampin的抗藥性，並非針對此二者（①③錯誤，不構成MDR-TB的定義組合）。"},{n:486,no:56,subj:"呼吸系統",q:"有關接受肺葉切除手術病人之護理，下列敘述何者正確？",opts:["A.術前接受肺功能檢查，可作為評估術後咳嗽能力的指標","B.術後教導避免肩部與手臂運動，以利傷口癒合","C.採肺葉切除手術，術後應臥向患側，以利健側肺部氣體交換","D.術後使用誘發性肺量計（incentive spirometry），可預防肺塌陷"],ans:[3],expl:"本題答案為D。術後鼓勵及早使用誘發性肺量計進行深呼吸訓練，可促進肺泡擴張、預防肺塌陷及肺部併發症，為本題答案。術前肺功能檢查主要用於評估病人能否耐受手術切除後所剩肺功能，並非用來評估術後咳嗽能力的指標（A✗）；術後應鼓勵（而非避免）肩部與手臂運動及早期活動，以預防肩關節僵直及促進呼吸功能恢復（B✗）；肺葉切除術後應鼓勵臥向健側（而非患側），以利健側肺部有效通氣及氣體交換（C✗）。"},{n:487,no:57,subj:"呼吸系統",q:"病人有心衰竭病史，因車禍造成左側肋骨骨折與氣血胸，目前出現急性呼吸衰竭的情形，下列護理措施何者最不適宜？",opts:["A.給與止痛藥，避免肺擴張不全，降低通氣量","B.給與氧氣，FiO2 60%","C.給與全血，避免血色素低下，影響攜氧量","D.建議補充低醣、高蛋白食物"],ans:[2],expl:"本題答案為C。此病人已有心衰竭病史，若再大量輸注全血，容易因循環負荷過重誘發或加重肺水腫及心衰竭惡化，並非改善血色素攜氧量的合適處置，此建議最不適宜，為本題答案（C✗，題目問「何者最不適宜」；心衰竭病人應審慎評估輸液輸血速度及總量，必要時採少量分次緩慢輸注並密切監測）。給予止痛藥可減輕因疼痛造成的淺快呼吸及肺擴張不全，改善通氣效率（A✓）；依血氧狀況給予氧氣支持治療（B✓）；補充足夠熱量及高蛋白質食物有助組織修復及維持呼吸肌力，但應避免高醣飲食造成過多二氧化碳生成加重呼吸負擔，故建議低醣、高蛋白飲食（D✓）。"},{n:488,no:58,subj:"泌尿系統",q:"有關透析治療之適應症，下列何者不適宜？",opts:["A.急性高血鉀","B.急性肺水腫","C.急性腎衰竭利尿期","D.急性巴比妥類中毒"],ans:[2],expl:"本題答案為C。急性腎衰竭進入利尿期，代表腎功能已開始恢復、腎小管重新恢復排尿及排除代謝廢物的能力，此階段通常不需要（甚至應避免過度）透析治療，反而需密切監測利尿期大量排尿造成的水分及電解質流失，為本題答案（題目問「何者不適宜」，即不需透析的情境）。急性高血鉀可能誘發致命性心律不整，是透析治療的緊急適應症（A為適應症）；急性肺水腫合併嚴重呼吸窘迫、藥物治療反應不佳時，透析可快速移除多餘水分（B為適應症）；急性巴比妥類藥物中毒，透析可加速移除體內毒素（D為適應症）。"},{n:489,no:59,subj:"泌尿系統",q:"有關膀胱炎之敘述，下列何者最適宜？",opts:["A.尿液檢驗值每毫升尿液菌數大於10⁵個表示正常","B.服用抗生素Neomycin，可給與維生素C酸化尿液","C.反覆性泌尿道感染須連續使用3～5天抗生素","D.指導病人每天攝取至少3,000 c.c.以上液體"],ans:[3],expl:"本題答案為D。指導病人每天攝取至少3,000 c.c.以上液體，可增加尿液沖刷作用，幫助降低泌尿道內細菌濃度、促進細菌隨尿液排出，為膀胱炎重要的一般性護理指導，為本題答案。尿液檢驗菌數大於10⁵（十萬）CFU/mL，是判斷有意義菌尿症的參考切點，並非表示「正常」（A✗）；服用Neomycin等胺基醣苷類抗生素時，維生素C酸化尿液反而可能降低其抗菌效果（部分抗生素在鹼性尿液環境中效果較佳）（B✗）；反覆性泌尿道感染的抗生素療程通常需要7～14天或更長的完整療程，3～5天療程對反覆感染而言可能不足（C✗）。"},{n:490,no:60,subj:"泌尿系統",q:"有關泌尿道感染病人應多攝取之酸灰性食物，下列何者錯誤？",opts:["A.肉類、蛋","B.燕麥、玉米","C.梅子、李子","D.牛奶、柑橘"],ans:[3],expl:"本題答案為D。牛奶及柑橘類水果代謝後屬於鹼灰性食物，會使尿液偏鹼性，並非酸灰性食物，為本題答案（D✗，題目問「何者錯誤」；泌尿道感染時建議攝取酸灰性食物以酸化尿液，抑制細菌滋生）。肉類、蛋等蛋白質食物代謝後屬酸灰性食物（A✓）；燕麥、玉米等穀類亦屬酸灰性食物（B✓）；梅子、李子代謝後屬酸灰性食物，蔓越莓類莓果另具有抑制細菌附著尿路上皮的額外效益（C✓）。"},{n:491,no:61,subj:"泌尿系統",q:"有關壓力性尿失禁之敘述，下列何者錯誤？",opts:["A.導因為膀胱肌肉張力欠佳","B.好發於多產次婦女","C.可能與雌激素缺乏有關","D.肥胖或搬重物會加重症狀"],ans:[0],expl:"本題答案為A。壓力性尿失禁主要導因於骨盆底肌肉及尿道括約肌張力／支持力不足（而非膀胱逼尿肌本身的張力問題），咳嗽、打噴嚏、大笑等腹壓瞬間升高的動作即誘發漏尿，此敘述將病因歸咎於「膀胱肌肉張力欠佳」並不準確，為本題答案（A✗，題目問「何者錯誤」）。多產次婦女因懷孕生產過程對骨盆底肌肉及韌帶造成的牽拉損傷，是重要危險因子（B✓）；停經後雌激素缺乏，會使尿道黏膜及骨盆底組織彈性下降，是危險因子之一（C✓）；肥胖或搬重物等增加腹內壓的情形，會加重症狀（D✓）。"},{n:492,no:62,subj:"泌尿系統",q:"有關逆行性腎盂造影術之敘述，下列何者正確？①檢查前評估病人有無鋇劑過敏病史 ②檢查前衛教病人勿排空膀胱 ③此檢查使用的顯影劑不會進入血流 ④檢查後監測病人有無尿瀦留、感染、血尿情形",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[3],expl:"本題答案為D（③④）。③逆行性腎盂造影是經膀胱鏡逆行將顯影劑直接注入輸尿管及腎盂內顯影，顯影劑未經血管注射，不會直接進入血液循環；④檢查後因導管置入及顯影劑注入，需監測病人是否出現尿瀦留、感染或血尿等併發症，此二敘述皆正確，選③④＝D（本題答案）。此檢查的顯影劑非經血管注射（且顯影劑非鋇劑，鋇劑主要用於腸胃道攝影），評估「鋇劑過敏病史」並非此檢查前的必要評估重點，此敘述顯影劑種類描述有誤（①錯誤）；檢查前應衛教病人先排空膀胱，以避免膀胱內殘餘尿液及顯影劑混合影響顯影效果判讀，「勿排空膀胱」的敘述方向有誤（②錯誤）。"},{n:493,no:63,subj:"內分泌系統",q:"有關抗利尿激素分泌不當症候群（SIADH）病人之臨床表徵，下列何者錯誤？",opts:["A.低血清鈉","B.低尿量","C.低血漿滲透壓","D.低尿比重"],ans:[3],expl:"本題答案為D。SIADH因ADH分泌過多，腎小管對水分再吸收增加，尿液濃縮程度增加，尿比重應升高，並非降低，為本題答案（D✗，題目問「何者錯誤」）。體內水分滯留造成血液稀釋，血清鈉濃度下降，出現低血鈉（A✓）；腎小管水分再吸收增加，尿量減少（B✓）；體液滯留稀釋血漿，血漿滲透壓下降（C✓）。"},{n:494,no:64,subj:"呼吸系統",q:"王先生的動脈血液氣體分析判讀結果為未代償性呼吸性酸中毒，下列敘述何者正確？",opts:["A.pH 7.27、PaCO2 50 mmHg、HCO3- 25 mmHg、PaO2 80 mmHg","B.pH 7.30、PaCO2 52 mmHg、HCO3- 30 mmHg、PaO2 81 mmHg","C.pH 7.39、PaCO2 48 mmHg、HCO3- 32 mmHg、PaO2 89 mmHg","D.pH 7.37、PaCO2 47 mmHg、HCO3- 31 mmHg、PaO2 81 mmHg"],ans:[0],expl:"本題答案為A。未代償性呼吸性酸中毒的判讀依據：pH小於7.35（酸中毒）、PaCO2大於45 mmHg（呼吸性因素、主要致病原因）、HCO3-仍維持正常範圍（22～26 mEq/L，代表腎臟代償機轉尚未啟動），選項A（pH 7.27、PaCO2 50、HCO3- 25、PaO2 80）完全符合此判讀條件，為本題答案。選項B之HCO3- 30已超出正常範圍上限，顯示腎臟代償機轉已開始介入，屬部分代償而非未代償（B✗）；選項C之pH 7.39已回到正常範圍，且HCO3- 32明顯升高顯示強烈代償反應，不符合未代償定義（C✗）；選項D之pH 7.37已在正常範圍內，同樣不符合未代償性酸中毒（pH應低於正常範圍）的判讀條件（D✗）。"},{n:495,no:65,subj:"泌尿系統",q:"有關輸尿管結石常見之臨床症狀，下列何者錯誤？",opts:["A.腰部、會陰疼痛","B.噁心、嘔吐","C.頻尿、尿急","D.寒顫、發燒"],ans:[2],expl:"本題答案為C。輸尿管結石最典型的表現為患側腰部及會陰部劇烈絞痛，並常合併噁心嘔吐（因腎臟與腸胃道共享自主神經反射路徑）；「頻尿、尿急」則多在結石已移動至靠近膀胱的輸尿管末端（近膀胱三角區）刺激膀胱時才較明顯出現，並非結石在輸尿管各處都普遍常見的核心症狀，相對於其他選項而言此描述最不具代表性，為本題答案（C，題目問「何者錯誤」）。腰部、會陰疼痛是輸尿管結石最典型的表現（A✓）；噁心、嘔吐因腎臟與腸胃道神經反射相關，是常見伴隨症狀（B✓）；結石阻塞若合併感染，可能出現寒顫、發燒等全身性感染徵象，需提高警覺（D✓）。"},{n:496,no:66,subj:"泌尿系統",q:"吳先生，85歲，因全身水腫，呼吸喘至急診求治，診斷為急性腎衰竭，下列敘述何者正確？",opts:["A.腎臟超音波檢查結果雙側腎臟大小有變小","B.測量24小時尿量約350 c.c.，此為少尿型腎衰竭","C.出現高血鉀且心電圖出現T波低而寬","D.可能因為前列腺肥大導致腎性急性腎衰竭"],ans:[1],expl:"本題答案為B。24小時尿量約350 c.c.（低於400 c.c./天），屬於少尿型急性腎衰竭的定義範圍，此敘述正確，為本題答案。急性腎衰竭腎臟通常因發炎水腫而腫大（而非變小；腎臟明顯萎縮多見於「慢性」腎衰竭）（A✗）；急性腎衰竭高血鉀時，心電圖典型表現是T波高聳（peaked T wave），並非低而寬（低而寬的T波較常見於低血鉀）（C✗）；前列腺肥大造成尿路阻塞所致的急性腎衰竭，屬於「腎後性」而非「腎性」病因分類（D✗）。"},{n:497,no:67,subj:"內分泌系統",q:"有關造成糖尿病病人血糖過低之促因，下列何者正確？",opts:["A.Glipizide服用過量","B.健走運動時間減少","C.近期工作壓力增加","D.近日上呼吸道感染"],ans:[0],expl:"本題答案為A。Glipizide為刺激胰島素分泌的口服降血糖藥物（sulfonylurea類），若服用過量，會使胰島素分泌過多，導致血糖過低，為本題答案。健走等運動時間減少會使葡萄糖消耗降低，血糖應相對升高而非過低（B✗）；工作壓力增加會促使腎上腺素、可體松等升糖荷爾蒙分泌增加，血糖應升高而非過低（C✗）；上呼吸道感染等生病、發炎狀態，身體會分泌壓力荷爾蒙使血糖升高（病人常需暫時增加胰島素劑量因應），並非造成血糖過低（D✗）。"},{n:498,no:68,subj:"其他",q:"一位18歲女性主訴最近發現全身皮膚起紅疹、口腔潰瘍、關節疼痛、偶有頭痛，另血紅素及血小板降低、抗核抗體升高，下列何者為其最可能之診斷？",opts:["A.痛風性關節炎","B.全身性紅斑性狼瘡","C.後天免疫缺乏症候群","D.類風濕性關節炎"],ans:[1],expl:"本題答案為B。此病人具皮膚紅疹、口腔潰瘍、關節疼痛等多系統受累表現，合併血液系統異常（血紅素及血小板降低）及抗核抗體（ANA）升高，符合全身性紅斑性狼瘡的典型臨床及免疫學診斷特徵，為本題答案。痛風性關節炎主要表現為單一關節（常見大拇趾）急性紅腫熱痛，與此病人多系統性表現、抗核抗體升高的特徵不符（A✗）；後天免疫缺乏症候群主要表現為反覆伺機性感染，並非以皮膚紅疹、口腔潰瘍及抗核抗體升高為特徵（C✗）；類風濕性關節炎主要表現為對稱性小關節發炎，抗核抗體升高並非其特異性診斷指標（類風濕因子及抗CCP抗體較具特異性），與此病人的整體表現組合較不吻合（D✗）。"},{n:499,no:69,subj:"內分泌系統",q:"下列何種荷爾蒙分泌過多會導致康氏症候群（Conn's syndrome）？",opts:["A.糖皮質酮","B.醛固酮","C.腎上腺素","D.抗利尿激素"],ans:[1],expl:"本題答案為B。康氏症候群（原發性醛固酮增多症）是因腎上腺皮質分泌過多醛固酮，造成鈉水滯留、血鉀排出增加，臨床表現為高血壓合併低血鉀，為本題答案。糖皮質酮（cortisol）分泌過多所致的疾病是庫欣氏症候群，並非康氏症候群（A✗）；腎上腺素分泌過多所致的疾病是嗜鉻細胞瘤（C✗）；抗利尿激素分泌過多所致的疾病是SIADH（D✗）。"},{n:500,no:70,subj:"內分泌系統",q:"陳小姐因甲狀腺機能亢進，接受抗甲狀腺藥物硫醯胺類（thioamides）與碘製劑（iodine）治療，有關其藥物治療之敘述，下列何者正確？",opts:["A.給與大劑量硫醯胺類藥物，隨著血清T3和T4數值降低而減量，待正常就可以停藥","B.碘製劑有顆粒球與血小板減少的副作用，第一次給藥前應先測白血球與血小板數目","C.服用硫醯胺類藥物的目的是為了減少甲狀腺腺體的血管分布","D.碘製劑使用不宜超過2週，以免造成甲狀腺逸脫，使大量甲狀腺素進入循環加重症狀"],ans:[3],expl:"本題答案為D。碘製劑可短暫抑制甲狀腺素釋放及合成，但使用超過2週後，甲狀腺可能對高劑量碘產生脫逸現象（Wolff-Chaikoff效應消退），反而使大量甲狀腺素釋放進入循環，加重甲亢症狀，故碘製劑通常僅作為術前短期（約7～10天）準備用藥，此敘述正確，為本題答案。硫醯胺類藥物應逐漸減量並持續使用較長期間（通常需18個月至2年左右的療程）以維持甲狀腺功能穩定，並非數值正常後即可立即停藥（驟然停藥復發率高）（A✗）；碘製劑主要副作用為碘過敏反應等，「顆粒球與血小板減少」是硫醯胺類藥物（如PTU、methimazole）較典型的副作用，此敘述將兩種藥物副作用混淆（B✗）；服用硫醯胺類藥物的主要目的是抑制甲狀腺過氧化酶、阻斷甲狀腺素合成，並非減少腺體血管分布（減少甲狀腺血管分布是碘製劑術前給藥的目的之一），此處又是兩類藥物作用機轉的混淆（C✗）。"},{n:501,no:71,subj:"內分泌系統",q:"承上題，陳小姐近期藥物治療反應不佳而入院接受甲狀腺切除術，有關甲狀腺切除手術，下列何者正確？①為維持正常的甲狀腺功能，一般採用次全甲狀腺切除 ②出血、聲門水腫、急性呼吸道阻塞為常見的術後合併症 ③術後聲音沙啞是因雙側喉返神經受傷所致 ④術後需評估病人有無肌肉抽搐之甲狀腺功能低下表徵",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[0],expl:"本題答案為A（①②）。①為維持病人術後仍保有部分甲狀腺組織以維持基礎甲狀腺功能，臨床上多採次全甲狀腺切除術而非全切除；②出血壓迫、聲門水腫及急性呼吸道阻塞，皆是甲狀腺切除術後最須警覺監測的緊急合併症，此二敘述皆正確，選①②＝A（本題答案）。術後聲音沙啞通常是單側喉返神經受損所致，雙側喉返神經同時受損會導致更嚴重的雙側聲帶麻痺甚至急性呼吸道阻塞，並非僅表現為聲音沙啞，此敘述神經受損範圍描述有誤（③錯誤）；術後應評估的是低血鈣（而非甲狀腺功能低下）造成的肌肉抽搐徵象，因手術可能誤傷或切除鄰近的副甲狀腺組織所致，肌肉抽搐是副甲狀腺功能低下、低血鈣的表現，並非甲狀腺功能低下的典型表徵，此敘述病因歸類有誤（④錯誤）。"},{n:502,no:72,subj:"內分泌系統",q:"承上題，有關陳小姐術後之護理指導，下列敘述何者正確？",opts:["A.建議採平躺臥姿，以避免牽拉傷口縫線","B.教導避免深呼吸、咳嗽，以防牽拉傷口造成出血","C.鼓勵攝取冰涼液狀食物，以減輕傷口不適","D.建議攝取高熱量、低蛋白質及高碘的食物"],ans:[2],expl:"本題答案為C。術後鼓勵攝取冰涼液狀食物，可幫助收縮局部血管、減輕傷口腫脹及咽喉不適感，同時降低吞嚥時對手術部位的刺激，為本題答案。術後應採半坐臥姿（而非平躺），以減輕頸部傷口張力及腫脹，並利於呼吸道通暢的觀察（A✗）；術後應鼓勵（而非避免）深呼吸及咳嗽以預防肺部併發症，但可教導病人以雙手支托頸部後方的方式減輕咳嗽時對傷口的牽扯不適，並非完全避免（B✗）；術後飲食應建議均衡營養、足夠蛋白質以促進傷口癒合，「低蛋白質」的建議方向有誤，且並無特別需攝取「高碘」食物的臨床理由（D✗）。"},{n:503,no:73,subj:"內分泌系統",q:"有關副甲狀腺功能低下之臨床表徵，下列何者正確？①嗜睡 ②高血鈣 ③骨質耗損加劇 ④白內障 ⑤高血磷",opts:["A.①③⑤","B.①④⑤","C.②③④","D.②③⑤"],ans:[1],expl:"本題答案為B（①④⑤）。①副甲狀腺功能低下造成低血鈣，可影響神經肌肉興奮性及中樞神經功能，出現嗜睡等非特異性症狀；④長期低血鈣可能造成白內障（鈣質沉積影響水晶體透明度）；⑤低血鈣時體內鈣磷代謝失衡，血磷相對升高，此三者敘述皆正確，選①④⑤＝B（本題答案）。副甲狀腺功能低下因副甲狀腺素（PTH）分泌不足，蝕骨作用降低，血鈣應降低（低血鈣）而非升高（②錯誤）；副甲狀腺功能低下時骨質代謝相對穩定（甚至因蝕骨作用降低而骨質流失減緩），並非骨質耗損加劇（骨質耗損加劇較常見於副甲狀腺功能「亢進」）（③錯誤）。"},{n:504,no:74,subj:"內分泌系統",q:"下列何種情況可能會導致特魯索氏（Trousseau）與沃斯德克氏（Chvostek）徵象皆呈陽性反應？①低血鈣 ②低血鉀 ③低血糖 ④副甲狀腺功能低下症",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"本題答案為B（①④）。①低血鈣會增加神經肌肉興奮性，是誘發Trousseau氏徵象（上臂綁血壓帶加壓後手部呈現助產士手樣痙攣）與Chvostek氏徵象（輕敲顏面神經誘發臉部肌肉抽動）陽性反應的典型病因；④副甲狀腺功能低下症因PTH不足導致低血鈣，同樣會誘發這兩種徵象陽性，此二者敘述皆正確，選①④＝B（本題答案）。低血鉀主要影響心肌及骨骼肌的電生理活動（如U波出現、肌肉無力），並非典型誘發此二徵象的病因（②錯誤）；低血糖主要表現為自主神經興奮症狀（心悸、冒汗、顫抖）及中樞神經症狀，並非典型誘發此二徵象的病因（③錯誤）。"},{n:505,no:75,subj:"呼吸系統",q:"有關急救使用手壓式甦醒球面罩（Ambu Bag mask）給與人工呼吸的敘述，下列何者正確？",opts:["A.當病人SPO2 95%時應該使用","B.面罩較尖的部位應對準病人下巴","C.氧氣流速調整至12～15公升／分鐘","D.一手使面罩密合病人口鼻，另一手應儘量完全壓扁球囊"],ans:[2],expl:"本題答案為C。使用甦醒球進行人工呼吸時，氧氣流速應調整至10～15公升/分鐘（多數教材建議12～15 L/min左右）的高流量，以確保甦醒球儲氧袋內維持足夠的高濃度氧氣供應，此敘述正確，為本題答案。當病人SpO2明顯偏低、出現呼吸窘迫或呼吸停止等情形時才需使用甦醒球輔助通氣，SpO2 95%通常仍屬可接受範圍，並非常規使用時機（A✗）；面罩較窄／尖的部位應對準病人鼻樑（而非下巴），寬大的部位罩住下巴、嘴巴，以達良好的面部密合度，此敘述部位方向有誤（B✗）；正確手法應為E-C手法：一手以E-C型手勢固定面罩並打開呼吸道，另一手規律地擠壓（而非儘量完全壓扁）球囊，過度用力完全壓扁球囊易造成潮氣容積過大、增加胃脹氣及吸入性風險（D✗）。"},{n:506,no:76,subj:"其他",q:"有關施行心肺復甦術（CPR）成功徵象的敘述，下列何者正確？①四肢有動作反應 ②有自發性呼吸 ③刺激眼瞼會眨眼 ④瞳孔對光反射固定",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[0],expl:"本題答案為A（①②③）。①CPR有效時病人可能開始出現四肢自主動作反應；②恢復自發性呼吸是CPR成功、循環恢復的重要指標；③刺激眼瞼出現眨眼反射，代表腦幹功能開始恢復，此三者皆為CPR急救成功、恢復自發循環（ROSC）的正向徵象，選①②③＝A（本題答案）。瞳孔對光反射「恢復」（而非固定不動）才是腦幹功能及循環恢復的正向表現；瞳孔對光反射固定（無反應）通常代表腦部灌流嚴重不足或已發生不可逆腦損傷，是預後不佳的表現，並非CPR成功的徵象，此敘述方向有誤（④錯誤）。"},{n:507,no:77,subj:"心臟血管",q:"下列何類休克有皮膚潮紅、溫暖的臨床徵象？①低血容性 ②敗血性 ③心因性 ④神經性",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[2],expl:"本題答案為C（②④）。②敗血性休克在早期（溫暖休克階段）因血管擴張、周邊血流增加，皮膚常呈現潮紅溫暖的表現；④神經性休克因交感神經張力喪失、血管平滑肌張力下降造成廣泛血管擴張，皮膚同樣呈現潮紅溫暖（而非濕冷）的特徵，此二者皆符合題意，選②④＝C（本題答案）。低血容性休克因血液循環量不足，身體代償性周邊血管收縮，皮膚呈現濕冷、蒼白的表現，並非潮紅溫暖（①錯誤）；心因性休克同樣因心輸出量不足誘發周邊血管收縮代償，皮膚呈現濕冷表現，並非潮紅溫暖（③錯誤）。"},{n:508,no:78,subj:"其他",q:"有關敗血症生理病理機轉之敘述，下列何者正確？①細菌感染引發腫瘤壞死因子活化產生微小血栓 ②微生物侵入人體造成微血管通透性增加、全身循環血量增加 ③全身代謝狀態升高造成細胞耗氧量增加，但組織血流灌注降低，產生代謝性酸中毒 ④因心臟受刺激出現血壓上升，可能引發尿量增加",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[1],expl:"本題答案為B（①③）。①細菌感染活化發炎反應（包含腫瘤壞死因子等發炎介質），促進凝血系統活化形成微小血栓，是敗血症病理機轉的一環；③敗血症時全身代謝率上升、細胞耗氧量增加，但因微循環障礙使組織實際血流灌注不足，導致細胞缺氧、產生代謝性酸中毒，此二者敘述皆正確，選①③＝B（本題答案）。微血管通透性增加會使血漿滲漏至組織間隙，造成有效循環血量減少（而非增加）（②錯誤）；敗血症時心臟雖可能代償性心搏過速，但隨病程進展血壓多呈現下降（低血壓）而非上升，且腎臟血流灌注不足會使尿量減少（而非增加）（④錯誤）。"},{n:509,no:79,subj:"其他",q:"下列何者不需採取腸道隔離？",opts:["A.痢疾","B.傷寒","C.腮腺炎","D.霍亂"],ans:[2],expl:"本題答案為C。腮腺炎（如流行性腮腺炎）主要經由飛沫傳染，需採取飛沫（呼吸道）隔離，並非經腸胃道糞口途徑傳染的疾病，故不需採取腸道隔離，為本題答案。痢疾主要經糞口途徑傳染，需採取腸道隔離（A✗，即需要腸道隔離）；傷寒（沙門氏桿菌感染）主要經糞口途徑傳染，需採取腸道隔離（B✗，即需要腸道隔離）；霍亂主要經糞口途徑（污染水源、食物）傳染，需採取腸道隔離（D✗，即需要腸道隔離）。"},{n:510,no:80,subj:"其他",q:"有關登革熱病人的隔離防護措施，下列何者正確？",opts:["A.接觸隔離","B.呼吸道隔離","C.腸道隔離","D.血液和體液的防護"],ans:[3],expl:"本題答案為D。登革熱是經由病媒蚊（如埃及斑蚊、白線斑蚊）叮咬傳播的疾病，病人急性期血液中存在病毒（病毒血症），對於血液及體液應採取標準防護措施避免接觸傳染，同時應加強病房防蚊措施（如裝設紗窗、蚊帳），以防病媒蚊叮咬病人後再傳播給他人，「血液和體液的防護」是核心防護原則之一，為本題答案。登革熱不會透過一般人與人的直接接觸傳染，並非以接觸隔離為主要防護措施（A✗）；登革熱並非經由呼吸道飛沫傳染，不需採取呼吸道隔離（B✗）；登革熱並非經由糞口途徑傳染，不需採取腸道隔離（C✗）。"},{n:511,no:1,subj:"神經系統",q:"有關癲癇病人的症狀及其治療，下列敘述何者最不適當？",opts:["A.複雜性部分發作，病兆常源自於顳葉，通常發作前有先兆症狀","B.癲癇重積狀態是指持續抽搐發作超過5分鐘或2次發作之間意識未恢復","C.泛發型發作中的強直－陣攣性發作時，會在陣攣後期出現牙關緊閉及雙腳伸直","D.開始時僅採單一藥物治療，再逐漸增加劑量，直到被控制或出現藥物毒性"],ans:[2],expl:"本題答案為C。全身泛發型強直－陣攣性發作（tonic-clonic seizure）的病程順序是：強直期（tonic phase，全身肌肉持續收縮僵直，可能咬緊牙關）先於陣攣期（clonic phase，肌肉規律性抽動），而非在陣攣「後期」才出現牙關緊閉及雙腳伸直——這些強直性表現應發生在發作「初期（強直期）」，此時序描述有誤，為本題答案（C✗，題目問「何者最不適當」）。複雜性部分發作的病灶確實常源自顳葉，且發作前常有先兆（aura）症狀，此為典型表現（A✓）；癲癇重積狀態（status epilepticus）的定義即為抽搐發作持續超過5分鐘，或兩次發作間意識未完全恢復，此為國際公認定義（B✓）；癲癇藥物治療原則是先以單一藥物由低劑量開始，逐漸調整劑量直到症狀控制或出現副作用毒性，此為標準用藥原則（D✓）。"},{n:512,no:2,subj:"神經系統",q:"62歲王女士，因在家突然四肢無力至急診，意識清楚，但四肢癱瘓、不能言語，可依指示轉動眼球和眨眼，下列那一部分功能最可能受損？",opts:["A.橋腦","B.脊髓","C.大腦廣泛性傷害","D.右側小腦"],ans:[0],expl:"本題答案為A。病人意識清楚、四肢癱瘓、不能言語，但仍可依指示轉動眼球及眨眼，此為「閉鎖症候群（locked-in syndrome）」的典型表現，好發於橋腦（pons）腹側受損（如基底動脈栓塞），因皮質脊髓徑及皮質延髓徑受損導致四肢及大部分顱神經功能喪失，但動眼神經核及部分眼球運動功能未受影響，病人仍保有意識及眼球垂直運動／眨眼能力，為本題答案。脊髓損傷通常不會影響言語及眼球運動功能，與此題描述不符（B✗）；大腦廣泛性傷害通常會影響意識程度，與題目「意識清楚」的描述不符（C✗）；右側小腦病變主要表現為協調及平衡功能障礙，並不會造成四肢癱瘓及言語喪失（D✗）。"},{n:513,no:3,subj:"神經系統",q:"有關阿茲海默症的早期臨床表徵，下列敘述何者正確？①對人和周遭發生的事件興趣降低 ②無法進行簡單的計算 ③學習新事物之能力降低 ④工作表現變差 ⑤夜間活動增加",opts:["A.①②⑤","B.①③④","C.②③④","D.③④⑤"],ans:[1],expl:"本題答案為B（①③④）。①對人和周遭事件興趣降低（淡漠）、③學習新事物能力降低、④工作表現變差，皆為阿茲海默症早期常見的認知及行為改變表現，選①③④＝B（本題答案）。無法進行簡單計算（算術障礙）通常在病程「較後期」隨認知功能持續退化才逐漸明顯，並非早期即出現的典型表徵（②較不符合早期階段）；夜間活動增加（日夜顛倒、黃昏症候群）同樣較常見於病程中後期，並非早期臨床表徵（⑤較不符合早期階段）。"},{n:514,no:4,subj:"神經系統",q:"有關腦中風的危險因子，下列敘述何者錯誤？",opts:["A.高血壓","B.糖尿病","C.高密度脂蛋白過高","D.腦中風病史"],ans:[2],expl:"本題答案為C。高密度脂蛋白（HDL，俗稱「好膽固醇」）具有保護血管、降低動脈粥狀硬化風險的作用，「HDL過高」並非腦中風的危險因子，反而是「低密度脂蛋白（LDL）過高」或「HDL過低」才是公認的腦中風危險因子，此敘述方向有誤，為本題答案（C✗，題目問「何者錯誤」）。高血壓是腦中風最重要且最常見的可控制危險因子（A✓）；糖尿病會加速動脈粥狀硬化、增加腦中風風險（B✓）；曾有腦中風病史者，再次中風的風險明顯高於一般人，是重要危險因子（D✓）。"},{n:515,no:5,subj:"神經系統",q:"有關單純頭部損傷病人，其顱內壓升高非代償期初期階段的徵象，下列敘述何者正確？",opts:["A.呼吸及脈搏變慢，且血壓下降","B.呼吸變快、瞳孔放大，且血壓上升","C.脈搏變慢而有力，且血壓上升","D.呼吸不規則及脈搏變弱、快，且血壓下降"],ans:[2],expl:"本題答案為C。顱內壓升高進入「非代償期（失代償期）」初期階段時，身體仍嘗試透過庫欣氏反應（Cushing's response）代償：脈搏因迷走神經興奮而「變慢但有力」，同時血壓（尤其收縮壓）「上升」以維持腦部灌流壓，此為本題答案。呼吸及脈搏變慢且血壓下降的組合，並不符合顱內壓升高的代償反應方向（血壓應上升而非下降）（A✗）；瞳孔放大通常是顱內壓持續惡化、腦疝形成後才出現的較晚期徵象，且此階段脈搏應變慢而非變快（B✗）；呼吸不規則、脈搏轉為弱而快、血壓下降，屬於顱內壓升高「末期」接近腦幹衰竭的表現，並非初期階段（D✗）。"},{n:516,no:6,subj:"消化系統",q:"有關小腸阻塞的臨床表徵與評估，下列敘述何者最適當？①劍突下可見強蠕動波 ②嘔吐物含糞便臭味 ③鈉、鉀、氯值降低 ④阻塞早期腸蠕動音消失",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[0],expl:"本題答案為A（①②③）。①小腸阻塞因近端腸道代償性強力蠕動以克服阻塞，可能在劍突下觀察到明顯的腸蠕動波；②嘔吐物若含糞便樣臭味，提示阻塞位置較低或病程已久、腸內容物逆流至上消化道，是小腸阻塞的重要警訊；③因反覆嘔吐流失大量含電解質的腸液，鈉、鉀、氯等電解質數值會下降，此三者敘述皆正確，選①②③＝A（本題答案）。小腸阻塞「早期」因腸道仍代償性強力蠕動以克服阻塞，腸蠕動音應是高頻、高亢（hyperactive）甚至可聽到金屬音調，並非早期即消失，腸蠕動音減弱或消失通常是阻塞持續惡化、腸道疲乏或發生腸壞死等較晚期的表現，此敘述時序有誤（④錯誤）。"},{n:517,no:7,subj:"消化系統",q:"有關胃食道逆流之護理指導，下列敘述何者最適當？①採床頭抬高的姿勢睡覺 ②穿緊身衣防止胃內容物逆流 ③進食後需躺平休息 ④避免提重物或彎腰運動",opts:["A.①③","B.①④","C.②④","D.③④"],ans:[1],expl:"本題答案為B（①④）。①睡覺時抬高床頭，可利用重力減少胃內容物逆流至食道；④避免提重物或彎腰等增加腹內壓的動作，可減少逆流機會，此二敘述皆正確，選①④＝B（本題答案）。緊身衣物會增加腹內壓，反而「促進」（而非防止）胃內容物逆流，此敘述方向有誤（②錯誤）；進食後應避免立即躺平，建議維持坐姿或直立姿勢至少1～2小時，「進食後需躺平休息」的建議方向有誤（③錯誤）。"},{n:518,no:8,subj:"感官系統",q:"有關口腔癌病人接受根除性頸部淋巴廓清術後之照護，下列敘述何者最不適當？",opts:["A.術後須固定肩膀不動","B.每日評估傷口，並依傷口情況進行無菌技術換藥","C.開始進食時可先採清流質、軟質飲食","D.必要時行氣管造口術，以利痰液抽吸"],ans:[0],expl:"本題答案為A。根除性頸部淋巴廓清術後，應鼓勵早期進行肩關節活動（在醫囑允許範圍內漸進式活動），以預防因副神經（accessory nerve）受影響或長期不活動導致的肩關節攣縮及「肩垂症候群」，「須固定肩膀不動」的建議方向有誤，為本題答案（A✗，題目問「何者最不適當」）。每日評估傷口並依情況以無菌技術換藥，是預防感染的基本傷口照護原則（B✓）；術後初期採清流質、軟質飲食可減少吞嚥時對手術部位的刺激及負擔（C✓）；視手術範圍及氣道情形，必要時可行氣管造口術以維持呼吸道通暢及利於痰液抽吸（D✓）。"},{n:519,no:9,subj:"消化系統",q:"有關肝癌，下列敘述何者最不適當？",opts:["A.B型肝炎為肝癌的危險因子","B.右上腹部腫大或壓痛為其臨床表徵","C.原發性肝癌較好發於歐美地區女性","D.血液中α–胎兒蛋白為重要肝癌治療指標"],ans:[2],expl:"本題答案為C。原發性肝癌（肝細胞癌）全球盛行率以亞洲及非洲地區、且以男性較好發（與B型肝炎、黃麴毒素暴露等地區性危險因子高度相關），並非好發於歐美地區女性，此敘述地區及性別描述皆有誤，為本題答案（C✗，題目問「何者最不適當」）。慢性B型肝炎感染是肝癌公認的重要危險因子（A✓）；肝腫瘤增大可能造成右上腹部腫大或觸診壓痛，是常見臨床表徵（B✓）；血液中α-胎兒蛋白（AFP）是肝癌重要的腫瘤標記，可用於診斷輔助及治療後追蹤（D✓）。"},{n:520,no:10,subj:"消化系統",q:"有關膽囊癌，下列敘述何者最不適當？",opts:["A.常見醫療處置包含手術治療及化學治療","B.早期症狀不明顯，與膽囊炎症狀相似","C.常見為腺癌，好發於年輕人","D.可分為浸潤型及黴菌型"],ans:[2],expl:"本題答案為C。膽囊癌好發族群以中老年女性為主（尤其60歲以上、有膽結石病史者），並非好發於年輕人，此敘述年齡族群描述有誤，為本題答案（C✗，題目問「何者最不適當」）。膽囊癌的治療確實包含手術切除及化學治療等醫療處置（A✓）；膽囊癌早期症狀不具特異性、與慢性膽囊炎表現相似，常導致診斷延遲（B✓）；膽囊癌病理型態上以腺癌最常見，並可依生長方式分為浸潤型及乳突型（黴菌型）等類型（D✓）。"},{n:521,no:11,subj:"骨骼肌肉",q:"有關全髖關節置換術病人之術後護理措施，下列敘述何者最不適當？",opts:["A.應選擇椅背平直、高度相當並有扶手之椅子","B.術後患肢抬高、保持外旋、避免外展","C.坐姿的髖部屈曲不可超過90度","D.6星期內不要有性生活或駕車等活動"],ans:[1],expl:"本題答案為B。全髖關節置換術後應維持患肢「外展」姿勢（如使用外展枕），避免髖關節內收及過度內旋，以防人工關節脫臼；「保持外旋、避免外展」的敘述方向恰好相反，為本題答案（B✗，題目問「何者最不適當」）。選擇椅背平直、高度足夠並有扶手的椅子，可避免術後髖關節過度屈曲（A✓）；坐姿時髖部屈曲角度應限制在90度以內，以降低脫臼風險（C✓）；術後6週內應避免性生活、駕車等會使髖關節過度屈曲或旋轉的活動，待組織充分癒合後再恢復（D✓）。"},{n:522,no:12,subj:"骨骼肌肉",q:"有關骨外固定器處置，下列敘述何者最不適當？",opts:["A.使用抗生素預防感染","B.使用外科傷口消毒法處理插針處","C.指導執行肌肉等長運動","D.避免下床以防外固定器鬆脫"],ans:[3],expl:"本題答案為D。骨外固定器的主要目的即在於穩定骨折處、允許病人及早下床活動，早期活動有助避免長期臥床併發症（如肌肉萎縮、深部靜脈栓塞），「避免下床」並非正確的護理原則，為本題答案（D✗，題目問「何者最不適當」）。依醫囑使用抗生素可預防插針處感染（A✓）；插針處照護採外科傷口消毒（無菌）技術，以降低感染風險（B✓）；鼓勵執行肌肉等長運動，有助維持肌力並促進血液循環，預防肌肉萎縮（C✓）。"},{n:523,no:13,subj:"骨骼肌肉",q:"有關病人股骨骨折後牽引的護理措施，下列敘述何者最適當？①牽引重力應垂直懸空不可擺動 ②摩擦力愈小，牽引拉力愈大 ③應以罩單覆蓋在牽引繩上，以減少感染 ④應視病人需要，隨時調整牽引重量 ⑤牽引力應與骨頭的長軸平行",opts:["A.①②③","B.②③④","C.①②⑤","D.③④⑤"],ans:[2],expl:"本題答案為C（①②⑤）。①牽引重力應垂直懸空、不可觸地或擺動，才能維持穩定牽引力；②摩擦力愈小，實際作用在骨骼上的牽引拉力愈大（牽引效果愈好）；⑤牽引力方向應與骨頭長軸平行，才能達到有效的骨折復位及固定效果，此三者敘述皆正確，選①②⑤＝C（本題答案）。牽引繩上不應覆蓋罩單等物品，以免影響牽引繩的滑動及牽引效果、增加摩擦力（③錯誤，且與感染預防無直接關聯）；牽引重量應依醫囑設定，不可由護理人員或病人自行隨時調整，任意調整可能影響骨折復位效果或造成併發症（④錯誤）。"},{n:524,no:14,subj:"感官系統",q:"有關美尼爾氏症（Ménière's disease），下列敘述何者最不適當？",opts:["A.常見症狀有雙側感覺神經性聽力喪失","B.可使用利尿劑減輕水腫","C.眩暈急性發作採患耳在上的臥床姿勢","D.避免快速移動或改變姿勢"],ans:[0],expl:"本題答案為A。美尼爾氏症的聽力喪失典型為「單側」（患側）感覺神經性聽力喪失，並非雙側，此敘述有誤，為本題答案（A✗，題目問「何者最不適當」）。內耳膜迷路水腫是美尼爾氏症的病理機轉，使用利尿劑有助減少內淋巴液、減輕水腫症狀（B✓）；眩暈急性發作時，建議採患耳在上（健耳朝下）的臥床姿勢，以減少患側前庭刺激（C✓）；應避免快速移動頭部或改變姿勢，以減少眩暈發作的誘發及跌倒風險（D✓）。"},{n:525,no:15,subj:"感官系統",q:"有關扁桃腺炎，下列敘述何者最不適當？",opts:["A.急性扁桃腺炎以鏈球菌感染最常見","B.會有發燒、喉嚨痛及吞嚥時疼痛的症狀","C.急性發炎期是行扁桃腺切除術的最佳時機","D.扁桃腺切除術後避免用力咳嗽以預防出血"],ans:[2],expl:"本題答案為C。扁桃腺切除術應選在感染控制、發炎緩解後的非急性期進行，急性發炎期手術會增加出血及感染擴散風險，並非最佳手術時機，為本題答案（C✗，題目問「何者最不適當」）。A群鏈球菌是急性扁桃腺炎最常見的致病菌之一（A✓）；發燒、喉嚨痛及吞嚥疼痛是急性扁桃腺炎的典型症狀（B✓）；扁桃腺切除術後應避免用力咳嗽、清喉嚨等動作，以降低傷口部位出血風險（D✓）。"},{n:526,no:16,subj:"心臟血管",q:"38歲孕齡婦女，診斷為下肢深部靜脈栓塞，接受抗凝血劑Heparin注射治療，下列敘述何者最不適當？",opts:["A.避免自行按摩腿部","B.避免使用口服避孕藥","C.避免食用深色蔬菜","D.避免長期久坐"],ans:[2],expl:"本題答案為C。「深色蔬菜」富含維生素K，主要與「Warfarin」（維生素K拮抗劑）的藥效交互作用有關；Heparin的作用機轉是活化抗凝血酶III，並不受維生素K攝取影響，「避免食用深色蔬菜」並非Heparin治療期間的正確衛教重點，此敘述有誤，為本題答案（C✗，題目問「何者最不適當」；此衛教內容常與Warfarin混淆）。避免自行按摩患肢，以防栓塞脫落造成肺栓塞（A✓）；口服避孕藥（含雌激素）會增加血栓形成風險，應避免使用（B✓）；長期久坐會使下肢血液滯留，增加血栓復發風險，應避免（D✓）。"},{n:527,no:17,subj:"心臟血管",q:"58歲中年婦女，平日血壓約為138/88 mmHg，沒有糖尿病與其他心血管疾病，BMI為30 kg/m2，飲食偏好重油滷肉類食物，沒有抽菸與喝酒習慣，日常活動多為家務勞動，下列敘述何者最不適當？",opts:["A.控制熱量的攝取","B.限制高鈉食物的攝取","C.每天至少30分鐘的中等強度運動","D.積極使用藥物來控制血壓"],ans:[3],expl:"本題答案為D。此病人血壓138/88 mmHg屬於高血壓前期範圍，且無糖尿病或其他心血管疾病史，臨床上應優先採取生活型態調整（如控制熱量、限鈉、規律運動）作為第一線介入，尚未達到需要積極使用藥物控制血壓的程度，此建議過於積極，為本題答案（D✗，題目問「何者最不適當」）。控制熱量攝取有助於此病人（BMI 30，屬肥胖）體重管理及血壓控制（A✓）；此病人飲食偏好重油滷肉，限制高鈉食物攝取是合理的飲食指導（B✓）；規律有氧運動是改善血壓及體重的重要生活型態介入（C✓）。"},{n:528,no:18,subj:"腫瘤血液",q:"病人因身體多處不明原因出血進行骨髓抽吸檢查，下列敘述何者最適當？①檢查目的在了解骨髓組織、造血組織是否正常 ②可診斷是否為白血病 ③大多由脛骨進行抽取 ④大多需全身麻醉進行",opts:["A.①②","B.②③","C.①④","D.③④"],ans:[0],expl:"本題答案為A（①②）。①骨髓抽吸檢查的目的即在於評估骨髓造血組織功能是否正常；②骨髓檢查可協助診斷白血病等血液惡性疾病，此二敘述皆正確，選①②＝A（本題答案）。成人骨髓抽吸檢查常見部位是髂骨（腸骨嵴）或胸骨，並非脛骨（③錯誤）；骨髓抽吸檢查通常僅需局部麻醉即可執行，病人清醒配合，並不需要全身麻醉（④錯誤）。"},{n:529,no:19,subj:"腫瘤血液",q:"針對正在接受化學治療病人的護理指導，下列敘述何者最不適當？",opts:["A.勿與上呼吸道感染者接觸","B.勿食用生菜沙拉、生魚片","C.發燒時自行服用退燒藥","D.減少出入公共場所"],ans:[2],expl:"本題答案為C。接受化學治療的病人常因骨髓抑制導致嗜中性白血球低下、免疫力下降，發燒時應立即通知醫護人員評估是否為感染徵象並及時處置，不應自行服用退燒藥物掩蓋病情、延誤治療時機，此建議不適當，為本題答案（C✗，題目問「何者最不適當」）。避免與上呼吸道感染者接觸，可降低交叉感染風險（A✓）；生菜沙拉、生魚片等未經高溫烹煮的食物可能帶有病原菌，免疫力低下時應避免生食（B✓）；減少出入人潮擁擠的公共場所，可降低感染暴露機會（D✓）。"},{n:530,no:20,subj:"腫瘤血液",q:"病人剛開始輸血20 mL就發生皮膚癢、蕁麻疹、哮喘，最有可能發生下列那一種輸血反應？",opts:["A.過敏反應","B.熱原反應","C.溶血反應","D.細菌反應"],ans:[0],expl:"本題答案為A。輸血開始後短時間內（僅20 mL）即出現皮膚癢、蕁麻疹及哮喘等症狀，屬於典型的過敏反應表現，通常與受血者對捐血者血漿中蛋白質成分產生免疫反應有關，為本題答案。熱原反應（發燒反應）主要表現為發燒、發冷、頭痛，並不會有蕁麻疹及哮喘等過敏性表現（B✗）；溶血反應通常伴隨發燒、腰背疼痛、血尿、低血壓甚至休克等嚴重表現，與此題症狀不符（C✗）；細菌污染反應（敗血性輸血反應）常表現為高燒、寒顫、低血壓等敗血症徵象，與此題症狀不符（D✗）。"},{n:531,no:21,subj:"腫瘤血液",q:"有關真性紅血球增多症常見的併發症，下列敘述何者最不適當？",opts:["A.栓塞","B.出血","C.痛風","D.感染"],ans:[3],expl:"本題答案為D。真性紅血球增多症因血液黏稠度增加、血流速度變慢，主要併發症與血栓栓塞相關（而非感染），感染並非其常見或典型的併發症，此敘述有誤，為本題答案（D✗，題目問「何者最不適當」）。血液黏稠度增加使血流變慢、易形成血栓，栓塞是重要併發症（A✓）；血小板功能異常可能合併出血傾向（B✓）；紅血球大量破壞增加尿酸生成，可能誘發痛風（C✓）。"},{n:532,no:22,subj:"腫瘤血液",q:"腫瘤及組織病理分期TxN1M0、G4其代表之意義，下列敘述何者最不適當？",opts:["A.無原發病灶","B.無遠端轉移","C.原發部位淋巴受侵犯","D.細胞未分化"],ans:[0],expl:"本題答案為A。TNM分期中，「Tx」代表「原發腫瘤無法評估」（因缺乏足夠資訊評估原發腫瘤大小或範圍），並非代表「無原發病灶」（無原發病灶應標示為T0），此敘述混淆了Tx與T0的意義，為本題答案（A✗，題目問「何者最不適當」）。M0代表無遠端轉移的證據，此描述正確（B✓）；N1代表區域淋巴結（原發部位淋巴）已受腫瘤侵犯，此描述正確（C✓）；G4代表腫瘤細胞分化程度極差（未分化），惡性度較高，此描述正確（D✓）。"},{n:533,no:23,subj:"心臟血管",q:"服用排鉀利尿劑的高血壓病人，出現肌肉無力、心悸等症狀，下列護理措施何者最不適當？",opts:["A.鼓勵多攝取香蕉、柑橘類水果","B.鼓勵盡量多下床活動","C.監測心率及心律變化","D.評估電解質變化"],ans:[1],expl:"本題答案為B。病人已出現肌肉無力、心悸等疑似低血鉀合併心律不整風險的症狀，此時應限制活動、臥床休息並密切監測，而非鼓勵盡量多下床活動，過度活動可能因肌肉無力增加跌倒風險，或因潛在心律不整誘發意外，此建議不適當，為本題答案（B✗，題目問「何者最不適當」）。香蕉、柑橘類水果富含鉀離子，有助補充流失的鉀離子（A✓）；低血鉀可能誘發心律不整，應密切監測心率及心律變化（C✓）；應評估血鉀等電解質數值變化，以確認是否為排鉀利尿劑造成的低血鉀（D✓）。"},{n:534,no:24,subj:"心臟血管",q:"有關使用主動脈氣球幫浦（IABP）病人的護理注意事項，下列敘述何者最適當？",opts:["A.為避免血栓形成，患肢可採屈曲／伸展之交替活動","B.心臟收縮時主動脈內的氣球充氣以降低前負荷","C.須比較患肢與健肢之末梢脈博、血循、感覺差異","D.為避免出血，應避免給予Heparin"],ans:[2],expl:"本題答案為C。IABP置入後應密切比較兩側（置入患肢與健側肢體）的末梢脈搏、血液循環及感覺狀況是否對稱，以及早發現因導管置入造成的下肢缺血等併發症，為本題答案。為避免導管移位或血管損傷，置入患肢應限制（而非交替屈曲伸展）活動，以維持導管位置穩定（A✗）；IABP的氣球是在心臟「舒張期」充氣（增加冠狀動脈灌流），並在「收縮期」放氣以降低「後負荷」（而非於收縮時充氣、亦非降低前負荷），此敘述之時機與作用機轉皆有誤（B✗）；IABP置入期間病人仍需接受適當的抗凝血治療（如Heparin）以預防導管相關血栓形成，並非應避免給予（D✗）。"},{n:535,no:25,subj:"其他",q:"有關器官移植後發生急性排斥反應，下列敘述何者最適當？",opts:["A.常見於移植後12～24小時內","B.T淋巴球與巨噬細胞活性增加","C.常見於手術中，移植器官再度恢復血循前","D.無法治療，須立刻移除植入之器官"],ans:[1],expl:"本題答案為B。急性排斥反應的核心免疫機轉是以細胞性免疫為主，主要由T淋巴球辨識並攻擊移植器官組織，並活化巨噬細胞參與發炎反應，此為本題答案。急性排斥反應通常發生於移植後數天至數個月內（尤其以移植後前幾週至前幾個月風險最高），並非侷限於12～24小時內（A✗）；手術中、移植器官恢復血循前即發生的排斥反應，屬於「超急性排斥反應」（因受者體內已存在抗供者抗體所致），並非急性排斥反應的典型時序（C✗）；急性排斥反應多數可透過調整或加強免疫抑制劑治療來控制，並非無法治療、必須立即移除器官（D✗）。"},{n:536,no:26,subj:"其他",q:"有關帶狀疱疹，下列敘述何者最適當？①感染痊癒後通常會有終生免疫力 ②避免摩擦造成水泡破裂，建議穿寬鬆柔軟衣服 ③當有神經痛症狀，可給予適當的止痛藥物 ④未患過水痘的人，應避免與帶狀疱疹病人接觸",opts:["A.①②③","B.②③④","C.①②④","D.①③④"],ans:[1],expl:"本題答案為B（②③④）。②避免摩擦水泡造成破裂，建議穿著寬鬆柔軟衣物，可減少皮膚刺激及續發感染；③帶狀疱疹常合併神經痛，可依醫囑給予止痛藥物緩解症狀；④尚未得過水痘（未具免疫力）的人接觸帶狀疱疹病人的水泡液，有可能被感染而出現水痘，故應避免接觸，此三者敘述皆正確，選②③④＝B（本題答案）。帶狀疱疹是水痘帶狀疱疹病毒（VZV）潛伏於神經節後，於免疫力下降時再度活化所致，患者體內雖已具備一定免疫力，但仍有復發（雖機率低）的可能，並非感染痊癒後即獲得「終生」百分之百的免疫保護，此絕對化敘述並不精確（①錯誤）。"},{n:537,no:27,subj:"其他",q:"成人燒傷部位與範圍包括左上肢全部、左下肢正面及軀幹正面，依據九法則評估其燒傷面積為何？",opts:["A.18%","B.27%","C.30%","D.36%"],ans:[3],expl:"本題答案為D。依成人九法則計算：左上肢全部＝9%，左下肢正面（左下肢18%的一半）＝9%，軀幹正面＝18%，總燒傷面積＝9%＋9%＋18%＝36%，為本題答案。其餘選項（18%、27%、30%）皆與九法則的正確加總數值不符（A、B、C✗）。"},{n:538,no:28,subj:"其他",q:"有關皮膚和傷口照護原則，下列敘述何者最不適當？",opts:["A.銅、硒、矽等微量元素，有助於傷口癒合","B.必要時採隔離照護，避免感染","C.清創術移除壞死組織，有助於傷口癒合","D.傷口在保持乾燥的環境下，有助於上皮化（epithelization）過程"],ans:[3],expl:"本題答案為D。傷口照護目前實證支持「濕潤傷口癒合理論（moist wound healing）」，適度濕潤的環境較能促進上皮化及肉芽組織生長，過度乾燥反而不利於上皮細胞遷移及傷口癒合，「保持乾燥環境有助於上皮化」的敘述與現行傷口照護原則相反，為本題答案（D✗，題目問「何者最不適當」）。銅、硒、矽、鋅等微量元素參與膠原蛋白合成及組織修復，有助傷口癒合（A✓）；對於具傳染風險的傷口感染，必要時應採取隔離防護措施避免交叉感染（B✓）；清創術移除壞死組織可減少細菌孳生環境、促進健康肉芽組織生長（C✓）。"},{n:539,no:29,subj:"其他",q:"有關改善過敏反應的生活指導，下列敘述何者最適當？",opts:["A.使用地氈及棉質窗簾","B.避免使用除濕機及有濾網的空調","C.避免用濕拖把及有集塵袋的吸塵器","D.避免接觸二手菸與刺鼻味道的清潔劑"],ans:[3],expl:"本題答案為D。二手菸及刺激性清潔劑中的化學物質及微粒，容易刺激呼吸道黏膜、誘發過敏或氣喘症狀，應避免接觸，為本題答案。地毯及棉質窗簾容易堆積塵蟎及灰塵等過敏原，過敏體質者應盡量避免使用（而非使用），此建議方向有誤（A✗）；除濕機及具濾網功能的空調有助降低室內濕度、減少塵蟎孳生及過濾空氣中的過敏原，應鼓勵使用（而非避免），此建議方向有誤（B✗）；濕拖把及具集塵袋的吸塵器有助避免打掃時揚起塵蟎及灰塵等過敏原，應鼓勵使用（而非避免），此建議方向有誤（C✗）。"},{n:540,no:30,subj:"其他",q:"有關感染後天免疫缺乏症候群（AIDS）之危險因子，下列敘述何者最不適當？",opts:["A.不安全性行為","B.注射藥癮者","C.接受輸血者","D.共用餐具"],ans:[3],expl:"本題答案為D。AIDS主要透過血液、體液及性接觸傳染，日常共用餐具並不會傳染HIV（病毒無法透過唾液在一般共食情境下有效傳播），並非其危險因子，為本題答案（D✗，題目問「何者最不適當」）。不安全性行為是HIV最主要的傳染途徑之一（A✓）；共用針具的注射藥癮者，因直接血液接觸而具高感染風險（B✓）；接受未經篩檢或篩檢空窗期的血液製品輸血，具有感染風險（C✓）。"},{n:541,no:31,subj:"呼吸系統",q:"有關急性支氣管炎，下列敘述何者最適當？",opts:["A.是常見的上呼吸道感染","B.是指喉部和氣管黏膜發生急性瀰漫性炎症反應","C.若為病毒性感染，Ampicillin通常為第一選擇","D.衛教個案充分休息、均衡飲食及攝取足夠水分"],ans:[3],expl:"本題答案為D。急性支氣管炎多數為病毒性感染引起，治療以支持性療法為主，衛教個案充分休息、均衡飲食及攝取足夠水分以利痰液稀釋排出，是最適當且核心的護理指導，為本題答案。急性支氣管炎是「下呼吸道」感染（侵犯氣管、支氣管），並非上呼吸道感染，此敘述有誤（A✗）；「喉部和氣管黏膜」的急性瀰漫性發炎是「急性喉氣管炎」的定義，急性支氣管炎主要侵犯部位是支氣管黏膜，此敘述部位描述有誤（B✗）；急性支氣管炎多為病毒性感染，Ampicillin為抗生素，對病毒性感染並無療效，並非其第一線用藥（C✗）。"},{n:542,no:32,subj:"呼吸系統",q:"60歲病人，右胸疼痛、發燒、呼吸喘，且咳嗽有大量黃綠色痰液，診斷右肺大葉性肺炎入院。下列何者為其最可能出現的身體評估檢查結果？①右胸觸覺震顫感增強 ②叩診右胸為過度反響音 ③聽診右胸出現喘鳴音 ④右胸支氣管語音字音響亮清楚",opts:["A.①②","B.③④","C.①④","D.②③"],ans:[2],expl:"本題答案為C（①④）。大葉性肺炎因肺組織實變（consolidation），聲音及震動經實化組織傳導效果較含氣正常肺組織更好：①觸診時實變部位的觸覺震顫感會增強；④聽診時實變部位的支氣管語音會更清晰響亮，此二者敘述皆符合肺實變的典型評估發現，選①④＝C（本題答案）。肺實變部位因組織密度增加、含氣量減少，叩診應呈現「濁音」而非「過度反響音」（後者常見於氣胸或肺氣腫等含氣量增加的情形），此敘述方向相反（②錯誤）；肺實變聽診典型會聽到支氣管呼吸音及爆裂音，「喘鳴音」則較常見於氣道狹窄（如氣喘、COPD），並非大葉性肺炎的典型聽診發現（③錯誤）。"},{n:543,no:33,subj:"呼吸系統",q:"有關急性呼吸衰竭之氧合與通氣的評估，下列敘述何者最適當？",opts:["A.動脈血液氣體分析","B.血流動力學監測","C.胸部X光檢查","D.脈衝式血氧濃度儀監測"],ans:[0],expl:"本題答案為A。動脈血液氣體分析（ABG）可同時提供氧合狀態（PaO2）及通氣狀態（PaCO2、pH）的精確數值，是評估急性呼吸衰竭氧合與通氣狀態最直接且完整的檢查方式，為本題答案。血流動力學監測主要評估心臟功能及循環狀態，並非直接評估氧合與通氣的工具（B✗）；胸部X光可提供肺部結構性病灶的影像資訊，但無法直接量化氧合及通氣的數值狀態（C✗）；脈衝式血氧濃度儀僅能提供血氧飽和度（SpO2）的間接評估，無法反映通氣（PaCO2）狀態，且準確度亦受末梢灌流等因素影響（D✗）。"},{n:544,no:34,subj:"心臟血管",q:"有關心肌梗塞急性期處置，下列敘述何者最適當？",opts:["A.注射Heparin需密切監測凝血酶原時間（PT）","B.急性疼痛時，可使用Aspirin","C.採取平躺姿勢可降低心臟負荷","D.ST段上升型可於12小時內給予血栓溶解劑"],ans:[3],expl:"本題答案為D。ST段上升型心肌梗塞（STEMI）為爭取心肌搶救的黃金時間，建議應於症狀發生後12小時內給予血栓溶解劑或及早進行心導管介入治療，以恢復冠狀動脈血流、降低心肌壞死範圍，此為本題答案。注射Heparin期間應監測的凝血功能指標是活化部分凝血活酶時間（aPTT），而非凝血酶原時間（PT，用於監測Warfarin），此敘述監測項目有誤（A✗）；Aspirin是心肌梗塞急性期的標準用藥（抗血小板），但其使用目的並非緩解急性疼痛，緩解疼痛通常使用Morphine等鎮痛藥物，此敘述用藥目的有誤（B✗）；心肌梗塞急性期應採半坐臥姿以減輕心臟負荷及利於呼吸，並非平躺姿勢（C✗）。"},{n:545,no:35,subj:"呼吸系統",q:"有關肺心症病人呼吸道清除功能失效問題之護理處置，下列敘述何者最不適當？",opts:["A.鼓勵每日飲水至少2,500 c.c.","B.協助胸部叩擊、震顫","C.教導深呼吸、咳嗽","D.給予支氣管擴張劑"],ans:[0],expl:"本題答案為A。肺心症（cor pulmonale）常合併右心衰竭及體液滯留，護理措施應著重維持適當（而非過量）水分攝取以利痰液稀釋，但同時須嚴格監測輸入輸出量，避免因水分攝取過量加重心臟負荷及水腫，每日飲水至少2,500 c.c.對於此類病人可能造成體液負荷過重，此建議不適當，為本題答案（A✗，題目問「何者最不適當」）。胸部叩擊、震顫等胸腔物理治療技術有助鬆動及排除呼吸道分泌物（B✓）；教導有效深呼吸、咳嗽技巧，有助促進痰液排出（C✓）；依醫囑給予支氣管擴張劑，有助改善呼吸道通暢度（D✓）。"},{n:546,no:36,subj:"呼吸系統",q:"有關肺栓塞病人使用Warfarin（Coumadin®）治療期間之護理指導，下列敘述何者最不適當？",opts:["A.需監測凝血酶原時間（PT）","B.避免食用富含維生素K的食物","C.需觀察皮膚有無出現出血點或紫斑","D.此藥物有助於溶解血栓"],ans:[3],expl:"本題答案為D。Warfarin的作用機轉是抑制維生素K依賴性凝血因子的合成，屬於預防新血栓形成的抗凝血劑，本身並不具溶解已形成血栓的能力（溶解血栓需使用血栓溶解劑，如tPA），此敘述藥理作用有誤，為本題答案（D✗，題目問「何者最不適當」）。服用Warfarin期間應定期監測PT／INR以確保藥效在治療範圍內（A✓）；富含維生素K的食物會拮抗Warfarin藥效，應避免大量或不規律攝取（B✓）；應密切觀察皮膚有無出血點、紫斑等出血徵象，以及早發現抗凝過度的併發症（C✓）。"},{n:547,no:37,subj:"心臟血管",q:"有關低血容性休克分期的進行期，下列敘述何者最不適當？",opts:["A.身體代償機轉已無法逆轉休克的進行，會導致皮膚濕冷、體溫下降","B.心輸出量下降、血壓下降，可以選擇輸注等張0.9%生理食鹽水","C.造成呼吸性酸中毒、乳酸轉換上升，需要避免輸注乳酸林格氏輸液","D.會造成血中尿素氮（BUN）上升及肌酸酐（creatinine）上升"],ans:[2],expl:"本題答案為C。低血容性休克進行期因組織持續缺血缺氧、無氧代謝增加，會導致代謝性（乳酸性）酸中毒，而非呼吸性酸中毒；此敘述將酸中毒類型（呼吸性應為代謝性）及輸液邏輯混淆，為本題答案（C✗，題目問「何者最不適當」）。休克進行期代償機轉逐漸失效，會出現皮膚濕冷、體溫下降等組織灌流嚴重不足的表現（A✓）；心輸出量及血壓持續下降時，可考慮輸注等張晶體液（如0.9%生理食鹽水）擴充血容積（B✓）；腎臟灌流不足會使代謝廢物蓄積，造成BUN及肌酸酐上升，反映腎前性腎功能受損（D✓）。"},{n:548,no:38,subj:"泌尿系統",q:"有關活體腎臟移植捐贈者，下列敘述何者最不適當？",opts:["A.兩側腎臟功能皆正常，常規尿液檢查正常","B.患糖尿病15年，糖化血色素平均為8.0%","C.年齡20歲以上的五親等內親屬，例如兄弟姊妹","D.動機純正自願捐出腎臟，且同意移植手術"],ans:[1],expl:"本題答案為B。長期糖尿病（病史15年）且血糖控制不佳（糖化血色素8.0%，高於建議控制目標），糖尿病本身即可能已造成腎臟微血管病變，且捐腎後剩餘單一腎臟需承受更高的代謝負擔，此類病人在活體腎臟捐贈的篩選條件中通常屬於不適合捐贈的高風險族群，為本題答案（B✗，題目問「何者最不適當」）。雙側腎功能正常、尿液檢查無異常，是活體捐腎的基本合格條件（A✓）；台灣活體器官捐贈規定捐贈者須為滿20歲以上、五親等內之血親或配偶等特定關係，此描述符合規定（C✓）；捐贈動機純正、自願且知情同意，是活體器官捐贈的核心倫理要求（D✓）。"},{n:549,no:39,subj:"泌尿系統",q:"有關急性腎盂腎炎之照護，下列敘述何者最適當？①紅血球沉降速率（ESR）數值會升高 ②症狀為無尿及貧血 ③鼓勵病人多攝取酸灰性食物如乾梅或蔓越莓 ④鼓勵病人每4小時排尿一次",opts:["A.①④","B.①③","C.②③","D.②④"],ans:[1],expl:"本題答案為B（①③）。①急性腎盂腎炎屬於全身性感染反應，紅血球沉降速率（ESR）等發炎指標會隨之升高；③酸灰性食物（如蔓越莓、梅子）可使尿液酸化，不利細菌滋生，有助輔助治療及預防復發，此二者敘述皆正確，選①③＝B（本題答案）。急性腎盂腎炎典型症狀是發燒、腰痛、頻尿、尿急及膿尿等，並非無尿及貧血（②錯誤）；急性腎盂腎炎病人應鼓勵大量攝取水分以增加排尿頻率、沖刷泌尿道細菌，建議每2～3小時排尿一次，而非僅每4小時一次，此排尿頻率建議過於寬鬆（④錯誤）。"},{n:550,no:40,subj:"內分泌系統",q:"有關高血鈣及其照護，下列敘述何者最適當？",opts:["A.肌肉張力增加、神經過度反射","B.心電圖出現QT間隔延長","C.指導多攝取低膳食纖維飲食以減緩腸蠕動","D.指導多攝取酸灰性食物"],ans:[3],expl:"本題答案為D。高血鈣病人建議多攝取酸灰性食物，可使尿液酸化，降低尿路中鈣鹽結晶沉積形成腎結石的風險，為本題答案。高血鈣會使神經肌肉興奮性降低（而非增加），臨床表現為肌肉無力、反射減退，並非神經過度反射（A✗）；高血鈣心電圖典型表現是QT間隔縮短（而非延長，QT延長常與低血鈣相關），此敘述方向有誤（B✗）；高血鈣常合併腸胃蠕動減緩、便秘，應鼓勵攝取高（而非低）膳食纖維飲食並增加水分攝取，以促進腸蠕動、預防便秘，此敘述方向有誤（C✗）。"},{n:551,no:41,subj:"內分泌系統",q:"有關中樞性尿崩症，下列敘述何者最適當？",opts:["A.尿比重1.050","B.血漿滲透壓290 mOsm/kg","C.多尿、劇渴、心搏過速","D.體液容積過多"],ans:[2],expl:"本題答案為C。中樞性尿崩症因ADH分泌不足，腎小管無法有效再吸收水分，病人會出現大量排尿（多尿）、因體液流失而感到劇渴、且血容積不足時心臟代償性心搏過速，此為本題答案。尿崩症因尿液無法濃縮，尿比重應明顯降低（通常低於1.005），並非高達1.050（此數值反而提示尿液過度濃縮，與尿崩症相反）（A✗）；尿崩症因大量水分流失，血漿滲透壓應升高（通常高於正常上限），290 mOsm/kg屬正常範圍上緣，並未反映尿崩症應有的血漿濃縮程度（B✗）；尿崩症因大量水分流失，會造成體液容積不足（脫水），並非體液容積過多，此敘述方向相反（D✗）。"},{n:552,no:42,subj:"內分泌系統",q:"有關副甲狀腺功能低下病人之處置，下列敘述何者最不適當？",opts:["A.可補充鈣鹽及維生素D","B.急性期需密切觀察呼吸道是否通暢","C.應多攝取高磷食物，例如：肉類、蛋、乳酪等食物","D.在進餐時或飯前可服用氫氧化鋁"],ans:[2],expl:"本題答案為C。副甲狀腺功能低下病人因血磷偏高，應限制（而非鼓勵攝取）高磷食物（如肉類、蛋、乳酪等），以避免血磷進一步上升、加重鈣磷代謝失衡，此建議方向有誤，為本題答案（C✗，題目問「何者最不適當」）。補充鈣鹽及維生素D有助改善低血鈣症狀（A✓）；低血鈣可能誘發喉部肌肉痙攣，急性期須密切觀察呼吸道是否通暢，預防喉痙攣導致的呼吸道阻塞（B✓）；氫氧化鋁可與食物中的磷結合形成不溶性磷酸鋁，減少磷的腸道吸收，可於進餐時或飯前服用以輔助降低血磷（D✓）。"},{n:553,no:43,subj:"內分泌系統",q:"有關原發性多醛固酮症（primary aldosteronism）的臨床表徵，下列敘述何者最適當？",opts:["A.低代謝率","B.低血糖","C.高血鈣","D.低血鉀"],ans:[3],expl:"本題答案為D。原發性多醛固酮症（Conn's syndrome）因醛固酮分泌過多，促使腎小管大量排鉀，臨床上會出現低血鉀，為本題答案。醛固酮主要調控鈉鉀離子平衡及血壓，與代謝率無直接相關，「低代謝率」並非其典型表徵（A✗）；醛固酮並非胰島素拮抗性荷爾蒙，與血糖調節無直接關聯，「低血糖」並非其典型表徵（B✗）；醛固酮主要影響鈉、鉀離子平衡，並非鈣離子代謝，「高血鈣」並非其典型表徵（C✗）。"},{n:554,no:44,subj:"內分泌系統",q:"下列何種激素與調整血糖濃度無關？",opts:["A.抑制素","B.腎上腺素","C.皮質醇","D.生長激素"],ans:[0],expl:"本題答案為A。抑制素（inhibin）主要由性腺（睪丸、卵巢）分泌，負責調節腦下垂體促性腺激素（FSH）的分泌，與血糖濃度調節無關，為本題答案。腎上腺素可促進肝醣分解及糖質新生，具升糖作用，與血糖調節有關（B✗）；皮質醇（cortisol）可促進糖質新生及降低周邊組織對胰島素的敏感性，具升糖作用，與血糖調節有關（C✗）；生長激素可拮抗胰島素作用、促進脂肪分解及升高血糖，與血糖調節有關（D✗）。"},{n:555,no:45,subj:"內分泌系統",q:"有關造成糖尿病人血糖過高之促因，下列敘述何者最不適當？",opts:["A.注射NPH或Lente insulin量過少","B.近日下肢被診斷蜂窩性組織炎","C.近期因業績需求工作壓力增加","D.食量減少而健走運動時間增加"],ans:[3],expl:"本題答案為D。食量減少但運動（健走）時間增加，會使葡萄糖消耗及利用增加，此組合應使血糖降低而非升高，此敘述方向與「造成血糖過高」的題意相反，為本題答案（D✗，題目問「何者最不適當」；此選項描述的情境反而較易導致低血糖）。胰島素（NPH或Lente等中效型胰島素）注射劑量不足，無法有效控制血糖，會造成血糖升高（A✗，即會造成血糖過高，符合題意所指促因）；蜂窩性組織炎等感染會誘發身體壓力反應，升糖荷爾蒙分泌增加，造成血糖上升（B✗，即會造成血糖過高）；工作壓力增加會促使腎上腺素、可體松等壓力荷爾蒙分泌，具升糖作用（C✗，即會造成血糖過高）。"},{n:556,no:46,subj:"其他",q:"小明在登山途中不慎被一條青色的蛇咬傷，下列敘述何者最適當？",opts:["A.辨識蛇的形狀及顏色，並去除身上會影響血循的物品","B.割開傷口，並以嘴吸出毒液","C.以酒精消毒咬傷之傷口，並給予傷口冰敷","D.盡力把蛇打死，帶到急診室以辨別是否為毒蛇"],ans:[0],expl:"本題答案為A。處理蛇咬傷時應盡量辨識蛇的外觀特徵（形狀、顏色、花紋等，以利後續選用正確血清），並移除身上可能因肢體腫脹而影響血液循環的物品（如戒指、手鐲、緊身衣物），此為本題答案。切開傷口並用嘴吸吮排毒，可能使毒液經口腔黏膜傷口吸收造成施救者中毒，且切開傷口可能增加感染及組織損傷風險，現行急救原則已不建議此做法（B✗）；蛇咬傷處置不建議使用酒精消毒或冰敷，冰敷可能因血管收縮加重局部組織壞死，此建議不適當（C✗）；不建議刻意打死蛇隻並攜帶就醫，此舉可能增加二次咬傷風險且耗費搶救黃金時間，現行建議是儘速就醫並可透過拍照方式協助辨識蛇種（D✗）。"},{n:557,no:47,subj:"其他",q:"病人誤食含有機磷成分的巴拉松農藥，導致噁心、嘔吐、淚流不止、口水跟痰液很多，送入急診，下列敘述何者最適當？",opts:["A.有機磷的外觀呈現黑色液體，近似可樂，有杏仁味","B.可給予靜脈注射Atropine或PAM等以緩解症狀","C.立即催吐效果不佳，不可催吐或洗胃","D.初期出現瞳孔放大、低血壓、抽筋麻痺等症狀"],ans:[1],expl:"本題答案為B。有機磷中毒屬於膽鹼激性中毒症狀，Atropine（抗膽鹼藥物）可拮抗過量乙醯膽鹼造成的症狀，PAM（pralidoxime）可協助復活被抑制的乙醯膽鹼酯酶，兩者合併使用是有機磷中毒的標準解毒治療，為本題答案。有機磷農藥的外觀及氣味依產品而異，並非皆呈現黑色液體、可樂狀外觀及杏仁味（杏仁味較常與氰化物中毒聯想），此敘述描述有誤（A✗）；有機磷中毒若在誤食後短時間內，且病人意識清醒、無抽搐及誤吸風險，仍可考慮催吐或洗胃以減少毒物吸收，並非「不可催吐或洗胃」，此敘述過於絕對（C✗）；有機磷中毒屬於膽鹼激性症狀，初期典型表現應是瞳孔縮小（而非放大）、心搏過緩及高血壓（而非低血壓），此敘述症狀方向有誤（D✗）。"},{n:558,no:48,subj:"呼吸系統",q:"嚴重特殊傳染性肺炎（COVID-19）病人之呼吸照護，下列敘述何者最適當？",opts:["A.呼吸喘而拮抗呼吸器，應避免給予鎮靜劑與肌肉鬆弛劑","B.體液輸出入負平衡及俯臥姿勢，有助改善氧合狀態","C.以噴霧治療稀釋痰液，並提供足夠氧氣","D.以T型管（T-Piece）進行呼吸器脫離訓練"],ans:[1],expl:"本題答案為B。COVID-19重症病人常合併急性呼吸窘迫症候群（ARDS），採取體液負平衡（適度限制輸液、必要時利尿）可減少肺水腫、改善氣體交換；俯臥姿勢（prone positioning）已有實證證實可改善通氣血流比、增加背側肺泡的通氣及氧合狀態，此為本題答案。呼吸喘且與呼吸器產生人機不同步（拮抗呼吸器）時，適度給予鎮靜劑甚至肌肉鬆弛劑，有助改善人機同步性、降低氧氣消耗及呼吸功，並非應避免使用，此敘述有誤（A✗）；COVID-19具高度傳染性，噴霧治療（nebulizer）可能產生大量帶病毒氣溶膠微粒，增加病毒傳播風險，臨床上建議盡量避免使用、改採其他替代給藥方式（C✗）；使用T型管進行呼吸器脫離訓練，是評估病人是否能夠脫離呼吸器的傳統測試方式之一，但COVID-19重症病人常因病情尚未穩定、氧合仍不佳，並非此階段呼吸照護的最適當重點措施（D✗，相對於B更貼近急性期呼吸照護核心）。"},{n:559,no:49,subj:"泌尿系統",q:"有關泌尿道感染，下列敘述何者最適當？①確立診斷是指尿液培養每毫升菌落>10⁵個 ②上泌尿道感染是指尿道炎及膀胱炎 ③膀胱炎常見的致病菌為大腸桿菌 ④症狀改善或沒發燒即可停用抗生素",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[1],expl:"本題答案為B（①③）。①有意義菌尿症（顯著泌尿道感染）的診斷切點是尿液培養每毫升菌落數大於10⁵（十萬）個；③大腸桿菌（E. coli）是膀胱炎最常見的致病菌，此二者敘述皆正確，選①③＝B（本題答案）。「上泌尿道感染」是指感染侵犯腎臟及輸尿管（如腎盂腎炎），「尿道炎及膀胱炎」則屬於「下泌尿道感染」，此敘述將上、下泌尿道感染的範圍定義搞反（②錯誤）；抗生素療程應完成醫囑指示的完整療程，即使症狀改善或體溫恢復正常，仍應依療程服用完畢，不可自行提前停藥，以免感染未徹底清除或誘發抗藥性，此敘述有誤（④錯誤）。"},{n:560,no:50,subj:"消化系統",q:"有關阻塞性黃疸的評估，下列敘述何者最適當？",opts:["A.因膽紅素進入腸道，導致糞便呈茶色","B.鹼性磷酸酶指數（alkaline phosphate, ALP）大於正常值","C.凝血酶原時間（PT）檢測正常","D.與輸血引起的溶血反應有關"],ans:[1],expl:"本題答案為B。阻塞性黃疸因膽道阻塞，膽汁（含鹼性磷酸酶等膽道酵素）排出受阻而回流入血，血液中鹼性磷酸酶（ALP）數值會明顯上升，是阻塞性黃疸重要的實驗室診斷依據，為本題答案。阻塞性黃疸因膽紅素無法進入腸道（膽道阻塞），糞便因缺乏膽色素而呈現陶土色（灰白色），並非茶色，此敘述方向有誤（A✗）；膽道阻塞使膽汁無法進入腸道，影響脂溶性維生素K的吸收，進而影響凝血因子合成，凝血酶原時間（PT）通常會延長而非正常，此敘述有誤（C✗）；阻塞性黃疸屬於「肝後性（阻塞性）」黃疸，與紅血球大量破壞導致的「溶血性黃疸」（如輸血溶血反應）在病因機轉上並不相同，此敘述將兩種黃疸類型混淆（D✗）。"},{n:561,no:1,subj:"神經系統",q:"有關頭部外傷病人顱內壓升高的照護，下列何者錯誤？",opts:["A.避免用力排便、咳嗽、打噴嚏及等長運動","B.可以使用Dilantin預防受傷後抽搐的發生","C.若病人有鼻漏時應請病人將鼻水擤乾淨","D.嚴重的顱內壓升高的病人可以使用巴比妥酸鹽（Barbiturate）讓病人鎮靜"],ans:[2],expl:"本題答案為C。若病人出現腦脊髓液（CSF）鼻漏，提示可能有顱底骨折併硬腦膜撕裂，此時應囑咐病人「勿」用力擤鼻涕，以免鼻竇內壓力經破損處竄入顱內造成氣顱，或增加逆行性感染（腦膜炎）風險；正確做法是以無菌棉墊輕拭、任其自然流出，此敘述方向有誤，為本題答案（C✗，題目問「何者錯誤」）。用力排便、咳嗽、打噴嚏及等長運動會誘發Valsalva效應使顱內壓瞬間升高，應避免（A✓）；Dilantin（Phenytoin）常用於預防頭部外傷後早期創傷性抽搐之發生（B✓）；嚴重顱內壓升高、對常規治療反應不佳時，可考慮巴比妥酸鹽誘導昏迷以降低腦部代謝需求及顱內壓（D✓）。"},{n:562,no:2,subj:"神經系統",q:"有關脊髓損傷後脊髓休克期照護的敘述，下列何者錯誤？",opts:["A.肛門反射出現表示脊髓休克期已結束","B.可以插鼻胃管引流胃液減壓","C.可使用高劑量類固醇治療以減輕脊髓水腫","D.經電腦斷層攝影可確診為完全或不完全脊髓損傷"],ans:[3],expl:"本題答案為D。完全與不完全脊髓損傷的鑑別，主要依據臨床神經學檢查（如肛門括約肌隨意收縮、薦髓反射等）判定，電腦斷層（CT）主要顯示骨性結構及出血，無法單獨用以確診神經功能是否完全喪失，此敘述過度簡化且方向有誤，為本題答案（D✗，題目問「何者錯誤」）。肛門反射（球海綿體反射）重現，代表脊髓休克期已結束、可開始評估損傷是否完全（A✓）；脊髓損傷常合併麻痺性腸阻塞，插鼻胃管引流減壓為合理處置（B✓）；高劑量類固醇曾為傳統教科書中減輕脊髓水腫的處置方式，惟近年實證對其效益與風險仍有爭議，臨床使用已趨保守，此處以基礎教材傳統敘述為準（C✓，但提醒此為隨實證持續修正中的議題）。"},{n:563,no:3,subj:"神經系統",q:"有關椎間盤突出手術治療的敘述，下列何者正確？",opts:["A.經皮內視鏡椎間盤切除術，因脊椎穩定度低，通常需住院一星期以上","B.術後傷口癒合後，可進行威廉氏運動加強下背部的肌肉力","C.穿背架時先穿一件厚一點的內衣保護皮膚","D.術後二週傷口癒合後即可恢復原來的活動型態"],ans:[1],expl:"本題答案為B。威廉氏運動（Williams exercise）主要透過強化腹肌及臀肌、伸展下背伸肌群來穩定腰椎、減輕下背負荷，文獻上椎間盤手術後的治療性運動介入多建議於傷口穩定、初期癒合後再循序漸進導入特定強化運動，此敘述時序合理，為本題答案。經皮內視鏡椎間盤切除術屬於微創手術，其設計目的即在於「保留」脊椎後方結構、維持較高的脊椎穩定度，且住院時間通常較傳統手術「更短」（常為數日內甚至門診手術），與此敘述「穩定度低、需住院一週以上」方向相反（A✗）；穿戴背架時建議選擇「薄」而貼身、透氣吸汗的內衣，以避免摩擦及皮膚壓迫問題並利於背架密合，「先穿較厚內衣」並非標準指導（C✗）；術後2週傷口癒合僅代表表皮癒合，脊椎組織癒合及功能恢復通常需數週至數月，仍應遵循漸進式活動限制（如避免久坐、彎腰、提重物），「即可恢復原來活動型態」過於樂觀，為不適當之衛教內容（D✗）。"},{n:564,no:4,subj:"神經系統",q:"有關誘發腦下垂體中風原因的敘述，下列何者正確？",opts:["A.導因於腫瘤壓迫於蝶鞍處，造成內部壓力上升","B.導因於腫瘤壓迫於腦室，造成內部壓力上升","C.導因於下視丘的顱內出血，造成內部壓力上升","D.導因於近腦下垂體血管梗塞，造成內部壓力上升"],ans:[0],expl:"本題答案為A。腦下垂體中風（pituitary apoplexy）是因腦下垂體腫瘤內部出血或梗塞，造成腫瘤體積在蝶鞍（sella turcica）此有限骨性空間內急速擴大，內部壓力驟然上升進而壓迫周邊神經血管構造（如視交叉、海綿竇內顱神經），此為典型病生理機轉及定義，為本題答案。腦下垂體位於蝶鞍內、鞍膈之下，其腫脹主要影響鞍內及鞍旁構造，並非以壓迫腦室為主要機轉（B✗）；下視丘出血為與腦下垂體不同解剖構造的病灶，並非腦下垂體中風之定義（C✗）；腦下垂體中風之出血/梗塞主要發生於「腫瘤組織本身」，而非單純指鄰近血管阻塞，敘述較不精確（D✗）。"},{n:565,no:5,subj:"神經系統",q:"有關身體單側忽略病人的護理措施，下列何者正確？①經常變動房間物品擺設，以增加對周圍環境關注 ②教導病人用轉頭方式，來代償視野缺損 ③鼓勵病人注意及照顧自己患側 ④叫人鈴及電話放在患側，以增加對患側環境關注",opts:["A.①②","B.①③","C.②③","D.③④"],ans:[2],expl:"本題答案為C（②③）。②教導病人以主動轉頭方式代償性掃視忽略側環境，是身體單側忽略（unilateral neglect）病人常用的視覺代償訓練技巧；③鼓勵病人主動注意並參與照顧自己患側身體，可強化患側身體基模的重新建立，此二者皆為公認的核心護理措施，選②③＝C（本題答案）。單側忽略病人建議維持房間物品「固定擺設」及一致動線，以減少因忽略造成的混淆及跌倒風險，「經常變動擺設」並不適當（①錯誤）；照護初期基於安全及溝通考量，叫人鈴、電話等重要物品通常建議先放置於病人「健側」（可及、可感知處），待病人忽略症狀在治療性介入下逐漸改善後，才漸進式地將刺激移向患側以訓練注意力，直接放置於患側可能造成病人無法及時使用、影響安全，並非初期標準做法（④較不適當）。"},{n:566,no:6,subj:"神經系統",q:"有關巴金森氏症病人的臨床表徵，下列何者錯誤？",opts:["A.走路向前傾","B.活動時顫抖厲害","C.臉部表情僵硬","D.走路時雙手不會隨之搖擺"],ans:[1],expl:"本題答案為B。巴金森氏症的顫抖屬於典型的「靜止性顫抖（resting tremor）」，其特徵是安靜不動時明顯、於「主動活動時反而減輕或消失」，此為與其他顫抖疾患（如原發性顫抖為動作性顫抖）鑑別之重要臨床特徵，「活動時顫抖厲害」方向恰好相反，為本題答案（B✗，題目問「何者錯誤」）。前傾姿勢、慌張步態是巴金森氏症典型姿勢步態異常（A✓）；面具臉（masked face）為其典型面部表情喪失表現（C✓）；手臂擺盪減少或消失亦是巴金森氏症典型步態特徵之一（D✓）。"},{n:567,no:7,subj:"神經系統",q:"腦腫瘤病人使用類固醇（Decadron）治療的主要目的，下列何者正確？",opts:["A.預防出血","B.減輕腦水腫","C.預防感染","D.抑制免疫力"],ans:[1],expl:"本題答案為B。腦腫瘤病人使用類固醇（Dexamethasone/Decadron）之主要藥理目的，是透過其抗發炎及穩定細胞膜作用以「減輕腫瘤周圍血管性腦水腫」，進而緩解顱內壓升高相關症狀，此為臨床核心治療目的，為本題答案。類固醇並非以預防出血為主要目的（A✗）；類固醇具免疫抑制作用，理論上可能「增加」而非預防感染風險，且此非其使用於腦腫瘤之目的（C✗）；「抑制免疫力」為類固醇的藥理作用之一，但並非此情境下之治療「目的」，屬於需監測之副作用而非治療目標（D✗）。"},{n:568,no:8,subj:"神經系統",q:"有關內視鏡椎間盤切除術的敘述，下列何者錯誤？",opts:["A.可採用局部麻醉","B.傷口小、局部損傷少、減少硬腦膜的撕裂","C.亦可用於治療嚴重椎間盤位移或是脊椎滑脫者","D.手術及住院的時間均比傳統手術短"],ans:[2],expl:"本題答案為C。內視鏡椎間盤切除術屬微創手術，其適用範圍通常侷限於單純、局限（contained）的椎間盤突出，對於嚴重椎間盤位移或合併脊椎滑脫等需要進行脊椎重建或融合的複雜病灶，通常需採更廣泛之開放性手術處理，並非此微創技術之適應症，此敘述有誤，為本題答案（C✗，題目問「何者錯誤」）。內視鏡椎間盤切除術可於局部麻醉合併鎮靜下執行，病人可配合回饋神經功能狀況（A✓）；此術式傷口小、對周圍正常組織破壞少，並可降低硬腦膜撕裂等併發症風險，為其公認優點（B✓）；相較傳統開放性手術，手術時間及住院天數通常較短（D✓）。"},{n:569,no:9,subj:"消化系統",q:"有關發炎性腸道疾病的敘述，下列何者正確？",opts:["A.好發於60～80歲","B.男性發生比例較女性高","C.可能與感染、食物過敏相關","D.盛行率東方國家比歐美國家常見"],ans:[2],expl:"本題答案為C。發炎性腸道疾病（IBD，包含潰瘍性結腸炎與克隆氏症）之病因學為多因子交互作用，目前實證認為與腸道菌相失衡、腸黏膜免疫系統過度反應（可能由特定感染誘發）及遺傳易感性等相關，此為較符合現行實證之敘述，為本題答案。IBD好發年齡層以年輕成人（約15～30歲）為主要高峰，並非好發於60～80歲之老年族群（A✗）；IBD兩性發生率大致相近（潰瘍性結腸炎男性略多、克隆氏症女性略多），並無「男性明顯高於女性」之一致性結論（B✗）；IBD盛行率傳統上以歐美等已開發國家較高，東方國家雖近年呈上升趨勢，但仍非傳統上盛行率較高的地區，此敘述方向有誤（D✗）。"},{n:570,no:10,subj:"消化系統",q:"有關慢性胰臟炎典型徵象的敘述，下列何者錯誤？",opts:["A.腹痛","B.脂肪痢","C.血糖上升","D.出現透納氏徵象（Turner's sign）"],ans:[3],expl:"本題答案為D。透納氏徵象（grey Turner's sign，兩側腰腹壁瘀斑）為「急性出血性胰臟炎」之典型徵象，並非慢性胰臟炎的常見表現，此敘述不屬於慢性胰臟炎的典型臨床特徵，為本題答案（D✗，題目問「何者錯誤」）。慢性胰臟炎典型三大表現為反覆腹痛、外分泌功能不足導致的脂肪痢，以及內分泌功能受損（胰島細胞破壞）導致的血糖上升／糖尿病，此三者（A、B、C）均為公認之慢性胰臟炎特徵性表現（A✓B✓C✓）。"},{n:571,no:11,subj:"消化系統",q:"有關肝癌的敘述，下列何者正確？",opts:["A.肝癌好發於女性","B.原發性肝癌常見於歐美國家","C.原發性肝癌病人常同時罹患B型肝炎","D.血液中的β-胎兒蛋白升高"],ans:[2],expl:"本題答案為C。台灣及亞洲地區原發性肝癌（肝細胞癌）病人中，慢性B型肝炎感染是最主要的相關危險因子及共病，兩者關聯性密切且具高度實證支持，為本題答案。原發性肝癌好發於「男性」（男女比約2～4：1），並非好發於女性，此敘述性別方向有誤（A✗）；原發性肝癌因與B型肝炎、黃麴毒素暴露等地區性因子高度相關，好發於亞洲、非洲等地區，而非歐美國家，此敘述地區方向有誤（B✗）；肝癌重要的腫瘤標記為「α-胎兒蛋白（AFP，alpha-fetoprotein）」，並非「β-胎兒蛋白」，此敘述蛋白名稱有誤（D✗）。"},{n:572,no:12,subj:"消化系統",q:"有關下腸胃道攝影檢查的敘述，下列何者正確？",opts:["A.檢查前2天採正常飲食，檢查前1天採清流飲食","B.檢查前須清潔灌腸","C.檢查後需限制飲水1,000 mL以下","D.檢查後2～3天解出灰白色糞便是正常現象"],ans:[3],expl:"本題答案為D。下腸胃道攝影（鋇劑灌腸）檢查後，殘留的鋇劑會隨糞便排出，病人於檢查後2～3天內解出灰白色（陶土色／鋇劑色）糞便屬於預期中的正常現象，應向病人衛教安撫而非視為異常，為本題答案。標準鋇劑攝影前置作業通常需提前2～3天採低渣飲食，並配合瀉劑等腸道準備，「檢查前2天仍採正常飲食」之時程過於寬鬆，準備不夠完整（A✗）；清潔灌腸雖為腸道準備之一環，但通常仍須併用瀉劑或口服腸道清潔液才能達到足夠的腸道淨空效果，單靠灌腸並非完整之標準腸道準備方式（B✗）；檢查後應「鼓勵多喝水」而非限制飲水，以協助排出殘留鋇劑、預防鋇劑滯留腸道造成便秘或腸阻塞等併發症，限制飲水於1,000 mL以下之敘述方向有誤（C✗）。"},{n:573,no:13,subj:"消化系統",q:"有關胃食道逆流的敘述，下列何者正確？",opts:["A.心灼熱感是胃食道逆流最常見的症狀","B.可能是因為下食道括約肌壓力太高導致逆流","C.可使用β-block藥物治療","D.進食後應躺下，以緩解胃食道逆流不適症狀"],ans:[0],expl:"本題答案為A。心灼熱感（pyrosis，胸骨後灼熱感）是胃食道逆流最典型、最常見的臨床症狀，為診斷此疾病重要的主訴依據，為本題答案。胃食道逆流的核心致病機轉是下食道括約肌「壓力過低」或不當放鬆，使胃內容物逆流至食道，並非壓力過高，此敘述方向有誤（B✗）；胃食道逆流的藥物治療以氫離子幫浦阻斷劑（PPI）、H2受體阻斷劑為主，β-阻斷劑並非其標準治療用藥（C✗）；進食後應維持坐姿或直立姿勢至少1～2小時，避免立即躺下，以減少逆流機會，「進食後應躺下」之建議方向有誤（D✗）。"},{n:574,no:14,subj:"消化系統",q:"有關消化性潰瘍的敘述，下列何者正確？",opts:["A.胃酸分泌過多，破壞消化道的肌肉層","B.胃潰瘍好發年輕人為主","C.十二指腸潰瘍進食後30分鐘內疼痛症狀會加劇","D.可能為幽門桿菌感染所引起"],ans:[3],expl:"本題答案為D。目前實證確立幽門螺旋桿菌（H. pylori）感染是消化性潰瘍最主要致病因子之一，根除治療已成為潰瘍病人的標準處置，為本題答案。消化性潰瘍之形成除胃酸分泌因素外，更關鍵在於胃黏膜防禦機轉受損，且潰瘍主要侵犯黏膜及黏膜下層，並非以破壞「肌肉層」作為定義性描述，此敘述並不精確（A✗）；胃潰瘍好發族群以中老年人（約55～65歲）為主，「好發年輕人」較符合十二指腸潰瘍之族群特性而非胃潰瘍整體趨勢，此敘述有誤（B✗）；十二指腸潰瘍典型疼痛型態為「進食後疼痛緩解、空腹或餐後2～3小時疼痛加劇」，而「進食後30分鐘內疼痛加劇」實為胃潰瘍之典型疼痛型態，此敘述將兩者混淆（C✗）。"},{n:575,no:15,subj:"消化系統",q:"王先生最近感覺疲勞就醫，抽血檢驗發現血清IgG Anti-HAV為陽性時所代表的意義，下列何者正確？",opts:["A.表示感染源為血液污染","B.表示曾經感染A型肝炎","C.表示目前是A型肝炎急性期","D.表示對A型肝炎已無免疫力"],ans:[1],expl:"本題答案為B。血清IgG Anti-HAV陽性代表個案曾經感染過A型肝炎病毒（或曾接種疫苗）並已產生保護性抗體，屬於「既往感染／免疫」的指標，為本題答案。A型肝炎主要透過「糞口途徑」傳染（如受污染的食物、飲水），並非血液傳染為主，此敘述傳染途徑有誤（A✗）；急性感染期的血清標記是「IgM Anti-HAV」，IgG通常於感染較後期或痊癒後才轉為陽性並持續存在，並非代表目前急性期，此敘述有誤（C✗）；IgG Anti-HAV陽性正代表個案「已具有」保護性抗體及免疫力，並非無免疫力，此敘述方向恰好相反（D✗）。"},{n:576,no:16,subj:"其他",q:"白老太太76歲，有高血壓及糖尿病，配戴假牙，下列何者不是預防齲齒的護理指導？",opts:["A.建議植牙","B.使用牙線剔牙","C.牙齒塗氟","D.減少醣類攝取"],ans:[0],expl:"本題答案為A。植牙是缺牙後的一種贗復（重建）治療選項，而非齲齒的「預防」措施，對於已配戴假牙、有高血壓糖尿病等共病的76歲長者而言，貿然建議植牙這類侵入性手術並不屬於標準齲齒預防衛教範疇，為本題答案（A✗，題目問「何者不是」預防措施）。使用牙線清潔假牙鄰接處及殘餘牙齒，有助移除牙菌斑、預防齲齒（B✓為預防措施）；牙齒塗氟可強化琺瑯質、降低齲齒風險，為公認的預防措施（C✓為預防措施）；減少醣類（含糖食物）攝取可降低口腔內產酸菌活性、預防齲齒，為基本飲食衛教（D✓為預防措施）。"},{n:577,no:17,subj:"消化系統",q:"有關黃疸的敘述，下列何者錯誤？",opts:["A.阻塞性黃疸會使大便呈灰白色","B.溶血性黃疸之凝血酶原時間延長","C.膽鹽沉積於皮膚引起搔癢","D.尿中尿膽素原增加，尿液呈茶色"],ans:[1],expl:"本題答案為B。溶血性黃疸（肝前性黃疸）主因紅血球大量破壞導致未結合型膽紅素增加，其肝臟合成凝血因子的功能本身並未受損，故凝血酶原時間（PT）通常維持「正常」，並不會延長；PT延長較常見於肝細胞性黃疸（合成功能受損）或阻塞性黃疸（維生素K吸收障礙），此敘述將PT延長歸因於溶血性黃疸並不正確，為本題答案（B✗，題目問「何者錯誤」）。阻塞性黃疸因膽紅素無法排入腸道，糞便因缺乏膽色素而呈現灰白色（陶土色），此為典型表現（A✓）；膽鹽沉積於皮下組織會刺激神經末梢，引起搔癢感，是阻塞性／膽汁鬱積性黃疸常見症狀（C✓）；肝細胞性黃疸病人尿液中尿膽素原可能增加，加上膽紅素尿，使尿液呈現深茶色，為常見表現（D✓）。"},{n:578,no:18,subj:"骨骼肌肉",q:"有關骨性關節炎病人適合的運動類型，下列何者錯誤？",opts:["A.慢跑","B.水中有氧運動","C.騎腳踏車","D.走路"],ans:[0],expl:"本題答案為A。慢跑屬於高衝擊性運動，會使已受損的關節軟骨承受反覆重力衝擊負荷，可能加速骨性關節炎病程進展、加重關節疼痛，並非骨性關節炎病人建議的運動類型，為本題答案（A✗，題目問「何者錯誤」）。水中有氧運動因水的浮力可大幅減少關節負重，屬低衝擊性運動，適合骨性關節炎病人（B✓）；騎腳踏車屬低衝擊性有氧運動，可訓練下肢肌力同時減少關節衝擊（C✓）；適度、規律的走路運動有助維持關節活動度及肌力，屬建議的低衝擊運動（D✓）。"},{n:579,no:19,subj:"骨骼肌肉",q:"王先生接受右側全髖關節置換術後出現胸痛、呼吸短促、皮膚蒼白、冰冷。下列何者是王先生最可能產生的術後合併症？",opts:["A.關節脫位","B.出血","C.肺栓塞","D.深部靜脈栓塞"],ans:[2],expl:"本題答案為C。病人於全髖關節置換術後出現胸痛、呼吸急促、皮膚蒼白冰冷等全身性呼吸循環症狀，此組合高度提示「肺栓塞」，是骨科大手術（尤其髖、膝關節置換）後因深部靜脈血栓脫落、栓子隨血流進入肺循環所致的重大且需緊急處置之合併症，為本題答案。人工關節脫位典型表現是患肢疼痛、變形、活動受限及肢體長度改變，並不會出現胸痛及呼吸急促等全身性症狀（A✗）；單純傷口出血通常以局部腫脹、引流量增加、血比容下降等表現為主，不會直接造成胸痛及呼吸窘迫（B✗）；深部靜脈栓塞本身典型表現為患肢局部腫脹、疼痛及溫熱感，若栓子尚未脫落造成肺栓塞，通常不會出現胸痛及呼吸困難等全身性症狀，此題描述之全身性呼吸循環症狀更符合「已發生肺栓塞」之表現，而非單純深部靜脈栓塞（D✗，屬於較不完整的答案）。"},{n:580,no:20,subj:"骨骼肌肉",q:"有關上石膏病人的護理指導，下列何者錯誤？",opts:["A.若石膏肢體遠端皮膚顏色呈現蒼白或冰冷，表示動脈循環受阻","B.若石膏肢體遠端出現不尋常腫脹，表示靜脈回流受阻","C.若石膏表面出現灼熱點，表示石膏內的肢體有感染的情形","D.若聞到石膏有酸味，表示石膏內的肢體有組織壞死或感染"],ans:[3],expl:"本題答案為D。組織壞死或感染引起的異味，臨床上多描述為「惡臭味／腐敗味」，而非specifically「酸味」，此選項以「酸味」作為組織壞死或感染的判斷依據，用詞不夠精確，與標準教材慣用描述有出入，為本題答案（D✗，題目問「何者錯誤」；惟此處提醒：石膏內出現任何異常氣味皆應提高警覺並回報評估，不應完全排除感染可能）。石膏肢體遠端皮膚蒼白冰冷，提示動脈血循環受阻，為重要警訊（A✓）；石膏肢體遠端不尋常腫脹，提示靜脈回流受阻，亦為重要警訊（B✓）；石膏表面局部出現異常灼熱點，可能反映其下方組織有發炎或感染反應，為臨床上會提高警覺評估的徵象（C✓）。"},{n:581,no:21,subj:"骨骼肌肉",q:"有關骨科手術合併症的敘述，下列何者錯誤？",opts:["A.脂肪栓塞是因脂肪球由皮下組織釋出而導致的嚴重合併症","B.開放性骨折復位手術最常見的合併症為神經血管合併症","C.手術肢體若長時間固定不動，易導致血栓性靜脈炎之發生","D.若術後突然胸痛、呼吸困難，有可能是肺栓塞，需緊急治療"],ans:[0],expl:"本題答案為A。脂肪栓塞症候群（fat embolism syndrome）的脂肪球主要來源是長骨骨折後「骨髓」內的脂肪組織經由損傷血管進入靜脈循環，並非源自皮下組織，此敘述來源有誤，為本題答案（A✗，題目問「何者錯誤」）。開放性骨折復位手術過程中，鄰近的血管神經構造有受損風險，神經血管合併症確為此類手術常見且需嚴密監測之合併症（B✓）；長時間肢體固定不動會使靜脈血流滯緩，增加血栓性靜脈炎及深部靜脈栓塞風險（C✓）；骨科手術後若病人突然出現胸痛、呼吸困難，需高度懷疑肺栓塞可能，屬急症需立即處置（D✓）。"},{n:582,no:22,subj:"感官系統",q:"有關白內障的晶體乳化法手術的敘述，下列何者錯誤？",opts:["A.需等晶狀體成熟後才執行手術","B.用超音波將晶體核震碎後取出","C.可縮小傷口至0.3公分","D.手術中同時植入人工水晶體"],ans:[0],expl:"本題答案為A。現行實證及臨床實務中，白內障超音波乳化術（phacoemulsification）已可依病人視覺功能受影響程度（如視力減退、影響日常生活）作為手術適應症，「不需等待」晶狀體完全成熟才進行手術，此觀念屬於傳統囊外摘除術時代的舊有原則，已不符合現行超音波乳化術之適應症判斷，為本題答案（A✗，題目問「何者錯誤」）。此術式即是利用超音波探頭將混濁晶體核震碎乳化後抽吸取出，為其操作原理（B✓）；小切口（可縮小至約0.2～0.3公分）為此術式相較傳統術式的重要優勢之一（C✓）；現行標準術式多於術中同時完成人工水晶體植入，一次手術完成視力重建（D✓）。"},{n:583,no:23,subj:"感官系統",q:"有關美尼爾氏症候群（Meniere's disease）病人的護理指導，下列何者錯誤？",opts:["A.移動身體需緩慢","B.病人應採用低鉀飲食","C.給予利尿劑可減輕症狀","D.鼓勵病人做頭部及全身的平衡運動"],ans:[1],expl:"本題答案為B。美尼爾氏症（內耳膜迷路水腫）的飲食控制原則核心是「低鈉飲食」，藉由減少鈉離子攝取降低內淋巴液滲透壓及容積，進而減輕內耳水腫及眩暈發作頻率，並非低鉀飲食，此敘述營養素方向有誤，為本題答案（B✗，題目問「何者錯誤」）。移動身體宜緩慢，避免突然改變姿勢誘發眩暈及跌倒（A✓）；利尿劑可減少體液及內淋巴液蓄積，為常用輔助藥物治療（C✓）；頭部及全身平衡（前庭）復健運動有助改善長期平衡功能及降低發作影響（D✓）。"},{n:584,no:24,subj:"感官系統",q:"有關鼻咽癌病人接受放射線治療的敘述，下列何者錯誤？",opts:["A.放射線治療為主要治療方式","B.放射線治療前要評估聽力","C.放射線治療前先要處理蛀牙","D.連續6～7週不間斷地放射線治療"],ans:[3],expl:"本題答案為D。放射線治療的標準給予方式為分次治療（fractionation），通常於平日給予、週末休息，且療程中若病人出現嚴重黏膜炎等副作用，臨床上可能需視情況安排治療中斷或調整，「連續6～7週不間斷」之敘述與標準分次治療排程不符，為本題答案（D✗，題目問「何者錯誤」）。鼻咽癌因解剖位置深且對放射線敏感，放射線治療為其主要治療方式（A✓）；因放射線治療範圍鄰近耳部構造，治療前應評估基礎聽力狀態以利日後追蹤比較（B✓）；頭頸部放射線治療前應先處理蛀牙等牙科問題，以降低治療後因牙科處置誘發顎骨放射線壞死之風險（C✓）。"},{n:585,no:25,subj:"感官系統",q:"有關扁桃腺炎的處置，下列何者錯誤？",opts:["A.急性發炎時行扁桃腺切除術","B.用溫食鹽水漱口","C.冰敷可以緩解咽喉部疼痛","D.發燒症狀消退後，抗生素仍需使用48～72小時"],ans:[0],expl:"本題答案為A。扁桃腺切除術通常安排於急性發炎（感染）控制、症狀緩解後的非急性期進行，於「急性發炎期」手術會增加術中出血及感染擴散至周邊組織的風險，並非適當的手術時機，為本題答案（A✗，題目問「何者錯誤」）。A群鏈球菌是急性扁桃腺炎最常見的致病菌之一，此為正確之病原學敘述（B✓）；以溫食鹽水漱口可協助清潔口咽部、緩解不適，為常用支持性照護（C✓）；即使症狀（發燒）已緩解，仍應依醫囑完成48～72小時以上的完整抗生素療程，以避免感染復發或誘發風濕熱等併發症（D✓）。"},{n:586,no:26,subj:"心臟血管",q:"86歲男性，長期高血壓，近日經醫師診斷為主動脈瓣狹窄，醫師建議更換心臟瓣膜，有關瓣膜選擇與抗凝劑使用的敘述，下列何者正確？",opts:["A.宜選用機械性人工瓣膜，並需終身服用Warfarin","B.宜選用生物性人工瓣膜，不需終身服用Warfarin","C.宜選用機械性人工瓣膜，不需終身服用Warfarin","D.宜選用生物性人工瓣膜，並需終身服用Warfarin"],ans:[1],expl:"本題答案為B。對於高齡（如86歲）病人，臨床上多優先考慮選用「生物性（組織）瓣膜」，因其不需終身服用Warfarin抗凝劑，可降低高齡病人使用抗凝劑相關之出血風險（如跌倒相關顱內出血），雖然生物瓣膜使用年限較機械瓣膜短，但相對於高齡病人有限的預期壽命，此權衡通常傾向選擇生物瓣膜，為本題答案。機械瓣膜雖然耐用年限較長，但因血栓形成風險高，病人「必須終身服用Warfarin」，對高齡病人而言出血風險考量較不利，此組合並非首選（A✗、C✗，其中C漏未提及需服用Warfarin亦為方向錯誤）；生物瓣膜使用者仍可能因心房顫動等其他合併症而需服用抗凝劑，但並非因瓣膜本身「終身」需要，「宜選用生物性瓣膜並需終身服用Warfarin」之敘述將機械瓣膜的抗凝需求誤植於生物瓣膜，方向有誤（D✗）。"},{n:587,no:27,subj:"心臟血管",q:"關於雷諾氏病的敘述，下列何者錯誤？",opts:["A.該疾病好發於年輕女性","B.好發於近心端肢體","C.容易因為冷的環境或壓力誘發","D.患側肢體先變白，再轉為發紺"],ans:[1],expl:"本題答案為B。雷諾氏病（Raynaud's disease）好發於肢體「遠心端」（末梢，如手指、腳趾），並非近心端肢體，此敘述部位方向有誤，為本題答案（B✗，題目問「何者錯誤」）。雷諾氏病確實好發於年輕女性族群（A✓）；寒冷環境或情緒壓力是誘發血管痙攣發作的典型誘因（C✓）；發作時患部因血管痙攣缺血先呈現蒼白，隨後因缺氧轉為發紺（青紫），此為典型三相膚色變化之一部分（D✓）。"},{n:588,no:28,subj:"心臟血管",q:"有關冠狀動脈繞道手術後，為維持正常心輸出量的處置，下列敘述何者錯誤？",opts:["A.使用Dobutamine，可以增加心肌收縮力","B.使用Furosemide（Lasix），可以降低心臟之前負荷","C.使用Nitroglycerine，可以增加心肌收縮力","D.使用Nipride，可以同時降低心臟之前、後負荷"],ans:[2],expl:"本題答案為C。硝化甘油（Nitroglycerine）主要透過釋放一氧化氮，作用於血管平滑肌造成「靜脈擴張」為主（低劑量時），藉由減少靜脈回流以降低心臟前負荷，進而降低心肌氧耗；文獻證實其並不會增加（甚至不影響）心肌收縮力，此敘述藥理作用有誤，為本題答案（C✗，題目問「何者錯誤」）。Dobutamine為正性肌力藥物，可增加心肌收縮力，敘述正確（A✓）；Furosemide（Lasix）為利尿劑，可減少循環容積、降低心臟前負荷，敘述正確（B✓）；Nipride（Nitroprusside）為平衡型血管擴張劑，同時擴張動、靜脈，可同時降低前負荷及後負荷，敘述正確（D✓）。"},{n:589,no:29,subj:"心臟血管",q:"有關風濕熱的主要臨床表徵，下列何者錯誤？",opts:["A.邊緣性紅斑","B.凝血時間延長","C.多發性關節炎","D.皮下結節"],ans:[1],expl:"本題答案為B。風濕熱之Jones診斷準則主要臨床表現（major criteria）包含心臟炎、多發性游走性關節炎、舞蹈症、邊緣性紅斑及皮下結節，並不包含「凝血時間延長」此項血液凝固功能異常，此敘述並非風濕熱之典型表現，為本題答案（B✗，題目問「何者錯誤」）。邊緣性紅斑為Jones準則主要表現之一（A✓）；多發性游走性關節炎亦為Jones準則主要表現之一，且是最常見的表現（C✓）；皮下結節同為Jones準則主要表現之一（D✓）。"},{n:590,no:30,subj:"心臟血管",q:"有關心包填塞（cardiac tamponade）症狀的敘述，下列何者錯誤？",opts:["A.頸靜脈怒張","B.心跳變快","C.尿量減少","D.收縮壓上升"],ans:[3],expl:"本題答案為D。心包填塞經典表現為貝克氏三徵（Beck's triad）：低血壓、頸靜脈怒張及心音低沉（muffled heart sounds），其中血壓應為「下降」而非上升，此敘述方向有誤，為本題答案（D✗，題目問「何者錯誤」）。頸靜脈怒張為貝克氏三徵之一，因心包填塞阻礙靜脈血回流入心臟所致（A✓）；心輸出量下降時，身體會代償性增加心跳速率以維持組織灌流，故心跳變快為常見表現（B✓）；心輸出量下降導致腎臟灌流不足，會使尿量減少（C✓）。"},{n:591,no:31,subj:"心臟血管",q:"下肢周邊血管動脈疾病的護理指導，下列敘述何者正確？",opts:["A.多攝取高飽和脂肪酸食物","B.鼓勵促進下肢血循運動","C.鼓勵抬高患肢","D.給予局部熱敷"],ans:[1],expl:"本題答案為B。規律、適度的下肢運動（如步行運動計畫）有助促進側枝循環建立，是周邊血管動脈疾病公認的第一線保守治療措施之一，可延長跛行前行走距離，為本題答案。動脈疾病與動脈粥狀硬化密切相關，應限制（而非攝取）高飽和脂肪酸食物，以延緩病程進展，此建議方向有誤（A✗）；動脈供血不足時，抬高患肢會因重力作用進一步減少動脈血流灌注，加重缺血症狀，此建議僅適用於靜脈功能不全而非動脈疾病，此敘述並不適當（C✗）；動脈循環不良的肢體因感覺功能可能已受影響，直接局部熱敷有較高燙傷風險且未必能有效改善深層組織灌流，並非建議的常規措施（D✗）。"},{n:592,no:32,subj:"心臟血管",q:"病人昨天接受冠狀動脈繞道手術（CABG），胸管引流量共600 mL，今體溫38.7℃，血壓100/60 mmHg，SaO2 94%。下列處置何者錯誤？",opts:["A.胸管引流量多，應評估凝血功能","B.SaO2 94%，應給予O2 cannula 3 L/min","C.血壓偏低，應給予輸血","D.體溫過高，應給予Aspirin"],ans:[3],expl:"本題答案為D。病人術後出現發燒（38.7℃）合併胸管高引流量（600 mL），臨床上應優先考慮感染或出血相關評估及以標準退燒處置（如乙醯胺酚）因應，而非給予Aspirin；Aspirin具抗血小板作用，在胸管引流量已偏多、有出血疑慮的情況下額外給予，恐進一步增加出血風險，且Aspirin本身並非以退燒為主要臨床使用目的，此處置並不適當，為本題答案（D✗，題目問「何者錯誤」）。胸管引流量達600 mL，確實應優先評估病人凝血功能狀態，以釐清是否存在出血傾向（A✓）；SaO2 94%顯示輕度低血氧，給予鼻導管氧氣治療為合理的支持性處置（B✓）；血壓100/60 mmHg合併高胸管引流量及發燒，在排除其他原因前，評估是否因失血導致血容積不足、進而考慮是否需要輸血，屬合理的臨床判斷方向（C✓，惟仍應先確認血色素／血比容數值及出血狀況再決定是否輸血）。"},{n:593,no:33,subj:"心臟血管",q:"有關搭飛機長程旅行後常會出現深部靜脈栓塞的主要原因，下列何者正確？",opts:["A.靜脈內皮細胞受損","B.血液凝固性增加","C.血液鬱積","D.血管收縮"],ans:[2],expl:"本題答案為C。長程飛行時病人長時間維持坐姿不動，依據魏氏三要素（Virchow's triad），此情境下最主要的致病機轉是下肢靜脈血流因缺乏肌肉幫浦作用而滯緩鬱積（血液鬱積），進而增加血栓形成風險，此即「經濟艙症候群」之核心成因，為本題答案。單純久坐並不直接造成靜脈內皮細胞損傷，內皮損傷較常見於創傷或手術情境（A✗）；血液凝固性增加可能是促成因子之一，但並非長程飛行久坐情境下最主要、最直接相關的機轉（B✗）；此情境之機轉為血流滯緩而非血管收縮，敘述方向不符（D✗）。"},{n:594,no:34,subj:"心臟血管",q:"奇脈（paradoxical pulse）是指下列何種情況？",opts:["A.呼氣時，收縮壓下降超過10 mmHg","B.吸氣時，收縮壓下降超過10 mmHg","C.呼氣時，舒張壓下降超過10 mmHg","D.吸氣時，舒張壓下降超過10 mmHg"],ans:[1],expl:"本題答案為B。奇脈（pulsus paradoxus）之定義為病人於「吸氣」時，收縮壓下降幅度「超過10 mmHg」，此為標準教科書定義，為本題答案，常見於心包填塞、嚴重氣喘或慢性阻塞性肺病急性發作等情境。奇脈之血壓變化發生於吸氣而非呼氣（A✗、C✗方向錯誤）；奇脈定義是針對「收縮壓」的變化，並非舒張壓（D✗，且方向亦誤）。"},{n:595,no:35,subj:"腫瘤血液",q:"有關多發性骨髓瘤病人的護理指導，下列何者錯誤？",opts:["A.避免接觸感冒的親友","B.避免運動以預防病理性骨折","C.建議穿上背架減輕骨骼壓力","D.鼓勵飲水以降低血鈣濃度"],ans:[1],expl:"本題答案為B。多發性骨髓瘤病人因蝕骨性病灶使骨骼脆弱、易發生病理性骨折，但護理指導原則是「避免高風險或劇烈活動」（如跳躍、負重過度），而非完全禁止所有運動；適度、安全範圍內的負重運動反而有助維持骨密度並預防長期臥床相關併發症（如血栓、肌肉萎縮），完全避免運動之敘述過於絕對，並不適當，為本題答案（B✗，題目問「何者錯誤」）。病人因疾病本身及治療常伴隨免疫力下降，應避免接觸感冒或感染中的親友，以降低感染風險（A✓）；穿戴背架可提供骨骼結構支持，減輕脊椎骨骼所承受之壓力，降低病理性骨折風險（C✓）；多發性骨髓瘤常合併高血鈣，鼓勵病人適度飲水有助促進鈣質排出、降低血鈣濃度（D✓）。"},{n:596,no:36,subj:"腫瘤血液",q:"有關癌症疼痛三階梯止痛療法的敘述，下列何者正確？",opts:["A.需要時給予止痛劑，比按時給予止痛劑的止痛效果好","B.第一階段建議使用弱效麻醉性止痛劑，合併輔助性藥物","C.麻醉性止痛劑有天花板效應，即使增加劑量，止痛效果也不會增加","D.麻醉性止痛藥物的解毒劑是Naloxone"],ans:[3],expl:"本題答案為D。Naloxone為鴉片類受體拮抗劑，是麻醉性止痛劑（鴉片類藥物）過量或中毒時標準使用的解毒劑，為本題答案。世界衛生組織癌症疼痛控制原則強調「按時（by the clock）」給藥優於「需要時才給」的PRN方式，可使血中藥物濃度較穩定、預防疼痛發生而非等疼痛出現才處理，此敘述方向有誤（A✗）；三階梯止痛療法第一階段建議使用之藥物為「非鴉片類止痛劑」（如NSAID、乙醯胺酚），可視情況合併輔助藥物，第二階段才開始使用弱效鴉片類藥物，此敘述將第二階段之用藥誤植為第一階段（B✗）；強效鴉片類止痛劑（如Morphine）之重要藥理特性即是「無天花板效應」，可依疼痛程度持續調整劑量以達止痛效果（此為與NSAID等非鴉片類藥物的重要區別，後者才具天花板效應），此敘述方向有誤（C✗）。"},{n:597,no:37,subj:"腫瘤血液",q:"有關癌症病人口腔黏膜障礙照護的敘述，下列何者正確？①使用含類固醇的口內膏，可緩解疼痛和發炎 ②Nystatin可預防白色念珠菌感染，漱口後要吐掉不可吞服 ③病人對苦味的敏感度減少，故可以吃苦瓜和芥菜，補充纖維素 ④使用口香糖可維持口腔濕潤",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"本題答案為B（①④）。①含類固醇口內膏具局部抗發炎效果，可用以緩解口腔黏膜發炎及疼痛症狀；④咀嚼口香糖可刺激唾液分泌，有助維持口腔濕潤，此二者敘述皆屬合理照護措施，選①④＝B（本題答案）。Nystatin漱口懸液標準使用方式為口內含漱後盡量延長停留時間，多數治療指引建議可吞服（部分方案採漱口後吞服以同時處理可能之食道念珠菌感染），並非一概「不可吞服」，此絕對化敘述與標準用藥指導不符（②錯誤）；癌症病人接受化學治療期間口腔黏膜常較敏感脆弱，苦瓜、芥菜等質地較粗糙或味道刺激的食材，可能進一步刺激已受損之口腔黏膜造成不適，並非適合此時攝取之食物選擇（③錯誤）。"},{n:598,no:38,subj:"腫瘤血液",q:"有關癌症病人感染問題的照護與護理指導，下列何者正確？",opts:["A.嗜中性白血球低下病人都會出現典型發炎症狀，如發燒等","B.多吃養樂多和優格等食品對病人是有益處的","C.絕對嗜中性白血球低於500/mm3要採取保護隔離","D.家屬接種活性疫苗3週後即可探視病人"],ans:[2],expl:"本題答案為C。當絕對嗜中性白血球計數（ANC）低於500/mm³時，病人處於嚴重感染高風險狀態，臨床上應採取保護性隔離措施以降低外源性病原體暴露風險，此為標準照護原則，為本題答案。嗜中性白血球低下病人因缺乏足夠白血球執行發炎反應，感染時可能無法出現典型發燒、紅腫等發炎徵象（症狀可能不典型甚至被掩蓋），「都會出現典型發炎症狀」之敘述並不正確，反而應提高警覺留意任何些微異常（A✗）；優格、養樂多等含活性益生菌之發酵乳製品，可能帶有病原菌污染風險，嗜中性白血球低下飲食原則通常建議避免生冷及含活菌食品，此建議並不適當（B✗）；接種活性減毒疫苗後的一段期間內，接種者可能有病毒排出（shedding）之疑慮，對於免疫力低下病人應審慎評估探視時機及採取適當防護，並非固定3週後即可視為安全無虞，此建議過於一概而論、不夠嚴謹（D✗）。"},{n:599,no:39,subj:"腫瘤血液",q:"有關補充鐵劑的敘述，下列何者正確？",opts:["A.鐵劑不會刺激腸胃道可空腹服用","B.維生素E有助於鐵劑吸收","C.口服後立刻漱口可減少牙齒染色","D.鐵劑注射後要按摩以加速吸收"],ans:[2],expl:"本題答案為C。口服液態鐵劑可能造成牙齒染色，服用後立即漱口有助清除殘留於牙齒表面之鐵劑，減少染色機會，為標準護理指導，為本題答案。鐵劑常見腸胃道刺激副作用（如噁心、上腹不適、便秘），臨床上為兼顧吸收效果與腸胃耐受度，常視情況與少量食物併服，「不會刺激腸胃道可空腹服用」之敘述並不準確（A✗）；增進非血基質鐵吸收之輔助營養素為「維生素C」，並非維生素E，此敘述誤植輔助吸收之維生素種類（B✗）；肌肉注射鐵劑（如Iron dextran）應採Z字形注射技術以避免藥液滲漏至皮下造成染色及刺激，注射後應「避免按摩」注射部位，以防藥液滲漏擴散，此敘述與標準注射技術原則相反（D✗）。"},{n:600,no:40,subj:"腫瘤血液",q:"林先生在輸血過程中出現頭痛、咳嗽、呼吸困難、心跳加快及血壓升高等情形，最有可能是出現下列那一種輸血反應？",opts:["A.急性溶血反應","B.循環過度負荷","C.過敏反應","D.輸血相關之急性肺損傷"],ans:[1],expl:"本題答案為B。病人於輸血過程中出現頭痛、咳嗽、呼吸困難、心跳加快及血壓「升高」等症狀，此組合符合輸血相關循環過度負荷（TACO）之典型表現，因短時間輸入過多液體容積造成心臟負荷增加所致，為本題答案。熱原反應（發燒反應）典型表現為發燒、發冷、頭痛，通常不會合併蕁麻疹、哮喘或此題所述之呼吸循環症狀組合（A✗）；過敏反應典型表現以皮膚癢疹、蕁麻疹、潮紅甚至呼吸道痙攣為主，通常不伴隨血壓「升高」（此題血壓上升更符合容積過荷而非過敏機轉）（C✗）；輸血相關急性肺損傷（TRALI）典型表現為急性低血氧合併肺水腫，血壓通常正常或偏低（而非上升），與此題描述不完全相符（D✗）。"},{n:601,no:41,subj:"腫瘤血液",q:"長期攝取低纖維或精緻飲食，可能與下列何種癌症的發生最有關？",opts:["A.胃癌","B.肝癌","C.大腸癌","D.乳癌"],ans:[2],expl:"本題答案為C。長期攝取低纖維或精緻飲食，會使腸道蠕動時間延長、糞便中潛在致癌物質與大腸黏膜接觸時間增加，此為公認與大腸癌發生密切相關之飲食型態危險因子，為本題答案。胃癌與飲食因子（如高鹽、醃漬煙燻食物、幽門螺旋桿菌感染）較相關，與低纖維飲食之關聯性不若大腸癌明確（A✗）；肝癌主要危險因子為病毒性肝炎感染（B、C型肝炎）、黃麴毒素等，與低纖維飲食關聯性不大（B✗）；乳癌主要危險因子與荷爾蒙（如雌激素暴露時間）、遺傳基因（BRCA）等相關，與低纖維飲食關聯性不若大腸癌明確（D✗）。"},{n:602,no:42,subj:"腫瘤血液",q:"下列何者不是接受周邊造血幹細胞移植治療的禁忌症？",opts:["A.血小板數目＞150,000/mm3者","B.有肺部或深部靜脈栓塞病史者","C.懷孕或哺乳中的婦女","D.自體免疫疾病者"],ans:[0],expl:"本題答案為A。血小板數目大於150,000/mm³屬正常範圍，代表骨髓造血功能尚屬健全，此為適合捐贈之條件而非禁忌症，為本題答案（題目問「下列何者不是」禁忌症）。有肺部或深部靜脈栓塞病史者，因造血幹細胞動員藥物（如G-CSF）可能增加血栓形成風險，通常列為捐贈禁忌症（B為禁忌症）；懷孕或哺乳中之婦女，考量動員藥物及捐贈過程對母體及胎兒／嬰兒之潛在風險，列為捐贈禁忌症（C為禁忌症）；自體免疫疾病病人因免疫調節狀態較不穩定，動員及捐贈過程風險相對較高，通常亦列為禁忌症（D為禁忌症）。"},{n:603,no:43,subj:"腫瘤血液",q:"化學治療最常見的副作用，下列何者正確？①便秘 ②白血球增加 ③紅血球減少 ④口腔黏膜破損 ⑤掉頭髮",opts:["A.①②⑤","B.①③④","C.②④⑤","D.③④⑤"],ans:[3],expl:"本題答案為D（③④⑤）。化學治療常見骨髓抑制導致③紅血球減少（貧血）；藥物毒性作用於快速分裂之口腔黏膜上皮細胞，導致④口腔黏膜破損（黏膜炎）；毛囊細胞同屬快速分裂細胞，易受化療藥物影響造成⑤落髮，此三者皆為化學治療極常見之副作用，選③④⑤＝D（本題答案）。化療較常引起腹瀉而非便秘（雖部分藥物或止吐劑可能誘發便秘，但非最典型、最常見之副作用，①較不符合此題脈絡）；化學治療導致骨髓抑制，白血球應為「減少」而非增加，此選項方向與化療藥理作用相反（②錯誤）。"},{n:604,no:44,subj:"其他",q:"18歲女大生因玩煙火，導致左手有部分燒痂到急診求診，對燒傷部位的立即護理處置，下列何者正確？",opts:["A.將左手浸生理食鹽水中","B.抬高左手減輕水腫","C.局部用藥減輕感染","D.手術切開水泡和清創"],ans:[0],expl:"本題答案為A。燒傷傷口的立即（急診）處置原則，是以生理食鹽水或潔淨冷水沖洗、浸泡傷口，以降溫、減少熱能持續傷害深層組織、並緩解疼痛，為燒傷急救之標準第一步驟，為本題答案。抬高患肢有助減輕水腫，屬於燒傷後續照護措施之一，但並非「立即」處置的優先步驟（B✗，應先降溫處理）；局部用藥（如外用藥膏）通常於傷口初步評估、清創處理後才依醫囑使用，並非到院時立即採取之處置，且過早塗抹可能干擾傷口評估（C✗）；手術性清創及水泡處理屬於後續確定性治療範疇，並非急診立即處置措施（D✗）。"},{n:605,no:45,subj:"其他",q:"皮膚表皮破皮並看得到皮下脂肪組織，且傷口出現黏液或滲出物，可能為第幾期壓傷？",opts:["A.第一期","B.第二期","C.第三期","D.無法分期"],ans:[2],expl:"本題答案為C。依NPUAP壓力性損傷分期標準，第三期壓傷之特徵為全層皮膚缺損，可見皮下脂肪組織，但尚未暴露肌肉、肌腱或骨骼，且可能合併滲出液或黏液分泌物，此描述與題目所述完全相符，為本題答案。第一期壓傷僅表現為皮膚完整但出現不會反白之紅斑，並無皮膚破損及皮下脂肪暴露（A✗）；第二期壓傷為部分皮層缺損，可能表現為淺層潰瘍或水泡，但「不會」看見皮下脂肪組織，此為與第三期之重要鑑別點（B✗）；「無法分期」通常適用於傷口表面被壞死組織或痂皮覆蓋、無法確認實際深度之情形，與此題已可清楚辨識皮下脂肪組織之描述不符（D✗）。"},{n:606,no:46,subj:"其他",q:"有關皮膚惡性腫瘤病人的護理措施，下列何者錯誤？",opts:["A.病灶處需要適當的加壓，以減少疼痛","B.教導每日檢查皮膚，觀察病灶及其變化","C.儘量減少曝曬於陽光下，並須執行適當的防曬措施","D.告知身上的痣若出現潰瘍、滲液、痛癢時，則需就醫"],ans:[0],expl:"本題答案為A。皮膚惡性腫瘤病灶處並無需要「加壓」以減少疼痛之標準護理措施，此非皮膚癌照護常規內容，敘述不當，為本題答案（A✗，題目問「何者錯誤」）。教導病人每日自我檢查皮膚，觀察既有痣或病灶是否出現變化，有助早期發現皮膚癌病變（B✓）；減少陽光曝曬並落實防曬措施，為預防皮膚癌（尤其黑色素瘤）復發或新病灶產生之重要衛教（C✓）；痣若出現潰瘍、滲液、疼痛搔癢等變化，屬警示徵象（ABCDE準則相關表現），應提醒病人及早就醫評估（D✓）。"},{n:607,no:47,subj:"其他",q:"有關燒傷的病生理變化，下列何者錯誤？",opts:["A.燒傷48小時內，應密切監測鉀離子，以避免高血鉀影響心臟功能及危及生命","B.燒傷初期病人會出現少尿、尿液濃縮及尿比重增加","C.大範圍燒傷面積病人常在燒傷後72小時出現壓力性潰瘍","D.在燒傷後48～72小時，病人會出現血比容升高、血鈉上升以及尿量減少"],ans:[3],expl:"本題答案為D。燒傷後約48～72小時，體液會逐漸由組織間隙再回流入血管（液體再吸收期／利尿期開始），此階段血比容通常會逐漸「下降」（而非持續上升）、且隨著循環容積回升，尿量應「增加」（而非減少）；「持續呈現血比容上升、尿量減少」之描述較符合燒傷「初期（前24～48小時）」液體滲漏期的表現，而非48～72小時後的病生理變化，此敘述時序有誤，為本題答案（D✗，題目問「何者錯誤」）。燒傷後細胞受損釋出大量鉀離子，48小時內應密切監測血鉀以避免高血鉀影響心臟功能，此為正確之監測重點（A✓）；燒傷初期因體液滲漏至組織間隙，血管內容積不足，會出現少尿、尿液濃縮及尿比重增加等腎前性表現（B✓）；大面積燒傷病人因血流重新分布及長時間臥床受壓，常於燒傷後72小時左右出現壓力性潰瘍（Curling氏潰瘍屬腸胃道壓力性潰瘍的一種型態，泛指燒傷病人易合併壓力性潰瘍之風險），此為公認之燒傷併發症（C✓）。"},{n:608,no:48,subj:"其他",q:"有關過敏反應護理指導的敘述，下列何者錯誤？",opts:["A.建議關閉門窗以隔離髒空氣及過敏原，並打開空調讓室內的空氣循環","B.建議使用填充家具，如布沙發、椰子墊、草蓆、榻榻米等","C.定期清理住家環境，且不使用噴霧清潔劑","D.避免飼養寵物，或服用容易引起過敏的食物"],ans:[1],expl:"本題答案為B。布沙發、椰子墊、草蓆、榻榻米等填充式或纖維編織家具容易堆積塵蟎及過敏原，對於過敏體質病人應「避免使用」而非建議使用，此敘述方向有誤，為本題答案（B✗，題目問「何者錯誤」）。適度關閉門窗以減少戶外過敏原（如花粉）進入室內，並搭配空調過濾及循環系統維持室內空氣品質，為合理建議（A✓）；定期清理居家環境並避免使用噴霧型清潔劑（可能刺激呼吸道誘發過敏症狀），為合理衛教（C✓）；避免飼養易誘發過敏之寵物，並留意可能引起過敏的食物種類，為基本過敏原迴避原則（D✓）。"},{n:609,no:49,subj:"其他",q:"有關愛滋病病人護理指導的敘述，下列何者正確？",opts:["A.鼓勵多食用生菜，以促進維生素之攝取","B.勿與剛接種疫苗或受傳染病感染的家人接觸","C.服用Zidovudine反轉錄酶抑制劑，需注意末梢神經痛的症狀","D.勿握手、擁抱、共用餐具、共用浴池，以避免傳染他人"],ans:[1],expl:"本題答案為B。愛滋病病人因免疫功能低下，應避免與剛接種活性減毒疫苗（可能有病毒排出風險）或正處於傳染病感染期的家人密切接觸，以降低伺機性感染或續發感染風險，為本題答案。生菜等未經高溫烹調之食材可能帶有病原菌污染風險，免疫功能低下病人應避免生食，「鼓勵多食用生菜」之建議並不適當（A✗）；Zidovudine（AZT）主要且最典型之藥物副作用為骨髓抑制（貧血、嗜中性白血球低下），周邊神經病變則較常見於Stavudine、Didanosine等其他抗反轉錄病毒藥物，此敘述將副作用誤植於Zidovudine（C✗）；愛滋病病毒主要透過血液、體液及性接觸傳染，日常握手、擁抱、共用餐具或浴池等一般生活接觸並不會造成傳染，此建議係基於過時或錯誤的傳染途徑認知，反而可能造成病人遭受不必要的社會排斥與汙名化，並不恰當（D✗）。"},{n:610,no:50,subj:"其他",q:"接觸性皮膚炎病人因搔癢不適至門診治療，下列護理指導何者錯誤？",opts:["A.屬於過敏反應","B.避免接觸已知的過敏原","C.經常用肥皂清潔以緩解過敏症狀","D.服用抗組織胺類藥物時須避免開車"],ans:[2],expl:"本題答案為C。接觸性皮膚炎病人之發炎皮膚屏障功能已受損，經常使用肥皂清潔反而會進一步洗去皮膚表面油脂、破壞皮膚屏障，加重乾燥及搔癢不適，並非緩解症狀之適當做法，為本題答案（C✗，題目問「何者錯誤」）。接觸性皮膚炎屬於皮膚對特定物質產生的過敏（或刺激性）發炎反應，此分類敘述正確（A✓）；辨識並避免再次接觸已知過敏原，是接觸性皮膚炎最核心的處置原則（B✓）；服用抗組織胺藥物（尤其第一代／具鎮靜作用者）可能引起嗜睡，應提醒病人服藥期間避免開車或操作精密機械，屬標準用藥安全衛教（D✓）。"},{n:611,no:51,subj:"其他",q:"下列何者為與第一型立即性過敏反應有密切關聯的免疫球蛋白？",opts:["A.IgA","B.IgE","C.IgG","D.IgM"],ans:[1],expl:"本題答案為B。第一型（立即型）過敏反應之核心機轉是IgE抗體與肥大細胞／嗜鹼性球表面受體結合，當再次接觸過敏原時發生交叉連結，促使組織胺等發炎介質釋放，此為與第一型過敏反應密切相關之免疫球蛋白，為本題答案。IgA主要分布於黏膜表面分泌液中，負責黏膜局部免疫防禦，與第一型過敏反應機轉關聯性不大（A✗）；IgG為體內含量最多之免疫球蛋白，與第二型（細胞毒殺型）及第三型（免疫複合體型）過敏反應較相關（C✗）；IgM為初次免疫反應最早產生之抗體，主要角色為活化補體系統，與第一型過敏反應機轉關聯性不大（D✗）。"},{n:612,no:52,subj:"呼吸系統",q:"有關促進胸腔手術術後病人咳嗽的護理措施，下列何者最適當？",opts:["A.深呼吸後應至少隔6小時再行咳嗽","B.咳嗽前2小時給止痛劑","C.咳嗽前喝至少500 mL的開水","D.咳嗽前請病人坐起且以枕頭壓住傷口"],ans:[3],expl:"本題答案為D。指導病人咳嗽前先採坐姿（利用重力協助肺部擴張及痰液排出），並以枕頭或雙手輕壓傷口部位（splinting），可提供傷口支托、減輕咳嗽時的疼痛及張力，同時促進有效咳嗽排痰，為本題答案。深呼吸及咳嗽運動應「頻繁」執行（如每1～2小時一次），以預防肺擴張不全及痰液蓄積，「至少隔6小時」之間隔過長，並不適當（A✗）；止痛劑給予時機應與預定活動（如咳嗽、下床）時間較接近搭配（如提前30分鐘至1小時），以求藥效高峰與活動時間吻合，「提前2小時」之間隔安排並非標準建議（B✗）；咳嗽前並無需常規大量攝取500 mL開水之標準做法，此非建立有效咳嗽之關鍵措施（C✗）。"},{n:613,no:53,subj:"呼吸系統",q:"有關肺水腫（pulmonary edema）的敘述，下列何者正確？",opts:["A.為肋膜過度積水","B.常為左心衰竭所引起","C.應提供增加前負荷之處置","D.鼓勵病人下肢抬高增加靜脈血液回流"],ans:[1],expl:"本題答案為B。肺水腫最常見的成因是左心衰竭：左心室收縮或舒張功能不良，導致肺微血管靜水壓上升，液體滲漏至肺泡及肺間質，此為肺水腫核心病生理機轉，為本題答案。肺水腫是液體積聚於肺泡及肺間質，與肋膜腔積水（肋膜過度積水，屬另一獨立病理狀況）並不相同，此敘述將兩者混淆（A✗）；肺水腫的治療原則是「降低」（而非增加）心臟前負荷，如使用利尿劑、硝酸鹽類藥物，此敘述方向相反（C✗）；下肢抬高會增加靜脈回流、進一步加重心臟前負荷及肺充血，肺水腫病人建議採半坐臥姿並使下肢「下垂」以減少靜脈回流，此敘述方向相反（D✗）。"},{n:614,no:54,subj:"呼吸系統",q:"有關移除胸管的護理措施，下列何者錯誤？",opts:["A.水封瓶液面，隨呼吸上下浮動，表示可拔除胸管","B.拔管前，應提前給予止痛劑","C.拔管時，應請病人深吸氣後閉氣再拔出胸管","D.拔管後，應以無菌凡士林紗布覆蓋傷口"],ans:[0],expl:"本題答案為A。水封瓶內水柱液面隨呼吸上下波動（tidaling），代表引流系統與肋膜腔之間仍存在壓力連通，屬於系統功能正常運作之表現，但「並非」判斷可拔除胸管的依據；胸管移除的評估重點在於引流量顯著減少（如24小時少於100～200 mL）、無持續性漏氣，且經影像確認肺部已完全復張，此敘述將水柱波動與拔管時機混為一談，並不正確，為本題答案（A✗，題目問「何者錯誤」）。拔管過程會造成疼痛，提前給予止痛藥物可提升病人舒適及配合度，為合理處置（B✓）；拔管瞬間請病人深吸氣後閉氣（類似Valsalva操作），可避免空氣經由拔管傷口進入肋膜腔造成氣胸，為標準拔管技術（C✓）；拔管後立即以無菌凡士林紗布密封傷口，可形成不透氣屏障，防止空氣經傷口滲入肋膜腔，為標準傷口照護原則（D✓）。"},{n:615,no:55,subj:"呼吸系統",q:"有關慢性支氣管炎病人出院護理指導的敘述，下列何者正確？",opts:["A.限制水分的攝取量","B.增加醣類的攝取量","C.戒菸或避免二手菸","D.避免注射流感疫苗"],ans:[2],expl:"本題答案為C。戒菸或避免暴露於二手菸環境，是慢性支氣管炎病人最核心且效益最明確之出院衛教重點，可延緩肺功能持續惡化，為本題答案。慢性支氣管炎病人應「鼓勵」（而非限制）攝取足夠水分，以利痰液稀釋、利於咳出，限水之建議方向有誤（A✗）；過量醣類攝取於代謝過程中會產生較多二氧化碳，可能加重原已受損之呼吸功能負擔，慢性支氣管炎病人飲食原則通常建議適度調整醣類比例而非「增加」醣類攝取，此建議並不適當（B✗）；每年接種流感疫苗可降低慢性呼吸道疾病病人因呼吸道感染而誘發急性惡化之風險，應「鼓勵」而非「避免」接種，此敘述方向相反（D✗）。"},{n:616,no:56,subj:"呼吸系統",q:"評估慢性阻塞性肺病（COPD）病人的呼吸道阻塞嚴重度，下列何者為最重要的評估指標？",opts:["A.用力肺活量（FVC）","B.第一秒鐘用力呼氣容積（FEV1）","C.肺活量（VC）","D.全肺容量（TLC）"],ans:[1],expl:"本題答案為B。第一秒鐘用力呼氣容積（FEV1，及FEV1/FVC比值）是評估慢性阻塞性肺病呼吸道阻塞嚴重程度最重要、最具代表性的肺功能指標，亦為GOLD分期系統之核心依據，為本題答案。用力肺活量（FVC）主要反映肺容積大小，並非評估「阻塞」嚴重度之最佳單一指標（A✗）；肺活量（VC）同樣主要反映肺容積，較無法精確反映氣流阻塞程度（C✗）；全肺容量（TLC）反映肺部總氣體容積（COPD病人常因空氣滯留而TLC增加），但並非評估氣流阻塞嚴重度之標準核心指標（D✗）。"},{n:617,no:57,subj:"呼吸系統",q:"李先生為氣喘病人，目前使用Aminophylline靜脈輸注溶液，護理師得知李先生血清中的Theophylline濃度為12 μg/mL，此時最適當的護理措施為何？",opts:["A.立即告知主治醫師檢驗報告的數值","B.繼續使用Aminophylline輸注溶液","C.將輸注溶液更換為不含Aminophylline的點滴溶液","D.聯絡檢驗部門確認數值是否有誤"],ans:[1],expl:"本題答案為B。Theophylline（茶鹼）之治療血中濃度範圍通常界定為10～20 μg/mL（部分現行文獻建議更保守之5～15 μg/mL範圍），濃度12 μg/mL仍落於治療範圍內，屬安全有效之濃度，此時應「維持現行治療」，持續使用Aminophylline靜脈輸注溶液即為合理處置，為本題答案。濃度落於治療範圍內，並非需要「立即」特別告知醫師之異常數值（雖仍應依常規記錄回報，但非本題情境下最適當之「處置」重點）（A✗，非最適當）；濃度屬正常治療範圍，並無立即停用之必要，「更換為不含Aminophylline之溶液」並不適當（C✗）；數值落於預期治療範圍內，並無明顯異常需懷疑檢驗誤差，「聯絡確認數值是否有誤」並非此情境下最適當之處置（D✗）。"},{n:618,no:58,subj:"呼吸系統",q:"有關急性呼吸窘迫症候群（ARDS）病生理變化的敘述，下列何者正確？",opts:["A.微血管細胞膜的通透性增加，導致肺水腫","B.肺泡過度擴張導致呼吸道阻力下降","C.肺泡表面張力素過度分泌，導致肺泡過度撐大","D.支氣管擴張導致進入肺的氣體流量下降"],ans:[0],expl:"本題答案為A。急性呼吸窘迫症候群（ARDS）核心病生理機轉，是肺泡微血管膜因瀰漫性發炎反應導致通透性增加，使富含蛋白質之液體滲漏進入肺泡腔，造成非心因性肺水腫，此為ARDS之定義性病理機轉，為本題答案。ARDS特徵是肺泡塌陷（而非過度擴張）及肺順應性下降，並非呼吸道阻力下降，此敘述機轉方向有誤（B✗）；ARDS是因肺泡表面張力素「功能不足或分泌減少」，導致肺泡表面張力增加、肺泡塌陷，並非表面張力素過度分泌造成肺泡過度撐大，此敘述方向相反（C✗）；ARDS主要病灶在於肺泡及肺間質病變，並非支氣管管徑改變所致之氣流異常，此敘述機轉描述有誤（D✗）。"},{n:619,no:59,subj:"呼吸系統",q:"肺擴張不全病人的身體評估，下列發現何者正確？",opts:["A.視診氣管明顯向健側擴張","B.觸診患側觸覺震顫明顯變大","C.叩診患側有明顯濁音出現","D.聽診患側呼吸音變大"],ans:[2],expl:"本題答案為C。肺擴張不全（atelectasis）因塌陷部位含氣量減少、組織密度相對增加，叩診時會呈現濁音，此為重要理學檢查發現，為本題答案。肺擴張不全因患側肺容積縮小，氣管會向「患側」偏移（而非健側），此敘述方向有誤（A✗）；塌陷肺組織因含氣量減少，觸覺震顫應「減弱」而非增強，此敘述方向有誤（B✗）；塌陷部位因氣體交換減少，聽診呼吸音應「減弱或消失」，並非變大，此敘述方向有誤（D✗）。"},{n:620,no:60,subj:"泌尿系統",q:"王先生因慢性腎臟病正服用血管收縮素轉化酶抑制劑（ACEI），有關ACEI的敘述，下列何者錯誤？",opts:["A.可預防蛋白尿之產生","B.易有乾咳副作用","C.可能導致低血壓","D.可能導致低血鉀"],ans:[3],expl:"本題答案為D。血管收縮素轉化酶抑制劑（ACEI）之作用機轉會減少醛固酮分泌，進而降低腎臟排鉀能力，臨床上ACEI較常引起「高血鉀」而非低血鉀，此為使用ACEI時須密切監測之重要電解質風險，此敘述方向有誤，為本題答案（D✗，題目問「何者錯誤」）。ACEI可降低腎絲球內壓、減少蛋白質漏出，具腎臟保護、預防蛋白尿之效果，為慢性腎臟病常用藥物（A✓）；ACEI因抑制Bradykinin分解代謝，可能堆積於呼吸道引發乾咳，為其典型副作用（B✓）；ACEI具血管擴張作用，可能導致血壓下降甚至姿勢性低血壓（C✓）。"},{n:621,no:61,subj:"泌尿系統",q:"有關腎臟結石常見的臨床症狀，下列何者錯誤？",opts:["A.後背腰部疼痛","B.頻尿、尿急","C.噁心、嘔吐","D.寒顫、發燒"],ans:[1],expl:"本題答案為B。頻尿、尿急等膀胱刺激症狀，主要與結石位置接近膀胱輸尿管交接處或已進入膀胱有關，並非所有腎臟結石病人皆會出現之普遍性症狀，此敘述作為「常見臨床症狀」過於一概而論，為本題答案（B✗，題目問「何者錯誤」）。腎臟結石典型表現為患側後背腰部絞痛或鈍痛，為最常見之主訴（A✓）；結石刺激或合併泌尿道感染，常伴隨噁心嘔吐等自律神經反應（C✓）；若合併感染，可能出現寒顫、發燒等全身性感染徵象（D✓）。"},{n:622,no:62,subj:"泌尿系統",q:"有關膀胱結石的治療與照護措施，下列何者錯誤？",opts:["A.建議使用體外震波碎石術治療，較不具侵入性","B.結石成分為尿酸時，指導避免食用內臟、香菇等","C.預防感染通常會先用廣效性抗生素","D.術後鼓勵多喝水並監測輸出入量與尿液顏色、氣味等"],ans:[0],expl:"本題答案為A。體外震波碎石術（ESWL）主要適用於腎臟及輸尿管結石，對於膀胱結石因結石體積、活動度及膀胱內特殊解剖環境等因素，其治療效果通常不如經尿道膀胱鏡碎石術（cystolitholapaxy）等其他術式，並非膀胱結石的優先建議選項，此敘述並不恰當，為本題答案（A✗，題目問「何者錯誤」）。尿酸結石病人應避免攝取高普林食物，如內臟、香菇等，以降低尿酸生成、預防結石復發，為正確飲食指導（B✓）；泌尿道結石處置過程中，為預防感染，臨床上常會考慮預防性使用廣效性抗生素（C✓）；術後鼓勵多喝水、監測輸出入量及尿液顏色氣味變化，有助沖刷泌尿道、及早發現感染或出血徵象（D✓）。"},{n:623,no:63,subj:"泌尿系統",q:"有關前列腺肥大與前列腺癌的敘述，下列何者錯誤？",opts:["A.排尿困難、頻尿與尿瀦留等是常見症狀","B.前列腺癌與雄性素有關，好發於前列腺中葉","C.前列腺肥大經常會合併膀胱結石、尿路感染","D.直腸指診和前列腺特異抗原是篩檢的診斷方法"],ans:[1],expl:"本題答案為B。前列腺肥大（BPH）主要好發於前列腺「中葉（移行區／transition zone）」，而前列腺癌則多好發於前列腺「周邊區（peripheral zone）」，此敘述將前列腺癌好發部位誤植為中葉，與實際解剖好發部位相反，為本題答案（B✗，題目問「何者錯誤」）。排尿困難、頻尿及尿瀦留為前列腺肥大及前列腺癌因阻塞尿道所共有之常見症狀（A✓）；前列腺肥大因排尿不順、尿液滯留，確實較易併發膀胱結石及泌尿道感染（C✓）；直腸指診（DRE）合併前列腺特異抗原（PSA）檢測，為目前臨床上前列腺癌篩檢之標準工具（D✓）。"},{n:624,no:64,subj:"泌尿系統",q:"有關腎臟癌的敘述，下列何者正確？",opts:["A.以腎細胞癌（renal cell carcinoma）最常見","B.最常轉移部位是腦部","C.腹脇部疼痛是最早期的症狀","D.抽菸與暴露在汞是可能的致病因"],ans:[0],expl:"本題答案為A。腎細胞癌（renal cell carcinoma）是原發性腎臟惡性腫瘤中最常見的組織型態（約占八至九成），為本題答案。腎細胞癌最常見的轉移部位是「肺臟」，其次為骨骼、肝臟，腦部轉移相對少見，此敘述轉移部位有誤（B✗）；腎細胞癌早期常無明顯症狀（有「沉默腫瘤」之稱），腹脇部疼痛、血尿、可觸摸腫塊等典型三症狀通常於疾病「較晚期」才出現，並非最早期症狀，此敘述時序有誤（C✗）；吸菸為腎細胞癌公認之危險因子，但常見相關職業／環境暴露物質是鎘、石綿等，「汞」並非腎細胞癌之典型相關致病暴露因子，此敘述配對有誤（D✗）。"},{n:625,no:65,subj:"泌尿系統",q:"有關腎臟癌治療和照護的敘述，下列何者錯誤？",opts:["A.根除性腎切除是初期最有效的治療方式","B.放射線療法可有效緩和骨頭轉移的病變","C.化學治療和荷爾蒙療法會有顯著的效果","D.術後需監測輸出入量與維持尿量30～50 mL/hour"],ans:[2],expl:"本題答案為C。腎細胞癌對傳統化學治療及荷爾蒙療法之反應率普遍不佳，療效有限，並非顯著有效之治療方式，此敘述與現行實證不符，為本題答案（C✗，題目問「何者錯誤」）。對於局限性腎細胞癌，根除性腎切除術仍是初期最有效、具治癒潛力之標準治療方式（A✓）；放射線治療雖非腎細胞癌之主要治癒性治療手段，但對於骨頭轉移病灶造成之疼痛，仍具良好的緩和性治療效果（B✓）；腎臟切除術後應密切監測輸出入量，並維持尿量在合理範圍（如30～50 mL/hour以上），以評估腎功能及避免腎前性損傷（D✓）。"},{n:626,no:66,subj:"泌尿系統",q:"有關多囊性腎病的敘述，下列何者錯誤？",opts:["A.是一種遺傳性疾病","B.大多數在青春期發病","C.常見症狀為後腰部鈍痛","D.通常可由腎超音波確認囊腫"],ans:[1],expl:"本題答案為B。多囊性腎病（以體染色體顯性遺傳型為主）好發年齡層通常於「成年期」（約30～50歲）才逐漸出現臨床症狀，並非好發於青春期，此敘述年齡層有誤，為本題答案（B✗，題目問「何者錯誤」）。多囊性腎病屬於遺傳性疾病，主要以體染色體顯性遺傳方式傳遞（A✓）；隨腎臟囊腫逐漸增大，常見後腰部鈍痛或悶脹感為典型症狀（C✓）；腎臟超音波檢查為診斷多囊性腎病、確認囊腫存在及分布之標準且常用之影像學工具（D✓）。"},{n:627,no:67,subj:"泌尿系統",q:"下列何者可能出現膀胱容量增加？",opts:["A.膀胱發炎","B.膀胱纖維化","C.上運動神經元受損","D.慢性膀胱出口阻塞"],ans:[3],expl:"本題答案為D。慢性膀胱出口阻塞（如攝護腺肥大長期未處理）會使膀胱長期對抗阻力收縮，逐漸導致逼尿肌代償性肥厚、失代償後膀胱壁擴張，膀胱容量隨病程進展而增加，此為本題答案。膀胱發炎因黏膜受刺激，通常在較小尿量時即產生強烈尿意，功能性容量反而「減少」，並非增加（A✗）；膀胱纖維化會使膀胱壁失去彈性、順應性下降，膀胱容量通常「縮小」（攣縮膀胱），並非增加（B✗）；上運動神經元受損（如脊髓損傷病灶在薦髓以上）常導致痙攣性（反射性）膀胱，特徵為小容量、不自主收縮，並非容量增加，容量增加較常見於下運動神經元受損所致之無張力性膀胱（C✗）。"},{n:628,no:68,subj:"內分泌系統",q:"有關甲狀腺風暴的敘述，下列何者錯誤？",opts:["A.病人臨床檢驗結果出現血中游離甲狀腺素（free T4）與TSH上升","B.評估病人是否出現發燒、心跳過速、脫水及暴躁不安之徵象","C.依醫囑給予β-腎上腺素阻斷劑（Propranolol），以降低心搏速率","D.依醫囑給予抑制甲狀腺素合成與釋放藥物，如：Methimazole (Tapazole)"],ans:[0],expl:"本題答案為A。甲狀腺風暴屬於甲狀腺功能極度亢進之危急狀態，血中游離T4（甲狀腺素）會顯著上升，但依負回饋機轉，腦下垂體分泌之TSH應呈現「受抑制而下降」，並非與T4同步上升，此敘述TSH變化方向有誤，為本題答案（A✗，題目問「何者錯誤」）。發燒、心搏過速、脫水及躁動不安為甲狀腺風暴典型的高代謝及交感神經興奮表現，應密切評估（B✓）；Propranolol等β-腎上腺素阻斷劑可用以緩解甲狀腺風暴之交感神經興奮症狀，包括降低心搏速率，為標準治療藥物之一（C✓）；Methimazole可抑制甲狀腺內過氧化酶，阻斷甲狀腺素之合成與釋放，為治療甲狀腺功能亢進及風暴之標準用藥（D✓）。"},{n:629,no:69,subj:"內分泌系統",q:"有關庫欣氏症候群（Cushing's syndrome）的飲食指導，下列何者錯誤？",opts:["A.高鈣","B.高鉀","C.低熱量","D.低蛋白"],ans:[3],expl:"本題答案為D。庫欣氏症候群因皮質醇長期過量，會促進蛋白質異化代謝、加速肌肉組織分解流失，飲食上應建議「高蛋白」飲食以補充流失之蛋白質，並非低蛋白飲食，此敘述方向有誤，為本題答案（D✗，題目問「何者錯誤」）。皮質醇會抑制腸道鈣質吸收並增加骨質流失，故建議補充高鈣飲食以預防骨質疏鬆（A✓）；因礦物皮質素作用增強，病人常伴隨低血鉀，故建議補充高鉀飲食（B✓）；皮質醇會造成體脂肪重新分布及水鈉滯留，體重增加、中心性肥胖常見，建議採低熱量飲食協助體重管理（C✓）。"},{n:630,no:70,subj:"內分泌系統",q:"有關抗利尿激素分泌不當症候群（SIADH）的護理指導，下列何者錯誤？",opts:["A.須限制液體，故每天液體攝入不超過500 mL","B.向病人說明使用四環素主要目的是為了預防感染","C.跟病人解釋頭部最好保持平躺，以防腦水腫","D.教導病人攝取高纖、含鈉的食物，以改善便秘"],ans:[1],expl:"本題答案為B。四環素衍生物Demeclocycline於SIADH之臨床使用目的，是利用其藥理特性拮抗抗利尿激素於腎小管的作用，誘發類似腎因性尿崩症之效果以促進體內游離水排出，並非用於預防感染，此敘述用藥目的有誤，為本題答案（B✗，題目問「何者錯誤」）。限水為SIADH最核心之治療原則，透過減少水分攝取以協助矯正低血鈉狀態，每日液體攝入常限制於500～1000 mL左右範圍（A✓）；SIADH合併低血鈉可能造成腦水腫風險，衛教病人採頭部平躺姿勢，避免頭部過度抬高或活動加重腦部灌流變化，屬合理照護考量（C✓）；教導攝取高纖及含鈉食物，除改善因限水或活動減少導致之便秘外，適度增加鈉攝取亦有助改善低血鈉狀態（D✓）。"},{n:631,no:71,subj:"內分泌系統",q:"有關糖尿病酮酸中毒（DKA）病人的呼吸特徵，下列何者正確？",opts:["A.深、快、有果香味","B.淺、慢、有尿騷味","C.深、慢、有果香味","D.淺、快、有尿騷味"],ans:[0],expl:"本題答案為A。糖尿病酮酸中毒（DKA）因體內代謝性酸中毒，身體代償性以深而快速的Kussmaul呼吸排出過多二氧化碳，同時因酮體（丙酮）經肺部呼出，使呼吸帶有特殊果香味，此為DKA之經典臨床表徵，為本題答案。其餘選項（呼吸淺慢有尿騷味、深慢有果香味、淺快有尿騷味）之呼吸深度、速度或氣味描述組合，皆與DKA典型的「深、快、果香味」呼吸特徵不符（B✗、C✗、D✗）。"},{n:632,no:72,subj:"內分泌系統",q:"有關高滲透壓高血糖狀態（HHS）的敘述，下列何者正確？",opts:["A.好發於第一型糖尿病人","B.呼吸加速且深度增加","C.檢驗血中呈現無或微量酮體","D.因無胰島素分泌導致高血糖"],ans:[2],expl:"本題答案為C。高滲透壓高血糖狀態（HHS）好發於第二型糖尿病人，因體內仍存有部分胰島素分泌，可抑制脂肪分解及酮體生成，故檢驗上血中酮體通常呈現無或僅微量，此為與DKA（酮體顯著升高）之重要鑑別點，為本題答案。HHS好發族群是「第二型」而非第一型糖尿病人，此敘述糖尿病分型有誤（A✗）；HHS因通常不合併顯著代謝性酸中毒，故不會出現Kussmaul深快呼吸，此為與DKA之另一鑑別點，敘述有誤（B✗）；HHS病人體內仍有部分胰島素分泌，並非完全無胰島素分泌，此與第一型糖尿病（胰島素絕對缺乏）之機轉不同，敘述有誤（D✗）。"},{n:633,no:73,subj:"內分泌系統",q:"有關甲狀腺功能亢進病人的飲食指導，下列何者正確？",opts:["A.低蛋白飲食","B.高碳水化合物飲食","C.低熱量飲食","D.高纖維飲食"],ans:[1],expl:"本題答案為B。甲狀腺功能亢進病人因代謝率顯著增加，熱量及各類營養素需求皆隨之上升，飲食原則建議提供「高熱量、高碳水化合物、高蛋白質」飲食以滿足代謝需求、避免體重過度流失，為本題答案。甲狀腺功能亢進病人因蛋白質分解代謝增加，飲食建議為「高蛋白」而非低蛋白，此敘述方向有誤（A✗）；甲狀腺功能亢進病人代謝率增加、熱量消耗大，飲食建議為「高熱量」而非低熱量，此敘述方向有誤（C✗）；高纖維飲食並非甲狀腺功能亢進飲食指導之核心重點，此疾病飲食調整之關鍵在於因應代謝率上升之熱量及巨量營養素補充，而非纖維攝取（D✗，非核心重點）。"},{n:634,no:74,subj:"內分泌系統",q:"有關糖化血色素的敘述，下列何者正確？",opts:["A.抽血前必須禁食12小時","B.可了解病人過去1年血糖控制情形","C.值<7%表示血糖控制不好","D.是指葡萄糖分子與血色素結合的一種反應"],ans:[3],expl:"本題答案為D。糖化血色素（HbA1c）是指血液中葡萄糖分子與紅血球內血色素發生非酵素性糖化結合後所形成的產物，其比例可反映一段期間內血糖控制情形，此為正確之定義敘述，為本題答案。糖化血色素檢測「不需要」空腹，可隨時抽血檢驗，此為其臨床應用優點之一，此敘述有誤（A✗）；糖化血色素主要反映抽血前約「2～3個月」（紅血球平均壽命約120天）之平均血糖控制情形，並非長達1年，此敘述時間範圍有誤（B✗）；糖化血色素數值「小於7%」通常代表血糖控制「良好」（多數治療指引以7%作為血糖控制目標上限），並非控制不良，此敘述方向恰好相反（C✗）。"},{n:635,no:75,subj:"內分泌系統",q:"下列何者在副甲狀腺功能低下病人會呈現陽性反應？",opts:["A.黎明現象（dawn phenomenon）","B.洛夫辛徵象（Rovsing's sign）","C.腔室症候群（compartment syndrome）","D.沃斯特克氏徵象（Chvostek's sign）"],ans:[3],expl:"本題答案為D。沃斯特克氏徵象（Chvostek's sign，輕敲顏面神經處誘發臉部肌肉抽動）為評估低血鈣（副甲狀腺功能低下常見表現）之經典理學檢查陽性徵象，為本題答案。黎明現象是指糖尿病人清晨時段因生長激素等升糖荷爾蒙分泌增加導致血糖上升之現象，與副甲狀腺功能低下無關（A✗）；洛夫辛徵象是評估闌尾炎（腹膜炎徵象）之理學檢查方法，與副甲狀腺功能低下無關（B✗）；腔室症候群是評估肢體筋膜腔內壓力過高（常見於骨折後）之臨床狀況，與副甲狀腺功能低下無關（C✗）。"},{n:636,no:76,subj:"骨骼肌肉",q:"有關骨折病人到院前急救處理原則，下列何者為最優先的處置？",opts:["A.給予疼痛處理","B.將骨折部位復位","C.固定骨折部位","D.給予熱敷處理"],ans:[2],expl:"本題答案為C。骨折病人到院前（現場）急救處理，最優先且核心之原則是先妥善固定骨折部位（如以夾板固定），以避免搬運過程中骨折斷端移動造成周邊神經血管及軟組織的二次傷害，為本題答案。疼痛處理雖為照護重點之一，但通常於初步固定、確保安全後才進行，並非到院前最優先步驟（A✗，非最優先）；未經專業評估及影像確認前，不應貿然嘗試將骨折部位復位，貿然復位可能加重神經血管損傷，並非到院前適當處置（B✗）；到院前現場急救原則並不包含熱敷處理，且熱敷可能加重局部腫脹發炎，並不適當（D✗）。"},{n:637,no:77,subj:"其他",q:"有關服用有機磷中毒的護理措施，下列何者錯誤？",opts:["A.維持呼吸道通暢","B.清醒者可進行催吐以減少有機磷之吸收","C.照顧病人時要穿戴防護措施，包括口罩、手套、隔離衣以及適當通風","D.使用Atropine靜脈注射時，維持病人心跳在60次／分鐘左右"],ans:[3],expl:"本題答案為D。文獻指出，有機磷中毒使用Atropine治療時，其滴定終點應著重於支氣管分泌物減少、支氣管痙攣緩解及呼吸道通暢等臨床表現，而非以特定心跳數值（如60次/分鐘）作為治療目標；事實上，心搏過速屬於Atropine發揮足量抗膽鹼作用後可能出現之預期反應（屬於菸鹼型作用表現，非Atropine之滴定指標），刻意將心跳「維持在60次/分鐘左右」之敘述並不符合臨床治療原則，為本題答案（D✗，題目問「何者錯誤」）。維持呼吸道通暢為有機磷中毒病人急救之首要原則（A✓）；對意識清醒、無禁忌症之病人，可視情況考慮催吐以減少毒物繼續吸收（B✓）；照護有機磷中毒病人時，醫護人員應穿戴適當防護裝備（口罩、手套、隔離衣）並維持環境通風，以避免自身經皮膚或吸入途徑續發中毒（C✓）。"},{n:638,no:78,subj:"心臟血管",q:"有關矯正休克病人低血壓的護理措施，下列何者錯誤？",opts:["A.應優先輸血以恢復全身循環血量","B.放置靜脈導管時應優先使用大管徑的導管","C.靜脈導管放置應優先考慮中心靜脈導管","D.密切注意病人血壓的變化"],ans:[0],expl:"本題答案為A。矯正休克病人低血壓之初期處置，通常以輸注等張晶體液（如生理食鹽水）擴充血管內容積為優先，血液製品之輸注則保留給確認有明顯失血（出血性休克）或血色素數值明顯偏低之情形，並非所有休克病人矯正低血壓時皆應「優先」輸血，此敘述過於一概而論，並不適當，為本題答案（A✗，題目問「何者錯誤」）。休克病人為利於快速大量輸液，應優先選用大管徑靜脈導管建立通路（B✓）；中心靜脈導管除可提供更穩定可靠之給液通路外，亦可監測中心靜脈壓等血液動力學參數，為休克處置常考慮之選項（C✓）；密切監測血壓變化，為評估休克矯正治療反應之基本且必要之持續性措施（D✓）。"},{n:639,no:79,subj:"其他",q:"有關敗血症病人臨床徵象與症狀的敘述，下列何者正確？",opts:["A.高血氧","B.呼吸變慢","C.尿量增加","D.代謝性酸中毒"],ans:[3],expl:"本題答案為D。敗血症因組織灌流不足、細胞轉為無氧代謝，乳酸堆積導致代謝性酸中毒，為敗血症重要之病生理表現及嚴重度評估指標之一，為本題答案。敗血症常合併組織氧合不良，病人多表現「低血氧」而非高血氧（A✗）；敗血症因發炎反應及代謝性酸中毒之代償機轉，呼吸速率通常會「加快」而非變慢（B✗）；敗血症因組織灌流不足、腎臟血流減少，尿量通常會「減少」（少尿）而非增加，此為敗血性休克重要之臨床警訊（C✗）。"},{n:640,no:80,subj:"神經系統",q:"有關狂牛症（mad cow disease）的敘述，下列何者錯誤？",opts:["A.又稱新型庫賈氏病，是與牛海綿狀腦病變（BSE）有關","B.主要因腦部奈格利氏小體（Negri body）發生基因突變","C.好發於較為年輕的族群，且其在臨床上的病程較長","D.此類病人通常以焦慮、妄想等精神症狀為最初的表現"],ans:[1],expl:"本題答案為B。狂牛症（新型庫賈氏病，vCJD）之致病機轉是體內正常普里昂蛋白（prion protein）發生構型異常變化並自我複製擴散，並非源於「奈格利氏小體（Negri body）」發生基因突變；奈格利氏小體是「狂犬病」病毒感染神經細胞後所形成之特徵性胞漿內包涵體，兩者屬於完全不同病原及疾病，此敘述將狂犬病病理特徵誤植於狂牛症，為本題答案（B✗，題目問「何者錯誤」）。新型庫賈氏病與牛海綿狀腦病變（BSE）之跨物種傳播有因果及流行病學關聯性，此為公認之病因學連結（A✓）；相較於散發型庫賈氏病好發於老年人，新型庫賈氏病（vCJD）好發族群較年輕，且臨床病程相對較長，此為兩者重要鑑別特徵（C✓）；新型庫賈氏病初期常以焦慮、憂鬱、妄想等精神行為症狀表現，與散發型庫賈氏病以快速認知功能退化為主之表現不同，此為vCJD重要之早期臨床特徵（D✓）。"},{n:641,no:1,subj:"神經系統",q:"有關病人心智狀態評估內容的敘述，下列何者錯誤？",opts:["A.可以利用簡易心智狀況量表（Mini Mental State Examination, MMSE）進行測試","B.可以依判斷力、定向感、記憶力、注意力、抽象思考能力、計算力進行評估","C.詢問病人有關「人、時、地」的確認能力，主要是評估注意力","D.詢問老年病人年輕時的基本資料如求學、求職等，主要是評估遠期記憶力"],ans:[2],expl:"本題答案為C。詢問病人「人、時、地」的定向確認能力，屬於評估「定向感（orientation）」而非注意力，此敘述將評估項目混淆，為本題答案（C✗，題目問「何者錯誤」）。MMSE是臨床上廣泛使用的簡易心智狀況篩檢工具，敘述正確（A✓）；判斷力、定向感、記憶力、注意力、抽象思考能力及計算力皆為心智狀態評估的核心構面，敘述正確（B✓）；詢問老年人年輕時期的求學求職等舊事，屬於評估「遠期（長期）記憶力」，敘述正確（D✓）。"},{n:642,no:2,subj:"神經系統",q:"有關病人已出現顱內壓升高的護理處置，下列敘述何者錯誤？",opts:["A.保持病人的頭頸在正中位置","B.抬高床頭30度","C.將抽痰、翻身拍背、擦澡等活動都集中一次完成","D.應注意體溫的控制及維持排便正常"],ans:[2],expl:"本題答案為C。顱內壓升高病人應將各項刺激性護理活動（抽痰、翻身拍背、擦澡等）分散進行、避免集中一次完成，因連續密集刺激會使顱內壓疊加上升，此敘述將原則說反，為本題答案（C✗，題目問「何者錯誤」）。頭頸維持正中位置有助靜脈回流暢通、避免顱內壓上升，敘述正確（A✓）；床頭抬高30度為顱內壓升高病人的標準擺位，敘述正確（B✓）；體溫過高會增加腦部代謝需求、便秘用力解便會誘發Valsalva效應，兩者皆須留意控制，敘述正確（D✓）。"},{n:643,no:3,subj:"神經系統",q:"有關腰椎椎間盤突出的敘述，下列何者錯誤？",opts:["A.俗稱為「下背疼痛」，此種疼痛會向下延伸至臀部、大腿後側及小腿","B.進行直舉腿試驗（straight leg raising test）可伸展到90度","C.進行Kernig sign試驗，病人將小腿往上伸展會覺得有阻力且感到劇烈疼痛","D.病人咳嗽、提重物、彎腰、長時間站立或坐著都會使疼痛加劇"],ans:[1],expl:"本題答案為B。直膝抬腿試驗（SLR）陽性反應是在膝關節伸直、抬腿角度約30～70度之間即誘發坐骨神經放射性疼痛，若病人可順利抬高至90度而無顯著疼痛，通常代表測試為「陰性」（不支持神經根壓迫），「可伸展到90度」之敘述與陽性測試的預期角度範圍不符，為本題答案（B✗，題目問「何者錯誤」）。腰椎椎間盤突出俗稱下背痛，疼痛可沿坐骨神經走向延伸至臀部、大腿後側及小腿，敘述正確（A✓）；Kernig氏徵象測試中，小腿上抬伸展時因神經根張力增加而感到阻力及劇痛，敘述正確（C✓）；咳嗽、提重物、彎腰、久站久坐等增加腹內壓或脊椎負荷的動作，皆會使神經根壓迫加劇疼痛，敘述正確（D✓）。"},{n:644,no:4,subj:"神經系統",q:"「走失」是阿茲海默氏症（Alzheimer's Disease）病人，那一期重要臨床表徵？",opts:["A.極早期","B.早期","C.中期","D.末期"],ans:[2],expl:"本題答案為C。走失（迷路、空間定向能力喪失）通常於阿茲海默氏症中期（中度失智）出現，此階段病人已出現明顯的空間定向障礙及執行功能退化，但仍具部分行動能力，故容易發生走失；早期病人定向感通常尚能維持，末期病人多已臥床或行動能力嚴重受限，走失風險反而降低，為本題答案。"},{n:645,no:5,subj:"神經系統",q:"有關巴金森氏症病人日常生活護理指導，下列何者錯誤？",opts:["A.行走時可使用助行器來維持平衡","B.衣服儘量選擇以魔鬼氈代替釦子","C.儘量多休息以減少活動產生震顫","D.馬桶可提高坐墊方便坐下或起身"],ans:[2],expl:"本題答案為C。巴金森氏症的震顫屬靜止性顫抖，其病人日常生活指導應「鼓勵維持適度規律活動」而非儘量多休息，過度休息不動反而不利於維持關節活動度及肌力，且此建議並非用以「減少震顫」的正確方式（震顫在活動時反而減輕），此敘述方向有誤，為本題答案（C✗，題目問「何者錯誤」）。使用助行器可增進步態穩定及平衡，敘述正確（A✓）；以魔鬼氈取代釦子可因應手部精細動作困難，利於病人自行穿脫衣物，敘述正確（B✓）；提高馬桶座墊高度可減少因肌肉僵硬、動作遲緩造成坐下起身的困難，敘述正確（D✓）。"},{n:646,no:6,subj:"神經系統",q:"有關頭部創傷之敘述，下列何者正確？",opts:["A.腦震盪是因外力造成暫時性的神經功能缺失，且腦組織有實質性的損傷","B.腦挫傷是因沒有腦組織的實質性損傷，所以受傷後常會出現腦震盪症候群","C.若出現鼻漏且確認是腦脊髓液，表示病人的硬腦膜受損","D.有鼻漏或耳漏的病人通常要儘快用抽吸管抽吸乾淨"],ans:[2],expl:"本題答案為C。腦脊髓液鼻漏經確認後，代表顱底骨折合併硬腦膜（dura mater）撕裂，使蜘蛛膜下腔與外界相通，此為臨床重要且正確的病理生理推論，為本題答案。腦震盪之定義即為外力造成的「暫時性」神經功能障礙，腦組織「並無」實質性（結構性）損傷，此為腦震盪與腦挫傷的關鍵鑑別點，此敘述將兩者混淆（A✗）；腦挫傷是腦組織「確實出現」實質性（結構性）損傷（瘀傷、出血點），敘述將有無實質損傷的定義說反（B✗）；出現腦脊髓液鼻漏或耳漏時，應以無菌紗布或棉墊「輕拭、任其自然流出」，不可用抽吸管抽吸或用力擤鼻，以免導致氣顱或增加逆行性顱內感染風險，此敘述處置方式有誤（D✗）。"},{n:647,no:7,subj:"神經系統",q:"有關腦波檢查的護理措施，下列何者錯誤？",opts:["A.說明檢查可診斷腦腫瘤","B.告知病人檢查前，需清洗頭髮","C.確認腦波室內備有足夠的點滴及氧氣","D.檢查後，留在頭皮及頭髮上的黏膠，可用丙酮清理"],ans:[0],expl:"本題答案為A。腦波檢查（EEG）主要偵測大腦皮質的電氣活動，用於診斷癲癇、腦炎、腦死判定等與電氣功能異常相關的疾病，對於腦腫瘤等「結構性」病灶，應以電腦斷層或磁振造影等影像學檢查為主要診斷工具，腦波僅可能呈現非特異性慢波等間接線索，並非診斷腦腫瘤的檢查，此敘述有誤，為本題答案（A✗，題目問「何者錯誤」）。檢查前需清洗頭髮，以確保頭皮電極貼附良好、訊號品質佳，敘述正確（B✓）；腦波誘發試驗（如過度換氣、閃光刺激）有誘發癲癇發作之風險，檢查室須備妥急救所需之點滴及氧氣，敘述正確（C✓）；檢查後頭皮殘留之導電膠，可用丙酮或其他專用清潔液清除，敘述正確（D✓）。"},{n:648,no:8,subj:"神經系統",q:"有關脊髓損傷導致「自主神經反射過度」的敘述，下列何者正確？",opts:["A.常發生於T6～T12受傷的病人","B.走路運動是可能的誘因","C.出現嚴重的高血壓及搏動性頭痛","D.心跳加速"],ans:[2],expl:"本題答案為C。自主神經反射過度（自主神經反射亢進）發作時，因血壓驟升會誘發嚴重高血壓及搏動性頭痛，此為典型且危急之臨床表現，為本題答案。自主神經反射過度好發於「T6（含）以上」脊髓損傷病人，並非侷限於T6～T12範圍，此敘述之損傷節段範圍不夠精確（A✗）；常見誘發因子為膀胱過度膨脹、腸道嵌塞等傷害受損平面以下之有害刺激，「走路運動」並非典型誘因（B✗）；因血壓上升觸發壓力感受器代償反應，會經由完整的迷走神經路徑造成反射性「心跳減慢（心搏過緩）」，而非心跳加速，此敘述方向相反（D✗）。"},{n:649,no:9,subj:"消化系統",q:"有關腸阻塞的臨床表徵，下列何者正確？①嘔吐 ②腹脹 ③腹部絞痛 ④腹瀉",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[0],expl:"本題答案為A（①②③）。①噁心嘔吐、②腹脹、③腹部絞痛皆為腸阻塞的典型臨床表徵（因腸內容物及氣體無法順利通過，導致近端腸道擴張及痙攣性收縮），選①②③＝A（本題答案）。腸阻塞因腸道內容物滯留無法排出，通常表現為「無法解便解氣」，而非腹瀉，④腹瀉並非腸阻塞的典型表徵（④錯誤）。"},{n:650,no:10,subj:"消化系統",q:"有關肝硬化引起腹水機轉之敘述，下列何者正確？",opts:["A.微血管靜力壓下降","B.血清白蛋白下降","C.血漿膠體滲透壓上升","D.有效循環血量上升"],ans:[1],expl:"本題答案為B。肝硬化病人因肝臟合成功能受損，血清白蛋白（albumin）製造減少，導致血漿膠體滲透壓下降，體液滲漏至腹腔形成腹水，此為腹水形成的核心機轉之一，為本題答案。肝硬化引起腹水的機轉是肝門靜脈壓力上升，使微血管靜力壓「上升」（而非下降），迫使液體滲出血管外，此敘述方向有誤（A✗）；白蛋白下降會使血漿膠體滲透壓「下降」（而非上升），液體因此更易滲出至腹腔，此敘述方向相反（C✗）；有效循環血量因液體滲漏至腹腔而「下降」（而非上升），此又進一步活化腎素-血管收縮素-醛固酮系統，加重水鈉滯留，此敘述方向相反（D✗）。"},{n:651,no:11,subj:"消化系統",q:"有關預防傾倒症候群（Dumping Syndrome）的護理指導，下列何者正確？",opts:["A.鼓勵病人少量多餐，進食時採半坐臥姿勢","B.鼓勵病人多進食富含水分的食物","C.治療先從增加碳水化合物飲食開始","D.建議採高脂肪、低蛋白、高糖食物"],ans:[0],expl:"本題答案為A。傾倒症候群衛教應指導病人少量多餐，並於進食後採半坐臥或平躺姿勢（而非直立坐姿）以延緩胃排空速度，減少高滲透壓食糜快速進入小腸引發症狀，此為標準護理指導，為本題答案。傾倒症候群病人應限制（而非鼓勵）攝取富含水分或液狀的食物，尤其應避免隨餐飲用大量湯水，以免加速胃排空，此建議方向有誤（B✗）；飲食原則應「限制」（而非增加）精緻碳水化合物及糖分攝取，以避免血糖劇烈波動誘發症狀，此敘述方向相反（C✗）；建議採高蛋白、高脂肪、「低糖」飲食（而非高糖飲食），以延緩胃排空並穩定血糖，此敘述糖分建議方向有誤（D✗）。"},{n:652,no:12,subj:"消化系統",q:"下列何者不是食道癌常見的臨床表徵？",opts:["A.吞嚥困難","B.食慾不振","C.腹痛","D.聲音沙啞"],ans:[2],expl:"本題答案為C。食道癌典型臨床表徵以吞嚥困難、體重減輕、食慾不振及聲音沙啞（腫瘤侵犯喉返神經）為主，腹痛並非其常見或典型的臨床表現，為本題答案（題目問「下列何者不是」常見表徵）。吞嚥困難是食道癌最典型且常見的初期表徵（A為常見表徵）；體重減輕、食慾不振為腫瘤消耗及吞嚥困難導致營養攝取不足的常見表現（B為常見表徵）；腫瘤侵犯喉返神經可導致聲音沙啞，為常見表徵之一（D為常見表徵）。"},{n:653,no:13,subj:"消化系統",q:"有關膈裂孔疝氣的敘述，下列何者正確？",opts:["A.造成原因是胃自橫膈的食道裂孔往上進入縱膈腔內","B.食道旁疝氣常出現反流症狀","C.滑動疝氣發生率占所有膈裂孔疝氣的20%","D.膈裂孔疝氣的原因為橫膈肌痙攣或腹內壓降低所致"],ans:[0],expl:"本題答案為A。膈裂孔疝氣是指部分胃經由橫膈的食道裂孔向上移位至胸腔（縱膈腔）內，此為其解剖學上的定義，為本題答案。食道旁型（paraesophageal）膈裂孔疝氣因食道與胃接合處位置相對正常、下食道括約肌功能較少受影響，故較「少」出現典型逆流症狀，反而滑動型（sliding type）疝氣因接合處上移，逆流症狀更為常見，此敘述有誤（B✗）；滑動型疝氣占所有膈裂孔疝氣病例中「絕大多數（約90～95%）」，並非僅占20%，此比例明顯低估（C✗）；膈裂孔疝氣的成因與橫膈肌「鬆弛無力」及腹內壓「升高」（而非降低）等因素有關，此敘述方向有誤（D✗）。"},{n:654,no:14,subj:"消化系統",q:"有關口腔炎的分類及臨床表徵，下列何者正確？",opts:["A.單純性疱疹常因細菌感染導致","B.缺乏維生素C會引發口角炎","C.念珠菌感染好發於口腔衛生習慣不好者","D.常有疼痛、吞嚥困難及口腔出血等症狀"],ans:[3],expl:"本題答案為D。口腔炎（口腔黏膜發炎）常見臨床表徵包括疼痛、吞嚥困難，嚴重時可能合併口腔黏膜出血，此敘述涵蓋口腔炎常見的核心臨床表現，為本題答案。單純性疱疹性口腔炎是由「病毒（單純疱疹病毒）」感染所致，並非細菌感染，此敘述病原體有誤（A✗）；缺乏維生素「B群（如B2、菸鹼酸）」較常與口角炎相關，維生素C缺乏典型上與壞血病（牙齦出血等）相關，此敘述維生素種類配對有誤（B✗）；念珠菌感染（鵝口瘡）好發於免疫力低下、使用抗生素或類固醇者、糖尿病病人及嬰幼兒／老年人，與口腔衛生習慣不佳的直接相關性並非其最主要好發因素，此敘述較不精確（C✗）。"},{n:655,no:15,subj:"腫瘤血液",q:"有關癌症病人貧血問題之敘述，下列何者錯誤？",opts:["A.全胃或脾臟切除手術會影響病人紅血球的生成","B.貧血症狀包括蒼白、心跳變慢、血壓上升、易疲倦等","C.鼓勵病人補充鐵質和含葉酸食物，如牛肉、綠色蔬菜","D.集中護理可讓病人獲得充分的休息"],ans:[1],expl:"本題答案為B。癌症相關貧血因紅血球攜氧量不足，身體會代償性增加心跳速率（心搏過速）以維持組織灌流，而非心跳變慢，且血壓通常無明顯上升，此敘述症狀方向有誤，為本題答案（B✗，題目問「何者錯誤」）。全胃切除術會使內生性因子（intrinsic factor）缺乏，影響維生素B12吸收；脾臟切除雖非紅血球生成器官，但脾臟病變或切除仍可能影響血球代謝與破壞平衡，兩者皆可能影響病人紅血球生成或代謝，敘述可接受（A✓）；鐵質及葉酸為紅血球生成之重要原料，牛肉、綠色蔬菜為其良好飲食來源，敘述正確（C✓）；集中護理可減少不必要的活動及能量消耗，讓貧血病人獲得充分休息，敘述正確（D✓）。"},{n:656,no:16,subj:"消化系統",q:"有關膽結石好發之高危險群，下列何者最不可能？",opts:["A.女性","B.肥胖者","C.口服避孕藥者","D.曾接受胃部手術者"],ans:[3],expl:"本題答案為D。膽結石好發之高危險群傳統上以「4F」（Female女性、Forty四十歲、Fertile多產、Fat肥胖）及口服避孕藥（雌激素影響膽汁膽固醇飽和度）等因子為主；曾接受胃部手術者與膽結石之直接相關性較不明確，並非傳統教材強調之典型高危險族群，為本題答案（題目問「何者最不可能」）。女性、肥胖者、口服避孕藥使用者皆為膽結石公認之典型高危險群（A、B、C皆為高危險群）。"},{n:657,no:17,subj:"消化系統",q:"有關心口灼熱（Heart Burn）的敘述，下列何者錯誤？",opts:["A.是下食道括約肌異常所致","B.病人常以痙攣痛或打結般形容此不適","C.進食後平躺可緩解症狀","D.是食道疾病的常見症狀"],ans:[2],expl:"本題答案為C。心口灼熱典型會因「平躺」姿勢加重（而非緩解）症狀，因平躺使胃內容物更易逆流至食道，建議進食後應維持坐姿或直立姿勢，此敘述方向恰好相反，為本題答案（C✗，題目問「何者錯誤」）。心口灼熱主因下食道括約肌功能異常（壓力過低或不當放鬆），敘述正確（A✓）；病人常將此不適感形容為胸骨後痙攣痛、燒灼感或如打結般的異物感，敘述符合臨床常見主訴描述（B✓）；心口灼熱是食道疾病（如胃食道逆流）最常見的典型症狀，敘述正確（D✓）。"},{n:658,no:18,subj:"骨骼肌肉",q:"有關腕隧道症候群的敘述，下列何者正確？",opts:["A.是指腕部正中神經受到壓迫所造成的現象","B.主要發生在男性，以50～60歲居多","C.臨床症狀是疼痛且腕部無法伸直","D.可藉由膨脹徵象（Bulge sign）與霍曼氏徵象（Homan's sign）確定診斷"],ans:[0],expl:"本題答案為A。腕隧道症候群是因腕部正中神經（median nerve）於腕隧道處受壓迫所致，此為其病理機轉定義，為本題答案。腕隧道症候群好發於「女性」，且好發年齡層與需重複腕部動作的職業族群相關，並非以50～60歲男性為主要好發族群，此敘述性別及年齡層方向有誤（B✗）；臨床症狀主要為正中神經分布區（拇指、食指、中指及部分無名指）之麻木刺痛感，並非以「腕部無法伸直」為特徵性表現，此敘述有誤（C✗）；腕隧道症候群的特異性理學檢查為Tinel徵象及Phalen測試，膨脹徵象與霍曼氏徵象分別用於評估膝關節積液及深部靜脈栓塞，與腕隧道症候群診斷無關，此敘述檢查方法配對有誤（D✗）。"},{n:659,no:19,subj:"骨骼肌肉",q:"王先生開放性骨折日前出院返家，近日發燒、寒顫、躁動不安、患肢持續性疼痛及拒絕移動關節或觸碰患肢。下列何者為其最可能的合併症？",opts:["A.肺栓塞","B.骨髓炎","C.脂肪栓塞","D.低血容積休克"],ans:[1],expl:"本題答案為B。開放性骨折出院後近期出現發燒、寒顫等全身性感染徵象，合併患肢持續性局部疼痛及拒絕移動觸碰（保護性姿勢），此組合高度提示患肢深部骨組織感染，即骨髓炎，為本題答案。肺栓塞典型表現為突發性胸痛、呼吸困難等呼吸循環症狀，與此題描述之局部患肢症狀不符（A✗）；脂肪栓塞好發於骨折後「24～72小時內」之早期階段，且典型表現為呼吸窘迫、意識改變及出血點三合一症狀，與此題「日前出院返家後近日」發生之時序及症狀表現不符（C✗）；低血容積休克表現為血壓下降、心跳加速等全身循環不穩定徵象，與此題局部患肢感染徵象不符（D✗）。"},{n:660,no:20,subj:"骨骼肌肉",q:"有關痛風藥物Probenecis（Benemid）的主要作用，下列何者正確？",opts:["A.抑制尿酸形成","B.增加尿酸排出","C.降低普林排出","D.抑制炎症反應"],ans:[1],expl:"本題答案為B。Probenecid（Benemid）屬於促尿酸排泄藥物，其主要作用機轉是抑制腎小管對尿酸的再吸收，進而增加尿酸自尿液排出，為本題答案。此藥物並非抑制尿酸「形成」（此為Allopurinol等黃嘌呤氧化酶抑制劑之作用機轉），此敘述機轉有誤（A✗）；此藥物是增加（而非降低）尿酸排出，其中普林（purine）代謝與尿酸生成相關，並非此藥直接作用之標的，此敘述有誤（C✗）；Probenecid並非消炎止痛藥物，不具抑制發炎反應的作用機轉，此敘述有誤（D✗）。"},{n:661,no:21,subj:"骨骼肌肉",q:"有關骨折的癒合過程，下列順序何者正確？①血腫形成期 ②骨化期 ③細胞增生期 ④重塑期 ⑤骨痂形成期",opts:["A.①②③④⑤","B.①③⑤②④","C.②③①④⑤","D.⑤④③②①"],ans:[1],expl:"本題答案為B。骨折癒合的標準病理生理順序為：①血腫形成期（骨折後立即形成血腫）→③細胞增生期（纖維母細胞及軟骨母細胞增生形成肉芽組織）→⑤骨痂形成期（軟骨性骨痂逐漸鈣化）→②骨化期（骨痂進一步鈣化為骨性骨痂）→④重塑期（骨骼依力學需求重塑改建），此順序為①③⑤②④，為本題答案。其餘排序組合（①②③④⑤、②③①④⑤、⑤④③②①）皆與此標準病理生理癒合順序不符（A✗、C✗、D✗）。"},{n:662,no:22,subj:"感官系統",q:"有關青光眼病人之護理措施，下列何者正確？",opts:["A.眼內壓上升超過正常值且造成視神經受損，稱為青光眼","B.準備病人接受晶狀體植入","C.熬夜不會影響眼壓","D.指導病人術後臥向手術側"],ans:[0],expl:"本題答案為A。青光眼的定義即為眼內壓上升超過正常範圍，進而壓迫視神經導致視神經纖維受損，甚至造成視野缺損及失明，此為正確之疾病定義，為本題答案。青光眼病人手術治療多為「小樑切除術」等降低眼壓的手術，「晶狀體植入」是白內障手術的處置內容，此敘述手術類型配對有誤（B✗）；熬夜睡眠不足、情緒壓力等因子「會」使眼壓升高，此敘述方向有誤（C✗）；青光眼手術後應臥向「健側（非手術側）」，以避免手術部位受壓迫或影響眼內引流，此敘述方向有誤（D✗）。"},{n:663,no:23,subj:"感官系統",q:"有關中耳炎手術病人之術後護理指導，下列何者錯誤？",opts:["A.手術後要觀察有無切斷顏面神經的合併症","B.病人應採用軟質飲食","C.禁做會阻塞耳咽管的伐氏操作法（Valsalva's Maneuver）","D.勿用力擤鼻子、用力咳嗽或打噴嚏"],ans:[2],expl:"本題答案為C。中耳炎手術後應避免執行伐氏操作法（用力閉氣鼓氣，如摒氣用力、擤鼻），因會使鼓室內壓力驟增，可能影響手術傷口癒合甚至造成聽小骨移位，此為正確之術後衛教重點，為本題答案（此處雖敘述本身內容正確，但由於原題設計此選項作為官方認定的「錯誤」選項，可能與「阻塞耳咽管」之機轉描述精確度或其他細節有關，讀者可留意伐氏操作法本身之定義及禁忌邏輯，核心觀念仍是「術後應避免用力閉氣鼓氣」）。手術後應密切觀察是否出現顏面神經受損之合併症（如口角歪斜），因顏面神經走行經過中耳腔，手術中有受損風險，敘述正確（A✓）；術後初期建議採軟質飲食，以減少咀嚼時對術耳部位的震動及不適，敘述正確（B✓）；勿用力擤鼻子、咳嗽或打噴嚏，以避免鼓室內壓力驟變影響傷口癒合，敘述正確（D✓）。"},{n:664,no:24,subj:"腫瘤血液",q:"下列腫瘤何者源自結締組織？",opts:["A.滑液膜肉瘤（synovial-sarcoma）","B.軟骨肉瘤（chondrosarcoma）","C.血管肉瘤（angiosarcoma）","D.淋巴管肉瘤（lymphangiosarcoma）"],ans:[1],expl:"本題答案為B。軟骨肉瘤（chondrosarcoma）是由軟骨細胞產生惡性腫瘤，而軟骨在組織學上明確歸類為結締組織的一種特化型態，為本題答案。滑液膜肉瘤雖好發於關節附近，但其腫瘤細胞來源與真正滑液膜組織的關聯性複雜，傳統上被歸類為軟組織肉瘤而非典型結締組織腫瘤（A✗）；血管肉瘤源自血管內皮細胞，屬於血管（內皮）組織來源腫瘤（C✗）；淋巴管肉瘤源自淋巴管內皮細胞，屬於淋巴管（內皮）組織來源腫瘤（D✗）。"},{n:665,no:25,subj:"感官系統",q:"有關聽力喪失病人的護理指導，下列何者錯誤？",opts:["A.與別人溝通時，等待對方先開口","B.採用適當的位置，使說話者面部採光良好","C.要求對方先說明主題，當改變話題時先通知","D.家中電話加裝擴音器，或家中電鈴加裝閃光"],ans:[0],expl:"本題答案為A。聽力喪失病人溝通時，宜由「說話者主動先開口、吸引病人注意」後再進行對話，若一味「等待對方先開口」，病人可能因未注意到對方已開始說話而錯過訊息開頭，此建議並不適當，為本題答案（A✗，題目問「何者錯誤」）。使說話者面部處於良好採光位置，有助聽力障礙者藉由讀唇及觀察表情輔助理解，敘述正確（B✓）；改變話題前先給予提示、告知主題，可幫助病人跟上對話內容轉換，敘述正確（C✓）；電話加裝擴音器及門鈴加裝閃光裝置，皆為聽力障礙者常用的環境輔助裝置，敘述正確（D✓）。"},{n:666,no:26,subj:"心臟血管",q:"有關心臟復健（Cardiac Rehabilitation, CR）活動時應注意事項的敘述，下列何者錯誤？",opts:["A.活動時應以漸進性方式增加強度","B.活動初期的心跳速率以其最大心跳的80%為原則","C.活動時的心跳速率以不超過靜態休息時的20次/分鐘為原則","D.活動後血壓上升以不超過正常血壓值25 mmHg為原則"],ans:[1],expl:"本題答案為B。心臟復健活動強度之訂定原則，通常建議初期活動強度以最大心跳「約60～80%範圍內、且需依個別評估漸進調整」為原則，而非直接以「80%」作為活動初期固定標準，對心臟功能尚未穩定的病人而言此強度可能過高，此敘述作為初期原則並不恰當，為本題答案（B✗，題目問「何者錯誤」）。心臟復健活動應採漸進式增加強度的原則，敘述正確（A✓）；活動時心跳速率上升不宜超過靜息心跳20次/分鐘，為常用安全監控標準，敘述正確（C✓）；活動後血壓上升幅度不宜超過原血壓值25 mmHg，為常用安全監控標準，敘述正確（D✓）。"},{n:667,no:27,subj:"心臟血管",q:"王先生經醫生診斷為柏格氏病（Buerger's Disease），下列敘述何者正確？",opts:["A.與抽菸有關","B.主要是周邊靜脈之阻塞","C.好發在上肢","D.走路無異狀"],ans:[0],expl:"本題答案為A。柏格氏病（Buerger's disease，血栓閉塞性脈管炎）與吸菸有高度相關性，戒菸是治療此疾病最關鍵的措施，為本題答案。柏格氏病主要侵犯周邊「動脈」（合併靜脈及神經），並非主要為靜脈阻塞，此敘述血管類型有誤（B✗）；柏格氏病好發於「下肢」（尤其足部及小腿的中小型動脈），並非好發於上肢，此敘述部位有誤（C✗）；因下肢動脈阻塞供血不良，病人走路時常出現間歇性跛行等異常表現，並非走路無異狀，此敘述有誤（D✗）。"},{n:668,no:28,subj:"心臟血管",q:"有關心絞痛病人接受股動脈經皮穿腔冠狀動脈血管成形術（PTCA）之術後護理，下列何者錯誤？",opts:["A.監測雙側肢體之脈搏","B.監測心電圖","C.鼓勵病人多飲水","D.鼓勵病人行下肢全關節主動運動"],ans:[3],expl:"本題答案為D。PTCA術後穿刺部位（股動脈）需保持該側下肢伸直制動一段時間，以避免穿刺處出血或血腫，「鼓勵下肢全關節主動運動」與術後穿刺部位制動的照護原則相違背，此敘述並不適當，為本題答案（D✗，題目問「何者錯誤」）。監測穿刺部位遠端雙側肢體脈搏，可及早發現血管併發症（如栓塞或阻塞），敘述正確（A✓）；PTCA術後應持續監測心電圖，以及早發現心律不整或再阻塞徵象，敘述正確（B✓）；鼓勵術後多飲水，有助促進顯影劑經腎臟排出，減少顯影劑腎病變風險，敘述正確（C✓）。"},{n:669,no:29,subj:"心臟血管",q:"有關裝置心臟節律器之護理指導，下列何者錯誤？",opts:["A.心律變慢時，可能是電池快沒電的徵象","B.每天需監測橈動脈至少1分鐘整","C.持續打嗝時，可利用Valsalva運動減緩打嗝","D.術後6週內避免抬重物"],ans:[2],expl:"本題答案為C。持續性打嗝（頑固性呃逆）並非心臟節律器裝置後的常規照護重點，且利用Valsalva運動（用力閉氣）處理打嗝時，此動作本身會影響胸內壓及靜脈回流，對於剛裝置節律器的病人而言並非建議的常規指導內容，此敘述並不恰當，為本題答案（C✗，題目問「何者錯誤」）。心律變慢可能反映節律器電池電力不足或感應功能異常，應提高警覺，敘述正確（A✓）；每日自我監測橈動脈脈搏至少1分鐘整，有助及早發現心律異常，為標準居家自我監測指導，敘述正確（B✓）；術後6週內應避免抬舉重物及劇烈手臂活動，以防導線移位，敘述正確（D✓）。"},{n:670,no:30,subj:"心臟血管",q:"有關心因性休克之敘述，下列何者錯誤？",opts:["A.心臟幫浦功能障礙造成循環衰竭","B.最常見之致病原因為心肌梗塞","C.最常見之症狀為呼吸停止","D.心輸出量不符身體組織所需"],ans:[2],expl:"本題答案為C。心因性休克最常見的症狀是低血壓、心搏過速、皮膚濕冷及意識改變等組織灌流不足之表現，「呼吸停止」並非其最常見或典型的初期臨床表現，此敘述有誤，為本題答案（C✗，題目問「何者錯誤」）。心因性休克之核心病生理機轉即為心臟幫浦功能障礙、心輸出量銳減導致全身循環衰竭，敘述正確（A✓）；心肌梗塞是心因性休克最常見的致病原因，敘述正確（B✓）；心輸出量不足以滿足身體組織代謝所需，是心因性休克之核心定義，敘述正確（D✓）。"},{n:671,no:31,subj:"心臟血管",q:"有關聽診心音之敘述，下列何者錯誤？",opts:["A.第一心音的產生是僧帽瓣與三尖瓣關閉血液撞擊所造成","B.聽診心音的主動脈瓣區在胸骨右緣第2肋間","C.聽到第二心音之後心動週期進入心室的舒張期","D.心臟衰竭病人如出現第三心音會在心室的舒張末期聽到"],ans:[3],expl:"本題答案為D。第三心音（S3）是發生於心室舒張「早期」（快速充盈期），而非舒張末期；心室舒張「末期」（心房收縮期）出現的額外心音應為第四心音（S4），此敘述將S3與S4的發生時期混淆，為本題答案（D✗，題目問「何者錯誤」）。第一心音是由二尖瓣（僧帽瓣）與三尖瓣關閉時瓣膜血液撞擊振動所產生，敘述正確（A✓）；主動脈瓣區聽診位置位於胸骨右緣第二肋間，敘述正確（B✓）；第二心音之後心動週期即進入心室舒張期，敘述正確（C✓）。"},{n:672,no:32,subj:"心臟血管",q:"下列血流動力學檢查結果何者正常？",opts:["A.右心房壓力130 mmHg","B.右心室收縮壓120 mmHg","C.左心室舒張壓40 mmHg","D.上腔靜脈壓8 mmHg"],ans:[3],expl:"本題答案為D。上腔靜脈壓（近似中心靜脈壓）正常範圍約2～8 mmHg，8 mmHg屬正常範圍內數值，為本題答案。右心房壓力正常範圍約0～8 mmHg，130 mmHg數值明顯異常過高，不符合正常生理數值（A✗）；右心室收縮壓正常範圍約15～30 mmHg，120 mmHg數值明顯異常過高（B✗）；左心室舒張壓（可反映左心室舒張末期壓力）正常範圍約4～12 mmHg，40 mmHg數值明顯異常過高，通常提示左心室衰竭或嚴重舒張功能障礙（C✗）。"},{n:673,no:33,subj:"心臟血管",q:"輸注下列何種藥物時，需以不透光錫箔紙包住點滴瓶及輸液管？",opts:["A.Diazoxide（Hyperstat）","B.Dobutamine（Dobutrex）","C.Nitroglycerin（Tridil）","D.Nitroprusside（Nipride）"],ans:[3],expl:"本題答案為D。硝普鈉（Nitroprusside, Nipride）於光照下會逐漸分解變質，故臨床上須以不透光錫箔紙包裹點滴瓶及輸液管，避免藥效減損，此為標準用藥照護原則，為本題答案。Diazoxide、Dobutamine、Nitroglycerin等藥物之保存及輸注雖各有其他注意事項，但並非以「避光」作為其輸注時的關鍵防護重點（A✗、B✗、C✗）。"},{n:674,no:34,subj:"心臟血管",q:"下列何者是心肌梗塞最常見且會導致死亡的併發症？",opts:["A.心因性休克","B.心肌梗塞再度發生","C.心律不整","D.急性肺水腫"],ans:[2],expl:"本題答案為C。心律不整（尤其致命性心室頻脈或心室顫動）是心肌梗塞後最常見且是導致早期猝死的主要合併症，為本題答案。心因性休克及急性肺水腫雖為心肌梗塞嚴重合併症，但其發生率與致死率相較於心律不整仍屬次要（A✗、D✗）；心肌梗塞再度發生雖為需留意之風險，但並非「最常見」導致死亡之立即合併症（B✗）。"},{n:675,no:35,subj:"腫瘤血液",q:"有關缺鐵性貧血病人的護理措施，下列何者正確？①教導病人使用吸管吸食液態鐵劑 ②鼓勵病人飯後服用鐵劑以增加鐵的吸收 ③鼓勵病人多攝取富含維生素C的食物 ④注射鐵劑後應避免立即拔出針頭",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[2],expl:"本題答案為C（①③④）。①使用吸管吸食液態鐵劑，可減少鐵劑接觸牙齒表面造成染色；③維生素C可促進非血基質鐵的腸道吸收效率；④肌肉注射鐵劑後應避免立即拔針，宜採Z字形注射技術並延遲拔針，以防藥液滲漏至皮下造成染色刺激，此三者敘述皆為正確之護理措施，選①③④＝C（本題答案）。鐵劑建議「空腹」服用以達最佳吸收效果（若腸胃道能耐受），飯後服用雖可能減少腸胃刺激但會降低吸收效率，並非以「增加鐵的吸收」為目的的正確建議，此敘述機轉方向有誤（②錯誤）。"},{n:676,no:36,subj:"腫瘤血液",q:"林先生接受骨髓移植後2週出現黃疸、腹水、體重增加，下列何者為最可能發生之合併症？",opts:["A.感染","B.間質性肺炎","C.肝靜脈阻塞疾病","D.慢性移植物對抗宿主疾病"],ans:[2],expl:"本題答案為C。骨髓移植後2週出現黃疸、腹水、體重增加（因肝內竇狀隙阻塞導致液體滯留），此組合為肝靜脈阻塞疾病（肝竇阻塞症候群）的典型臨床三徵，為本題答案。感染典型表現以發燒、局部感染徵象為主，與此題黃疸腹水體重增加的表現組合不符（A✗）；間質性肺炎典型表現為呼吸道症狀（咳嗽、呼吸困難），與此題症狀不符（B✗）；慢性移植物對抗宿主疾病通常發生於移植「100天後」的較晚期階段，且主要侵犯皮膚、肝臟、腸胃道及眼睛等多重器官，與移植後2週即出現的時序不符（D✗）。"},{n:677,no:37,subj:"腫瘤血液",q:"有關白血病病人接受異體骨髓移植後出現合併症之敘述，下列何者錯誤？",opts:["A.移植前曾罹患肝炎者會增加肝靜脈阻塞的機率","B.急性移植物對抗宿主疾病以皮膚、腸胃道及肝臟為主","C.慢性移植物對抗宿主疾病的發生率與年齡有關","D.移植後2星期內的感染以巨細胞病毒感染最常見"],ans:[3],expl:"本題答案為D。骨髓移植後2星期內（極早期）感染以「細菌及黴菌」感染為主（因嗜中性白血球尚未恢復、黏膜屏障受損），巨細胞病毒（CMV）感染則好發於移植後「1～4個月」的中期階段，此敘述時序有誤，為本題答案（D✗，題目問「何者錯誤」）。移植前曾罹患肝炎（肝功能已受損）者，移植後發生肝靜脈阻塞疾病之風險確實較高，敘述正確（A✓）；急性移植物對抗宿主疾病主要侵犯皮膚、腸胃道及肝臟三大器官，敘述正確（B✓）；慢性移植物對抗宿主疾病的發生率與病人年齡（年齡增長風險增加）等因子相關，敘述正確（C✓）。"},{n:678,no:38,subj:"腫瘤血液",q:"有關特異性血小板減少性紫斑症之敘述，下列何者正確？①可能與自體免疫疾病有關 ②骨髓檢查可發現巨核細胞增加 ③須避免使用Aspirin的藥物 ④經常發生於細菌感染後",opts:["A.①②③","B.①②④","C.①③④","D.②③④"],ans:[0],expl:"本題答案為A（①②③）。①特異性血小板減少性紫斑症（ITP）與自體免疫機轉相關（產生抗血小板抗體）；②骨髓檢查因周邊血小板被破壞增加，骨髓代償性增生，可發現巨核細胞數目「增加」；③因血小板數目低下，應避免使用具抗血小板作用之Aspirin類藥物以防加重出血風險，此三者敘述皆正確，選①②③＝A（本題答案）。ITP好發於「病毒感染」後（尤其兒童型ITP常見於病毒感染後2～3週），而非細菌感染後，此敘述病原體類型有誤（④錯誤）。"},{n:679,no:39,subj:"腫瘤血液",q:"有關化學治療藥物作用機轉與副作用之敘述，下列何者錯誤？",opts:["A.Cisplatin屬烴基化合物，常見副作用是噁心嘔吐、耳毒性和周邊神經病變等","B.Fluorouracil（5-FU）屬抗代謝藥物，常見副作用是口腔炎、骨髓抑制等","C.Doxorubicin屬類固醇藥物，可促進G0期癌細胞進入分裂期","D.Vincristine屬植物鹼類藥物，作用於M期，干擾有絲分裂"],ans:[2],expl:"本題答案為C。Doxorubicin屬於「抗腫瘤抗生素（蒽環類藥物）」，其作用機轉是嵌入DNA雙股螺旋並抑制拓樸異構酶II，進而阻斷DNA複製及RNA合成，並非類固醇藥物，亦非以「促進G0期癌細胞進入分裂期」為其藥理作用機轉，此敘述藥物分類及機轉皆有誤，為本題答案（C✗，題目問「何者錯誤」）。Cisplatin屬鉑類（烴基）化合物，常見副作用包括噁心嘔吐、耳毒性及周邊神經病變，敘述正確（A✓）；Fluorouracil（5-FU）屬抗代謝藥物，常見副作用為口腔炎、骨髓抑制，敘述正確（B✓）；Vincristine屬植物鹼類藥物，作用於細胞週期M期（有絲分裂期），干擾紡錘體形成，敘述正確（D✓）。"},{n:680,no:40,subj:"腫瘤血液",q:"有關放射線治療病人照射處皮膚照護之敘述，下列何者錯誤？",opts:["A.要用中性肥皂搓洗避免感染","B.不可塗抹含酒精的乳液","C.可依醫囑塗抹氧化鋅","D.只能使用電動刮鬍刀"],ans:[0],expl:"本題答案為A。放射線治療照射處皮膚較脆弱敏感，應避免用力搓洗，建議以「溫水及中性肥皂輕柔清洗」而非用力搓洗，過度摩擦可能加重皮膚破損及感染風險，此敘述「搓洗」的力道方式並不適當，為本題答案（A✗，題目問「何者錯誤」）。應避免使用含酒精成分之乳液，以防刺激及乾燥照射處皮膚，敘述正確（B✓）；可依醫囑塗抹氧化鋅等皮膚保護劑，敘述正確（C✓）；照射部位若需除毛，建議使用電動刮鬍刀（而非傳統刀片），以降低皮膚割傷及感染風險，敘述正確（D✓）。"},{n:681,no:41,subj:"腫瘤血液",q:"有關癌症病人出血問題之敘述，下列何者錯誤？",opts:["A.血小板數目8萬/μL是正常的數據","B.消化道出血時，可使用冰鹽水灌洗","C.有出血傾向的病人要限制使用Coumadin和Heparine","D.要避免肌肉注射或量肛溫等侵入性處置"],ans:[0],expl:"本題答案為A。血小板數目正常範圍約為15～45萬/μL，8萬/μL已低於正常範圍（屬血小板低下），並非正常數據，此敘述有誤，為本題答案（A✗，題目問「何者錯誤」）。消化道出血時，可使用冰生理食鹽水灌洗，透過低溫促進血管收縮以協助止血，敘述正確（B✓）；有出血傾向之病人應限制使用具抗凝血作用之Coumadin（Warfarin）及Heparin，以免加重出血風險，敘述正確（C✓）；應避免肌肉注射及測量肛溫等侵入性處置，以減少醫源性出血或黏膜損傷風險，敘述正確（D✓）。"},{n:682,no:42,subj:"腫瘤血液",q:"有關乳癌症狀與疾病分期之敘述，下列何者正確？",opts:["A.好發部位在乳房的內上1/4處","B.T2N1M0屬於癌症分期的第三期","C.最常見的症狀為疼痛性腫塊","D.乳頭下腫塊會造成乳頭回縮或高低不一"],ans:[3],expl:"本題答案為D。乳頭下方腫塊可能牽扯乳房懸韌帶（Cooper's ligament），造成乳頭回縮或兩側乳頭高低不對稱，此為乳癌重要且正確之臨床表徵敘述，為本題答案。乳癌好發部位是乳房「外上1/4象限」（因該區域乳腺組織較豐富），並非內上1/4處，此敘述部位有誤（A✗）；依TNM分期系統，T2N1M0通常歸類為癌症分期第「II期（IIB期）」，並非第三期，此敘述分期有誤（B✗）；乳癌初期腫塊通常為「無痛性」腫塊，此為其臨床特徵之一，並非以疼痛性腫塊為最常見表現，此敘述有誤（C✗）。"},{n:683,no:43,subj:"泌尿系統",q:"有關前列腺癌之敘述，下列何者正確？",opts:["A.藥物治療大多使用雄性素","B.放射線治療時最常使用鈷60放射源","C.鹼性磷酸酶值過高與前列腺癌之診斷有關","D.前列腺特異性抗原（PSA）濃度可做為治療效果的參考"],ans:[3],expl:"本題答案為D。前列腺特異性抗原（PSA）除可輔助診斷外，亦可作為前列腺癌治療反應及疾病進展追蹤之重要參考指標，為本題答案。前列腺癌之藥物治療原則是使用「抗雄性素藥物或去勢治療」以降低雄性素刺激腫瘤生長，並非使用雄性素本身，此敘述用藥方向有誤（A✗）；前列腺癌放射線治療現行多採用直線加速器等現代放射源，鈷60已非現行最常使用之放射源，此敘述有誤（B✗）；鹼性磷酸酶（ALP）升高較常與前列腺癌「骨轉移」相關，並非直接作為前列腺癌本身之診斷依據，此敘述關聯性描述不夠精確（C✗）。"},{n:684,no:44,subj:"其他",q:"有關決定膚色的黑色素細胞主要分布在下列那一層？",opts:["A.顆粒層","B.棘狀層","C.基底層","D.網狀層"],ans:[2],expl:"本題答案為C。黑色素細胞（melanocyte）主要分布於表皮的基底層（stratum basale），負責製造黑色素以決定膚色深淺，此為正確之解剖生理位置，為本題答案。顆粒層、棘狀層及網狀層皆非黑色素細胞主要分布之部位（A✗、B✗、D✗）。"},{n:685,no:45,subj:"其他",q:"有關全身性紅斑性狼瘡之護理措施，下列何者錯誤？",opts:["A.出門時應穿長袖衣物及穿戴寬邊帽子防曬","B.出現血尿、蛋白尿等狀況時，應多下床活動","C.慢性疲勞時，建議執行漸進式活動，如步行或游泳等","D.若有生育考量，於病情控制良好6個月後，再與醫師討論懷孕計畫"],ans:[1],expl:"本題答案為B。全身性紅斑性狼瘡病人若出現血尿、蛋白尿等腎臟受侵犯（狼瘡腎炎）之表現，應以「休息」為主、限制活動量，並密切配合治療監測腎功能，而非鼓勵多下床活動，此敘述並不適當，為本題答案（B✗，題目問「何者錯誤」）。紫外線是誘發或加重紅斑性狼瘡疾病活性之重要環境因子，應做好防曬措施，敘述正確（A✓）；慢性疲勞時建議採漸進式、低強度的規律運動（如步行、游泳），以避免過度疲累同時維持身體功能，敘述正確（C✓）；懷孕前應確認病情控制穩定（一般建議至少6個月無疾病活動期），並與醫師討論懷孕時機及風險，敘述正確（D✓）。"},{n:686,no:46,subj:"其他",q:"有關感染疥瘡（Scabies）引起皮膚疾病之敘述，下列何者錯誤？",opts:["A.人體接觸疥蟲後2週左右會出現症狀","B.疥蟲感染者所使用的床單，在2週內具有傳染力","C.劇癢症狀好發在頸部以下","D.衣物用具加熱煮沸可以殺死疥蟲"],ans:[0],expl:"本題答案為A。疥瘡（疥蟲感染）初次感染後，通常約需「2～6週」的潛伏期才會出現搔癢等過敏反應症狀（若為重複感染，因已致敏，發作時間可縮短至數天），「2週左右」此時間敘述較不精確、偏短，為本題答案（A✗，題目問「何者錯誤」）。使用過的床單、衣物在離開人體宿主後，疥蟲仍可於物品上存活並具傳染力達1～2週左右，敘述正確（B✓）；劇癢症狀好發於皮膚皺褶處，如指縫、手腕、腋下及軀幹（頸部以下），敘述正確（C✓）；疥蟲不耐高溫，衣物寢具經加熱煮沸或高溫烘乾可有效殺死疥蟲及蟲卵，敘述正確（D✓）。"},{n:687,no:47,subj:"其他",q:"有關燒傷深度的敘述，下列何者錯誤？",opts:["A.一度燒傷是指表皮受到損害，會有疼痛感","B.二度燒傷是指真皮層受到損傷，會有劇烈疼痛","C.三度燒傷是指全皮層的損傷，會有劇烈疼痛","D.四度燒傷是指全皮層、肌肉和骨骼的損傷，沒有疼痛感"],ans:[2],expl:"本題答案為C。三度燒傷（全層皮膚燒傷）因表皮及真皮層的神經末梢已完全被破壞，病人反而「不會有疼痛感」（僅周圍未完全燒傷區域可能有痛覺），此敘述「會有劇烈疼痛」與三度燒傷神經受損的病理特徵相反，為本題答案（C✗，題目問「何者錯誤」）。一度燒傷僅表皮受損，神經末梢未受破壞，故會有疼痛感，敘述正確（A✓）；二度燒傷侵犯真皮層，因神經末梢暴露刺激，會有劇烈疼痛感，敘述正確（B✓）；四度燒傷深達肌肉及骨骼，神經組織已完全破壞，故不會有疼痛感，敘述正確（D✓）。"},{n:688,no:48,subj:"其他",q:"有關後天免疫缺乏症候群（Acquired Immunodeficiency Syndrome, AIDS）之敘述，下列何者錯誤？",opts:["A.不會經由握手、擁抱、共餐、共用馬桶、游泳、蚊蟲叮咬等途徑傳染病毒","B.有皮膚疾患或懷孕的醫療人員不應直接對病人進行醫療照護","C.由於病人容易產生伺機性感染，避免到人多擁擠的公共場所","D.病人應定期接種麻疹腮腺炎德國麻疹混合疫苗（MMR）與流感疫苗"],ans:[3],expl:"本題答案為D。愛滋病病人應避免接種「活性減毒疫苗」（因免疫功能低下，接種活疫苗有引發疫苗株感染之風險），MMR（麻疹腮腺炎德國麻疹混合疫苗）即屬活性減毒疫苗，並非愛滋病人應定期接種的建議項目，此敘述有誤，為本題答案（D✗，題目問「何者錯誤」）。愛滋病毒不會經由日常生活接觸（握手、擁抱、共餐、共用馬桶、游泳、蚊蟲叮咬）傳染，敘述正確（A✓）；醫療人員若有開放性皮膚傷口或處於懷孕（考量特殊藥物暴露風險）等狀況，應避免直接執行有體液暴露風險之醫療照護，敘述可接受（B✓）；病人因免疫力低下、容易併發伺機性感染，應避免出入人多擁擠的公共場所，敘述正確（C✓）。"},{n:689,no:49,subj:"其他",q:"有關器官移植後之護理指導，下列何者錯誤？",opts:["A.移植後應多做戶外運動、曬太陽，以增強抵抗力","B.移植後避免出入公共場所，外出戴口罩","C.移植後服藥出現藥物副作用，不可自行停藥，回診由醫師調整用藥","D.移植後需要暫時避孕，若準備懷孕應事先與醫師討論"],ans:[0],expl:"本題答案為A。器官移植後病人須服用免疫抑制劑，免疫功能較常人低下，應「避免」長時間曝露於陽光下及出入人多場所，以降低感染及皮膚癌風險，「多做戶外運動、曬太陽以增強抵抗力」之建議並不適當且方向有誤，為本題答案（A✗，題目問「何者錯誤」）。移植後應避免出入公共場所並於外出時戴口罩，以降低感染風險，敘述正確（B✓）；出現疑似藥物副作用時，應回診由醫師評估調整用藥，不可自行停藥（以防排斥反應），敘述正確（C✓）；移植後因抗排斥藥物對胎兒的潛在風險及身體狀況尚未穩定，需暫時避孕，若考慮懷孕應事先與醫師討論用藥調整，敘述正確（D✓）。"},{n:690,no:50,subj:"骨骼肌肉",q:"有關類風濕性關節炎之敘述，下列何者正確？①手部關節會出現尺側偏斜 ②活動後有僵硬的現象 ③關節X光變化呈現關節腔變窄 ④關節腫脹呈現不對稱性",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[1],expl:"本題答案為B（①③）。①類風濕性關節炎因慢性發炎侵蝕關節周邊韌帶及肌腱，可造成手指關節向尺側偏移（尺側偏斜）之典型畸形；③關節滑膜發炎侵蝕軟骨，X光可見特徵性關節腔間隙變窄，此二者皆為類風濕性關節炎的典型表現，選①③＝B（本題答案）。類風濕性關節炎的晨僵及活動後僵硬現象，典型上是「休息後（尤其晨起）」僵硬明顯、活動後反而緩解，「活動後才出現僵硬」之敘述時序方向有誤（②錯誤）；類風濕性關節炎的關節腫脹分布特徵是「兩側對稱性」（而非不對稱性），此為與退化性關節炎等其他關節疾病鑑別之重要特徵，此敘述方向有誤（④錯誤）。"},{n:691,no:51,subj:"其他",q:"有關鞏皮症之敍述，下列何者正確？",opts:["A.又稱「進行性系統性硬化症」，好發於男性","B.常發生雷諾氏症候群（Raynaud's syndrome）","C.血液檢查γ–球蛋白增加，主要是IgA增加","D.侵犯臉部，造成臉部表情豐富現象"],ans:[1],expl:"本題答案為B。鞏皮症（進行性系統性硬化症）病人因周邊血管病變，常合併雷諾氏症候群（肢端遇冷或壓力誘發血管痙攣、膚色變化），此為其常見合併之血管性表現，為本題答案。鞏皮症好發於「女性」（尤其30～50歲），並非好發於男性，此敘述性別方向有誤（A✗）；鞏皮症血液檢查異常主要與抗核抗體（ANA）及特異性自體抗體（如抗Scl-70）相關，並非典型以γ-球蛋白中IgA增加為特徵性表現，此敘述並不精確（C✗）；鞏皮症侵犯臉部皮膚會因膠原纖維化增生使皮膚繃緊變硬，造成「臉部表情喪失（面具臉）」，並非表情豐富，此敘述方向相反（D✗）。"},{n:692,no:52,subj:"呼吸系統",q:"有關使用呼氣末期陽壓（PEEP）治療急性呼吸窘迫症候群的主要目的，下列何者正確？",opts:["A.可避免肺纖維化的產生","B.可使吸氣時有更多氣體帶入肺內","C.可將100%的氧氣帶入肺內","D.可避免吐氣時肺泡塌陷"],ans:[3],expl:"本題答案為D。呼氣末期陽壓（PEEP）之主要生理目的，是在吐氣末期維持肺泡內一定的正壓，避免肺泡於吐氣末完全塌陷，藉此增加功能性肺餘容積、改善氣體交換及血氧狀態，為本題答案。PEEP主要目的並非直接預防肺纖維化之產生，兩者機轉無直接關聯（A✗）；PEEP是作用在「吐氣末期」維持肺泡開放，並非直接增加「吸氣時」帶入肺內的氣體量，此為潮氣容積或吸氣壓力設定之作用範疇，此敘述機轉有誤（B✗）；PEEP的設定與提供之氧氣濃度（FiO2）為呼吸器兩個獨立參數，PEEP本身並非用以「將100%氧氣帶入肺內」，此敘述機轉有誤（C✗）。"},{n:693,no:53,subj:"呼吸系統",q:"下列何者為肺水腫最典型的症狀？",opts:["A.呼吸音出現肋膜摩擦音","B.突然胸痛","C.粉紅色泡沫痰","D.杵狀指"],ans:[2],expl:"本題答案為C。粉紅色泡沫痰是肺水腫（尤其急性心因性肺水腫）最典型、最具特徵性的臨床症狀，因肺泡內滲出液與空氣混合、並含微量血液所致，為本題答案。呼吸音出現肋膜摩擦音較常見於肋膜炎，並非肺水腫之典型症狀（A✗）；突然胸痛較常見於氣胸、肺栓塞或心肌梗塞等急症，並非肺水腫最典型的症狀（B✗）；杵狀指常與慢性缺氧性疾病（如慢性肺部疾病、發紺性心臟病）相關，並非肺水腫的急性典型表現（D✗）。"},{n:694,no:54,subj:"呼吸系統",q:"病人行氣管內插管後聽診呼吸音時，發現左側肺部呼吸音減弱但右側正常，下列何者為導致此情形最可能的原因？",opts:["A.氣管內管插到食道中","B.氣管內管插到右主支氣管內","C.氣管內管插到氣管分叉處上","D.病人有左肺肺炎"],ans:[1],expl:"本題答案為B。氣管內管因解剖角度關係，最容易滑入角度較直、較垂直的「右主支氣管」，導致左側肺葉未被充分通氣，聽診時左側呼吸音會明顯減弱，而右側因仍持續甚至過度通氣而聽診正常，此為臨床最常見且需優先排除的插管過深情形，為本題答案。氣管內管插入食道會導致「雙側」肺部呼吸音皆消失或減弱，且會伴隨胃部脹氣、CO2偵測器無法偵測到吐氣末二氧化碳等表現，與此題單側呼吸音減弱不符（A✗）；氣管內管若僅插至氣管分叉處上方（位置正常），雙側肺部呼吸音應大致對稱，不會出現單側減弱的情形（C✗）；病人若原有左肺肺炎，通常會使左側呼吸音出現爆裂音、囉音等異常聲音，而非單純呼吸音「減弱」，且此為插管前已存在之病灶而非插管操作直接造成之情形，與題目情境（插管後聽診發現異常）較不相符（D✗）。"},{n:695,no:55,subj:"呼吸系統",q:"有關呼吸器的使用，通常會設定每分鐘數次深呼吸，其所要預防之首要合併症，下列何者正確？",opts:["A.氣胸","B.肺栓塞","C.肺炎","D.肺擴張不全"],ans:[3],expl:"本題答案為D。呼吸器設定中常規每隔一段時間給予數次深呼吸（嘆息式呼吸/sigh breath），主要目的是預防因潮氣容積過小、長時間淺快呼吸所導致的肺泡塌陷（肺擴張不全），為本題答案。氣胸較常與呼吸器使用不當造成的壓力性損傷相關，並非深呼吸設定所要預防的「首要」合併症（A✗）；肺栓塞主因與血栓形成相關，與呼吸器深呼吸設定的預防目的無直接關聯（B✗）；肺炎的預防重點在於呼吸道分泌物清除及感染控制，並非深呼吸設定之首要目的（C✗）。"},{n:696,no:56,subj:"呼吸系統",q:"照護右上肺葉肺炎病人之護理措施，下列何者不適當？",opts:["A.協助病人右側臥","B.教導病人抱胸咳嗽","C.將病人床頭抬高45度","D.鼓勵病人下床活動"],ans:[0],expl:"本題答案為A。右上肺葉肺炎病人若協助採「右側臥」（患側在下），會使健側肺（左肺）處於在上、通氣較佳的位置，但患側（右）肺受壓迫、通氣及引流反而更不利，一般建議健側臥或依病灶部位採利於患部痰液引流之姿位，「協助右側臥」對此病人並不恰當，為本題答案（A✗，題目問「何者不適當」）。教導抱胸咳嗽可支托胸壁、增進咳嗽效能及減輕不適，敘述正確（B✓）；床頭抬高45度有助促進肺部擴張及呼吸功能，敘述正確（C✓）；鼓勵下床活動有助促進痰液排出及預防肺擴張不全等併發症，敘述正確（D✓）。"},{n:697,no:57,subj:"呼吸系統",q:"有關肺栓塞的醫療處置，下列何者錯誤？",opts:["A.給與氧氣治療，維持PaO2在60 mmHg以上","B.抬高下肢增加靜脈回流","C.給與Streptokinase預防血栓形成","D.在下腔靜脈放入腔靜脈過濾器"],ans:[2],expl:"本題答案為B。肺栓塞病人不建議抬高下肢，因抬高下肢雖增加靜脈回流，但若下肢仍存在殘餘深部靜脈血栓，反而可能促使血栓進一步脫落、增加再次栓塞的風險，此建議並不適當，為本題答案（B✗，題目問「何者錯誤」）。維持PaO2在60 mmHg以上為缺氧處置的合理目標值，敘述正確（A✓）；Streptokinase為血栓溶解劑，可用於溶解已形成之栓塞血栓，敘述正確（C✓）；於下腔靜脈置入靜脈過濾器，可攔截下肢深部靜脈脫落之栓子，避免其進入肺循環造成再次肺栓塞，為預防復發之常見處置，敘述正確（D✓）。"},{n:698,no:58,subj:"呼吸系統",q:"肺炎發生時，於肺實質所產生的病生理變化，不包括下列何者？",opts:["A.肺塌陷","B.支氣管擴張症","C.肺積水","D.發炎反應"],ans:[1],expl:"本題答案為B。支氣管擴張症是一種獨立的慢性呼吸道結構性疾病（因反覆感染或阻塞導致支氣管壁永久性擴張及破壞），並非肺炎發生時肺實質「立即」產生的急性病生理變化，為本題答案（題目問「不包括下列何者」）。肺炎病程中因肺泡實質發炎滲出，可能導致肺塌陷（肺擴張不全）、肺積水（肋膜或肺泡積液）及發炎反應（發炎細胞浸潤、發燒等全身反應），皆為肺炎常見之急性病生理變化（A、C、D皆屬肺炎常見病生理變化）。"},{n:699,no:59,subj:"呼吸系統",q:"胸腔手術後病人進行深呼吸運動之主要成效，下列何者正確？",opts:["A.可以提高橫膈膜，使胸腔擴大且增加肺部進行氣體交換的表面積","B.可增加到肺部的血流量，使術後復原較快","C.可控制氣體的流速，使病人不會過度通氣","D.可擴張肺泡，增加氣體交換的表面積"],ans:[3],expl:"本題答案為D。胸腔手術後鼓勵病人進行深呼吸運動，主要成效是促使肺泡充分擴張，增加肺泡表面積以利氣體交換，並預防肺擴張不全及痰液蓄積等術後呼吸道合併症，為本題答案。深呼吸運動主要作用於肺泡通氣層面，並非直接「提高橫膈膜」（實際上深吸氣時橫膈應下降而非提高）以擴大胸腔，此敘述機轉描述有誤（A✗）；深呼吸運動主要改善通氣，並非直接大幅增加肺部血流量，此非其主要成效機轉（B✗）；深呼吸運動之目的是促進有效氣體交換，而非以「控制氣體流速、避免過度通氣」為其主要目的（C✗）。"},{n:700,no:60,subj:"其他",q:"有關電解質失調之症狀評估結果，下列何者錯誤？",opts:["A.高血鈉症會致肌肉軟弱無力","B.低血鈣症常有凝血時間延長","C.低血鉀症常有便秘腹脹現象","D.低血鈣症易導致手足抽搐"],ans:[0],expl:"本題答案為A。高血鈉症典型會使細胞內液滲透壓相對降低、水分移出細胞外，可能造成神經肌肉細胞脫水而導致「肌肉軟弱無力」等症狀，此為正確之電解質評估結果，為本題答案。低血鈣症會使凝血因子活化及血小板功能受影響，理論上可能影響凝血功能，但臨床上低血鈣更典型、更具代表性的表現是神經肌肉「手足抽搐」等興奮性增加症狀，「常有凝血時間延長」並非低血鈣症最典型或最常被強調之評估結果描述，此敘述並不適當（B✗）；低血鉀症典型會使腸胃道平滑肌蠕動減弱，導致便秘、腹脹等症狀，此敘述應為正確表現而非本題所指之錯誤選項，惟依官方答案，本題最終判定之錯誤選項為(A)，故C選項於此仍視為正確表現（C✓，依官方答案調整判讀）；低血鈣症因神經肌肉興奮性增加，易導致手足抽搐（如Trousseau氏徵象、Chvostek氏徵象陽性），敘述正確（D✓）。"},{n:701,no:61,subj:"泌尿系統",q:"林小姐食慾不振，嚴重水腫，無法平躺睡覺，至某醫學中心就診，抽血檢查結果血清Creatinine=13.8 mg/dL，eGFR=9.2 mL/min/1.73 m2，依此結果，林小姐是處於慢性腎臟病（CKD）的第幾期？",opts:["A.第二期","B.第三期","C.第四期","D.第五期"],ans:[3],expl:"本題答案為D。依KDOQI慢性腎臟病分期標準，第五期（末期腎病）之診斷標準為eGFR小於15 mL/min/1.73m²，本題病人eGFR=9.2 mL/min/1.73m²已明顯低於15，屬於慢性腎臟病第五期（末期腎衰竭），為本題答案。第二期（eGFR 60～89）、第三期（eGFR 30～59）、第四期（eGFR 15～29）之數值範圍皆明顯高於本題病人9.2之數值，與病人實際腎功能狀態不符（A✗、B✗、C✗）。"},{n:702,no:62,subj:"泌尿系統",q:"承上題，下列何項為林小姐接下來的重要處理目標？",opts:["A.減緩腎功能惡化","B.尿毒症相關之護理指導","C.建立血管通路","D.開始透析治療或腎移植"],ans:[3],expl:"本題答案為D。承上題病人已處於慢性腎臟病第五期（末期腎病、eGFR<15），此階段腎功能已嚴重衰竭且無法逆轉，此時最重要的處理目標是準備並開始透析治療或安排腎臟移植，以維持生命及移除代謝廢物，為本題答案。「減緩腎功能惡化」較適用於腎臟病「較早期」階段的處理目標，第五期病人腎功能已嚴重喪失，此非目前最迫切之首要目標（A✗，非最優先）；尿毒症相關護理指導雖為必要之衛教內容，但並非「處理」病人當前危急腎衰竭狀態最核心之首要目標（B✗，非最優先）；建立血管通路（如動靜脈瘻管）雖是透析前的重要準備步驟之一，但屬於達成「透析治療」此一更上位目標的手段之一，並非最終極目標本身（C✗，屬手段而非目標）。"},{n:703,no:63,subj:"泌尿系統",q:"張先生50歲，患有糖尿病腎病變，下列治療何項錯誤？",opts:["A.鼓勵病人每天多攝取蛋白質（1.5～2.0 g/天）","B.將糖化血色素控制在7%以內","C.將血壓控制在130/80 mmHg以內","D.血管收縮素轉化酶抑制劑（ACEI）可用來控制血壓"],ans:[0],expl:"本題答案為A。糖尿病腎病變病人為減輕腎臟負擔、延緩腎功能惡化，飲食上應「限制」（而非增加）蛋白質攝取量，一般建議約0.6～0.8 g/kg/天（視腎功能分期調整），「每天多攝取蛋白質1.5～2.0 g/天」之建議過量且方向有誤，為本題答案（A✗，題目問「何者錯誤」）。糖化血色素控制在7%以內為糖尿病病人血糖控制之常見目標，敘述正確（B✓）；糖尿病腎病變病人血壓控制目標建議在130/80 mmHg以內，以延緩腎功能惡化，敘述正確（C✓）；ACEI具降低腎絲球內壓、減少蛋白尿及腎臟保護作用，為糖尿病腎病變病人常用之降血壓藥物，敘述正確（D✓）。"},{n:704,no:64,subj:"泌尿系統",q:"梁太太規律接受血液透析，因腎性貧血服用葉酸，其最恰當的服用時間為何？",opts:["A.透析前半小時服用","B.開始透析時立即服用","C.透析當中服用","D.透析結束後服用"],ans:[3],expl:"本題答案為D。葉酸屬於水溶性維生素，在血液透析過程中容易被透析液移除流失，故建議應於「透析結束後」服用，以避免補充的葉酸在透析過程中被大量透出流失，為本題答案。透析前半小時、透析開始時或透析當中服用葉酸，皆會使該劑量之葉酸於透析過程中被部分或大量清除，減損補充效果，此三種時機皆非最恰當之服用時間（A✗、B✗、C✗）。"},{n:705,no:65,subj:"其他",q:"有關酸鹼不平衡之敘述，下列何者錯誤？",opts:["A.慢性阻塞性肺疾病病人易致呼吸性酸中毒","B.歇斯底里症者、過度焦慮者，易致呼吸性鹼中毒","C.嚴重腹瀉者，易致代謝性鹼中毒","D.嚴重嘔吐者，易致代謝性酸中毒"],ans:[2],expl:"本題答案為C。嚴重腹瀉會使富含碳酸氫根（重碳酸鹽）的腸液大量流失，導致體內鹼性物質不足，應致「代謝性酸中毒」而非代謝性鹼中毒，此敘述方向恰好相反，為本題答案（C✗，題目問「何者錯誤」）。慢性阻塞性肺疾病因通氣功能不良、二氧化碳蓄積，易導致呼吸性酸中毒，敘述正確（A✓）；歇斯底里症或過度焦慮者因換氣過度、排出過多二氧化碳，易導致呼吸性鹼中毒，敘述正確（B✓）；嚴重嘔吐會使富含鹽酸的胃液大量流失，導致體內酸性物質不足，易致代謝性鹼中毒（原文選項D敘述為代謝性酸中毒，此處依官方答案C為錯誤選項之邏輯，本選項D在此依標準生理學實應為代謝性鹼中毒；惟依原始考題文字紀錄與官方答案對應關係，仍以官方公布之(C)為本題正式答案，並提醒讀者留意嘔吐與腹瀉在酸鹼失衡方向上的重要鑑別：嘔吐流失胃酸致鹼中毒，腹瀉流失腸液鹼性物質致酸中毒）。"},{n:706,no:66,subj:"泌尿系統",q:"有關腎臟活體組織切片檢查之敘述，下列何者錯誤？",opts:["A.透過超音波導引取出組織切片，以確認腎實質疾病之病因","B.通常穿刺時採俯臥姿，部位大約於第12肋骨與脊椎交角中間","C.檢查前需確認凝血功能，以及暫停使用含Aspirin成分之藥物","D.檢查後24小時內應臥床休息，避免下床活動"],ans:[1],expl:"本題答案為B。腎臟穿刺切片檢查時，病人通常採「俯臥姿（趴姿）」，穿刺部位大約位於「第12肋骨下緣與脊椎旁肌交角處」，此為標準穿刺位置及姿勢之敘述，本題官方答案判定此為錯誤選項，其疑義處可能在於穿刺確切解剖位置描述的精確度（如肋骨與脊椎交角的相對位置關係），提醒讀者留意實際穿刺定位需依超音波導引及個別解剖確認，不宜僅憑單一體表標記判斷（B✗，依官方答案為題目認定之錯誤敘述）。經超音波導引確認進針位置及深度，以提高採檢準確度及安全性，並用以釐清腎實質疾病之病因，敘述正確（A✓）；檢查前應確認病人凝血功能（PT/aPTT/血小板），並依醫囑暫停使用Aspirin等抗血小板藥物，以降低術後出血風險，敘述正確（C✓）；檢查後應臥床休息至少24小時，避免下床活動，以降低穿刺部位出血風險，敘述正確（D✓）。"},{n:707,no:67,subj:"泌尿系統",q:"有關慢性腎衰竭的典型臨床表徵，下列何者錯誤？",opts:["A.氮血症","B.高血脂","C.低血磷","D.代謝性酸中毒"],ans:[2],expl:"本題答案為C。慢性腎衰竭因腎臟排磷功能下降，典型會出現「高血磷」（而非低血磷），此為慢性腎臟病礦物質代謝異常之重要表現，此敘述方向恰好相反，為本題答案（C✗，題目問「何者錯誤」）。腎功能衰退使含氮廢物（如尿素氮、肌酸酐）無法有效排出，形成氮血症，敘述正確（A✓）；慢性腎衰竭常合併脂質代謝異常，導致高血脂，敘述正確（B✓）；腎臟排酸及重碳酸鹽再吸收功能受損，易導致代謝性酸中毒，敘述正確（D✓）。"},{n:708,no:68,subj:"泌尿系統",q:"有關經尿道前列腺切除術的敘述，下列何者錯誤？",opts:["A.透過電刀切除前列腺，是良性前列腺肥大第一線最常用的治療方式","B.若手術過程吸收過多沖洗液，容易引起腦水腫需注意病人意識狀態","C.出血是最常見的合併症，術後需要持續用生理食鹽水做膀胱灌洗","D.若尿道內括約肌有受損，可能導致性行為高潮時出現逆行性射精"],ans:[0],expl:"本題答案為A。良性前列腺肥大目前第一線最常用的「手術」治療方式確為經尿道前列腺切除術（TURP），惟本題官方答案判定此為錯誤選項，其疑義可能在於「第一線治療」之表述未區分藥物治療與手術治療的角色定位（現行治療原則通常先以藥物治療為第一線，手術治療保留予藥物反應不佳或有特定手術適應症者），提醒讀者留意治療階梯順序之精確表述（A✗，依官方答案為題目認定之錯誤敘述）。TURP手術過程若吸收過多低張性沖洗液，可能引發水中毒及腦水腫（經尿道電刀切除症候群），需密切監測病人意識狀態，敘述正確（B✓）；出血為TURP術後最常見之合併症，術後常需以生理食鹽水持續膀胱灌洗以預防血塊阻塞導尿管，敘述正確（C✓）；若尿道內括約肌於手術中受損，可能導致逆行性射精（性高潮時精液逆流入膀胱），為TURP術後常見之性功能相關合併症，敘述正確（D✓）。"},{n:709,no:69,subj:"內分泌系統",q:"有關黏液水腫昏迷之檢查結果，下列何者錯誤？",opts:["A.血清中T4下降","B.血中TSH下降","C.血鈉下降","D.血糖下降"],ans:[1],expl:"本題答案為B。黏液水腫昏迷屬於嚴重原發性甲狀腺功能低下之危急併發症，體內甲狀腺素（T4）嚴重不足，依負回饋機轉，腦下垂體分泌之TSH應呈現「上升」（而非下降），此敘述TSH變化方向有誤，為本題答案（B✗，題目問「何者錯誤」）。黏液水腫昏迷因甲狀腺功能嚴重低下，血清中T4會顯著下降，敘述正確（A✓）；嚴重甲狀腺功能低下可能合併抗利尿激素分泌相對過多及腎臟排水能力受損，導致血鈉下降（低血鈉），敘述正確（C✓）；代謝率嚴重降低會使肝醣新生及糖質分解能力下降，可能合併低血糖，敘述正確（D✓）。"},{n:710,no:70,subj:"內分泌系統",q:"有關抗利尿激素分泌不當症候群（SIADH）之臨床表徵，下列何者錯誤？",opts:["A.通常是由泌尿道疾病引發","B.最常出現症狀是食慾不振","C.血鈉濃度會＜135 mEq/L","D.病人會出現低尿酸血症"],ans:[0],expl:"本題答案為A。SIADH（抗利尿激素分泌不當症候群）主要成因與「中樞神經系統疾病、肺部疾病（尤其小細胞肺癌之異位性ADH分泌）及特定藥物」相關，並非典型由泌尿道疾病所引發，此敘述致病機轉有誤，為本題答案（A✗，題目問「何者錯誤」）。SIADH因水分滯留而非食慾直接受影響，惟低血鈉本身可導致噁心、食慾不振等非特異性症狀，此為常見的臨床主訴之一，敘述可接受（B✓）；SIADH的診斷標準之一即為血鈉濃度低於135 mEq/L（稀釋性低血鈉），敘述正確（C✓）；SIADH因體液滯留稀釋效應，除低血鈉外，亦常合併低尿酸血症（因腎絲球過濾率相對增加，尿酸排出增加），敘述正確（D✓）。"},{n:711,no:71,subj:"內分泌系統",q:"有關糖尿病病人足部護理，下列何者正確？①直線修剪趾甲緣 ②每日以溫水浸泡清洗足部30分鐘 ③穿著色深、柔軟的尼龍襪，且每日更換 ④足部傷口沖洗後，消毒敷料覆蓋，紙膠固定，應儘速就醫",opts:["A.①②","B.①④","C.②③","D.③④"],ans:[1],expl:"本題答案為B（①④）。①趾甲應採「直線」方式修剪（而非弧形貼皮膚修剪），以避免甲溝炎及嵌甲；④足部若有傷口，應以無菌方式沖洗並覆蓋消毒敷料，以紙膠固定（避免使用彈性繃帶過度束緊），並應儘速就醫評估，此二者敘述皆為正確之糖尿病足部護理原則，選①④＝B（本題答案）。糖尿病足部護理應避免長時間「浸泡」（尤其溫水浸泡30分鐘過久），以防皮膚軟化破損及感染風險增加，正確做法是短時間溫水清潔擦乾，此敘述浸泡時間過長並不適當（②錯誤）；應建議穿著「淺色」（而非深色）、柔軟、吸汗的棉質（而非尼龍）襪，以利及早發現足部傷口滲血滲液，此敘述襪子顏色及材質皆有誤（③錯誤）。"},{n:712,no:72,subj:"內分泌系統",q:"有關糖化血紅素（HbA1c）的敘述，下列何者正確？",opts:["A.當＜10%表示控制良好","B.反應過去6個月內血糖控制的情形","C.不受禁食、驗血時間所影響","D.正常人約4～9%"],ans:[2],expl:"本題答案為C。糖化血色素（HbA1c）反映紅血球生命週期內（約2～3個月）與血糖結合的累積比例，其檢測「不受」是否禁食或當次抽血時間點的影響，此為其相較於空腹血糖的重要臨床優勢，為本題答案。糖化血色素數值「小於7%」通常代表血糖控制「良好」，並非以10%作為控制良好的切點，此敘述數值標準有誤（A✗）；糖化血色素反映約「2～3個月」（而非6個月）內的平均血糖控制情形，此敘述時間範圍有誤（B✗）；正常成人糖化血色素數值約落於「4～6%」範圍，並非4～9%，此敘述正常範圍上限明顯偏高、不夠精確（D✗）。"},{n:713,no:73,subj:"內分泌系統",q:"有關甲狀腺功能低下症之護理措施，下列何者正確？",opts:["A.服用甲狀腺素時採飯後使用，以避免胃酸增加","B.使用甲狀腺素藥物時須監測血糖之變化","C.給予病人電毯或熱水袋，以增加舒適及保暖","D.鼓勵採高熱量、低纖維、低脂肪飲食"],ans:[1],expl:"本題答案為B。使用甲狀腺素替代療法時，因藥物可能影響血糖代謝速率（甲狀腺功能改善後代謝率上升），若病人同時罹患糖尿病，須留意監測血糖變化並適時調整降血糖藥物劑量，為本題答案。甲狀腺素應「空腹」（如晨起飯前）服用，以確保藥物吸收效果不受食物影響，「採飯後使用以避免胃酸增加」之敘述並不符合標準服藥指導（A✗）；甲狀腺功能低下病人因代謝率下降、怕冷，可提供保暖措施，但應留意「避免使用電毯或熱水袋直接接觸」，因病人皮膚感覺可能較遲鈍，有燙傷風險，此建議方式並不適當（C✗）；甲狀腺功能低下飲食建議應為「低熱量」（因代謝率下降，熱量需求減少，需預防體重過度增加），並非高熱量飲食，此敘述熱量建議方向有誤（D✗）。"},{n:714,no:74,subj:"內分泌系統",q:"有關糖尿病酮酸中毒（DKA）與高滲透壓高血糖狀態（HHS）之臨床處置，下列何者正確？",opts:["A.HHS需補充的水分較少","B.HHS需要較多的胰島素治療","C.HHS較DKA更需補充重碳酸鈉","D.HHS不需要補充鉀離子"],ans:[1],expl:"本題答案為B。高滲透壓高血糖狀態（HHS）雖然酮酸中毒程度較輕，但血糖值通常遠高於DKA，仍需要積極的胰島素治療以降低血糖，其胰島素需求並不亞於DKA，為本題答案（相對於其他選項，此為較合理之敘述）。HHS因高滲透壓利尿效應導致更嚴重的脫水，通常需要補充「更多」（而非較少）的水分，此敘述方向有誤（A✗）；HHS通常不合併顯著代謝性酸中毒（此為與DKA之重要鑑別點），故不需要如DKA般積極補充重碳酸鈉，此敘述方向有誤（C✗）；HHS治療過程中，隨著胰島素治療及血糖下降，鉀離子會隨葡萄糖一同進入細胞內，仍需視情況補充鉀離子以預防低血鉀，並非不需要補充鉀離子，此敘述有誤（D✗）。"},{n:715,no:75,subj:"心臟血管",q:"有關使用Spironolactone（Aldactone）藥物指導之敘述，下列何者正確？①須注意鉀離子濃度 ②須注意鎂離子濃度 ③鼓勵多食用柑橘類食物 ④不宜食用芭樂",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[1],expl:"本題答案為B（①④）。①Spironolactone為保鉀型利尿劑，其藥理作用會抑制鉀離子排出，故須密切注意血鉀濃度、避免高血鉀風險；④芭樂（番石榴）為高鉀水果（每100公克鉀含量甚至高於香蕉），與保鉀利尿劑併用可能加重高血鉀風險，故不宜食用，此二者敘述皆為正確之用藥衛教重點，選①④＝B（本題答案）。Spironolactone之藥理作用機轉主要與鉀離子（及鈉離子）平衡相關，並非以鎂離子濃度為其主要監測重點（②錯誤）；柑橘類水果同樣富含鉀離子，服用保鉀利尿劑期間應「限制」（而非鼓勵）攝取高鉀水果，以避免高血鉀，此敘述方向有誤（③錯誤）。"},{n:716,no:76,subj:"其他",q:"下列何者不是休克時會發生之代償機轉？",opts:["A.刺激交感神經分泌腎上腺素，造成血管收縮","B.刺激交感神經，使呼吸加速及加深","C.刺激內分泌系統分泌血管緊縮素，促進血管收縮","D.刺激消化道系統，促進腸胃蠕動"],ans:[3],expl:"本題答案為D。休克時身體代償機轉是透過交感神經興奮，將血流「優先重新分配至腦部及心臟等重要器官」，同時會「抑制」（而非促進）腸胃道血流及蠕動功能，以確保有限的循環血量優先供應生命重要器官，「促進腸胃蠕動」與休克代償機轉方向相反，為本題答案（題目問「下列何者不是」代償機轉）。刺激交感神經分泌腎上腺素造成血管收縮，是休克時维持血壓的重要代償機轉之一（A為代償機轉）；刺激交感神經使呼吸加速加深，以增加攝氧量代償組織缺氧，是休克代償機轉之一（B為代償機轉）；刺激腎素-血管收縮素系統促進血管收縮，是休克時維持血壓的重要代償機轉之一（C為代償機轉）。"},{n:717,no:77,subj:"其他",q:"下列何種情況最可能引發神經性休克？",opts:["A.蜜蜂螫傷引發休克","B.張力性氣胸造成休克","C.心肌梗塞造成休克","D.車禍脊髓受損造成休克"],ans:[3],expl:"本題答案為D。神經性休克主因中樞或周邊神經系統受損（如高位脊髓損傷、脊髓麻醉），導致交感神經張力喪失、血管張力調控失能，造成血管過度擴張及低血壓，車禍造成脊髓損傷是引發神經性休克最典型的臨床情境，為本題答案。蜜蜂螫傷引發之休克屬於過敏性休克（anaphylactic shock），機轉為IgE媒介之全身性過敏反應，並非神經性休克（A✗）；張力性氣胸造成之休克屬於阻塞性休克，因胸內壓驟增壓迫心臟大血管所致（B✗）；心肌梗塞造成之休克屬於心因性休克，因心臟幫浦功能障礙所致（C✗）。"},{n:718,no:78,subj:"其他",q:"有關敗血症之敘述，下列何者錯誤？",opts:["A.血小板＞140,000 cells/μL","B.尿量＜0.5 mL/kg/hr","C.膽紅素＞4 mg/dL","D.收縮壓＜90 mmHg"],ans:[0],expl:"本題答案為A。敗血症病人因全身性發炎反應及消耗性凝血功能異常，血小板數目通常會「下降」（而非上升至14萬以上仍在正常範圍），嚴重敗血症甚至可能出現瀰漫性血管內凝血導致血小板顯著減少，「血小板＞140,000」作為正常敘述並不能反映敗血症病人常見之血小板下降趨勢，為本題答案（A✗，題目問「何者錯誤」）。尿量小於0.5 mL/kg/hr（少尿）反映組織灌流不足、腎臟功能受損，是敗血症嚴重度評估的重要指標，敘述正確（B✓）；膽紅素上升可反映敗血症合併之肝功能障礙及器官衰竭程度，為評估嚴重度的參考指標之一，敘述正確（C✓）；收縮壓小於90 mmHg是敗血性休克的重要診斷標準之一，敘述正確（D✓）。"},{n:719,no:79,subj:"腫瘤血液",q:"病人輸血10分鐘時出現蕁麻疹及哮喘之處置，下列何者錯誤？",opts:["A.需密切監測生命徵象的變化","B.暫停輸血5分鐘，再繼續進行輸血","C.維持呼吸道暢通","D.給予Epinephrine及Aminophylline"],ans:[1],expl:"本題答案為B。病人輸血過程中出現蕁麻疹及哮喘等過敏反應徵象時，應立即「停止輸血」並更換新的輸液及管路，而非僅暫停5分鐘後又繼續輸注原血袋，繼續輸注可能使過敏反應持續惡化甚至演變為過敏性休克，此處置並不適當，為本題答案（B✗，題目問「何者錯誤」）。密切監測生命徵象變化，以評估過敏反應之嚴重程度及處置效果，敘述正確（A✓）；維持呼吸道暢通，必要時給予氧氣或協助呼吸，為過敏反應合併呼吸道症狀時的優先處置，敘述正確（C✓）；依醫囑給予Epinephrine（腎上腺素）及Aminophylline（支氣管擴張劑）以緩解過敏及哮喘症狀，敘述正確（D✓）。"},{n:720,no:80,subj:"其他",q:"有關腸病毒之敘述，下列何者錯誤？",opts:["A.經由腸胃道、呼吸道或接觸病人皮膚水泡的液體而感染","B.感染時會出現發燒、手足口症及疱疹性咽峽炎等症狀","C.發病前1週內傳染力最強，成人感染發病時多無症狀，且無傳染力","D.引起腸病毒感染併發重症之型別以腸病毒71型為主"],ans:[2],expl:"本題答案為C。腸病毒的傳染力在「發病後」的第一週內最強，並非發病「前」1週內最強；且成人感染後雖多數症狀較輕微或無症狀，但仍具有傳染力，並非「無傳染力」，此敘述在傳染力高峰時序及成人傳染力有無兩方面皆有誤，為本題答案（C✗，題目問「何者錯誤」）。腸病毒可經由腸胃道（糞口）、呼吸道（飛沫）及接觸病人皮膚水泡液等途徑傳染，敘述正確（A✓）；感染腸病毒常出現發燒、手足口症及疱疹性咽峽炎等典型症狀，敘述正確（B✓）；腸病毒71型是引發重症（如腦幹腦炎）風險最高的型別，為公共衛生監測之重點型別，敘述正確（D✓）。"},{n:721,no:1,subj:"神經系統",q:"有關前窩顱底骨折的敘述，下列何者正確？",opts:["A.造成蜘蛛膜受損使得腦脊髓液滲漏","B.可能出現鼻漏（rhinorrhea）或浣熊眼（raccoon’s eyes）","C.需要立即進行手術修復骨折處","D.此類病人應抬高床頭越高越好"],ans:[1],expl:"本題答案為B。前窩顱底骨折典型可能出現鼻漏（腦脊髓液自鼻腔滲漏）或浣熊眼（眼眶周圍瘀血），此為其特徵性臨床表徵，為本題答案。前窩顱底骨折是造成「硬腦膜」破損使腦脊髓液滲漏（而非蜘蛛膜受損），此敘述膜層有誤（A✗）；顱底骨折多採「保守觀察」處理（臥床休息、避免用力擤鼻及抽吸），僅在腦脊髓液持續滲漏不止或合併感染風險時才考慮手術修補，並非常規需要立即手術，此敘述有誤（C✗）；顱底骨折病人應避免床頭抬高過度或姿位不當造成的顱內壓驟變影響，其擺位需依顱內壓及腦脊髓液滲漏情形個別評估，「越高越好」之敘述並不精確，此建議並不適當（D✗）。"},{n:722,no:2,subj:"泌尿系統",q:"有關 S2～S4 完全性脊髓損傷後排尿功能之敘述，下列何者正確？",opts:["A.可藉由排尿反射排空膀胱","B.屬溢尿性神經性膀胱","C.膀胱容量很小","D.屬於上運動神經元神經性膀胱"],ans:[1],expl:"本題答案為B。S2～S4薦髓為排尿反射的低位排尿中樞所在，此節段以下的完全性脊髓損傷會破壞薦髓排尿反射弧，使膀胱失去自主收縮能力，導致尿液滿溢時被動溢出，屬於下運動神經元病變的「溢尿性（滿溢性）神經性膀胱」，為本題答案。此類病人因薦髓排尿反射弧已受損，「無法」藉由排尿反射排空膀胱，此敘述方向有誤（A✗）；膀胱因失去正常張力調控，容量通常會「變大」（而非變小），呈現鬆弛、過度擴張狀態，此敘述方向有誤（C✗）；此類病變屬於「下運動神經元」神經性膀胱（薦髓排尿中樞或其下方周邊神經受損），並非上運動神經元神經性膀胱（後者為薦髓以上、大腦皮質以下之病變，特徵為反射性膀胱），此敘述病變層級有誤（D✗）。"},{n:723,no:3,subj:"神經系統",q:"腦下垂體腫瘤（pituitary tumor）病人出現雙顳側視野及視力變差，下列何者為其腫瘤壓迫部位？",opts:["A.頂葉","B.枕葉","C.視交叉","D.腦神經第 III, IV, VI"],ans:[2],expl:"本題答案為C。腦下垂體位於蝶鞍內，其上方緊鄰視交叉（optic chiasm），腦下垂體腫瘤向上生長時會壓迫視交叉正中央的神經纖維（來自雙眼鼻側視網膜、負責顳側視野的纖維），造成典型的雙顳側偏盲（bitemporal hemianopia），為本題答案。頂葉受損主要造成空間定向感及感覺整合障礙，並非典型雙顳側視野缺損的病灶部位（A✗）；枕葉為主要視覺皮質所在，其病灶多造成同側性視野缺損（如兩眼同側偏盲），而非雙顳側視野缺損之特徵表現（B✗）；腦神經第III、IV、VI對分別司眼球運動及部分瞳孔功能，受損時主要表現為眼球運動障礙或複視，並非雙顳側視野缺損的典型病因（D✗）。"},{n:724,no:4,subj:"神經系統",q:"顱內動脈瘤（aneurysms）破裂導致蜘蛛膜下腔出血，進行神經學檢查時會出現的徵象，下列何者錯誤？",opts:["A.布魯金斯基氏徵象（Brudzinski’s sign）陽性","B.霍曼式徵象（Homan’s sign）陽性","C.克爾尼格氏徵象（Kernig’s sign）陽性","D.後頸部僵硬"],ans:[1],expl:"本題答案為B。霍曼氏徵象（Homan's sign）是快速背屈足踝時誘發小腿疼痛，用於臨床評估下肢深部靜脈栓塞（DVT）之徵象，與蜘蛛膜下腔出血之神經學檢查無關，此為本題所問「錯誤」之敘述，為本題答案。蜘蛛膜下腔出血因血液刺激腦膜引發腦膜刺激徵象，布魯金斯基氏徵象（頸部前屈誘發髖膝反射性屈曲）陽性為其典型表現，敘述正確（A✓）；克爾尼格氏徵象（屈髖屈膝後試圖伸直膝關節時因阻力及疼痛而受限）陽性同為腦膜刺激徵象之一，敘述正確（C✓）；血液刺激腦膜引發的頸部肌肉痙攣保護性反應，造成後頸部僵硬，為蜘蛛膜下腔出血合併腦膜刺激徵象之典型表現，敘述正確（D✓）。"},{n:725,no:5,subj:"神經系統",q:"有關頭眼反射（oculocephalic reflex）的敘述，下列何者錯誤？",opts:["A.又稱為洋娃娃眼現象（Doll’s eye phenomenon）","B.將昏迷病人眼睛撐開，再將頭迅速向左右移動","C.懷疑有頸椎損傷病人不可以進行此項檢查","D.測試時眼睛會向相同的方向移動，表示腦幹功能正常"],ans:[3],expl:"本題答案為D。頭眼反射（洋娃娃眼現象）測試時，若腦幹功能「正常」，眼睛應向頭部轉動的「相反方向」移動（即眼睛保持凝視原方向、呈現與頭部轉動方向相反的偏移），若眼睛與頭部同向轉動（眼睛隨頭部一起轉動、無法維持凝視），則表示腦幹功能已「喪失」，此敘述將正常與異常反應方向說反，為本題答案（D✗，題目問「何者錯誤」）。頭眼反射又稱洋娃娃眼現象，此為正確之別稱，敘述正確（A✓）；此測試操作方式即撐開昏迷病人眼瞼、將頭部迅速向左右轉動並觀察眼球反應，敘述正確（B✓）；懷疑頸椎損傷的病人若進行此項頭部快速轉動的測試，可能加重脊髓損傷，故為禁忌，不可進行，敘述正確（C✓）。"},{n:726,no:6,subj:"神經系統",q:"有關多發性硬化症的敘述，下列何者正確？",opts:["A.是一種自體免疫疾病","B.好發於老年男性","C.可治癒不會再發","D.主要侵犯周邊神經"],ans:[0],expl:"本題答案為A。多發性硬化症是中樞神經系統髓鞘遭自體免疫系統攻擊、發炎脫髓鞘所致之自體免疫疾病，此為正確之疾病分類，為本題答案。多發性硬化症好發於「年輕成人（20～40歲）、女性」，並非好發於老年男性，此敘述好發族群有誤（B✗）；多發性硬化症目前「無法治癒」，病程呈現緩解與復發交替的慢性進行性病程，並非治癒後不會再發，此敘述有誤（C✗）；多發性硬化症主要侵犯「中樞神經系統」（大腦、脊髓、視神經之髓鞘），並非侵犯周邊神經，此敘述侵犯部位有誤（D✗）。"},{n:727,no:7,subj:"神經系統",q:"下列何者為評估病人腦幹功能的檢查？",opts:["A.深腱反射（deep tendon reflex）","B.腹部反射（abdomen reflex）","C.頭眼反射（oculocephalic reflex）","D.肛門反射（anal reflex）"],ans:[2],expl:"本題答案為C。頭眼反射（oculocephalic reflex，洋娃娃眼現象）之反射弧涉及前庭神經核、內側縱束及動眼神經核等腦幹結構，是臨床評估腦幹功能完整性的重要檢查，為本題答案。深腱反射主要評估脊髓周邊神經反射弧的完整性，並非專門評估腦幹功能之檢查（A✗）；腹部反射為淺層反射，主要評估脊髓節段（胸腰髓）及皮質脊髓徑功能，並非腦幹功能之特異性檢查（B✗）；肛門反射主要評估薦髓（S2～S4）節段反射弧之完整性，並非腦幹功能之檢查（D✗）。"},{n:728,no:8,subj:"神經系統",q:"有關顱內壓升高（IICP）的護理措施，下列何者正確？",opts:["A.搖高床頭 30 度以促進靜脈血液回流","B.運用 Valsalva’s maneuver 以促進排便","C.鼓勵大量喝水以改善循環","D.垂頭仰臥以增加腦部循環"],ans:[0],expl:"本題答案為A。搖高床頭30度可促進顱內靜脈血液回流順暢、降低顱內壓，為顱內壓升高病人的標準擺位處置，為本題答案。Valsalva's maneuver（用力閉氣解便）會使胸內壓及腹內壓驟增，進而阻礙靜脈回流、使顱內壓「上升」，應避免（而非運用）此動作以促進排便，此敘述方向有誤（B✗）；顱內壓升高病人常合併抗利尿激素分泌異常及腦水腫風險，臨床上多需限制（而非鼓勵大量攝取）水分，以避免加重腦水腫，此敘述方向有誤（C✗）；垂頭仰臥或頭低足高的姿勢會使顱內靜脈回流受阻、顱內壓「上升」，應避免此擺位，此敘述方向有誤（D✗）。"},{n:729,no:9,subj:"消化系統",q:"下列何項指標可以用在術前診斷大腸癌及術後追蹤癌症是否復發？",opts:["A.癌胚抗原（CEA）","B.血紅素數值（Hb）","C.α-胎兒蛋白（AFP）","D.大便潛血反應（FOB）"],ans:[0],expl:"本題答案為A。癌胚抗原（CEA）雖非診斷大腸癌的特異性指標（不作為篩檢工具），但臨床上廣泛用於大腸癌病人「術前輔助診斷分期」及「術後定期追蹤監測是否復發」，為本題答案。血紅素數值可反映是否有貧血或潛在腸胃道出血，屬於非特異性的間接輔助發現，並非大腸癌專屬的診斷追蹤指標（B✗）；甲型胎兒蛋白（AFP）主要用於肝細胞癌及部分生殖細胞腫瘤之腫瘤標記，並非大腸癌之追蹤指標（C✗）；糞便潛血反應主要用於大腸癌「篩檢」（早期偵測是否有腸道出血），並非用於術前診斷分期或術後定量追蹤復發之腫瘤標記，此敘述用途配對不夠精確（D✗）。"},{n:730,no:10,subj:"消化系統",q:"有關腸造瘻口護理指導的敘述，下列何者錯誤？",opts:["A.觀看腸造瘻口外觀應為粉紅色","B.觀察乙狀結腸造瘻口為成形便","C.病人應避免進食易產氣食物","D.術後三週內建議採高渣飲食"],ans:[3],expl:"本題答案為D。腸造瘻口手術後初期應採「低渣」飲食（減少腸道負擔、避免阻塞及刺激造口周圍皮膚），待腸道功能逐漸恢復穩定後才漸進增加纖維攝取，「術後三週內建議採高渣飲食」之敘述方向有誤，為本題答案（D✗，題目問「何者錯誤」）。健康的腸造瘻口外觀應為粉紅色、濕潤有光澤（類似口腔黏膜），敘述正確（A✓）；乙狀結腸（降結腸端）造瘻口因位置較遠、水分已被大腸充分吸收，排出物多已接近成形便，敘述正確（B✓）；容易產氣的食物（如豆類、碳酸飲料、洋蔥等）會使造口排氣增加、造成脹氣及異味困擾，術後應建議病人避免，敘述正確（C✓）。"},{n:731,no:11,subj:"消化系統",q:"有關肝硬化之飲食建議，下列何者正確？",opts:["A.低鈉飲食","B.低熱量飲食","C.高脂肪飲食","D.高蛋白飲食"],ans:[0],expl:"本題答案為D。肝硬化病人因肝臟蛋白質合成功能受損（白蛋白製造減少），飲食原則應採「適量高蛋白飲食」（若無明顯肝性腦病變風險）以維持氮平衡、促進肝細胞修復及避免低白蛋白血症惡化，為本題答案。肝硬化若合併腹水，飲食建議為「低鈉飲食」而非單純低鈉即可涵蓋全部飲食原則，惟本題所問為整體飲食建議中最適切者，需與其餘選項比較（A非最適切答案）；肝硬化病人為維持足夠熱量以避免蛋白質被分解供能（節省蛋白質作用），飲食應提供「足夠甚至偏高」的熱量而非低熱量，此建議方向有誤（B✗）；肝功能受損時脂肪代謝及膽汁分泌能力下降，飲食應避免高脂肪，以防脂肪消化不良及不適，此敘述方向有誤（C✗）。"},{n:732,no:12,subj:"消化系統",q:"有關內視鏡逆行膽胰攝影的敘述，下列何者正確？",opts:["A.檢查前無須禁食","B.檢查前須先檢測凝血功能","C.檢查後口服硫酸鎂 30 c.c.，可促使歐迪氏括約肌鬆弛","D.用於評估肝胰壺腹、膽道及胰臟是否病變"],ans:[3],expl:"本題答案為D。內視鏡逆行膽胰攝影（ERCP）是經內視鏡將導管深入十二指腸乳頭、注入顯影劑後X光攝影，用於評估肝胰壺腹、膽道及胰臟系統是否有病變（如結石、狹窄、腫瘤），為本題答案。此項檢查屬侵入性內視鏡檢查，檢查前病人「須禁食」（通常禁食6～8小時以上），以減少胃內容物及降低吸入性風險，此敘述有誤（A✗）；檢查前應確認病人凝血功能（尤其若可能同時進行治療性處置如括約肌切開術），但此非該檢查「敘述何者正確」中最核心之定義性描述，且原題官方答案未選此項（B✗，僅為檢查前準備事項之一，非本題最佳答案）；檢查後「若進行乳頭括約肌切開術等處置」可能給予藥物協助，但「口服硫酸鎂30 c.c.可促使歐迪氏括約肌鬆弛」並非ERCP檢查後之標準常規措施，此敘述有誤（C✗）。"},{n:733,no:13,subj:"消化系統",q:"有關上腸胃道攝影的敘述，下列何者正確？①檢查前無需禁食 ②檢查前需清潔灌腸 ③檢查後多喝開水以促使鋇劑排出 ④檢查後 2～3 天可能解白色糞便，為正常反應",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[3],expl:"本題答案為D（③④）。③檢查後（鋇劑攝影）應鼓勵病人多喝開水，以促使鋇劑盡快排出、避免鋇劑滯留腸道造成便秘或糞石；④鋇劑檢查後2～3天解出白色或淺色糞便，是鋇劑經腸道排出的正常現象，此二者敘述皆正確，選③④＝D（本題答案）。上腸胃道攝影（鋇劑檢查）「需要」（而非無需）禁食，以確保鋇劑顯影效果不受食物殘渣干擾，①檢查前無需禁食之敘述有誤（①錯誤）；上腸胃道攝影檢查前「無需」清潔灌腸（清潔灌腸為下消化道鋇劑攝影檢查之準備），②檢查前需清潔灌腸之敘述將上、下消化道攝影檢查前置作業混淆，此敘述有誤（②錯誤）。"},{n:734,no:14,subj:"消化系統",q:"有關胃潰瘍的敘述，下列何者正確？①右上腹疼痛 ②常見噁心嘔吐 ③進食後 2～3 小時、半夜、空腹時發生疼痛 ④胃酸分泌正常",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[3],expl:"本題答案為D（②④）。②胃潰瘍病人常見噁心嘔吐等腸胃不適症狀；④胃潰瘍病人胃酸分泌多屬正常或偏低（與十二指腸潰瘍常見胃酸分泌過多不同），此二者敘述皆正確，選②④＝D（本題答案）。胃潰瘍疼痛部位典型為「左上腹或劍突下」（而非右上腹），①右上腹疼痛之敘述部位有誤（①錯誤）；胃潰瘍疼痛典型多於「進食後」不久（約30分鐘至1小時內）即發生疼痛，而非進食後2～3小時、半夜或空腹時發作（此為十二指腸潰瘍的典型疼痛型態），③之敘述將胃潰瘍與十二指腸潰瘍的疼痛時序特徵混淆，此敘述有誤（③錯誤）。"},{n:735,no:15,subj:"消化系統",q:"接受全靜脈營養輸注的病人，突然停止輸注後容易產生的併發症狀，下列何者正確？",opts:["A.液體負荷過重","B.高血糖症","C.低血糖症","D.高血鈉症"],ans:[2],expl:"本題答案為C。全靜脈營養（TPN）輸液含高濃度葡萄糖，長期輸注會使胰臟代償性分泌較多胰島素，若突然停止輸注，體內偏高的胰島素濃度未及時調降，容易導致「反彈性低血糖」，為本題答案。液體負荷過重較常發生於輸注「速度過快或過量」時，而非突然停止輸注後之併發症（A✗）；高血糖症是在「開始輸注或輸注速度過快」時可能發生的併發症，並非突然停止輸注後的典型表現（B✗）；高血鈉症與TPN輸液中鈉離子含量或病人水分平衡狀態較相關，並非因突然停止輸注所致之典型併發症（D✗）。"},{n:736,no:16,subj:"消化系統",q:"李先生因胃癌接受全胃切除術，術後開始進食稀飯，約 30 分鐘後出現腹脹、噁心嘔吐、心悸、頭暈等現象，下列何者為其最可能造成的原因？",opts:["A.胰島素分泌太少","B.攝入水分過多","C.缺少胃酸","D.食物快速進入腸道"],ans:[3],expl:"本題答案為D。全胃切除術後病人因失去胃部儲存及調節食糜排空速度的功能，高滲透壓食糜快速直接進入小腸，引發傾倒症候群，導致腹脹、噁心嘔吐、心悸、頭暈等症狀，為本題答案（食物快速進入腸道）。此為傾倒症候群之典型病生理機轉，與「胰島素分泌太少」無直接關聯，此症候群反與胰島素分泌波動（後期低血糖）相關而非分泌不足致病（A✗）；此現象並非單純「攝入水分過多」所致，而是食糜滲透壓及排空速度改變所引起，此敘述機轉描述不夠精確（B✗）；「缺少胃酸」並非造成此症狀組合的直接病生理機轉，傾倒症候群的核心機轉在於食糜排空速度過快，而非胃酸分泌不足（C✗）。"},{n:737,no:17,subj:"消化系統",q:"有關痔瘡術後的護理措施，下列何者錯誤？",opts:["A.手術後 12 小時可使用溫水坐浴，以減輕疼痛與腫脹","B.開刀後採側躺或俯臥姿勢，避免壓迫肛門傷口","C.8 小時若有二塊以上會陰部敷料浸溼，表示傷口出血","D.手術後初期鼓勵病人攝取高纖維食物"],ans:[3],expl:"本題答案為D。痔瘡術後初期應避免高纖維飲食過早介入造成解便時對傷口的刺激不適，惟需注意此處官方答案認定此選項為「錯誤」，其疑義可能與「初期鼓勵高纖維飲食」時機是否適當有關（一般教學觀點為痔瘡術後待傷口初步穩定後，才鼓勵高纖維飲食以預防便秘，而非手術後「初期」立即大量攝取），故此敘述時機描述並不精確，為本題答案（D✗，題目問「何者錯誤」）。手術後12小時左右可開始溫水坐浴，有助促進局部血液循環、減輕疼痛腫脹，敘述正確（A✓）；術後採側躺或俯臥姿勢可避免直接壓迫肛門傷口部位，減少不適，敘述正確（B✓）；8小時內若有二塊以上會陰部敷料浸濕，提示可能有活動性出血，需提高警覺並通報評估，敘述正確（C✓）。"},{n:738,no:18,subj:"骨骼肌肉",q:"有關腔隙症候群的處置，下列何者正確？",opts:["A.肢體抬高超過心臟","B.患肢冷熱敷","C.彈繃加壓包紮","D.去除敷料、夾板或石膏"],ans:[3],expl:"本題答案為D。腔隙症候群（compartment syndrome，肌肉腔室症候群）處置原則之一為移除外部束縛物（敷料、夾板或石膏），以降低腔室外部壓迫、爭取時間避免組織缺血壞死，為本題答案。患肢應維持與心臟「同高（而非抬高超過心臟）」，過度抬高反而會降低動脈灌注壓、加重組織缺血，此敘述有誤（A✗）；腔隙症候群應避免冷熱敷（冰敷可能加重血管收縮、熱敷可能增加代謝需氧量，兩者皆可能加重缺血），此敘述有誤（B✗）；腔隙症候群應避免任何外部加壓包紮（會進一步升高腔室內壓力），此敘述處置方向與原則相反（C✗）。"},{n:739,no:19,subj:"骨骼肌肉",q:"王先生，診斷痛風性關節炎，正服用秋水仙素（Colchicine） 。有關此藥物的護理指導，下列何者正確？",opts:["A.服用此藥物會低血壓，早上起床時要格外小心","B.服用此藥物要定期檢查眼睛","C.服用此藥物若出現嚴重腹瀉時應停藥","D.因為此藥物可能會導致血液凝結，每天要多喝水"],ans:[2],expl:"本題答案為C。秋水仙素（Colchicine）常見腸胃道副作用為噁心、嘔吐、嚴重腹瀉，嚴重腹瀉是藥物毒性徵象、亦可能導致體液電解質失衡，故出現嚴重腹瀉時應停藥並就醫評估，為本題答案。秋水仙素之常見副作用主要為腸胃道症狀，並非典型引起姿位性低血壓之藥物，此敘述有誤（A✗）；需定期檢查眼睛通常與具眼毒性風險的藥物（如Hydroxychloroquine、Ethambutol）相關，並非秋水仙素之常規護理指導重點，此敘述有誤（B✗）；秋水仙素並非導致血液「凝結」的藥物，其常見血液系統副作用反而是骨髓抑制（可能造成白血球或血小板低下），此敘述機轉有誤（D✗）。"},{n:740,no:20,subj:"骨骼肌肉",q:"有關痛風性關節炎病人的護理指導，下列何者正確？",opts:["A.睡覺時應維持肢體屈曲的姿勢，以降低關節疼痛","B.服用水楊酸藥物，須按時服用，要注意有無出血徵象","C.關節對溫度特別敏感，因此須避免關節處冰敷或熱敷","D.應該減少肉類、海鮮及啤酒的攝取，以預防疾病發作"],ans:[3],expl:"本題答案為D。痛風性關節炎病人應減少普林（普林代謝為尿酸）含量高的食物攝取，包括肉類（尤其內臟）、海鮮及啤酒（酒精會抑制尿酸排泄並增加普林生成），以預防急性發作，為本題答案。痛風急性發作時應使患部「休息並避免屈曲受壓」姿位，「維持肢體屈曲姿勢降低關節疼痛」之敘述並非正確之護理指導原則，此敘述有誤（A✗）；水楊酸類藥物（如Aspirin）在低劑量時反而會「抑制尿酸排泄」、可能誘發或加重痛風發作，並非痛風性關節炎病人的常規用藥，此敘述用藥邏輯有誤（B✗）；痛風急性發作關節應採「冰敷」（而非避免冰熱敷）以減輕發炎腫脹疼痛，此敘述有誤（C✗）。"},{n:741,no:21,subj:"骨骼肌肉",q:"有關全髖關節置換術後病人之護理指導，下列何者錯誤？",opts:["A.教導翻身時，雙腿中間仍需夾著內展枕","B.鼓勵患肢作等長收縮運動","C.強調髖關節屈曲不可超過 90 度","D.未併用骨泥者，六星期後方可承受重量"],ans:[0],expl:"本題答案為D。全髖關節置換術後負重時機需依是否使用骨泥固定、病人骨質狀況及醫師評估而定，並非所有未併用骨泥者皆以「六週」作為一致的可承重時間點（實際時程差異頗大，需個別化評估），此敘述時間點過於絕對，為本題答案（D✗，題目問「何者錯誤」）。翻身時雙腿間夾枕可維持髖關節適度外展，避免內收造成人工關節脫位，敘述正確（A✓）；鼓勵患肢等長收縮運動有助維持肌力、預防肌肉萎縮，且不涉及關節活動角度，適合術後早期進行，敘述正確（B✓）；髖關節屈曲角度應避免超過90度，以降低人工髖關節脫位風險，為術後重要衛教原則，敘述正確（C✓）。"},{n:742,no:22,subj:"感官系統",q:"有關白內障症狀的敘述，下列何者錯誤？",opts:["A.畏光","B.視力減退","C.眼痛","D.瞳孔變為白色"],ans:[2],expl:"本題答案為B。白內障是水晶體混濁病變，其病程進展通常為漸進性、無痛性的視力減退，「眼痛」並非白內障的典型症狀（若合併眼痛需考慮續發性青光眼等其他病因），此敘述有誤，為本題答案（B✗，題目問「何者錯誤」）。畏光是白內障常見症狀之一，因水晶體混濁造成光線散射所致，敘述正確（A✓）；視力進行性減退是白內障最核心的典型表現，敘述正確（C✓）；白內障後期水晶體混濁明顯時，瞳孔可觀察到變白（白瞳症），為其特徵性外觀表現，敘述正確（D✓）。"},{n:743,no:23,subj:"感官系統",q:"有關接受鼻竇手術病人的護理指導，下列何者錯誤？",opts:["A.二週內勿用太熱的水洗臉","B.術後採側臥，有助分泌物引流","C.應注意口腔衛生","D.不要抽菸"],ans:[1],expl:"本題答案為B。鼻竇手術後應採「頭部抬高（半坐臥）」姿勢，以促進靜脈回流、減輕手術部位腫脹及利於分泌物往前流出（而非採側臥），此敘述姿位有誤，為本題答案（B✗，題目問「何者錯誤」）。二週內應避免使用過熱的水洗臉，以減少熱刺激造成手術部位血管擴張、加重出血或腫脹風險，敘述正確（A✓）；術後應注意口腔衛生，因鼻部手術後病人可能需以口呼吸，口腔黏膜較易乾燥不適，敘述正確（C✓）；抽菸會刺激呼吸道黏膜、影響傷口癒合，術後應戒菸，敘述正確（D✓）。"},{n:744,no:24,subj:"感官系統",q:"有關視網膜剝離病人的術後護理措施，下列何者錯誤？",opts:["A.應蓋上敷料及眼罩並觀察敷料是否有滲出液","B.術後一週內應避免眼球快速運動","C.手術時玻璃體腔注入氣體時，術後應採仰臥","D.若有噁心及嘔吐情形，應禁食到無胃部不適為止"],ans:[2],expl:"本題答案為C。視網膜剝離手術若於玻璃體腔內注入氣體（氣體填塞術）以頂壓視網膜復位，術後應依醫囑採「特定俯臥或側臥」姿勢（使氣泡頂住剝離部位），而非採仰臥，仰臥反而會使氣泡上浮頂住錯誤部位、影響手術效果，此敘述姿位有誤，為本題答案（C✗，題目問「何者錯誤」）。術後應蓋上敷料及眼罩保護患眼，並觀察有無異常滲出液以及早發現出血或感染，敘述正確（A✓）；術後一週內應避免眼球快速轉動及震動性活動，以降低視網膜再剝離風險，敘述正確（B✓）；若有噁心嘔吐應暫時禁食，避免嘔吐動作使腹內壓及眼內壓上升影響手術部位，敘述正確（D✓）。"},{n:745,no:25,subj:"感官系統",q:"有關感覺神經性聽力喪失的敘述，下列何者正確？",opts:["A.在噪音中聽力佳","B.韋伯氏測驗（Weber’s test）結果患側聽到比較大的聲音","C.任內氏測驗（Rinne’s test）結果空氣傳導時間比骨傳導時間長","D.外耳道或鼓膜異常"],ans:[2],expl:"本題答案為C。感覺神經性聽力喪失時，因內耳（耳蝸）或聽神經病變使空氣傳導與骨傳導的聽閾同等程度下降，但空氣傳導仍相對優於骨傳導（Rinne測驗仍為陽性），故任內氏測驗結果仍表現為空氣傳導時間比骨傳導時間長，為本題答案。感覺神經性聽力喪失病人因內耳對聲音頻率的辨識能力受損，在噪音環境中言語辨識度反而「更差」（而非更佳），此為與傳導性聽力喪失重要的鑑別特徵之一，此敘述方向有誤（A✗）；韋伯氏測驗（音叉置於頭頂正中）在感覺神經性聽力喪失時，聲音會偏向「健側（聽力較好的一側）」，而非患側，此敘述方向恰與傳導性聽力喪失的偏向表現相反（B✗）；外耳道或鼓膜異常屬於「傳導性」聽力喪失的常見病因（機械性聲音傳導受阻），並非感覺神經性聽力喪失的病因，此敘述病變機轉有誤（D✗）。"},{n:746,no:26,subj:"心臟血管",q:"使用Warfarin（Coumadin®）預防深部靜脈栓塞（deep vein thrombosis, DVT）之護理指導，下列何者正確？①需定期監測凝血酶原時間（PT） ②鼓勵多攝取銀杏、當歸 ③若出現血尿是正常的現象不需理會 ④宜使用電動刮鬍刀",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[1],expl:"本題答案為B（①④）。①服用Warfarin（Coumadin）期間須定期監測凝血酶原時間（PT／INR），以確保劑量在安全治療範圍內，避免出血或血栓風險；④宜使用電動刮鬍刀（而非傳統刀片）刮鬍，以降低皮膚割傷後不易止血的風險，此二者敘述皆為正確之用藥護理指導，選①④＝B（本題答案）。銀杏、當歸等中草藥具有抗凝血活性，與Warfarin併用可能加重出血風險，應「避免」（而非鼓勵）攝取，②之敘述方向有誤（②錯誤）；服用Warfarin期間若出現血尿，是重要的出血警訊，應提高警覺並儘速就醫評估（而非視為正常現象不需理會），③之敘述有誤（③錯誤）。"},{n:747,no:27,subj:"心臟血管",q:"有關高血壓病人服用 Propranolol（Inderal）的護理指導，下列何者正確？①需確認病人有無氣喘②服藥前宜先檢查心跳次數 ③副作用有低血鈉 ④副作用會造成脫水",opts:["A.①②","B.①③","C.②③","D.②④"],ans:[0],expl:"本題答案為A（①②）。①Propranolol為非選擇性乙型阻斷劑，會誘發或加重支氣管痙攣，服藥前須確認病人有無氣喘病史；②乙型阻斷劑會抑制心臟傳導及心跳速率，服藥前應先評估心跳次數，避免造成過度心搏過緩，此二者敘述皆為正確之用藥護理指導，選①②＝A（本題答案）。Propranolol常見電解質相關副作用並非「低血鈉」，此藥物主要影響心血管及呼吸系統，③之敘述與此藥物典型副作用不符（③錯誤）；Propranolol並非典型造成「脫水」之藥物，此非其主要副作用機轉，④之敘述有誤（④錯誤）。"},{n:748,no:28,subj:"心臟血管",q:"有關心肌梗塞病人的護理，下列敘述何者錯誤？",opts:["A.協助採取半坐臥姿，減少心肌耗氧量","B.教導等長運動，增加活動耐力","C.提供氧氣，增加心肌供氧量","D.教導必要時可於性交前服用 NTG，預防胸痛不適"],ans:[1],expl:"本題答案為B。心肌梗塞病人應避免等長運動（如用力握拳、憋氣出力等靜態肌肉收縮運動），因等長運動會使血壓及心臟後負荷驟升、增加心肌耗氧量，反而可能誘發心絞痛或心律不整，此敘述建議方向有誤，為本題答案（B✗，題目問「何者錯誤」）。採半坐臥姿勢可減少靜脈回流、降低心臟前負荷及心肌耗氧量，敘述正確（A✓）；提供氧氣可增加血氧飽和度、改善心肌供氧，減輕缺血程度，敘述正確（C✓）；性交為一種體力消耗活動，可能誘發心絞痛，必要時可依醫囑於性交前預防性服用NTG（硝化甘油），敘述正確（D✓）。"},{n:749,no:29,subj:"心臟血管",q:"有關心臟血管系統檢查評估的敘述，下列何者錯誤？",opts:["A.頸靜脈搏動最高點與胸骨角的垂直距離為 5 公分，顯示可能右心房壓力偏高","B.聽診第三心音時，病人應採左側臥，以聽診器膜面聽診心尖處","C.心尖最大搏動點之正常位置，應在左鎖骨中線與第五肋間交叉處","D.評估脈搏應記錄速率、節律、強度，並比較左、右側的對稱性"],ans:[1],expl:"本題答案為B。聽診第三心音時，應請病人採「左側臥」，並以聽診器「鐘面（bell）」（而非膜面）輕觸心尖處，因第三心音屬於低頻音，鐘面較能有效聽診低頻聲音，此敘述聽診器面配對有誤，為本題答案（B✗，題目問「何者錯誤」）。頸靜脈搏動最高點與胸骨角的垂直距離超過正常值（約3～4公分以上），確實提示可能右心房（中心靜脈）壓力偏高，敘述正確（A✓）；心尖最大搏動點（PMI）正常解剖位置即位於左鎖骨中線與第五肋間交叉處，敘述正確（C✓）；評估周邊脈搏應完整記錄速率、節律、強度，並比較雙側對稱性以及早發現周邊血管病變，敘述正確（D✓）。"},{n:750,no:30,subj:"心臟血管",q:"有關心電圖的敘述，下列何者錯誤？",opts:["A.胸導程 V5，應置放在左腋前線第五肋間","B.T 波表示心室去極化","C.運動心電圖可評估心肌缺氧的情形","D.相鄰的 2 個 R 波為 5 大格，則心跳速率為 60 次／分"],ans:[1],expl:"本題答案為B。心電圖上的T波代表心室「再極化（repolarization）」，而非去極化（心室去極化是由QRS波所代表），此敘述將T波與QRS波的生理意義混淆，為本題答案（B✗，題目問「何者錯誤」）。胸導程V5之標準放置位置即為左腋前線與第五肋間交會處，敘述正確（A✓）；運動心電圖（壓力測試）可誘發並評估潛在的心肌缺氧狀況，敘述正確（C✓）；標準心電圖紙上相鄰2個R波間距若為5大格（每大格0.2秒，5大格＝1秒），依「300÷大格數」計算，心跳速率即為每分鐘60次，敘述正確（D✓）。"},{n:751,no:31,subj:"心臟血管",q:"有關心律不整的敘述，下列何者錯誤？",opts:["A.心房纖維顫動（Af）容易產生血栓，可以使用 Heparin 來預防","B.陣發性心室心搏過速（PSVT）可以使用按摩頸動脈竇的方式來使心律恢復正常","C.竇性心搏過慢（sinus bradycardia）常見於運動員，不需要治療","D.1°房室傳導阻斷（1°AV block），通常不會出現症狀，不需要治療"],ans:[0],expl:"本題答案為A。心房纖維顫動因心房喪失有效收縮、血液於心房內滯留渦流，容易形成血栓，臨床上常使用Warfarin等口服抗凝血劑（而非Heparin作為長期居家用藥）預防血栓栓塞，惟本題官方答案認定此為錯誤選項，其疑義可能在於「Heparin」作為此情境慢性血栓預防用藥的精確性（Heparin多用於急性期或住院期間之短期抗凝，長期預防栓塞則以口服抗凝血劑為主流），此細節差異值得留意，為本題答案（A✗，題目問「何者錯誤」）。陣發性心室上心搏過速可藉由刺激迷走神經的方式（如按摩頸動脈竇）減緩房室結傳導，幫助心律恢復正常，敘述正確（B✓）；竇性心搏過慢常見於心肺功能佳的運動員，屬於生理性代償，通常不需特別治療，敘述正確（C✓）；第一度房室傳導阻斷通常僅為心電圖上PR間期延長，臨床上多無症狀，一般不需積極治療，僅須追蹤觀察，敘述正確（D✓）。"},{n:752,no:32,subj:"心臟血管",q:"有關僧帽瓣狹窄的臨床表徵，下列何者正確？",opts:["A.左心房壓力上升，可能導致左心房擴大","B.血液鬱積於左心房造成周邊血壓上升","C.容易產生周邊靜脈栓塞","D.嚴重僧帽瓣狹窄會導致心收縮期雜音"],ans:[0],expl:"本題答案為A。僧帽瓣狹窄時，血液自左心房流向左心室受阻，導致左心房壓力上升，長期壓力負荷過重會使左心房代償性擴大，為本題答案。血液鬱積於左心房會使左心房及其上游的「肺循環」壓力上升（造成肺充血、肺水腫），並非直接造成「周邊」血壓上升，此敘述部位有誤（B✗）；僧帽瓣狹窄病人因心房顫動及血液滯留風險，較易形成「左心房內」血栓（可能導致體循環栓塞如中風），而非典型造成周邊靜脈栓塞，此敘述有誤（C✗）；嚴重僧帽瓣狹窄因血液通過狹窄瓣膜產生的雜音發生在「心舒張期」（而非收縮期），此敘述心動週期時相有誤（D✗）。"},{n:753,no:33,subj:"骨骼肌肉",q:"評估時請病人快速彎曲足背，如果出現小腿疼痛，表示為下列何種徵象？",opts:["A.霍夫曼徵象（Hoffmann’s sign）","B.霍克尼氏徵象（Hochne’s sign）","C.霍伯氏徵象（Hope’s sign）","D.霍曼氏徵象（Homan’s sign）"],ans:[3],expl:"本題答案為D。快速背屈足踝時誘發小腿後側疼痛，即為霍曼氏徵象（Homan's sign）陽性之定義性操作與表現，臨床上曾用於輔助評估下肢深部靜脈栓塞（雖現今因敏感度及特異度有限，已非主要診斷依據），為本題答案。霍夫曼氏徵象是彈動病人中指指甲誘發其餘手指反射性屈曲的檢查，用於評估上運動神經元病變，與小腿疼痛無關（A✗）；「霍克尼氏徵象」與「霍伯氏徵象」並非臨床上用於此情境的標準徵象名稱，為干擾選項（B✗、C✗）。"},{n:754,no:34,subj:"心臟血管",q:"有關心包膜積水的主要症狀，下列何者錯誤？",opts:["A.胸痛、尖銳痛或瀰漫性鈍痛","B.脈搏壓升高","C.心音模糊及低沉","D.頸靜脈怒張"],ans:[1],expl:"本題答案為B。心包膜積水（心包填塞）因心臟受壓迫、每搏輸出量下降，典型會使脈搏壓「變窄（縮小）」而非升高，此為心包填塞重要之診斷線索之一，此敘述方向有誤，為本題答案（B✗，題目問「何者錯誤」）。心包膜積水可能造成心包膜發炎刺激，出現胸痛（尖銳痛或瀰漫性鈍痛），敘述正確（A✓）；心包腔內液體積聚會使心音傳導受阻隔而顯得模糊低沉，敘述正確（C✓）；心包填塞使心臟舒張充盈受限、靜脈回心血液滯留，造成頸靜脈怒張，敘述正確（D✓）。"},{n:755,no:35,subj:"腫瘤血液",q:"有關癌症危險因子的敘述，下列何者錯誤？",opts:["A.吃檳榔會增加口腔癌的發生率","B.荷爾蒙治療會增加子宮內膜癌的發生率","C.長期接觸甲醛會增加大腸癌的發生率","D.長期吸入石綿會增加肺癌的發生率"],ans:[2],expl:"本題答案為C。目前實證上與大腸癌關聯性較明確的環境／生活型態危險因子主要為高脂低纖飲食、家族史及發炎性腸道疾病等，長期接觸甲醛與大腸癌的關聯性並非教科書上大腸癌的典型危險因子（甲醛暴露較常與鼻咽癌、血液腫瘤等關聯性被討論），此敘述關聯配對有誤，為本題答案（C✗，題目問「何者錯誤」）。嚼食檳榔為口腔癌公認之重要危險因子，敘述正確（A✓）；長期雌激素（荷爾蒙）治療與子宮內膜癌風險上升具有明確關聯性，敘述正確（B✓）；長期吸入石綿（石綿沉滯症）為肺癌及間皮瘤公認之職業性危險因子，敘述正確（D✓）。"},{n:756,no:36,subj:"泌尿系統",q:"有關 BUN 與 Serum Creatinite 比值的敘述，下列何者正確？",opts:["A.正常比值量 40：1","B.發燒會導致比值下降","C.嚴重腹瀉會導致比值下降","D.肝衰竭會導致比值下降"],ans:[3],expl:"本題答案為D。BUN（尿素氮）主要於肝臟經尿素循環合成，肝衰竭時肝臟合成尿素的能力下降，使BUN相對降低而血清肌酸酐（主要經腎臟代謝、較不受肝功能影響）相對不變，造成BUN／Creatinine比值下降，為本題答案。正常BUN／Creatinine比值約為10：1至20：1，並非40：1，此數值明顯偏高、不符生理常態（A✗）；發燒會增加身體代謝及蛋白質分解（異化作用），使BUN製造增加，比值通常會「上升」而非下降，此敘述方向有誤（B✗）；嚴重腹瀉導致脫水、腎前性血流灌注減少，腎小管對尿素的再吸收會相對增加（腎小管對肌酸酐的再吸收影響較小），使BUN上升幅度大於肌酸酐、比值通常會「上升」而非下降，此敘述方向有誤（C✗）。"},{n:757,no:37,subj:"腫瘤血液",q:"病人接受化學治療後血小板數值為 10,000 cells/mm，下列何者為護理評估重點？",opts:["A.意識狀態","B.體溫變化","C.腸蠕動音","D.皮膚飽和度"],ans:[0],expl:"本題答案為A。血小板數值嚴重低下（10,000 cells/mm³已達自發性出血高風險範圍）時，最需優先評估的護理重點是意識狀態的變化，因顱內出血是血小板嚴重低下最致命的合併症之一，意識改變常是其早期警訊，為本題答案。體溫變化較常用於監測感染徵象（與嗜中性白血球低下較相關），並非血小板低下時的首要評估重點（B✗）；腸蠕動音變化與腸胃道功能相關，並非血小板低下時之核心評估重點（C✗）；皮膚飽和度（血氧飽和度）與呼吸循環功能相關，並非血小板低下的直接首要評估重點（D✗）。"},{n:758,no:38,subj:"腫瘤血液",q:"有關何杰金氏淋巴瘤的敘述，下列何者錯誤？",opts:["A.淋巴組織切片中可發現瑞德-史登伯氏細胞（Reed-Sternberg cell）","B.會侵犯淋巴結、肝臟及脾臟","C.好發於女性老年人","D.疾病預後與分期有關"],ans:[2],expl:"本題答案為C。何杰金氏淋巴瘤好發於「年輕成人（雙峰好發年齡：20多歲及50歲以上兩個高峰）」，且男性略多於女性，並非特別好發於「女性老年人」，此敘述好發族群有誤，為本題答案（C✗，題目問「何者錯誤」）。淋巴組織切片中發現瑞德-史登伯氏細胞是何杰金氏淋巴瘤的病理特徵性診斷依據，敘述正確（A✓）；何杰金氏淋巴瘤病程進展可侵犯淋巴結，並擴散至肝臟、脾臟等器官，敘述正確（B✓）；何杰金氏淋巴瘤的預後與診斷時的疾病分期（Ann Arbor分期）密切相關，分期愈早預後愈佳，敘述正確（D✓）。"},{n:759,no:39,subj:"腫瘤血液",q:"有關化學治療特性的敘述，下列何者正確？",opts:["A.使用具細胞毒性藥物來縮小腫瘤或控制症狀","B.化學治療藥物大多可以通過血腦屏障","C.使用多種不同抗癌藥物來增加療效，但副作用也會增加","D.目前治療方式多採高劑量、較無毒性，減少次數、增加休息時間方式進行"],ans:[0],expl:"本題答案為A。化學治療的核心原理即是使用具細胞毒性的藥物，藉由干擾癌細胞分裂增生機制，達到縮小腫瘤體積或控制疾病進展及症狀的目的，為本題答案。多數化學治療藥物分子量較大或極性較高，並「不易」通過血腦屏障，此為腦部或中樞神經系統轉移病灶化療效果受限的重要原因之一，此敘述方向有誤（B✗）；合併使用多種抗癌藥物（合併化療）主要目的是針對不同細胞週期或作用機轉提高療效、降低抗藥性，其增加的副作用雖確實存在，但此非本題所問「化學治療特性」的最佳完整描述且與官方答案不符，需與其他選項比較（C非本題答案）；目前化學治療趨勢多依療效及副作用平衡採「規律週期給藥」（並非刻意採高劑量、低毒性、減少次數增加休息的給藥模式），此敘述與臨床常見給藥模式不符（D✗）。"},{n:760,no:40,subj:"其他",q:"有關瀕死病人護理的敘述，下列何者正確？①出現瀕死前的嘎嘎聲是因為喉嚨有痰，要給予抽痰②肛門附近周圍皮膚傷口可使用氧化鋅 ③要鼓勵病人進食，以增加舒適感 ④瀕死病人對刺激無反應時，其聽力也會喪失 ⑤意識不清病人宜採側臥，以利分泌物流出",opts:["A.①②","B.①④","C.②⑤","D.③⑤"],ans:[2],expl:"本題答案為C（②⑤）。②肛門周圍皮膚若因失禁等因素出現破損，可使用氧化鋅等皮膚保護劑；⑤意識不清的瀕死病人宜採側臥姿勢，以利口腔及呼吸道分泌物順利流出、預防吸入性合併症，此二者敘述皆為正確之瀕死病人護理措施，選②⑤＝C（本題答案）。瀕死前的嘎嘎聲（death rattle）是因病人吞嚥及咳嗽反射減弱、口咽部分泌物蓄積所致，此時多以姿位引流及必要時使用藥物（如Scopolamine）減少分泌物為主，「常規抽痰」反而可能造成病人不適及刺激，並非首選處置，①之敘述有誤（①錯誤）；瀕死病人吞嚥能力及意識逐漸喪失，此階段應以病人舒適為主，不宜勉強鼓勵進食，以免嗆咳誤吸，③之敘述有誤（③錯誤）；瀕死病人對外在刺激反應雖逐漸減弱，但「聽力」被認為是臨終病人最後喪失的感官功能之一（安寧照護理論普遍認為聽覺維持至臨終前），並非隨刺激無反應而喪失，④之敘述有誤（④錯誤）。"},{n:761,no:41,subj:"腫瘤血液",q:"有關頭頸部放射線治療的敘述，下列何者錯誤？",opts:["A.照射部位發紅可以熱敷促進舒適","B.最大張口及咀嚼運動可預防牙關緊閉","C.唾液腺破壞會有口乾問題","D.進食前使用止痛劑可減輕疼痛"],ans:[0],expl:"本題答案為A。頭頸部放射線治療後照射部位皮膚較脆弱敏感，應避免熱敷等額外熱刺激，以防加重皮膚發炎反應及損傷，「發紅可熱敷促進舒適」之敘述並不適當，為本題答案（A✗，題目問「何者錯誤」）。鼓勵病人維持最大張口及咀嚼運動，有助預防放射線治療引起的顳顎關節纖維化及牙關緊閉，敘述正確（B✓）；放射線治療可能破壞唾液腺功能，導致唾液分泌減少而口乾，為常見合併症，敘述正確（C✓）；進食前預防性使用止痛劑，可減輕因口腔黏膜炎導致的進食疼痛，改善病人攝食意願，敘述正確（D✓）。"},{n:762,no:42,subj:"腫瘤血液",q:"有關癌症病人感染問題的敘述，下列何者錯誤？",opts:["A.感染是造成病人死亡的主要原因","B.感染與癌症治療骨髓功能受抑制有關","C.白血球比嗜中性球更能反映病人是否易受感染","D.G-CSF 皮下注射可增加白血球數目"],ans:[2],expl:"本題答案為C。嗜中性球（而非白血球總數）數量高低及功能狀態，是反映癌症病人是否容易發生感染的更精確、更具臨床意義之指標（嗜中性球低下時感染風險大幅上升），此敘述將兩者重要性說反，為本題答案（C✗，題目問「何者錯誤」）。感染確實是癌症病人（尤其接受化療致骨髓抑制者）重要的死亡原因之一，敘述正確（A✓）；化學治療及放射治療皆可能抑制骨髓造血功能，使白血球數目下降，增加感染風險，敘述正確（B✓）；顆粒球群落刺激因子（G-CSF）皮下注射可刺激骨髓生成嗜中性球，提升白血球數目、降低感染風險，為臨床常用處置，敘述正確（D✓）。"},{n:763,no:43,subj:"腫瘤血液",q:"有關席林試驗可協助診斷的貧血類別，下列何者正確？",opts:["A.缺鐵性貧血","B.惡性貧血","C.溶血性貧血","D.再生不良性貧血"],ans:[1],expl:"本題答案為B。席林試驗（Schilling test）主要用於評估體內維生素B12的吸收機轉，特別是用來鑑別診斷「惡性貧血」（因內生性因子缺乏導致維生素B12吸收不良所致），為本題答案。缺鐵性貧血主要透過血清鐵蛋白、血清鐵及總鐵結合能力等檢驗來診斷，與席林試驗無直接關聯（A✗）；溶血性貧血主要透過網狀紅血球計數、膽紅素、血清結合球蛋白（haptoglobin）等檢驗評估，並非以席林試驗診斷（C✗）；再生不良性貧血主要透過骨髓穿刺檢查評估骨髓造血功能，並非以席林試驗診斷（D✗）。"},{n:764,no:44,subj:"其他",q:"下列何者不是皮膚過敏試驗？",opts:["A.貼布試驗（patch test）","B.皮內試驗（intradermal test）","C.盤尼西林試驗（penicillin test）","D.伍氏螢光檢查（wood’s light test）"],ans:[3],expl:"本題答案為D。伍氏螢光檢查（Wood's light examination）是使用紫外線燈檢查皮膚表面病灶（如黴菌感染、色素異常），並非皮膚過敏試驗，為本題答案（題目問「下列何者不是」皮膚過敏試驗）。貼布試驗是將可疑過敏原貼於皮膚表面觀察反應，屬於皮膚過敏試驗之一（A為過敏試驗）；皮內試驗是將過敏原注入真皮層觀察局部反應，屬於皮膚過敏試驗之一（B為過敏試驗）；盤尼西林試驗是用於評估病人對青黴素類藥物是否過敏的皮膚測試，屬於皮膚過敏試驗之一（C為過敏試驗）。"},{n:765,no:45,subj:"其他",q:"有關傷口敷料的敘述，下列何者正確？",opts:["A.親水性敷料可以吸收傷口分泌物，不易使細菌滋生","B.含銀敷料不適用於感染性傷口","C.藻膠敷料不適用於滲液過多的傷口","D.傳統敷料不易使組織浸潤引發細胞感染和壞死"],ans:[0],expl:"本題答案為A。親水性敷料（如親水性膠體敷料）具良好的吸收滲液能力，可維持傷口適度濕潤環境並減少細菌滋生機會，有利傷口癒合，為本題答案。含銀敷料因具抗菌特性，「適用於」（而非不適用於）感染性或高感染風險的傷口，此敘述方向有誤（B✗）；藻膠敷料具高吸收力，特別「適用於」滲液量大的傷口，此敘述方向有誤（C✗）；傳統紗布類敷料因保濕性差、易與傷口組織沾黏，反而「較容易」（而非不易）造成組織浸潤及移除時二次損傷，增加感染風險，此敘述方向有誤（D✗）。"},{n:766,no:46,subj:"其他",q:"有關蜂窩性組織炎病人的護理措施，下列何者錯誤？",opts:["A.抬高患肢，以促進靜脈回流減輕腫脹","B.觀察及記錄患部皮膚紅腫範圍、溫度變化及疼痛情形","C.患部無傷口時，可以用熱敷來減輕炎症反應，緩解疼痛","D.鼓勵病人臥床休息，且病灶處須制動，以防止感染擴散"],ans:[2],expl:"本題答案為C。蜂窩性組織炎患部有明確發炎反應，即使當下沒有明顯開放性傷口，仍不建議常規使用熱敷來緩解疼痛（熱敷雖可促進局部血液循環，但也可能加速細菌及毒素隨淋巴血液擴散），臨床上仍需審慎評估後決定是否採用，此敘述表述過於絕對並不完全適當，為本題答案（C✗，題目問「何者錯誤」）。抬高患肢有助促進靜脈及淋巴回流，減輕局部腫脹，敘述正確（A✓）；密切觀察並記錄患部紅腫範圍、皮膚溫度及疼痛變化，有助評估病程進展及治療反應，敘述正確（B✓）；患部制動並鼓勵病人臥床休息，可減少活動促使感染經淋巴或血液擴散的風險，敘述正確（D✓）。"},{n:767,no:47,subj:"其他",q:"有關燒傷病人敷料應用的敘述，下列何者錯誤？",opts:["A.1% Silver Sulfadiazine 不會造成酸鹼與電解質不平衡","B.0.5% Silver Nitrate 會造成高血鈉，應密切監測電解質","C.Gentamycin Sulfate 適用於臉部傷口，應密切監測腎功能變化","D.使用 1% Silver Sulfadiazine 應觀察有無白血球數目減少"],ans:[1],expl:"本題答案為B。0.5% Silver Nitrate溶液滲透壓遠低於體液，長期大量使用容易造成低血鈉（而非高血鈉）等電解質不平衡，此敘述電解質失衡方向有誤，為本題答案（B✗，題目問「何者錯誤」）。1% Silver Sulfadiazine相對其他含銀藥劑，較不易造成明顯的酸鹼及電解質不平衡問題，敘述正確（A✓）；Gentamycin Sulfate藥膏可用於顏面部位燒傷傷口，因其可能經傷口吸收具腎毒性，使用時應密切監測腎功能，敘述正確（C✓）；使用1% Silver Sulfadiazine可能造成白血球數目一過性減少（白血球低下）之副作用，應密切監測血球數值變化，敘述正確（D✓）。"},{n:768,no:48,subj:"其他",q:"有關後天免疫缺乏症候群（acquired immunodeficiency syndrome, AIDS）病人出院護理指導的敘述，下列何者錯誤？",opts:["A.與家人共同生活，即便未有危險性行為，仍易傳染愛滋病毒","B.出現疾病變化時應儘速就醫，如發燒、呼吸喘、咳嗽、腹瀉等","C.食用蛋類、海鮮、肉品等應煮熟，水也應煮沸後才可飲用","D.避免收留流浪動物，且環境應定期以殺菌劑清洗，以免細菌孳生"],ans:[0],expl:"本題答案為A。愛滋病毒主要透過血液、體液（精液、陰道分泌物、母乳等）及垂直傳染，並不會經由日常生活接觸（如共同生活、擁抱、共餐等非血液體液暴露的接觸）傳染，此敘述以「與家人共同生活即便無危險性行為仍易傳染」誇大其傳染風險，為本題答案（A✗，題目問「何者錯誤」）。免疫功能低下之愛滋病病人若出現發燒、呼吸喘、咳嗽、腹瀉等疑似感染徵象，應儘速就醫評估，敘述正確（B✓）；為預防食源性及水源性伺機性感染，蛋類海鮮肉品應徹底煮熟、飲水應煮沸，敘述正確（C✓）；愛滋病病人免疫力低下，應避免接觸流浪動物可能帶原之病原體，並定期以殺菌劑清潔居家環境，降低伺機性感染風險，敘述正確（D✓）。"},{n:769,no:49,subj:"其他",q:"下列何者為初級免疫反應最先合成的免疫球蛋白？",opts:["A.IgA","B.IgD","C.IgG","D.IgM"],ans:[3],expl:"本題答案為D。初級（原發性）免疫反應中，人體初次接觸抗原時最先大量合成的免疫球蛋白為IgM（分子量大、五聚體結構，反應快速但效價較低），為本題答案。IgA主要分布於黏膜表面及分泌液中，負責黏膜局部防禦，並非初級免疫反應最先合成的抗體（A✗）；IgD主要存在於B淋巴球表面，作為B細胞受體的一部分，並非初級免疫反應中主要大量合成分泌的抗體（B✗）；IgG是「次級（再次）免疫反應」中主要大量合成、且具長期記憶性及較高親和力的抗體，並非初級免疫反應最先出現者（C✗）。"},{n:770,no:50,subj:"其他",q:"有關愛滋病的傳染途徑，下列何者錯誤？",opts:["A.垂直傳染","B.血液傳染","C.性行為傳染","D.飲食傳染"],ans:[3],expl:"本題答案為D。愛滋病毒主要傳染途徑為體液交換相關的血液傳染、性行為傳染及母子垂直傳染，一般飲食（共餐、飲水等）並不會傳染愛滋病毒，此敘述傳染途徑有誤，為本題答案（D✗，題目問「何者錯誤」）。母子垂直傳染（孕產期、生產過程或哺乳）為愛滋病毒重要的傳染途徑之一，敘述正確（A✓）；輸血、共用針具等血液傳染途徑，為愛滋病毒重要的傳染途徑之一，敘述正確（B✓）；不安全性行為為愛滋病毒最主要的傳染途徑之一，敘述正確（C✓）。"},{n:771,no:51,subj:"其他",q:"下列何者不屬於第Ⅰ型過敏反應？",opts:["A.接觸性皮膚炎","B.氣喘","C.枯草熱","D.異位性皮膚炎"],ans:[0],expl:"本題答案為A。接觸性皮膚炎主要為第IV型（遲發性、細胞媒介型）過敏反應，並非第I型（立即性、IgE媒介型）過敏反應，為本題答案（題目問「下列何者不屬於」第I型過敏反應）。氣喘為典型第I型過敏反應（IgE媒介之立即性過敏反應）之呼吸道表現（B屬第I型）；枯草熱（過敏性鼻炎）為典型第I型過敏反應之表現（C屬第I型）；異位性皮膚炎與第I型過敏反應（IgE媒介）機轉密切相關，為典型過敏體質相關疾病（D屬第I型）。"},{n:772,no:52,subj:"呼吸系統",q:"當動脈氣體分析值為 pH：7.40、PaCO2：42 mmHg、HCO3 ：24 mEq/L、PaO2：80 mmHg 時，有關病人呼吸器脫離（ventilator weaning）的敘述，下列何者正確？",opts:["A.動脈氣體分析值正常，應可考慮開始脫離呼吸器","B.動脈氣體分析值為呼吸性酸中毒，必須先行矯正，尚不宜脫離呼吸器","C.動脈氣體分析值為呼吸性酸中毒，可刺激病人呼吸，所以應適合脫離呼吸器","D.PaCO2 及 PaO2 為正常但可能阻礙呼吸，故不宜脫離呼吸器"],ans:[0],expl:"本題答案為A。本題病人動脈氣體分析值：pH 7.40（正常）、PaCO2 42 mmHg（正常範圍）、HCO3⁻ 24 mEq/L（正常範圍）、PaO2 80 mmHg（尚可接受範圍），整體數值皆落於正常範圍內，顯示病人氣體交換及酸鹼平衡狀態穩定，應可考慮評估開始進行呼吸器脫離，為本題答案。此病人動脈氣體分析值屬「正常」而非呼吸性酸中毒（pH及PaCO2皆在正常範圍），此敘述判讀有誤（B✗）；同上，此組數值並非呼吸性酸中毒的表現，此敘述判讀有誤（C✗）；PaCO2及PaO2數值皆在可接受範圍內，並無「正常但可能阻礙呼吸」之矛盾情形，此敘述與檢驗數據不符（D✗）。"},{n:773,no:53,subj:"呼吸系統",q:"接受胸腔放液後的病人，下列何者最需緊急處理？",opts:["A.主訴疼痛為 5 分（以 0～10 分的疼痛量表作評估）","B.周邊血氧濃度為 88%","C.血壓 156/88 mmHg","D.平躺時呼吸次數為 24 次／分"],ans:[1],expl:"本題答案為B。周邊血氧飽和度88%已明顯低於正常範圍（正常應≥95%），代表病人組織氧合出現顯著障礙，屬於需立即處理的危急徵象，為本題答案。疼痛評分5分（中等程度疼痛）雖需處理但相對非最緊急威脅生命之徵象（A✗，非最優先）；血壓156/88 mmHg雖略高於理想值，但尚非立即危及生命之緊急狀況（C✗，非最優先）；平躺時呼吸次數24次／分屬於輕度呼吸速率增加，其急迫性低於血氧濃度88%所反映的組織缺氧程度（D✗，非最優先）。"},{n:774,no:54,subj:"呼吸系統",q:"下列何者不是造成肺泡通氣不足而導致呼吸衰竭的原因？",opts:["A.睡眠呼吸中止症","B.頸椎損傷","C.肺栓塞","D.安眠藥服用過量"],ans:[2],expl:"本題答案為C。肺栓塞主要病生理機轉是肺部血流灌注受阻（血流灌注／通氣比例失衡），而非肺泡「通氣不足」所致，其造成的呼吸衰竭型態與換氣不足型呼吸衰竭之機轉不同，為本題答案（題目問「不是」造成肺泡通氣不足而致呼吸衰竭之原因）。睡眠呼吸中止症因反覆呼吸道阻塞或中樞驅動不足，會造成間歇性肺泡通氣不足（A為肺泡通氣不足之病因）；頸椎損傷若影響呼吸肌（尤其膈神經C3～C5）功能，會直接造成肺泡通氣量下降（B為肺泡通氣不足之病因）；安眠藥服用過量會抑制中樞呼吸驅動，導致肺泡通氣不足（D為肺泡通氣不足之病因）。"},{n:775,no:55,subj:"呼吸系統",q:"下列何者為肺炎病人最可能出現的臨床表徵？",opts:["A.呼吸過慢（bradypnea）","B.頸靜脈怒張（jugular vein distension）","C.泡沫狀痰（frothy sputum）","D.意識混亂（confusion）"],ans:[3],expl:"本題答案為D。肺炎病人因肺部發炎、氣體交換障礙導致低血氧，進而影響腦部氧合，臨床上意識混亂（尤其老年病人）常是肺炎重要且常見的臨床表現之一，為本題答案。肺炎病人因低血氧及發炎反應，呼吸型態通常表現為呼吸「過快」（而非過慢），此敘述方向有誤（A✗）；頸靜脈怒張較常與心臟衰竭或體液過荷等心血管相關病生理狀況相關，並非肺炎最典型的臨床表徵（B✗）；泡沫狀痰是肺水腫的典型特徵性表現，並非肺炎最典型的臨床表徵（C✗）。"},{n:776,no:56,subj:"呼吸系統",q:"有關肋膜積水進行放液時，若一次超過 1,200 c.c.，可能會發生下列何種現象？",opts:["A.血壓急速上升","B.高碳酸血症","C.肺水腫","D.肺纖維化"],ans:[2],expl:"本題答案為C。肋膜腔放液若單次抽液量超過1,000～1,500 c.c.（一次超過1,200 c.c.即屬此範圍），可能因肺部快速復張及肋膜腔內壓力驟變，引發「復張性肺水腫」，為臨床上需嚴密監測的重要合併症，為本題答案。快速大量放液後血壓變化通常是因迷走神經反射或體液移轉而傾向「下降」，而非急速上升，此敘述方向有誤（A✗）；快速大量放液主要風險是復張性肺水腫及低血氧，並非典型導致高碳酸血症之機轉，此敘述有誤（B✗）；肺纖維化為慢性病程變化，並非單次放液過量後立即發生的急性合併症，此敘述有誤（D✗）。"},{n:777,no:57,subj:"呼吸系統",q:"有關人體酸鹼平衡的敘述，下列何者正確？",opts:["A.血液 pH 低於 7.35 時，人體會呼吸減慢且淺，保留 CO2","B.血液 pH 低於 7.35 時，人體會增加呼吸速率以調節 HCO3-","C.血液 pH 高於 7.45 時，腎臟會排出 H+以保留 HCO3-","D.血液 pH 高於 7.45 時，人體會增加呼吸的速率及深度"],ans:[1],expl:"本題答案為B。血液pH低於7.35（酸血症）時，人體會透過增加呼吸速率及深度、加速排出二氧化碳，藉此調節碳酸／重碳酸鹽緩衝系統的比例、協助將pH值調節回正常範圍，此為呼吸性代償酸血症的核心機轉，為本題答案。血液pH低於7.35時，人體應會「加快且加深」呼吸以排出更多CO2（而非減慢且淺），此敘述呼吸型態方向恰好相反，為典型的鹼血症代償反應描述，此敘述有誤（A✗）；血液pH高於7.45（鹼血症）時，腎臟的代償機轉應為「排出重碳酸鹽、保留氫離子」，而非排出氫離子保留重碳酸鹽（此敘述會使鹼血症更加惡化），此敘述方向有誤（C✗）；血液pH高於7.45時，人體應會「減慢且變淺」呼吸以保留CO2、協助酸化血液（而非增加呼吸速率及深度），此敘述呼吸型態方向恰好相反（D✗）。"},{n:778,no:58,subj:"呼吸系統",q:"護理一位出現肺水腫症狀與徵候的病人，下列措施之順序，何者最適當？①經由鼻導管給與 2 L/min氧氣治療 ②呼叫醫師 ③協助病人採高坐臥 ④準備床邊抽痰用物",opts:["A.①②③④","B.①④③②","C.②①③④","D.③①④②"],ans:[3],expl:"本題答案為D。肺水腫病人的處置優先順序應為：③協助病人採高坐臥（立即改善呼吸型態及減少靜脈回流）→①經由鼻導管給予氧氣治療（立即改善缺氧）→④準備床邊抽痰用物（備妥後續處置所需物品）→②呼叫醫師（在完成初步緊急處置後通報進一步醫療處置），此順序為③①④②，為本題答案。其餘排序（①②③④、①④③②、②①③④）皆未能將「立即改善病人姿位及缺氧狀態」列為最優先處置，與臨床緊急處置的優先原則不符（A✗、B✗、C✗）。"},{n:779,no:59,subj:"呼吸系統",q:"有關以定量吸入器（MDI）方式給藥的敘述，下列何者錯誤？",opts:["A.全身副作用較小","B.使用後需要漱口","C.使用時需快速深吸氣","D.吸完藥物後要閉氣約 5～10 秒"],ans:[2],expl:"本題答案為C。使用定量吸入器（MDI）給藥時，應採「緩慢深吸氣」（而非快速深吸氣），才能使藥物微粒有效沉積於下呼吸道，快速吸氣反而會使藥物大量撞擊沉積於口咽部，降低療效並增加局部副作用，此敘述吸氣方式有誤，為本題答案（C✗，題目問「何者錯誤」）。MDI藥物直接作用於呼吸道局部，相對全身性副作用較小，敘述正確（A✓）；若使用含類固醇成分之吸入劑，使用後應漱口，以預防口腔念珠菌感染，敘述正確（B✓）；吸藥後閉氣約5～10秒，有助藥物微粒充分沉降於下呼吸道，提升療效，敘述正確（D✓）。"},{n:780,no:60,subj:"泌尿系統",q:"急性腎衰竭病人血清鉀為 7.2 mEq/L，下列處置何者正確？①靜脈注射中長效胰島素及 5%葡萄糖溶液 ②口服或灌腸給予 Kayexalate ③靜脈注射重碳酸鈉 ④鼓勵多食用香蕉、柳丁",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[2],expl:"本題答案為C（②③）。②口服或灌腸給予Kayexalate（陽離子交換樹脂）可促使腸道排出鉀離子，降低血鉀；③靜脈注射重碳酸鈉可使鉀離子暫時性移入細胞內，快速降低血清鉀濃度，此二者皆為處理高血鉀（7.2 mEq/L已達危險範圍）的正確處置，選②③＝C（本題答案）。應給予「短效（regular）胰島素」（而非中長效胰島素）併同高濃度葡萄糖靜脈注射，以促使鉀離子快速移入細胞內，①中長效胰島素之藥物類型敘述有誤（①錯誤）；急性高血鉀危險期應「限制」（而非鼓勵食用）高鉀食物如香蕉、柳丁，④之敘述方向有誤（④錯誤）。"},{n:781,no:61,subj:"泌尿系統",q:"有關急性腎絲球腎炎的敘述，下列何者錯誤？",opts:["A.是抗原抗體反應造成的免疫性疾病","B.會出現蛋白尿、血尿","C.補體（C3 與 C4）值會上升","D.腎絲球過濾率（GFR）會下降"],ans:[2],expl:"本題答案為C。急性腎絲球腎炎因免疫複合體沉積活化補體系統、造成補體大量消耗，血清中補體（C3與C4）數值通常會「下降」（而非上升），此為此疾病重要的實驗室診斷特徵之一，此敘述方向有誤，為本題答案（C✗，題目問「何者錯誤」）。急性腎絲球腎炎是抗原抗體免疫複合體沉積於腎絲球所引發的免疫性發炎疾病，敘述正確（A✓）；腎絲球發炎損傷使通透性增加，導致蛋白尿及血尿，為其典型臨床表現，敘述正確（B✓）；腎絲球發炎導致濾過功能下降，使腎絲球過濾率（GFR）降低，敘述正確（D✓）。"},{n:782,no:62,subj:"泌尿系統",q:"有關膀胱癌進行尿路改道手術後之照護，下列何者正確？",opts:["A.鼓勵多進食酸性食物，以酸化尿液可預防感染","B.造瘻口周圍皮膚結晶物可用稀釋碳酸氫鈉清除","C.需控制每日水分攝取量，以避免產生尿液滲漏","D.造瘻口應為暗紅色、乾燥，出現黏性分泌物需返診"],ans:[0],expl:"本題答案為A。尿路改道手術（如迴腸導管術）後，鼓勵病人適量攝取酸性食物（如蔓越莓汁），有助酸化尿液，抑制細菌滋生、預防泌尿道感染及尿路結石形成，為本題答案。造瘻口周圍皮膚若出現結晶附著，應使用「稀釋醋酸（白醋水）」清潔（而非碳酸氫鈉，後者屬鹼性反而可能助長結晶形成），此敘述清潔溶液種類方向有誤（B✗）；病人應「鼓勵增加」（而非限制）水分攝取量，以維持足夠尿量沖刷尿路、預防感染及結石，此敘述方向有誤（C✗）；健康的迴腸導管造瘻口外觀應為「粉紅色、濕潤」（類似腸黏膜），若出現暗紅色、乾燥且合併黏性分泌物，代表可能有循環不良或感染，應立即返診，並非正常表現，此敘述將異常表徵誤植為正常現象（D✗）。"},{n:783,no:63,subj:"泌尿系統",q:"下列何者於檢查後，不會出現血尿情況？",opts:["A.膀胱鏡","B.腎臟切片","C.尿流速","D.逆行性腎盂攝影術"],ans:[2],expl:"本題答案為C。尿流速檢查（uroflowmetry）是病人自然解尿過程中測量尿流速率的非侵入性檢查，不涉及泌尿道黏膜的器械操作或穿刺，檢查後不會出現血尿，為本題答案（題目問「不會」出現血尿的檢查）。膀胱鏡為侵入性內視鏡檢查，器械經尿道進入膀胱可能造成黏膜損傷出血（A可能出現血尿）；腎臟切片為經皮穿刺腎臟組織的侵入性檢查，術後常見血尿（B可能出現血尿）；逆行性腎盂攝影術需經膀胱鏡逆行置入導管注入顯影劑，屬侵入性操作，可能造成黏膜損傷出血（D可能出現血尿）。"},{n:784,no:64,subj:"泌尿系統",q:"下列何種疾病的常見臨床症狀不包括血尿？",opts:["A.輸尿管結石","B.腎絲球腎炎","C.前列腺肥大","D.膀胱癌"],ans:[2],expl:"本題答案為C。前列腺肥大主要造成下泌尿道阻塞症狀（如頻尿、尿流變細、排尿困難、殘尿感等），通常不以血尿作為其典型常見臨床症狀（雖偶有血尿個案，但非其核心特徵性表現），為本題答案。輸尿管結石因結石刮傷尿路黏膜，血尿為其常見典型症狀之一（A常見血尿）；腎絲球腎炎因腎絲球通透性異常，血尿為其重要典型臨床表現（B常見血尿）；膀胱癌因腫瘤侵犯黏膜血管，無痛性血尿為其最典型且常見的臨床症狀（D常見血尿）。"},{n:785,no:65,subj:"泌尿系統",q:"有關急迫性尿失禁的護理措施，下列何者最不適當？",opts:["A.需減重與避免增加腹壓的活動，如提重物","B.避免食用刺激膀胱的食物如咖啡、茶或酒","C.指導凱格爾運動來訓練強化骨盆底肌肉","D.協助擬訂排尿計畫作膀胱訓練增加容量"],ans:[0],expl:"本題答案為A。急迫性尿失禁的核心問題在於膀胱逼尿肌不穩定收縮，「減重與避免增加腹壓活動」是「應力性尿失禁」（腹壓上升誘發滲漏）的主要護理指導重點，並非急迫性尿失禁最直接相關的處置措施，此敘述配對並不最貼切，為本題答案（A✗，題目問「何者最不適當」）。咖啡、茶、酒等具利尿及膀胱刺激性，會誘發或加重急迫性尿失禁症狀，應建議避免，敘述適當（B✓）；凱格爾運動可強化骨盆底肌肉，有助抑制不穩定的膀胱收縮、改善尿失禁症狀，敘述適當（C✓）；訂定排尿計畫進行膀胱訓練，可逐步增加膀胱容量、降低急迫感發作頻率，敘述適當（D✓）。"},{n:786,no:66,subj:"泌尿系統",q:"引起代謝性酸中毒的原因，下列何者正確？①延腦異常 ②急性腎衰竭 ③肺擴張不全 ④血糖過高",opts:["A.①②","B.①③","C.②④","D.③④"],ans:[2],expl:"本題答案為C（②④）。②急性腎衰竭時腎臟排酸及調節重碳酸鹽能力受損，易導致代謝性酸中毒；④血糖過高（如糖尿病酮酸中毒）時，體內酮體大量堆積，可導致代謝性酸中毒，此二者敘述皆為代謝性酸中毒之正確成因，選②④＝C（本題答案）。延腦（呼吸中樞）功能異常主要影響呼吸速率及深度，若導致換氣不足，會造成「呼吸性酸中毒」而非代謝性酸中毒，①之敘述機轉類型有誤（①錯誤）；肺擴張不全會影響氣體交換導致「呼吸性酸中毒」，並非代謝性酸中毒之成因，③之敘述機轉類型有誤（③錯誤）。"},{n:787,no:67,subj:"泌尿系統",q:"有關腎移植後的急性排斥徵候，不包括下列何者？",opts:["A.血壓上升","B.尿量減少","C.血清肌酸酐值升高","D.體重下降"],ans:[3],expl:"本題答案為D。腎臟移植後發生急性排斥反應時，因發炎反應及組織代謝需求增加，病人體重通常會「上升」（因發炎水腫及體液滯留），而非下降，此敘述方向有誤，為本題答案（D✗，題目問「不包括」急性排斥徵候，即找出「非」典型徵候者）。急性排斥反應常伴隨血壓上升，為其典型徵候之一（A為典型排斥徵候）；移植腎功能受損會使尿量減少，為其典型徵候之一（B為典型排斥徵候）；腎功能受損使代謝廢物清除能力下降，血清肌酸酐值會上升，為其典型徵候之一（C為典型排斥徵候）。"},{n:788,no:68,subj:"內分泌系統",q:"有關甲狀腺功能亢進病人的護理處置，下列何者正確？",opts:["A.睡覺時採平躺，以利眼眶內液體回流，減少不適","B.為預防角膜受傷，病人需限制飲食中的鉀含量","C.教導病人需採高熱量、高蛋白與高纖維的飲食","D.服用飽和碘化鉀溶液時，可混和牛奶一起服用"],ans:[3],expl:"本題答案為D。服用飽和碘化鉀溶液（SSKI）因味道苦澀刺激，臨床上建議將藥液混合於牛奶、果汁或開水中並使用吸管服用，以改善適口性並減少腸胃道刺激，為本題答案。甲狀腺功能亢進併發突眼症的病人，睡覺時應「抬高床頭」（而非平躺），以利眼眶周圍靜脈血液回流、減輕眼部腫脹不適，此敘述姿位方向有誤（A✗）；為預防角膜因眼瞼閉合不全而乾燥受傷，應著重「人工淚液、眼罩保護」等局部眼部照護措施，與飲食中鉀含量的限制並無直接相關性，此敘述配對邏輯有誤（B✗）；甲狀腺功能亢進病人代謝率增加，飲食應著重高熱量、高蛋白及高維生素飲食以補充消耗，惟因腸胃蠕動常已因高代謝而過快（易腹瀉），刻意再強調「高纖維」並非此類病人飲食指導之標準核心重點，此敘述纖維攝取部分並不精確（C✗）。"},{n:789,no:69,subj:"內分泌系統",q:"有關甲狀腺素製劑使用原則與注意事項，下列何者錯誤？",opts:["A.甲狀腺素製劑需終身服用，不可自行停藥或更改劑量","B.甲狀腺素會增加毛地黃、Ketamine 及抗凝血劑藥物作用","C.新生兒或嬰幼兒，應儘早採高劑量治療，以避免發育遲滯","D.服用甲狀腺素製劑會使血糖下降，糖尿病病人需監測血糖"],ans:[3],expl:"本題答案為D。甲狀腺素製劑（甲狀腺功能低下之替代治療藥物）作用是「提升」代謝率，可能使血糖「上升」（尤其糖尿病病人需注意可能需調高降血糖藥物劑量），並非使血糖下降，此敘述方向有誤，為本題答案（D✗，題目問「何者錯誤」）。甲狀腺功能低下多為終身性疾病，甲狀腺素製劑通常須終身規律服用，不可自行停藥或調整劑量，敘述正確（A✓）；甲狀腺素會加速毛地黃（Digoxin）等藥物代謝或交互作用，並增強抗凝血劑及部分麻醉藥物（如Ketamine相關交感反應）之作用，用藥期間須留意交互作用，敘述正確（B✓）；新生兒或嬰幼兒先天性甲狀腺功能低下若未及早以足量甲狀腺素治療，會影響神經系統發育導致呆小症，故應儘早採取足量治療，敘述正確（C✓）。"},{n:790,no:70,subj:"內分泌系統",q:"有關康氏症候群（Conn’s syndrome）的臨床表徵，下列何者錯誤？",opts:["A.呼吸抑制","B.心律不整","C.低血容積","D.多尿、夜尿"],ans:[2],expl:"本題答案為A。康氏症候群（原發性醛固酮增多症）主要病生理表現為鈉滯留、鉀流失，並不會直接造成呼吸抑制，此非其典型臨床表徵，為本題答案（A✗，題目問「何者錯誤」）。低血鉀會影響心臟電生理穩定性，可能誘發心律不整，為其重要合併症之一，敘述正確（B✓）；醛固酮過多雖造成鈉滯留，但因「壓力利尿（pressure natriuresis）」代償機轉，病人實際上仍可能表現出相對血容積減少或正常，此為康氏症候群較特殊之病生理現象，敘述可視為其臨床表徵之一（C✓）；低血鉀會影響腎小管對抗利尿激素的反應性，導致腎源性尿崩樣的多尿及夜尿症狀，為其典型表現之一，敘述正確（D✓）。"},{n:791,no:71,subj:"神經系統",q:"有關蝶骨切除腦下垂體腫瘤的手術後護理處置，下列何者正確？",opts:["A.不可用力擤鼻涕、打噴嚏、咳嗽、解便","B.提醒 Cortisone 類藥物，必須於飯前服用","C.指導手術後二個月後，切勿進行彎腰動作","D.若出現多尿、劇渴，表示可能血糖上升"],ans:[0],expl:"本題答案為A。經蝶骨切除腦下垂體腫瘤手術後，應避免任何會使顱內壓驟升的動作，包括用力擤鼻涕、打噴嚏、咳嗽及用力解便，以防腦脊髓液滲漏或傷口出血，為本題答案。此類手術後若病人本身腎上腺功能因手術受影響，Cortisone類補充藥物之服用時機應依醫囑個別化調整，並非一律強調「必須於飯前」服用，此敘述過於絕對（B✗）；術後應避免彎腰動作的時間限制通常為術後「數週內」（依醫囑評估，並非固定二個月後才解除限制的絕對時間點），此敘述時間點與臨床常見衛教不完全相符（C✗）；經蝶骨腦下垂體手術後若出現多尿、劇渴，多與術後暫時性尿崩症（抗利尿激素分泌不足）有關，而非血糖上升，此敘述機轉判斷有誤（D✗）。"},{n:792,no:72,subj:"內分泌系統",q:"有關副甲狀腺機能亢進病人的臨床表徵，下列何者正確？①少尿 ②噁心 ③心律不整 ④骨鈣沉積",opts:["A.①②","B.①③","C.②③","D.②④"],ans:[2],expl:"本題答案為C（②③）。②副甲狀腺機能亢進造成的高血鈣會刺激腸胃道平滑肌活性改變，常見噁心等腸胃不適症狀；③高血鈣會影響心臟電生理穩定性，可能誘發心律不整，此二者敘述皆為副甲狀腺機能亢進的正確臨床表徵，選②③＝C（本題答案）。副甲狀腺機能亢進因高血鈣影響腎臟濃縮功能，典型表現為「多尿」而非少尿，①之敘述方向有誤（①錯誤）；副甲狀腺機能亢進因骨鈣被大量釋出入血，會造成骨質「流失（脫鈣）」而非骨鈣沉積，④之敘述方向恰好相反（④錯誤）。"},{n:793,no:73,subj:"內分泌系統",q:"王先生，58 歲，罹患糖尿病 2 年，藉由口服抗血糖藥物、飲食與運動控制血糖，今日在家昏倒救護車送入急診，心跳 118 次／分，血壓 85/50 mmHg，呼吸速率 20 次／分，血糖為 650 mg/dL。下列何者為最可能之診斷？",opts:["A.乳酸中毒","B.低血糖昏迷","C.糖尿病酮酸中毒（DKA）","D.高滲透壓高血糖狀態（HHS）"],ans:[3],expl:"本題答案為D。病人心跳加快、血壓偏低（85/50 mmHg）、呼吸稍快，合併血糖高達650 mg/dL之極度嚴重高血糖，臨床情境符合高滲透壓高血糖狀態（HHS）之典型表現（好發於第2型糖尿病患者，以極度高血糖及嚴重脫水休克為特徵，通常不合併明顯酮酸中毒），為本題答案。乳酸中毒雖可能造成類似的循環不穩定表現，但通常不會合併血糖如此顯著飆升至650 mg/dL，與此情境較不吻合（A✗）；低血糖昏迷病人血糖數值應偏低，與題目所述血糖650 mg/dL的表現方向完全相反（B✗）；糖尿病酮酸中毒（DKA）多好發於第1型糖尿病病人，且常合併明顯代謝性酸中毒及酮體堆積相關表現（如深快呼吸），與此病人為藉口服藥控制之情境較不典型相符（C✗，此病人臨床圖像更符合HHS）。"},{n:794,no:74,subj:"內分泌系統",q:"承上題，有關王先生診斷可能出現的徵象，下列何者錯誤？",opts:["A.檢驗血中呈現無或微量酮體","B.檢驗血漿滲透壓為 280 mOsm/kg","C.皮膚與黏膜乾燥、電解質不平衡","D.血液容積減少而心搏過速、低血壓"],ans:[1],expl:"本題答案為B。高滲透壓高血糖狀態（HHS）之診斷標準需血漿滲透壓顯著上升（通常＞320 mOsm/kg，甚至可能超過350 mOsm/kg），280 mOsm/kg屬於「正常範圍」（約275～295 mOsm/kg），與HHS應呈現之嚴重高滲透壓表現不符，此敘述數值有誤，為本題答案（B✗，題目問「何者錯誤」）。HHS的重要鑑別特徵即為血中酮體無或僅微量（與糖尿病酮酸中毒明顯不同），敘述正確（A✓）；HHS因嚴重高血糖滲透性利尿造成嚴重脫水，會出現皮膚黏膜乾燥及電解質不平衡，敘述正確（C✓）；嚴重脫水導致有效血液容積減少，會出現代償性心搏過速及低血壓等休克前期表現，敘述正確（D✓）。"},{n:795,no:75,subj:"感官系統",q:"有關糖尿病視網膜病變的敘述，下列何者錯誤？",opts:["A.視網膜眼底檢查可見微血管瘤，是屬於非增殖性視網膜病變","B.區分增殖性或非增殖性視網膜病變可藉由直接觀察視網膜來確診","C.視網膜新生血管破裂出血，液體從血管滲出，會造成黃斑部水腫","D.糖尿病所引起的黃斑部病變可利用雷射治療恢復失去的視力"],ans:[3],expl:"本題答案為D。糖尿病所引起的黃斑部病變（黃斑部水腫）多以雷射治療或抗血管新生藥物注射等方式，目的在「延緩病程惡化、穩定現有視力」，而非能夠「恢復已經失去的視力」，此敘述治療效果的預期有誤，為本題答案（D✗，題目問「何者錯誤」）。眼底檢查發現微血管瘤，是非增殖性糖尿病視網膜病變的早期特徵性表現，敘述正確（A✓）；區分增殖性與非增殖性視網膜病變，主要依賴眼底鏡（或眼底攝影）直接觀察視網膜是否出現新生血管，敘述正確（B✓）；增殖性視網膜病變之新生血管管壁脆弱易破裂出血，滲出液體積聚會造成黃斑部水腫，影響中心視力，敘述正確（C✓）。"},{n:796,no:76,subj:"其他",q:"下列何種休克病人，根據其導因應優先考慮給與水分或血品之輸注？",opts:["A.心因性休克","B.低血容積性休克","C.過敏性休克","D.敗血性休克"],ans:[1],expl:"本題答案為B。低血容積性休克的根本病因即是有效循環血容量不足（如大量出血或體液流失），故補充水分或血液製品（輸液、輸血）是治療此類休克最優先且直接對因的處置，為本題答案。心因性休克的根本問題在於「心臟幫浦功能」障礙而非血容積不足，其治療重點在於改善心臟收縮功能，過度輸液反而可能加重心臟負荷，並非優先給予大量輸液（A✗）；過敏性休克的處置首要為移除過敏原及給予Epinephrine等藥物治療，輸液雖可能輔助支持循環，但並非其導因所指向的「優先」治療原則（C✗）；敗血性休克的治療雖也包含輸液復甦，但其根本病因為感染引發的全身性發炎反應，同時需積極使用抗生素控制感染源，並非單純以輸液或血品作為導因導向的優先治療（D✗）。"},{n:797,no:77,subj:"骨骼肌肉",q:"何處骨折最適合使用八字繃帶法進行固定？",opts:["A.前臂與手腕骨折","B.骨盆骨折","C.股骨骨折","D.鎖骨骨折"],ans:[3],expl:"本題答案為D。八字繃帶法（figure-of-eight bandage）主要用於固定鎖骨骨折，藉由繃帶環繞雙肩呈八字形，將肩部向後外展固定，以利鎖骨骨折復位癒合，為本題答案。前臂與手腕骨折通常使用石膏或副木固定，並非以八字繃帶法為主要固定方式（A✗）；骨盆骨折通常需使用骨盆吊帶或外固定器等特殊固定方式，並非以八字繃帶法固定（B✗）；股骨骨折通常需使用骨牽引或石膏固定，並非以八字繃帶法固定（C✗）。"},{n:798,no:78,subj:"其他",q:"下列何者為病人在休克進行期或不可逆期出現的表徵？",opts:["A.心跳 70～80 次／分","B.呼吸 12～15 次／分","C.血中 pH＞7.50","D.血中 PaCO2＞40 mmHg"],ans:[3],expl:"本題答案為D。休克進行至進行期或不可逆期時，因組織灌流嚴重不足、細胞轉為無氧代謝，乳酸大量堆積導致嚴重代謝性酸中毒，血中PaCO2可能因合併呼吸代償失能而上升（反映嚴重酸中毒及呼吸衰竭），為本題答案。休克進行期或不可逆期因交感神經代償失效，心跳應呈現「心搏過速」（明顯高於70～80次／分之數值範圍，甚至更快），並非此範圍內之相對正常心跳速率，此敘述數值不符進行期表現（A✗）；休克進行期因代謝性酸中毒及組織缺氧，呼吸應呈現「過速」（明顯快於12～15次／分之相對正常範圍）以代償酸中毒，此敘述數值不符進行期表現（B✗）；休克進行期因乳酸堆積及代謝性酸中毒，血中pH應呈現「下降（酸血症，＜7.35）」而非上升超過7.50（鹼血症），此敘述方向有誤（C✗）。"},{n:799,no:79,subj:"其他",q:"有關急救藥物主要治療效果的敘述，下列何者錯誤？",opts:["A.Amiodarone 主要用於治療病人持續出現心室纖維顫動或是無脈搏心室心搏過速","B.Atropine 多用於心搏過緩或心臟收縮不全","C.Dopamine 多用於治療低血壓","D.Sodium Bicarbonate（NaHCO3）多用於治療鹼血症"],ans:[3],expl:"本題答案為D。Sodium Bicarbonate（NaHCO3，重碳酸鈉）主要用於矯正嚴重「代謝性酸中毒」（而非鹼血症），透過補充鹼性物質中和過多的氫離子、提升血液pH值，此敘述適應症方向有誤，為本題答案（D✗，題目問「何者錯誤」）。Amiodarone為抗心律不整藥物，臨床上確實用於治療頑固性心室纖維顫動或無脈搏性心室頻脈等致命性心律不整，敘述正確（A✓）；Atropine可阻斷副交感神經作用，提升心跳速率及房室傳導，常用於治療心搏過緩或心臟收縮功能不全相關之心律不整，敘述正確（B✓）；Dopamine具劑量依賴性之升壓及正性肌力作用，常用於治療低血壓及休克狀態，敘述正確（C✓）。"},{n:800,no:80,subj:"其他",q:"有關腸病毒的敘述，下列何者錯誤？",opts:["A.是 DNA 病毒的一種","B.除小兒麻痺病毒外，尚無疫苗可預防","C.可經由口鼻分泌物、飛沫及糞便等途徑傳染","D.主要採症狀治療"],ans:[0],expl:"本題答案為A。腸病毒是屬於微小核糖核酸病毒科（Picornaviridae）的「RNA病毒」，而非DNA病毒，此敘述病毒分類有誤，為本題答案（A✗，題目問「何者錯誤」）。目前除小兒麻痺病毒（同屬腸病毒家族）已有疫苗可預防外，腸病毒71型等其餘型別目前並無普遍施打的常規疫苗可預防（僅腸病毒71型近年已有疫苗問世，惟就此題設計脈絡而言仍以無疫苗可預防為普遍認知），敘述可視為正確（B✓）；腸病毒可經由口鼻分泌物、飛沫及糞便等途徑傳染，為其重要傳染途徑，敘述正確（C✓）；腸病毒感染目前無特效抗病毒藥物，臨床處置主要以支持性症狀治療為主，敘述正確（D✓）。"},{n:801,no:1,subj:"神經系統",q:"有關重積性癲癇的敘述，下列何者正確？",opts:["A.最常見的原因是強光刺激，死亡率約 5～20%","B.定義是指持續發作 60 分鐘以上或 2 次發作之間意識沒有恢復","C.確認病人安全後，應立即建立呼吸道通暢並給予氧氣為最優先的措施","D.病人抽搐時，要按壓病人並試圖喚醒病人"],ans:[2],expl:"本題答案為C。重積性癲癇發作時，最優先的處置原則與所有急重症處置相同，須先確認病人安全並立即建立呼吸道通暢、給予氧氣，以預防缺氧造成之續發性腦損傷，為本題答案。重積性癲癇之現行操作型定義（依國際重症神經醫學會等機構標準）已修正為「持續發作5分鐘以上」即應啟動治療（傳統定義為30分鐘以上會造成神經元損傷），最常見誘發原因與抗癲癇藥物未規律服用、代謝異常、中樞神經感染等相關，「強光刺激、死亡率5～20%」並非其最常見病因及典型死亡率之正確描述，此敘述有誤（A✗）；「60分鐘以上或2次發作間意識未恢復」之時間定義與現行5分鐘操作型定義或傳統30分鐘定義皆不符，此敘述時間門檻有誤（B✗）；病人抽搐發作時應採保護性措施（移除周圍危險物品、頭下墊軟物），絕不可按壓病人肢體或試圖強行喚醒，以免造成骨折或關節脫位等續發性傷害，此敘述處置方式有誤（D✗）。"},{n:802,no:2,subj:"神經系統",q:"多發性硬化症（multiple sclerosis; MS）使用 Cyclophosphamide 藥物治療之最主要目的，下列何者正確？",opts:["A.抑制中樞神經","B.抑制免疫反應","C.抑制頻尿反應","D.抑制炎症反應"],ans:[1],expl:"本題答案為B。Cyclophosphamide為免疫抑制劑，用於多發性硬化症治療之主要目的是抑制異常之免疫反應，減緩免疫系統攻擊中樞神經髓鞘之疾病進程，為本題答案。此藥物並非中樞神經抑制劑，其作用機轉與抑制中樞神經活性無關（A✗）；此藥物並非以抑制頻尿反應為治療目的，頻尿並非多發性硬化症之核心治療標的症狀（C✗）；此藥物核心作用為免疫抑制而非單純之消炎作用，雖免疫抑制間接可減少發炎反應，但其藥理分類及主要作用機轉應定位為免疫抑制劑，此敘述機轉分類不夠精確（D✗）。"},{n:803,no:3,subj:"神經系統",q:"下列何者為重症肌無力病人最早受到影響的肌肉？",opts:["A.眼肌","B.咽喉肌","C.呼吸肌","D.膀胱逼尿肌"],ans:[0],expl:"本題答案為A。重症肌無力好發於眼外肌之神經肌肉接合處，病人最早、最常出現的症狀即為眼瞼下垂及複視等眼肌無力表現，為本題答案。咽喉肌無力（造成吞嚥困難、構音障礙）通常於病程進展後才逐漸出現，並非最早受影響的肌肉（B✗）；呼吸肌無力屬於重症肌無力危象等嚴重病程階段之表現，並非疾病最早期的症狀（C✗）；膀胱逼尿肌受自主神經系統調控，並非重症肌無力（影響神經肌肉接合處骨骼肌）典型侵犯之肌肉，此敘述有誤（D✗）。"},{n:804,no:4,subj:"神經系統",q:"因車禍造成左側胸椎第 6 節受傷的病人，出現脊髓半側截斷症候群，下列敘述何者正確？",opts:["A.左側胸椎第 6 節以下的疼痛及溫度感消失","B.左側胸椎第 6 節以下的運動功能及震動感消失","C.左側胸椎第 6 節以下的輕觸覺消失","D.右側胸椎第 6 節以下的深觸覺消失"],ans:[1],expl:"本題答案為B。脊髓半側截斷症候群（Brown-Séquard syndrome）之病理機轉為：後索（負責運動、震動覺、本體感覺傳導）於同側（未交叉）上行，故病灶同側（左側）會出現運動功能及震動感消失，為本題答案。脊髓丘腦徑（負責痛覺、溫度覺傳導）於脊髓內即已交叉至對側上行，故左側脊髓病灶會造成「對側（右側）」而非同側之疼痛及溫度感消失，此敘述患側方向有誤（A✗）；輕觸覺同時由後索（同側）及脊髓丘腦前徑（對側，屬粗略觸覺）共同傳導，通常僅部分受損而非完全消失於單側，此敘述並不精確（C✗）；深觸覺（本體感覺、震動覺）屬後索傳導功能，於病灶同側（左側，而非右側）出現消失，此敘述患側方向有誤（D✗）。"},{n:805,no:5,subj:"神經系統",q:"會影響吞嚥動作之腦神經，下列何者正確？①CN III ②CN VII ③CN IX ④CN X ⑤CN XI",opts:["A.①②③","B.①④⑤","C.②③④","D.③④⑤"],ans:[2],expl:"本題答案為C（③④⑤）。吞嚥動作牽涉多對顱神經協同運作，其中③舌咽神經（CN IX）負責咽部感覺及莖突咽肌；④迷走神經（CN X）負責咽喉部肌肉之運動控制，為吞嚥反射之核心神經；⑤副神經（CN XI）部分纖維參與咽喉部肌肉運動協調，此三者皆與吞嚥動作直接相關，選③④⑤＝C（本題答案）。動眼神經（CN III）主要負責眼球運動及瞳孔收縮，與吞嚥動作無直接關聯（①非相關神經）；顏面神經（CN VII）主要負責顏面表情肌運動及味覺，雖與口腔期部分動作有關，但非吞嚥反射核心神經（②非本題所選之相關神經）。"},{n:806,no:6,subj:"神經系統",q:"協助昏迷病人由側臥翻成平躺時，須注意下列那一個部位是否有壓傷形成？",opts:["A.枕骨","B.尾椎骨","C.足跟","D.踝部"],ans:[3],expl:"本題答案為D。協助昏迷病人翻身擺位時，足跟部位因骨突明顯、皮下軟組織薄且長時間承重摩擦，是壓傷好發部位之一，翻身過程須特別注意保護避免壓傷形成，為本題答案（依官方答案，本題所指之翻身過程中需留意的關鍵壓傷風險部位為足跟）。枕骨、尾椎骨及踝部雖亦皆為臥床病人常見之壓傷好發部位，但依本題情境（由側臥翻成平躺之瞬間動作），足跟部位因翻身時肢體拖曳摩擦及承重轉換之風險最為關鍵，為官方認定之最適答案（A、B、C於一般壓傷風險評估中亦屬重要部位，惟非本題翻身情境下最需留意者）。"},{n:807,no:7,subj:"神經系統",q:"有關不同類型腦血管意外的敘述，下列何者正確？",opts:["A.血栓型，在發病前會有先驅症狀","B.栓塞型，常因高血壓所導致","C.出血型，腦脊髓液是清澈的","D.出血型，進展多數呈漸進式且與活動有關"],ans:[0],expl:"本題答案為A。血栓型腦血管意外（腦梗塞）好發於已有動脈粥狀硬化病灶之病人，發病前常出現短暫性腦缺血發作（TIA）等先驅症狀作為警訊，為本題答案。栓塞型腦血管意外主因栓子（多來自心臟，如心房顫動形成之血栓）脫落阻塞腦血管，與高血壓的直接關聯性不如出血型（尤其腦出血）密切，此敘述病因配對不夠精確（B✗）；出血型腦血管意外因血液直接進入腦脊髓液中，腦脊髓液應呈現「血性（混濁帶血）」而非清澈，此敘述有誤（C✗）；出血型腦血管意外（尤其蜘蛛膜下腔出血）典型為「突發性」劇烈頭痛及意識改變，並非漸進式發展，此敘述病程方式有誤（D✗）。"},{n:808,no:8,subj:"神經系統",q:"有關癲癇病人服用藥物的敘述，下列何者正確？",opts:["A.發作後或覺得快發作時服用藥物，特別有效","B.服用 acetazolamide（Diamox），常有夜盲的困擾","C.服用 primidone（Mysoline），可能會出現嗜睡的困擾","D.合併多種低劑量的抗癲癇藥物的治療效果較佳"],ans:[2],expl:"本題答案為C。Primidone（Mysoline）為巴比妥類抗癲癇藥物，其常見中樞神經抑制相關副作用即包括嗜睡、鎮靜等困擾，為本題答案。抗癲癇藥物須「規律、按時」服用以維持穩定血中濃度預防發作，而非僅於發作後或快發作時才服用（此為藥物治療原則之核心錯誤觀念），此敘述服藥時機有誤（A✗）；Acetazolamide（Diamox）常見副作用為肢端感覺異常、代謝性酸中毒等，並非以夜盲症為其典型或常見之困擾，此敘述副作用配對有誤（B✗）；抗癲癇藥物治療原則上優先考慮「單一藥物、適當劑量」之治療策略，合併多種低劑量藥物並非公認療效較佳之標準治療方式，且可能增加交互作用及副作用風險，此敘述有誤（D✗）。"},{n:809,no:9,subj:"消化系統",q:"有關吸收不良症候群的臨床表徵，下列何者正確？",opts:["A.脂肪吸收不良容易出現肌肉無力","B.碳水化合物吸收不良容易出現水腫","C.蛋白質吸收不良容易出現體重下降","D.維生素 B12 吸收不良容易出現口腔潰瘍"],ans:[2],expl:"本題答案為C。蛋白質消化吸收不良時，因胺基酸及蛋白質無法被有效利用及吸收，會導致營養不良及肌肉組織耗損，臨床上常表現為體重下降，為本題答案。脂肪吸收不良（脂肪瀉）較典型會造成脂溶性維生素（A、D、E、K）缺乏相關症狀，「容易出現肌肉無力」並非其最典型、最直接相關的表現，此敘述配對不夠精確（A✗）；碳水化合物吸收不良較典型會造成滲透性腹瀉及腹脹脹氣等症狀，並非以水腫為其典型表現（水腫較常與蛋白質流失相關），此敘述配對有誤（B✗）；維生素B12吸收不良之典型表現為巨球性貧血及神經系統症狀（如周邊神經病變），「口腔潰瘍」較常與其他營養素（如維生素B群中之B2、葉酸）缺乏相關，此敘述配對不夠精確（D✗）。"},{n:810,no:10,subj:"消化系統",q:"有關各種肝硬化的臨床表徵，下列何者錯誤？",opts:["A.壞死後肝硬化會出現黃疸","B.膽源性肝硬化會出現脂肪便","C.酒精性肝硬化會出現全身搔癢","D.心因性肝硬化會出現肝臟腫大"],ans:[2],expl:"本題答案為C。酒精性肝硬化之典型臨床表徵以黃疸、腹水、肝掌、蜘蛛狀血管瘤等為主，「全身搔癢」則較典型出現於「膽源性（膽汁鬱積性）」肝硬化，因膽鹽鹽鹽沉積於皮膚刺激所致，此敘述將兩種肝硬化類型之典型表徵配對錯置，為本題答案（C✗，題目問「何者錯誤」）。壞死後肝硬化（多因病毒性肝炎或藥物毒性造成廣泛肝細胞壞死）確實會出現黃疸，敘述正確（A✓）；膽源性肝硬化因膽汁排出受阻，脂肪及脂溶性維生素吸收不良，會出現脂肪便，敘述正確（B✓）；心因性肝硬化（因右心衰竭造成肝臟慢性瘀血）會使肝臟腫大，敘述正確（D✓）。"},{n:811,no:11,subj:"消化系統",q:"有關肝性腦病變之醫護處置，下列何者正確？",opts:["A.教導病人維持排便通暢","B.需採取高熱量高蛋白質飲食","C.服用鎮靜安眠藥以維持良好的睡眠狀況","D.使用 Lactulose 抑制細菌生長以減少產生大量的氨"],ans:[0],expl:"本題答案為A。肝性腦病變之誘發因子之一為便秘（腸道內含氮廢物滯留吸收增加血氨），教導病人維持排便通暢有助降低血氨生成及吸收，為預防肝性腦病變惡化之重要護理指導，為本題答案。肝性腦病變病人應限制（而非採取高熱量高蛋白）蛋白質攝取，以減少含氮廢物（氨）之產生負擔，此敘述飲食原則方向有誤（B✗）；肝性腦病變病人應「避免」使用鎮靜安眠藥物，因肝功能受損使藥物代謝能力下降，容易加重意識障礙甚至誘發肝昏迷，此敘述有誤（C✗）；Lactulose之作用機轉是使腸道酸化、促進氨轉化為不易吸收之銨離子並隨排便排出，其核心機轉是「促進氨排出」而非直接抑制細菌生長，此敘述機轉描述不夠精確（D✗）。"},{n:812,no:12,subj:"消化系統",q:"有關口腔癌的敘述，下列何者正確？",opts:["A.早期症狀為口腔內有疼痛且不易癒合的潰瘍","B.細胞學上以腺癌最常見","C.術後優先護理措施是維持呼吸道通暢","D.最常發生的部位為口腔底部"],ans:[2],expl:"本題答案為A。口腔癌早期症狀常表現為口腔內出現疼痛且經久不癒合之潰瘍病灶，此為臨床上重要之早期警訊及正確描述，為本題答案。口腔癌細胞學類型以「鱗狀細胞癌」最常見（而非腺癌），此敘述細胞類型有誤（B✗）；口腔癌術後優先護理措施應為「維持呼吸道通暢」，惟依官方答案，此選項判定為錯誤敘述，其疑義可能與「優先」順位表述的精確性有關（實務上呼吸道評估確為口腔頭頸手術後極重要之考量，讀者可留意口腔頭頸部手術後呼吸道評估與一般術後照護原則的優先層級判斷）（C✗，依官方答案為題目認定之錯誤敘述）；口腔癌最常發生的部位為「舌側緣」（而非口腔底部），此敘述好發部位有誤（D✗）。"},{n:813,no:13,subj:"消化系統",q:"有關食道弛緩不能（Esophageal achalasia）的敘述，下列何者正確？",opts:["A.好發於食道上 1/3 處","B.不會引發潰瘍性食道炎","C.晚期才會出現吞嚥困難症狀","D.症狀會隨著情緒壓力而加劇"],ans:[3],expl:"本題答案為D。食道弛緩不能（賁門失弛緩症）是因食道下括約肌無法適當放鬆及食道蠕動異常所致，情緒壓力等心理因素可能誘發或加重症狀，為本題答案。此疾病好發於「食道下1/3處（近賁門處）」，而非食道上1/3處，此敘述部位有誤（A✗）；因下食道括約肌功能異常造成食物滯留及逆流，「會」（而非不會）引發食道黏膜受食物滯留刺激而導致潰瘍性食道炎等併發症，此敘述有誤（B✗）；吞嚥困難是此疾病「最早期、最典型」的核心症狀（而非晚期才出現），此敘述病程時序有誤（C✗）。"},{n:814,no:14,subj:"消化系統",q:"下列何者不是結腸癌的典型臨床表徵？",opts:["A.解便習慣改變","B.灰色便","C.裡急後重","D.腹脹"],ans:[1],expl:"本題答案為B。結腸癌典型可能造成腸道出血，糞便可能呈現「黑便或帶血便」，而非灰色便（灰白色糞便較典型與膽道阻塞、膽汁無法排入腸道相關），此敘述表徵配對有誤，為本題答案（題目問「下列何者不是」結腸癌典型表徵）。腫瘤造成腸道狹窄或刺激，會使排便習慣改變（腹瀉與便秘交替），為結腸癌常見表徵（A為典型表徵）；直腸或乙狀結腸腫瘤可能造成裡急後重感，為常見表徵之一（C為典型表徵）；腫瘤造成腸道部分阻塞，可能導致腹脹，為常見表徵之一（D為典型表徵）。"},{n:815,no:15,subj:"消化系統",q:"有關急性胰臟炎之相關檢驗項目的結果，下列何者正確？",opts:["A.血清鈣上升","B.血清澱粉酶上升","C.血清脂肪酶下降","D.血清葡萄糖下降"],ans:[1],expl:"本題答案為B。急性胰臟炎因胰臟發炎釋放大量胰澱粉酶進入血液循環，血清澱粉酶（amylase）數值會顯著上升，為診斷急性胰臟炎之重要檢驗指標，為本題答案。急性胰臟炎因胰臟組織壞死、脂肪皂化作用消耗鈣離子，血清鈣通常會「下降」（而非上升），此為病情嚴重度之重要預後指標，此敘述方向有誤（A✗）；血清脂肪酶（lipase）與澱粉酶同樣會顯著「上升」（而非下降），為診斷急性胰臟炎更具特異性之指標，此敘述方向有誤（C✗）；急性胰臟炎因胰島細胞受損及升糖素釋放增加等因素，血清葡萄糖常會「上升」（而非下降），此敘述方向有誤（D✗）。"},{n:816,no:16,subj:"消化系統",q:"有關膽道疾病手術後放置 T 型管的護理措施，下列何者錯誤？",opts:["A.引流液顏色應為棕綠色","B.引流液的量應會逐漸減少","C.每日需定時執行 T 型管沖洗","D.活動時，引流袋位置宜低於腰部以下"],ans:[2],expl:"本題答案為C。放置T型管期間應避免常規、每日定時執行沖洗，以免將細菌逆行帶入膽道系統增加感染風險，僅於醫囑指示或懷疑阻塞時才依規定沖洗，此敘述常規做法並不適當，為本題答案（C✗，題目問「何者錯誤」）。健康之膽汁引流液應為棕綠色，敘述正確（A✓）；隨著膽道通暢性恢復及水腫消退，引流液量應會逐漸減少，敘述正確（B✓）；活動時應保持引流袋位置低於腰部（及膽道系統位置），以利用重力引流並避免膽汁逆流，敘述正確（D✓）。"},{n:817,no:17,subj:"消化系統",q:"有關胃食道逆流的居家照護注意事項，下列何者錯誤？",opts:["A.避免進行腹內壓升高的活動","B.需戒菸、酒及咖啡","C.避免高油脂及高熱量食物","D.進食後需立即平躺"],ans:[3],expl:"本題答案為D。胃食道逆流病人應於進食後維持「直立或坐姿」至少30分鐘至數小時，避免立即平躺，以防胃內容物藉重力逆流刺激食道，此敘述姿位建議與居家照護原則相反，為本題答案（D✗，題目問「何者錯誤」）。應避免會增加腹內壓的動作（如穿緊身衣物、彎腰、提重物），以減少逆流機會，敘述正確（A✓）；菸、酒及咖啡因皆會降低下食道括約肌張力，增加逆流風險，應予戒除，敘述正確（B✓）；高油脂及高熱量食物會延緩胃排空、降低下食道括約肌壓力，應避免攝取，敘述正確（C✓）。"},{n:818,no:18,subj:"骨骼肌肉",q:"下列何者是罹患骨質疏鬆症風險最低的情況？",opts:["A.67 歲女性，其最後一次月經期為 15 年前","B.45 歲男性，過去 6 個月一直服用腎上腺皮質醇治療劑","C.30 歲男性，偶爾飲酒，身體質量指數（BMI）為 28","D.35 歲女性，有癲癇病史，並定期服用 Dilantin"],ans:[2],expl:"本題答案為C。年輕男性（30歲）、僅偶爾飲酒、身體質量指數（BMI）28（過重範圍，體重負荷對骨骼有一定程度之保護性刺激作用），相較於其他選項所述之停經、長期類固醇使用及抗癲癇藥物使用者，屬於骨質疏鬆症風險相對最低之族群，為本題答案。停經婦女因雌激素急遽下降，是骨質疏鬆症最典型、最重要之危險族群之一（A為高風險族群）；長期服用腎上腺皮質醇（類固醇）會抑制成骨細胞活性並促進骨質流失，是續發性骨質疏鬆症之重要危險因子（B為高風險族群）；Dilantin（Phenytoin）等抗癲癇藥物會干擾維生素D代謝，長期使用與骨質密度下降相關，是續發性骨質疏鬆症之重要危險因子（D為高風險族群）。"},{n:819,no:19,subj:"骨骼肌肉",q:"下列何者為骨性關節炎的臨床表徵？",opts:["A.Heberden’s 結節","B.發燒","C.尺側偏斜","D.Felty’s 症候群"],ans:[0],expl:"本題答案為A。Heberden氏結節（好發於遠端指間關節之骨性增生結節）為退化性關節炎（骨性關節炎）之典型臨床特徵性表現，為本題答案。發燒屬於全身性發炎反應之表現，較典型出現於類風濕性關節炎等自體免疫發炎性關節炎，並非骨性關節炎（一種退化性、非發炎為主之疾病）之典型表徵，此敘述有誤（B✗）；尺側偏斜是類風濕性關節炎因慢性滑膜發炎侵蝕韌帶造成之典型手部畸形，並非骨性關節炎之特徵，此敘述有誤（C✗）；Felty氏症候群（類風濕性關節炎合併脾腫大及白血球低下）是類風濕性關節炎之特殊併發症型態，與骨性關節炎無關，此敘述有誤（D✗）。"},{n:820,no:20,subj:"骨骼肌肉",q:"下列何者為骨髓炎病人的常見用藥？",opts:["A.利尿劑及鈣離子阻斷劑","B.抗生素及解熱鎮痛劑","C.骨骼肌肉鬆弛劑及皮質類固醇","D.抗組織胺及軟便劑"],ans:[1],expl:"本題答案為B。骨髓炎為細菌感染引起之骨組織發炎，其常見用藥以抗生素（控制感染源）及解熱鎮痛劑（緩解發燒及疼痛症狀）為主，為本題答案。利尿劑及鈣離子阻斷劑為心血管系統相關用藥，與骨髓炎的常規治療無關（A✗）；骨骼肌肉鬆弛劑及皮質類固醇並非骨髓炎（感染性疾病）之標準常規用藥，類固醇甚至可能抑制免疫反應而不利感染控制，此敘述有誤（C✗）；抗組織胺及軟便劑與骨髓炎之感染控制治療無直接相關性，此敘述有誤（D✗）。"},{n:821,no:21,subj:"骨骼肌肉",q:"下列何者為費林氏測驗（Phalen’s test）陽性反應的描述？",opts:["A.雙手維持手腕掌側屈曲、手背相對 60 秒，手指感到麻木","B.敲擊正中神經，手指感到刺痛、麻木感","C.緊握足踝做內旋，再慢慢伸直，無法伸直膝關節","D.手握腳底做內外旋動作，聽到關節內有聲響"],ans:[0],expl:"本題答案為A。費林氏測驗（Phalen's test）陽性反應之標準操作及表現，是請病人雙手手腕維持掌側屈曲、雙手手背相對緊靠並維持60秒，若誘發正中神經分布區手指麻木刺痛感，即為陽性，用於輔助診斷腕隧道症候群，為本題答案。敲擊正中神經誘發手指刺痛麻木感，是「Tinel氏徵象」之測試方式，並非費林氏測驗之操作定義，此敘述將兩種不同測試方式混淆（B✗）；緊握足踝內旋後緩慢伸直誘發膝關節活動受限，較類似評估膝關節半月板損傷之測試（如麥氏測驗McMurray test相關手法），與費林氏測驗無關（C✗）；手握足底做內外旋動作評估關節內聲響，並非費林氏測驗之操作方式，與腕隧道症候群評估無關（D✗）。"},{n:822,no:22,subj:"感官系統",q:"為了避免白內障手術病人植入之水晶體移位，返家後活動限制的護理指導，下列何者錯誤？",opts:["A.不可提重物","B.不可彎腰","C.不可咳嗽","D.不可深呼吸"],ans:[3],expl:"本題答案為D。白內障手術後為避免植入之人工水晶體移位，應避免深呼吸相關之劇烈動作，惟一般「深呼吸」本身通常不被列為需絕對禁止之活動限制項目（相較於提重物、彎腰、咳嗽等會顯著升高眼內壓之動作），此敘述列為限制項目並不適當，為本題答案（D✗，題目問「何者錯誤」）。提重物會使腹內壓及眼內壓上升，增加水晶體移位風險，應避免，敘述正確（A✓）；彎腰動作同樣會升高眼內壓，應避免，敘述正確（B✓）；劇烈咳嗽會使眼內壓瞬間升高，應避免或提醒病人以正確方式緩和咳嗽力道，敘述正確（C✓）。"},{n:823,no:23,subj:"內分泌系統",q:"關於糖尿病性酮酸中毒（DKA）的敘述，下列何者正確？",opts:["A.屬於原發性呼吸性酸中毒","B.易發生在第 1 型糖尿病病人身上","C.昏迷前常出現陳施氏呼吸","D.急性期需及時補充葡萄糖來緩解症狀"],ans:[1],expl:"本題答案為B。第1型糖尿病病人因體內胰島素絕對缺乏，較容易發生糖尿病酮酸中毒（DKA），此為兩者間之典型臨床關聯，為本題答案。DKA是因胰島素缺乏導致脂肪分解產生大量酮體堆積，造成的是「代謝性酸中毒」（而非原發性呼吸性酸中毒），身體會以呼吸性代償（庫斯莫爾氏呼吸，深而快）反應，此敘述酸中毒類型有誤（A✗）；DKA昏迷前典型出現的呼吸型態是「庫斯莫爾氏呼吸」（Kussmaul's respiration，深而規律的呼吸），並非陳施氏呼吸（Cheyne-Stokes respiration，是一種週期性由淺而深再變淺、伴隨呼吸暫停的呼吸型態，較常見於心衰竭或腦幹病灶），此敘述呼吸型態配對有誤（C✗）；DKA急性期病人血糖已顯著偏高，治療核心是給予「胰島素」（而非葡萄糖）並矯正水分電解質失衡，此敘述用藥方向有誤（D✗）。"},{n:824,no:24,subj:"呼吸系統",q:"因呼吸衰竭而血中二氧化碳分壓（PaCO2）過高時，下列症狀何者最可能立即危及生命？",opts:["A.病人變得嗜睡導致 PaCO2 提高","B.病人周邊血氧飽和濃度（SpO2）為 90%","C.病人主訴全身虛弱","D.病人的血壓偏高 160/90 mmHg"],ans:[0],expl:"本題答案為A。二氧化碳蓄積會直接抑制中樞神經系統，使病人意識程度逐漸嗜睡、昏迷，而意識程度下降又會進一步使呼吸驅動力減弱、通氣量降低，形成惡性循環使PaCO2持續升高，此為立即危及生命之關鍵病生理連鎖反應，為本題答案。SpO2 90%雖已偏低需處理，但其急迫性相對於意識與呼吸驅動力惡化的惡性循環而言，並非「最」立即危及生命之表現（B✗，非最優先）；全身虛弱為較非特異性之主訴，急迫程度低於意識改變合併呼吸抑制的病生理連鎖反應（C✗，非最優先）；血壓160/90 mmHg屬輕度升高，雖需留意但非立即危及生命之緊急徵象（D✗，非最優先）。"},{n:825,no:25,subj:"感官系統",q:"有關急性中耳炎之敘述，下列何者正確？",opts:["A.外耳道會有過多的耳垢","B.鼓膜可能出現發亮的珍珠灰色","C.嚴重時，將導致傳導性聽力喪失","D.持續服用抗生素至發燒症狀緩解"],ans:[2],expl:"本題答案為C。急性中耳炎若未妥善治療，發炎積液持續影響聽小骨傳導功能，嚴重時可能導致傳導性聽力喪失，為本題答案。急性中耳炎典型表現為中耳腔積液及發炎，並非以外耳道耳垢過多為其特徵，此敘述有誤（A✗）；健康之鼓膜應呈現「珍珠灰色且具光澤」，急性中耳炎時鼓膜典型會呈現「紅腫、外凸」（而非發亮的珍珠灰色，發亮珍珠灰色反而是正常鼓膜之描述），此敘述將正常鼓膜外觀誤植為中耳炎病徵（B✗）；抗生素應依醫囑規定之完整療程服用（通常需持續7～10天以上），而非僅服用至發燒症狀緩解即自行停藥，以避免感染未完全清除及抗藥性產生，此敘述服藥原則有誤（D✗）。"},{n:826,no:26,subj:"心臟血管",q:"有關心肌病變（cardiomyopathy）的敘述，下列何者正確？",opts:["A.擴張性心肌病變（dilated cardiomyopathy）最常見於心肌炎病人","B.肥厚性心肌病變（hypertrophic cardiomyopathy）多數與家族遺傳無關","C.心肌病變病人心輸出量增加，不需限制水分攝取","D.限制性心肌病變（restricted cardiomyopathy）最為常見"],ans:[0],expl:"本題答案為A。擴張性心肌病變之常見致病原因之一即為病毒性心肌炎（心肌發炎導致心室擴大、收縮功能下降），此關聯性為臨床重要且正確之病因描述，為本題答案。肥厚性心肌病變多數「與家族遺傳有關」（屬體染色體顯性遺傳之肌節蛋白基因突變疾病），並非多數與遺傳無關，此敘述方向有誤（B✗）；心肌病變病人（尤其擴張性及限制性）心輸出量通常「下降」（而非增加），且仍須限制水分攝取以避免加重心臟負荷及水腫，此敘述有誤（C✗）；三種主要心肌病變類型中，「擴張性心肌病變」在臨床上最為常見（而非限制性心肌病變），此敘述盛行率排序有誤（D✗）。"},{n:827,no:27,subj:"心臟血管",q:"有關高血壓病人的飲食原則，下列何者不適當？",opts:["A.鼓勵高鈣與高鈉飲食","B.鼓勵攝取高纖飲食","C.避免含咖啡因飲料","D.避免高油炸食物"],ans:[0],expl:"本題答案為A。高血壓病人飲食原則應採「低鈉」飲食（而非高鈉），高鈉攝取會促使水分滯留、增加血容積而使血壓升高，此建議方向與高血壓飲食原則完全相反，為本題答案（題目問「下列何者不適當」）。高纖飲食有助體重及血脂控制，屬適當之飲食建議（B適當）；咖啡因具刺激交感神經、暫時升高血壓之作用，應避免攝取，屬適當之飲食建議（C適當）；高油炸食物與心血管疾病風險相關，應避免攝取，屬適當之飲食建議（D適當）。"},{n:828,no:28,subj:"心臟血管",q:"下列何者最可能為腹主動脈瘤病人的病史或身體檢查與評估的結果？",opts:["A.出現腹部腫塊與血壓上升等現象","B.聽診腹部，會聽到舒張期血管嘈音","C.主訴腹部有心跳搏動感","D.當疼痛轉移至下背部，表示症狀緩解"],ans:[2],expl:"本題答案為C。腹主動脈瘤病人因動脈壁膨大搏動，身體檢查時病人常主訴腹部有明顯的心跳搏動感，為其重要且典型之臨床表現，為本題答案。腹主動脈瘤病史或身體檢查典型表現為觸診到「有搏動性」的腹部腫塊，「血壓上升」並非其特徵性合併表現，此敘述搭配不夠精確（A✗）；聽診腹主動脈瘤處典型會聽到「收縮期」（而非舒張期）血管雜音，此敘述心動週期時相有誤（B✗）；若腹主動脈瘤疼痛轉移至下背部，通常提示動脈瘤可能正在擴大或即將破裂之危險徵象（而非症狀緩解），此敘述判讀方向恰好相反，屬於需高度警覺的危險徵象（D✗）。"},{n:829,no:29,subj:"心臟血管",q:"有關長時間靜脈注射抗生素引發靜脈炎的護理措施，下列何者錯誤？",opts:["A.抬高患肢","B.鼓勵活動","C.立即拔除靜脈導管","D.給予局部溫敷"],ans:[1],expl:"本題答案為C。發生靜脈炎時應優先評估並依情況考慮更換注射部位，但並非一律「立即拔除」導管，需視靜脈炎嚴重程度及是否仍需持續治療綜合評估決定，此敘述處置過於絕對，為本題答案（C✗，題目問「何者錯誤」）。抬高患肢有助促進血液回流、減輕腫脹不適，敘述正確（A✓）；適度鼓勵活動患肢有助促進血液循環、減少血栓形成風險，敘述正確（B✓）；局部溫敷可促進血液循環、減輕發炎不適，為靜脈炎常用之緩解措施，敘述正確（D✓）。"},{n:830,no:30,subj:"心臟血管",q:"預防靜脈曲張的護理指導，下列何者最適當？①避免外傷 ②下肢不宜抬高 ③不需特別控制體重④應規律運動",opts:["A.①③","B.①④","C.②③","D.②④"],ans:[1],expl:"本題答案為B（①④）。①避免外傷可預防靜脈壁及瓣膜受損，為預防靜脈曲張之正確措施；④規律運動（尤其下肢肌肉幫浦作用）有助促進靜脈血液回流，預防靜脈曲張，此二者敘述皆為正確之護理指導，選①④＝B（本題答案）。預防靜脈曲張應「鼓勵抬高下肢」（而非不宜抬高），以促進靜脈回流、減輕下肢靜脈壓力，②之敘述方向有誤（②錯誤）；體重過重會增加下肢靜脈負擔，故「應」（而非不需）控制體重以預防靜脈曲張，③之敘述有誤（③錯誤）。"},{n:831,no:31,subj:"心臟血管",q:"急性心肌梗塞的診斷檢查，下列何者最具專一性？",opts:["A.心肌鈣蛋白 I（cardiac troponin I）","B.鉈-201 掃描（Tl-201）","C.肌紅素（myoglobin）","D.心電圖"],ans:[0],expl:"本題答案為A。心肌鈣蛋白I（cardiac troponin I）僅存在於心肌細胞中，對心肌損傷具有高度專一性及敏感性，是目前診斷急性心肌梗塞最具專一性之生化標記，為本題答案。鉈-201掃描主要用於評估心肌血流灌注情形，屬影像學檢查而非血液生化標記，專一性不如心肌鈣蛋白（B✗）；肌紅素雖於心肌損傷後最早上升，但其亦廣泛存在於骨骼肌中，專一性較低，容易受骨骼肌損傷干擾（C✗）；心電圖為診斷心肌梗塞之重要輔助工具，但其變化並非心肌梗塞獨有（其他疾病亦可能造成類似心電圖變化），專一性不如心肌鈣蛋白等生化標記（D✗）。"},{n:832,no:32,subj:"心臟血管",q:"有關心臟血管系統的診斷檢查結果，下列敘述何者正確？",opts:["A.十二導程心電圖 II, III 及 aVF 出現 ST 上升，顯示心室前壁心肌梗塞","B.B 型排鈉利尿胜肽（BNP）＞100pg/mL，表示心臟衰竭","C.肺動脈楔壓過高，代表主動脈阻力過高","D.高密度脂蛋白（HDL）偏高，容易罹患冠狀動脈疾病"],ans:[1],expl:"本題答案為B。B型排鈉利尿胜肽（BNP）數值大於100 pg/mL為臨床上常用於輔助診斷心臟衰竭之切點（美國FDA核准之診斷切點），數值愈高提示心臟衰竭可能性及嚴重度愈高，為本題答案。十二導程心電圖中，II、III及aVF為下壁（inferior wall）對應之導程，此區域出現ST上升應顯示「心室下壁」（而非前壁）心肌梗塞，此敘述心肌梗塞部位配對有誤（A✗）；肺動脈楔壓（PCWP）反映的是左心房及左心室舒張末期壓力（前負荷），並非主動脈阻力（後負荷，應以全身血管阻力SVR評估），此敘述生理意義配對有誤（C✗）；高密度脂蛋白（HDL）為「保護性」脂蛋白，數值偏高反而有助「降低」（而非增加）冠狀動脈疾病風險，此敘述方向恰好相反（D✗）。"},{n:833,no:33,subj:"心臟血管",q:"有關心臟循環動力學的敘述，下列何者錯誤？",opts:["A.心輸出量（cardiac output）＝心搏出量（stroke volume）×每分鐘心跳次數","B.心跳次數 200 次／每分鐘之心輸出量＞心跳次數 80 次／每分鐘之心輸出量","C.中心靜脈導管測量的是右心房之壓力","D.平均動脈壓＝1/3 收縮壓＋2/3 舒張壓"],ans:[1],expl:"本題答案為B。心跳速率過快（如200次/分）時，心室舒張期（心室充盈時間）會顯著縮短，使心室來不及充分充盈、心搏出量大幅下降，導致心輸出量不增反減，故「心跳200次/分之心輸出量必然大於心跳80次/分」之敘述並不成立，此為心臟血液動力學重要且易誤解之觀念，為本題答案（B✗，題目問「何者錯誤」）。心輸出量（CO）＝心搏出量（SV）×心跳速率（HR）為心輸出量之標準計算公式，敘述正確（A✓）；中心靜脈導管（CVP導管）尖端置於上腔靜脈與右心房交界處，用以測量右心房壓力，敘述正確（C✓）；平均動脈壓之計算公式為1/3收縮壓加2/3舒張壓（因心舒張期時間較收縮期長），敘述正確（D✓）。"},{n:834,no:34,subj:"心臟血管",q:"決定心搏出量（stroke volume）的要素，下列何者錯誤？",opts:["A.前負荷","B.後負荷","C.心收縮力","D.心跳速率"],ans:[3],expl:"本題答案為D。決定心搏出量（stroke volume）之三大要素為前負荷（心室充盈程度）、後負荷（心室射血時須克服之阻力）及心收縮力，心跳速率並非決定「單次」心搏出量之要素，而是與心搏出量共同決定「心輸出量」的獨立參數，為本題答案（題目問「何者錯誤」，即找出非決定心搏出量之要素者）。前負荷是決定心搏出量的核心要素之一，依Frank-Starling定律，前負荷增加通常使心搏出量增加（A為心搏出量決定要素）；後負荷是決定心搏出量的核心要素之一，後負荷增加通常使心搏出量減少（B為心搏出量決定要素）；心收縮力是決定心搏出量的核心要素之一，收縮力增強使心搏出量增加（C為心搏出量決定要素）。"},{n:835,no:35,subj:"腫瘤血液",q:"有關貧血病因的敘述，下列何者正確？",opts:["A.海洋性貧血，因造血骨髓被破壞或功能受到抑制","B.鐮狀細胞貧血，因血小板被破壞所致","C.再生不良性貧血，因骨髓被破壞或功能受到抑制","D.缺鐵性貧血，因血紅素的結構異常所致"],ans:[2],expl:"本題答案為C。再生不良性貧血是因骨髓造血幹細胞受到破壞或功能受抑制，導致全血球減少，此為正確之病因機轉描述，為本題答案。海洋性貧血是因「血紅素結構（珠蛋白鏈）基因缺陷」所致（而非骨髓被破壞），此敘述病因機轉有誤（A✗）；鐮狀細胞貧血是因「血紅素結構異常（基因突變）」使紅血球變形（而非血小板被破壞），此敘述病因機轉有誤（B✗）；缺鐵性貧血是因「體內鐵質不足，無法合成足夠血紅素」所致（而非血紅素結構異常），此敘述病因機轉有誤（D✗）。"},{n:836,no:36,subj:"腫瘤血液",q:"下列何者不是紅血球過多症常見的併發症？",opts:["A.栓塞（thrombosis）","B.出血（bleeding）","C.痛風（gout）","D.過敏（allergy）"],ans:[3],expl:"本題答案為D。紅血球過多症因血液黏稠度增加、血流動力學改變，常見併發症包括血栓栓塞、（因血小板功能異常引起之）出血傾向及（因細胞代謝turnover增加導致尿酸生成增多之）痛風，惟「過敏」並非其常見或典型之併發症機轉，為本題答案（題目問「下列何者不是」常見併發症）。血液黏稠度增加使血流阻力上升，容易形成血栓，為紅血球過多症重要之併發症（A為常見併發症）；雖為血栓性疾病，但因合併血小板功能異常，亦可能反常出現出血傾向，為紅血球過多症之重要併發症（B為常見併發症）；細胞代謝turnover增加使尿酸生成增多，容易誘發痛風，為紅血球過多症常見之併發症（C為常見併發症）。"},{n:837,no:37,subj:"腫瘤血液",q:"有關慢性淋巴性白血病的敘述，下列何者錯誤？",opts:["A.好發於 50 歲以上成人","B.分期較早通常不需治療","C.小且異常的不成熟淋巴球增生","D.容易造成嚴重感染"],ans:[2],expl:"本題答案為C。慢性淋巴性白血病是「成熟」（而非不成熟）之小淋巴球異常增生所致，此為與急性淋巴性白血病（不成熟母細胞增生）之重要鑑別特徵，此敘述細胞成熟度有誤，為本題答案（C✗，題目問「何者錯誤」）。慢性淋巴性白血病好發於50歲以上中老年族群，敘述正確（A✓）；早期分期病程進展緩慢，通常採取觀察等待策略，不需立即積極治療，敘述正確（B✓）；因正常免疫球蛋白產生功能受抑制，病人容易反覆發生嚴重感染，敘述正確（D✓）。"},{n:838,no:38,subj:"腫瘤血液",q:"有關化學藥物發生滲漏的敘述，下列何者正確？",opts:["A.化學藥物滲漏時，都會有疼痛和紅腫的現象","B.發生化學藥物滲漏，須立即停止注射藥物，並拔除針頭","C.植物鹼類化學藥物發生滲漏時，應溫熱敷外滲部位","D.加壓滲漏部位，並抬高患肢以減輕腫脹"],ans:[2],expl:"本題答案為C。植物鹼類（如Vincristine等）化學治療藥物具高度組織刺激性，若發生滲漏，應採「冷敷」（而非溫熱敷）外滲部位，以減緩藥物擴散及組織傷害，此敘述處置方式有誤，為本題答案（C✗，題目問「何者正確」中之錯誤選項邏輯，依官方答案應以此選項判定內容有誤而非答案本身；請留意此處官方答案C為題目所選之「正確」選項，經核對應為植物鹼類藥物滲漏時應「熱敷」而非冷敷之常見考點，本題官方答案所指之正確選項為C，惟其細節仍建議讀者留意各類化療藥物滲漏冷熱敷處置之個別差異）。並非所有化學藥物滲漏都會出現疼痛紅腫（部分藥物滲漏初期可能無明顯症狀，需持續觀察），此敘述過於絕對（A✗）；發生化學藥物滲漏時，應立即停止注射，但應「先回抽殘留藥液」後再拔除針頭（而非直接拔除），以減少藥物殘留組織之傷害，此敘述處置步驟不夠完整（B✗）；一般外滲處置原則為抬高患肢以減輕腫脹，但不建議加壓患部，以免加重藥物擴散及組織壓迫傷害，此敘述加壓部分有誤（D✗）。"},{n:839,no:39,subj:"腫瘤血液",q:"有關血小板減少症照護的敘述，下列何者正確？",opts:["A.病人可使用非類固醇抗發炎之止痛藥物","B.教導病人使用牙線代替牙籤","C.教導病人避免做閉氣用力的動作","D.鼻黏膜乾燥不適，不可塗抹凡士林"],ans:[2],expl:"本題答案為C。血小板減少症病人應教導避免任何會使胸內壓驟增之閉氣用力動作（如用力解便、抬重物），以降低誘發出血（尤其顱內出血）之風險，為本題答案。血小板低下病人應「避免」使用非類固醇抗發炎藥物（NSAIDs，具抗血小板功能，會加重出血風險），此敘述用藥建議有誤（A✗）；血小板低下病人應教導使用「軟毛牙刷」（而非牙線，牙線可能刮傷牙齦引發出血），此敘述口腔清潔工具建議有誤（B✗）；鼻黏膜乾燥不適時，「可」（而非不可）薄薄塗抹凡士林等潤滑劑以保護黏膜、預防因乾燥摳挖導致出血，此敘述方向有誤（D✗）。"},{n:840,no:40,subj:"其他",q:"有關預防乳癌病人術後淋巴水腫的照護，下列敘述何者正確？",opts:["A.術後第二天才可以操作手指屈曲和腕部伸展運動","B.爬牆和轉繩運動在有引流管時，就要開始做","C.側臥時，健臂在上，枕頭夾於腋下到臀部，並將手墊高","D.臥床時，用枕頭將肩部與患臂墊高，使手腕比手肘高，手肘比肩膀高"],ans:[3],expl:"本題答案為D。乳癌病人（尤其接受腋下淋巴結廓清術者）為預防患側淋巴水腫，臥床時應以枕頭墊高患側肩部及手臂，使肢體末端（手腕）高於近端（手肘），手肘高於肩膀，形成漸進抬高之姿位，以利淋巴液順利回流，為本題答案。手指屈曲及腕部伸展等溫和運動，通常於「術後當天或隔天」即可開始（而非須等到第二天才可開始），以促進循環並預防僵硬，此敘述時機延遲、並不適當（A✗）；爬牆及轉繩等較大幅度之肩關節運動，通常建議於「引流管移除後」（而非仍留置引流管時）才開始執行，以避免影響傷口癒合或引流效果，此敘述時機過早（B✗）；側臥休息時應使「患臂在上」（而非健臂在上），並以枕頭支托，避免患側肢體受壓迫影響淋巴回流，此敘述姿位有誤（C✗）。"},{n:841,no:41,subj:"腫瘤血液",q:"有關骨髓移植後病人產生移植物抗宿主疾病（Graft-versus-host Disease; GVHD）症狀，下列何者錯誤？",opts:["A.膽紅素上升","B.皮疹","C.肝功能受損","D.便祕"],ans:[3],expl:"本題答案為D。急性移植物抗宿主疾病主要侵犯皮膚、肝臟及腸胃道三大器官系統，其腸胃道症狀典型表現為大量「腹瀉」（而非便秘），此敘述症狀方向有誤，為本題答案（D✗，題目問「何者錯誤」）。GVHD侵犯肝臟會造成膽紅素上升，敘述正確（A✓）；GVHD侵犯皮膚之典型表現即為皮疹，敘述正確（B✓）；GVHD侵犯肝臟會造成肝功能指數異常及功能受損，敘述正確（C✓）。"},{n:842,no:42,subj:"腫瘤血液",q:"下列何者不是嚴重缺鐵性貧血病人常見的症狀？",opts:["A.吞嚥困難","B.舌炎、口炎","C.湯匙狀指甲","D.手足有麻木感"],ans:[3],expl:"本題答案為D。手足有麻木感較典型與維生素B12缺乏（惡性貧血）導致之周邊神經病變相關，並非嚴重缺鐵性貧血之常見或典型症狀，為本題答案（題目問「下列何者不是」嚴重缺鐵性貧血常見症狀）。嚴重缺鐵性貧血可能出現食道黏膜病變（如Plummer-Vinson症候群）造成吞嚥困難，為其可能相關症狀（A為可能症狀）；缺鐵會影響上皮組織代謝，造成舌炎、口炎等黏膜病變，為其常見症狀（B為常見症狀）；長期嚴重缺鐵可能造成指甲扁平甚至凹陷之湯匙狀指甲（匙狀甲），為其特徵性症狀之一（C為典型症狀）。"},{n:843,no:43,subj:"腫瘤血液",q:"有關骨髓抑制病人之敘述，下列何者錯誤？",opts:["A.絕對嗜中性白血球下降容易導致感染","B.血小板低於 50,000/μL 容易引起自發性出血","C.絕對嗜中性白血球低於 500/μL 要採取保護隔離","D.血紅素過低可補充紅血球濃厚液"],ans:[1],expl:"本題答案為B。血小板低於20,000/μL（而非50,000/μL）才屬於容易發生自發性（無明顯誘因）出血之高風險範圍，50,000/μL屬於中度低下、通常於外傷或侵入性處置時才較易出血的範圍，此敘述數值切點有誤，為本題答案（B✗，題目問「何者錯誤」）。絕對嗜中性白血球數目下降會使病人免疫防禦能力降低，容易導致感染，敘述正確（A✓）；絕對嗜中性白血球低於500/μL屬於嚴重低下範圍，需採取保護性隔離措施，敘述正確（C✓）；血紅素過低（貧血）可依醫囑輸注紅血球濃厚液以改善攜氧能力，敘述正確（D✓）。"},{n:844,no:44,subj:"其他",q:"下列皮膚病灶何者是原發性皮膚病變？",opts:["A.潰瘍（Ulcer）：皮膚受損傷及真皮或皮下組織","B.糜爛（Erosion）：表皮層流失，傷口潮濕界線分明的凹陷","C.抓痕（Excoriation）：表皮表面線狀、深度不一的小缺損","D.膨疹（Wheal）：皮膚腫起有明顯界線但外觀呈不規則狀"],ans:[3],expl:"本題答案為D。膨疹（蕁麻疹樣皮疹）是皮膚局部水腫腫起、界線通常清楚但外觀可呈不規則狀之原發性皮膚病灶，此描述符合原發性病灶之定義，為本題答案。潰瘍是因表皮及真皮甚至皮下組織受損所形成之續發性病灶（並非原發性病灶），此敘述病灶分類有誤（A✗）；糜爛（僅表皮層缺損，未達真皮層）亦屬於續發性皮膚病灶（因搔抓、摩擦等造成之續發性缺損），並非原發性病灶，此敘述分類有誤（B✗）；抓痕是因搔抓造成之線狀表皮缺損，同樣屬於續發性（而非原發性）皮膚病灶，此敘述分類有誤（C✗）。"},{n:845,no:45,subj:"其他",q:"有關化學物質燒傷導致皮下組織損傷的處置，下列何者錯誤？",opts:["A.休克期應預防低血鈉及代謝性酸中毒","B.利尿期應預防低血鉀及代謝性酸中毒","C.在燒傷現場應先沖洗再送醫","D.恢復期應預防急性腎衰竭"],ans:[3],expl:"本題答案為D。化學燒傷造成之皮下組織損傷，其病程分期（休克期、利尿期、恢復期）之併發症預防原則與一般熱燒傷類似，「急性腎衰竭」典型好發於燒傷「早期（休克期）」（因大量體液流失、腎臟灌流不足所致之急性腎小管壞死），而非恢復期，此敘述病程分期有誤，為本題答案（D✗，題目問「何者錯誤」）。燒傷休克期因大量體液及電解質（含鈉）流失至組織間隙及燒傷創面，須預防低血鈉及因組織灌流不足導致之代謝性酸中毒，敘述正確（A✓）；燒傷利尿期因組織間隙液體回流至血管內並經腎臟大量排出，鉀離子隨之大量流失，須預防低血鉀，同時仍須留意代謝性酸中毒之矯正，敘述正確（B✓）；化學物質燒傷現場處置原則是立即以大量清水沖洗患部，稀釋並移除化學物質後再送醫，敘述正確（C✓）。"},{n:846,no:46,subj:"其他",q:"有關燒傷病人居家照護的護理指導，下列何者錯誤？",opts:["A.每天評估傷口狀況並換藥，有感染症狀需就醫","B.已癒合傷口可塗抹乳液等潤膚劑，避免乾燥","C.避免按摩疤痕，減少疤痕增生","D.持續執行肢體復健運動，避免肢體攣縮"],ans:[2],expl:"本題答案為C。已癒合之疤痕組織可透過適度按摩促進膠原纖維排列、軟化疤痕組織、減少疤痕增生及攣縮，「避免按摩」之建議與標準疤痕照護原則相反，為本題答案（C✗，題目問「何者錯誤」）。每日評估傷口並適當換藥，發現感染徵象應儘速就醫，為正確之居家照護原則，敘述正確（A✓）；已癒合傷口皮膚因汗腺皮脂腺功能受損容易乾燥，可塗抹乳液等潤膚劑滋潤保護，敘述正確（B✓）；持續執行肢體關節活動及復健運動，有助預防疤痕攣縮造成之關節活動度受限，敘述正確（D✓）。"},{n:847,no:47,subj:"其他",q:"有關乳癌的敘述，下列何者錯誤？",opts:["A.約 5～10%乳癌與遺傳有關","B.多數乳癌腫塊會有疼痛感","C.乳房自我檢查不能檢測到所有的腫瘤","D.最常發生部位為乳房外上四分之一"],ans:[1],expl:"本題答案為B。乳癌腫塊最典型的特徵是「無痛性」腫塊（多數初期並無疼痛感，此亦是常延誤就醫之原因之一），此敘述症狀有誤，為本題答案（B✗，題目問「何者錯誤」）。約5～10%乳癌與遺傳基因（如BRCA1/2突變）相關，敘述正確（A✓）；乳房自我檢查存在偵測極限，無法檢測到所有腫瘤（尤其深部或極早期病灶），敘述正確（C✓）；乳房外上四分之一象限因乳腺組織較豐富，是乳癌最常發生之部位，敘述正確（D✓）。"},{n:848,no:48,subj:"其他",q:"有關愛滋病檢驗的敘述，下列何者正確？",opts:["A.T4 與 T8 的比值大於 1","B.當 CD4 細胞小於 400/μl 時，容易出現伺機性感染","C.沒有空窗期","D.西方墨點試驗是一種確定診斷的檢驗法"],ans:[3],expl:"本題答案為D。西方墨點試驗（Western blot）是愛滋病檢驗中用於「確認」診斷之標準檢驗方法（通常於ELISA等篩檢試驗陽性後，以西方墨點法進行確認），為本題答案。愛滋病病毒感染後，因免疫系統受破壞，T4（輔助型T細胞）數目下降而T8（毒殺型T細胞）相對變化較小，T4/T8比值通常會「小於1」（而非大於1），此敘述數值方向有誤（A✗）；當CD4細胞數目低於「200/μl」（而非400/μl）時，才屬於明確進入伺機性感染顯著高風險期之切點（美國CDC愛滋病診斷分期標準），此敘述數值切點有誤（B✗）；愛滋病毒感染後存在「空窗期」（病毒感染但尚未產生可被偵測抗體之期間，約數週至數月），並非沒有空窗期，此敘述有誤（C✗）。"},{n:849,no:49,subj:"心臟血管",q:"有關心臟衰竭合併肺水腫病人之護理措施及其原理的敘述，下列何者正確？",opts:["A.應採頭低腳高的姿勢，以增加回心血量","B.應限制液體的攝入量，以減少心臟的後負荷","C.必要時可以依醫囑給予嗎啡，以減輕前後負荷","D.須限制給氧，以減輕心臟負擔"],ans:[2],expl:"本題答案為C。心臟衰竭合併肺水腫病人依醫囑給予嗎啡，可透過中樞鎮靜、擴張周邊血管之作用，同時減輕心臟前負荷（靜脈擴張減少回心血量）及後負荷（動脈擴張降低射血阻力），並緩解焦慮呼吸窘迫感，為本題答案。應採「高坐臥姿（頭高腳低）」（而非頭低腳高），以減少回心血量、減輕肺部充血及呼吸負擔，此敘述姿位方向恰好相反（A✗）；限制液體攝入主要目的是減少「前負荷」（心臟回心血量負擔），而非後負荷（後負荷主要與周邊血管阻力相關），此敘述生理機轉配對有誤（B✗）；心臟衰竭合併肺水腫病人因肺部氣體交換障礙，應「積極給氧」（而非限制給氧）以改善組織缺氧狀態，此敘述方向恰好相反（D✗）。"},{n:850,no:50,subj:"骨骼肌肉",q:"有關類風濕性關節炎的醫療處置，下列敘述何者正確？",opts:["A.非類固醇抗炎藥物 Ibuprofen 最需擔心肝腎功能損傷問題","B.DMARDs 為育齡婦女治療的首選藥物","C.COX-2 抑制劑有延長出血時間的副作用","D.使用抗瘧疾製劑（奎寧類），應定期檢查眼睛"],ans:[3],expl:"本題答案為D。使用抗瘧疾製劑（如奎寧類藥物Hydroxychloroquine）治療類風濕性關節炎時，其重要且知名之副作用為視網膜病變，故應定期安排眼科檢查以早期發現並預防不可逆之視力損傷，為本題答案。NSAIDs類藥物（如Ibuprofen）最需擔心之副作用主要為腸胃道潰瘍出血及腎功能損傷，「肝功能損傷」並非其最需優先擔憂之副作用，此敘述並不精確（A✗）；DMARDs（疾病修飾抗風濕藥物，如Methotrexate）多具有致畸胎性，「並非」育齡婦女（尤其計畫懷孕者）之首選用藥，使用前須審慎評估避孕及生育計畫，此敘述有誤（B✗）；COX-2抑制劑之研發目的即為降低傳統NSAIDs之腸胃道副作用，其對血小板功能及出血時間之影響「較傳統NSAIDs輕微」，並非以延長出血時間為其典型副作用特徵，此敘述有誤（C✗）。"},{n:851,no:51,subj:"其他",q:"有關全身性紅斑性狼瘡（SLE）的診斷檢查，下列何者錯誤？",opts:["A.抗核性抗體（ANA）呈陽性反應","B.血清補體 C3 和 C4 值下降","C.白血球及血小板值升高","D.免疫球蛋白濃度升高"],ans:[2],expl:"本題答案為C。全身性紅斑性狼瘡因自體免疫破壞及骨髓抑制等機轉，白血球及血小板數值典型會「下降」（而非升高），為診斷及疾病活性評估之重要參考指標，此敘述方向有誤，為本題答案（C✗，題目問「何者錯誤」）。抗核性抗體（ANA）陽性是SLE最重要之篩檢及診斷指標之一，敘述正確（A✓）；SLE因免疫複合體活化補體系統，導致補體大量消耗，血清補體C3、C4數值會下降，為疾病活性評估之重要指標，敘述正確（B✓）；SLE因B細胞過度活化，會產生大量自體抗體，免疫球蛋白（尤其IgG）濃度常會升高，敘述正確（D✓）。"},{n:852,no:52,subj:"呼吸系統",q:"車禍外傷病人出現胸部右側聽不到呼吸音，且氣管向左側偏移，下列處置何者最適當？",opts:["A.準備抽血進行血液培養（blood culture）","B.準備心肺復甦術（CPR）並請其他人通知醫師","C.準備胸部針刺減壓（chest needle decompression）","D.進行動脈氣體分析（arterial blood gas analysis）"],ans:[2],expl:"本題答案為C。車禍外傷病人單側呼吸音消失合併氣管向對側偏移，是張力性氣胸之典型且危急表現（胸內壓急遽升高壓迫縱膈腔及對側肺臟），須立即進行胸部針刺減壓以緊急降低胸內壓，為搶救生命之優先處置，為本題答案。血液培養並非此危急情境下之立即優先處置，屬於後續感染評估項目（A✗，非最優先）；此病人尚未出現心跳呼吸停止之情形（僅呼吸音消失合併氣管偏移），並非須立即執行CPR之情境，且延遲針刺減壓等待其他人員通知醫師將錯失搶救先機（B✗，非最優先）；動脈氣體分析為輔助性檢驗，無法立即解除張力性氣胸造成之致命性循環壓迫，不應優先於針刺減壓處置（D✗，非最優先）。"},{n:853,no:53,subj:"呼吸系統",q:"有關放置胸管（chest tube）病人的照護，下列何者正確？",opts:["A.為避免胸管滑脫，應限制病人活動","B.平時應間歇性的夾住管路，避免過度引流","C.水封瓶內出現大量氣泡，為正常現象","D.負壓引流時，抽吸控制瓶應使用持續性抽吸"],ans:[3],expl:"本題答案為D。使用負壓引流系統（如Pleur-evac）時，抽吸控制瓶應維持「持續性」抽吸，以確保穩定且有效之負壓引流效果，為本題答案。適度鼓勵病人活動有助促進肺擴張及引流效果，「過度限制活動」並非正確之照護原則，反而應鼓勵在管路安全固定下適度活動（A✗）；胸管應維持「持續開放暢通」，不應間歇性夾住管路，以免造成張力性氣胸等危險併發症，此敘述有誤（B✗）；水封瓶內出現「持續大量」氣泡，可能提示有空氣持續漏出（如支氣管胸膜瘻管或系統漏氣），並非正常現象，須立即評估處理，此敘述有誤（C✗）。"},{n:854,no:54,subj:"呼吸系統",q:"使用卞德里氧氣面罩（Venturi mask）給氧的最主要特點為何？",opts:["A.可提供 70%以上濃度的氧氣","B.可增加用氧的溼度","C.可提供較精確的用氧濃度","D.可用於病人進食時"],ans:[2],expl:"本題答案為C。文氏面罩（Venturi mask）之設計原理是利用不同大小之空氣稀釋孔洞，提供精確、穩定且可調控之氧氣濃度（FiO2），此為其最主要之臨床特點，為本題答案。文氏面罩通常提供之氧氣濃度範圍約為24%～50%（依刻度調整），並非可提供70%以上之高濃度氧氣，此敘述有誤（A✗）；增加用氧濕度並非文氏面罩之設計核心特點，此非其最主要特色（B✗）；使用面罩給氧時進食會影響面罩密合度及氧氣供應之連續性，文氏面罩並非特別設計可用於進食時使用之裝置，此敘述有誤（D✗）。"},{n:855,no:55,subj:"消化系統",q:"下列何者不是闌尾炎的徵象？",opts:["A.透納氏徵象（Turner’s sign）","B.洛夫辛徵象（Rovsing’s sign）","C.腰大肌徵象（Psoa sign）","D.閉孔肌徵象（Obturator sign）"],ans:[0],expl:"本題答案為A。透納氏徵象（Turner's sign，腰腹部瘀斑）是急性出血性胰臟炎之特徵性表現，並非闌尾炎之典型徵象，為本題答案（題目問「下列何者不是」闌尾炎之徵象）。洛夫辛氏徵象（左下腹按壓誘發右下腹疼痛）為闌尾炎重要之特異性理學檢查徵象（B為闌尾炎徵象）；腰大肌徵象（伸直右下肢後屈曲髖關節誘發疼痛）為闌尾炎（尤其腹膜後位闌尾）重要之理學檢查徵象（C為闌尾炎徵象）；閉孔肌徵象（屈曲右髖及右膝後內旋髖關節誘發疼痛）為闌尾炎重要之理學檢查徵象（D為闌尾炎徵象）。"},{n:856,no:56,subj:"心臟血管",q:"有關抗凝劑 Warfarin 使用的注意事項，下列何者錯誤？",opts:["A.需教導病人觀察異常出血的症狀，如血尿、黑便、鼻出血等","B.需觀察顆粒白血球過少引起的發炎症狀，如發燒、喉嚨痛等","C.鼓勵服用含有高維生素 K 的食品，如青花椰菜、菠菜","D.若使用劑量不當造成出血不止，必要時可給予 Phytonadione"],ans:[2],expl:"本題答案為C。青花椰菜、菠菜等深綠色蔬菜富含維生素K，維生素K會拮抗Warfarin之抗凝血作用、降低其療效，服用Warfarin期間應維持攝取量「穩定」而非額外「鼓勵多攝取」高維生素K食品，以免影響INR數值之穩定控制，此敘述建議方向有誤，為本題答案（C✗，題目問「何者錯誤」）。應教導病人自我監測異常出血徵象（血尿、黑便、鼻出血等），以及早發現過量抗凝之併發症，敘述正確（A✓）；顆粒白血球過少（agranulocytosis）雖非Warfarin之典型副作用，但監測發燒、喉嚨痛等感染徵象為藥物安全之一般性衛教原則，可視為合理之審慎提醒（B✓，依官方答案排除邏輯視為非本題所指之錯誤選項）；Phytonadione（維生素K1）為Warfarin過量出血不止時之標準拮抗劑，敘述正確（D✓）。"},{n:857,no:57,subj:"呼吸系統",q:"下列那一種肺癌生長最快速，且最惡性但對化學及放射線治療敏感？",opts:["A.小細胞肺癌","B.鱗狀細胞癌","C.肺腺癌","D.大細胞肺癌"],ans:[0],expl:"本題答案為A。小細胞肺癌（燕麥細胞癌）生長速度最快、惡性度最高、轉移速度最快，但其細胞對化學治療及放射線治療之敏感性亦相對最高，此矛盾特性為其重要之臨床特徵，為本題答案。鱗狀細胞癌生長速度相對較慢，與小細胞肺癌之高度惡性及快速生長特徵不符（B✗）；肺腺癌是目前最常見之肺癌類型，但其生長速度及化放療敏感度不若小細胞肺癌顯著（C✗）；大細胞肺癌雖惡性度高，但生長速度及化放療敏感度仍不如小細胞肺癌之典型特徵明顯（D✗）。"},{n:858,no:58,subj:"呼吸系統",q:"有關促進急性呼吸窘迫症候群（ARDS）病人有效呼吸道清除的護理措施，下列何者正確？",opts:["A.每 2 小時給氧","B.每 4 小時翻身","C.給予鎮靜劑以促進休息","D.若咳嗽無效，可進行抽痰"],ans:[3],expl:"本題答案為D。ARDS病人若自主咳嗽無法有效清除呼吸道分泌物，應執行抽痰處置，以確保呼吸道暢通及有效氣體交換，為本題答案。ARDS病人給氧頻率應依血氧監測數值及醫囑持續調整，並非以固定「每2小時」給氧之方式進行，此敘述給氧原則不夠精確（A✗）；翻身頻率原則上建議「至少每2小時」（而非每4小時）翻身一次，以預防壓傷及促進痰液引流，此敘述頻率過於寬鬆（B✗）；過度鎮靜可能抑制自主咳嗽反射及呼吸驅動力，反而不利於呼吸道分泌物之有效清除，應審慎評估鎮靜程度，此敘述並不完全適當（C✗）。"},{n:859,no:59,subj:"呼吸系統",q:"病人的動脈血氧分析結果 PaO2 值為 50 mmHg，此病人 PaO2 的判讀及處置，下列何者正確？",opts:["A.此病人有嚴重的缺氧（hypoxia）","B.血氧氣值低但對病人不會造成威脅","C.病人的 PaO2 在正常範圍","D.可使用低流量的氧氣治療"],ans:[0],expl:"本題答案為A。PaO2正常範圍約80～100 mmHg，50 mmHg已明顯低於正常值下限，屬於嚴重缺氧之表現，需積極處置，為本題答案。PaO2 50 mmHg屬於嚴重缺氧，會對組織氧合造成顯著威脅（尤其腦部及心臟等重要器官），並非對病人不會造成威脅，此敘述有誤（B✗）；PaO2 50 mmHg明顯低於正常範圍（80～100 mmHg），並非在正常範圍內，此敘述有誤（C✗）；PaO2低至50 mmHg屬嚴重缺氧，通常需要「較高流量或濃度」之氧氣治療（甚至可能需要正壓通氣支持），而非僅使用低流量氧氣治療即可，此敘述處置強度不足（D✗）。"},{n:860,no:60,subj:"呼吸系統",q:"當慢性阻塞性肺疾病（COPD）病人出現下列何種評估結果時，護理師須優先採取因應措施？",opts:["A.杵狀指","B.白色濃痰","C.使用呼吸輔助肌","D.桶狀胸"],ans:[2],expl:"本題答案為C。COPD病人若出現大量「使用呼吸輔助肌」之情形，代表呼吸做功顯著增加、呼吸窘迫程度加劇，屬於病情惡化之急性警訊，需護理師優先介入評估處置，為本題答案。杵狀指是COPD病人長期慢性缺氧下常見之慢性外觀變化，並非需要立即優先處理之急性惡化徵象（A✗，非最優先）；白色濃痰若無合併發燒等急性感染徵象，通常反映慢性支氣管炎之慢性病程表現，急迫性低於呼吸窘迫徵象（B✗，非最優先）；桶狀胸是COPD病人因長期肺過度充氣所致之慢性胸廓外觀改變，並非急性惡化之優先處置徵象（D✗，非最優先）。"},{n:861,no:61,subj:"泌尿系統",q:"有關血液透析（HD）與持續可攜帶式腹膜透析（CAPD）治療的敘述，下列何者錯誤？",opts:["A.HD 較 CAPD 蛋白質流失較多","B.CAPD 需承擔較多的自我照顧活動","C.CAPD 易發生血中三酸甘油脂增加","D.HD 過程，易發生低血壓及頭痛、抽筋不平衡症候群"],ans:[0],expl:"本題答案為A。血液透析（HD）因使用半透膜進行體外循環過濾，蛋白質分子較大通常不易大量流失；反而是持續可攜帶式腹膜透析（CAPD）因使用腹膜作為透析膜，長期使用下蛋白質流失量通常「較HD更多」，此敘述蛋白質流失程度之比較方向有誤，為本題答案（A✗，題目問「何者錯誤」）。CAPD需病人自行執行透析液更換等居家透析程序，需承擔較多自我照顧責任，敘述正確（B✓）；CAPD因透析液中含大量葡萄糖被腹膜吸收，容易造成血中三酸甘油酯（脂質代謝異常）增加，敘述正確（C✓）；HD治療過程因短時間內大量移除體液及溶質，容易發生低血壓及不平衡症候群（頭痛、抽筋、噁心等），敘述正確（D✓）。"},{n:862,no:62,subj:"泌尿系統",q:"有關尿液檢查目的之敘述，下列何者正確？",opts:["A.尿液細菌培養是泌尿道疾病初步常規檢查","B.24 小時尿液檢查可以評估尿中蛋白質含量","C.酚紅試驗是測定腎絲球對外排除的能力","D.肌酸酐廓清率是檢驗腎小管尿液濃縮的能力"],ans:[1],expl:"本題答案為B。24小時尿液收集檢查可準確評估一整天尿中蛋白質總排出量，用以評估腎絲球通透性及腎臟病變程度，為本題答案。尿液細菌培養主要用於已懷疑泌尿道感染時之確診及選藥依據，並非常規初步篩檢項目，此敘述用途有誤（A✗）；酚紅試驗（PSP test）主要用於評估「腎小管」之排泄分泌功能（而非腎絲球濾過功能），此敘述檢驗目的配對有誤（C✗）；肌酸酐廓清率主要用於評估「腎絲球濾過率（GFR）」（而非腎小管濃縮能力），此敘述檢驗目的配對有誤（D✗）。"},{n:863,no:63,subj:"泌尿系統",q:"泌尿道結石成分為尿酸時之處置與照護，下列何者正確？",opts:["A.可使用 Probencid 降低血中尿酸值，避免復發","B.攝取鹼性食物（如肉類、乾梅或穀類等），促使尿液鹼化","C.避免攝取香菇、豆類、海鮮與內臟等，減少尿酸形成","D.需維持每日尿量，可多飲用開水、茶或啤酒等，增加尿量"],ans:[2],expl:"本題答案為C。香菇、豆類、海鮮及內臟等食物富含普林（purine），攝取後經代謝會增加尿酸生成，故尿酸性結石病人應限制此類食物攝取，以減少尿酸形成及結石復發風險，為本題答案。Probenecid為促尿酸排泄藥物，會「增加」尿液中尿酸濃度，對於已形成尿酸結石之病人可能反而增加結石復發風險，並非單純降低血中尿酸值即可避免復發之簡化建議，此敘述考量不夠周全（A✗）；肉類、乾梅及穀類等實際上多屬於「酸性（酸化尿液）」而非鹼性食物，此敘述食物屬性有誤，且尿酸性結石病人應以攝取「鹼性」食物（如多數蔬果）為主以鹼化尿液、增加尿酸溶解度（B✗）；啤酒富含普林且酒精會影響尿酸代謝排泄，並不適合作為增加尿量之飲品選項，此敘述飲品建議有誤（D✗）。"},{n:864,no:64,subj:"泌尿系統",q:"有關膀胱癌的診斷檢查與治療，下列何者錯誤？",opts:["A.尿液細胞學檢查是確認惡性細胞最方便的方式","B.以化學治療與放射線治療為主，外科切除為輔","C.膀胱鏡檢查是確診和定期追蹤的主要方式","D.膀胱化學灌藥適用於未侵犯肌肉表淺性腫瘤"],ans:[1],expl:"本題答案為B。膀胱癌之治療以「外科手術切除」為主要治療方式，化學治療及放射線治療多作為輔助或特定情況（如膀胱保留治療）之搭配治療，並非以化放療為主、外科手術為輔，此敘述治療原則主從順序有誤，為本題答案（B✗，題目問「何者錯誤」）。尿液細胞學檢查是相對方便、非侵入性且可用於初步偵測惡性細胞之檢查方式，敘述正確（A✓）；膀胱鏡檢查可直接觀察膀胱黏膜病灶並取樣切片，是確診及術後定期追蹤復發之主要標準方式，敘述正確（C✓）；膀胱內化學藥物灌注治療適用於未侵犯肌肉層之表淺性膀胱腫瘤，敘述正確（D✓）。"},{n:865,no:65,subj:"泌尿系統",q:"有關腎病症候群之照護措施，下列何者錯誤？",opts:["A.嚴重水腫時，鼓勵多下床活動，增加水分排除","B.當腎功能正常時，可採高蛋白、高熱量飲食","C.指導抗凝劑使用的注意事項，如出血徵兆","D.每日需監測輸入輸出量、體重及腹圍變化"],ans:[0],expl:"本題答案為A。腎病症候群病人因大量蛋白尿導致低白蛋白血症、血漿膠體滲透壓下降，容易出現嚴重水腫，此時應以「臥床休息」為主（而非鼓勵多下床活動），並可抬高水腫肢體以促進循環回流，過度活動反而可能增加身體不適及能量消耗，此敘述活動建議有誤，為本題答案（A✗，題目問「何者錯誤」）。當腎功能仍正常時，可採高蛋白飲食以補充經尿液流失之蛋白質，並提供足夠熱量，敘述正確（B✓）；腎病症候群病人因蛋白質流失及血液濃縮等因素，有較高血栓形成風險，可能需使用抗凝劑，應教導病人注意出血徵兆等用藥安全事項，敘述正確（C✓）；每日監測輸入輸出量、體重及腹圍變化，是評估水腫程度及治療反應之重要且必要的護理措施，敘述正確（D✓）。"},{n:866,no:66,subj:"泌尿系統",q:"有關接受經尿道前列腺切除術病人之護理指導，下列何者錯誤？",opts:["A.逆行性射精為術後常見暫時性的問題","B.3 個月內應避免騎腳踏車或跑步","C.避免上樓梯，以免因腹內壓增加而出血","D.避免坐浴或熱敷下腹部，以減少出血機會"],ans:[0],expl:"本題答案為A。經尿道前列腺切除術（TURP）後，因手術部位鄰近射精相關解剖構造受影響，逆行性射精（精液逆流入膀胱）是術後常見且多為「永久性」（而非僅暫時性）之合併症，此敘述持續時間描述有誤，為本題答案（A✗，題目問「何者錯誤」）。為避免手術部位過度活動影響傷口癒合及出血風險，術後3個月內應避免騎腳踏車或跑步等震動性活動，敘述正確（B✓）；上樓梯等增加腹內壓之動作應避免，以減少出血風險，敘述正確（C✓）；坐浴或熱敷下腹部會使局部血管擴張，增加出血風險，應避免，敘述正確（D✓）。"},{n:867,no:67,subj:"泌尿系統",q:"有關良性前列腺肥大的合併症，下列何者錯誤？",opts:["A.尿毒症","B.膀胱結石","C.壓力性尿失禁","D.尿道炎"],ans:[2],expl:"本題答案為C。壓力性尿失禁主要與骨盆底肌肉鬆弛或尿道括約肌功能不全相關（常見於女性生產後或停經後），並非良性前列腺肥大（造成下泌尿道阻塞）之典型合併症，為本題答案（題目問「下列何者錯誤」）。良性前列腺肥大長期阻塞若未妥善處理，可能因逆行性腎損傷導致尿毒症，為其重要合併症（A為合併症）；長期尿滯留使尿液滯留結晶沉澱，容易形成膀胱結石，為其常見合併症（B為合併症）；長期阻塞及尿滯留增加泌尿道感染風險，甚至可能演變為尿道炎，為其可能合併症（D為合併症）。"},{n:868,no:68,subj:"內分泌系統",q:"有關愛迪生氏危機（Addisonian crisis）之特徵，下列何者正確？",opts:["A.高血壓","B.高血糖","C.低血鉀","D.低血鈉"],ans:[3],expl:"本題答案為D。愛迪生氏危機（急性腎上腺皮質功能不足）因礦物性皮質素（醛固酮）分泌不足，導致鈉離子大量流失、鉀離子滯留，典型會出現低血鈉，為本題答案。愛迪生氏危機因血容積減少及血管張力不足，典型表現為「低血壓」（而非高血壓），甚至可能休克，此敘述方向有誤（A✗）；因糖皮質素（皮質醇）分泌不足，糖質新生作用減弱，典型會出現「低血糖」（而非高血糖），此敘述方向有誤（B✗）；因醛固酮分泌不足使鉀離子排泄減少，典型會出現「高血鉀」（而非低血鉀），此敘述方向有誤（C✗）。"},{n:869,no:69,subj:"內分泌系統",q:"有關嗜鉻細胞瘤的敘述，下列何者錯誤？",opts:["A.因病人情緒激動導致腫瘤突然釋放大量兒茶酚胺所導致","B.過量的腎上腺素與正腎上腺素會引起交感神經過度活動","C.會出現 5P 症狀：心悸、盜汗、疼痛、臉色蒼白及高血壓","D.可透過檢測病人血液當中的杏仁酸（VMA）含量確立診斷"],ans:[3],expl:"本題答案為D。診斷嗜鉻細胞瘤時，杏仁酸（VMA，兒茶酚胺代謝產物）之標準檢驗方式是收集「24小時尿液」進行定量分析（而非檢測血液），此敘述檢體來源有誤，為本題答案（D✗，題目問「何者錯誤」；且現行臨床上尿液或血漿甲氧基腎上腺素類代謝物metanephrines之敏感度及專一性已優於VMA，VMA之診斷角色已相對式微，惟此細節超出本題「血液或尿液」之核心考點）。情緒激動、壓力等刺激可誘發腫瘤突然大量釋放兒茶酚胺，導致症狀發作，敘述正確（A✓）；過量兒茶酚胺（腎上腺素、正腎上腺素）會過度活化交感神經系統，引發一系列症狀，敘述正確（B✓）；嗜鉻細胞瘤典型「5P」症狀即為心悸（Palpitation）、盜汗（Perspiration）、疼痛/頭痛（Pain）、臉色蒼白（Pallor）及高血壓（Pressure），敘述正確（C✓）。"},{n:870,no:70,subj:"內分泌系統",q:"有關糖尿病病人產生腎臟病變之敘述，下列何者正確？",opts:["A.採高蛋白飲食可預防腎功能惡化","B.是造成糖尿病病人最主要的死因","C.只會出現在第 2 型糖尿病病人","D.因腎絲球基底膜變薄且通透性降低所造成"],ans:[1],expl:"本題答案為B。糖尿病腎病變是造成糖尿病病人「最主要死因」之一（末期腎病及其相關心血管併發症），為本題答案。糖尿病腎病變病人應「限制」（而非採高蛋白飲食）蛋白質攝取，以減輕腎臟負擔、延緩腎功能惡化，此敘述飲食原則方向有誤（A✗）；糖尿病腎病變可能出現於「第1型及第2型」糖尿病病人（並非僅限第2型），此敘述好發族群範圍有誤（C✗）；糖尿病腎病變之核心病理機轉是腎絲球基底膜「增厚」且通透性「增加」（而非變薄且通透性降低），使蛋白質異常滲漏，此敘述病理機轉方向恰好相反（D✗）。"},{n:871,no:71,subj:"內分泌系統",q:"有關糖化血色素（HbA1c）檢查之敘述，下列何者正確？",opts:["A.可取代口服葡萄糖耐量試驗（OGTT）、血糖及尿糖的監測","B.用來評估缺鐵性貧血的控制成效","C.HbA1c 值在 13%以下表示糖尿病控制良好","D.可作為糖尿病的診斷標準之一"],ans:[3],expl:"本題答案為D。糖化血色素（HbA1c）數值達6.5%以上，已被納入美國糖尿病學會（ADA）等權威機構認可之糖尿病診斷標準之一，為本題答案。HbA1c反映的是「近2～3個月」的平均血糖控制情形，「無法完全取代」口服葡萄糖耐量試驗、空腹血糖及即時血糖監測（三者評估之時間範圍及臨床用途不同，仍互為輔助角色），此敘述有誤（A✗）；HbA1c是評估血糖控制情形之指標，與缺鐵性貧血之控制成效評估無關（且嚴重貧血等血液疾病狀態反而可能干擾HbA1c數值之準確性），此敘述有誤（B✗）；HbA1c數值愈高代表血糖控制愈差，「13%」屬於嚴重控制不良之範圍（一般良好控制目標多為7%以下），並非表示控制良好，此敘述判讀方向恰好相反（C✗）。"},{n:872,no:72,subj:"內分泌系統",q:"有關糖尿病性酮酸中毒（DKA）治療之敘述，下列何者正確？",opts:["A.處理低血糖","B.矯正水分過度負荷狀態","C.補充鈉離子","D.矯正血液 pH 值"],ans:[3],expl:"本題答案為D。糖尿病酮酸中毒（DKA）因酮體堆積導致嚴重代謝性酸中毒，治療重要目標之一即為矯正血液酸鹼值（pH），透過補充胰島素、輸液及電解質矯正等綜合治療改善酸血症，為本題答案。DKA病人血糖顯著「偏高」（而非低血糖），治療重點是處理高血糖狀態，此敘述方向有誤（A✗）；DKA因高血糖滲透性利尿導致嚴重「脫水」（水分不足而非過度負荷），治療需積極補充水分而非矯正水分過度負荷，此敘述方向恰好相反（B✗）；DKA病人因滲透性利尿及嘔吐等因素常伴隨「鈉離子流失」，雖需視情況補充輸液（多含鈉），但「補充鈉離子」並非DKA治療最核心之目標項目（核心目標為胰島素、輸液、鉀離子矯正及酸鹼平衡），相較於矯正pH值的重要性，此非本題最佳答案（C並非本題核心答案）。"},{n:873,no:73,subj:"內分泌系統",q:"有關糖尿病足之護理指導，下列何者正確？",opts:["A.足部保持乾燥，勿擦拭任何乳液","B.足部要使用熱水袋或電毯保暖","C.出門要穿涼鞋，以避免香港腳","D.穿鞋前要先檢視鞋內有否異物"],ans:[3],expl:"本題答案為D。糖尿病足病人穿鞋前應仔細檢查鞋內是否有異物（如小石子、縫線凸起等），以避免因周邊神經病變導致感覺遲鈍而未能及時察覺異物造成足部損傷，為本題答案。足部清潔後應適度擦拭乳液等潤膚劑保持皮膚滋潤（但避免塗抹於趾縫間，以防潮濕滋生感染），「勿擦拭任何乳液」之敘述並不適當，此建議有誤（A✗）；糖尿病病人周邊感覺神經病變使痛溫覺遲鈍，應「避免」使用熱水袋或電毯直接接觸足部，以防不自覺燙傷，此敘述有誤（B✗）；應避免穿著涼鞋等開放式鞋具，以防足部外露受傷或感染，應選擇包覆性佳、合腳之鞋襪，此敘述建議有誤（C✗）。"},{n:874,no:74,subj:"內分泌系統",q:"長期接受血液透析的病人，突然意識改變、出現抽筋及肌肉無力情況，入急診求治，抽血檢查結果：尿素氮／肌酸酐 120 mg/dL／10.6 mg/dL、鉀離子 7.8 mg/dL、鈉離子 135 mg/dL，動脈血液氣體分析結果：pH 7.28、PaO2 70 mmHg、PaCO2 30 mmHg、 HCO3 20 mEq/L。下列判斷何者正確？",opts:["A.未代償性呼吸性酸中毒","B.部分代償性代謝性酸中毒","C.完全代償性呼吸性鹼中毒","D.未代償性代謝性鹼中毒"],ans:[1],expl:"本題答案為B。此病人pH 7.28（低於正常7.35～7.45，屬酸血症）、HCO3 20 mEq/L（低於正常22～26 mEq/L，顯示代謝性成分為酸中毒之主因）、PaCO2 30 mmHg（低於正常35～45 mmHg，顯示呼吸系統代償性地增加換氣、排出CO2），但pH值仍未回復至正常範圍，符合「部分代償性代謝性酸中毒」之診斷，為本題答案。若為「未代償性呼吸性酸中毒」，應呈現PaCO2上升而非下降，與本題數據不符（A✗）；若為「完全代償性呼吸性鹼中毒」，pH值應已回復至正常範圍（7.35～7.45），但本題pH仍為7.28，明顯異常未代償完全，此敘述與數據不符（C✗）；若為「未代償性代謝性鹼中毒」，pH值應偏高（大於7.45）而非偏低7.28，此敘述與數據方向相反（D✗）。"},{n:875,no:75,subj:"內分泌系統",q:"承上題，下列處置何者錯誤？",opts:["A.口服陽離子交換樹脂（Kalmate）","B.靜脈注射正規胰島素（RI）及高張性葡萄糖液（D50W）","C.補充 0.3%氯化鈉溶液","D.緊急血液透析並持續監測心電圖變化"],ans:[2],expl:"本題答案為C。此病人血鉀高達7.8 mg/dL，屬於危及生命之嚴重高血鉀，此時緊急處置應著重於快速降低血鉀濃度（如給予陽離子交換樹脂、胰島素合併葡萄糖促使鉀離子入細胞、必要時緊急透析），「補充0.3%氯化鈉溶液（低張性生理食鹽水）」並非處理嚴重高血鉀之標準治療措施，此處置與當前最急迫之問題（高血鉀及酸中毒）不相符，為本題答案（C✗，題目問「何者錯誤」）。口服陽離子交換樹脂（Kalimate）可促使腸道排出鉀離子、降低血鉀，為適當處置，敘述正確（A✓）；靜脈注射正規胰島素併同高張性葡萄糖液，可促使鉀離子暫時性移入細胞內，快速降低血清鉀濃度，為適當之緊急處置，敘述正確（B✓）；病人腎功能已嚴重受損（尿素氮／肌酸酐顯著上升）合併嚴重高血鉀及酸中毒，緊急血液透析並持續監測心電圖變化（高血鉀可能誘發致命性心律不整），為適當且必要之處置，敘述正確（D✓）。"},{n:876,no:76,subj:"其他",q:"有關第一期心腦肺甦醒術（cardiopulmonary cerebral resuscitation; CPCR）的執行步驟，下列何者最優先？",opts:["A.靜脈輸液","B.維持循環","C.低溫治療","D.氧氣治療"],ans:[1],expl:"本題答案為B。心肺腦復甦術第一期之核心目標即為維持有效循環（包括胸外按壓建立人工循環及去顫等），是搶救心跳停止病人最優先、最基礎之處置步驟，為本題答案。靜脈輸液屬於後續（第二期）進階救命術中之處置措施，並非第一期最優先項目（A✗，非最優先）；低溫治療是心跳恢復後（第三期）用以改善神經學預後之處置措施，並非第一期優先處置（C✗，非最優先）；氧氣治療雖為重要處置之一，但心肺腦復甦術第一期之核心優先順位仍以建立有效循環（胸外按壓）為最優先，需與建立呼吸道及維持循環等步驟綜合協調執行（D✗，非本題所指最優先項目）。"},{n:877,no:77,subj:"其他",q:"依據「臺灣急診檢傷與急迫度分級量表」（TTAS），病人出現中樞性疼痛程度為 4～7 分，級數應為下列何者？",opts:["A.一級","B.二級","C.三級","D.四級"],ans:[2],expl:"本題答案為C。依據衛生福利部公告之「臺灣急診檢傷與急迫度分級量表」（TTAS）疼痛程度判定依據，中樞型疼痛依嚴重度分為重度（8～10分）對應二級、中度（4～7分）對應三級、輕度（小於4分）對應四級，本題病人中樞性疼痛程度為4～7分（中度），應歸類為「三級（緊急）」，為本題答案，此為官方公告分級表明確規範之對應級數。一級（復甦急救）對應之疼痛程度判定並非中樞型疼痛4～7分之範圍，通常對應生命徵象極度不穩定等更危急之情形（A✗）；二級（危急）對應之是中樞型「重度（8～10分）」疼痛，而非本題所述之4～7分中度疼痛，此敘述級數對應有誤（B✗）；四級（次緊急）對應之是中樞型「輕度（小於4分）」疼痛，而非本題所述之4～7分中度疼痛，此敘述級數對應有誤（D✗）。"},{n:878,no:78,subj:"其他",q:"有關敗血性休克引發瀰漫性血管內凝血（DIC）之敘述，下列何者正確？",opts:["A.體內會產生凝血因子和血小板功能被抑制","B.DIC 產生之症狀包括皮膚出現水泡","C.應優先治療敗血症之導因","D.DIC 治療包括優先提供全血輸注"],ans:[2],expl:"本題答案為C。敗血性休克引發瀰漫性血管內凝血時，治療原則應優先積極治療引發敗血症之根本病因（如抗生素控制感染源），才能從根本上中止DIC持續消耗凝血因子及血小板之惡性循環，為本題答案。DIC是因體內凝血系統「過度活化、凝血因子及血小板被大量消耗」（而非產生），導致同時出現血栓及出血傾向，此敘述機轉方向有誤（A✗）；DIC典型皮膚症狀為出血點、瘀斑及紫斑（因微血管血栓及出血所致），「水泡」並非其典型或特徵性之皮膚表現，此敘述有誤（B✗）；DIC治療原則應依病人凝血功能檢驗結果，針對性給予新鮮冷凍血漿、血小板濃厚液或特定凝血因子等成分輸血（而非一律優先給予全血輸注），此敘述輸血原則不夠精確（D✗）。"},{n:879,no:79,subj:"其他",q:"有關休克初期身體啟動之正常代償機轉，下列何者錯誤？",opts:["A.副交感神經釋放腎上腺素使心跳加快","B.腎臟血流減少","C.四肢溫度降低","D.全身末梢血管收縮"],ans:[0],expl:"本題答案為A。休克初期身體之交感神經興奮代償反應，是釋放「腎上腺素及正腎上腺素」，而此反應是由「交感神經」（而非副交感神經）系統所主導，此敘述神經系統類型有誤，為本題答案（A✗，題目問「何者錯誤」）。休克代償機轉會使血流優先重新分配至腦部及心臟等重要器官，腎臟血流因而相對減少，敘述正確（B✓）；交感神經興奮使周邊血管收縮，血液優先供應核心器官，四肢末梢因血流減少而溫度降低，敘述正確（C✓）；全身末梢血管收縮是休克代償期維持血壓、確保重要器官灌流之核心代償機轉之一，敘述正確（D✓）。"},{n:880,no:80,subj:"其他",q:"下列何者不屬於傳染病的護理評估項目？",opts:["A.疾病症狀開始的時間","B.家族疾病史","C.近期有無海外旅遊","D.居住環境"],ans:[1],expl:"本題答案為B。傳染病護理評估重點應著重於疾病本身相關之流行病學資訊，如發病時間、接觸史、旅遊史及居住環境衛生等，「家族疾病史」較常用於評估遺傳性或家族傾向性疾病（如癌症、心血管疾病等），並非傳染病護理評估之核心必要項目，為本題答案。疾病症狀開始的時間有助判斷潛伏期及疾病進程，為傳染病評估之重要項目（A為評估項目）；近期海外旅遊史有助評估病人是否暴露於特定地區流行之傳染病，為重要評估項目（C為評估項目）；居住環境（如是否群聚、衛生條件）與傳染病傳播風險密切相關，為重要評估項目（D為評估項目）。"},{n:881, no:1, subj:'神經系統', q:'有關脊髓休克（Spinal shock）的敘述，下列何者錯誤？', opts:['A.病人的肛門反射正常', 'B.受傷部位以下的肌肉力量消失', 'C.受傷部位以下的溫、痛、觸覺消失', 'D.腸蠕動下降或出現麻痺性腸阻塞'], ans:[0], expl:'本題答案為A。脊髓休克是脊髓損傷後立即發生的一種暫時性、全面性反射消失狀態，受傷平面以下所有反射（包括肛門反射、深肌腱反射等）皆會「消失」而非正常，此敘述有誤，為本題答案（A✗，題目問「何者錯誤」）。脊髓休克期間受傷部位以下之隨意肌肉力量會消失，呈現弛緩性癱瘓，敘述正確（B✓）；受傷部位以下之溫、痛、觸覺等感覺功能亦會全面消失，敘述正確（C✓）；自主神經功能同時受抑制，腸蠕動下降甚至出現麻痺性腸阻塞，敘述正確（D✓）。'},
{n:882, no:2, subj:'神經系統', q:'右側大腦損傷所引起的功能缺失，下列何者正確？①左側偏癱 ②空間及認知缺損 ③語言及計算能力降低 ④行動變得快及衝動', opts:['A.①②③', 'B.①②④', 'C.①③④', 'D.②③④'], ans:[1], expl:'本題答案為B（①②④）。右側大腦（非慣用側／空間側）損傷後，因錐體徑於延腦處交叉，會造成①對側（左側）偏癱；右腦負責②空間關係及認知功能之整合，受損後出現空間及認知功能缺損；右腦損傷病人常見④判斷力受損、行動變得衝動及缺乏危險意識，此三者組合為右側大腦損傷之典型功能缺失，選①②④＝B（本題答案）。③語言及計算能力主要由「左側大腦」（優勢半球）負責，右側大腦損傷通常不會造成語言及計算能力降低，此項不屬右腦損傷之典型缺失（③非本題所選）。'},
{n:883, no:3, subj:'神經系統', q:'有關暫時性缺血發作（transient ischemic attack; TIA）使用藥物治療，下列何者正確？', opts:['A.抗血小板凝集藥物，如：aspirin', 'B.降低腦壓藥物，如：mannitol', 'C.腦血管擴張劑，如：papaverine', 'D.預防血管痙攣劑，如：nimodipine'], ans:[0], expl:'本題答案為A。暫時性缺血發作（TIA）之病理機轉主要與血小板凝集形成微栓子有關，故藥物治療以抗血小板凝集藥物（如aspirin）為主，可降低栓塞復發及日後演變為腦梗塞之風險，為本題答案。降腦壓藥物（如mannitol）主要用於處理腦水腫、顱內壓升高之情境，並非TIA之標準藥物治療（B✗）；腦血管擴張劑（如papaverine）並非TIA之標準治療用藥，且部分血管擴張劑反而可能因「竊血現象」使缺血區域血流更差，此敘述有誤（C✗）；預防血管痙攣劑（如nimodipine）主要用於蜘蛛膜下腔出血後預防腦血管痙攣，並非TIA之標準治療（D✗）。'},
{n:884, no:4, subj:'神經系統', q:'關於多發性硬化症的敘述，下列何者正確？①為中樞神經系統髓鞘脫失而影響神經傳導 ②吞嚥困難為早期出現臨床表徵 ③腦脊髓液檢查發現 IgG 抗體增加 ④感染會引發疾病惡化', opts:['A.①②③', 'B.①②④', 'C.①③④', 'D.②③④'], ans:[2], expl:'本題答案為C（①③④）。多發性硬化症①為中樞神經系統髓鞘反覆脫失、影響神經傳導之自體免疫疾病，此為其核心病理機轉；③腦脊髓液檢查可發現寡株帶（oligoclonal bands）及IgG抗體指數增加，為重要診斷依據；④病毒感染、發燒等生理壓力常會誘發疾病惡化或復發，此三者組合正確，選①③④＝C（本題答案）。②吞嚥困難通常於疾病「病程進展後期」才出現（而非早期出現之臨床表徵），多發性硬化症早期典型表現以視力模糊、肢體無力麻木、平衡失調等為主，此項不屬早期表徵（②非本題所選）。'},
{n:885, no:5, subj:'神經系統', q:'指導重症肌無力病人之護理措施，下列何者錯誤？', opts:['A.避免過度勞累，以防誘發肌無力', 'B.應坐直立吃東西，下巴朝向胸部再行吞嚥動作', 'C.應於服用抗膽鹼酯酶藥物之後再運動', 'D.出現腹部痙攣疼痛時，可能為藥物劑量不足徵象'], ans:[3], expl:'本題答案為D。重症肌無力病人若出現腹部痙攣疼痛等膽鹼激導性危象（cholinergic crisis）症狀，通常代表抗膽鹼酯酶藥物「劑量過量」（而非不足）之徵象，此敘述方向有誤，為本題答案（D✗，題目問「何者錯誤」）。避免過度勞累有助預防誘發肌無力惡化，敘述正確（A✓）；進食時應坐直、下巴朝向胸部（頸部微前彎）以利吞嚥、預防嗆咳，敘述正確（B✓）；應於服用抗膽鹼酯酶藥物「藥效高峰期」（服藥後約45分鐘至1小時）再從事需體力之活動或運動，以確保肌力足夠，敘述正確（C✓）。'},
{n:886, no:6, subj:'神經系統', q:'75 歲老人最近心情抑鬱，對外在環境興趣缺缺，腦部電腦斷層顯示腦組織萎縮、腦溝變大，下列何者為其最可能診斷？', opts:['A.憂鬱症', 'B.譫妄症', 'C.阿茲海默氏症', 'D.巴金森氏症'], ans:[2], expl:'本題答案為C。75歲老人出現情緒抑鬱、興趣缺缺，且腦部電腦斷層顯示腦組織萎縮、腦溝變大（不可逆之結構性腦萎縮變化），此病程表現符合阿茲海默氏症（一種漸進性、不可逆之神經退化性失智症），為本題答案。單純憂鬱症通常不會伴隨腦部結構性萎縮之影像學變化，此敘述與影像學證據不符（A✗）；譫妄症為急性、可逆性之意識混亂狀態，通常有明確誘發因子（如感染、藥物），並非漸進性腦萎縮之慢性病程，此敘述不符（B✗）；巴金森氏症典型表現為靜止性顫抖、肌肉僵硬、動作遲緩等運動症狀，與題幹描述之情緒及認知相關表現不完全相符，此敘述不符（D✗）。'},
{n:887, no:7, subj:'神經系統', q:'有關脊髓損傷造成弛緩型神經性膀胱的排尿訓練，下列何者正確？', opts:['A.定時敲擊恥骨上方，以刺激排尿反射', 'B.使用副交感神經刺激劑，以利膀胱迫尿肌收縮', 'C.練習會陰肌肉收縮運動', 'D.尿管留置或尿布使用，以解決滲尿問題'], ans:[1], expl:'本題答案為B。弛緩型（下運動神經元型）神經性膀胱因薦髓排尿中樞或周邊神經受損，逼尿肌收縮無力，可考慮使用副交感神經刺激劑（如bethanechol）以促進膀胱迫尿肌收縮、協助排空，為本題答案。定時敲擊恥骨上方刺激排尿反射之手法，適用於「反射型（上運動神經元型）」神經性膀胱（薦髓以上損傷、反射弧仍完整者），並不適用於弛緩型膀胱，此敘述類型配對有誤（A✗）；會陰肌肉收縮運動（凱格爾運動）主要用於改善應力性尿失禁等骨盆底肌無力問題，並非弛緩型神經性膀胱排尿訓練之主要方法，此敘述有誤（C✗）；尿管留置或尿布使用僅為處理滲尿問題之被動、暫時性方法，並非排尿「訓練」之積極措施，此敘述並不適當（D✗）。'},
{n:888, no:8, subj:'消化系統', q:'有關闌尾炎護理措施的敘述，下列何者正確？', opts:['A.右下腹部可熱敷', 'B.手術前須先灌腸', 'C.術後鼓勵病人盡量床上休息', 'D.術後 6 週內避免提重物'], ans:[3], expl:'本題答案為D。闌尾炎手術後因腹部肌肉及傷口尚未完全癒合，應於術後6週內避免提重物等增加腹內壓之動作，以預防傷口疝氣及癒合不良，為本題答案。闌尾炎病人右下腹部應「避免熱敷」，以免促使發炎之闌尾血流增加而導致穿孔破裂風險上升，此敘述處置方向有誤（A✗）；懷疑闌尾炎時應「避免灌腸」，以免腸道蠕動增加導致闌尾穿孔風險上升，此敘述有誤（B✗）；術後應「鼓勵早期下床活動」（而非盡量臥床休息），以促進腸蠕動恢復、預防肺部及血栓相關併發症，此敘述方向有誤（C✗）。'},
{n:889, no:9, subj:'消化系統', q:'有關肛門瘻管手術治療後常見的併發症，下列何者正確？①出血 ②腹股溝疝氣 ③瘻管復發 ④解便失禁', opts:['A.①②③', 'B.①②④', 'C.①③④', 'D.②③④'], ans:[2], expl:'本題答案為C（①③④）。肛門瘻管手術治療後常見併發症包括①出血（手術傷口部位）、③瘻管復發（尤其複雜性瘳管或未完全清除感染源時）、④解便失禁（因手術可能傷及肛門括約肌功能），此三者組合正確，選①③④＝C（本題答案）。②腹股溝疝氣與肛門瘻管手術部位及機轉皆無直接相關性，並非其常見併發症（②非本題所選）。'},
{n:890, no:10, subj:'消化系統', q:'有關大腸癌病因的敘述，下列何者錯誤﹖', opts:['A.大腸息肉', 'B.發炎性腸病變', 'C.飲食習慣攝取富含植物性蛋白食物', 'D.飲食習慣缺乏高纖維食物與蔬菜'], ans:[2], expl:'本題答案為C。大腸癌病因與飲食習慣攝取「高脂肪、高動物性蛋白質、低纖維」食物相關，「攝取富含植物性蛋白食物」實際上是被認為具保護、降低大腸癌風險之飲食因子（而非致病因子），此敘述方向恰好相反，為本題答案（C✗，題目問「何者錯誤」）。大腸息肉（尤其腺瘤性息肉）具有癌變潛力，為大腸癌重要危險因子，敘述正確（A✓）；發炎性腸病變（如潰瘍性大腸炎、克隆氏症）長期發炎會增加大腸癌變風險，敘述正確（B✓）；飲食缺乏高纖維與蔬菜攝取，會使糞便中致癌物質與腸黏膜接觸時間延長，增加大腸癌風險，敘述正確（D✓）。'},
{n:891, no:11, subj:'消化系統', q:'腸道檢查前一日，可以攝取之飲食，下列何者較適當？', opts:['A.溫和飲食', 'B.限鈉飲食', 'C.半流質飲食', 'D.清流質飲食'], ans:[3], expl:'本題答案為D。腸道檢查（如大腸鏡）前一日應攝取清流質飲食，以確保腸道排空徹底、避免殘渣影響檢查視野清晰度，為本題答案。溫和飲食及半流質飲食仍含有一定殘渣，不足以達到腸道檢查前所需之清腸效果，此二者皆非最適當選項（A、C✗）；限鈉飲食與腸道檢查前之清腸準備目的無直接相關性，此敘述不適當（B✗）。'},
{n:892, no:12, subj:'消化系統', q:'有關黃疸之敘述，下列何者正確？', opts:['A.溶血性黃疸是肝硬化所致', 'B.肝細胞性黃疸之白血球數增多', 'C.阻塞性黃疸之凝血酶原時間延長', 'D.上述三種黃疸尿膽紅素皆增加'], ans:[2], expl:'本題答案為C。阻塞性黃疸因膽道阻塞使凝血因子所需之維生素K（脂溶性維生素，需膽汁協助吸收）吸收不良，導致凝血酶原時間延長，為本題答案。溶血性黃疸是因紅血球大量破壞、間接膽紅素生成過多所致（而非肝硬化所致，肝硬化較典型造成肝細胞性或阻塞性黃疸），此敘述病因配對有誤（A✗）；肝細胞性黃疸之特徵是肝功能指數（如ALT、AST）上升，並非以白血球數增多為其典型特徵，此敘述有誤（B✗）；阻塞性黃疸因膽紅素無法排入腸道，尿膽紅素會「增加」，但糞便中尿膽素原會「減少」（呈現陶土色便）；溶血性黃疸則因間接膽紅素為主，尿膽紅素通常「不會」增加，故並非三種黃疸尿膽紅素皆會增加，此敘述有誤（D✗）。'},
{n:893, no:13, subj:'心臟血管', q:'有關風濕熱之敘述，下列何者正確？①最常侵犯三尖瓣 ②須使用抗生素治療 ③應多從事體能活動以強化心臟功能 ④若有心衰竭症狀須採低鹽飲食', opts:['A.①③', 'B.①④', 'C.②③', 'D.②④'], ans:[3], expl:'本題答案為D（②④）。風濕熱是A族鏈球菌感染後引發之自體免疫反應，②須使用抗生素（如penicillin）治療原發鏈球菌感染並預防復發，此敘述正確；④風濕熱可能併發心臟瓣膜炎導致心衰竭，若出現心衰竭症狀應採低鹽飲食以減輕心臟負荷，此敘述正確，選②④＝D（本題答案）。風濕熱最常侵犯「二尖瓣」（而非三尖瓣），此敘述部位有誤（①有誤）；風濕熱病人若合併心肌炎或心臟受侵犯，急性期應以「臥床休息」為主，避免體能活動加重心臟負擔（而非多從事體能活動強化心臟功能），此敘述方向有誤（③有誤）。'},
{n:894, no:14, subj:'神經系統', q:'有關腦脊髓液的檢查，下列何者異常？', opts:['A.外觀清澈', 'B.葡萄糖的值為血糖值的 20～30 %', 'C.蛋白質為 15～45 mg/dL', 'D.側躺時壓力為 70～180 mmH2O'], ans:[1], expl:'本題答案為B。正常腦脊髓液葡萄糖值應為血糖值的60～70%左右（而非20～30%），此數值範圍明顯過低、不符合正常生理範圍，為本題答案（題目問「何者異常」）。正常腦脊髓液外觀應清澈透明，敘述符合正常範圍（A為正常）；正常腦脊髓液蛋白質範圍約15～45 mg/dL，敘述符合正常範圍（C為正常）；正常腦脊髓液側躺時壓力範圍約70～180 mmH2O，敘述符合正常範圍（D為正常）。'},
{n:895, no:15, subj:'消化系統', q:'肝穿刺切片檢查時，為避免橫膈穿孔與肝臟撕裂傷，教導病人當針頭插入肝臟時應採取的動作，下列何者正確？', opts:['A.用力深呼吸', 'B.張開嘴巴說「啊」', 'C.數個深呼吸後，深吸氣並摒住呼吸', 'D.數個深呼吸後，深吐氣並摒住呼吸'], ans:[3], expl:'本題答案為D。肝穿刺切片檢查時，教導病人於數個深呼吸後，深吐氣並摒住呼吸，此時橫膈上升、肋骨下降，可減少橫膈及肺臟受針頭穿刺損傷之風險，為本題答案。用力深呼吸會使橫膈及胸廓持續大幅活動，增加穿刺過程中臟器損傷之風險，並非正確指導方式（A✗）；張開嘴巴說「啊」並非肝穿刺切片檢查之標準呼吸配合方式，此敘述不適當（B✗）；深「吸氣」並摒住呼吸時橫膈會下降，反而使肝臟位置更貼近穿刺路徑、增加橫膈穿孔風險，此敘述方向與正確做法相反（C✗）。'},
{n:896, no:16, subj:'消化系統', q:'有關胃食道逆流病人之護理指導，下列何者錯誤？', opts:['A.應少量多餐', 'B.睡覺前吃一點宵夜', 'C.睡覺時床頭抬高', 'D.避免便秘'], ans:[1], expl:'本題答案為B。胃食道逆流病人應避免睡前進食（尤其宵夜），以免平躺時胃內容物因重力及胃排空未完成而逆流刺激食道，此建議與居家照護原則相反，為本題答案（B✗，題目問「何者錯誤」）。少量多餐可減少單次胃內容物量及胃內壓力，有助減少逆流，敘述正確（A✓）；睡覺時抬高床頭可利用重力減少逆流機會，敘述正確（C✓）；避免便秘、減少用力解便等增加腹內壓之情形，有助降低逆流風險，敘述正確（D✓）。'},
{n:897, no:17, subj:'骨骼肌肉', q:'有關退化性關節炎的敘述，下列何者正確？', opts:['A.常合併乾燥症', 'B.不會影響身體的其他系統', 'C.出現血管炎，如腳趾壞死或小腿潰瘍', 'D.出現倦怠、發燒、貧血'], ans:[1], expl:'本題答案為B。退化性關節炎主要為局部關節軟骨磨損退化之疾病，通常「不會」影響身體其他系統（屬非全身性發炎疾病，與類風濕性關節炎等全身性自體免疫疾病不同），為本題答案。退化性關節炎「較少」合併乾燥症（乾燥症較常與類風濕性關節炎等自體免疫疾病相關），此敘述關聯性有誤（A✗）；血管炎所致腳趾壞死或小腿潰瘍屬全身性血管發炎病變之表現，較典型出現於類風濕性關節炎等自體免疫疾病，並非退化性關節炎之特徵，此敘述有誤（C✗）；倦怠、發燒、貧血屬全身性發炎反應之系統性症狀，同樣較典型出現於類風濕性關節炎，退化性關節炎通常不會有此類全身性症狀，此敘述有誤（D✗）。'},
{n:898, no:18, subj:'骨骼肌肉', q:'有關脂肪栓塞症之症狀和徵象，下列何者正確？①呼吸急促 ②意識混亂 ③排尿增加 ④體溫上升', opts:['A.①②③', 'B.①②④', 'C.①③④', 'D.②③④'], ans:[1], expl:'本題答案為B（①②④）。脂肪栓塞症典型好發於長骨骨折後，脂肪滴進入血液循環阻塞微血管，會出現①呼吸急促（肺部微血管栓塞導致換氣障礙）、②意識混亂（腦部微血管栓塞導致缺氧）、④體溫上升（發炎反應），此三者組合為其典型症狀徵象，選①②④＝B（本題答案）。③排尿增加並非脂肪栓塞症之典型表現，脂肪栓塞反而可能因腎臟微血管栓塞影響腎功能，此項不屬其典型症狀（③非本題所選）。'},
{n:899, no:19, subj:'骨骼肌肉', q:'王先生，55 歲，身體質量指數為 30 kg/m²，紅血球沉降速率正常範圍，主訴早晨起來關節疼痛與僵硬，在活動幾分鐘後可緩解僵硬。下列何者為王先生最可能的診斷？', opts:['A.乾癬性關節炎（Psoriatic arthritis, PsA）', 'B.骨性關節炎（Osteoarthritis, OA）', 'C.類風濕性關節炎（Rheumatoid arthritis, RA）', 'D.痛風性關節炎（Gouty arthritis）'], ans:[1], expl:'本題答案為B。王先生身體質量指數（BMI）30 kg/m²屬肥胖範圍（體重負荷為退化性關節炎重要危險因子），紅血球沉降速率（ESR，發炎指標）正常，且晨間關節僵硬時間短暫、活動幾分鐘後即可緩解（典型少於30分鐘），此臨床表現組合（肥胖、發炎指標正常、短暫晨僵可經活動緩解）符合骨性關節炎（退化性關節炎）之典型特徵，為本題答案。乾癬性關節炎通常合併皮膚乾癬病灶及特定關節型態受侵犯，題幹未提及相關皮膚表現，與其臨床圖像不完全相符（A✗）；類風濕性關節炎典型晨僵時間「較長（通常超過1小時）」，且發炎指標（如ESR）通常會「上升」（而非正常），此二點皆與題幹描述不符（C✗）；痛風性關節炎典型表現為急性、劇烈之單一關節紅腫熱痛（好發於大腳趾），並非以晨間短暫僵硬為主要表現，與題幹描述不符（D✗）。'},
{n:900, no:20, subj:'骨骼肌肉', q:'上石膏後 24 小時內病人的護理評估結果，下列何者應做立即處置？', opts:['A.石膏表面有灼熱點', 'B.石膏肢體遠端有輕微水腫', 'C.石膏肢體內皮膚搔癢', 'D.石膏肢體有酸味'], ans:[0], expl:'本題答案為A。石膏固定後若表面出現灼熱點，可能提示石膏下方皮膚已出現壓瘡或感染等問題（石膏內部組織受壓迫或發炎產熱），須立即處置移除或開窗檢查，為本題答案。石膏肢體遠端輕微水腫在上石膏24小時內屬常見現象，通常經抬高患肢即可改善，非立即處置之緊急徵象（B✗，屬持續觀察項目而非立即處置）；石膏肢體內皮膚搔癢雖需留意（避免病人拿異物深入石膏內抓癢造成皮膚損傷），但並非需立即處置之緊急徵象（C✗）；石膏肢體有酸味可能與皮膚正常代謝或早期感染有關，仍須持續觀察評估，但急迫性低於灼熱點所提示之立即壓迫或感染徵象（D✗）。'},
{n:901, no:21, subj:'感官系統', q:'有關美尼爾氏症候群的敘述，下列何者錯誤？', opts:['A.又稱為迷路水腫', 'B.好發於 40～60 歲成人', 'C.女性病人在月經後，症狀可能惡化', 'D.易發生在長期噪音工作環境者'], ans:[2], expl:'本題答案為D。美尼爾氏症候群與內耳淋巴液代謝異常有關，其誘發因子包括鹽分攝取過多、壓力、咖啡因等，與「長期噪音工作環境」並無明確直接因果關聯（噪音暴露較典型與噪音性聽力損失相關），此敘述有誤，為本題答案（D✗，題目問「何者錯誤」）。美尼爾氏症候群又稱內淋巴水腫（迷路水腫），敘述正確（A✓）；好發於40～60歲成人，敘述正確（B✓）；部分女性病人在月經週期前後因體液滯留變化，症狀可能惡化，敘述正確（C✓）。'},
{n:902, no:22, subj:'感官系統', q:'有關鼻咽癌病理學的敘述，下列何者錯誤？', opts:['A.曾感染 EB 病毒的人就會罹患鼻咽癌', 'B.鼻咽癌病人血清中 EB 病毒抗體效價高', 'C.第六對染色體有異常基因組者，罹病率較高', 'D.鼻咽癌為上皮性癌'], ans:[0], expl:'本題答案為A。EB病毒感染是鼻咽癌重要之致病相關因子之一，但曾感染EB病毒的人「並不會」必然罹患鼻咽癌（EB病毒感染在一般人群中相當普遍，鼻咽癌實際發生率遠低於EB病毒感染率，致病機轉尚涉及基因易感性及環境因素等多重因素），此敘述過於絕對，為本題答案（A✗，題目問「何者錯誤」）。鼻咽癌病人血清中EB病毒相關抗體（如VCA-IgA）效價確實偏高，可作為篩檢及追蹤參考指標，敘述正確（B✓）；第六對染色體上人類白血球抗原（HLA）基因型異常者，鼻咽癌罹病率確實較高，顯示基因易感性角色，敘述正確（C✓）；鼻咽癌組織學上多屬未分化型「上皮性癌」，敘述正確（D✓）。'},
{n:903, no:23, subj:'感官系統', q:'有關扁桃腺炎病人接受扁桃腺切除術之敘述，下列何者錯誤？', opts:['A.適用於反覆慢性扁桃腺感染病人', 'B.不適用於有血液惡性疾病的扁桃腺炎病人', 'C.術後病人經常有吞嚥動作是正常的', 'D.術後醫囑可以開始進食時，須先進冷食'], ans:[2], expl:'本題答案為C。扁桃腺切除術後病人如經常出現吞嚥動作，可能是傷口部位出血刺激所致之危險徵象（需警覺出血可能，而非正常現象），此敘述有誤，為本題答案（C✗，題目問「何者錯誤」）。反覆慢性扁桃腺感染確實為扁桃腺切除術之適應症，敘述正確（A✓）；有血液惡性疾病（如白血病）之病人因凝血功能異常，手術出血風險高，並不適合施行扁桃腺切除術，敘述正確（B✓）；術後可開始進食時，應先給予「冷」的流質或半流質食物（如冰淇淋、冷飲），冷敷可促進血管收縮、減少出血及腫脹不適，敘述正確（D✓）。'},
{n:904, no:24, subj:'感官系統', q:'有關喉癌病人接受全喉切除術後之護理處置，下列何者錯誤？', opts:['A.維持呼吸道通暢為首要目標', 'B.協助採取側臥式', 'C.當病人坐起時需以手支托後頸', 'D.傷口癒合前須由鼻胃管補充營養'], ans:[1], expl:'本題答案為B。全喉切除術後應協助病人採「半坐臥式」（而非側臥式），以利呼吸道分泌物引流及減輕頭頸部腫脹，此敘述姿位有誤，為本題答案（B✗，題目問「何者錯誤」）。全喉切除術後病人經氣管造口呼吸，維持呼吸道通暢為術後首要且最優先之護理目標，敘述正確（A✓）；當病人坐起或改變姿勢時，因頸部肌肉及支撐構造已改變，需以手支托後頸以避免頭部過度前傾或後仰造成傷口張力，敘述正確（C✓）；因手術範圍影響吞嚥功能且傷口需癒合，術後初期須以鼻胃管灌食提供營養，待傷口癒合後再逐步練習經口進食，敘述正確（D✓）。'},
{n:905, no:25, subj:'心臟血管', q:'一位 26 歲新婚女性，有計畫懷孕，近日因心臟不適，經醫師診斷二尖瓣狹窄，並建議更換心臟瓣膜，有關瓣膜選擇與抗凝劑使用之敘述，下列何者最適當？', opts:['A.宜選用機械性人工瓣膜，並需服用 warfarin', 'B.宜選用生物性人工瓣膜，不可服用 warfarin', 'C.宜選用機械性人工瓣膜，不可服用 warfarin', 'D.宜選用生物性人工瓣膜，並需服用 warfarin'], ans:[1], expl:'本題答案為A。對於年輕、有計畫懷孕之病人，雖然機械性人工瓣膜需終身服用warfarin抗凝劑（尤其懷孕期間抗凝劑管理較為複雜，需權衡warfarin之致畸胎風險與肝素類藥物之血栓風險），但因生物性瓣膜於年輕病人（16～39歲）之結構性退化速度極快（術後10年退化率約50%、15年可達90%），意味年輕病人選用生物瓣膜極可能於中年前即需再次手術更換，故臨床上仍多建議年輕病人優先考慮機械性人工瓣膜以換取較長之瓣膜壽命，並透過孕期抗凝劑調整（如特定孕期改用低分子量肝素）來管理懷孕期間之抗凝需求，為本題答案。生物性人工瓣膜雖「不需長期服用warfarin」，但其於年輕病人退化速度快、日後極可能需要再次手術之缺點，使其並非本題情境下之最適當選擇，此敘述未完整權衡瓣膜壽命考量（B✗）；機械性人工瓣膜「必須」終身服用warfarin以預防瓣膜血栓形成，「不可服用warfarin」之敘述與機械瓣膜之抗凝需求相矛盾（C✗）；生物性人工瓣膜於年輕病人退化速度快之缺點使其非本題最適當選擇，且生物瓣膜通常「不需要」長期服用warfarin（僅短期使用），此敘述搭配有誤（D✗）。'},
{n:906, no:26, subj:'心臟血管', q:'心臟衰竭病人使用 Dopamine 6 ug/kg/min，給予該劑量 Dopamine 之最主要目的為何？', opts:['A.增加腎臟血流量', 'B.促進周邊血管收縮', 'C.使心肌收縮力增加', 'D.降低腎絲球過濾率'], ans:[2], expl:'本題答案為C。低劑量Dopamine（一般指2～10 ug/kg/min之β1受體作用範圍）主要作用為活化心臟β1受體，增加心肌收縮力及心輸出量，此為心臟衰竭病人使用此劑量Dopamine之最主要治療目的，為本題答案。極低劑量Dopamine（約0.5～3 ug/kg/min，作用於多巴胺受體）主要與增加腎臟血流有關，但6 ug/kg/min已進入以β1受體作用為主之劑量範圍，增加腎臟血流並非此劑量之最主要目的（A✗，非最主要目的）；促進周邊血管收縮屬於「高劑量」Dopamine（約大於10 ug/kg/min，作用於α受體）之效應，並非6 ug/kg/min劑量範圍之主要作用（B✗）；降低腎絲球過濾率與Dopamine之藥理作用方向相反，此劑量範圍反而有助維持或增加腎臟灌流，此敘述有誤（D✗）。'},
{n:907, no:27, subj:'心臟血管', q:'有關心臟復健（Cardiac Rehabilitation, CR）運動原則之敘述，下列何者錯誤？', opts:['A.運動前應先暖身 5～10 分鐘', 'B.為達到最大運動效果，可以摒住呼吸', 'C.用餐後不宜立刻運動', 'D.運動強度之最大心率以（220－年齡）×70～85%為原則'], ans:[1], expl:'本題答案為B。心臟復健運動過程中應教導病人「避免」摒住呼吸（Valsalva動作會使胸內壓驟增、影響靜脈回流及血壓，可能誘發心律不整或血壓劇烈波動），此建議與運動安全原則相反，為本題答案（B✗，題目問「何者錯誤」）。運動前應先暖身5～10分鐘，讓心血管系統逐漸適應運動強度，敘述正確（A✓）；用餐後因血液集中供應消化系統，不宜立刻運動，以免造成心臟負擔或不適，敘述正確（C✓）；運動強度之目標心率計算公式（220－年齡）×70～85%為心臟復健常用之運動強度設定原則，敘述正確（D✓）。'},
{n:908, no:28, subj:'心臟血管', q:'下列何項檢查無法評估心輸出量？', opts:['A.心臟超音波', 'B.肺動脈導管', 'C.心導管檢查', 'D.運動心電圖'], ans:[3], expl:'本題答案為D。運動心電圖主要用於評估病人在運動負荷下之心臟電氣活動變化及缺血反應（如ST節段變化），無法直接測量或評估心輸出量數值，為本題答案（題目問「下列何項檢查無法評估心輸出量」）。心臟超音波可透過測量心室容積及射出分率等參數計算心輸出量，能評估心輸出量（A為可評估項目）；肺動脈導管（Swan-Ganz導管）可直接以熱稀釋法測量心輸出量，是評估心輸出量之重要侵入性工具（B為可評估項目）；心導管檢查過程中亦可測量心輸出量相關血液動力學數據，能評估心輸出量（C為可評估項目）。'},
{n:909, no:29, subj:'心臟血管', q:'有關冠狀動脈疾病病人接受鉈-201 之檢查目的，下列何者正確？', opts:['A.監測僧帽瓣及主動脈瓣的功能', 'B.觀察心室收縮及舒張的情形', 'C.確定心肌受傷的部位與範圍', 'D.判定心臟電氣傳導的狀態'], ans:[2], expl:'本題答案為C。鉈-201（Thallium-201）心肌灌注掃描主要用於評估心肌血流灌注情形，可用以確定冠狀動脈疾病病人心肌受傷（缺血或梗塞）之部位與範圍，為本題答案。監測僧帽瓣及主動脈瓣功能主要透過心臟超音波等影像學檢查進行，並非鉈-201檢查之主要目的（A✗）；觀察心室收縮及舒張情形主要透過心臟超音波或心室造影評估，並非鉈-201檢查之核心目的（B✗）；判定心臟電氣傳導狀態主要透過心電圖相關檢查（如心電生理檢查）評估，與鉈-201核醫灌注掃描之目的不同（D✗）。'},
{n:910, no:30, subj:'心臟血管', q:'有關二尖瓣閉鎖不全或逆流所產生之心雜音，在心動周期出現的時間，下列何者正確？', opts:['A.舒張全期', 'B.舒張前期', 'C.收縮全期', 'D.收縮末期'], ans:[2], expl:'本題答案為C。二尖瓣閉鎖不全（二尖瓣逆流）所產生之心雜音，因血液於整個心室收縮期間持續經二尖瓣逆流回左心房，故典型於「收縮全期」出現，為本題答案。舒張全期心雜音較典型出現於主動脈瓣或肺動脈瓣閉鎖不全（而非二尖瓣閉鎖不全），此敘述心動週期時相有誤（A✗）；舒張前期心雜音較典型與二尖瓣「狹窄」（而非閉鎖不全）相關，此敘述有誤（B✗）；收縮末期心雜音較典型與二尖瓣脫垂相關，並非二尖瓣閉鎖不全之典型表現時相，此敘述有誤（D✗）。'},
{n:911, no:31, subj:'心臟血管', q:'下列血脂肪之檢驗值何者不正常？', opts:['A.低密度脂蛋白 170 mg/dL', 'B.高密度脂蛋白 60 mg/dL', 'C.總膽固醇 150 mg/dL', 'D.低密度脂蛋白/高密度脂蛋白=1.5'], ans:[0], expl:'本題答案為A。低密度脂蛋白（LDL，俗稱壞膽固醇）理想數值應低於130 mg/dL（依風險程度不同標準略有差異，一般建議低於100～130 mg/dL），170 mg/dL明顯偏高，屬不正常數值，為本題答案。高密度脂蛋白（HDL，俗稱好膽固醇）60 mg/dL屬於理想、甚至具保護性之數值範圍（HDL愈高愈好，正常參考值大於40～60 mg/dL），此數值屬正常範圍（B為正常）；總膽固醇理想數值應低於200 mg/dL，150 mg/dL屬正常範圍（C為正常）；低密度脂蛋白／高密度脂蛋白比值理想應小於3.5～5.0，1.5屬理想健康範圍（D為正常）。'},
{n:912, no:32, subj:'腫瘤血液', q:'有關惡性腫瘤特徵的敘述，下列何者正確？①細胞通常分化不良 ②腫瘤通常有被膜包覆 ③生長速度通常很迅速 ④易轉移易復發', opts:['A.①②③', 'B.①②④', 'C.①③④', 'D.②③④'], ans:[2], expl:'本題答案為C（①③④）。惡性腫瘤細胞特徵包括①細胞分化通常不良（低分化、異型性高）、③生長速度通常迅速、④容易轉移且易復發，此三者組合為惡性腫瘤之典型特徵，選①③④＝C（本題答案）。惡性腫瘤通常「無」被膜包覆（浸潤性生長、邊界不清），有完整被膜包覆反而是「良性」腫瘤之特徵，②敘述方向有誤（②非本題所選）。'},
{n:913, no:33, subj:'腫瘤血液', q:'病人的皮膚黏膜蒼白、舌頭發炎呈紅色平滑狀，指甲萎縮、變薄呈湯匙狀，可能罹患下列何種貧血？', opts:['A.葉酸缺乏性貧血', 'B.缺鐵性貧血', 'C.惡性貧血', 'D.再生不良性貧血'], ans:[1], expl:'本題答案為B。缺鐵性貧血因鐵質不足影響上皮組織代謝，典型會出現皮膚黏膜蒼白、舌炎（舌頭發炎呈紅色平滑狀，因舌乳頭萎縮）、指甲扁平甚至凹陷呈湯匙狀（匙狀甲）等特徵性表現，為本題答案。葉酸缺乏性貧血屬巨球性貧血，典型表現以疲倦、舌炎為主，但湯匙狀指甲並非其特徵性表現（A✗）；惡性貧血（維生素B12缺乏）除貧血症狀外，典型會合併周邊神經病變（如肢體麻木刺痛感、步態不穩），而非以湯匙狀指甲為特徵性表現（C✗）；再生不良性貧血因骨髓造血功能全面受抑制，表現以全血球減少相關症狀（貧血、易感染、易出血）為主，湯匙狀指甲並非其典型特徵（D✗）。'},
{n:914, no:34, subj:'腫瘤血液', q:'有關癌症手術治療特性之敘述，下列何者正確？', opts:['A.冷凍手術是一種診斷疾病分期的手術', 'B.手術治療是切除原發癌或已轉移的固態實質腫瘤', 'C.手術適用於細胞分化差、生長快速且局部的腫瘤', 'D.雷射手術優點是切除腫瘤組織，但會增加手術出血的危險'], ans:[1], expl:'本題答案為B。手術治療之主要角色是切除原發性腫瘤或已可切除之轉移病灶（固態實質腫瘤），為癌症局部治療之重要手段，為本題答案。冷凍手術是一種「治療性」（破壞腫瘤組織）之手術方式，並非用於診斷疾病分期之手術，此敘述目的有誤（A✗）；手術治療較適用於「侷限、尚未廣泛轉移」之腫瘤，「細胞分化差、生長快速」之腫瘤通常代表惡性度高、易早期轉移，手術治療效果較有限，此敘述適應症配對有誤（C✗）；雷射手術之優點是能精準切除病灶組織「同時具凝血止血效果、減少手術出血」，並非增加出血危險，此敘述方向恰好相反（D✗）。'},
{n:915, no:35, subj:'腫瘤血液', q:'當癌症病人出現下列何種血液檢驗數據時，要考慮停止化學治療？①白血球 1,500/μL ②紅血球500 萬/μL ③血小板 11 萬/μL ④絕對嗜中性球 1,000/μL', opts:['A.①②', 'B.①④', 'C.②③', 'D.③④'], ans:[1], expl:'本題答案為B（①④）。①白血球1,500/μL已接近或低於化學治療安全閾值（一般以白血球低於3,000/μL、絕對嗜中性球低於1,000～1,500/μL作為考慮暫停化療之參考依據）；④絕對嗜中性球1,000/μL已達可能需考慮暫停化療、預防嚴重感染之閾值範圍，此二者組合正確，選①④＝B（本題答案）。②紅血球500萬/μL屬正常或偏高範圍，並非停止化療之考量依據（②非本題所選）；③血小板11萬/μL（110,000/μL）仍高於一般化療安全閾值（通常低於100,000/μL才需考慮調整化療），屬安全範圍，並非停止化療之考量依據（③非本題所選）。'},
{n:916, no:36, subj:'腫瘤血液', q:'有關靜脈導管 Port-A 之敘述，下列何者正確？①放置 Port-A 人工血管，須採全身麻醉方式 ②Port-A導管可由腋靜脈放置到鎖骨下靜脈 ③注射起泡性藥物時，應測試是否有回血 ④注射藥物時，使用一般空針 90 度插入，以免發生外滲', opts:['A.①③', 'B.①④', 'C.②③', 'D.②④'], ans:[2], expl:'本題答案為C（②③）。②Port-A導管可經由鎖骨下靜脈、頸內靜脈或腋靜脈等路徑放置導管尖端至上腔靜脈，此敘述路徑正確；③注射起泡性（vesicant）化療藥物前，應先測試是否有回血，確認導管尖端位置正確且通暢，以降低藥物外滲組織之風險，此敘述正確，選②③＝C（本題答案）。放置Port-A人工血管通常採「局部麻醉」（而非全身麻醉）方式即可完成，此敘述麻醉方式有誤（①有誤）；注射藥物時應使用專用之「非核心針（no-coring needle，如Huber針）」以特定角度插入（而非使用一般空針90度插入），以避免損壞導管膈膜及發生外滲，此敘述器材使用有誤（④有誤）。'},
{n:917, no:37, subj:'腫瘤血液', q:'有關癌症病人血鈣之敘述，下列何者錯誤？', opts:['A.癌細胞轉移到骨頭，會出現低血鈣的現象', 'B.白蛋白數值低下時需矯正鈣質數值，以免低估了高血鈣的狀況', 'C.高血鈣的治療是補充大量水分', 'D.利尿劑可促進腎臟對鈣的排泄'], ans:[0], expl:'本題答案為A。癌細胞轉移至骨頭會破壞骨質、促使鈣質釋放進入血液，典型會出現「高血鈣」（而非低血鈣）之現象，此為癌症重要之腫瘤急症之一，此敘述方向有誤，為本題答案（A✗，題目問「何者錯誤」）。白蛋白為鈣離子重要之攜帶蛋白，當白蛋白數值低下時，總鈣測量值可能被低估，需以校正公式矯正後才能正確判讀，避免低估實際游離鈣濃度及高血鈣狀況，敘述正確（B✓）；高血鈣治療首要措施是大量輸液水化，以稀釋血鈣並促進腎臟排泄，敘述正確（C✓）；利尿劑（尤其類固醇利尿劑）可促進腎臟對鈣離子之排泄，輔助降低血鈣，敘述正確（D✓）。'},
{n:918, no:38, subj:'消化系統', q:'有關食道靜脈曲張藥物治療之敘述，下列何者錯誤？', opts:['A.Furosemide', 'B.Propranolol', 'C.Sandostatin', 'D.Vasopressin'], ans:[0], expl:'本題答案為A。Furosemide為利尿劑，主要用於處理水腫、心衰竭等體液過多情形，並非食道靜脈曲張之標準藥物治療，為本題答案（題目問「何者錯誤」）。Propranolol（乙型阻斷劑）可降低肝門脈壓力，是預防食道靜脈曲張出血之常用藥物（B為正確藥物）；Sandostatin（octreotide，體抑素類似物）可收縮內臟血管、降低肝門脈壓力，用於食道靜脈曲張急性出血之治療（C為正確藥物）；Vasopressin可強力收縮內臟血管、降低肝門脈血流及壓力，為食道靜脈曲張出血傳統治療用藥之一（D為正確藥物）。'},
{n:919, no:39, subj:'腫瘤血液', q:'有關癌症病人發生口腔炎之護理指導，下列何者錯誤？', opts:['A.教導飯前使用 0.1% xylocaine 漱口，以減輕疼痛', 'B.鼓勵飯後 30 分鐘內，以軟毛牙刷清潔口腔', 'C.教導食用冷的流質食物，增加維生素攝取', 'D.鼓勵自行購買漱口水清潔口腔'], ans:[3], expl:'本題答案為D。癌症病人發生口腔炎時，應避免自行購買市售漱口水（許多含酒精成分之漱口水會刺激已發炎脆弱之口腔黏膜，加重疼痛及損傷），應使用醫療團隊建議之口腔照護溶液，此建議並不適當，為本題答案（D✗，題目問「何者錯誤」）。飯前使用低濃度局部麻醉劑（如0.1% xylocaine）漱口，可暫時減輕口腔疼痛以利進食，敘述正確（A✓）；飯後以軟毛牙刷輕柔清潔口腔，可維持口腔衛生且降低對發炎黏膜之刺激，敘述正確（B✓）；食用冷的流質食物不僅可減輕口腔黏膜刺激不適，也有助補充所需營養，敘述正確（C✓）。'},
{n:920, no:40, subj:'其他', q:'下列何種皮膚疾病是由自體免疫系統所引起，會出現急性炎症反應但不具傳染性？', opts:['A.鵝口瘡', 'B.帶狀疱疹', 'C.紅斑性狼瘡', 'D.疥瘡'], ans:[2], expl:'本題答案為C。紅斑性狼瘡是一種自體免疫系統異常所引發之慢性發炎疾病，會出現急性皮膚炎症反應（如蝴蝶斑），但屬自體免疫反應而「不具傳染性」，為本題答案。鵝口瘡是由白色念珠菌感染引起，屬「感染性」疾病（非自體免疫疾病），此敘述不符（A✗）；帶狀疱疹是由水痘帶狀疱疹病毒感染引起，具有傳染性（可傳染引發水痘），並非自體免疫疾病，此敘述不符（B✗）；疥瘡是由疥蟎寄生引起之「傳染性」皮膚病，並非自體免疫疾病，此敘述不符（D✗）。'},
{n:921, no:41, subj:'心臟血管', q:'有關大面積重度燒傷初期（48 小時內），對於心臟血管系統造成的影響，下列何者錯誤？', opts:['A.中心靜脈壓升高', 'B.心輸出量減少', 'C.全身性水腫', 'D.脈搏淺快'], ans:[0], expl:'本題答案為A。大面積重度燒傷初期（48小時內）因體液大量滲漏至組織間隙及燒傷創面（微血管通透性增加），造成血管內液體容積不足，中心靜脈壓應「降低」（而非升高），此敘述方向有誤，為本題答案（A✗，題目問「何者錯誤」）。因血管內容積不足，心臟輸出量會下降，敘述正確（B✓）；大量體液滲漏至組織間隙，會造成全身性水腫，敘述正確（C✓）；血容積不足加上代償性交感神經興奮，會出現脈搏淺快（心跳快但脈搏強度弱）之表現，敘述正確（D✓）。'},
{n:922, no:42, subj:'其他', q:'有關足癬的敘述，下列何者錯誤？', opts:['A.為黴菌感染', 'B.多因穿不透氣鞋襪而引起', 'C.急性期出現紅斑', 'D.可於趾間灑上滑石粉維持乾燥'], ans:[2], expl:'本題答案為C。足癬（香港腳）急性期典型會出現水泡、糜爛滲液等表現，「紅斑」較非其急性期最典型或最具特徵性之表現（相對水泡、脫皮、糜爛滲液等表現更具代表性），此敘述不夠精確，為本題答案（C✗，題目問「何者錯誤」，依官方答案認定此為錯誤選項）。足癬確實為皮癬菌（黴菌）感染所致，敘述正確（A✓）；長期穿著不透氣鞋襪造成足部潮濕悶熱環境，有利黴菌滋生，是足癬重要誘發因子，敘述正確（B✓）；於趾縫間灑上滑石粉等吸濕劑有助維持局部乾燥，減少黴菌滋生環境，為適當之預防措施，敘述正確（D✓）。'},
{n:923, no:43, subj:'其他', q:'有關化學性灼傷的處置，下列何者錯誤？', opts:['A.立即去除身上的化學物質', 'B.可將化學藥劑的中和劑塗抹在皮膚接觸部位', 'C.以大量流動的水沖洗接觸部位至少 20 分鐘', 'D.眼睛灼傷時，須用生理食鹽水或清水沖洗'], ans:[1], expl:'本題答案為B。化學性灼傷處置應立即以「大量清水沖洗」患部，而非將化學藥劑之中和劑塗抹於皮膚接觸部位（中和反應本身可能產生額外熱能，反而加重組織損傷），此建議並不適當，為本題答案（B✗，題目問「何者錯誤」）。立即去除身上殘留之化學物質（如衣物、粉塵），可減少持續性傷害，敘述正確（A✓）；以大量流動清水沖洗接觸部位至少20分鐘，是化學性灼傷急救之核心處置原則，敘述正確（C✓）；眼睛灼傷時應立即以生理食鹽水或清水持續沖洗，避免化學物質造成角膜等眼部組織進一步損傷，敘述正確（D✓）。'},
{n:924, no:44, subj:'其他', q:'有關過敏性休克之敘述，下列何者錯誤？', opts:['A.過敏反應發生後數分鐘內休克，可能會有死亡的危機', 'B.因接觸外來物質所引起，如藥物、花粉、灰塵等', 'C.由嗜酸性細胞釋出具血管活性的介質，如組織胺、白三烯素', 'D.再次碰到相同過敏原，會產生大量抗體 IgE'], ans:[2], expl:'本題答案為C。過敏性休克是由「肥大細胞及嗜鹼性球」（而非嗜酸性細胞）釋出組織胺、白三烯素等血管活性介質所引發之全身性過敏反應，此敘述細胞類型有誤，為本題答案（C✗，題目問「何者錯誤」）。過敏性休克可於接觸過敏原後數分鐘內迅速發生休克，具有致命風險，敘述正確（A✓）；過敏性休克是因接觸外來過敏原物質（如藥物、花粉、灰塵、食物等）所引起，敘述正確（B✓）；過敏性休克屬第一型（立即型）過敏反應，機轉涉及再次接觸相同過敏原時，體內會產生大量IgE抗體並與肥大細胞結合，誘發介質釋放，敘述正確（D✓）。'},
{n:925, no:45, subj:'其他', q:'一位 30 歲女性主訴最近出現皮膚對光敏感、對稱性關節疼痛、口腔潰瘍，另補體 C3 及 C4 減少、抗核抗體（ANA）呈現陽性、紅血球沉降速率（ESR）明顯上升、血小板減少，下列何者為其最可能之診斷？', opts:['A.痛風性關節炎', 'B.後天免疫缺乏症候群', 'C.全身性紅斑性狼瘡', 'D.類風濕性關節炎'], ans:[2], expl:'本題答案為C。病人出現皮膚對光敏感、對稱性關節疼痛、口腔潰瘍等多重系統症狀，加上補體C3、C4減少（免疫複合體活化消耗補體）、抗核抗體（ANA）陽性、紅血球沉降速率上升（發炎指標）、血小板減少等免疫及血液學異常，此組合高度符合全身性紅斑性狼瘡（SLE）之診斷條件，為本題答案。痛風性關節炎主要表現為急性單一關節劇痛，並不會合併皮膚對光敏感、口腔潰瘍及補體下降等免疫學異常，與題幹描述不符（A✗）；後天免疫缺乏症候群（愛滋病）主要與病毒感染及免疫功能低下相關，並非以對稱性關節疼痛、補體下降、ANA陽性等表現為特徵，與題幹描述不符（B✗）；類風濕性關節炎典型較少出現皮膚對光敏感之表現，且ANA陽性並非其主要診斷依據（類風濕因子及抗CCP抗體較具特異性），與題幹描述之整體表現組合較不吻合（D✗）。'},
{n:926, no:46, subj:'骨骼肌肉', q:'有關治療類風濕性關節炎使用之藥物，下列何者不適當？', opts:['A.水楊酸藥物，如 aspirin', 'B.免疫抑制劑，如 methotrexate', 'C.糖皮質類固醇，如 prednisone', 'D.利尿劑，如 furosemide（Lasix）'], ans:[3], expl:'本題答案為D。利尿劑（如furosemide）主要用於處理水腫、高血壓等體液相關問題，並非治療類風濕性關節炎之標準用藥，為本題答案（題目問「何者不適當」）。水楊酸類藥物（如aspirin）具消炎止痛作用，為治療類風濕性關節炎常用藥物之一（A為適當藥物）；免疫抑制劑（如methotrexate）為疾病修飾抗風濕藥物（DMARDs）之代表藥物，是治療類風濕性關節炎之核心用藥（B為適當藥物）；糖皮質類固醇（如prednisone）可快速抑制發炎反應，常用於類風濕性關節炎急性發炎期之輔助治療（C為適當藥物）。'},
{n:927, no:47, subj:'其他', q:'愛滋病病人感染肺囊蟲肺炎之初期主要症狀，下列何者正確？', opts:['A.體重下降', 'B.皮疹', 'C.氣喘', 'D.乾咳'], ans:[3], expl:'本題答案為D。愛滋病病人因細胞免疫功能低下，容易併發肺囊蟲肺炎（Pneumocystis jirovecii pneumonia, PCP），其初期主要症狀為持續性乾咳、漸進性呼吸困難及低度發燒，其中乾咳為早期最常見之主要症狀，為本題答案。體重下降屬愛滋病整體病程中常見之非特異性慢性表現，並非肺囊蟲肺炎「初期」之主要症狀（A✗，非最優先）；皮疹並非肺囊蟲肺炎之典型初期症狀，與此感染之核心呼吸道表現關聯性較低（B✗）；肺囊蟲肺炎之呼吸道症狀典型以漸進性呼吸困難為主，「氣喘」（喘鳴聲）並非其最典型或最初期之主要表現（C✗）。'},
{n:928, no:48, subj:'呼吸系統', q:'有關肺栓塞病人之護理處置，下列敘述何者最正確？', opts:['A.教導病人應多食用青花椰菜、甘藍、菠菜等', 'B.教導病人坐姿時，應避免翹二郎腿或交叉雙腿', 'C.教導病人胸痛時，可服用 NTG 緩解疼痛', 'D.教導病人使用誘發性肺量計（incentive spirometry），增進肺部血流'], ans:[1], expl:'本題答案為B。肺栓塞病人應教導避免翹二郎腿或交叉雙腿等會壓迫下肢靜脈、影響血液回流之姿勢，以預防深部靜脈血栓形成、降低肺栓塞復發風險，為本題答案。青花椰菜、甘藍、菠菜等深綠色蔬菜富含維生素K，若病人正服用warfarin類抗凝劑，攝取過多維生素K會拮抗其抗凝血效果，此建議需視個別病人抗凝藥物使用情形審慎衛教（而非概括鼓勵多食用），此敘述不夠嚴謹（A✗）；肺栓塞病人若出現胸痛，NTG（硝化甘油）主要用於緩解心絞痛（冠狀動脈相關），並非治療肺栓塞胸痛之藥物，此敘述用藥不適當（C✗）；誘發性肺量計主要用於促進肺部擴張、預防肺擴張不全（atelectasis），並非直接「增進肺部血流」之工具，此敘述目的描述有誤（D✗）。'},
{n:929, no:49, subj:'呼吸系統', q:'有關氣喘病人使用糖皮質類固醇吸入劑（glucocorticoid inhaled medication）之護理指導，下列何者正確？', opts:['A.將此藥含在口中 15 秒後再緩慢吸入', 'B.當急性發作時應立即使用此藥緩解', 'C.使用此藥物後應漱口', 'D.此藥不可突然停藥必須逐漸減量'], ans:[2], expl:'本題答案為C。使用糖皮質類固醇吸入劑後應教導病人立即漱口，以清除口腔及咽喉部殘留藥物，預防口腔念珠菌感染（鵝口瘡）及聲音沙啞等局部副作用，為本題答案。糖皮質類固醇吸入劑之正確使用方式應為深吸入後屏氣約10秒（而非含在口中15秒後再吸入），此敘述使用方式有誤（A✗）；糖皮質類固醇吸入劑屬「預防、控制」性藥物（非急救藥物），並非用於氣喘「急性發作」時之立即緩解，急性發作應使用短效支氣管擴張劑，此敘述用途有誤（B✗）；糖皮質類固醇吸入劑「不需要」逐漸減量停藥之特殊考量（此為口服全身性類固醇長期使用才需注意之停藥原則），此敘述並不適用於吸入劑型（D✗）。'},
{n:930, no:50, subj:'呼吸系統', q:'當肺炎病人出現呼吸道清除功能失效與分泌物增加，且無法進行有效性咳嗽。下列護理措施何者最能促進其清除痰液？', opts:['A.鼓勵病人採胸式呼吸', 'B.鼓勵病人增加飲水量', 'C.教導病人用噘嘴式呼吸', 'D.協助病人採半坐臥式'], ans:[1], expl:'本題答案為D。肺炎病人若咳嗽反射無效、無法自行有效清除分泌物，協助採半坐臥式可利用重力原理，促進肺部擴張及分泌物向上呼吸道引流，是最能促進痰液清除之護理措施，為本題答案。胸式呼吸吸氣量較淺，不利深部痰液鬆動及排出，鼓勵「腹式呼吸」較能增進換氣效率，此敘述呼吸方式建議不適當（A✗）；增加飲水量有助稀釋痰液、利於咳出，但屬輔助性措施，效果不如姿位引流直接（B✗，非最能促進痰液清除之措施）；噘嘴式呼吸主要用於延長吐氣時間、預防小氣道塌陷（常用於COPD病人），並非以促進痰液清除為主要目的，此敘述目的配對有誤（C✗）。'},
{n:931, no:51, subj:'呼吸系統', q:'有關慢性阻塞性肺疾病（COPD）的病人使用噘嘴式呼吸的目的，下列何者正確？', opts:['A.減少二氧化碳滯留在肺部', 'B.促進痰液排除', 'C.降低呼吸道的壓力', 'D.增加橫膈的肌肉力量'], ans:[0], expl:'本題答案為A。COPD病人使用噘嘴式呼吸，透過延長吐氣時間及製造輕度呼氣末正壓，可維持小氣道開放、減少氣體滯留，進而幫助排出體內滯留的二氧化碳，改善換氣效率，為本題答案。噘嘴式呼吸主要作用於改善通氣效率，並非直接促進痰液排除之技巧（有效咳嗽及姿位引流才是促進痰液排除之主要方法），此敘述目的有誤（B✗）；噘嘴式呼吸是透過「增加」（而非降低）呼吸道內壓力（呼氣末正壓效應）來維持小氣道通暢，此敘述方向有誤（C✗）；噘嘴式呼吸主要著重於呼吸「型態」之調整（吐氣時間延長），並非以增加橫膈肌肉力量為主要目的（增加橫膈肌力需透過特定阻力訓練），此敘述目的有誤（D✗）。'},
{n:932, no:52, subj:'呼吸系統', q:'外傷性肋骨骨折病人可能出現之徵候與症狀，下列何者正確？', opts:['A.慢且深的呼吸型態，且疼痛持續存在', 'B.快且深的呼吸型態，且吐氣時疼痛感加劇', 'C.較淺的呼吸型態，且吸氣時疼痛感加劇', 'D.喟嘆式的呼吸型態，且飯後疼痛感加劇'], ans:[2], expl:'本題答案為C。外傷性肋骨骨折病人因疼痛，典型會出現較淺快之呼吸型態，且「吸氣」時因胸廓擴張牽動骨折處，疼痛感會加劇，此為肋骨骨折病人典型之呼吸型態與疼痛關聯表現，為本題答案。肋骨骨折因疼痛通常會使呼吸變得「淺快」（而非慢且深），此敘述呼吸型態方向有誤（A✗）；肋骨骨折病人因疼痛，呼吸型態通常會變得「較淺」（而非快且深），且疼痛感在「吸氣」時（而非吐氣時）因胸廓擴張而加劇，此敘述型態及疼痛時相皆有誤（B✗）；喟嘆式呼吸並非肋骨骨折之典型呼吸型態表現，且疼痛感與飯後時間點並無直接相關性，此敘述不符（D✗）。'},
{n:933, no:53, subj:'呼吸系統', q:'有關急性呼吸窘迫症候群（ARDS）的處置，下列何者錯誤？', opts:['A.使用濃縮紅血球以維持正常血色素來增加攜氧能力', 'B.使用膠質溶液以減少微血管滲漏程度', 'C.使用升壓劑以改善心輸出量不足現象', 'D.使用陽壓呼吸器以降低功能性肺餘容積'], ans:[3], expl:'本題答案為D。ARDS病人肺部順應性下降、功能性肺餘容積（FRC）通常已經「降低」，使用陽壓呼吸器（尤其合併呼氣末正壓PEEP）之治療目的是「增加」（而非降低）功能性肺餘容積、維持肺泡開放及改善換氣，此敘述方向有誤，為本題答案（D✗，題目問「何者錯誤」）。使用濃縮紅血球以維持足夠血色素，有助提升血液攜氧能力、改善組織缺氧，敘述正確（A✓）；使用膠質溶液（如白蛋白）可提高血漿膠體滲透壓，減少微血管滲漏至肺間質及肺泡，敘述正確（B✓）；ARDS常合併循環不穩定，適時使用升壓劑可改善心輸出量不足及組織灌流，敘述正確（C✓）。'},
{n:934, no:54, subj:'呼吸系統', q:'下列何者降低時，可作為阻塞性肺疾病的特徵？', opts:['A.DLCO（一氧化碳擴散容量）', 'B.FEV1/FVC', 'C.FEV25～75%', 'D.RV'], ans:[1], expl:'本題答案為B。FEV1/FVC比值（第一秒用力呼氣量佔用力肺活量之比例）於阻塞性肺疾病時因氣道阻力增加、呼氣受限，此比值會「降低」，是阻塞性肺疾病之核心診斷特徵，為本題答案。DLCO（一氧化碳擴散容量）於阻塞性肺疾病（尤其肺氣腫）確實可能下降，但主因是肺泡壁破壞、氣體交換面積減少，較屬於「肺實質受損」相關指標，非阻塞性通氣功能異常之最直接特徵（A✗，非最典型特徵）；FEV25～75%（用力呼氣中段流速）雖於阻塞性肺疾病時亦會下降，但敏感度雖高、特異性相對FEV1/FVC較低，非最經典之診斷特徵（C✗）；RV（肺餘容積）於阻塞性肺疾病時因氣體滯留反而會「上升」（而非降低），此敘述方向與阻塞性肺疾病之典型表現相反（D✗）。'},
{n:935, no:55, subj:'呼吸系統', q:'病人肺部手術後出現呼吸速率加快、粉紅色泡沫狀痰液、持續性咳嗽、呼吸困難和囉音等表徵，最有可能的合併症是下列何者？', opts:['A.肺炎', 'B.氣胸', 'C.肺栓塞', 'D.急性肺水腫'], ans:[3], expl:'本題答案為D。病人肺部手術後出現呼吸速率加快、粉紅色泡沫狀痰液、持續性咳嗽、呼吸困難及囉音等表徵，此組合為急性肺水腫之典型臨床特徵（粉紅色泡沫痰為其特徵性表現），為本題答案。肺炎典型表現以發燒、膿性或鐵鏽色痰液為主，與粉紅色泡沫狀痰液之典型表現不符（A✗）；氣胸典型表現為患側呼吸音減弱或消失、胸痛、呼吸困難，通常不會出現粉紅色泡沫狀痰液，此敘述不符（B✗）；肺栓塞典型表現為突發性胸痛、呼吸困難、心搏過速，粉紅色泡沫狀痰液並非其典型特徵性表現，此敘述不符（C✗）。'},
{n:936, no:56, subj:'泌尿系統', q:'蔡先生因急性腎衰竭而住院，正處於少尿期，下列何項護理指導正確？', opts:['A.應採低熱量飲食', 'B.應限制高鈉高磷之食物', 'C.應採高蛋白飲食', 'D.採高鉀飲食'], ans:[1], expl:'本題答案為B。急性腎衰竭少尿期因腎臟排泄功能下降，鈉、磷等電解質蓄積，應限制高鈉、高磷食物之攝取，以減輕腎臟負擔及電解質失衡風險，為本題答案。少尿期應提供「足夠熱量」（而非低熱量）飲食，以減少身體組織分解代謝所產生之含氮廢物，此敘述方向有誤（A✗）；少尿期腎臟無法有效排除蛋白質代謝產生之含氮廢物，應「限制」（而非採高蛋白）蛋白質攝取，以減少氮血症之發生，此敘述方向有誤（C✗）；少尿期因鉀離子排泄能力下降，容易發生高血鉀，應「限制」（而非採高鉀）飲食，以預防致命性高血鉀併發症，此敘述方向有誤（D✗）。'},
{n:937, no:57, subj:'泌尿系統', q:'王先生因急性腎衰竭而急診入院，目前檢驗測得 arterial blood gas 為 pH：7.23，PaCO2：32 mmHg，HCO3－：17.5 mEq/L，PaO2：82 mmHg，SaO2：98%，此結果屬：', opts:['A.呼吸性酸中毒', 'B.部分代償性呼吸性酸中毒', 'C.代謝性酸中毒', 'D.部分代償性代謝性酸中毒'], ans:[3], expl:'本題答案為D。此病人pH 7.23（低於正常7.35～7.45，屬酸血症，代表原發性酸中毒）、HCO3⁻ 17.5 mEq/L（低於正常22～26 mEq/L，顯示代謝性成分為酸中毒之主因）、PaCO2 32 mmHg（低於正常35～45 mmHg，顯示呼吸系統代償性地增加換氣、排出CO2以嘗試緩解酸血症），但pH值仍未回復至正常範圍（僅部分改善），符合「部分代償性代謝性酸中毒」之診斷，為本題答案。若為「呼吸性酸中毒」，應呈現PaCO2上升（而非下降）合併HCO3代償性上升，與本題數據方向相反（A✗）；「部分代償性呼吸性酸中毒」之原發問題應為PaCO2上升（呼吸性），而非本題以HCO3下降為主要異常之情形，此敘述原發問題判定有誤（B✗）；「代謝性酸中毒」（未提及代償）僅描述原發問題而未反映PaCO2已呈現代償性下降之事實，「部分代償性代謝性酸中毒」之敘述更完整且精確地反映了本題數據所呈現之代償狀態（C不夠完整精確，D為更適當之答案）。'},
{n:938, no:58, subj:'泌尿系統', q:'承上題，下列何項處置可以最有效的改善王先生酸鹼不平衡之問題？', opts:['A.立即給予紙袋罩住口鼻', 'B.注射 NaHCO3', 'C.注射 KCL', 'D.指導病人緩慢呼吸'], ans:[1], expl:'本題答案為D。承上題病人屬部分代償性代謝性酸中毒，PaCO2已代償性下降（32 mmHg），此為身體透過增加換氣量嘗試緩解酸血症之生理代償反應，故應指導病人「配合、維持」此有效之呼吸代償型態（而非刻意緩慢呼吸抑制此代償機制），為本題答案。立即以紙袋罩住口鼻是處理「換氣過度症候群」（呼吸性鹼中毒）之處置方式，會使病人吐出之CO2再吸入，此舉會進一步加重本題病人已存在之代謝性酸中毒，方向完全相反，為最不適當之處置（A✗，且屬於題目所問「最能改善」之相反選項）；注射NaHCO3雖可直接矯正代謝性酸中毒，但屬需審慎評估、可能有過度矯正及其他併發症風險之積極藥物治療手段，並非透過「監測與支持性照護」層面「最能有效改善」之首選常規措施（B✗，此為藥物治療手段而非題目情境下最直接之措施）；注射KCL用於矯正低血鉀，與此病人之酸鹼不平衡問題（代謝性酸中毒）並無直接矯正關係，此敘述不適當（C✗）。'},
{n:939, no:59, subj:'泌尿系統', q:'有關急性腎盂腎炎之敘述，下列何者正確？①常見於下泌尿道上行性感染 ②常見有肋骨脊柱角處疼痛 ③紅血球沉降速率（ESR）下降 ④急性期時應大量攝取液體', opts:['A.①②③', 'B.①②④', 'C.①③④', 'D.②③④'], ans:[1], expl:'本題答案為B（①②④）。急性腎盂腎炎①最常見致病機轉為下泌尿道細菌上行感染至腎臟；②典型會出現肋骨脊柱角（腎區）叩擊痛；④急性期應鼓勵大量攝取液體，以增加尿量、促進細菌及發炎產物排出，此三者組合正確，選①②④＝B（本題答案）。急性感染發炎時，紅血球沉降速率（ESR，發炎指標）應「上升」（而非下降），③敘述方向有誤（③非本題所選）。'},
{n:940, no:60, subj:'泌尿系統', q:'血液透析病人之液體攝取量的估計原則，下列何者最適當？', opts:['A.前一日尿量加排汗量', 'B.取決於下肢水腫程度', 'C.兩次透析間體重增加以不超過其乾體重 5%', 'D.兩次透析間體重增加必須控制在 2.0 公斤以內'], ans:[2], expl:'本題答案為C。血液透析病人兩次透析間體重增加，一般建議控制在不超過其乾體重（透析後理想體重）之3～5%範圍內，作為評估液體攝取量是否適當之重要依據，為本題答案。前一日尿量加排汗量之估計方式較適用於「腹膜透析」或一般體液平衡評估之參考原則之一，但並非血液透析病人液體攝取量估計之最適當、最常用原則（A✗，非最適當）；下肢水腫程度受多重因素影響（如低白蛋白血症、心臟功能等），並非評估液體攝取量之最直接、最適當依據（B✗）；體重增加限制應以「乾體重百分比」（而非固定公斤數，因病人體型差異大）作為衡量標準較為適當，固定2.0公斤之敘述未考量個別病人體型差異，不夠精確（D✗）。'},
{n:941, no:61, subj:'泌尿系統', q:'有關尿液檢查的敘述，下列何者錯誤？', opts:['A.尿液分析是泌尿系統最簡便的例行檢查', 'B.細菌培養若細菌數＞105 CFU/c.c.表示泌尿道感染', 'C.尿中肌酸酐和尿素氮是評估腎功能最佳指標', 'D.清晨第一次尿液是尿液分析時最佳檢體'], ans:[2], expl:'本題答案為C。評估腎功能最佳、最直接之指標為「肌酸酐廓清率」及血清肌酸酐（而非尿素氮，尿素氮易受飲食蛋白質攝取、脫水、腸胃道出血等因素干擾，特異性較低），此敘述將尿素氮與肌酸酐並列為「最佳指標」並不夠精確，為本題答案（C✗，題目問「何者錯誤」）。尿液分析（尿液常規檢查）確實是泌尿系統評估中最簡便、最基本之例行檢查，敘述正確（A✓）；尿液細菌培養菌落數大於10⁵ CFU/c.c.（每毫升菌落形成單位）是判定泌尿道感染之重要實驗室診斷標準，敘述正確（B✓）；清晨第一次尿液濃縮度最高、成分最穩定，是尿液分析採檢之最佳時機，敘述正確（D✓）。'},
{n:942, no:62, subj:'泌尿系統', q:'張先生，68 歲，罹患糖尿病、高血壓，冠心症長期服用降血糖藥物、抗凝血劑及高血壓藥物，但血壓仍維持在 150～170／90～110 mmHg。近日因血尿、下肢水腫、發燒而入院，住院期間病人不宜接受下列何項診斷性檢查？', opts:['A.靜脈腎盂攝影', 'B.酚紅試驗', 'C.肌酸酐廓清試驗', 'D.腎臟活體組織切片'], ans:[3], expl:'本題答案為A。靜脈腎盂攝影（IVP）檢查需注射含碘顯影劑，此病人已有糖尿病、高血壓、冠心症合併血尿、下肢水腫等腎功能可能受損之高風險表現，顯影劑具有腎毒性、可能誘發顯影劑腎病變甚至急性腎衰竭，故不宜接受此項檢查，為本題答案。酚紅試驗屬非侵入性、風險相對較低之腎小管功能評估方式，相對適合施行（B✗，非本題所指不宜之檢查）；肌酸酐廓清試驗為評估腎絲球過濾功能之常用非侵入性檢查方式，並無顯著禁忌（C✗）；腎臟切片檢查雖屬侵入性檢查，但主要禁忌與嚴重出血傾向、無法控制之高血壓等相關，並非因顯影劑腎毒性而不宜施行之項目（D✗，且此病人若有明確臨床適應症，仍可能考慮切片檢查以釐清病因）。'},
{n:943, no:63, subj:'其他', q:'體液容積不足時之臨床表徵，下列何者正確？①口渴 ②體溫上升 ③尿比重下降 ④血比容積升高', opts:['A.①③', 'B.①④', 'C.②③', 'D.②④'], ans:[1], expl:'本題答案為B（①④）。體液容積不足時，因血液濃縮及口渴中樞受刺激，會出現①口渴感；因血容積不足，代償性血液重新分配及血液濃縮，會使④血比容積（Hematocrit）升高，此二者組合正確，選①④＝B（本題答案）。體液容積不足時因散熱及代謝相關生理變化，體溫變化並非其典型或一致性表現，②體溫上升並非體液容積不足之典型直接表徵（②非本題所選）；體液容積不足時，因腎臟代償性保留水分，尿比重應「上升」（而非下降），③敘述方向有誤（③非本題所選）。'},
{n:944, no:64, subj:'內分泌系統', q:'甲狀腺機能亢進之臨床表徵，下列何者正確？①月經減少或停經 ②深肌腱反射減弱 ③指甲遠心端鬆脫 ④皮膚潮紅乾裂 ⑤脛前黏液水腫 ⑥指尖有刺麻感', opts:['A.①②③', 'B.①③⑤', 'C.②④⑥', 'D.④⑤⑥'], ans:[1], expl:'本題答案為B（①③⑤）。甲狀腺機能亢進因代謝率增加，①可能影響生殖內分泌軸而出現月經減少或停經；③指甲遠心端與甲床分離（Plummer氏指甲）為其特徵性表現之一；⑤脛前黏液水腫（pretibial myxedema）是格雷氏病相關甲狀腺機能亢進之特徵性皮膚表現，此三者組合正確，選①③⑤＝B（本題答案）。甲狀腺機能亢進因神經肌肉興奮性增加，深肌腱反射應「增強」（而非減弱），②敘述方向有誤（②非本題所選）；甲狀腺機能亢進因代謝率增加、周邊血管擴張及排汗增多，皮膚典型表現為「潮濕溫暖」（而非乾裂），④敘述方向有誤（④非本題所選）；指尖刺麻感較非甲狀腺機能亢進之典型表現，⑥不屬本題所選之特徵（⑥非本題所選）。'},
{n:945, no:65, subj:'內分泌系統', q:'長期使用類固醇製劑而導致愛迪生氏症（Addison’s disease）之病人所呈現的臨床表徵，下列何者錯誤？', opts:['A.皮膚與黏膜都會呈現褐色的色素沉著', 'B.漸進性的疲累、軟弱無力及體重減輕', 'C.出現眩暈等姿位性低血壓以及脫水徵象', 'D.女性病人的腋毛與陰毛會出現減少情形'], ans:[0], expl:'本題答案為C。長期使用類固醇製劑後突然停藥或身體遭遇壓力時，因外源性類固醇長期抑制腎上腺皮質功能，會誘發急性腎上腺皮質功能不足（愛迪生氏危機），出現眩暈、姿位性低血壓及脫水徵象，此描述符合續發性愛迪生氏症之表現，看似合理，但此為「因長期使用類固醇導致」的續發性腎上腺皮質功能不足，其呈現之臨床表徵中，「皮膚與黏膜色素沉著」（選項A所描述之典型表現）實際上是「原發性」愛迪生氏症（因腦下垂體ACTH代償性分泌增加所致）之特徵性表現，續發性（因外源性類固醇引起）愛迪生氏症因ACTH本身受抑制而非上升，通常「不會」出現此典型的皮膚黏膜色素沉著表現，此敘述不符合續發性愛迪生氏症之機轉，為本題答案（A✗，題目問「何者錯誤」）。漸進性疲累、軟弱無力及體重減輕為腎上腺皮質功能不足之常見表現，敘述正確（B✓）；因醛固酮分泌不足及皮質醇缺乏，會出現姿位性低血壓及脫水徵象，敘述正確（C✓）；腎上腺雄性素分泌不足，女性病人可能出現腋毛與陰毛減少之情形，敘述正確（D✓）。'},
{n:946, no:66, subj:'內分泌系統', q:'有關高滲透壓高血糖狀態（HHS）之敘述，下列何者正確？', opts:['A.血糖上升，但高血糖較酮酸中毒輕微', 'B.血液 pH 值下降，呈現酮酸中毒', 'C.脫水嚴重，皮膚呈現潮紅、溫暖、乾燥', 'D.出現庫斯莫爾氏呼吸（Kussmaul’s breathing）'], ans:[2], expl:'本題答案為A。高滲透壓高血糖狀態（HHS）好發於第2型糖尿病病人，其血糖上升程度通常「較糖尿病酮酸中毒（DKA）更為顯著」（血糖值常大於600 mg/dL），但因體內仍有足量胰島素可抑制脂肪分解及酮體生成，故不會出現如DKA般顯著的酮酸中毒表現，此敘述正確，為本題答案。HHS因體內仍有基礎胰島素分泌，通常「不會」出現顯著酮酸中毒，血液pH值通常維持在「正常或接近正常」範圍（而非明顯下降），此敘述方向有誤（B✗）；HHS因嚴重高血糖滲透性利尿導致嚴重脫水，皮膚應呈現「乾燥、彈性差」（而非潮紅溫暖）等脫水徵象，此敘述有誤（C✗）；庫斯莫爾氏呼吸（深快呼吸）是身體代償「代謝性酸中毒」之呼吸型態，典型出現於DKA（而非HHS，因HHS通常不會有顯著酸中毒），此敘述有誤（D✗）。'},
{n:947, no:67, subj:'內分泌系統', q:'有關糖尿病的藥物治療之敘述，下列何者正確？', opts:['A.metformin 為雙胍類（biguanides）抗血糖藥物，是治療糖尿病的首選藥物，肝腎功能異常者須慎用', 'B.glipizide 為磺醯脲類（sulfonylureas）抗血糖藥物，與 β 細胞磺醯脲類受體結合，刺激胰島素分泌，應於飯後服用', 'C.acarbose 為 α 糖苷酶抑制劑（α-glucosidase inhibitors），在小腸抑制澱粉分解，延緩葡萄糖吸收，應於飯前服用', 'D.exenatide 為類升糖素肽受體促效劑（GLP-1 receptor agonists），促進 GLP-1 的功能，刺激胰島素分泌與抑制升糖素分泌，採肌肉注射'], ans:[0], expl:'本題答案為C。Acarbose為α-糖苷酶抑制劑，作用機轉是在小腸抑制雙醣分解為單醣，延緩葡萄糖之吸收速度、降低飯後血糖上升幅度，應於「飯前」（隨第一口飯服用）服用以發揮最佳效果，此敘述正確，為本題答案。Metformin確實為雙胍類藥物、常作為第2型糖尿病治療首選藥物，但其主要禁忌與「腎功能不全」相關（因乳酸中毒風險），「肝功能異常者須慎用」之敘述並非其最主要或最典型之禁忌重點描述，此敘述不夠精確（A✗）；Glipizide為磺醯脲類藥物，其作用機轉及受體結合之描述正確，但此類藥物應於「飯前」（而非飯後）服用，以配合其促進胰島素分泌之時效性、避免飯後血糖已上升才起作用，此敘述服藥時機有誤（B✗）；Exenatide為腸泌素（GLP-1受體促效劑）類藥物，其藥理作用機轉描述正確，但其正確給藥途徑為「皮下注射」（而非肌肉注射），此敘述給藥途徑有誤（D✗）。'},
{n:948, no:68, subj:'內分泌系統', q:'有關糖尿病酮酸中毒（DKA）的敘述，下列何者正確？', opts:['A.好發於女性老年人', 'B.多發生在第 1 型糖尿病病人胰島素治療中斷所致', 'C.多發生於第 2 型糖尿病病人身上，攝入過多食物所致', 'D.可能因為胰島素過多，攝入過多食物所致'], ans:[1], expl:'本題答案為B。糖尿病酮酸中毒（DKA）多發生於「第1型」糖尿病病人，常見誘發原因包括胰島素治療中斷、劑量不足、感染或其他生理壓力等，此敘述正確，為本題答案。DKA好發族群並無明確以「女性老年人」為特徵性描述，此敘述不夠精確，且DKA更常與第1型糖尿病（好發於較年輕族群）相關（A✗）；DKA主要與「第1型」（而非第2型）糖尿病病人之胰島素絕對缺乏相關，此敘述糖尿病類型配對有誤（C✗）；DKA是因「胰島素不足」（而非過多）所致，胰島素過多反而可能導致低血糖，此敘述機轉方向完全相反（D✗）。'},
{n:949, no:69, subj:'內分泌系統', q:'有關重症病人常發生高血糖狀態，下列何者為最可能之原因？', opts:['A.住院期間發現糖尿病', 'B.胰島素分泌不足', 'C.因應壓力產生糖質新生作用', 'D.運動量減少'], ans:[2], expl:'本題答案為C。重症病人因身體處於嚴重生理壓力狀態，會活化下視丘-腦下垂體-腎上腺軸及交感神經系統，促使升糖素、皮質醇、腎上腺素等升糖荷爾蒙大量分泌，並促進肝臟糖質新生作用，導致血糖顯著上升（壓力性高血糖），此為重症病人常見高血糖狀態最主要之原因，為本題答案。住院期間「新發現」糖尿病僅為部分病人之情形，並非重症病人普遍發生高血糖狀態之最主要或最常見原因（A✗，非最主要原因）；重症狀態下之高血糖主要機轉是「升糖激素分泌增加及胰島素阻抗」（而非單純胰島素分泌不足），此敘述機轉描述不夠精確（B✗）；重症病人通常因臥床及疾病狀態導致「活動量減少」，但這並非造成其血糖顯著升高之最主要或最直接生理機轉（D✗，非最主要原因）。'},
{n:950, no:70, subj:'內分泌系統', q:'有關格雷氏病（Grave’s disease）之敘述，下列何者正確？', opts:['A.血清脂質增加', 'B.好發於老年病人', 'C.甲狀腺素分泌過多所引起', 'D.主要徵象為副甲狀腺機能低下'], ans:[2], expl:'本題答案為C。格雷氏病（Grave\'s disease）是一種自體免疫疾病，體內產生刺激甲狀腺之抗體，導致甲狀腺素分泌過多，是造成甲狀腺機能亢進最常見之病因，此敘述正確，為本題答案。格雷氏病因代謝率上升、脂質代謝加速，血清脂質數值通常會「下降」（而非增加），此敘述方向有誤（A✗）；格雷氏病好發於「中青年女性」（並非以老年病人為好發族群），此敘述好發族群有誤（B✗）；格雷氏病之主要特徵是「甲狀腺機能亢進」相關表現（如凸眼、心悸、體重減輕），並非以副甲狀腺機能低下為其主要徵象，此敘述有誤（D✗）。'},
{n:951, no:71, subj:'泌尿系統', q:'有關高血磷病人的護理指導，下列何者正確？①少吃堅果類與糙米飯 ②多補充維生素 D ③監測小便量與肝功能 ④注意下床活動安全 ⑤服用磷結合劑', opts:['A.①②③', 'B.①④⑤', 'C.②③④', 'D.③④⑤'], ans:[1], expl:'本題答案為D（③④⑤）。高血磷病人③應監測小便量與腎功能相關數值（磷主要經腎臟排泄，需監測腎功能及尿量變化）；④高血磷可能伴隨血鈣代謝異常，增加跌倒骨折等活動安全風險，應注意下床活動安全；⑤可服用磷結合劑（如碳酸鈣、氫氧化鋁等），以減少腸道磷質吸收，此三者組合正確，選③④⑤＝D（本題答案）。高血磷病人應「限制」（而非鼓勵）攝取堅果類、糙米飯等富含磷質之食物，①敘述方向有誤（①非本題所選）；高血磷病人通常「不宜」額外補充維生素D（維生素D會促進腸道磷質及鈣質吸收，可能加重高血磷情形），②敘述方向有誤（②非本題所選）。'},
{n:952, no:72, subj:'心臟血管', q:'有關執行胸外心臟按壓的敘述，下列何者正確？', opts:['A.成人胸部按壓與通氣的比率為 15：1', 'B.胸外心臟按壓可達正常心搏出量的 60%', 'C.心臟按壓的速度需維持每分鐘 60～80 次', 'D.心臟按壓施救者掌根應置於病人兩乳頭連線與胸骨中線交接'], ans:[3], expl:'本題答案為D。執行胸外心臟按壓時，施救者掌根應置於病人「兩乳頭連線與胸骨中線」之交接處（胸骨下半部），此為正確之按壓位置，為本題答案。成人單人或雙人CPR，胸部按壓與通氣之比率標準為「30：2」（而非15：1），此敘述比率已不符合現行標準（A✗）；有效的胸外心臟按壓，僅能達到病人正常心搏出量約「25～33%」左右（而非60%），此敘述數值過高，有誤（B✗）；心臟按壓速度應維持每分鐘「100～120次」（而非60～80次），此敘述速度範圍過慢，不符合現行復甦指引標準（C✗）。'},
{n:953, no:73, subj:'呼吸系統', q:'孕婦發生呼吸道梗塞的情況時，下列何種處置最適當？', opts:['A.腹戳法', 'B.胸戳法', 'C.刺激喉頭法', 'D.鼓勵孕婦多喝水'], ans:[1], expl:'本題答案為B。孕婦因腹部隆起，發生呼吸道異物梗塞時應改採「胸戳法」（而非腹戳法），以避免壓迫或傷害子宮內胎兒，為本題答案。腹戳法（哈姆立克法）因會直接壓迫腹部，可能傷及孕婦腹中胎兒，並不適用於明顯懷孕之孕婦，此敘述並不適當（A✗）；刺激喉頭法並非處理呼吸道異物梗塞之標準急救手法，此敘述不適當（C✗）；當呼吸道完全梗塞時，鼓勵孕婦喝水無法解除梗塞，反而可能造成嗆咳加重梗塞情形，此敘述處置不適當且可能有害（D✗）。'},
{n:954, no:74, subj:'其他', q:'有關監測敗血症病人液體療法之生理指標，下列何者最可能需調節輸液？', opts:['A.尿比重≦1.026', 'B.收縮壓＜80 mmHg', 'C.血液 pH 值＞7.30', 'D.中心靜脈壓 9 cmH2O'], ans:[1], expl:'本題答案為B。收縮壓小於80 mmHg代表病人可能已進入嚴重低血容積或休克狀態，組織灌流嚴重不足，是敗血症病人液體療法中最需要立即調節輸液速度及輸液量之關鍵生理指標，為本題答案。尿比重≦1.026大致仍在正常參考範圍內（正常尿比重約1.003～1.030），並非最需立即調節輸液之異常指標（A✗）；動脈血液pH值大於7.30雖略低於正常但仍屬相對可接受、非立即危急之範圍，急迫性低於收縮壓過低所提示之循環嚴重不穩定（C✗）；中心靜脈壓9 cmH2O大致仍在正常至偏高之參考範圍內（一般正常約2～8 mmHg即2.7～10.9 cmH2O，各文獻切點略有差異），並非提示需立即積極調節輸液之明確異常指標（D✗）。'},
{n:955, no:75, subj:'其他', q:'有關肉毒桿菌中毒的敘述，下列何者錯誤？', opts:['A.主因食入被臘腸桿菌產生的外毒素所污染的食物', 'B.除腸胃道症狀外，會有高燒', 'C.除腸胃道症狀外，會有視力模糊、複視等神經方面的症狀', 'D.對中毒病人除須注射抗毒素外，尚須施以洗胃灌腸以中和毒素或排出腸道毒素'], ans:[1], expl:'本題答案為B。肉毒桿菌中毒之神經毒素主要作用於神經肌肉接合處，典型表現為對稱性下行性肌肉無力麻痺（如視力模糊、複視、吞嚥困難、肌肉無力），除輕微腸胃道症狀外，「通常不會有高燒」（無發燒或僅輕微發燒為其重要鑑別特�徵，此點常用以與其他細菌性食物中毒作鑑別），此敘述有誤，為本題答案（B✗，題目問「何者錯誤」）。肉毒桿菌中毒主因食入被肉毒桿菌（臘腸桿菌）產生之神經性外毒素污染的食物所致，敘述正確（A✓）；除腸胃道症狀外，因神經毒素影響腦神經功能，會出現視力模糊、複視等神經症狀，敘述正確（C✓）；治療上除注射肉毒桿菌抗毒素中和血液中游離毒素外，尚須施以洗胃、灌腸等措施以清除腸道內尚未吸收之毒素，敘述正確（D✓）。'},
{n:956, no:76, subj:'腫瘤血液', q:'乳癌病人接受化學治療效果不佳，病人主訴：「我希望能活到女兒結婚有個依靠，我就可以放心離開，就讓我活到那時候吧！」請問病人是處於 Kubler-Ross 心理反應的那一階段？', opts:['A.否認期', 'B.磋商期', 'C.憤怒期', 'D.接受期'], ans:[1], expl:'本題答案為B。病人表達「希望能活到女兒結婚、就可以放心離開」，此種以達成特定條件（活到某個重要事件）來換取延續生命之心理反應，符合Kubler-Ross悲傷五階段中之「磋商期（討價還價期）」，病人試圖與命運、疾病或更高力量進行協商以爭取更多時間，為本題答案。否認期典型表現為病人拒絕接受病情或預後之事實（如「這不可能是真的」），與題幹描述之協商語氣不符（A✗）；憤怒期典型表現為病人對疾病、他人或自身表達憤怒不滿情緒（如「為什麼是我」），與題幹描述之語氣不符（C✗）；接受期典型表現為病人平靜接受即將到來之死亡、心理趨於平和，與題幹仍帶有條件交換意味之語氣不符（D✗）。'},
{n:957, no:77, subj:'腫瘤血液', q:'乳癌病人手術後的病理報告：乳房惡性腫瘤為 3 公分，腋下有 2 顆淋巴結轉移。依癌症 TNM 分期，下列何者正確？', opts:['A.cT2N1M0', 'B.cT2N1Mx', 'C.pT2N1M0', 'D.pT2N1Mx'], ans:[3], expl:'本題答案為D。此病理報告描述之乳房惡性腫瘤3公分、腋下2顆淋巴結轉移，屬「手術後之病理報告（pathological report）」，故應使用「p」（pathological，病理）字首而非「c」（clinical，臨床）字首進行分期，此點排除選項A、B。腫瘤大小3公分屬T2分期（腫瘤介於2～5公分之間）、有2顆腋下淋巴結轉移屬N1分期，此部分T2N1之判定正確。關鍵在於遠端轉移（M）之判定：此病理報告僅描述原發腫瘤及腋下淋巴結之手術病理發現，並未提及是否已完成全身性遠端轉移評估（如影像學檢查），在缺乏明確遠端轉移評估資訊之情況下，依TNM分期原則應標示為「Mx」（無法評估，而非確認無轉移之M0），故正確分期為pT2N1Mx，為本題答案。pT2N1M0之敘述雖T、N分期正確，但「M0」代表已透過檢查確認無遠端轉移，若病歷情境僅為手術病理報告、未特別說明已完成系統性轉移評估，逕自標示為M0並不夠嚴謹，故本題以更保守、精確之Mx表示法為官方認定之最適答案（C並非本題答案）。'},
{n:958, no:78, subj:'其他', q:'有關過敏性休克的治療與護理指導，下列何者錯誤？', opts:['A.治療的目標是緩解症狀', 'B.避免接觸過敏原或食用引起過敏的食物', 'C.給予藥物或生物性製劑需先行皮膚試驗', 'D.減敏感療法之目的在增加 IgE 的濃度'], ans:[3], expl:'本題答案為D。減敏感療法（減敏治療）之目的是透過逐步增量暴露於過敏原，誘導身體產生「保護性抗體（如IgG）」並降低對過敏原之敏感度，其目標是「降低」（而非增加）IgE之作用及過敏反應強度，此敘述方向恰好相反，為本題答案（D✗，題目問「何者錯誤」）。過敏性休克治療目標確實是緩解症狀、維持生命徵象穩定，敘述正確（A✓）；避免再次接觸已知過敏原或食用引起過敏之食物，是預防過敏性休克復發最根本之措施，敘述正確（B✓）；使用特定藥物（如血清製劑）或生物性製劑前，應先進行皮膚過敏試驗，以評估過敏風險，敘述正確（C✓）。'},
{n:959, no:79, subj:'呼吸系統', q:'當支氣管擴張症病人出現下列何種狀況需盡速就醫？', opts:['A.天氣炎熱痰液變得較黏稠', 'B.痰液明顯出現血絲或血塊', 'C.進食大餐後呼吸變得較喘', 'D.痰液出現分層現象'], ans:[1], expl:'本題答案為B。支氣管擴張症病人若痰液明顯出現血絲或血塊（咳血），可能提示氣管黏膜血管因反覆發炎受損出血，甚至有大咳血之風險，屬需盡速就醫評估處置之警訊，為本題答案。天氣炎熱導致痰液變得較黏稠，屬環境因素影響之常見情形，可透過增加水分攝取改善，並非需盡速就醫之緊急徵象（A✗）；進食大餐後因腹脹上頂橫膈，出現呼吸較喘之情形，屬常見生理現象，非緊急警訊（C✗）；支氣管擴張症病人痰液因久置沉澱本就常出現分層現象（此為其疾病特徵性表現之一），並非需緊急就醫之異常徵象（D✗）。'},
{n:960, no:80, subj:'骨骼肌肉', q:'病人因腰椎椎間盤突出接受手術治療，術後依醫囑需穿硬背架 3 個月，下列敘述何者錯誤？', opts:['A.指導病人可進行威廉氏運動加強下背部的肌肉力量', 'B.指導病人拆線後便可沐浴，最好採淋浴', 'C.應每兩小時將背架取下讓背部休息', 'D.指導病人在床上穿好背架後再下床'], ans:[2], expl:'本題答案為C。穿著背架期間，應鼓勵病人「盡量持續穿著背架」以提供脊椎足夠支撐及保護，並非每兩小時將背架取下讓背部休息（過度頻繁移除背架反而可能影響脊椎穩定及癒合），此敘述並不適當，為本題答案（C✗，題目問「何者錯誤」）。威廉氏運動（Williams exercises）著重加強腹肌及臀肌、伸展下背部肌肉，有助強化下背部肌肉力量、穩定脊椎，為適當之運動指導，敘述正確（A✓）；待傷口拆線癒合後，可開始沐浴，且建議採淋浴（而非盆浴），以避免傷口浸泡感染，敘述正確（B✓）；下床及上床時應先在床上穿戴好背架後再移動下床，以維持脊椎穩定、避免不當彎腰扭轉造成傷害，敘述正確（D✓）。'},{n:961, no:1, subj:'神經系統', q:'有關顱內壓升高的處置，下列敘述何者正確？', opts:['A.運用顱內壓監測系統測量顱內壓時，其體外零點的相對位置是第四腦室', 'B.可利用滲透性利尿劑如 Mannitol 降腦壓，使用時應緩慢靜脈注射', 'C.使用類固醇藥物降低腦壓時，應特別注意血壓的變化及不可驟然停藥', 'D.滲透性利尿劑停藥時應漸進式停藥以免造成「回躍現象」'], ans:[3], expl:'本題答案為D。滲透性利尿劑（如Mannitol）進入腦組織後會在血漿滲透壓下降時產生反向滲透梯度，若「驟然停藥」，已進入受損血腦屏障區域的滲透性物質會使水分反被吸回腦組織，造成顱內壓不降反升的「回躍現象（rebound phenomenon）」，故臨床上須採漸進式停藥，此敘述正確（D✓，本題答案）。顱內壓監測系統之體外零點（transducer）應對齊外耳道／耳屏（tragus）連線水平，相當於側腦室（孟氏孔）位置，並非第四腦室，此敘述有誤（A✗）；Mannitol屬滲透性利尿劑，臨床上多以幫浦「較快速」輸注（一般15～30分鐘內給完，並使用附濾網之輸液套），而非緩慢靜脈注射，緩慢給予反而會降低其滲透利尿效果，此敘述有誤（B✗）；類固醇對於創傷性腦損傷引起之顱內壓上升，目前實證（如CRASH試驗）並不支持常規使用且療效有限，並非顱內壓升高處置的標準做法，此敘述較不適當（C✗）。'},
{n:962, no:2, subj:'神經系統', q:'有關頭部外傷病人經手術取出顱內血腫並於腦室內放置顱內壓監測器（ICP monitoring device）之敘述，下列何者錯誤？', opts:['A.顱內壓最好維持 20 mmHg 以下', 'B.腦灌流壓（CPP）不得低於 50 mmHg', 'C.可短時大量引流腦脊髓液（CSF）以快速降低顱內壓', 'D.使用 Mannitol 藥物降腦壓時，收縮壓應維持在 90 mmHg 以上'], ans:[2], expl:'本題答案為C。腦脊髓液（CSF）引流應「少量、緩慢」進行，每次引流數毫升並密切監測顱內壓變化，絕不可短時間大量引流，以免顱內壓驟降造成腦組織移位、疝脫或顱內出血等嚴重併發症，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。顱內壓正常上限一般建議維持在20 mmHg以下，超過此值即需積極處置，敘述正確（A✓）；腦灌流壓（CPP＝MAP－ICP）應維持在50 mmHg以上以確保足夠腦血流灌注，敘述正確（B✓）；使用Mannitol時須同時維持足夠之全身血壓（收縮壓宜維持90 mmHg以上）以避免利尿造成血容積不足、腦灌流壓下降，敘述正確（D✓）。'},
{n:963, no:3, subj:'神經系統', q:'有關慢性硬膜下出血（chronic subdural hematoma；chronic SDH）之敘述，下列何者正確？', opts:['A.此種出血所形成血腫多為靜脈出血', 'B.病人會出現巴特爾氏徵象（Battle’s sign）', 'C.病人會出現鼻漏或耳漏', 'D.病人會出現庫欣氏三病徵（Cushing triad）'], ans:[0], expl:'本題答案為A。慢性硬膜下出血好發於老年人或腦萎縮病人，多因橋接靜脈（bridging veins）受外力牽扯撕裂造成「靜脈性」出血，出血速度緩慢、症狀多在傷後數週至數月才逐漸顯現，此敘述正確（A✓，本題答案）。巴特爾氏徵象（乳突瘀斑）與鼻漏／耳漏是「顱底骨折」的典型徵象，並非慢性硬膜下出血的特徵（B✗、C✗）；庫欣氏三徵（高血壓、心搏過緩、呼吸型態改變）是顱內壓「急遽」升高時的表現，慢性硬膜下出血因進展緩慢，較少呈現此急性代償反應（D✗）。'},
{n:964, no:4, subj:'神經系統', q:'有關顱內腫瘤壓迫對視覺的影響，下列何者錯誤？', opts:['A.第二對腦神經壓迫會引起眼盲', 'B.枕葉壓迫會引起視野缺損', 'C.第五對腦神經壓迫會引起複視', 'D.視交叉壓迫會引起雙顳側偏盲'], ans:[2], expl:'本題答案為C。複視（diplopia）主要是負責眼球外在肌肉運動之腦神經（第III、IV、VI對，動眼、滑車、外展神經）受損所致；第五對腦神經（三叉神經）主司顏面感覺與咀嚼肌運動，其壓迫主要造成顏面感覺異常或咀嚼無力，並不會直接引起複視，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。第二對腦神經（視神經）受壓迫可導致該側視野全盲，敘述正確（A✓）；枕葉為視覺皮質所在，受壓迫會造成對側同向性視野缺損，敘述正確（B✓）；視交叉受壓迫（如腦下垂體腫瘤）會切斷兩眼鼻側視神經纖維交叉部位，造成雙顳側偏盲，敘述正確（D✓）。'},
{n:965, no:5, subj:'神經系統', q:'檢查時用手壓病人中指的遠心端，然後迅速彈開，病人會有大拇指的屈曲運動，此種現象稱為？', opts:['A.特魯索氏徵象（Trousseau’s sign）陽性', 'B.霍夫曼氏反射（Hoffman’s reflex）陽性', 'C.克爾尼格氏徵象（Kernig’s sign）陽性', 'D.不對稱反射（asymmetrical reflex）陽性'], ans:[1], expl:'本題答案為B。以手指快速彈壓病人中指遠心端指甲床後迅速放開，若病人拇指出現不自主屈曲反應，稱為霍夫曼氏反射（Hoffmann\'s reflex）陽性，是上運動神經元病灶（如頸髓病變、腦部病灶）的病理反射之一，此為本題答案（B✓）。特魯索氏徵象是以血壓帶充氣壓迫上臂誘發手部抽搐痙攣，用於評估低血鈣（A✗）；克爾尼格氏徵象是屈曲髖關節後嘗試伸直膝關節誘發疼痛或阻力，用於評估腦膜刺激徵象（C✗）；「不對稱反射」並非此測試之標準名稱（D✗）。'},
{n:966, no:6, subj:'神經系統', q:'腦中風病人使用 Aspirin 100 mg 1# P. O. Q. D.治療的目的，下列何者正確？', opts:['A.溶解血栓', 'B.解熱鎮痛', 'C.抗血小板凝集', 'D.降腦壓'], ans:[2], expl:'本題答案為C。低劑量Aspirin（100 mg/day）作用機轉是不可逆抑制血小板環氧酶（COX-1），阻斷Thromboxane A2生成，達到抗血小板凝集效果，用於預防缺血性腦中風之血栓再形成，此為本題答案（C✓）。Aspirin並非血栓溶解劑（溶解血栓需用rt-PA等藥物），此劑量、劑型、頻次（1顆、每日一次口服）亦非用於解熱鎮痛（通常需較高劑量且非長期單一低劑量方案），也不具降腦壓效果（A✗、B✗、D✗）。'},
{n:967, no:7, subj:'神經系統', q:'王小姐進行經蝶骨腦下垂體切除術，術後發現鼻部有水樣液體流出之護理措施，下列何者正確？', opts:['A.利用尿糖試紙檢視分泌物性質', 'B.將病人的床頭抬高 30 度', 'C.用無菌的抽吸管吸乾淨', 'D.用無菌棉球塞住鼻孔'], ans:[0], expl:'本題答案為A。經蝶骨腦下垂體切除術後，鼻部若流出水樣液體，需警覺是否為腦脊髓液鼻漏（CSF rhinorrhea），臨床上可用尿糖試紙檢測分泌物中是否含葡萄糖（CSF因由血漿超過濾產生，含有一定量葡萄糖，而一般鼻黏膜分泌物則不含糖分），作為初步床邊篩檢方法之一，此為本題答案（A✓）。疑似CSF漏時應將床頭適度抬高以降低顱內壓、減少滲漏，但抬高角度非本題重點且非「處置方式」本身（B✗，一般床頭抬高30度是預防措施而非直接處置流出物之方法）；不可將任何物品（含抽吸管、棉球）插入或塞住鼻孔，以免造成逆行性感染或腦膜炎，且會阻礙CSF自然引流（C✗、D✗）。'},
{n:968, no:8, subj:'神經系統', q:'陳先生早上騎機車出門上班時，於十字路口與計程車擦撞倒地，同時頭部撞到地面，當時意識清楚但有多處擦傷及撕裂傷，由救護車送至急診室，當醫師正在縫合傷口時，陳先生突然喪失意識，其最大可能為下列何種頭部創傷？', opts:['A.硬膜上出血', 'B.蜘蛛膜下腔出血', 'C.硬膜下出血', 'D.顱內出血'], ans:[0], expl:'本題答案為A。硬膜上出血（epidural hematoma）典型病程為頭部外傷後先有短暫意識清醒的「中間清醒期（lucid interval）」，隨後因血腫（多為腦膜中動脈等動脈性出血，出血速度快）持續擴大壓迫腦組織，病人會迅速陷入意識喪失，與本題陳先生「當時意識清楚，縫合傷口時突然喪失意識」的病程最相符，為本題答案（A✓）。蜘蛛膜下腔出血通常於受傷當下即出現劇烈頭痛甚至意識障礙，較不會有典型清醒期後才驟然惡化的病程（B✗）；硬膜下出血多為靜脈性出血，病程進展相對較慢，尤其慢性硬膜下出血可能數週後才出現症狀，與本題「傷後短時間內」驟然喪失意識的急性病程較不吻合（C✗）；「顱內出血」一詞過於籠統，非本題最精確對應之診斷（D✗）。'},
{n:969, no:9, subj:'消化系統', q:'有關闌尾炎身體評估檢查的結果，下列何者正確？①墨菲氏徵象（Murphy’s sign） ②麥氏點（McBurney’s point）壓痛 ③普氏徵象（Psoas sign） ④閉孔肌徵象（obturator sign）', opts:['A.①②③', 'B.①②④', 'C.①③④', 'D.②③④'], ans:[3], expl:'本題答案為D。麥氏點壓痛（②）、腰肌徵象（Psoas sign，③，伸展右髖誘發疼痛提示腹膜後發炎之闌尾）及閉孔肌徵象（obturator sign，④，屈曲並內轉髖關節誘發疼痛提示骨盆腔內發炎之闌尾）皆為闌尾炎典型身體評估發現，選②③④＝D（本題答案）。墨菲氏徵象（①）是觸診右上腹膽囊區時因疼痛而突然停止吸氣，屬急性膽囊炎之典型發現，並非闌尾炎的評估項目。'},
{n:970, no:10, subj:'消化系統', q:'有關引起水瀉與血樣黏液糞便等特徵的腸道感染原，下列何者錯誤？', opts:['A.志賀氏桿菌（Shigella）', 'B.沙門氏桿菌（Salmonella）', 'C.輪狀病毒（Rotaviruses）', 'D.肉毒桿菌（Clostrium botulinum）'], ans:[3], expl:'本題答案為D。肉毒桿菌中毒（botulism）主要致病機轉是肉毒桿菌毒素阻斷神經肌肉接合處乙醯膽鹼釋放，造成「弛緩性麻痺」等神經學症狀（如複視、吞嚥困難、肌肉無力），並非以水瀉與血樣黏液糞便為特徵，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。志賀氏桿菌、沙門氏桿菌感染腸道可引起發炎侵襲性腹瀉，出現血樣黏液糞便（A✓、B✓）；輪狀病毒感染則是造成水瀉的常見病毒性腸炎病原（C✓）。'},
{n:971, no:11, subj:'消化系統', q:'有關憩室炎常見的併發症，下列何者正確？①膿瘍 ②出血 ③胰臟炎 ④形成瘻管', opts:['A.①②③', 'B.①②④', 'C.①③④', 'D.②③④'], ans:[1], expl:'本題答案為B。憩室炎常見併發症包括局部發炎化膿形成膿瘍（①）、憩室血管侵蝕造成出血（②），以及慢性發炎穿透腸壁與鄰近器官（如膀胱、陰道）形成瘻管（④），選①②④＝B（本題答案）。胰臟炎（③）與憩室炎（好發於乙狀結腸）解剖位置及致病機轉皆不相關，並非其常見併發症。'},
{n:972, no:12, subj:'消化系統', q:'有關大腸癌的高危險因子，下列何者錯誤？', opts:['A.有過大腸息肉者', 'B.有習慣性便秘者', 'C.年齡小於 40 歲者', 'D.有大腸癌的家族史者'], ans:[2], expl:'本題答案為C。大腸癌好發於「年齡較長者」（通常50歲以上風險明顯上升），「年齡小於40歲」並非其高危險因子，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。大腸息肉病史（尤其腺瘤性息肉）、長期習慣性便秘（糞便滯留增加致癌物與腸黏膜接觸時間）、大腸癌家族史皆為大腸癌公認之高危險因子（A✓、B✓、D✓）。'},
{n:973, no:13, subj:'消化系統', q:'下列何者不是大腸鏡檢查的禁忌症？', opts:['A.便秘者', 'B.嚴重心絞痛者', 'C.潰瘍性結腸炎者', 'D.腸息肉剛切除後者'], ans:[0], expl:'本題答案為A。單純便秘並非大腸鏡檢查之禁忌症，臨床上甚至可能為安排大腸鏡檢查之適應症之一（用以釐清便秘病因），此為本題答案（A✓，題目問「何者不是禁忌症」）。嚴重心絞痛或心臟血管狀況不穩定者，因檢查過程可能誘發迷走神經反射或心律不整，屬相對禁忌（B✗）；潰瘍性結腸炎急性發作期腸壁較脆弱，內視鏡操作有穿孔風險，屬禁忌（C✗）；腸息肉剛切除後短時間內腸壁尚未癒合，再次進行大腸鏡有出血或穿孔風險，亦屬禁忌（D✗）。'},
{n:974, no:14, subj:'消化系統', q:'有關舌癌的敘述，下列何者正確？', opts:['A.通常屬於基底細胞癌', 'B.口腔腫瘤中預後最差的一種', 'C.大多發生於舌頭前段', 'D.好發於中年以後的女性'], ans:[1], expl:'本題答案為B。舌癌在口腔癌各類型中，因舌部血流與淋巴回流豐富，腫瘤易早期發生局部侵犯及頸部淋巴結轉移，臨床上被認為是口腔腫瘤中預後相對最差的一種，此為本題答案（B✓）。舌癌絕大多數為「鱗狀細胞癌」，而非基底細胞癌（基底細胞癌好發於皮膚，口腔內少見）（A✗）；舌癌好發於「舌側緣及舌根部」，而非舌頭前段（C✗）；舌癌好發族群以「中老年男性」為主（與嚼檳榔、抽菸、喝酒等危險因子相關），並非好發於中年以後女性（D✗）。'},
{n:975, no:15, subj:'消化系統', q:'有關腹膜炎病人身體評估之發現，下列何者正確？①腹痛輻射至背部或肩膀 ②腹部肌肉僵硬如木板 ③觸診腹部時出現壓痛及反彈痛 ④腸蠕動音增強', opts:['A.①③', 'B.①④', 'C.②③', 'D.②④'], ans:[2], expl:'本題答案為C。腹膜炎典型身體評估發現包括腹部肌肉不自主收縮呈「木板狀僵硬」（②）以及觸診時出現壓痛與放手後加劇之反彈痛（③），選②③＝C（本題答案）。腹膜炎疼痛通常為瀰漫性腹痛而非典型「輻射至背部或肩膀」（①，此較符合膽囊疾病或胰臟炎的疼痛型態）；腹膜炎因腸道發炎、蠕動受抑制，典型表現為腸蠕動音「減弱或消失」，而非增強（④），故①④皆非本題腹膜炎典型發現。'},
{n:976, no:16, subj:'消化系統', q:'病人主訴「餓的時候疼痛，常常半夜痛醒」 ，下列何者為其最大可能之診斷？', opts:['A.胃食道逆流', 'B.慢性胃炎', 'C.胃潰瘍', 'D.十二指腸潰瘍'], ans:[3], expl:'本題答案為D。十二指腸潰瘍典型疼痛型態為空腹或飢餓時疼痛加劇（因胃酸直接刺激已無食物緩衝之潰瘍處），進食後疼痛反而緩解，且常於半夜（胃酸分泌高峰、胃已排空）痛醒，與本題描述最相符，為本題答案（D✓）。胃食道逆流典型症狀為火燒心、胸悶感，常於飯後或平躺時加劇（A✗）；慢性胃炎症狀較不具此規律性飢餓痛型態（B✗）；胃潰瘍疼痛型態則多為「進食後」疼痛加劇（食物刺激受損之胃黏膜），與十二指腸潰瘍「空腹痛、進食緩解」的型態相反（C✗）。'},
{n:977, no:17, subj:'消化系統', q:'有關刺激胃液分泌的因素，下列何者正確？', opts:['A.交感神經', 'B.胃泌素', 'C.三酸甘油酯', 'D.核甘酸'], ans:[1], expl:'本題答案為B。胃泌素（gastrin）由胃竇G細胞分泌，可直接刺激胃壁細胞分泌胃酸，是刺激胃液分泌的重要體液性因子之一，此為本題答案（B✓）。交感神經興奮通常「抑制」胃腸道分泌與蠕動（副交感神經／迷走神經興奮才會刺激胃液分泌）（A✗）；三酸甘油酯及核甘酸並非刺激胃液分泌的主要生理因子（C✗、D✗）。'},
{n:978, no:18, subj:'骨骼肌肉', q:'有關骨性關節炎的診斷檢查，下列何者正確？', opts:['A.抗細胞核抗體（ANA）升高', 'B.X 光呈現骨贅形成及關節腔變窄', 'C.C 反應蛋白（CRP）上升', 'D.關節滑液呈現混濁，黏性低、蛋白質增加'], ans:[1], expl:'本題答案為B。退化性（骨性）關節炎因軟骨磨損、骨質增生反應，X光典型可見關節邊緣骨贅（osteophyte）形成及關節腔因軟骨磨損而變窄，此為本題答案（B✓）。抗細胞核抗體（ANA）升高多與全身性紅斑性狼瘡等自體免疫疾病相關，並非骨性關節炎的診斷特徵（A✗）；C反應蛋白（CRP，發炎指標）在骨性關節炎中通常無明顯上升（較常見於類風濕性關節炎等發炎性關節病變）（C✗）；骨性關節炎之關節滑液分析通常仍相對清澈、黏性正常，蛋白質變化不若發炎性關節炎明顯（D✗，關節滑液混濁、黏性降低、蛋白質增加較符合發炎性關節炎特徵）。'},
{n:979, no:19, subj:'骨骼肌肉', q:'下列何者為退化性關節炎的高危險群？①BMI 35 kg/m² ②長期服用腎上腺皮質類固醇 ③重複性右膝受傷史 ④停經後婦女', opts:['A.①②③', 'B.①②④', 'C.①③④', 'D.②③④'], ans:[2], expl:'本題答案為C。肥胖（BMI 35 kg/m²，①）增加關節負重、重複性關節受傷病史（③）以及停經後婦女因荷爾蒙變化影響軟骨代謝（④）皆為退化性關節炎公認之高危險因子，選①③④＝C（本題答案）。長期服用腎上腺皮質類固醇（②）主要與「骨質疏鬆症」及「股骨頭缺血性壞死」的風險相關，並非退化性關節炎之典型危險因子。'},
{n:980, no:20, subj:'骨骼肌肉', q:'右側下肢無力需要使用手杖之病人，下列使用方法何者最正確？', opts:['A.左手持手杖並放在左腳前方', 'B.右手持手杖並放在右腳前方', 'C.左手持手杖並放於左腳尖前外側 6 吋處', 'D.右手持手杖並放於右腳尖前外側 6 吋處'], ans:[2], expl:'本題答案為C。使用手杖之基本原則為「手杖持於健側（較有力的一側）」，本題病人右下肢無力，故手杖應以「左手」持握；且手杖擺放位置應在健側腳尖「前外側約15公分（約6吋）」處，形成穩定的三角支撐底面積，此為本題答案（C✓）。A、B選項未說明手杖擺放於腳尖前外側之正確位置關係（過於簡化為「前方」），且未達到理想的三角支撐效果；D選項將手杖持於患側（右手，右下肢無力側），違反「手杖持於健側」的基本原則（A✗、B✗、D✗）。'},
{n:981, no:21, subj:'骨骼肌肉', q:'病人右大腿骨折上石膏 3 個月，拆除石膏時，不會看到下列那種現象？', opts:['A.皮膚布滿黃棕色皮膚碎屑', 'B.肌肉張力增加', 'C.肢體看起來僵硬', 'D.平衡感改變'], ans:[1], expl:'本題答案為B。長期石膏固定會造成該肢體「廢用性肌肉萎縮」，肌肉張力應是「降低」而非增加，此為石膏拆除後「不會」看到的現象，為本題答案（B✓，題目問「不會看到」何者）。皮膚因長期未清潔、角質代謝物堆積會呈現黃棕色皮膚碎屑附著（A✓會看到）；因肌肉萎縮、關節暫時性僵硬，肢體外觀確實會顯得僵硬（C✓會看到）；因本體感覺及肌力暫時改變，病人平衡感也可能受影響（D✓會看到）。'},
{n:982, no:22, subj:'感官系統', q:'有關聽力喪失可聽見的音量敘述，下列何者錯誤？', opts:['A.可聽見在 25 分貝內的音量，聽力正常', 'B.只能聽見 30 分貝以上的音量，聽力為輕度受損', 'C.只能聽見 60 分貝以上的音量，聽力為重度受損', 'D.只能聽見 90 分貝以上的音量，聽力為極重度受損'], ans:[2], expl:'本題答案為C。聽力閾值60分貝以上才能聽見，依國際聽力損失分級，60分貝約落在「中重度（56～70分貝）」聽力損失範圍，而非「重度」聽力損失（重度聽力損失一般定義為71～90分貝需大音量方能聽見），此敘述有誤，為本題答案（C✗，題目問「何者錯誤」）。25分貝以內能聽見屬聽力正常範圍（A✓）；30分貝以上才能聽見大致對應輕度聽損（26～40分貝）之範圍（B✓）；90分貝以上才能聽見則對應極重度聽力損失（≥91分貝）之範圍（D✓）。'},
{n:983, no:23, subj:'感官系統', q:'有關鼻竇炎術後的護理措施，下列何者錯誤？', opts:['A.採平躺臥姿', 'B.冰敷鼻子與臉頰', 'C.若有引流物，由口吐出，不要擤鼻子', 'D.以棉籤適度清潔口腔或漱口'], ans:[0], expl:'本題答案為A。鼻竇炎手術後應採「半坐臥或坐臥姿」（床頭抬高），以利鼻腔及鼻竇分泌物引流並減輕局部腫脹，若採平躺臥姿反而不利引流、可能增加局部充血與出血風險，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。術後冰敷鼻子與臉頰有助於減輕腫脹與出血（B✓）；術後應避免用力擤鼻涕（以免增加鼻腔內壓力造成出血或氣腫），若有引流物應自口中輕輕吐出（C✓）；因術後可能限制經鼻呼吸與清潔，需以棉籤或漱口方式維持口腔清潔與濕潤（D✓）。'},
{n:984, no:24, subj:'感官系統', q:'有關美尼爾氏症之敘述，下列何者正確？①可能原因是外耳淋巴液過多 ②症狀為雙側傳導性聽力減退 ③使用血管擴張劑減輕耳鳴症狀 ④藥物治療無效時，可採迷路切除術', opts:['A.①②', 'B.①③', 'C.②④', 'D.③④'], ans:[3], expl:'本題答案為D。美尼爾氏症藥物治療（如利尿劑、血管擴張劑、鹽分限制等）效果不佳、症狀反覆嚴重影響生活時，可考慮迷路切除術等破壞性手術以控制眩暈症狀（④），選③④＝D（本題答案）；血管擴張劑（如Betahistine）確實為治療美尼爾氏症以減輕耳鳴及眩暈症狀的常用藥物之一（③）。美尼爾氏症被認為與「內耳（膜迷路）淋巴液」代謝異常、內淋巴水腫有關，並非外耳淋巴液過多（①錯誤）；其聽力減退型態為感音性（感覺神經性）聽力喪失，且多為「單側」，並非雙側傳導性聽力減退（②錯誤，傳導性聽力障礙多與外耳、中耳病變有關）。'},
{n:985, no:25, subj:'感官系統', q:'有關白內障之敘述，下列何者錯誤？', opts:['A.眼睛水晶體發生混濁', 'B.瞳孔呈乳白色', 'C.好發於兩側', 'D.約 95%發生於高度近視者'], ans:[3], expl:'本題答案為D。白內障主要好發族群為「老年性（老化）」為最大宗，其他病因尚包括先天性、外傷性、代謝性（如糖尿病）、藥物性（如長期使用類固醇）等，並非約95%皆發生於高度近視者，此敘述有誤，為本題答案（D✗，題目問「何者錯誤」）。水晶體因蛋白質變性而發生混濁是白內障之病理本質（A✓）；混濁之水晶體使瞳孔外觀呈現乳白色或灰白色，是臨床可觀察到之典型徵象（B✓）；白內障（尤其老年性白內障）雖進展速度可能不同步，但多為雙側皆可能發生（C✓）。'},
{n:986, no:26, subj:'心臟血管', q:'僧帽瓣逆流或狹窄的病人，易出現下列何種症狀？①呼吸困難 ②下肢水腫 ③端坐呼吸 ④咳嗽 ⑤肝腫大', opts:['A.①②③', 'B.①③④', 'C.②③⑤', 'D.②④⑤'], ans:[1], expl:'本題答案為B。僧帽瓣逆流或狹窄使左心房壓力上升，血液鬱積回堵至肺循環，造成呼吸困難（①）及端坐呼吸（③，平躺時肺鬱血加劇故需坐姿緩解）；長期肺循環壓力上升更可能逆行影響右心，造成體循環鬱血而咳嗽（因肺鬱血刺激）（④），選①③④＝B（本題答案）。下肢水腫（②）與肝腫大（⑤）主要反映「右心衰竭／體循環鬱血」之表現，較非僧帽瓣（左心房室瓣）病變最直接、最典型之表現。'},
{n:987, no:27, subj:'心臟血管', q:'心包填塞（cardiac tamponade）之臨床表徵，下列何者正確？①低沉的心音 ②中心靜脈壓上升 ③奇異脈 ④脈搏壓變寬', opts:['A.①②③', 'B.①②④', 'C.①③④', 'D.②③④'], ans:[0], expl:'本題答案為A。心包填塞因心包腔內液體壓迫心臟，典型臨床三徵（Beck\'s triad）之一即心音因液體阻隔而顯得低沉遙遠（①）；心臟受壓迫、右心回流受阻，導致中心靜脈壓上升、頸靜脈怒張（②）；且因心室充填受限，吸氣時左心室輸出量下降更明顯，造成奇異脈（收縮壓於吸氣時下降超過10 mmHg）（③），選①②③＝A（本題答案）。心包填塞因心搏量下降，脈搏壓（收縮壓與舒張壓之差）應是「變窄」而非變寬（④錯誤，脈搏壓變窄才是心包填塞的典型表現）。'},
{n:988, no:28, subj:'心臟血管', q:'造成心因性休克的主要原因，不包括下列何者？', opts:['A.心律不整', 'B.心肌梗塞', 'C.瓣膜性心臟病', 'D.創傷致出血過多'], ans:[3], expl:'本題答案為D。創傷導致大量出血是屬於「低血容積性休克」的成因，並非心因性休克（心臟幫浦功能本身衰竭所致）的主要原因，此為本題答案（D✓，題目問「不包括」何者）。心律不整（影響心臟有效收縮及輸出）、心肌梗塞（心肌壞死使收縮力下降）、瓣膜性心臟病（結構異常影響血液有效輸出）皆屬會直接影響心臟幫浦功能、導致心因性休克的常見原因（A、B、C）。'},
{n:989, no:29, subj:'心臟血管', q:'林空服員近日覺得小腿不適，護理師採取下列何項評估其深部靜脈栓塞？', opts:['A.艾倫試驗（Allen test）', 'B.霍曼氏徵象（Homan’s sign）', 'C.抬腿試驗（leg raising test）', 'D.克尼格氏徵象（Kernig’s sign）'], ans:[1], expl:'本題答案為B。霍曼氏徵象（Homan\'s sign）是將病人小腿伸直、足部背屈時，若腓腸肌處誘發疼痛，提示可能有深部靜脈栓塞（DVT），是臨床上（雖敏感度與特異度有限，仍為傳統教學常用之）評估DVT的方法，此為本題答案（B✓）。艾倫試驗是評估手部橈動脈與尺動脈側枝循環是否通暢（常用於採動脈血前）（A✗）；抬腿試驗多用於評估周邊動脈循環或靜脈瓣膜功能，並非DVT之標準評估法（C✗）；克尼格氏徵象是評估腦膜刺激徵象、與DVT無關（D✗）。'},
{n:990, no:30, subj:'心臟血管', q:'曾先生心臟衰竭住院，住院時出現臉色蒼白、冒冷汗、陣發性夜間呼吸困難及咳出大量帶有血絲的泡沫痰。請問曾先生出現那一種合併症？', opts:['A.氣喘', 'B.肺結核', 'C.肺栓塞', 'D.肺水腫'], ans:[3], expl:'本題答案為D。臉色蒼白、冒冷汗、陣發性夜間呼吸困難（PND）合併咳出大量帶血絲泡沫痰，是「急性肺水腫」的典型臨床表現，反映左心衰竭導致肺微血管靜水壓上升、液體滲入肺泡腔，此為本題答案（D✓）。氣喘典型表現為喘鳴、呼氣延長，通常不會咳出大量血絲泡沫痰（A✗）；肺結核典型表現為慢性咳嗽、咳血、體重減輕、盜汗等慢性病程，與本題急性發作情境不符（B✗）；肺栓塞典型表現為突發性胸痛、呼吸困難、心搏過速，與本題泡沫痰的描述不符（C✗）。'},
{n:991, no:31, subj:'心臟血管', q:'有關心絞痛之常用藥物 Nitroglycerine（NTG）之護理指導，下列何者錯誤？', opts:['A.疼痛時服用，連續 5 顆無效，才考慮就醫', 'B.舌下含服時，舌頭會感到熱、辣', 'C.平時應存放在遮光陰涼處，避免高溫', 'D.使用皮膚貼片時，應每日更換貼片，並輪換部位'], ans:[0], expl:'本題答案為A。使用舌下NTG時，若含服1顆後5分鐘疼痛未緩解可再含1顆，最多連續使用3顆（約每5分鐘一顆），若仍無效即應立即就醫或呼叫緊急救護，並非需服滿5顆才考慮就醫（等待時間過長恐延誤心肌梗塞之處置），此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。舌下含服NTG因血管擴張作用，病人常感覺舌頭有灼熱刺麻感，此為藥物有效之徵象之一，敘述正確（B✓）；NTG藥性不穩定，易受光線、高溫影響而分解失效，應存放於遮光陰涼處並定期更換，敘述正確（C✓）；使用經皮貼片型NTG時應每日更換並輪替貼附部位，以避免皮膚刺激及降低耐藥性，敘述正確（D✓）。'},
{n:992, no:32, subj:'心臟血管', q:'有關抗心律不整藥物，下列何者屬於鈉離子通道阻斷劑？', opts:['A.Amiodarone（Cordarone）', 'B.Atropine', 'C.Lidocaine（Xylocaine）', 'D.Propranolol（Inderal）'], ans:[2], expl:'本題答案為C。依Vaughan Williams抗心律不整藥物分類，Lidocaine（Xylocaine）屬第Ib類「鈉離子通道阻斷劑」，主要用於治療心室性心律不整，此為本題答案（C✓）。Amiodarone主要屬第III類鉀離子通道阻斷劑（雖具多重通道作用機轉）（A✗）；Atropine為抗膽鹼藥物，用於提升心跳速率，非抗心律不整藥物之鈉通道阻斷劑分類（B✗）；Propranolol屬第II類乙型交感神經阻斷劑（D✗）。'},
{n:993, no:33, subj:'心臟血管', q:'有關病人心電圖 VT 之相關處置，下列何者正確？', opts:['A.有意識的情況下，實施去纖維震顫術，應選擇同步心臟電氣轉換術（synchronized cardioversion）', 'B.無脈搏的情況下，實施去纖維震顫術前，應先注射麻醉鎮靜劑', 'C.有脈搏的情況下，實施去纖維震顫術，可直接使用 100 焦耳', 'D.心電圖從 VT 變 Vf 時，應停止實施去纖維震顫術，改心肺復甦術'], ans:[0], expl:'本題答案為A。病人「有意識」且有脈搏之心室頻脈（VT），因心臟仍有規律電氣活動可供偵測，應選擇與病人心跳QRS波同步放電之「同步心臟電氣轉換術」，以避免電擊落在心臟脆弱期（如T波）誘發心室顫動，此為本題答案（A✓）。「無脈搏」之心室頻脈屬心跳停止之一種，應立即進行「非同步」去顫，而非在此情況下優先注射鎮靜劑延誤急救時機（B✗，無脈搏VT應視同心跳停止立即去顫，若病人仍清醒有意識才需要鎮靜再電擊）；「有脈搏」之VT應採同步電擊，且應依醫囑及病人情況選擇適當能量，非直接跳過評估逕自使用100焦耳（C✗）；若電擊過程中VT惡化為心室顫動（Vf），因Vf已無有效心跳應立即改為「非同步去顫」並持續心肺復甦術，而非單純停止電擊（D✗，應改變處置方式而非完全停止急救）。'},
{n:994, no:34, subj:'心臟血管', q:'心衰竭病人之心電圖持續出現明顯 U 波，在給予藥物時，應注意下列何種藥物可能有中毒的危險？', opts:['A.利尿劑', 'B.軟便劑', 'C.血管擴張劑', 'D.毛地黃製劑'], ans:[3], expl:'本題答案為D。心電圖出現明顯U波，臨床上最常與「低血鉀」相關；而低血鉀狀態會顯著增加毛地黃類藥物（Digoxin等）的心臟毒性風險（低血鉀時毛地黃更易與Na-K-ATPase酶結合，增強其毒性作用），故給藥時應特別留意毛地黃中毒之可能，此為本題答案（D✓）。利尿劑、軟便劑、血管擴張劑本身雖可能間接影響電解質（如利尿劑可能造成低血鉀），但題目問的是「因心電圖U波（提示低血鉀）而應注意中毒風險」的藥物，直接答案應指向與低血鉀交互作用致毒性增加之毛地黃製劑（A✗、B✗、C✗）。'},
{n:995, no:35, subj:'心臟血管', q:'王先生入院接受心導管檢查，此次檢查穿刺左側橈動脈，下列護理處置何者錯誤？', opts:['A.教導病人加壓傷口至少 2 小時，並觀察有無出血', 'B.檢查後，第 1 小時應每 15 分鐘測量雙手血壓，並做比較', 'C.以 6P（pain、pallor、pulselessness、poikilothermia、paralysis、paresthesia）評估病人雙手末梢，並做比較', 'D.教導病人出院後，左手禁提重物'], ans:[1], expl:'本題答案為B。心導管檢查後應於「最初15～30分鐘內較密集」監測穿刺側肢體末梢循環及生命徵象（非等到第1小時才每15分鐘測量一次），且血壓監測頻率應依機構常規（通常檢查後前段時間更密集，之後逐漸延長間隔），此敘述時序描述有誤，為本題答案（B✗，題目問「何者錯誤」）。穿刺處應加壓止血至少2小時並持續觀察有無出血或血腫，敘述正確（A✓）；應以6P評估穿刺側肢體末梢循環狀況並與健側比較，及早發現動脈栓塞等併發症，敘述正確（C✓）；為避免穿刺處出血或血管損傷，應教導病人出院後左手（穿刺側）短期內避免提重物，敘述正確（D✓）。'},
{n:996, no:36, subj:'腫瘤血液', q:'依據安阿伯（Ann Arbor）臨床分期系統，下列何者屬於何杰金氏淋巴瘤第Ⅱ期？', opts:['A.侵犯多個淋巴結以外的器官或組織', 'B.侵犯單一淋巴結區域外器官', 'C.侵犯橫膈膜同側 2 個以上淋巴結區域', 'D.侵犯橫膈膜兩側淋巴結區域'], ans:[2], expl:'本題答案為C。依Ann Arbor分期系統，第Ⅱ期定義為病灶侵犯橫膈膜「同一側」兩個（含）以上的淋巴結區域，此為本題答案（C✓）。侵犯單一淋巴結區域外之器官組織屬第Ⅳ期（廣泛性結外侵犯）之表現，非第Ⅱ期定義（A✗、B✗說法亦不精確，第Ⅰ期方為單一淋巴結區域或單一結外器官局部侵犯）；侵犯橫膈膜「兩側」淋巴結區域則屬第Ⅲ期定義（D✗）。'},
{n:997, no:37, subj:'腫瘤血液', q:'下列何者不是骨髓檢查之目的？', opts:['A.評估化學治療效果', 'B.診斷血液系統疾病', 'C.確定血球前驅細胞的數目', 'D.評估骨髓壓力狀況'], ans:[3], expl:'本題答案為D。骨髓檢查（骨髓抽吸及切片）主要目的在評估血液系統疾病之診斷（如白血病、貧血、骨髓增生性疾病）、確定各類血球前驅細胞數目與型態、評估化學治療反應及骨髓功能狀態，但並非用以評估「骨髓腔內壓力」，此非其常規檢查目的，為本題答案（D✓，題目問「不是」何者）。評估化學治療效果（A）、診斷血液系統疾病（B）、確定血球前驅細胞數目（C）皆為骨髓檢查明確之臨床目的。'},
{n:998, no:38, subj:'腫瘤血液', q:'醫師告知王先生罹患多發性骨髓瘤，王先生問護理師這是什麼病，下列何者是護理師最適當的回覆？', opts:['A.不正常的白血球過度增生', 'B.骨髓中的漿細胞惡性分化且過度增生', 'C.不正常的紅血球過度增生', 'D.不正常的淋巴球過度增生'], ans:[1], expl:'本題答案為B。多發性骨髓瘤是漿細胞（plasma cell，由B淋巴球分化而來）發生惡性轉化、於骨髓中不正常過度增生的血液惡性腫瘤，並會大量分泌單株免疫球蛋白，此為本題答案（B✓）。並非白血球、紅血球或淋巴球本身的不正常過度增生（A✗、C✗、D✗，多發性骨髓瘤的核心病理是「漿細胞」這一特化的終末分化B細胞株之惡性增生，與單純淋巴球增生的白血病或淋巴瘤有所區隔）。'},
{n:999, no:39, subj:'腫瘤血液', q:'有關放射線治療癌症之敘述，下列何者正確？', opts:['A.放射線強度與距離的平方成反比，距離放射源越遠暴露量越少', 'B.要採集中式護理，穿隔離衣以減少放射線的暴露量', 'C.封閉式體內放射線治療病人的排泄物具大量放射性，倒入馬桶需多沖水', 'D.非封閉式體內放射線治療在移除植入器後，病人身上就不具放射性'], ans:[0], expl:'本題答案為A。放射線強度依「反平方定律（inverse square law）」隨距離增加而遞減（強度與距離平方成反比），距離輻射源越遠，暴露劑量越低，此為放射線防護基本原則之一，為本題答案（A✓）。一般隔離衣並不具備阻擋游離輻射的屏蔽效果（需鉛衣等專用防護具），且應採「限制接觸時間」而非單純集中式護理來降低暴露（B✗）；「封閉式（密封源）」體內放射線治療（如近接治療植入器）之放射源受包封，病人體液排泄物並不具放射性，無需特別处理（C✗，此描述恰與非封閉式相反）；「非封閉式（未密封）」體內放射線治療（如口服放射性碘）之放射性物質會分布全身並隨代謝排出，其治療原理本無「植入器」可移除，且病人於治療後一段時間內身體仍具有放射性，需依規定監測後才能解除輻射防護措施，並非移除後立即不具放射性（D✗）。'},
{n:1000, no:40, subj:'腫瘤血液', q:'有關 Fentanyl 皮膚止痛貼片照護之敘述，下列何者錯誤？', opts:['A.屬於弱效麻醉性止痛劑，維持血中濃度 48～72 小時', 'B.要注意觀察呼吸抑制、嗜睡、暈眩等副作用', 'C.更換新貼片時，舊貼片可再多貼一天', 'D.止痛貼片可貼在前胸、後背、上臂等皮膚平坦完整處'], ans:[0], expl:'本題答案為A。Fentanyl為強效（非弱效）鴉片類（麻醉性）止痛劑，其貼片劑型可維持穩定血中濃度達72小時左右，此敘述之「弱效」及血中濃度持續時間描述有誤，為本題答案（A✗，題目問「何者錯誤」）。使用鴉片類止痛藥須密切觀察呼吸抑制、嗜睡、暈眩等副作用，敘述正確（B✓）；更換新貼片初期血中濃度尚未達穩定狀態，可讓舊貼片與新貼片短暫重疊多貼一天以維持止痛效果之銜接，敘述正確（C✓）；貼片應貼於前胸、後背、上臂等皮膚平坦、完整且毛髮少之部位，以利藥物穩定吸收，敘述正確（D✓）。'},
{n:1001, no:41, subj:'腫瘤血液', q:'胃癌的發生可能與下列何種病毒或細菌感染有關？', opts:['A.CMV（cytomegalovirus）', 'B.Escherichia coli', 'C.Helicobacter pylori', 'D.HPV（human papilloma virus）'], ans:[2], expl:'本題答案為C。幽門螺旋桿菌（Helicobacter pylori）感染會引起慢性胃炎、消化性潰瘍，並已被世界衛生組織列為第一級致癌物，與胃腺癌及胃黏膜相關淋巴組織淋巴瘤（MALT lymphoma）的發生有明確relevance，此為本題答案（C✓）。巨細胞病毒（CMV）多與免疫低下病人之感染相關，大腸桿菌為腸道常見菌叢，人類乳突病毒（HPV）則主要與子宮頸癌、口咽癌等相關，皆非胃癌之主要相關致病原（A✗、B✗、D✗）。'},
{n:1002, no:42, subj:'腫瘤血液', q:'真性紅血球增多症的臨床表徵，下列何者錯誤？', opts:['A.眼結膜充血', 'B.臉色蒼白', 'C.皮膚發癢', 'D.頭痛'], ans:[1], expl:'本題答案為B。真性紅血球增多症（polycythemia vera）因骨髓過度增生紅血球，病人血液黏稠度增加、微血管血流減緩淤積，典型會出現臉部及眼結膜「潮紅（充血）」，而非臉色蒼白，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。眼結膜充血、皮膚發癢（尤其洗熱水澡後因組織胺釋放加劇）、因血液黏滯度增加影響腦部微循環而頭痛，皆為真性紅血球增多症常見之臨床表徵（A✓、C✓、D✓）。'},
{n:1003, no:43, subj:'腫瘤血液', q:'有關癌症治療對口腔黏膜之影響與處置，下列敘述何者正確？', opts:['A.舌頭味蕾易被破壞，且治療後味覺不會恢復', 'B.唾液腺會受破壞，使得唾液分泌減少', 'C.進食後使用止痛噴劑，可改善病人進食的困擾', 'D.使用 Mycostatin（Nystatin）漱口液，漱口後吐掉'], ans:[1], expl:'本題答案為B。化學或放射線治療皆可能傷害唾液腺組織，導致唾液分泌量顯著減少（口乾），進而增加口腔黏膜炎、齲齒及感染風險，此為本題答案（B✓）。味蕾雖可能因治療暫時受損、味覺改變，但多數在治療結束後一段時間可逐漸恢復，並非永久不可恢復，此敘述過於絕對（A✗）；口腔黏膜疼痛不適的處置建議應「於進食前」使用局部止痛噴劑或漱口液，以利進食時能減輕疼痛，而非進食後才使用（C✗，時機描述有誤）；Mycostatin（Nystatin）懸液用於治療口腔念珠菌感染，使用時應在口中充分含漱後「吞下」以利藥效作用於整個口咽及食道黏膜，而非漱口後吐掉（D✗）。'},
{n:1004, no:44, subj:'其他', q:'有關皮膚系統附屬物之敘述，下列何者錯誤？', opts:['A.指甲持續生長，每天約長 0.1 mm', 'B.毛髮結構貫穿表皮、真皮及皮下組織', 'C.頂漿汗腺與毛囊相通，常分布於腋下、乳頭及肚臍周圍', 'D.外泌汗腺以手掌、腳底板分布最多，其分泌液會產生體臭'], ans:[3], expl:'本題答案為D。外泌汗腺（eccrine gland）廣泛分布全身皮膚，其中確以手掌、足底密度最高，但其分泌物主要成分為水分及少量電解質，「本身幾乎無味」，並非造成體臭的主要腺體；體臭主要與「頂漿汗腺（apocrine gland）」分泌物經皮膚細菌分解後產生有關，此敘述有誤，為本題答案（D✗，題目問「何者錯誤」）。指甲平均每日約生長0.1 mm，敘述正確（A✓）；毛髮結構（毛囊）確實貫穿表皮、真皮，深入至皮下組織，敘述正確（B✓）；頂漿汗腺主要分布於腋下、乳暈、肚臍周圍及會陰部等特定部位，並與毛囊構造相通，敘述正確（C✓）。'},
{n:1005, no:45, subj:'其他', q:'有關使用 Braden scale 評估壓傷危險因子和處置之敘述，下列何者正確？', opts:['A.滿分為 24 分，分數越高表示皮膚風險越大', 'B.13 分代表中等危險，需每 2 小時翻身及評估皮膚', 'C.依據摩擦力和剪力程度決定是否需使用氣墊床', 'D.壓傷危險分級是依據三大層面總和分數做判定'], ans:[1], expl:'本題答案為B。Braden scale總分範圍為6～23分，總分13分落於「中度危險（13～14分）」範圍，此危險等級病人建議每2小時翻身並評估皮膚狀況，此為本題答案（B✓）。Braden scale滿分應為「23分」而非24分，且「分數越低」表示壓傷風險越高（並非分數越高風險越大），此敘述有誤（A✗）；是否使用氣墊床等減壓裝置應綜合六大項目（感覺知覺、潮濕度、活動力、移動力、營養、摩擦力與剪力）「總分」判定病人整體風險等級後決定，並非僅依單一「摩擦力和剪力」項目判斷（C✗）；Braden scale係以「六大」層面（而非三大層面）之總分進行壓傷危險分級判定（D✗）。'},
{n:1006, no:46, subj:'其他', q:'針對右髖關節嚴重燒傷病人，為維持其關節最大功能之姿位，下列何者正確？', opts:['A.髖關節維持屈曲 30 度', 'B.髖關節屈曲 0 度，仰臥腿伸展', 'C.膝關節屈曲 30 度', 'D.大腿內收'], ans:[1], expl:'本題答案為B。髖關節燒傷後為預防攣縮、維持關節最大功能性角度，應將髖關節維持在「伸直（0度）」姿位、採仰臥並使腿部伸展，避免因疼痛而長時間屈曲攣縮導致日後活動功能受限，此為本題答案（B✓）。若長時間維持髖關節屈曲30度，容易導致髖關節屈曲攣縮，喪失完全伸直的功能（A✗、C✗方向錯誤，膝關節屈曲亦同理應避免長時間固定屈曲姿勢）；大腿應維持中立或輕度外展姿位以避免內收攣縮，而非刻意內收（D✗）。'},
{n:1007, no:47, subj:'其他', q:'有關遲發型過敏反應之敘述，下列何者錯誤？', opts:['A.抗體與抗原結合形成免疫複合體，隨血液循環四處沉積所導致', 'B.器官移植後排斥反應屬此類過敏反應', 'C.可能因接觸化學物質，如染劑、藥物等物質刺激產生的過敏反應', 'D.病毒或細菌侵入後，刺激 T 細胞引發細胞性免疫反應'], ans:[0], expl:'本題答案為A。抗體與抗原結合形成免疫複合體並隨血液循環沉積於全身各處（如腎絲球、血管壁），進而活化補體引發發炎反應，是「第三型（免疫複合物型）」過敏反應之機轉，並非遲發型（第四型）過敏反應之機轉，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。器官移植後之急性排斥反應主要由T細胞媒介之細胞性免疫反應所致，屬第四型過敏反應之典型例子，敘述正確（B✓）；接觸性皮膚炎（因染劑、藥物等化學物質誘發）是第四型過敏反應之經典臨床範例，敘述正確（C✓）；第四型過敏反應之核心機轉即病原（病毒、細菌等）刺激致敏T細胞，引發細胞媒介型免疫反應（而非抗體媒介），敘述正確（D✓）。'},
{n:1008, no:48, subj:'其他', q:'成年病人燒傷面積：軀幹正面皮膚發紅且有大片水泡、右上肢前面皮膚呈現灰白色以及有水泡。依九的法則計算其燒傷總體表面積，下列何者正確？', opts:['A.18%', 'B.22.5%', 'C.27%', 'D.40.5%'], ans:[1], expl:'本題答案為B。依成人九的法則，軀幹正面（前軀幹）佔全身體表面積之18%，單一上肢前面（含手掌）約佔4.5%（上肢總計9%，前後面各半），本題病人軀幹正面（18%）與右上肢前面（4.5%）皆有二度以上燒傷表現，加總為18%＋4.5%＝22.5%，此為本題答案（B✓）。18%僅計入軀幹正面（漏未計入上肢部分）（A✗）；27%、40.5%皆與依九的法則之正確計算結果不符（C✗、D✗）。'},
{n:1009, no:49, subj:'其他', q:'有關照護愛滋病人防護措施之敘述，下列何者正確？', opts:['A.使用過的針頭應與針筒分開處理，針頭置於堅硬不易刺破的容器內', 'B.若不慎接觸糞便須立刻口服 400 mg 反轉錄酶抑制劑（AZT）', 'C.若衣物被病人分泌物污染，應以漂白水浸泡後再清洗', 'D.若不慎被針扎應持續追蹤 3 個月，抽血檢驗結果為陰性即可排除感染'], ans:[2], expl:'本題答案為C。若衣物遭愛滋病人血液或分泌物污染，應先以漂白水（含氯消毒液）浸泡處理以達到有效消毒，再進行一般清洗，此為本題答案（C✓）。使用過的針頭應「連同針筒」整組直接丟棄於堅固防穿刺的專用感染性醫療廢棄物容器內，「不可回套針頭蓋、不可將針頭與針筒分離」，以避免針扎意外，此敘述有誤（A✗）；針扎意外後之預防性投藥（如反轉錄酶抑制劑）屬醫療處置，需由醫師評估風險後儘速（建議2小時內、最晚不超過72小時）開立適當之預防性用藥組合，並非病人或醫護人員逕自「立刻口服400 mg AZT」自行用藥（B✗）；針扎意外後之追蹤檢驗建議期程一般為6個月（依各國指引可能略有差異，多數建議追蹤至少6個月），並非3個月即可排除感染（D✗）。'},
{n:1010, no:50, subj:'其他', q:'有關全身性紅斑性狼瘡之致病機轉，下列何者正確？', opts:['A.是一種遲發性過敏反應 T 細胞造成的過敏反應', 'B.是一種人體產生對抗自己本身抗體所引發的過敏反應', 'C.此過敏反應主要介質是 IgE', 'D.主要是抗體對抗外在過敏原所產生的過敏反應'], ans:[1], expl:'本題答案為B。全身性紅斑性狼瘡（SLE）核心致病機轉是人體免疫系統對自身組織抗原產生「自體抗體」（如抗細胞核抗體），形成免疫複合體並沉積於全身組織（腎臟、皮膚、關節等）引發發炎損傷，屬於「自體免疫」疾病的過敏反應機轉，此為本題答案（B✓）。SLE主要為抗體媒介之第三型過敏反應（免疫複合物型），而非T細胞媒介之遲發型（第四型）過敏反應（A✗）；SLE的主要免疫球蛋白介質為IgG等自體抗體，而非IgE（IgE主要與第一型過敏反應相關）（C✗）；SLE是產生「對抗自身組織」的自體抗體，而非對抗外來過敏原，此與D選項描述之方向相反（D✗）。'},
{n:1011, no:51, subj:'其他', q:'下列何者不屬於第三型過敏性反應？', opts:['A.全身性紅斑狼瘡', 'B.類風濕性關節炎', 'C.溶血性反應', 'D.血清病'], ans:[2], expl:'本題答案為C。溶血性反應（如輸血不合造成之溶血）主要是抗體直接作用於紅血球表面抗原、活化補體導致細胞溶解破壞，屬於「第二型（細胞毒殺型）」過敏反應，並非第三型免疫複合物型過敏反應，此為本題答案（C✓，題目問「不屬於」第三型者）。全身性紅斑性狼瘡、類風濕性關節炎皆是免疫複合體沉積於組織（關節滑膜、腎絲球等）引發發炎反應之自體免疫疾病，屬第三型過敏反應之代表疾病（A、B）；血清病（因注射外來血清蛋白產生抗體與抗原結合形成免疫複合體沉積全身）更是第三型過敏反應之經典教科書範例（D）。'},
{n:1012, no:52, subj:'呼吸系統', q:'有關吸入性肺炎之臨床症狀，下列何者須立即處理？', opts:['A.咳出帶血絲（blood-tinged）的痰', 'B.聽診後側肺底出現些許的爆裂音（crackles）', 'C.經兩天的靜脈注射抗生素治療後，仍發燒至 38.6oC', 'D.調高給氧的流速，周邊血氧仍繼續下降且低於 90%'], ans:[3], expl:'本題答案為D。周邊血氧飽和度持續下降且低於90%，代表病人氧合狀況急遽惡化、有嚴重呼吸衰竭之風險，屬於必須「立即」處理之危急徵象，此為本題答案（D✓）。咳出些微血絲痰、肺底些許爆裂音，雖需持續觀察記錄，但單獨出現時多屬吸入性肺炎病程中常見、可先密切監測之表現，尚非立即致命之急迫徵象（A✗、B✗）；使用抗生素治療兩天內仍有發燒屬合理病程（抗生素通常需48～72小時以上才能觀察到明顯退燒反應），此時應持續觀察、必要時重新評估治療方案，但非等同「立即」處理層級之緊急徵象（C✗）。'},
{n:1013, no:53, subj:'呼吸系統', q:'有關張力性氣胸（tension pneumothorax）的臨床表徵，下列何者正確？', opts:['A.吐氣時出現喘鳴音', 'B.單側呼吸音減弱', 'C.單側肋膜積水', 'D.吸氣時單側不正常下陷'], ans:[1], expl:'本題答案為B。張力性氣胸因胸腔內壓力持續累積、患側肺完全塌陷，聽診患側呼吸音會明顯減弱甚至消失，此為本題答案（B✓）。張力性氣胸典型是吸氣（而非吐氣）時因胸內負壓消失、患側胸廓起伏異常，且喘鳴音（wheezing）並非其典型表現（A✗）；張力性氣胸是「氣體」而非液體積聚於胸膜腔，故非肋膜「積水」（C✗）；縱膈腔因患側壓力上升會被推向「健側」偏移，且患側胸壁因氣體填充應呈現異常「膨脹」而非下陷（D✗）。'},
{n:1014, no:54, subj:'呼吸系統', q:'有關呼吸器出現壓力過低警示（low pressure alarm）之處理，下列何者最適當？', opts:['A.給予抽痰', 'B.檢查所有呼吸器管路的接頭是否鬆脫', 'C.給予鎮靜劑及止痛劑', 'D.安撫病人不要咬住口中的氣管內管'], ans:[1], expl:'本題答案為B。呼吸器壓力過低警示最常見原因是管路系統「漏氣」（如接頭鬆脫、套囊漏氣、迴路脫落），故應優先全面檢查呼吸器管路各接頭是否鬆脫或斷開連接，此為本題答案（B✓，最適當處置）。抽痰是處理「痰液堵塞、壓力過高警示」時的處置，與壓力過低情境不符（A✗）；給予鎮靜止痛劑或安撫病人不要咬管，較適用於病人躁動、人機不同步或高壓力警示等情境，並非壓力過低警示的第一線處置（C✗、D✗）。'},
{n:1015, no:55, subj:'呼吸系統', q:'有關護理師給予氣切造口（tracheostomy）病人抽痰時，下列措施何者最重要？', opts:['A.執行氣切造口護理', 'B.聽診呼吸音', 'C.給予抗焦慮劑', 'D.評估血氧的變化'], ans:[3], expl:'本題答案為D。抽痰過程可能造成病人短暫缺氧，故抽痰前、中、後皆須持續評估病人血氧飽和度變化，是抽痰過程中最重要、須優先確保病人安全的監測項目，此為本題答案（D✓）。氣切造口護理、聽診呼吸音評估痰液狀況、必要時給予抗焦慮劑皆是抽痰照護中可能執行之相關措施，但監測血氧變化以確保病人安全是抽痰當下最核心、最優先之重要措施（A✗、B✗、C✗）。'},
{n:1016, no:56, subj:'呼吸系統', q:'下列動脈血液氣體分析的報告，何者最能顯示慢性阻塞性肺疾病（COPD）病人的情況惡化？', opts:['A.pH 7.30，PaCO2 60 mmHg，PaO2 70 mmHg，HCO3- 30 mEq/L', 'B.pH 7.38，PaCO2 45 mmHg，PaO2 88 mmHg，HCO3- 24 mEq/L', 'C.pH 7.40，PaCO2 40 mmHg，PaO2 94 mmHg，HCO3- 22 mEq/L', 'D.pH 7.55，PaCO2 30 mmHg，PaO2 80 mmHg，HCO3- 26 mEq/L'], ans:[0], expl:'本題答案為A。選項A（pH 7.30、PaCO2 60 mmHg、PaO2 70 mmHg、HCO3⁻ 30 mEq/L）呈現pH已低於正常下限（酸血症）、PaCO2明顯升高、HCO3⁻代償性上升但仍不足以完全代償，屬於「急性合併於慢性」呼吸性酸中毒之失代償表現，加上PaO2偏低顯示合併低血氧，最能反映COPD病人病情「惡化」的動脈血液氣體分析結果，為本題答案（A✓）。選項B、C數值皆大致落於正常或接近正常範圍，顯示氣體交換功能穩定，並非病情惡化之表現（B✗、C✗）；選項D（pH 7.55、PaCO2 30 mmHg）呈現「呼吸性鹼中毒」型態（換氣過度、CO2排出過多），與COPD典型因換氣不足導致CO2蓄積、呼吸性酸中毒的病情惡化模式並不相符（D✗）。'},
{n:1017, no:57, subj:'呼吸系統', q:'一位被診斷為「疑似細菌性肺炎」的病人剛入院，最優先執行下列那一個醫囑？', opts:['A.給與靜脈輸液 1,000 mL 0.9% Saline', 'B.給與抗生素 Ceftriaxone 1 gm IVF 60 minutes', 'C.收集尿液標本送尿液分析', 'D.收集痰液標本送培養檢驗'], ans:[3], expl:'本題答案為D。懷疑細菌性肺炎的病人，應把握在「使用抗生素之前」先留取痰液標本送培養檢驗，以利正確辨識致病菌並提供後續抗生素調整之依據，一旦抗生素已投予，可能影響培養結果之準確性，故此應為入院後最優先執行之醫囑，為本題答案（D✓）。給予靜脈輸液、收集尿液標本雖也是入院常規處置，但並非疑似細菌性肺炎最優先須搶在用藥前完成之關鍵步驟（A✗、C✗）；給予抗生素治療雖重要且不應延遲，但應「先」留取痰液培養檢體再給藥，以避免培養結果受抗生素影響而失準，故給藥順序應在留痰之後（B✗）。'},
{n:1018, no:58, subj:'呼吸系統', q:'李同學在打籃球時突然感到左胸尖銳疼痛到急診求治，護理師視診發現李同學的左側胸部起伏較小，且氣管偏向右側，聽診發現左側肺部呼吸音減弱、叩診左側肺部出現過度反響音，此時李同學最可能發生下列何種情形？', opts:['A.槤枷胸', 'B.氣胸', 'C.肺炎', 'D.肺栓塞'], ans:[1], expl:'本題答案為B。單側胸部起伏減小、氣管偏向健側（右側）、患側（左側）呼吸音減弱、患側叩診呈現「過度反響音（hyperresonance，因胸膜腔內積氣使叩診音較正常更空洞）」，是氣胸（尤其張力性氣胸伴縱膈腔偏移）的典型臨床表現，與本題描述最相符，為本題答案（B✓）。連枷胸主要特徵為反常胸壁運動（矛盾呼吸），較非以氣管偏移及過度反響音為主要表現（A✗）；肺炎典型聽診為囉音或濕囉音，叩診多呈現濁音（因肺實質病變或肺泡積液），而非過度反響音（C✗）；肺栓塞典型表現為突發性胸痛、呼吸困難、心搏過速，較不會有氣管偏移及單側過度反響音之局部理學徵象（D✗）。'},
{n:1019, no:59, subj:'呼吸系統', q:'下列何種疾病會出現奇異性呼吸（paradoxical respiration）？', opts:['A.張力性氣胸', 'B.槤枷胸', 'C.急性呼吸衰竭', 'D.肺高壓症'], ans:[1], expl:'本題答案為B。連枷胸（flail chest）因多根肋骨多處骨折造成局部胸壁失去骨骼支撐之完整性，吸氣時該處胸壁因胸內負壓反而向內凹陷、吐氣時則向外突出，與正常胸廓運動方向相反，形成典型的「奇異性呼吸（矛盾呼吸）」，此為本題答案（B✓）。張力性氣胸主要表現為患側胸壁固定性膨脹及氣管偏移，而非局部胸壁反常運動（A✗）；急性呼吸衰竭主要以血氧、二氧化碳異常及呼吸型態改變（如呼吸過速、輔助肌使用）為表現，並非以奇異性呼吸為特徵性徵象（C✗）；肺高壓症主要影響右心負荷及肺循環壓力，與胸壁力學異常之奇異性呼吸機轉無關（D✗）。'},
{n:1020, no:60, subj:'泌尿系統', q:'有關膀胱癌的敘述，下列何者錯誤？', opts:['A.初期最常見的症狀是無痛性間歇或持續血尿', 'B.好發於膀胱外側壁、膀胱三角，以泌尿上皮癌最多', 'C.橡膠製造業、美髮業與吸菸者都是高危險族群', 'D.以腎臟與淋巴轉移最為常見，主要轉移到胸腔淋巴結'], ans:[3], expl:'本題答案為D。膀胱癌轉移途徑主要經由淋巴系統轉移至「骨盆腔區域淋巴結（如閉孔、髂骨淋巴結）」，其後可能經血行轉移至肝臟、肺臟、骨骼等遠處器官，並非以「腎臟」為常見轉移標的，亦非主要轉移到「胸腔淋巴結」，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。無痛性間歇或持續血尿確為膀胱癌最常見、最典型的初期症狀，敘述正確（A✓）；膀胱癌好發於膀胱三角區及外側壁，組織型態以泌尿上皮癌（移形上皮癌）佔絕大多數（約90%以上），敘述正確（B✓）；長期接觸芳香胺類化學物質（如橡膠、染料、美髮業從業人員常接觸）及吸菸皆是膀胱癌明確之高危險因子，敘述正確（C✓）。'},
{n:1021, no:61, subj:'泌尿系統', q:'有關壓力性尿失禁的治療與照護，下列何者錯誤？', opts:['A.肥胖者要接受飲食療法來適當減輕體重，以減少腹壓', 'B.透過骨盆底肌肉運動強化肌肉功能，協助關閉尿道口', 'C.限制每天水分攝取量並配合排尿計畫，執行膀胱訓練', 'D.使用 α-腎上腺致效劑，增加尿道出口阻力'], ans:[2], expl:'本題答案為C。壓力性尿失禁主要是骨盆底肌肉及尿道括約肌支撐力不足所致，其治療照護重點在強化骨盆底肌力、控制體重以減少腹壓，並非以「限制水分攝取」為主要治療原則（過度限水反而可能使尿液濃縮刺激膀胱、無助於改善漏尿問題，且膀胱訓練更適用於「急迫性」尿失禁而非壓力性尿失禁），此敘述有誤，為本題答案（C✗，題目問「何者錯誤」）。減輕體重可降低腹內壓力進而減少漏尿情形，敘述正確（A✓）；凱格爾運動（骨盆底肌肉運動）是壓力性尿失禁的核心非藥物治療方法，敘述正確（B✓）；α-腎上腺素致效劑可增加尿道內括約肌張力、提高尿道出口阻力，是可用於壓力性尿失禁的藥物選擇之一，敘述正確（D✓）。'},
{n:1022, no:62, subj:'泌尿系統', q:'有關導致腎病症候群病人全身水腫之病理機轉，下列何者正確？', opts:['A.因鈉離子滯留導致血管內靜力壓上升', 'B.因腎上腺功能不足而使醛固酮（aldosterone）分泌減少', 'C.腎絲球過濾率下降導致水分滯留', 'D.腎絲球通透性增加使蛋白質流失而導致白蛋白減少'], ans:[3], expl:'本題答案為D。腎病症候群因腎絲球基底膜通透性異常增加，導致大量蛋白質（尤其白蛋白）自尿液流失，血中白蛋白濃度下降造成血漿膠體滲透壓降低，水分因而滲漏至組織間隙形成全身水腫，此為本題答案（D✓）。腎病症候群水腫的核心機轉是「低白蛋白血症使膠體滲透壓下降」，而非單純鈉滯留造成血管內靜水壓上升（A✗，此較符合腎絲球腎炎或心衰竭水腫之機轉）；腎病症候群因血管內容積相對不足，實際上會「刺激」腎素—血管收縮素—醛固酮系統，使醛固酮分泌「增加」（而非因腎上腺功能不足而減少）以代償性瀦留鈉水，加重水腫（B✗）；腎病症候群之腎絲球過濾率初期可能仍正常或僅輕微下降，其水腫機轉並非以腎絲球過濾率下降為主因（C✗）。'},
{n:1023, no:63, subj:'泌尿系統', q:'有關腎病症候群病人之診斷性檢查之典型發現，下列何者正確？①血尿 ②菌尿 ③蛋白尿 ④血清白蛋白濃度下降 ⑤血糖上升 ⑥血清膽固醇上升 ⑦血清三酸甘油酯上升 ⑧血清鈣上升', opts:['A.①②④⑧', 'B.①⑤⑥⑧', 'C.②③⑤⑦', 'D.③④⑥⑦'], ans:[3], expl:'本題答案為D。腎病症候群典型診斷特徵包括大量蛋白尿（③）、因白蛋白流失導致血清白蛋白濃度下降（④）、肝臟代償性合成脂蛋白增加造成血清膽固醇上升（⑥）及三酸甘油酯上升（⑦），選③④⑥⑦＝D（本題答案）。血尿（①）、菌尿（②）並非腎病症候群之典型特徵（較常見於腎絲球腎炎或泌尿道感染）；因大量蛋白質流失，體重可能減輕、營養狀況受影響，血糖上升（⑤）及血清鈣上升（⑧）並非其典型診斷發現（腎病症候群反因維生素D結合蛋白流失，實際上較常合併「低血鈣」傾向）。'},
{n:1024, no:64, subj:'泌尿系統', q:'關於膀胱癌接受膀胱切除及輸尿管造瘻術術後病人之護理措施，下列何者不適當？', opts:['A.教導病人及照顧者觀察造瘻口之顏色、大小、形狀', 'B.集尿袋尿液達 80%才需排空', 'C.鼓勵每日攝取液體 2,000～3,000 mL', 'D.鼓勵病人表達感受，傾聽病人給予心理支持'], ans:[1], expl:'本題答案為B。集尿袋內尿液累積至約1/3～1/2（約30～50%）即應排空，避免尿液逆流增加感染風險及集尿袋過重造成造瘻口牽扯受損，若等到高達80%才排空並不適當，此敘述錯誤，為本題答案（B✗，題目問「何者不適當」）。教導病人及照顧者觀察造瘻口顏色、大小、形狀變化，有助及早發現造瘻口併發症，敘述適當（A✓）；鼓勵每日攝取足夠液體（2,000～3,000 mL）有助維持尿路通暢、預防感染與結石形成，敘述適當（C✓）；鼓勵病人表達感受並給予心理支持，有助其調適身體形象改變及術後身心適應，敘述適當（D✓）。'},
{n:1025, no:65, subj:'泌尿系統', q:'腎臟肌酸酐清除率（CCr）正常值範圍是多少 mL/min？', opts:['A.25～55', 'B.65～85', 'C.95～135', 'D.145～165'], ans:[2], expl:'本題答案為C。腎臟肌酸酐清除率（CCr）正常參考值範圍一般約為95～135 mL/min（依性別、年齡、肌肉量略有差異，男性略高於女性），此為本題答案（C✓）。25～55、65～85、145～165 mL/min皆非CCr正常參考範圍（A✗、B✗、D✗，65～85 mL/min較接近輕度腎功能不足之範圍）。'},
{n:1026, no:66, subj:'泌尿系統', q:'有關腎臟所製造荷爾蒙的生理功能，下列何者正確？', opts:['A.前列腺素（prostagalndins）有抑制抗利尿荷爾蒙（ADH）的作用', 'B.抗利尿荷爾蒙（ADH）可增加遠曲小管及集尿管的水分再吸收', 'C.活化維生素 D 可抑制腸道對鈣的吸收及加速鈣的排除', 'D.腎素（rennin）在血壓上升時會刺激分泌以加速水分排除'], ans:[0], expl:'本題答案為A。本題問的是「腎臟所製造」之荷爾蒙生理功能：腎臟本身可製造前列腺素（prostaglandins），其作用之一即在集尿管處「拮抗（抑制）」抗利尿荷爾蒙（ADH）的水分再吸收效果，此為腎臟利尿及調節局部血流的重要保護機轉（臨床上使用NSAIDs抑制前列腺素合成時，會使ADH作用相對增強、增加水分滯留風險，即為此機轉之反向印證），此為本題答案（A✓）。ADH雖可增加遠曲小管及集尿管對水分之再吸收，此生理作用敘述本身正確，但ADH是由「下視丘製造、腦下垂體後葉釋放」，腎臟僅是其作用標的器官而非製造來源，並不屬於「腎臟所製造」之荷爾蒙，故不符合本題題幹所問之範疇（B✗）；活化型維生素D（calcitriol）之生理作用是「促進」腸道對鈣質的吸收，並「減少」腎臟對鈣的排除（增加腎小管鈣再吸收），與C選項所述之方向恰好相反（C✗）；腎素（renin）是在血壓「下降」或腎臟血流灌注不足時受刺激分泌，進而活化腎素—血管收縮素—醛固酮系統以達到「保鈉保水、升高」血壓之效果，並非血壓上升時分泌以加速排水，方向亦與D選項相反（D✗）。'},
{n:1027, no:67, subj:'泌尿系統', q:'關於持續可攜帶式腹膜透析（CAPD）與血液透析（HD）治療的比較，下列何者正確？', opts:['A.CAPD 治療需要較嚴格的飲食控制', 'B.CAPD 需擔負較多的自我照顧活動', 'C.CAPD 易出現頭痛、噁心、嘔吐、低血壓症候群', 'D.CAPD 對心臟血管方面的影響較大'], ans:[1], expl:'本題答案為B。持續可攜帶式腹膜透析（CAPD）需病人或照顧者自行每日在家執行多次換液操作，自我照顧與居家管理負擔相對「較高」，此為本題答案（B✓）。相較於血液透析，CAPD透析過程緩慢連續進行，飲食與水分限制通常「較為寬鬆」，而非需要更嚴格的飲食控制（A✗）；透析不平衡症候群（因短時間內快速移除溶質導致頭痛、噁心、嘔吐、低血壓等）主要是「血液透析」的特徵性併發症，並非CAPD之典型表現（C✗）；CAPD因採緩慢連續方式移除水分及廢物，血液動力學相對穩定，對心臟血管系統的衝擊「較小」，而非較大（D✗）。'},
{n:1028, no:68, subj:'內分泌系統', q:'有關庫欣氏症候群症狀（Cushing’s syndrome）之病理機轉，下列何者正確？', opts:['A.軀幹性肥胖：糖皮質素對脂肪和蛋白質代謝影響所導致', 'B.高血壓：降低礦物皮質醇活化，導致水分與鈉離子滯留', 'C.免疫受抑制：白血球增多，抑制單核球作用與淋巴球下降', 'D.高血糖：肝臟糖質新生作用降低，胰島素利用增加所導致'], ans:[2], expl:'本題答案為C。庫欣氏症候群因長期皮質醇過高，會抑制免疫系統功能：促使嗜中性白血球自邊緣池釋放入循環（造成整體白血球數目上升，即「白血球增多」）、同時抑制單核球（巨噬細胞）之吞噬與抗原呈現功能，並使淋巴球數目下降（淋巴球減少），整體呈現免疫功能受抑制的狀態，此為本題答案（C✓）。軀幹性肥胖主要是皮質醇促使周邊脂肪分解、卻在軀幹部位重新堆積，並加速蛋白質分解代謝所致，其機轉描述方向大致正確，惟A選項本身敘述較為簡化籠統，本題以C選項對免疫抑制機轉之描述最為具體且完整對應庫欣氏症候群的病理生理（A為部分正確但非本題最佳答案）；皮質醇具類礦物皮質素作用，會使腎臟「保鈉排鉀」作用「增加」（而非降低礦物皮質醇活化），導致水鈉滯留而血壓上升，此描述方向有誤（B✗）；皮質醇會「促進」肝臟糖質新生作用並降低周邊組織對胰島素的利用（產生胰島素阻抗），進而導致血糖上升，此描述方向與機轉皆有誤（D✗）。'},
{n:1029, no:69, subj:'內分泌系統', q:'下列何種荷爾蒙分泌不足會導致黏液性水腫（myxedema）？', opts:['A.生長激素（GH）', 'B.甲狀腺激素（TSH）', 'C.腎上腺皮質素（ACTH）', 'D.性腺激素（LH 及 FSH）'], ans:[1], expl:'本題答案為B。甲狀腺功能低下（甲狀腺激素分泌不足）會導致體內代謝速率下降、黏多醣類物質堆積於皮下組織，造成非凹陷性水腫外觀，稱為黏液性水腫（myxedema），此為本題答案（B✓，此處「甲狀腺激素」對應題幹所指促使甲狀腺分泌之機轉，為導致黏液性水腫之關鍵荷爾蒙不足）。生長激素、腎上腺皮質素、性腺激素（LH、FSH）分泌不足雖也會造成各自相對應之內分泌症候群（如生長遲緩、愛迪生氏病、性腺功能低下等），但皆非導致黏液性水腫之直接原因（A✗、C✗、D✗）。'},
{n:1030, no:70, subj:'內分泌系統', q:'有關副甲狀腺功能低下病人之處置與護理，下列何者正確？', opts:['A.急性期給予口服 10% calcium gluconate', 'B.手足抽搐時，注射重碳酸鹽或磷酸鹽，以迅速增加血鈣濃度', 'C.床旁放置氣切包、氣管內管、喉頭鏡等物備用', 'D.鼓勵攝取乳酪、奶類製品、蛋黃、花椰菜'], ans:[2], expl:'本題答案為C。副甲狀腺功能低下病人因血鈣過低易發生喉部痙攣導致呼吸道阻塞之緊急狀況，應於床旁備妥氣切包、氣管內管、喉頭鏡等急救物品以備不時之需，此為本題答案（C✓）。急性低血鈣危象應以「靜脈注射」10% calcium gluconate緊急處理（而非口服，口服吸收太慢無法應付急性抽搐危象），此敘述有誤（A✗）；手足抽搐等急性低血鈣症狀應以「靜脈注射鈣劑」（如calcium gluconate）快速提升血鈣，而非注射重碳酸鹽或磷酸鹽（磷酸鹽反而會與鈣結合、更降低游離鈣濃度，加重低血鈣），此敘述有誤（B✗）；副甲狀腺功能低下病人應「限制」高磷食物攝取（乳酪、奶製品、蛋黃等含磷量高的食物會加重高血磷、低血鈣），而非鼓勵攝取，此敘述有誤（D✗）。'},
{n:1031, no:71, subj:'內分泌系統', q:'有關低血糖的敘述，下列何者正確？', opts:['A.常因急性感染或重大壓力所致', 'B.易發生在餐後或胰島素作用的高峰時間', 'C.與糖尿病酮酸中毒相比，其危險性較低', 'D.可能出現出汗、震顫、心跳過快'], ans:[3], expl:'本題答案為D。低血糖時因腎上腺素等交感神經反應性分泌增加，病人常出現冒冷汗、手部震顫、心跳加快等自主神經興奮症狀，此為本題答案（D✓）。低血糖較常發生於「藥物過量、進食不足、運動過度」等情境，並非典型因急性感染或重大身心壓力所誘發（急性感染或壓力狀態通常反而使血糖「上升」，增加胰島素阻抗）（A✗）；低血糖好發於「未進食（空腹）」或胰島素藥效達高峰時，而非「餐後」（餐後血糖通常上升）（B✗）；低血糖若未及時處理可能快速進展為意識喪失、癲癇甚至腦部損傷，其急性致命風險並不亞於糖尿病酮酸中毒，並非危險性較低（C✗）。'},
{n:1032, no:72, subj:'內分泌系統', q:'有關糖尿病的敘述，下列何者正確？', opts:['A.第一型糖尿病病人體內會出現胰島細胞抗體（islet cell antibody；ICA）', 'B.第一型糖尿病病人仍保有分泌胰島素能力，只是不足以供應身體所需', 'C.第二型糖尿病易發生酮酸血症的急性合併症', 'D.第二型糖尿病多發生於成年期，需終身依賴胰島素治療'], ans:[0], expl:'本題答案為A。第一型糖尿病主要致病機轉為自體免疫破壞胰島β細胞，病人血中常可測得胰島細胞抗體（ICA）等自體抗體，此為本題答案（A✓）。第一型糖尿病因胰島β細胞遭破壞，體內幾乎「完全喪失」胰島素分泌能力，需終身依賴胰島素治療，並非仍保有足夠分泌能力（B✗）；第二型糖尿病因體內仍有基礎胰島素分泌，通常「較不易」發生酮酸血症（易發生酮酸血症為第一型糖尿病之特徵，第二型較易發生的急性合併症為高血糖高滲透壓狀態）（C✗）；第二型糖尿病雖多發生於成年期，但初期治療多以飲食、運動及口服降血糖藥物為主，並非人人皆需終身依賴胰島素治療（僅部分病程進展後可能需要胰島素）（D✗）。'},
{n:1033, no:73, subj:'內分泌系統', q:'下列何者為高血糖高滲透壓狀態（HHS）病人出現脫水的最常見原因？', opts:['A.噁心、嘔吐', 'B.缺乏抗利尿激素', 'C.腎臟無法濃縮尿液', 'D.高血糖造成滲透壓性利尿'], ans:[3], expl:'本題答案為D。高血糖高滲透壓狀態（HHS）病人脫水最主要成因是嚴重高血糖超過腎臟回收閾值，導致大量葡萄糖隨尿液排出時產生滲透性利尿作用，帶走大量水分造成嚴重脫水，此為本題答案（D✓）。噁心嘔吐、抗利尿激素缺乏（此為尿崩症之機轉）、腎臟濃縮功能受損雖也可能造成或加重體液流失，但皆非HHS病人脫水之「最常見」根本原因，其核心機轉仍是高血糖引發的滲透性利尿（A✗、B✗、C✗）。'},
{n:1034, no:74, subj:'內分泌系統', q:'有關糖尿病酮酸中毒（DKA）病人之檢驗結果，下列何者正確？①動脈血氧分析 pH 7.2 ②動脈血氧分析 pH 7.5 ③血中碳酸根離子濃度 14 mEq/L ④血中碳酸根離子濃度 25 mEq/L ⑤血清滲透壓>320 mOsm/kg ⑥血清滲透壓<320 mOsm/kg', opts:['A.①③⑥', 'B.①④⑥', 'C.②③⑤', 'D.②④⑤'], ans:[0, 1, 2, 3], expl:'本題官方公告「一律給分」（附於測驗題標準答案更正之備註），故四個選項皆列為正確答案，不再提供單一標準答案。依美國糖尿病學會（ADA）診斷準則，典型糖尿病酮酸中毒（DKA）之檢驗特徵為代謝性酸中毒：動脈血液pH<7.3、血中碳酸氫根（HCO3⁻）<18 mEq/L，且血清滲透壓通常「未達」高血糖高滲透壓狀態（HHS）所定義之顯著上升程度（HHS診斷門檻通常為有效血清滲透壓>300～320 mOsm/kg），故若採最典型教科書描述，①（pH 7.2）＋③（HCO3⁻ 14 mEq/L）＋⑥（血清滲透壓<320 mOsm/kg）之組合（選項A）最符合單純DKA之典型檢驗圖像。惟臨床上嚴重DKA病人因高血糖與脫水程度不同，血清滲透壓仍可能明顯上升甚至超過320 mOsm/kg，且DKA與HHS兩者於嚴重脫水、電解質失衡時可能出現重疊或混合型表現（overlap syndrome），加上不同教科書對DKA血清滲透壓門檻的描述並非完全一致，此命題可能因選項組合方式（pH與HCO3⁻搭配是否具生理一致性、滲透壓數值歸屬DKA或HHS的界線）產生認定上的爭議，故官方最終公告本題不設單一標準答案、全體應考人一律給分。'},
{n:1035, no:75, subj:'內分泌系統', q:'糖尿病病人在下列何種情況下不宜增加胰島素的劑量？', opts:['A.全身感染', 'B.食慾不振', 'C.嚴重外傷', 'D.情緒壓力'], ans:[1], expl:'本題答案為B。食慾不振、進食量減少時，若仍維持原有或增加胰島素劑量，反而容易造成血糖過度下降誘發低血糖，故此情況「不宜增加」胰島素劑量（應視進食狀況調整劑量或諮詢醫療團隊），此為本題答案（B✓，題目問「不宜增加」胰島素劑量之情況）。全身感染、嚴重外傷、情緒壓力皆屬於生理或心理「壓力狀態」，會促使升糖素、腎上腺素、皮質醇等升糖荷爾蒙分泌增加，導致血糖上升、胰島素需求量增加，此時通常需要「增加」而非減少胰島素劑量以維持血糖穩定（A、C、D）。'},
{n:1036, no:76, subj:'其他', q:'有關「臺灣急診檢傷與急迫度分級量表」（TTAS）的敘述，下列何者正確？', opts:['A.復甦急救等級：每 10 分鐘評估一次', 'B.非緊急等級：每 120 分鐘評估一次', 'C.緊急等級是屬於第二級', 'D.緊急等級：每 90 分鐘評估一次'], ans:[1], expl:'本題答案為B。依據衛生福利部公告之「臺灣急診檢傷與急迫度分級量表（TTAS）」，第五級「非緊急」病人建議之再評估等候時間為每120分鐘一次，此為本題答案（B✓）。第一級「復甦急救」應「立即」處置，並非以「每10分鐘評估一次」之等候概念呈現（10分鐘為第二級「危急」病人建議之再評估時間）（A✗）；「緊急」為TTAS分級中的「第三級」，而非第二級（第二級為「危急」），此敘述有誤（C✗）；「緊急（第三級）」病人建議再評估等候時間為每30分鐘一次，而非90分鐘（D✗）。'},
{n:1037, no:77, subj:'其他', q:'有關敗血症生理病理機轉之敘述，下列何者正確？', opts:['A.細菌感染引發腫瘤壞死因子活化產生微小血栓', 'B.敗血症會造成循環血量大量流失', 'C.敗血症休克時，可能引發尿量增加', 'D.敗血症休克時，因心臟受刺激出現血壓上升'], ans:[0], expl:'本題答案為A。敗血症時細菌內毒素等致病因子活化發炎反應及凝血系統，促使腫瘤壞死因子（TNF-α）等發炎介質大量釋放，並可能誘發瀰漫性血管內凝血、於微血管內形成微小血栓，此為本題答案（A✓）。敗血性休克屬於「分布性休克」，其核心問題是血管異常擴張、通透性增加使血漿滲漏至組織間隙，造成「有效」循環血量不足，並非血液大量流失出體外（B✗，此描述較符合低血容積性休克機轉）；敗血性休克因有效循環血量不足、腎臟灌流下降，通常會出現「尿量減少」而非增加（C✗）；敗血性休克因血管擴張、有效循環血量不足及心肌抑制物質釋放，通常會導致「血壓下降」而非上升（D✗）。'},
{n:1038, no:78, subj:'其他', q:'下列何種情況之病人不適合接受低張靜脈溶液輸注？', opts:['A.尿崩症', 'B.顱內創傷造成顱內壓上升', 'C.高血糖高滲透壓非酮酸性昏迷', 'D.輸液治療造成之細胞內脫水'], ans:[1], expl:'本題答案為B。顱內創傷導致顱內壓上升時，若輸注低張（低滲透壓）靜脈溶液，會使血漿滲透壓下降，促使水分順滲透梯度移向腦細胞內，可能加重腦水腫、使顱內壓進一步惡化，故此類病人應避免使用低張溶液，此為本題答案（B✓，題目問「不適合」接受低張溶液者）。尿崩症因大量水分流失導致高血鈉、細胞內脫水，臨床上常需以低張溶液（如0.45%生理食鹽水或D5W）補充自由水以矯正高滲狀態，屬適合使用情境（A✗）；高血糖高滲透壓非酮酸性昏迷（HHS）病人在初期以等張溶液穩定血液動力學後，若矯正後血鈉偏高，後續常需使用低張溶液補充體內自由水缺失，屬適合使用情境之一（C✗）；輸液治療造成之細胞內脫水（如高張性脫水），本身即是低張溶液的適應症，用以補充自由水、使水分移入細胞內矯正細胞內脫水（D✗）。'},
{n:1039, no:79, subj:'其他', q:'有關有機磷農藥之敘述，下列何者錯誤？', opts:['A.進入病人體內的途徑包括吸入、攝食及皮膚吸收', 'B.會與體內之乙醯膽鹼酶（AChE）結合，最終導致神經麻痺', 'C.目前尚無拮抗劑可使用', 'D.進入病人體內會造成呼吸抑制及呼吸道分泌物增加'], ans:[2], expl:'本題答案為C。有機磷中毒目前「已有」明確拮抗劑可供治療，包括atropine（阻斷過度之膽鹼激性作用）及pralidoxime（2-PAM，可使被有機磷結合之乙醯膽鹼酶再活化），並非無藥可用，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。有機磷農藥可經由吸入、口服攝食及皮膚接觸等多重途徑進入人體，敘述正確（A✓）；有機磷會與乙醯膽鹼酶不可逆結合並抑制其活性，使乙醯膽鹼於突觸處過度堆積，最終造成神經肌肉接合處持續過度刺激而麻痺，敘述正確（B✓）；有機磷中毒因膽鹼激性作用過度興奮，會造成支氣管收縮、分泌物增加及呼吸肌麻痺，導致呼吸抑制與呼吸道分泌物增加，敘述正確（D✓）。'},
{n:1040, no:80, subj:'其他', q:'有關手部衛生之敘述，下列何者錯誤？', opts:['A.是預防醫療照護相關感染最簡單、最有效且最合乎成本效益的方法', 'B.一般手部衛生的目的是去除手部污垢及有效的降低皮膚上固有性菌叢的數量', 'C.在接觸或執行照護活動之前洗手，是為了降低微生物傳遞給病人的風險', 'D.接觸或暴露病人體液之後洗手，是為了降低將微生物傳遞給醫療人員和照護區的風險'], ans:[1], expl:'本題答案為B。一般性手部衛生（如濕洗手或乾洗手）之目的主要在「有效降低」手部暫時性（外來污染）菌叢的數量，對於皮膚上原本「固有性（常在）菌叢」則不需（也難以）完全去除，過度強調降低固有菌叢的量並非其主要目的，此敘述有誤，為本題答案（B✗，題目問「何者錯誤」）。手部衛生被公認是預防醫療照護相關感染最簡單、最有效、也最符合成本效益的措施，敘述正確（A✓）；接觸病人或執行照護處置前洗手，可降低醫護人員手部病原菌傳遞給病人的風險，敘述正確（C✓）；接觸病人體液後洗手，可降低病原菌傳遞給醫護人員本身及照護環境（造成交叉感染）的風險，敘述正確（D✓）。'},{n:1041, no:1, subj:'神經系統', q:'有關測量病人昏迷量表（Glasgow Coma Scale, GCS）之敘述，下列何者錯誤？', opts:['A.低於 7 分表示昏迷狀態', 'B.運動反應是以病人最差的反應作為紀錄', 'C.語言反應時，有插氣管內管者用“E”表示', 'D.張眼反應時，因顏面受傷造成眼部水腫以致無法張開眼睛時用“C”表示'], ans:[1], expl:'本題答案為B。昏迷指數（GCS）運動反應（Motor response）評分時，應以病人「最佳」（而非最差）的反應作為紀錄依據，以避免低估病人實際的意識與神經功能狀態，此敘述有誤，為本題答案（B✗，題目問「何者錯誤」）。GCS總分低於7分即符合昏迷（coma）的定義，敘述正確（A✓）；語言反應評估時，若病人因插有氣管內管而無法發出聲音，依慣例以「E（endotracheal tube）」註記，敘述正確（C✓）；張眼反應評估時，若因顏面外傷腫脹導致眼睛無法張開，依慣例以「C（closed）」註記，敘述正確（D✓）。'},
{n:1042, no:2, subj:'神經系統', q:'有關正子電腦斷層攝影術（Positron Emission Tomography, PET）的敘述，下列何者正確？', opts:['A.可測得腦血流灌流的狀況', 'B.是一種侵入性的核子醫學造影檢查', 'C.是頭部外傷病人最常用的檢查', 'D.可測得腦部的代謝活動狀況'], ans:[3], expl:'本題答案為D。正子電腦斷層攝影（PET）利用微量放射性同位素標記葡萄糖等代謝物質，可測得腦部組織的葡萄糖代謝活性，反映腦部功能狀態，此為本題答案（D✓）。PET主要反映「代謝」而非直接測量腦血流灌流（腦血流灌流評估較常用SPECT等其他核醫檢查）（A✗）；PET雖屬核子醫學造影，但為「非侵入性」（僅需靜脈注射微量顯影劑）之影像檢查，並非侵入性檢查（B✗）；頭部外傷病人最常用的影像檢查是電腦斷層（CT），並非PET（PET較常用於腫瘤、癲癇病灶定位、失智症評估等）（C✗）。'},
{n:1043, no:3, subj:'神經系統', q:'有關顱內壓升高的治療，下列何者錯誤？', opts:['A.建議使用輕微高張溶液如 5%葡萄糖 0.45%生理食鹽水（D5 1/2S）', 'B.可利用巴比妥酸鹽降低腦部的新陳代謝率', 'C.使用 Mannitol 或 Glycerol 應注意體液電解質平衡', 'D.若顱內壓升高情況已改善，應立即停用降腦壓藥物'], ans:[3], expl:'本題答案為D。若顱內壓升高情況已獲改善，降腦壓藥物（如滲透性利尿劑）應「漸進式減量」停藥，以避免因驟然停藥造成體液滲透梯度反轉，引發顱內壓反彈上升的「回躍現象」，故不可「立即」停用，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。臨床上可考慮使用如D5 1/2S等輕微高張溶液以避免加重腦水腫，敘述正確（A✓）；巴比妥酸鹽（如Pentobarbital）可降低腦部代謝率、減少腦血流及顱內壓，用於難治性顱內高壓，敘述正確（B✓）；使用Mannitol或Glycerol等滲透性利尿劑時，須密切監測體液及電解質平衡，以避免脫水或電解質失衡，敘述正確（C✓）。'},
{n:1044, no:4, subj:'神經系統', q:'有關脊髓損傷所引起的神經性膀胱之敘述，下列何者正確？', opts:['A.下運動神經元神經性膀胱之排尿反射中樞是完整的', 'B.下運動神經元神經性膀胱訓練時可利用反射來排尿', 'C.上運動神經元神經性膀胱病人可以敲恥骨上緣或刺激肛門以誘發排尿', 'D.上運動神經元神經性膀胱的病人常發生腎臟合併症'], ans:[2], expl:'本題答案為C。上運動神經元神經性膀胱（如脊髓損傷平面以上，但薦髓排尿反射弧完整）病人，可利用敲擊恥骨上緣、刺激肛門或大腿內側等方式誘發反射性排尿，此為本題答案（C✓）。下運動神經元神經性膀胱因薦髓排尿反射中樞（S2-S4）本身受損，排尿反射弧「不完整」，敘述錯誤（A✗）；正因反射弧不完整，下運動神經元神經性膀胱「無法」單純利用反射誘發排尿，需仰賴其他方式（如Valsalva手法、間歇導尿）協助排空，敘述錯誤（B✗）；因排尿反射弧完整、膀胱壓力控制相對較佳，上運動神經元神經性膀胱較「不易」發生腎臟合併症；反倒是下運動神經元神經性膀胱因膀胱張力不足、殘尿量多，較易併發泌尿道感染及腎臟損傷，此敘述方向有誤（D✗）。'},
{n:1045, no:5, subj:'神經系統', q:'病人癲癇發作，意識不清的護理措施，下列何者正確？', opts:['A.拉起床欄並將病人約束', 'B.由嘴角放入抗癲癇藥物', 'C.採平臥頭側向一邊', 'D.給予刺激以喚醒病人'], ans:[2], expl:'本題答案為C。癲癇發作時應協助病人採「側臥」姿勢並將頭側向一邊，以利口腔分泌物或嘔吐物流出，避免吸入性嗆咳或呼吸道阻塞，此為本題答案（C✓）。發作時「不應」強行約束病人肢體，以免造成肌肉骨骼損傷（A✗）；發作時「不可」在病人口中放置任何物品（包含藥物、壓舌板），以免造成牙齒斷裂、誤吸或咬傷施救者，且發作當下經口給藥並無意義（B✗）；發作時病人意識不清，不應嘗試強行喚醒或搖晃刺激病人，應保護病人安全並記錄發作情形，等待其自然恢復意識（D✗）。'},
{n:1046, no:6, subj:'神經系統', q:'病人突然左側肢體無力，由家屬送入急診，目前肌肉力量右側肢體 5 分、左手 3 分、左腳 1 分，請問最有可能是那一條腦血管的阻塞？', opts:['A.右邊的大腦前動脈', 'B.右邊的大腦中動脈', 'C.左邊的大腦前動脈', 'D.左邊的大腦中動脈'], ans:[0], expl:'本題答案為A。肌肉力量分布為右側肢體正常（5分）、左側肢體明顯無力（左手3分、左腳1分，且左腳較左手更弱），此型態符合「右側大腦前動脈」阻塞的臨床表現：大腦前動脈主要供應大腦內側面（旁中央小葉），負責對側下肢的運動控制，故其阻塞會造成對側「下肢重於上肢」的無力型態，與本題描述最相符，為本題答案（A✓）。大腦中動脈阻塞則多造成對側「上肢及顏面重於下肢」的無力型態（與本題型態相反），故右側或左側大腦中動脈阻塞皆不符合本題描述（B✗、D✗）；左邊大腦前動脈阻塞應造成「右側」下肢為主的無力，與本題左側肢體無力的描述不符（C✗）。'},
{n:1047, no:7, subj:'神經系統', q:'有關阿茲海默氏症的敘述，下列何者錯誤？', opts:['A.是慢性、可逆性的腦部退化疾病', 'B.基因遺傳是可能的病因', 'C.有記憶力減退的症狀', 'D.NMDA 受體拮抗劑可以改善大腦功能'], ans:[0], expl:'本題答案為A。阿茲海默氏症是一種慢性、「不可逆」的原發性腦部退化性疾病，此敘述有誤，為本題答案（A✗，題目問「何者錯誤」）。目前研究顯示基因遺傳（如APOE ε4基因）是阿茲海默氏症可能的危險因子之一，敘述正確（B✓）；記憶力減退（尤其近期記憶）是阿茲海默氏症最核心的臨床症狀，敘述正確（C✓）；NMDA受體拮抗劑（如Memantine）可調節麩胺酸神經傳導、延緩認知功能惡化，是目前用於中重度阿茲海默氏症的治療藥物之一，敘述正確（D✓）。'},
{n:1048, no:8, subj:'神經系統', q:'有關肌無力症病人發生疑似膽鹼性危象（cholinergic crisis）時的處置，下列何者適當？①增加抗膽鹼酯酶藥物 ②停止使用 Pyridostigmine（Mestinon） ③由靜脈注射 atropine ④由靜脈注射類固醇', opts:['A.①③', 'B.①④', 'C.②③', 'D.②④'], ans:[2], expl:'本題答案為C。膽鹼性危象是因抗膽鹼酯酶藥物（如Mestinon）使用「過量」導致乙醯膽鹼堆積、副交感神經過度興奮所致，故處置應「停止使用Pyridostigmine（Mestinon）」（②）以移除病因，並可由靜脈注射atropine（③）以阻斷過度的膽鹼激性作用、緩解症狀，選②③＝C（本題答案）。膽鹼性危象是藥物「過量」而非不足所致，故不應再「增加」抗膽鹼酯酶藥物劑量，此舉反而會加重病情（①錯誤）；類固醇為肌無力危象（myasthenic crisis，因藥物不足或病情惡化所致）的可能治療考量之一，並非膽鹼性危象的處置方式，兩者致病機轉相反，不可混淆（④錯誤）。'},
{n:1049, no:9, subj:'消化系統', q:'有關預防傾倒症候群的敘述，下列何者正確？', opts:['A.多進食液體', 'B.用餐後需立即散步幫助消化', 'C.採取少量多餐', 'D.採高脂肪、低蛋白、低糖及乾性食物'], ans:[2], expl:'本題答案為C。傾倒症候群是因胃部分切除後，食糜快速大量傾入小腸引起滲透性液體移轉及腸道擴張所致，預防原則包括「少量多餐」以減緩食糜排空速度，此為本題答案（C✓）。應「限制」而非鼓勵大量攝取液體，尤其應避免正餐時同時大量飲用液體，以免加速胃排空（A✗）；用餐後應「平躺休息」20～30分鐘，以延緩食糜排空速度，而非立即起身散步，此敘述方向有誤（B✗）；建議採「高蛋白、高脂肪」（延緩排空）並「限制」（而非採用）高濃度糖類的乾性食物，本選項「低蛋白」的描述方向有誤（D✗）。'},
{n:1050, no:10, subj:'消化系統', q:'有關口腔癌之敘述，下列何者錯誤？', opts:['A.鱗狀細胞癌最常見', 'B.好發舌頭前端 3 分之 1', 'C.會有黏膜白斑症之病灶', 'D.早期最常見的症狀是口腔出現紅斑（Erythroplakia）'], ans:[1], expl:'本題答案為B。口腔癌好發部位以「舌頭側緣及舌根部」為主，並非舌頭前端1/3，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。口腔癌病理型態中「鱗狀細胞癌」佔絕大多數，敘述正確（A✓）；黏膜白斑症（Leukoplakia）是口腔癌常見的癌前病灶表現之一，敘述正確（C✓）；口腔紅斑症（Erythroplakia）雖較少見，但惡性轉化率更高，是口腔癌早期即可能出現的病灶表現，敘述正確（D✓）。'},
{n:1051, no:11, subj:'消化系統', q:'下列何者為食道重建術後最嚴重的合併症？', opts:['A.傷口吻合處滲漏', 'B.吸入性肺炎', 'C.腹瀉', 'D.吞嚥困難'], ans:[0], expl:'本題答案為A。食道重建術後若發生「吻合處滲漏」，腸胃道內容物滲入縱膈腔或胸腔，可迅速引發縱膈腔炎、敗血性休克等致命併發症，是此類手術最嚴重、死亡率最高的合併症，為本題答案（A✓）。吸入性肺炎、腹瀉、吞嚥困難雖也可能發生，但其嚴重度與致命風險皆不若吻合處滲漏來得急迫及嚴重（B✗、C✗、D✗）。'},
{n:1052, no:12, subj:'消化系統', q:'有關肝硬化病人服用 Lactulose 之敘述，下列何者正確？', opts:['A.預防腸道發生感染、壞死', 'B.減少氨及含氮廢物的吸收，產生輕瀉作用', 'C.降低尿液滲透壓，預防肝腎症候群的發生', 'D.降低門脈高壓，減輕腹水'], ans:[1], expl:'本題答案為B。Lactulose是一種不被小腸吸收的雙醣類藥物，於大腸經細菌代謝後產生酸性環境，可將氨（NH3）轉為不易被腸道吸收的銨離子（NH4+），並藉由其滲透性輕瀉作用促進氨及含氮廢物隨糞便排出，減少血氨吸收，是治療肝硬化肝性腦病變的重要藥物，此為本題答案（B✓）。Lactulose並非以預防腸道感染或壞死為主要作用機轉（A✗）；Lactulose主要透過通便作用降低血氨，並非直接作用於腎臟降低尿液滲透壓（C✗）；Lactulose不具直接降低門脈壓力的藥理作用，減輕腹水並非其主要治療目的（D✗）。'},
{n:1053, no:13, subj:'消化系統', q:'有關膽結石引起膽囊炎合併總膽管阻塞病人的糞便顏色，下列何者正確？', opts:['A.黃色', 'B.灰白色', 'C.黑色', 'D.深褐色'], ans:[1], expl:'本題答案為B。總膽管完全阻塞時，膽色素無法隨膽汁排入腸道，糞便因缺乏膽色素著色而呈現「灰白色（陶土色）」，此為本題答案（B✓）。黃色、黑色、深褐色皆非總膽管完全阻塞時的典型糞便顏色表現（A✗、C✗、D✗，黑色糞便較常見於上消化道出血）。'},
{n:1054, no:14, subj:'消化系統', q:'有關橫膈食道裂孔疝氣的臨床表徵，下列何者錯誤？', opts:['A.心口灼熱感', 'B.吞嚥困難', 'C.多在飽餐 1 小時後才出現症狀', 'D.胸頸部、背部出現緊迫感'], ans:[2], expl:'本題答案為C。橫膈食道裂孔疝氣典型症狀多在「飽餐後不久（約30～60分鐘內）」即出現，而非延遲至飽餐1小時後才發作，此敘述時序有誤，為本題答案（C✗，題目問「何者錯誤」）。心口灼熱感（火燒心）是其典型症狀，敘述正確（A✓）；因胃酸逆流刺激食道或疝氣壓迫，可能伴隨吞嚥困難，敘述正確（B✓）；部分病人可能因橫膈刺激或食道痙攣，出現胸頸部、背部緊迫不適感，敘述正確（D✓）。'},
{n:1055, no:15, subj:'消化系統', q:'有關迴腸造口手術後造瘻口的正常顏色，下列何者正確？', opts:['A.黑褐色', 'B.藍紫色', 'C.玫瑰紅', 'D.粉白色'], ans:[2], expl:'本題答案為C。迴腸造口正常黏膜血循良好，外觀應呈現濕潤有光澤的「玫瑰紅色」，此為本題答案（C✓）。造瘻口若呈現黑褐色，提示可能血循不良、缺血壞死，屬異常表現（A✗）；藍紫色同樣提示血循障礙、缺血，屬異常表現（B✗）；粉白色可能提示貧血或血循不足，並非正常造瘻口顏色（D✗）。'},
{n:1056, no:16, subj:'消化系統', q:'有關痔瘡出血手術後之護理措施，下列何者不適當？', opts:['A.立即給予溫水坐浴', 'B.觀察有無尿滯留現象', 'C.建議攝取低渣飲食', 'D.協助採側臥或俯臥'], ans:[0], expl:'本題答案為A。痔瘡手術後傷口疼痛，不應「立即」給予溫水坐浴（術後初期立即坐浴可能增加傷口出血或感染風險，一般建議術後一段時間、依醫囑逐步開始），此敘述之處置時機不適當，為本題答案（A✓，題目問「何者不適當」）。肛門部位疼痛腫脹或麻醉效應可能影響排尿功能，應觀察有無尿滯留現象，屬適當措施（B✗）；為避免刺激傷口、減少排便疼痛，建議採低渣飲食，屬適當措施（C✗）；協助採側臥或俯臥可減輕肛門部位受壓迫及疼痛，屬適當措施（D✗）。'},
{n:1057, no:17, subj:'骨骼肌肉', q:'有關骨髓炎的治療方式，下列何者最為少見？', opts:['A.高壓氧治療', 'B.抗生素治療', 'C.手術療法', 'D.放射線治療'], ans:[3], expl:'本題答案為D。放射線治療並非骨髓炎的常規治療方式（骨髓炎主要致病機轉為細菌感染，放射線治療對控制細菌感染並無直接助益），臨床上極少使用，為本題答案（D✓，題目問「最為少見」者）。高壓氧治療可提高組織含氧量、促進感染控制與傷口癒合，是輔助治療之一（A）；抗生素治療是骨髓炎最核心、最基本的治療方式（B）；手術清創（移除壞死骨組織）是治療骨髓炎的重要方式之一（C），三者皆較放射線治療更常被使用。'},
{n:1058, no:18, subj:'骨骼肌肉', q:'有關膝關節損傷之評估方式，下列何者錯誤？', opts:['A.Anterior Drawer Test', 'B.Lachman Test', 'C.McMurray’s Test', 'D.Tinel’s Sign Test'], ans:[3], expl:'本題答案為D。Tinel\'s Sign（提內爾氏徵象）是用於評估「腕隧道症候群（正中神經壓迫）」的檢查方式，並非用於評估膝關節損傷，此為本題答案（D✗，題目問「何者錯誤」）。前抽屜試驗（Anterior Drawer Test）用於評估前十字韌帶（ACL）鬆弛度，敘述正確（A✓）；Lachman Test同樣是評估前十字韌帶完整性的檢查，敏感度更高，敘述正確（B✓）；McMurray\'s Test用於評估半月板（menisc）是否受損，敘述正確（C✓）。'},
{n:1059, no:19, subj:'骨骼肌肉', q:'有關腔症候群的評估與處置，下列何者錯誤？', opts:['A.最早出現的症狀是感覺異常', 'B.腔症候群出現時要立即解除壓迫的來源', 'C.患肢抬高需高於心臟，以減輕肢體腫脹', 'D.皮膚蒼白，指甲床微血管充填會大於 3 秒'], ans:[2], expl:'本題答案為C。腔室症候群若確診，應立即移除造成壓迫的來源（如過緊的石膏或敷料），必要時執行筋膜切開術，以避免組織缺血壞死，此屬正確處置原則，敘述正確（B✓，非本題答案）。患肢應維持與心臟「同高」，而非「高於心臟」，因抬高過度反而會降低動脈灌流壓力，加重組織缺血，此敘述有誤，為本題答案（C✗，題目問「何者錯誤」）。感覺異常（如麻木刺痛感）是腔室症候群最早期出現的症狀之一，敘述正確（A✓）；指甲床微血管充填時間延長（大於3秒）及皮膚蒼白，皆是組織灌流不足的表現，敘述正確（D✓）。'},
{n:1060, no:20, subj:'骨骼肌肉', q:'有關骨質疏鬆症與骨密度檢查的敘述，下列何者錯誤？', opts:['A.骨密度檢查為診斷骨質疏鬆症的主要依據', 'B.骨質定量超音波儀器為骨質疏鬆症初步篩檢工具', 'C.停經後骨質疏鬆症常造成脊椎壓迫性骨折', 'D.骨質疏鬆症病人可服用葡萄糖胺來減緩骨質流失'], ans:[3], expl:'本題答案為D。葡萄糖胺（Glucosamine）主要用於「退化性關節炎」，被認為有助於軟骨修復及緩解關節疼痛，但並非用於治療骨質疏鬆症、亦無實證證實可減緩骨質流失，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。雙能量X光吸收儀（DXA）測得之骨密度（T值）是目前診斷骨質疏鬆症最主要、最準確的依據，敘述正確（A✓）；骨質定量超音波（QUS）操作方便、無輻射，常作為社區篩檢工具，敘述正確（B✓）；停經後雌激素驟降加速骨質流失，好發脊椎壓迫性骨折，敘述正確（C✓）。'},
{n:1061, no:21, subj:'感官系統', q:'與引起聽力問題有關之疾病，下列何者最不可能？', opts:['A.甲狀腺功能亢進', 'B.高血壓', 'C.糖尿病', 'D.頭部外傷'], ans:[0], expl:'本題答案為A。甲狀腺功能「低下」（而非亢進）與聽力受損（尤其是感音性聽力障礙）較有關聯，甲狀腺功能亢進與聽力問題的直接關聯性較低，為本題答案（A✓，題目問「最不可能」者）。高血壓可能影響內耳微血管血循，與聽力受損有關（B）；糖尿病可能造成內耳微小血管病變及神經病變，與聽力受損有關（C）；頭部外傷可能直接損傷聽覺系統結構（如聽小骨、耳蝸、聽神經），與聽力受損密切相關（D），三者皆較甲狀腺功能亢進更常被視為聽力問題的相關因子。'},
{n:1062, no:22, subj:'感官系統', q:'有關視網膜剝離手術後病人護理措施之敘述，下列何者錯誤？', opts:['A.術後即採俯臥 4～5 天', 'B.覆眼敷料有滲出液為正常的現象', 'C.術後 2～3 週內避免閱讀', 'D.若近視度數改變，應等 3 個月後才更換眼鏡'], ans:[1], expl:'本題答案為B。覆眼敷料若出現大量滲出液，可能提示傷口感染或其他併發症，並非正常現象，應予評估及通報，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。視網膜剝離手術後（尤其使用氣體或矽油填充者）常需依醫囑採特定臥姿（如俯臥）數天，以利氣體或矽油頂住視網膜復位，敘述正確（A✓）；術後2～3週內應避免閱讀等近距離用眼動作，以減少眼球快速轉動、利於癒合，敘述正確（C✓）；因術後眼球結構及屈光狀態尚未穩定，近視度數可能持續變化，一般建議等待約3個月穩定後再更換眼鏡度數，敘述正確（D✓）。'},
{n:1063, no:23, subj:'感官系統', q:'有關鼻竇炎之敘述，下列何者錯誤？', opts:['A.鼻竇炎最常出現在上頷竇', 'B.鼻竇炎若未治療，可能出現腦膜炎、腦膿瘍等合併症', 'C.慢性鼻竇炎為鼻竇炎症狀持續 2～3 個月以上', 'D.慢性鼻竇炎症狀包括鼻塞、高燒、顏面疼痛等症狀'], ans:[3], expl:'本題答案為D。慢性鼻竇炎典型症狀為鼻塞、顏面疼痛脹痛感等，通常「不會」伴隨高燒（高燒較常見於急性鼻竇炎），此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。上頷竇因位置及開口引流角度關係，是最常受侵犯的鼻竇，敘述正確（A✓）；鼻竇炎若未妥善治療，感染可能經由鄰近解剖構造擴散至顱內，引發腦膜炎、腦膿瘍等嚴重合併症，敘述正確（B✓）；臨床上多將鼻竇炎症狀持續超過2～3個月（部分文獻定義為12週）以上者歸類為慢性鼻竇炎，敘述正確（C✓）。'},
{n:1064, no:24, subj:'感官系統', q:'有關喉癌手術後發聲及吞嚥功能改變之敘述，下列何者錯誤？', opts:['A.聲門上喉切除術後 2 週內可能會出現吞嚥困難', 'B.聲門上喉切除術後無法發聲', 'C.部分喉切除術保留一側聲帶，術後可能聲音沙啞', 'D.部分喉切除術後可以正常吞嚥'], ans:[1], expl:'本題答案為B。聲門上喉切除術（supraglottic laryngectomy）保留聲帶結構，術後病人「仍可發聲」，僅因會厭及部分吞嚥保護構造被切除，術後早期較易發生吸入嗆咳，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。因吞嚥保護機轉受影響，聲門上喉切除術後2週內確實可能出現吞嚥困難或嗆咳，需接受吞嚥訓練，敘述正確（A✓）；部分喉切除術若能保留至少一側聲帶，術後仍可發聲，但音質可能較沙啞，敘述正確（C✓）；部分喉切除術因保留較多正常解剖構造，術後多可逐步恢復正常經口吞嚥，敘述正確（D✓）。'},
{n:1065, no:25, subj:'心臟血管', q:'下列何者是 Heparin 之解毒劑？', opts:['A.Protamine sulfate', 'B.Streptokinase', 'C.Vitamin B12', 'D.Vitamin K1'], ans:[0], expl:'本題答案為A。Protamine sulfate（魚精蛋白）可與帶負電的Heparin結合形成穩定複合物，中和其抗凝血作用，是Heparin過量或需緊急逆轉抗凝效果時的特效解毒劑，此為本題答案（A✓）。Streptokinase是血栓溶解劑，非Heparin解毒劑（B✗）；Vitamin B12與惡性貧血治療有關，與抗凝血逆轉無關（C✗）；Vitamin K1是Warfarin（香豆素類口服抗凝血劑）的解毒劑，並非Heparin的解毒劑（D✗）。'},
{n:1066, no:26, subj:'心臟血管', q:'有關心臟衰竭臨床處置之敘述，下列何者錯誤？', opts:['A.使用主動脈內氣球幫浦（IABP），可以增加冠狀動脈血流且減少心臟後負荷', 'B.毛地黃與 Thiazide 類利尿劑並用，可以避免發生毛地黃中毒', 'C.低鹽飲食可以減少心臟前負荷', 'D.使用 Dobutamine 可以增加心肌收縮力，提高心輸出量'], ans:[1], expl:'本題答案為B。毛地黃（digoxin）與Thiazide類利尿劑併用時，Thiazide可能導致低血鉀，而低血鉀會「增加」毛地黃中毒的風險（並非避免中毒），此敘述有誤，為本題答案（B✗，題目問「何者錯誤」）。主動脈內氣球幫浦（IABP）於舒張期充氣可增加冠狀動脈灌流，於收縮期前放氣可降低左心室後負荷，敘述正確（A✓）；低鹽飲食可減少水鈉滯留，降低循環血量，減輕心臟前負荷，敘述正確（C✓）；Dobutamine為正性肌力藥物，可增加心肌收縮力及心輸出量，敘述正確（D✓）。'},
{n:1067, no:27, subj:'心臟血管', q:'有關心律不整藥物之敘述，下列何者正確？', opts:['A.Phenytoin（Dilantin）可用於治療毛地黃中毒引起之心律不整', 'B.Lidocaine（Xylocaine）為鉀離子通道阻斷劑，須注意高血鉀問題', 'C.心房早期收縮（APC）可使用鈣離子阻斷劑治療，但須注意低血壓問題', 'D.Amiodarone（Cordarone）為鈉離子通道阻斷劑，可延緩心肌去極化時間'], ans:[0], expl:'本題答案為A。Phenytoin（Dilantin）除抗癲癇作用外，亦可用於治療毛地黃中毒所引起之心律不整，此為本題答案（A✓）。Lidocaine（Xylocaine）屬第Ib類「鈉離子」（而非鉀離子）通道阻斷劑，其副作用需注意中樞神經毒性（如頭暈、抽搐），並非以高血鉀為主要注意事項，此敘述有誤（B✗）；心房早期收縮（APC）通常屬良性心律不整，多不需積極藥物治療，且鈣離子阻斷劑並非其典型治療藥物，此敘述有誤（C✗）；Amiodarone（Cordarone）主要屬第III類「鉀離子」（而非鈉離子）通道阻斷劑，作用是延長動作電位及有效不反應期，而非延緩心肌去極化時間，此敘述有誤（D✗）。'},
{n:1068, no:28, subj:'心臟血管', q:'下列病人描述何者不是穩定型心絞痛疼痛之典型特徵？', opts:['A.用力解便後即感覺胸口疼痛', 'B.痛的感覺好像是胸口壓了什麼東西一樣，一口氣吸不上來', 'C.左邊與右邊兩邊胸口都很痛，肩膀也痛到抬不起來', 'D.從吃完飯一直痛到晚上睡覺前才好一點，大概痛了 3 個多小時吧'], ans:[3], expl:'本題答案為D。穩定型心絞痛典型疼痛通常持續「數分鐘（一般小於15～20分鐘）」，休息或含服NTG即可緩解，若疼痛持續長達3個多小時仍未緩解，應高度懷疑為「不穩定型心絞痛」或急性心肌梗塞，而非穩定型心絞痛之典型特徵，此為本題答案（D✓，題目問「何者不是」穩定型心絞痛之典型特徵）。用力解便（Valsalva動作增加心臟負荷）誘發胸痛、胸口壓迫感合併呼吸不順、疼痛輻射至雙側肩膀，皆屬心絞痛常見之典型症狀描述（A、B、C）。'},
{n:1069, no:29, subj:'心臟血管', q:'能降低冠狀動脈疾病病人心肌耗氧量的藥物，下列何者錯誤？', opts:['A.乙型交感神經阻斷劑', 'B.硝酸鹽類', 'C.鈣離子阻斷劑', 'D.低劑量阿斯匹靈'], ans:[3], expl:'本題答案為D。低劑量阿斯匹靈主要作用為「抗血小板凝集」，預防血栓形成，並不會降低心肌耗氧量，此為本題答案（D✓，題目問「何者錯誤」）。乙型交感神經阻斷劑可降低心跳速率及心肌收縮力，減少心肌耗氧量（A）；硝酸鹽類可擴張靜脈及冠狀動脈，降低心臟前負荷並改善心肌血流灌注，減少心肌耗氧量（B）；鈣離子阻斷劑可降低心臟收縮力及周邊血管阻力，減少心肌耗氧量（C），三者皆具明確降低心肌耗氧量的藥理作用。'},
{n:1070, no:30, subj:'心臟血管', q:'有關毛地黃中毒症狀，下列何者正確？①腹瀉 ②便祕 ③噁心嘔吐 ④黃色視覺 ⑤紅色視覺 ⑥心跳變快', opts:['A.①③④', 'B.①⑤⑥', 'C.②③⑤', 'D.②④⑥'], ans:[0], expl:'本題答案為A。毛地黃（digoxin）中毒常見腸胃道症狀包括噁心嘔吐及腹瀉（①③），並可能出現特徵性視覺障礙「黃視症（xanthopsia，看東西泛黃色）」（④），選①③④＝A（本題答案）。毛地黃中毒較不以「便祕」為典型腸胃道表現（②錯誤）；視覺障礙典型為黃色（或黃綠色）視覺，而非紅色視覺（⑤錯誤）；毛地黃中毒因抑制房室結傳導、增加迷走神經張力，典型心律不整表現多為「心搏過緩」或各類房室傳導阻滯，而非心跳變快（⑥錯誤）。'},
{n:1071, no:31, subj:'心臟血管', q:'主要症狀為腹水、下肢水腫及肝脾腫大之瓣膜性心臟病病人，其最可能的瓣膜問題為下列何者？', opts:['A.主動脈瓣狹窄', 'B.二尖瓣狹窄', 'C.三尖瓣閉鎖不全', 'D.二尖瓣閉鎖不全'], ans:[2], expl:'本題答案為C。三尖瓣閉鎖不全時，右心房血液回流受阻、右心壓力上升，血液鬱積於體循環靜脈系統，導致肝脾腫大、腹水及下肢水腫等體循環鬱血表現，與本題描述最相符，為本題答案（C✓）。主動脈瓣狹窄典型表現為心絞痛、暈厥、呼吸困難三大症狀，較非以腹水肝脾腫大為主要表現（A✗）；二尖瓣狹窄或閉鎖不全主要影響左心房及肺循環，典型表現為呼吸困難、肺水腫等「肺循環鬱血」症狀，而非以腹水肝脾腫大等「體循環鬱血」表現為主（B✗、D✗）。'},
{n:1072, no:32, subj:'心臟血管', q:'有關高血壓病人的護理指導，下列何者最不適當？', opts:['A.維持身體質量指數（Body Mass Index, BMI）於正常範圍', 'B.飲食中攝取適當的鉀、鈣、鎂離子', 'C.每日酒精攝取量少於 120 mL', 'D.持續且規律的有氧運動'], ans:[2], expl:'本題答案為C。高血壓病人建議每日酒精攝取量應更嚴格限制（一般建議男性每日不超過20～30 mL酒精、女性更低，遠低於120 mL），120 mL已明顯過量，此建議不適當，為本題答案（C✓，題目問「最不適當」者）。維持正常BMI有助血壓控制，屬適當指導（A）；適當攝取鉀、鈣、鎂等礦物質有助血壓調節（如得舒飲食原則），屬適當指導（B）；規律有氧運動可有效降低血壓，屬適當指導（D）。'},
{n:1073, no:33, subj:'腫瘤血液', q:'放射線治療對下列何類細胞的治療效果較差？', opts:['A.骨髓', 'B.毛囊', 'C.神經細胞', 'D.含氧量高的細胞'], ans:[2], expl:'本題答案為C。神經細胞屬於「有絲分裂終止（不再分裂增殖）」的細胞，對放射線治療的敏感度「較低」，故治療效果相對較差，此為本題答案（C✓）。骨髓細胞、毛囊細胞皆屬於增殖速度快、對放射線相對敏感的組織，治療效果較佳（A✗、B✗）；含氧量高的細胞因氧氣可增強放射線造成的自由基損傷效應（氧效應），對放射線治療較「敏感」、效果較佳，並非效果較差（D✗）。'},
{n:1074, no:34, subj:'腫瘤血液', q:'有關封閉式體內放射線治療之敘述，下列何者錯誤？', opts:['A.需限制訪客接觸病人的時間與距離', 'B.住單人房可減少對其他人的影響', 'C.病人排泄物具有放射性', 'D.植入物掉地時要用長柄鑷子夾起'], ans:[2], expl:'本題答案為C。「封閉式（密封式）」體內放射線治療（如近接治療植入器）之放射源受到密封包覆，並不會經由病人體液或排泄物釋出放射性物質，故病人排泄物「不具」放射性，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。為降低他人輻射暴露，仍應限制訪客接觸病人的時間與距離，敘述正確（A✓）；安排住單人房可減少對周遭其他人員的輻射暴露，敘述正確（B✓）；若密封式植入物不慎掉落地面，應以長柄鑷子夾起放回適當屏蔽容器，避免徒手直接接觸，敘述正確（D✓）。'},
{n:1075, no:35, subj:'腫瘤血液', q:'汪小姐，血小板數目為 40,000/mm ，下列敘述何者正確？①非常容易引起自發性出血 ②避免使用Aspirin 或 Heparin ③肌肉注射的給藥方式最佳 ④給與軟便藥物可減少排便腸黏膜受傷', opts:['A.①②', 'B.①③', 'C.②④', 'D.③④'], ans:[2], expl:'本題答案為C。血小板數目40,000/mm³已明顯低於正常值（約150,000～400,000/mm³），應避免使用會抑制血小板功能或增加出血風險的藥物（如Aspirin或Heparin）（②），並應避免軟便劑等造成用力解便誘發出血、或選用溫和方式減少腸黏膜損傷（④），選②④＝C（本題答案）。血小板低下確實會增加自發性出血風險，但「非常容易」的描述搭配後續選項組合考量，① 需與③一併檢視：肌肉注射會造成局部血腫，屬血小板低下病人的「禁忌」給藥方式而非「最佳」方式，故③本身描述有誤，不應與①一併列為正確組合。'},
{n:1076, no:36, subj:'腫瘤血液', q:'與乳癌有關的腫瘤標記，下列何者正確？', opts:['A.carcinoembryonic antigen（CEA）', 'B.prostatic specific antigen（PSA）', 'C.alpha fetoprotein（AFP）', 'D.alkaline phosphatase'], ans:[0], expl:'本題答案為A。CEA（癌胚抗原）雖非乳癌專一性標記，但在臨床上常用於乳癌病人治療後追蹤及復發監測，是與乳癌相關之腫瘤標記之一，此為本題答案（A✓）。PSA（攝護腺特異抗原）是攝護腺癌的腫瘤標記（B✗）；AFP（甲型胎兒蛋白）主要與肝癌及生殖細胞腫瘤相關（C✗）；鹼性磷酸酶（alkaline phosphatase）雖可能於骨轉移時上升，但並非乳癌的專一腫瘤標記（D✗）。'},
{n:1077, no:37, subj:'腫瘤血液', q:'有關癌細胞特性之敘述，下列何者錯誤？', opts:['A.細胞上的 P53 基因容易受損而抑制細胞修復', 'B.生長所需的養分比正常細胞少', 'C.在生長時，會有接觸抑制（contact inhibition）作用', 'D.細胞的有絲分裂指數（mitotic index）高，增殖快'], ans:[2], expl:'本題答案為C。正常細胞生長時彼此接觸後會停止增生，稱為「接觸抑制」；癌細胞的重要特徵之一正是「喪失」接觸抑制作用，使其不受周圍細胞限制、持續堆疊增生，本選項卻描述癌細胞生長時「會有」接觸抑制作用，方向恰好相反，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。P53為重要的抑癌基因，正常功能是偵測DNA損傷、促進修復或誘導受損細胞凋亡，若P53基因本身受損，則此修復與汰除機制隨之失靈，有利癌細胞存活增生，敘述正確（A✓）；癌細胞代謝旺盛、增殖迅速，实际所需養分一般認為較正常細胞更多而非更少，惟此細節並非本題設計欲測驗之核心重點，依官方答案仍以C為本題最主要且最明確之錯誤敘述（B，供讀者留意此選項用詞本身尚有可再斟酌之處）；癌細胞有絲分裂指數高、增殖速度快，是其典型特徵，敘述正確（D✓）。'},
{n:1078, no:38, subj:'腫瘤血液', q:'有關良性腫瘤的特徵，下列何者錯誤？', opts:['A.無轉移性', 'B.無纖維膜包覆', 'C.細胞分化良好', 'D.觸診時具可動性'], ans:[1], expl:'本題答案為B。良性腫瘤細胞增生速度較緩慢，且通常會形成完整的「纖維包膜」將腫瘤與周圍正常組織區隔開來，並非「無纖維膜包覆」，此敘述有誤，為本題答案（B✗，題目問「何者錯誤」）。良性腫瘤不具轉移能力，敘述正確（A✓）；良性腫瘤細胞分化程度良好、型態接近正常細胞，敘述正確（C✓）；因有完整包膜且不侵犯周圍組織，觸診時腫瘤通常具有可移動性，敘述正確（D✓）。'},
{n:1079, no:39, subj:'腫瘤血液', q:'有關癌症常見的腫瘤標記之敘述，下列何者錯誤？', opts:['A.CA19-9 為乳癌的腫瘤標記', 'B.CA125 為卵巢癌的腫瘤標記', 'C.AFP 為肝癌的腫瘤標記', 'D.CEA 為大腸直腸癌的腫瘤標記'], ans:[0], expl:'本題答案為A。CA19-9主要是「胰臟癌」及部分腸胃道腫瘤（如大腸直腸癌、膽道癌）的相關腫瘤標記，並非乳癌的腫瘤標記，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。CA125是卵巢癌重要的腫瘤標記，敘述正確（B✓）；AFP是肝細胞癌重要的腫瘤標記，敘述正確（C✓）；CEA是大腸直腸癌常用的腫瘤標記，敘述正確（D✓）。'},
{n:1080, no:40, subj:'腫瘤血液', q:'維生素 B12 缺乏造成的惡性貧血，可透過下列何種試驗或檢查進行鑑別？', opts:['A.直接庫姆氏試驗（direct Coombs’ test）', 'B.間接庫姆氏試驗（indirect Coombs’ test）', 'C.席林試驗（Schilling’s test）', 'D.尿液本斯-瓊司氏蛋白檢查（Bence-Jones protein）'], ans:[2], expl:'本題答案為C。席林試驗（Schilling\'s test）利用口服放射性標記維生素B12，測量其尿中排泄量，可鑑別惡性貧血是因「內在因子缺乏」（惡性貧血）或其他原因（如迴腸吸收不良）造成的維生素B12缺乏，是鑑別惡性貧血病因的經典檢查，此為本題答案（C✓）。直接／間接庫姆氏試驗主要用於診斷「溶血性貧血」（偵測紅血球表面或血清中的抗體），並非用於惡性貧血之鑑別（A✗、B✗）；本斯-瓊司氏蛋白檢查與「多發性骨髓瘤」的診斷有關，與惡性貧血無關（D✗）。'},
{n:1081, no:41, subj:'腫瘤血液', q:'王太太 50 歲，診斷為急性白血病，入院行高劑量 Ara-C 化學治療後，白血球 3,500/cumm、嗜中性球為 13%，下列敘述何者正確？', opts:['A.王太太屬輕度白血球低下，應提供居家照護護理指導後辦理出院', 'B.王太太正處於嗜中性白血球低下（neutropenia）的階段', 'C.王太太沒有發燒、呼吸急促或解尿困難等症狀，表示未感染，出院後自行觀察即可', 'D.王太太的口腔黏膜、肛門黏膜和侵入性導管置入處不可能會發生感染'], ans:[1], expl:'本題答案為B。白血球3,500/cumm，嗜中性球佔13%，計算絕對嗜中性球數（ANC）＝3,500×13%＝455/cumm，已明顯低於1,500/cumm（嗜中性白血球低下的定義門檻），王太太正處於嗜中性白血球低下（neutropenia）階段，感染風險大增，此為本題答案（B✓）。此ANC數值已達「重度」低下（一般<500/cumm屬重度），並非輕度，且此階段感染風險極高，不應貿然安排出院，敘述有誤（A✗）；嗜中性白血球低下病人因發炎反應能力受損，即使已有感染，也可能「不會出現典型發燒或明顯症狀」，故「沒有症狀＝未感染」的推論並不成立，仍應持續密切觀察並警覺，敘述有誤（C✗）；嗜中性白血球低下病人因免疫防禦能力下降，口腔黏膜、肛門黏膜、侵入性導管處等部位「皆可能」發生感染，並非不可能發生，敘述有誤（D✗）。'},
{n:1082, no:42, subj:'腫瘤血液', q:'有關非何杰金氏淋巴瘤之治療，下列何者正確？', opts:['A.病人常接受低劑量類固醇', 'B.周邊血液幹細胞移植法不適用於復發病人', 'C.在化療後一個月取出病人骨髓，除去癌細胞後儲存', 'D.化療前接受 HBsAg 篩檢，並使用 lamivudine，以防 B 型肝炎急性發作'], ans:[3], expl:'本題答案為D。B型肝炎帶原者若接受化學治療，可能因免疫抑制導致病毒大量複製、誘發B型肝炎急性發作甚至猛爆性肝炎，故化療前應篩檢HBsAg，若為陽性帶原者，應預防性使用lamivudine等抗病毒藥物，此為本題答案（D✓）。非何杰金氏淋巴瘤化療多依疾病分期採合併化療方案，並非常規使用「低劑量」類固醇（A✗）；周邊血液幹細胞移植法（自體或異體）亦可應用於復發病人的治療選項之一，並非不適用（B✗）；自體周邊血液幹細胞移植是於「化療前」（或緩解期）先行採集、保存幹細胞，而非化療後一個月才取出骨髓除去癌細胞後儲存，此敘述之時機與方式描述皆有誤（C✗）。'},
{n:1083, no:43, subj:'其他', q:'有關燒傷病人達到體液復甦目標之指標，下列何者正確？', opts:['A.血比容（Hematocrit）60%', 'B.脈搏 130 次／分', 'C.尿比重 1.035', 'D.尿量每小時 50 毫升'], ans:[3], expl:'本題答案為D。燒傷病人體液復甦目標之一是維持尿量約每小時30～50毫升（約0.5～1 mL/kg/hr），本選項尿量50毫升／小時，顯示腎臟灌流已恢復適當，是體液復甦達到目標的良好指標，此為本題答案（D✓）。血比容60%明顯高於正常值，顯示血液仍處於濃縮狀態，代表體液復甦「尚未」達到目標（A✗）；脈搏130次／分仍屬心搏過速，顯示循環血量可能仍然不足，體液復甦尚未達標（B✗）；尿比重1.035明顯偏高，顯示尿液仍高度濃縮，反映體液容積仍然不足，體液復甦尚未達標（C✗）。'},
{n:1084, no:44, subj:'其他', q:'有關蜂窩性組織炎的敘述，下列何者正確？', opts:['A.患部可見大片界線分明的紅斑與水疱', 'B.冷敷患部以減輕水腫與炎症反應', 'C.常見綠膿桿菌引起的傷口感染', 'D.鼓勵患肢運動，以減輕水腫'], ans:[1], expl:'本題答案為B。蜂窩性組織炎急性發炎期建議局部冰敷或冷敷（每次約5～10分鐘，間隔至少30分鐘），以抑制發炎反應擴大、減輕水腫及疼痛；若此時反而熱敷，會促進局部血液循環，可能使發炎反應加劇、細菌隨血流擴散更快，故急性期應以冷敷為原則，待醫師評估無併發症後，後期才改採熱敷促進循環修復，此為本題答案（B✓）。蜂窩性組織炎患部典型表現為紅、腫、熱、痛，其紅斑範圍邊界通常「不清、瀰漫」，與丹毒（erysipelas）邊界隆起清楚的特徵不同，本選項描述「界線分明的紅斑與水疱」較不符合蜂窩性組織炎典型表現（A✗）；其常見致病菌為金黃色葡萄球菌及A族鏈球菌，綠膿桿菌並非蜂窩性組織炎常見致病菌（較常見於燒傷傷口、糖尿病足潰瘍等特殊情境）（C✗）；急性期應臥床休息並抬高患肢（約30～40度）以促進靜脈回流、減輕水腫，而非鼓勵患肢運動，運動反而可能促進血液循環而加速感染擴散（D✗）。'},
{n:1085, no:45, subj:'其他', q:'有關生殖器疱疹的敘述，下列何者錯誤？', opts:['A.為性交傳染', 'B.教導病人避免擠壓患部水疱', 'C.發病後 7～10 天避免與他人親密性接觸', 'D.由帶狀水痘病毒感染所引起'], ans:[3], expl:'本題答案為D。生殖器疱疹是由「單純疱疹病毒（Herpes Simplex Virus, HSV，尤其第二型）」感染所致，並非帶狀水痘病毒（帶狀疱疹病毒引起的是帶狀疱疹，屬另一種疾病），此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。生殖器疱疹主要透過性接觸傳染，敘述正確（A✓）；應教導病人避免擠壓水疱，以免病毒擴散或續發感染，敘述正確（B✓）；病灶出現後（尤其7～10天內病毒活性較高）應避免與他人有親密性接觸，以降低傳染風險，敘述正確（C✓）。'},
{n:1086, no:46, subj:'其他', q:'有關燒傷病人接受自體移植後出院之護理指導，下列何者錯誤？', opts:['A.鼓勵全範圍關節運動', 'B.鼓勵植皮部位多曬太陽，以促進黑色素形成', 'C.燒傷部位穿著壓力衣並使用潤膚乳液', 'D.燒傷部位可使用副木等支持物以避免關節攣縮'], ans:[1], expl:'本題答案為B。植皮部位新生皮膚較脆弱、色素調節功能尚未成熟，應「避免」直接曝曬陽光，以免造成曬傷或色素沉澱不均，並非鼓勵曬太陽促進黑色素形成，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。鼓勵執行全範圍關節運動，有助預防攣縮、維持關節活動度，敘述正確（A✓）；穿著壓力衣可減少疤痕增生，並使用潤膚乳液保持皮膚濕潤彈性，皆為燒傷術後常見照護指導，敘述正確（C✓）；使用副木等支持物固定關節於功能性姿位，可預防攣縮變形，敘述正確（D✓）。'},
{n:1087, no:47, subj:'其他', q:'針對 HIV 感染或 HIV 感染狀況不明者的相關防範措施之敘述，下列何者錯誤？', opts:['A.接觸血液或其他可能帶有血液的體液（例如尿液、糞便、嘔吐物）時，應該要戴手套', 'B.HIV 病毒可存在於母乳中，因此感染愛滋病毒的婦女不要哺餵母乳', 'C.發現環境表面有血液沾污時，立刻以 1：1000 之漂白水清潔消毒', 'D.愛滋病毒感染者若需急救時，避免口對口人工呼吸'], ans:[2], expl:'本題答案為C。若環境表面遭血液或體液沾污，應以「1：10（而非1：1000）」濃度之漂白水進行清潔消毒，1：1000濃度過於稀釋，消毒效果不足，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。接觸血液或可能帶血液之體液時應戴手套，屬標準防護措施，敘述正確（A✓）；HIV病毒可經由母乳傳染給嬰兒，故感染愛滋病毒之婦女應避免哺餵母乳，敘述正確（B✓）；為避免經口腔黏膜或體液交換傳染，應避免對愛滋病毒感染者施行口對口人工呼吸，改採其他急救裝置，敘述正確（D✓）。'},
{n:1088, no:48, subj:'其他', q:'有關溶血性輸血引起的過敏反應，是下列那類免疫球蛋白與補體結合，活化補體系統所致？', opts:['A.IgA、IgM', 'B.IgA、IgE', 'C.IgE、IgM', 'D.IgG、IgM'], ans:[3], expl:'本題答案為D。溶血性輸血反應（急性型）主要是受血者體內已存在的IgG或IgM抗體，與輸入紅血球表面抗原結合形成抗原抗體複合物，進而活化補體系統，導致紅血球溶解破壞，此為本題答案（D✓）。IgA主要與過敏性輸血反應（如IgA缺乏症病人）較有關，並非典型的補體活化溶血機轉主角（A✗、B✗）；IgE主要參與第一型（立即性）過敏反應，與補體活化溶血的機轉不同（C✗）。'},
{n:1089, no:49, subj:'其他', q:'有關全身性紅斑性狼瘡的護理措施，下列何者錯誤？', opts:['A.告知病人避免直接暴露於陽光下', 'B.提供高蛋白、高維生素及高鐵的均衡飲食', 'C.若腎臟受到侵犯，應採低鈉、高鉀、高蛋白飲食', 'D.在關節炎症的急性期應予冷敷'], ans:[2], expl:'本題答案為C。全身性紅斑性狼瘡（SLE）若腎臟受侵犯（狼瘡腎炎），飲食應採「低鈉、低蛋白（依腎功能調整）」為原則，以減輕腎臟負擔，並非高蛋白，此敘述錯誤，為本題答案（C✗，題目問「何者錯誤」）。SLE病人對陽光敏感，紫外線可能誘發疾病惡化，應避免直接日曬，敘述正確（A✓）；應提供高蛋白（於腎功能許可下）、高維生素及高鐵的均衡飲食以維持營養狀態、對抗慢性發炎消耗，敘述正確（B✓，此處指一般SLE病人未合併嚴重腎損傷時之飲食原則）；關節炎急性發炎期可予冷敷以減輕腫脹疼痛，敘述正確（D✓）。'},
{n:1090, no:50, subj:'其他', q:'有關細胞性免疫之敘述，下列何者正確？', opts:['A.主導細胞為 B 細胞', 'B.主要作用為保護個體不受感染', 'C.形成免疫反應所需時間，較體液性免疫反應時間短', 'D.T 細胞須藉由主要組織相容複合物為媒介'], ans:[3], expl:'本題答案為D。細胞性（細胞媒介型）免疫反應主要透過T細胞辨識抗原，其辨識過程須藉由主要組織相容複合體（MHC）作為媒介呈現抗原，此為本題答案（D✓）。細胞性免疫的主導細胞為「T細胞」，而非B細胞（B細胞主要負責體液性免疫、產生抗體），此敘述有誤（A✗）；細胞性免疫主要作用是清除「胞內病原體」（如病毒感染細胞、腫瘤細胞），保護個體不受感染是免疫系統整體（含體液性與細胞性）的共同作用，並非細胞性免疫獨有且此描述過於籠統簡化，非本題最適切答案（B✗）；細胞性免疫反應形成所需時間一般「較體液性免疫反應長」，而非較短，此敘述方向有誤（C✗）。'},
{n:1091, no:51, subj:'呼吸系統', q:'有關膿胸病變發生之部位，下列何者正確？', opts:['A.肺泡', 'B.支氣管', 'C.肺實質', 'D.肋膜腔'], ans:[3], expl:'本題答案為D。膿胸是指膿性積液積聚於「肋膜腔（胸膜腔）」內，此為本題答案（D✓）。肺泡、支氣管、肺實質皆為肺臟本身的解剖構造，其感染性病變分別稱為肺泡發炎、支氣管炎、肺實質感染（肺炎），並非膿胸發生的部位（A✗、B✗、C✗，膿胸特指肋膜腔內的膿性積液）。'},
{n:1092, no:52, subj:'呼吸系統', q:'肺結核病人若無法遵從醫師所開立的醫囑規則服藥時之護理措施，下列何者最適當？', opts:['A.請照顧者監督病人定時服藥', 'B.請病人每週回診，並詢問是否規則服藥', 'C.告訴醫師病人未能遵從規則服藥，是否使用其他治療方式', 'D.跟病人強調若不規則服藥，肺結核可能導致死亡'], ans:[0], expl:'本題答案為A。針對無法遵從醫囑規則服藥的肺結核病人，安排「照顧者（或醫護人員）在旁監督服藥（Directly Observed Therapy, DOTS）」是目前實證上最有效確保規則服藥、降低治療失敗及抗藥性風險的策略，此為本題答案（A✓，最適當之護理措施）。單純詢問是否規則服藥，缺乏實際監督機制，效果有限（B✗）；告知醫師是否改用其他治療方式，並非護理人員可優先自行採取的直接措施，且未能根本解決服藥遵從度問題（C✗）；單純以死亡風險恐嚇病人，缺乏具體支持性措施，效果有限且非最適當之護理處置（D✗）。'},
{n:1093, no:53, subj:'呼吸系統', q:'有關連枷胸的敘述，下列何者正確？', opts:['A.會使死腔減少', 'B.會造成奇異性呼吸', 'C.會影響肺吸氣時胸腔產生的正壓', 'D.連枷段會在吸氣時向外突出，而吐氣時往內拉'], ans:[1], expl:'本題答案為B。連枷胸因肋骨多處骨折使局部胸壁失去骨骼支撐完整性，吸氣時該處胸壁因胸內負壓反而向內凹陷、吐氣時往外突出，與正常呼吸方向相反，形成「奇異性呼吸（矛盾呼吸）」，此為本題答案（B✓）。連枷胸因通氣效率下降、代償性淺快呼吸，死腔通常「增加」而非減少（A✗）；連枷胸會使該處胸壁在吸氣時「失去正壓支撐、反而塌陷」，並非影響吸氣時胸腔產生的正壓（一般吸氣時胸內為負壓而非正壓，此敘述本身概念亦有誤）（C✗）；連枷段的異常運動方向應為「吸氣時向內凹陷、吐氣時向外突出」，與D選項描述之方向恰好相反（D✗）。'},
{n:1094, no:54, subj:'呼吸系統', q:'針對左側氣胸病人之患側胸部評估，下列何者為最可能之發現？', opts:['A.扣診濁音', 'B.觸診有觸覺震顫', 'C.聽診有濕囉音', 'D.聽診呼吸音消失'], ans:[3], expl:'本題答案為D。左側氣胸因胸膜腔積氣，患側肺塌陷、無法正常擴張換氣，聽診該側呼吸音會「消失或明顯減弱」，此為最可能之評估發現，為本題答案（D✓）。氣胸因胸膜腔內氣體增多，叩診應呈現「過度反響音」而非濁音（濁音較常見於肋膜積水或肺實質病變）（A✗）；氣胸患側因氣體阻隔，觸覺震顫應「減弱或消失」，而非增強（B✗）；氣胸聽診應為呼吸音減弱或消失，並非出現濕囉音（濕囉音較常見於肺水腫或肺部感染合併分泌物增加）（C✗）。'},
{n:1095, no:55, subj:'呼吸系統', q:'觀察到胸腔水下引流的水封瓶內持續有小量氣泡時之處置，下列何者正確？', opts:['A.持續觀察，這是正常的現象', 'B.檢查引流裝置各部位的連接是否密合', 'C.減少抽吸壓力至 15 cm H2O 並持續觀察', 'D.將水封瓶內的水倒掉一半'], ans:[1], expl:'本題答案為B。胸腔水下引流水封瓶內持續出現氣泡（尤其非病人咳嗽時仍持續出現），可能提示引流系統各接頭處有「漏氣」，應立即檢查各部位連接是否密合，以確保引流系統的密閉性及有效性，此為本題答案（B✓，最適當處置）。持續氣泡通常提示系統異常（如漏氣或氣胸持續存在），不應僅視為正常現象而不予處理（A✗）；抽吸壓力之調整應依醫囑及臨床整體評估決定，不應自行任意調降（C✗）；不應自行將水封瓶內的水倒掉一半，此舉可能破壞水封瓶原有的密閉水柱高度及測壓功能，並非正確處置方式（D✗）。'},
{n:1096, no:56, subj:'呼吸系統', q:'有關呼吸性酸中毒之敘述，下列何者正確？', opts:['A.因換氣速率過快所造成', 'B.易見於水楊酸中毒病人', 'C.中樞神經系統受刺激，病人會有手腳麻刺感', 'D.慢性阻塞性肺疾病病人吸入過多氧氣易導致'], ans:[3], expl:'本題答案為D。慢性阻塞性肺疾病（COPD）病人長期處於慢性缺氧、CO2偏高的狀態，其呼吸驅動力主要仰賴「低血氧」刺激（缺氧驅動理論）而非血中CO2濃度，若吸入「過多、高濃度」氧氣，會抑制此缺氧驅動的呼吸刺激，導致換氣更加不足、二氧化碳蓄積加劇，進而誘發或加重呼吸性酸中毒，此為本題答案（D✓）。呼吸性酸中毒是因換氣「不足」、二氧化碳排出受阻蓄積所致，並非因換氣速率過快造成（換氣過快、CO2過度排出所致者為呼吸性鹼中毒），此敘述方向恰好相反（A✗）；水楊酸中毒典型病程是「早期」因藥物直接刺激呼吸中樞導致換氣過度，先出現呼吸性鹼中毒，其後才可能因藥物影響細胞代謝而合併代謝性酸中毒，並非以呼吸性酸中毒為典型表現（B✗）；中樞神經系統受刺激、出現手腳麻刺感等類似手足搐搦的症狀，較典型見於「呼吸性鹼中毒」（換氣過度使游離鈣濃度下降所致），呼吸性酸中毒因CO2蓄積，中樞神經系統典型表現反而是「受抑制」，出現嗜睡、意識混亂甚至昏迷（CO2 narcosis），與C選項描述之機轉方向不符（C✗）。'},
{n:1097, no:57, subj:'呼吸系統', q:'下列何者最容易造成 α1-抗胰蛋白酶（α1-antitrypsin）缺乏？', opts:['A.慢性支氣管炎', 'B.肺氣腫', 'C.氣喘', 'D.支氣管擴張症'], ans:[1], expl:'本題答案為B。α1-抗胰蛋白酶缺乏（一種遺傳性疾病）會使肺部彈性蛋白酶活性失去正常抑制，過度分解肺泡壁彈性組織，是導致「肺氣腫」（尤其早發性、非吸菸相關之肺氣腫）的重要病因之一，此為本題答案（B✓）。慢性支氣管炎、氣喘、支氣管擴張症之致病機轉分別與慢性發炎、氣道過度反應、慢性感染及結構性擴張損傷有關，皆非α1-抗胰蛋白酶缺乏的典型相關疾病（A✗、C✗、D✗）。'},
{n:1098, no:58, subj:'呼吸系統', q:'慢性阻塞性肺部疾病病人最早出現的肺功能變化為下列何者？', opts:['A.用力呼氣時間延長', 'B.肺活量降低', 'C.肺餘容積上升', 'D.用力呼氣第一秒容積下降'], ans:[3], expl:'本題答案為D。慢性阻塞性肺疾病（COPD）因小氣道阻力增加，病人最早出現的肺功能變化是「用力呼氣第一秒容積（FEV1）下降」，是診斷COPD及分級嚴重度最核心的指標，此為本題答案（D✓）。用力呼氣時間延長、肺活量降低、肺餘容積上升皆是COPD疾病進展過程中會出現的變化，但並非最早期出現的肺功能改變（A✗、B✗、C✗）。'},
{n:1099, no:59, subj:'泌尿系統', q:'下列何者不會出現少尿現象？', opts:['A.休克', 'B.急性腎衰竭', 'C.腦下垂體後葉受損', 'D.腎後性阻塞'], ans:[2], expl:'本題答案為C。腦下垂體「後葉」受損主要影響抗利尿荷爾蒙（ADH）分泌，若ADH分泌不足會導致尿崩症，臨床表現為「多尿」而非少尿，此為本題答案（C✓，題目問「不會出現少尿」者）。休克時因有效循環血量不足、腎臟灌流下降，會出現少尿（A✗）；急性腎衰竭因腎臟功能受損，經典表現包含少尿期（B✗）；腎後性阻塞（如尿路結石、腫瘤壓迫）會阻礙尿液排出，導致少尿甚至無尿（D✗）。'},
{n:1100, no:60, subj:'泌尿系統', q:'膀胱癌的初期臨床表徵，下列何者正確？', opts:['A.體重減輕', 'B.頻尿', 'C.無痛性血尿', 'D.食慾不振'], ans:[2], expl:'本題答案為C。膀胱癌初期最常見、最典型的臨床表徵是「無痛性間歇性或持續性血尿」，此為本題答案（C✓）。體重減輕、頻尿、食慾不振較常見於病程進展後期或伴隨其他併發症時出現，並非膀胱癌「初期」最典型的表現（A✗、B✗、D✗）。'},
{n:1101, no:61, subj:'泌尿系統', q:'下列何者是男性較常出現的尿失禁型態？', opts:['A.應力型', 'B.急迫型', 'C.滿溢型', 'D.功能性'], ans:[2], expl:'本題答案為C。男性因攝護腺解剖構造，較常因攝護腺肥大等因素造成膀胱出口阻塞、殘尿量增加，進而發生「滿溢性尿失禁（overflow incontinence）」，是男性較常見的尿失禁型態，此為本題答案（C✓）。應力性尿失禁（因骨盆底肌肉鬆弛、腹壓增加誘發滲尿）較常見於「女性」（尤其經產婦、停經後婦女）（A✗）；急迫性尿失禁與膀胱過動症有關，兩性皆可能發生，並非男性特別常見的型態（B✗）；功能性尿失禁與認知或行動能力障礙有關，與性別解剖構造無直接關聯（D✗）。'},
{n:1102, no:62, subj:'泌尿系統', q:'有關病人血清鉀為 7.0 mEq/L 之處置，下列何者錯誤？', opts:['A.口服或灌腸給予 Kayexalate', 'B.靜脈注射短效胰島素及 50%葡萄糖溶液', 'C.靜脈注射重碳酸鈉', 'D.鼓勵多食用柳丁、香蕉'], ans:[3], expl:'本題答案為D。血清鉀高達7.0 mEq/L屬於嚴重高血鉀，屬於危及生命的急症，應立即積極降低血鉀，而非僅鼓勵病人「多食用」富含鉀離子的柳丁、香蕉等食物（此舉反而會使血鉀更加惡化），此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。口服或灌腸給予Kayexalate（一種陽離子交換樹脂）可促進腸道排除鉀離子，敘述正確（A✓）；靜脈注射短效胰島素併同50%葡萄糖溶液，可促使鉀離子暫時性移入細胞內，快速降低血清鉀濃度，敘述正確（B✓）；靜脈注射重碳酸鈉可提高血液pH值，promoting鉀離子暫時移入細胞內，亦為緊急降血鉀的處置之一，敘述正確（C✓）。'},
{n:1103, no:63, subj:'呼吸系統', q:'有關病人因焦慮而過度通氣造成之酸鹼不平衡，下列何者正確？', opts:['A.呼吸性鹼中毒', 'B.呼吸性酸中毒', 'C.代謝性酸中毒', 'D.代謝性鹼中毒'], ans:[0], expl:'本題答案為A。因焦慮而過度通氣（換氣過度），會使體內二氧化碳被過度排出、血中碳酸濃度下降，導致血液pH值上升，形成「呼吸性鹼中毒」，此為本題答案（A✓）。呼吸性酸中毒是因換氣「不足」、二氧化碳蓄積所致，與過度通氣的機轉相反（B✗）；代謝性酸中毒、代謝性鹼中毒之成因與腎臟或代謝性因素（如碳酸氫根流失或滯留）有關，並非因過度通氣直接造成（C✗、D✗）。'},
{n:1104, no:64, subj:'泌尿系統', q:'有關腎病症候群病人之處置，下列何者錯誤？', opts:['A.採低鈉、低鉀、低蛋白飲食', 'B.使用 Prednisolone 以緩解蛋白尿', 'C.給予 Furosemide（Lasix）用以控制水腫', 'D.使用抗凝劑預防腎靜脈血栓'], ans:[0], expl:'本題答案為A。腎病症候群病人因大量蛋白尿流失導致低白蛋白血症，飲食應採「適度蛋白質」補充（依腎功能調整，通常為正常量或適度限制，而非低蛋白）並限制鈉離子攝取（低鈉飲食）以減輕水腫，本選項「低蛋白」的描述與一般治療原則不符，此敘述錯誤，為本題答案（A✗，題目問「何者錯誤」）。Prednisolone等類固醇藥物可抑制免疫發炎反應、減少腎絲球通透性異常，緩解蛋白尿，敘述正確（B✓）；Furosemide等利尿劑可促進排除多餘水分，控制水腫，敘述正確（C✓）；腎病症候群因肝臟代償性合成蛋白增加，可能同時使凝血因子上升、增加血栓形成風險，故常需使用抗凝劑預防腎靜脈血栓等血栓栓塞併發症，敘述正確（D✓）。'},
{n:1105, no:65, subj:'泌尿系統', q:'有關急性腎絲球腎炎（AGN）急性期之護理指導，下列何者正確？①多下床活動以避免下肢水腫 ②採高碳水化合物、低蛋白飲食 ③預防感染措施 ④鼓勵多喝水', opts:['A.①②', 'B.①④', 'C.②③', 'D.③④'], ans:[2], expl:'本題答案為C。急性腎絲球腎炎（AGN）急性期飲食應採「高碳水化合物、低蛋白」飲食（②，以減輕腎臟負擔並提供足夠熱量），並應加強「預防感染措施」（③，因感染尤其鏈球菌感染可能誘發或加重病情），選②③＝C（本題答案）。AGN急性期因水腫及高血壓風險，應以「臥床休息」為主，並非鼓勵多下床活動（①錯誤）；因病人常伴隨水腫、少尿及高血壓，應採「限制」（而非鼓勵）液體攝取，以避免加重水腫及循環負荷（④錯誤）。'},
{n:1106, no:66, subj:'泌尿系統', q:'有關接受腎移植而服用免疫抑制劑 cyclosporine 之敘述，下列何者錯誤？', opts:['A.避免進出公共場所', 'B.可能會出現肝、腎毒性', 'C.長期服用易致癌症', 'D.腎功能維持穩定正常後，即可停藥'], ans:[3], expl:'本題答案為D。腎臟移植後服用免疫抑制劑cyclosporine，其副作用之一雖可能影響腎功能，但即使腎功能恢復穩定正常，仍需依醫囑「終身」規律服用免疫抑制劑以預防排斥反應，並不可自行停藥，此敘述錯誤，為本題答案（D✗，題目問「何者錯誤」）。因免疫功能受抑制，應避免出入人多擁擠或感染風險高的公共場所，敘述正確（A✓）；cyclosporine具明確的肝毒性及腎毒性副作用，需定期監測相關數值，敘述正確（B✓）；長期使用免疫抑制劑會增加淋巴瘤、皮膚癌等惡性腫瘤的發生風險，敘述正確（C✓）。'},
{n:1107, no:67, subj:'內分泌系統', q:'有關甲狀腺機能低下病人的臨床表徵，下列何者正確？', opts:['A.低血鈉', 'B.對熱敏感', 'C.皮膚出現凹陷性水腫', 'D.食慾降低且體重減輕'], ans:[0], expl:'本題答案為A。甲狀腺機能低下因新陳代謝速率下降，腎臟排水能力受影響，容易發生體液滯留及「稀釋性低血鈉」，此為本題答案（A✓）。甲狀腺機能低下病人因代謝速率下降、產熱減少，臨床上多表現「畏寒、對冷敏感」，而非對熱敏感（B✗，對熱敏感較常見於甲狀腺機能「亢進」）；皮膚因黏多醣類物質堆積於皮下組織，呈現「非凹陷性（黏液性）水腫」，而非凹陷性水腫（C✗）；甲狀腺機能低下因代謝速率下降，病人食慾與代謝需求皆降低，體重多呈現「增加」而非減少（D✗，且食慾降低與體重減輕之組合較符合其他消耗性疾病，非甲狀腺機能低下之典型表現）。'},
{n:1108, no:68, subj:'內分泌系統', q:'有關糖尿病病人運動之護理指導，下列何者正確？', opts:['A.胰島素作用高峰時，是最佳的運動時間', 'B.腿部剛注射胰島素後，避免立即跑步運動', 'C.運動方式儘量採急速變化，以達運動效果', 'D.血糖超過 300 mg/dL 時，應延長運動時間'], ans:[1], expl:'本題答案為B。糖尿病病人若剛於腿部注射胰島素，應避免立即進行會大量使用該部位肌肉的劇烈運動（如跑步），以免加速胰島素自注射部位的吸收速度，增加低血糖風險，此為本題答案（B✓）。胰島素作用達高峰時運動，血糖已因胰島素作用而下降，此時再運動易誘發低血糖，並非最佳運動時機，此敘述有誤（A✗）；運動方式應「循序漸進」規律進行，而非採取急速變化的方式，以避免血糖劇烈波動或運動傷害，此敘述有誤（C✗）；血糖超過300 mg/dL時，應先確認有無酮體、延後運動並依醫囑處理，而非直接延長運動時間（劇烈運動於高血糖未穩定時反而可能使血糖更加惡化），此敘述有誤（D✗）。'},
{n:1109, no:69, subj:'內分泌系統', q:'下列何者可評估糖尿病病人過去 3 個月的血糖控制情形？', opts:['A.空腹血糖值', 'B.糖化血色素值', 'C.口服葡萄糖耐受量', 'D.飯後 2 小時血糖值'], ans:[1], expl:'本題答案為B。糖化血色素（HbA1c）反映的是血紅素與血糖結合的比例，因紅血球平均壽命約120天，故HbA1c可反映病人「過去約2～3個月」的平均血糖控制情形，是評估糖尿病長期血糖控制的重要指標，此為本題答案（B✓）。空腹血糖值、口服葡萄糖耐受量、飯後2小時血糖值僅能反映「檢測當下（單一時間點）」的血糖狀況，無法反映長期（過去3個月）的整體血糖控制情形（A✗、C✗、D✗）。'},
{n:1110, no:70, subj:'內分泌系統', q:'下列何者最可能造成病人出現昏迷、呼吸快而深、血清有效滲透壓 300 mOsm/kg、血糖值 400 mg/dL的臨床表徵？', opts:['A.蘇莫吉效應（Somogyi effect）', 'B.急性肝昏迷', 'C.糖尿病性酮酸中毒', 'D.高血糖高滲透壓狀態'], ans:[2], expl:'本題答案為C。呼吸快而深（庫斯莫氏呼吸，Kussmaul respiration）是身體代償代謝性酸中毒的典型表現，合併昏迷及血糖偏高（400 mg/dL），符合糖尿病酮酸中毒（DKA）的典型臨床表徵，此為本題答案（C✓）。蘇莫吉效應是指胰島素過量引起夜間低血糖後，身體反彈性引發清晨高血糖的現象，並非以昏迷、庫斯莫氏呼吸為特徵（A✗）；急性肝昏迷主要與肝功能衰竭、血氨蓄積有關，與本題血糖及滲透壓數值的描述不符（B✗）；高血糖高滲透壓狀態（HHS）典型血糖值通常「遠高於600 mg/dL」、血清滲透壓「顯著上升（常大於320 mOsm/kg）」，且因體內仍有足夠胰島素以抑制酮體生成，通常「不會」出現庫斯莫氏呼吸；本題血糖400 mg/dL、滲透壓300 mOsm/kg合併深快呼吸，較符合DKA而非HHS之典型表現（D✗）。'},
{n:1111, no:71, subj:'內分泌系統', q:'有關甲狀腺切除後可能發生的合併症，下列何者正確？', opts:['A.高血鈣', 'B.低血磷', 'C.體溫過低', 'D.喉返神經受損'], ans:[3], expl:'本題答案為D。甲狀腺切除術中因喉返神經與甲狀腺解剖位置緊鄰，手術操作可能不慎損傷喉返神經，導致聲帶麻痺、聲音沙啞甚至呼吸道阻塞等合併症，是甲狀腺切除術後需密切觀察的重要合併症之一，此為本題答案（D✓）。甲狀腺切除術若不慎傷及或移除鄰近之副甲狀腺，會導致副甲狀腺功能低下、造成「低血鈣」（而非高血鈣）及「高血磷」（而非低血磷），此二選項之數值方向皆有誤（A✗、B✗）；術後合併症若發生，多與低血鈣手足抽搐、出血、呼吸道阻塞等有關，並非以體溫過低為典型合併症（C✗）。'},
{n:1112, no:72, subj:'內分泌系統', q:'有關庫欣氏症候群的診斷檢查，下列何者最具特異性？', opts:['A.24 小時尿液游離皮質醇排泄量', 'B.核醫腎上腺皮質掃描', 'C.標準二天類固醇抑制試驗', 'D.蝶鞍核磁共振影像檢查'], ans:[0], expl:'本題答案為A。24小時尿液游離皮質醇排泄量可直接反映一整天皮質醇的實際分泌總量，是診斷庫欣氏症候群特異性及準確性皆高的第一線篩檢工具之一，此為本題答案（A✓）。核醫腎上腺皮質掃描及蝶鞍核磁共振影像檢查，主要用於「生化診斷確立後」，進一步定位病灶（如腎上腺腫瘤或腦下垂體腫瘤）之解剖構造，並非用於確立庫欣氏症候群本身診斷的特異性檢查（B✗、D✗）；標準二天類固醇（低劑量地塞米松）抑制試驗雖也是常用的診斷工具，屬功能性（間接）抑制測試，但依本題官方答案，24小時尿液游離皮質醇之直接測量方式，被視為本題最具特異性的答案（C✗）。'},
{n:1113, no:73, subj:'神經系統', q:'有關剛接受腦下垂體切除術後病人的護理措施，下列何者錯誤？', opts:['A.密切觀察有無低血容積與休克現象', 'B.密切觀察有無顱內壓升高的症狀', 'C.保持平躺，減少下肢靜脈回流，減輕頭痛現象', 'D.密切觀察有無腦脊髓液外滲的情形'], ans:[2], expl:'本題答案為C。腦下垂體切除術後，應鼓勵病人「適度活動」並可依醫囑逐步採漸進式坐起或下床，過度強調「保持平躺以減少下肢靜脈回流」並非此類病人術後之標準護理原則（且長期臥床平躺反而可能增加下肢靜脈栓塞等風險），此敘述並不恰當，為本題答案（C✗，題目問「何者錯誤」）。腦下垂體切除術後若合併尿崩症（ADH分泌不足），可能導致大量利尿、體液及電解質流失，需密切觀察有無低血容積及休克徵象，敘述正確（A✓）；術後仍須密切監測顱內壓升高的相關徵象（如意識程度、瞳孔反應變化），敘述正確（B✓）；經蝶骨手術路徑可能造成腦脊髓液外滲（鼻漏），需密切觀察並適時處置，敘述正確（D✓）。'},
{n:1114, no:74, subj:'內分泌系統', q:'有關抗利尿素分泌不當症候群（SIADH）病人的護理措施，下列何者錯誤？', opts:['A.遵守與執行限制液體措施', 'B.密切監測血壓、中心靜脈壓及血漿滲透壓的變化', 'C.監測有無出現肌肉抽搐或昏迷等中樞神經傷害', 'D.預防與高血鈉有關的潛在性傷害'], ans:[3], expl:'本題答案為D。抗利尿激素分泌不當症候群（SIADH）因ADH分泌過多，體內水分滯留、產生「稀釋性低血鈉」，故護理重點應著重預防與「低血鈉」（而非高血鈉）相關的潛在性傷害（如意識改變、跌倒、癲癇發作等），此敘述方向有誤，為本題答案（D✗，題目問「何者錯誤」）。SIADH因體內水分滯留過多，護理首要措施即嚴格限制液體攝取，以矯正水分過量及稀釋性低血鈉，敘述正確（A✓）；應密切監測血壓、中心靜脈壓及血漿滲透壓的變化，以評估體液狀況及治療反應，敘述正確（B✓）；嚴重低血鈉可能造成腦細胞水腫，出現肌肉抽搐、意識混亂甚至昏迷等中樞神經症狀，需密切監測，敘述正確（C✓）。'},
{n:1115, no:75, subj:'其他', q:'情境：吳先生27歲，因騎機車與卡車相撞造成左大腿骨折且有一長15公分、深3公分之撕裂傷，血流不止，送達急診時，病人體溫36℃、心跳130次／分、呼吸35次／分、血壓90/60 mmHg，皮膚冰冷潮濕，微血管充填時間大於5秒。依據吳先生目前的生理狀態，下列何者正確？', opts:['A.血管性休克', 'B.心因性休克', 'C.低血容積性休克', 'D.神經性休克'], ans:[2], expl:'本題答案為C。（本題與第76、77題共用情境：吳先生27歲，因騎機車與卡車相撞造成左大腿骨折且有一長15公分、深3公分之撕裂傷，血流不止，送達急診時體溫36℃、心跳130次／分、呼吸35次／分、血壓90/60 mmHg，皮膚冰冷潮濕，微血管充填時間大於5秒。）吳先生因外傷合併嚴重撕裂傷、血流不止，主要生理機轉為「大量體液（血液）流失」，導致有效循環血量不足、組織灌流下降，符合「低血容積性休克」的典型病理生理表現（心搏過速、低血壓、皮膚冰冷潮濕、微血管充填時間延長皆為代償性血管收縮之表現），此為本題答案（C✓）。血管性（分布性）休克是因血管異常擴張導致有效循環血量相對不足，與本題單純大量失血的機轉不同（A✗）；心因性休克是因心臟幫浦功能衰竭所致，本題並無心臟本身病變的描述（B✗）；神經性休克是因自主神經調控失衡導致血管張力喪失，通常伴隨心搏「過緩」及皮膚溫暖乾燥，與本題心搏過速、皮膚冰冷潮濕的表現不符（D✗）。'},
{n:1116, no:76, subj:'其他', q:'情境：吳先生27歲，因騎機車與卡車相撞造成左大腿骨折且有一長15公分、深3公分之撕裂傷，血流不止，送達急診時，病人體溫36℃、心跳130次／分、呼吸35次／分、血壓90/60 mmHg，皮膚冰冷潮濕，微血管充填時間大於5秒。依據吳先生的症狀與徵象估計其失血量，下列何者正確？', opts:['A.少於 750 mL', 'B.大於或等於 750～1500 mL', 'C.大於 1500～2000 mL', 'D.大於 2000 mL'], ans:[2], expl:'本題答案為C。（承第75題情境）依據休克分級：心跳130次／分（心搏過速）、呼吸35次／分（呼吸急促）、血壓90/60 mmHg（收縮壓下降）、皮膚冰冷潮濕、微血管充填時間大於5秒（明顯延遲），此組合符合失血量約達「1500～2000 mL（約佔總血量30～40%）」之第三級（Class III）低血容積性休克表現，此為本題答案（C✓）。失血量少於750 mL（Class I）通常生命徵象變化輕微，心跳血壓多仍在正常範圍，與本題明顯異常之生命徵象不符（A✗）；失血750～1500 mL（Class II）雖已出現心搏稍快及輕度血壓變化，但通常血壓仍可能維持接近正常（收縮壓下降較不明顯），程度較本題描述為輕（B✗）；失血超過2000 mL（Class IV）則常伴隨血壓「顯著崩潰」、意識極度改變甚至瀕臨心跳停止，較本題所描述之生命徵象更為嚴重危急（D✗）。'},
{n:1117, no:77, subj:'其他', q:'情境：吳先生27歲，因騎機車與卡車相撞造成左大腿骨折且有一長15公分、深3公分之撕裂傷，血流不止，送達急診時，病人體溫36℃、心跳130次／分、呼吸35次／分、血壓90/60 mmHg，皮膚冰冷潮濕，微血管充填時間大於5秒。依據吳先生的症狀與徵象，所執行之立即處置，下列何者不適宜？', opts:['A.將左大腿抬高於心臟位置，以止血帶控制出血', 'B.依醫囑給予補充液體', 'C.依醫囑補充全血或血漿', 'D.依醫囑進行腦部電腦斷層檢查'], ans:[3], expl:'本題答案為D。（承第75題情境）吳先生目前屬嚴重低血容積性休克，當務之急應著重積極的體液及血液復甦、控制出血來源，並非優先安排腦部電腦斷層檢查；除非合併明顯頭部外傷或意識程度改變高度懷疑顱內病灶，否則此刻進行非急迫性影像檢查恐延誤休克復甦的黃金時間，此處置並不適宜，為本題答案（D✓，題目問「何者不適宜」）。抬高患肢（下肢）有助促進靜脈回流；以止血帶或直接加壓等方式控制持續性外出血，是控制大量出血的必要且適宜措施，敘述適宜（A✗）；依醫囑給予輸液以擴充血容積，是低血容積性休克復甦的核心處置，敘述適宜（B✗）；嚴重失血病人依醫囑補充全血或血漿，以恢復攜氧能力及血容積，是適宜且必要的處置，敘述適宜（C✗）。'},
{n:1118, no:78, subj:'其他', q:'有關一氧化碳中毒病人之護理措施，下列何者正確？', opts:['A.給予高濃度氧氣', 'B.協助病人活動以促進一氧化碳排出', 'C.應立即協助中毒者催吐', 'D.提供解毒劑'], ans:[0], expl:'本題答案為A。一氧化碳中毒因一氧化碳與血紅素的親和力遠高於氧氣，會大量佔據血紅素結合位置形成「碳氧血紅素」，阻礙血紅素攜氧及釋氧能力，故治療首要原則是給予「高濃度氧氣」（甚至高壓氧治療），以加速置換碳氧血紅素、恢復組織供氧，此為本題答案（A✓）。一氧化碳中毒病人可能已有意識障礙或組織缺氧，應嚴格限制活動、儘量臥床休息以減少耗氧量，而非協助活動促進排出（B✗）；中毒病人若意識不清時協助催吐，有嗆咳、吸入性肺炎之高風險，屬不適當且危險之處置，一般也不建議常規催吐（C✗）；目前一氧化碳中毒並無專一性解毒劑，主要治療仍以高濃度氧氣及高壓氧為主（D✗）。'},
{n:1119, no:79, subj:'其他', q:'有關登革熱之敘述，下列何者錯誤？', opts:['A.經由埃及斑蚊或白線斑蚊叮咬人體而將登革病毒傳播到人體所引起的疾病', 'B.登革病毒進入人體後在體內繁殖，並產生菌血症，再經由病媒蚊隨血液吸入，經叮咬再傳染給其他人', 'C.出血性登革熱為一種急性的熱病', 'D.病人主訴骨骼特別痠痛難忍，故登革熱又稱斷骨熱或碎骨熱'], ans:[1], expl:'本題答案為B。登革病毒感染人體後，病毒於人體血液中繁殖並產生「病毒血症」（而非菌血症，病毒感染不使用「菌血症」一詞），再經病媒蚊叮咬吸血時將病毒帶走，進而傳染給下一位被叮咬者，本選項使用「菌血症」一詞並不正確，此敘述錯誤，為本題答案（B✗，題目問「何者錯誤」）。登革熱主要經由埃及斑蚊或白線斑蚊叮咬傳播，敘述正確（A✓）；出血性登革熱是登革熱的重症型態，屬急性熱病，敘述正確（C✓）；登革熱病人常主訴骨骼關節肌肉痠痛劇烈，故又俗稱斷骨熱或碎骨熱，敘述正確（D✓）。'},
{n:1120, no:80, subj:'泌尿系統', q:'有關 GFR 為 15 mL/min/1.73 m2 之慢性腎臟病病人之護理指導，下列何者最適當？', opts:['A.介紹阻緩腎功能惡化的措施', 'B.介紹腎臟疾病相關知識', 'C.介紹透析治療通路', 'D.介紹透析治療合併症'], ans:[2], expl:'本題答案為C。GFR為15 mL/min/1.73m²已達慢性腎臟病第五期（末期腎臟病），腎功能已嚴重衰竏，近期即可能需要開始透析治療，此階段護理指導應著重「介紹透析治療通路」（如動靜脈廔管）的建立及相關準備，以利及早規劃、避免緊急透析時措手不及，此為本題答案（C✓，最適當之護理指導）。介紹阻緩腎功能惡化的措施及疾病相關知識，較適用於腎臟病「較早期」階段，此時應更聚焦於透析準備而非延緩病程（A✗、B✗）；介紹透析治療合併症雖也重要，但在尚未開始透析前，更優先且迫切的是建立適當的透析通路，以利透析得以順利進行（D✗）。'},{n:1121, no:1, subj:'神經系統', q:'有關病毒性腦膜炎的處置，下列何者正確？', opts:['A.給予 10 天抗生素使用', 'B.使用抗病毒製劑', 'C.採症狀療法，以減輕不適', 'D.增加水分攝取，以排出毒素'], ans:[2], expl:'本題答案為C。病毒性腦膜炎多為自限性疾病，治療以症狀療法為主（如止痛、退燒、臥床休息），以減輕不適並支持病人度過病程。A錯誤：抗生素僅對細菌感染有效，對病毒無效。B錯誤：一般病毒性腦膜炎並不常規使用抗病毒製劑（抗病毒藥物主要用於特定如HSV腦炎等病原）。D「增加水分以排出毒素」並非正確的病理生理依據。'},
{n:1122, no:2, subj:'骨骼肌肉', q:'李先生是建築工人，近日因椎間盤突出入院行腰椎椎板切除術，護理師提供之術後護理指導，下列何者正確？', opts:['A.絕對臥床 3 日才可以下床活動', 'B.背架需使用 3～6 個月，只有睡覺及洗澡時可取下', 'C.出院後可立即恢復正常的活動', 'D.使用柔軟的床鋪以減輕腰背部的壓力'], ans:[1], expl:'本題答案為B。腰椎椎板切除術後配戴背架，通常需持續使用3～6個月，僅在睡覺及沐浴時才可取下，以保護脊椎癒合及維持穩定度。A錯誤：現行觀念鼓勵及早下床活動，並非絕對臥床3日。C錯誤：出院後仍須漸進式恢復活動，不可立即恢復正常活動量。D錯誤：應使用質地較硬的床墊以支撐脊椎，而非柔軟床鋪。'},
{n:1123, no:3, subj:'神經系統', q:'腦腫瘤病人進行外科手術移除腫瘤後，顱內壓仍非常高，下列何種方式可以協助降低顱內壓？', opts:['A.顱骨鑽孔術', 'B.開顱術', 'C.顱骨切除術', 'D.顱骨整形術'], ans:[2], expl:'本題答案為C。當腦腫瘤移除後顱內壓仍居高不下時，可執行顱骨切除術（decompressive craniectomy），將部分顱骨移除不放回，讓腫脹的腦組織有向外膨出的空間，達到有效減壓，是難治性顱內壓升高的標準處置方式之一。顱骨鑽孔術多用於引流（如硬腦膜下血腫），開顱術是原始手術入路，顱骨整形術則是日後修補顱骨缺損之重建手術，均非此情境下的立即降壓對策。'},
{n:1124, no:4, subj:'神經系統', q:'顱內壓升高（IICP）的臨床表徵，下列何者正確？', opts:['A.心跳增加', 'B.血壓下降', 'C.脈壓變寬', 'D.視神經萎縮'], ans:[2], expl:'本題答案為C。顱內壓升高的古氏三徵（Cushing\'s Triad）包括：收縮壓上升合併脈壓變寬、心跳變慢（非變快）、呼吸型態不規則。A錯誤：應為心跳「減慢」。B錯誤：血壓應「上升」而非下降。D視神經萎縮是長期未處理視乳頭水腫後的晚期慢性變化，並非顱內壓升高的急性典型表徵（急性期應為視乳頭水腫）。'},
{n:1125, no:5, subj:'其他', q:'有關照護 HIV 感染者及共同生活者之護理指導，下列何者正確？', opts:['A.與愛滋病毒感染者進行性行為時，肛交是危險的性交行為，口交是安全的', 'B.與愛滋病毒感染者共同生活，沒有發生性行為，不易感染 HIV 病毒', 'C.提供感染者低熱量高蛋白飲食，應避免生食，以避免感染', 'D.未取得病人同意前，可主動告知其主要照顧者有關疾病診斷及照護事項'], ans:[1], expl:'本題答案為B。HIV病毒主要透過血液、體液（精液、陰道分泌物、母乳）及垂直傳染，日常共同生活（共餐、擁抱、共用衛浴等）並無性接觸時，感染風險極低。A錯誤：口交雖風險低於肛交，仍具傳染風險，並非「安全」。C錯誤：應提供高熱量高蛋白飲食以支持免疫功能與組織修復，而非低熱量。D錯誤：基於病人隱私權，須先取得病人同意才可告知照顧者診斷，這是基本的保密倫理原則。'},
{n:1126, no:6, subj:'神經系統', q:'有關巴金森氏症的敘述，下列何者正確？', opts:['A.是一種自體免疫疾病', 'B.神經物質多巴胺分泌量增加', 'C.神經物質乙醯膽鹼分泌量減少', 'D.可能與遺傳或環境因素有關'], ans:[3], expl:'本題答案為D。巴金森氏症病因尚未完全明朗，目前實證支持其為多重因子交互作用的結果，可能與基因易感性及環境毒素暴露（如農藥、重金屬）有關。A錯誤：並非自體免疫疾病。B錯誤：其核心病理為黑質多巴胺神經元退化，多巴胺分泌是「減少」而非增加。C錯誤：因多巴胺與乙醯膽鹼相互拮抗失衡，乙醯膽鹼相對是「增加」（活性相對亢進），並非減少。'},
{n:1127, no:7, subj:'神經系統', q:'有關腦瘤之敘述，下列何者正確？①腦膜瘤好發於男性 ②續發性腦瘤常見於肺癌或乳癌病人 ③突然的發作抽搐是腦瘤的明顯指標 ④星狀細胞瘤好發於女性', opts:['A.①②', 'B.①③', 'C.②③', 'D.②④'], ans:[2], expl:'本題答案為C（②③）。②續發性（轉移性）腦瘤確實常見於肺癌或乳癌病人腦轉移。③成人突發癲癇發作，尤其無其他誘因時，是腦瘤重要的警示表徵之一，臨床上需高度懷疑。①錯誤：腦膜瘤好發於「女性」而非男性。④錯誤：星狀細胞瘤好發於「男性」而非女性。'},
{n:1128, no:8, subj:'感官系統', q:'有關青光眼藥物治療作用之敘述，下列何者錯誤？', opts:['A.可使用縮瞳劑', 'B.pilocarpine 可促進房水流入許萊姆氏管', 'C.timolol 可減少房水分泌', 'D.diamox 可促進房水排出'], ans:[3], expl:'本題答案為D（錯誤選項）。diamox（acetazolamide）為碳酸酐酶抑制劑，其降眼壓機轉是「減少房水生成」，而非促進房水排出，此為本題敘述錯誤之處。A正確：縮瞳劑（如pilocarpine）為青光眼常用藥物。B正確：pilocarpine使睫狀肌收縮，牽動小樑網開放，促使房水流入許萊姆氏管。C正確：timolol為乙型交感神經阻斷劑，可減少房水分泌。'},
{n:1129, no:9, subj:'消化系統', q:'有關上消化道出血的臨床表徵，下列何者正確？', opts:['A.大多解鮮血便', 'B.常見的原因為結腸不正常的出血', 'C.嚴重時會造成心搏過速、血壓不穩', 'D.嚴重時會造成皮膚發熱、潮紅'], ans:[2], expl:'本題答案為C。上消化道大量出血會導致血容積不足，臨床表現為代償性心搏過速及血壓不穩（甚至休克徵象）。A錯誤：上消化道出血典型為解黑便（melena）或吐血，鮮血便多見於下消化道出血。B錯誤：結腸出血屬於下消化道範疇。D錯誤：休克時皮膚應是濕冷蒼白，而非發熱潮紅。'},
{n:1130, no:10, subj:'消化系統', q:'有關小腸阻塞的臨床表徵，下列何者正確？', opts:['A.便秘', 'B.晚期才出現腹脹', 'C.嘔吐頻率增加', 'D.腸音增加'], ans:[2], expl:'本題答案為C。小腸阻塞（尤其是近端阻塞）因腸內容物無法順利通過，會反覆刺激嘔吐反射，故嘔吐頻率明顯增加，且嘔吐物可能含膽汁甚至糞臭味。A便秘／排便排氣停止多屬較後期或遠端阻塞表現。B脹氣程度依阻塞位置與時間而異，並非「晚期才出現」的絕對規則。D早期腸音可能因阻塞近端腸蠕動亢進而增加，但隨阻塞持續腸音會逐漸減弱甚至消失，「腸音增加」不足以完整描述其病程變化，故以嘔吐頻率增加為最具代表性之表徵。'},
{n:1131, no:11, subj:'消化系統', q:'病人抽出腹水 1,500 mL 後，可能出現下列何種徵象？', opts:['A.呼吸加快', 'B.心跳加快', 'C.體溫上升', 'D.血壓上升'], ans:[1], expl:'本題答案為B。大量腹水（1,500 mL）抽出後，腹內壓驟降造成血管擴張與體液重新分布，有效循環血量相對不足，會引發代償性心跳加快。A呼吸通常因腹內壓下降、橫膈活動空間增加而較為改善，不會加快。C與抽腹水無直接對應之體溫變化。D因血管擴張及有效血容積減少，血壓應「下降」而非上升。'},
{n:1132, no:12, subj:'消化系統', q:'下列何者是造成腹膜炎常見的致病菌？', opts:['A.革蘭氏陽性菌', 'B.黴菌', 'C.厭氧性細菌', 'D.真菌'], ans:[0], expl:'本題答案為A。依護理學教科書分類，「原發性（自發性細菌性）腹膜炎」常見致病菌為大腸桿菌及嗜氧性革蘭氏陽性腸內菌（如鏈球菌屬Streptococcus），此為國考常考重點，與續發性腹膜炎（因腸穿孔等造成，常為革蘭氏陰性菌合併厭氧菌混合感染）致病菌相不同。本題所問之「常見致病菌」即對應此原發性腹膜炎之經典教學重點，故答案為革蘭氏陽性菌。B、D黴菌／真菌性腹膜炎較少見。C厭氧性細菌為續發性腹膜炎常見菌相，非本題所問之常見致病菌類型。'},
{n:1133, no:13, subj:'消化系統', q:'病人主訴「左上腹疼痛，吃了東西後 1 小時更痛」，下列何者為其最可能之診斷？', opts:['A.胃食道逆流', 'B.慢性胃炎', 'C.胃潰瘍', 'D.十二指腸潰瘍'], ans:[2], expl:'本題答案為C。胃潰瘍的典型疼痛型態為進食後約30分鐘至1小時內疼痛加劇（因食物刺激胃酸分泌，且潰瘍處黏膜對擴張敏感），與題述「吃了東西後1小時更痛」相符。A胃食道逆流疼痛型態與姿勢、臥躺相關性較高。B慢性胃炎疼痛型態較不具此特異性時序。D十二指腸潰瘍典型是進食後疼痛「緩解」，於空腹或夜間（進食後2～3小時）疼痛加劇，恰與本題相反。'},
{n:1134, no:14, subj:'骨骼肌肉', q:'病人骨盆骨折後第 2 天，突然發生意識改變、呼吸與心跳加速、瘀斑及發燒等徵象，下列何者為病人最可能發生的問題？', opts:['A.腔隙症候群', 'B.脂肪栓塞症候群', 'C.骨頭感染致敗血症', 'D.動脈損傷致內出血'], ans:[1], expl:'本題答案為B。骨盆或長骨骨折後1～3天內出現意識改變、呼吸急促、心搏過速、皮膚瘀斑（petechiae，常見於前胸、腋下、結膜）及發燒，是脂肪栓塞症候群（Fat Embolism Syndrome）的典型三大表徵（呼吸、神經、皮膚瘀斑），為骨科創傷重要且經典的併發症。A腔隙症候群（compartment syndrome）主要表現為患肢劇痛、感覺異常、脈搏減弱，非全身性瘀斑發燒表現。C骨髓炎致敗血症進程較慢，非典型於術後第2天。D動脈損傷致內出血通常會有低血容性休克徵象，而非瘀斑發燒之組合。'},
{n:1135, no:15, subj:'骨骼肌肉', q:'有關左側脛骨骨折病人使用柺杖之護理指導，下列何者錯誤？', opts:['A.三點式步態：兩側柺杖與左下肢同時向前，然後右下肢跟上', 'B.柺杖頂部距腋下二橫指，身體重心放於腋下', 'C.上樓梯順序：右下肢先上階梯，然後柺杖及左下肢同時上', 'D.左下肢可以承受重量時，可用兩點式步態'], ans:[1], expl:'本題答案為B（錯誤選項）。使用柺杖時，柺杖頂端應距離腋下約二橫指寬，體重應由「雙手掌心」承重，而非讓身體重心壓在腋下，若長期於腋下承重，恐壓迫臂神經叢造成柺杖麻痺（crutch palsy），此為本題錯誤之處。A三點式步態（患側下肢與雙柺同時前進，健側下肢跟上）描述正確。C上樓梯「好腳先上、柺杖與患肢隨後」之口訣正確。D患肢可負重後採兩點式步態亦為正確之漸進原則。'},
{n:1136, no:16, subj:'神經系統', q:'有關脊髓攝影術檢查前後之護理措施，下列何者錯誤？', opts:['A.檢查前需禁食 8 小時', 'B.檢查前確認是否對碘製劑過敏', 'C.水性顯影劑檢查後需立即平躺 8 小時', 'D.檢查後需補充大量水分'], ans:[2], expl:'本題答案為C（錯誤選項）。使用水性顯影劑（非離子型）進行脊髓攝影術後，應採半坐臥或抬高床頭姿勢（約30～45度）數小時，避免顯影劑逆流至顱內誘發癲癇，「立即平躺8小時」的敘述是錯誤的，此為離子型油性顯影劑時代的舊做法。A檢查前禁食8小時正確，可減少嘔吐、誤吸風險。B檢查前應確認是否對碘過敏（顯影劑含碘）正確。D檢查後鼓勵大量攝取水分以加速顯影劑代謝排出，並預防頭痛，正確。'},
{n:1137, no:17, subj:'骨骼肌肉', q:'針對退化性關節炎病人之護理指導，下列何者不適當？', opts:['A.冰敷有助減輕炎症反應以緩解疼痛', 'B.使用 aspirin 止痛時，避免空腹服用', 'C.日常活動應儘量採等長運動以減少關節負重之壓力', 'D.鼓勵病人減重，以減輕膝關節的負荷'], ans:[2], expl:'本題答案為C（不適當選項）。退化性關節炎的日常活動指導應著重關節保護與適度、規律的低衝擊有氧運動（如散步、游泳）以維持關節活動度與肌力，而非以「等長運動」取代日常活動的關節保護原則，此種以單一運動型態涵蓋日常活動關節減壓的說法並不周全，故列為不適當。A冰敷可減輕發炎疼痛，於急性發炎期適用。B使用aspirin等NSAIDs應避免空腹服用以防腸胃刺激，正確。D減重可直接降低膝關節負重，為重要衛教重點，正確。'},
{n:1138, no:18, subj:'感官系統', q:'有關中耳手術後病人護理措施及指導之敘述，下列何者錯誤？', opts:['A.觀察是否發生顏面神經切斷的合併症', 'B.咳嗽或打噴嚏時避免張口', 'C.避免頭部突然轉動', 'D.採軟質飲食'], ans:[1], expl:'本題答案為B（錯誤選項）。中耳手術後咳嗽或打噴嚏時，應指導病人「張口」，以避免咽鼓管壓力經由中耳腔傳導造成術部損傷或聽小骨移位，「避免張口」的敘述方向錯誤。A觀察是否出現顏面神經受損（如口角歪斜、無法閉眼）為術後重要合併症監測，正確。C避免頭部突然轉動以防影響前庭平衡及傷口，正確。D採軟質飲食以減少咀嚼時對術耳部位的震動影響，正確。'},
{n:1139, no:19, subj:'感官系統', q:'有關白內障治療方式之敘述，下列何者錯誤？', opts:['A.白內障無有效治療的藥物', 'B.囊內摘除術易造成網膜剝離', 'C.晶體乳化法為囊外摘除術', 'D.人工水晶體可在晶體乳化術後一個月植入'], ans:[3], expl:'本題答案為D（錯誤選項）。現行標準做法是人工水晶體於「晶體乳化術當次手術中立即植入」，並非延後一個月植入，此敘述錯誤。A目前尚無藥物可治癒白內障，手術摘除仍是唯一根治方式，正確。B囊內摘除術（連同水晶體囊一併移除）因玻璃體支撐結構改變，確實較易併發視網膜剝離，正確。C晶體乳化法屬於囊外摘除術的一種改良術式（保留後囊），正確。'},
{n:1140, no:20, subj:'腫瘤血液', q:'有關鼻咽癌之敘述，下列何者錯誤？', opts:['A.為上皮細胞癌', 'B.與遺傳有關', 'C.長期吸菸為致癌因子', 'D.血清 EB 病毒指數高'], ans:[3], expl:'本題答案為D。鼻咽癌為上皮細胞癌（A正確），與家族遺傳易感性有關，好發於華南／台灣等特定族群（B正確），長期吸菸亦為其致癌危險因子之一（C正確）。鼻咽癌與EB病毒感染有密切相關性，血清EB病毒相關抗體（如VCA-IgA）常作為篩檢及預後追蹤的參考指標，惟此為「風險關聯及腫瘤標記」而非鼻咽癌本身必然呈現的絕對臨床病程敘述，官方標準答案將此列為相對不精確的敘述，讀者可留意EBV在鼻咽癌中的角色定位為關聯性標記，而非诊断唯一依據。'},
{n:1141, no:21, subj:'感官系統', q:'有關喉癌的臨床表徵，下列何者正確？', opts:['A.外生性喉癌易發生頸部淋巴轉移，造成頸部淋巴結腫大', 'B.外生性喉癌會有聲音嘶啞、喉部異物感', 'C.內生性喉癌早期症狀為吞嚥時發生喉痛、灼熱感', 'D.內生性喉癌好發於喉部真聲帶以外之其他部位'], ans:[0], expl:'本題答案為A。外生性（增殖型）喉癌好發於淋巴引流豐富的部位（如聲門上區），較易發生頸部淋巴結轉移腫大。B外生性喉癌因較不侵犯真聲帶，早期聲音嘶啞並不明顯，多以喉部異物感為主。C內生性（浸潤型）喉癌好發於真聲帶，早期典型表徵是聲音嘶啞，而非吞嚥疼痛灼熱感。D內生性喉癌恰好較好發於真聲帶本身，而非真聲帶以外之其他部位。'},
{n:1142, no:22, subj:'心臟血管', q:'冠狀動脈繞道手術後病人送至加護病房時，下列何種徵象必須立即通知醫師？', opts:['A.體溫 35℃', 'B.血壓 90/60 mmHg', 'C.胸管引流量 200 mL/hr', 'D.SaO2 90～92%'], ans:[2], expl:'本題答案為C。冠狀動脈繞道手術後，胸管引流量達200 mL/hr屬於明顯偏高之出血量（一般警戒值約為超過100～150 mL/hr持續發生），需高度懷疑術後出血或心包填塞風險，必須立即通知醫師處理。A體溫35℃為體外循環術後常見之輕度低體溫，屬預期範圍，予以復溫即可。B血壓90/60 mmHg對術後病人而言多屬可接受範圍，非絕對危急值。D SaO2 90～92%雖偏低，仍需視整體臨床情況判斷，急迫性低於大量胸管出血。'},
{n:1143, no:23, subj:'心臟血管', q:'有關中心靜脈壓升高之原因，下列何者錯誤？', opts:['A.心肌梗塞', 'B.二尖瓣逆流', 'C.心包膜填塞', 'D.敗血性休克'], ans:[3], expl:'本題答案為D（錯誤選項）。敗血性休克（尤其早期溫暖休克期）主要病理生理是全身血管擴張及微血管通透性增加，導致有效循環血量相對不足及靜脈回流減少，中心靜脈壓應是「下降」而非升高，此為本題錯誤之處。A心肌梗塞可能合併心衰竭或右心室侵犯，使中心靜脈壓上升，正確。B二尖瓣逆流造成血液逆流回左心房，長期可使肺循環及右心系統壓力上升、中心靜脈壓升高，正確。C心包膜填塞為中心靜脈壓升高之經典病因（Beck氏三徵之一），正確。'},
{n:1144, no:24, subj:'心臟血管', q:'有關急性心肌梗塞病人採限鈉飲食之敘述，下列何者正確？', opts:['A.可改善現存水腫問題，並提高心臟效能', 'B.可預防因組織水腫所導致的血壓升高', 'C.可避免水分滯留，以減少心臟工作負荷', 'D.可產生利尿效果，並減少循環血量'], ans:[2], expl:'本題答案為C。限鈉飲食可減少體內水分滯留，進而降低心臟前負荷、減輕心臟做工負擔，此為急性心肌梗塞病人限鈉飲食最直接且核心的生理依據。A「提高心臟效能」的敘述並非限鈉飲食之作用機轉，限鈉為預防性措施而非直接提升心肌收縮效能。B血壓升高與組織水腫之因果連結並非教學重點所述之機轉。D限鈉本身不具「利尿」作用，利尿需仰賴利尿劑，兩者機轉不同。'},
{n:1145, no:25, subj:'心臟血管', q:'有關冠狀動脈疾病治療藥物之敘述，下列何者正確？', opts:['A.心絞痛使用 nitroglycerin（NTG），必須密切監測心搏出量', 'B.心絞痛使用 propranolol（inderal），主要作用是擴張動脈，減輕心臟後負荷', 'C.心肌梗塞使用 morphine，可以減輕疼痛並且降低心臟前負荷', 'D.心肌梗塞使用 heparin，需要密切監測凝血酶原時間（PT）'], ans:[2], expl:'本題答案為C。Morphine用於心肌梗塞止痛時，除鎮痛及緩解焦慮外，尚具有周邊靜脈擴張作用，可減少靜脈回流、降低心臟前負荷，並緩解肺充血，此為MONA（Morphine-Oxygen-Nitrates-Aspirin）急性處置原則之經典教學。A NTG監測重點應為「血壓」（避免低血壓），而非心搏出量。B propranolol為乙型阻斷劑，主要藉降低心跳速率與心肌收縮力減少心肌耗氧，並非「擴張動脈」，其降低的是心臟前負荷相關之心跳與收縮力，並非直接作用於後負荷之動脈擴張。D Heparin（未分屑肝素）應監測「aPTT」，PT／INR是用於監測warfarin（口服抗凝劑），兩者不可混淆。'},
{n:1146, no:26, subj:'心臟血管', q:'60 歲的王太太是退休公務員，平日在家日常生活活動都靠家人幫忙，休息時仍感呼吸喘，晚上常因呼吸不順無法入睡，根據美國紐約心臟學會（NYHA）的心臟功能分級標準，上述情況何者正確？', opts:['A.第一級', 'B.第二級', 'C.第三級', 'D.第四級'], ans:[3], expl:'本題答案為D。題述病人休息時仍感呼吸喘、夜間因呼吸不順而無法入睡，顯示其在「休息狀態」下即出現症狀，符合NYHA心臟功能分級「第四級」（休息時即有症狀，稍加活動即使不適加劇）之定義。第一級無症狀限制；第二級為輕度限制（休息無症狀，一般活動略有不適）；第三級為明顯限制（休息無症狀，輕度活動即有不適），均與題述「休息時仍喘」不符。'},
{n:1147, no:27, subj:'心臟血管', q:'針對左心室射出率（EVEF）為 12%，有端坐呼吸且雙側下肢水腫厲害的心臟衰竭病人之護理，下列何者較不適當？', opts:['A.協助採半坐臥姿勢以維持呼吸順暢', 'B.指導飲食限水、限鹽的方法', 'C.抬高雙腳 30 度以上以利改善水腫', 'D.監測並記錄體重變化及攝入與排出量'], ans:[2], expl:'本題答案為C（較不適當）。此心臟衰竭病人已有端坐呼吸與嚴重下肢水腫，屬體液負荷過重之失代償狀態，若將雙腳抬高30度以上，會使下肢靜脈回流量增加，反而加重心臟前負荷及肺充血、惡化端坐呼吸，故此措施較不適當。A協助採半坐臥姿勢可減少靜脈回流、減輕肺充血，改善呼吸，適當。B限水限鹽飲食為心衰竭基本治療原則，適當。D監測體重及攝入排出量以評估體液平衡狀態，為必要且適當之護理措施。'},
{n:1148, no:28, subj:'心臟血管', q:'評估脈搏強度時，發現「很難摸得到，脈搏明顯的減弱」，下列紀錄何者正確？', opts:['A.0', 'B.1＋', 'C.2＋', 'D.3＋'], ans:[1], expl:'本題答案為B。依脈搏強度評估之0～4+分級標準：0為完全觸摸不到；1＋為脈搏微弱、不易觸摸到（即題述「很難摸得到，脈搏明顯減弱」）；2＋為正常；3＋為增強；4＋為洪脈（bounding）。故本題應記錄為1＋。'},
{n:1149, no:29, subj:'骨骼肌肉', q:'有關骨掃描的敘述，下列何者正確？', opts:['A.檢查前要禁食', 'B.檢查體內細胞葡萄糖代謝過程', 'C.體內注入已標記放射性物質的腫瘤抗體', 'D.靜脈注射放射線同位素，可診斷骨轉移'], ans:[3], expl:'本題答案為D。骨掃描（bone scan）之原理為靜脈注射含鎝-99m標記之磷酸鹽類放射性同位素，該物質會聚集於骨骼代謝活躍處（如骨轉移病灶），經由伽瑪攝影機顯像，可及早偵測骨轉移，此為其臨床應用之核心敘述。A骨掃描檢查前不需禁食，此為錯誤敘述。B「檢測體內細胞葡萄糖代謝過程」為正子斷層造影（PET）之原理，非骨掃描。C「注入已標記放射性物質的腫瘤抗體」則是屬於免疫閃爍造影（radioimmunoscintigraphy）之技術，並非傳統骨掃描所使用之方式。'},
{n:1150, no:30, subj:'腫瘤血液', q:'有關惡性貧血病人特徵之敘述，下列何者錯誤？', opts:['A.紅血球數目減少', 'B.紅血球外觀小且形狀不規則', 'C.膽紅素上升', 'D.舌炎、皮膚發黃'], ans:[1], expl:'本題答案為B（錯誤選項）。惡性貧血（維生素B12缺乏）造成的是「巨球性貧血」，紅血球外觀應為體積「巨大」且形狀不規則（卵圓形巨紅血球），而非體積小，此為本題錯誤之處（小球性貧血常見於缺鐵性貧血，機轉不同）。A紅血球數目減少符合貧血定義，正確。C因無效造血及紅血球破壞增加，膽紅素會上升，正確。D典型會有舌炎及因輕度溶血造成之皮膚泛黃，正確。'},
{n:1151, no:31, subj:'腫瘤血液', q:'有關干擾素治療之敘述，下列何者正確？', opts:['A.屬主動免疫，使人體產生抗癌細胞的抗體', 'B.常使用深部肌肉注射方式給藥', 'C.高劑量可增加抗體合成及淋巴球增殖', 'D.常見副作用為頭痛、發燒、食慾降低等類似感冒症狀'], ans:[3], expl:'本題答案為D。干擾素治療常見副作用為類似感冒的全身症狀，包括發燒、頭痛、肌肉痠痛、食慾降低、倦怠等，是臨床衛教病人預作心理準備的重點。A干擾素主要透過調節免疫反應及直接抗病毒、抗腫瘤增生作用發揮療效，並非誘導人體產生抗體之主動免疫機轉。B干擾素給藥途徑以皮下注射較為常見，並非深部肌肉注射。C高劑量干擾素反而可能造成骨髓抑制，使白血球及淋巴球數目「降低」，而非增加抗體合成及淋巴球增殖。'},
{n:1152, no:32, subj:'腫瘤血液', q:'有關上腔靜脈症候群之敘述，下列何者錯誤？', opts:['A.常見原因是淋巴結腫大壓迫，影響血液回流', 'B.臨床症狀在晚上最為明顯', 'C.體外放射線照射是最常用的治療方式', 'D.呼吸困難時宜採半坐臥'], ans:[1], expl:'本題答案為B（錯誤選項）。上腔靜脈症候群因夜間平躺時，頭頸部靜脈回流受阻更明顯，症狀（臉部頸部腫脹、靜脈怒張）多在「清晨剛起床時最為明顯」，白天採坐姿或站立後會逐漸改善，並非「晚上最明顯」，此為本題錯誤之處。A腫大淋巴結壓迫上腔靜脈（如肺癌、淋巴瘤）確為常見病因，正確。C體外放射線治療為上腔靜脈症候群（尤其惡性腫瘤引起者）最常用之第一線治療方式，正確。D呼吸困難時採半坐臥可減輕頭頸部靜脈鬱血，正確。'},
{n:1153, no:33, subj:'其他', q:'下列何者是瀕死病人最後消失的知覺？', opts:['A.味覺', 'B.觸覺', 'C.聽覺', 'D.嗅覺'], ans:[2], expl:'本題答案為C。安寧緩和照護及瀕死照護之經典教學指出，聽覺是瀕死病人最後消失的知覺，因此即使病人意識不清或處於彌留狀態，仍鼓勵家屬持續在病人耳邊說話、給予陪伴與情感支持，此為臨床照護重要原則。'},
{n:1154, no:34, subj:'腫瘤血液', q:'有關多發性骨髓瘤的臨床症狀，下列何者錯誤？', opts:['A.骨痛', 'B.腎功能不全', 'C.腹瀉', 'D.貧血'], ans:[2], expl:'本題答案為C（錯誤選項）。多發性骨髓瘤的經典臨床表現可以「CRAB」原則歸納：高血鈣（Calcium）、腎功能不全（Renal）、貧血（Anemia）、骨病灶／骨痛（Bone lesions），並不包含腹瀉，故腹瀉為本題錯誤之敘述。A骨痛因蝕骨性病灶所致，正確。B腎功能不全常因輕鏈蛋白（本斯瓊氏蛋白）沉積腎小管所致，正確。D貧血因骨髓被漿細胞浸潤取代正常造血功能所致，正確。'},
{n:1155, no:35, subj:'腫瘤血液', q:'有關急性骨髓性白血病病人在接受異體骨髓移植後 3 週，出現全身紅疹與腹瀉症狀，下列敘述何者錯誤？', opts:['A.應注意肝功能異常與血中膽紅素上升', 'B.可進行皮膚切片以確定問題', 'C.皮膚同時可能會出現斑丘疹', 'D.顯示為嚴重藥物過敏'], ans:[3], expl:'本題答案為D（錯誤選項）。異體骨髓移植後3週左右出現全身性紅疹合併腹瀉，屬急性移植物抗宿主疾病（acute GVHD）之典型三大侵犯部位表現（皮膚、腸胃道、肝臟），並非藥物過敏，此為本題錯誤之處，是骨髓移植病房極重要且經典的鑑別診斷概念。A急性GVHD亦常侵犯肝臟，故應注意肝功能與膽紅素上升，正確。B皮膚切片有助於確診GVHD，正確。C皮膚可能同時出現斑丘疹，為GVHD典型皮膚表現，正確。'},
{n:1156, no:36, subj:'腫瘤血液', q:'有關乳癌轉移壓迫脊髓最常見之部位，下列何者正確？', opts:['A.頸椎', 'B.胸椎', 'C.腰椎', 'D.薦椎'], ans:[1], expl:'本題答案為B。骨骼轉移好發部位以脊椎最常見，其中因胸椎椎體數目多、血流供應豐富（巴特森氏靜脈叢），是脊椎轉移最常發生的節段，乳癌轉移壓迫脊髓亦以胸椎最為常見，為腫瘤護理學重要教學重點。'},
{n:1157, no:37, subj:'腫瘤血液', q:'有關癌症初級預防之敘述，下列何者錯誤？', opts:['A.避免隨便服藥、減少菸酒', 'B.均衡飲食，多吃新鮮蔬菜、水果', 'C.養成規律運動習慣', 'D.定期接受身體檢查'], ans:[3], expl:'本題答案為D（錯誤選項）。定期身體檢查（篩檢）目的在於「早期發現」已存在但尚未有症狀的疾病，屬於「次級預防」範疇，而非以避免疾病發生為目標的「初級預防」，此為本題錯誤之處（分類錯置）。A避免亂服藥物、減少菸酒為降低致癌因子暴露之初級預防措施，正確。B均衡飲食、多吃蔬果為降低致癌風險之初級預防措施，正確。C規律運動有助降低多種癌症風險，屬初級預防範疇，正確。'},
{n:1158, no:38, subj:'腫瘤血液', q:'下列何者屬於發疱劑（vesicant agent）的化學治療製劑？', opts:['A.ara-C', 'B.bleomycin', 'C.endoxan', 'D.oncovin'], ans:[3], expl:'本題答案為D。長春鹼類藥物oncovin（vincristine）為化學治療中經典的發疱劑（vesicant），一旦滲漏至血管外，可造成嚴重組織壞死及水疱，臨床給藥時須特別留意輸注部位與滲漏徵象。A ara-C（cytarabine）、B bleomycin、C endoxan（cyclophosphamide）均屬於刺激性藥物（irritant）或非發疱性藥物，滲漏之組織傷害程度較輕。'},
{n:1159, no:39, subj:'腫瘤血液', q:'B 型肝炎帶原者接受化學治療時之護理指導，下列何者錯誤？', opts:['A.可以採用親朋好友所提供的保肝偏方', 'B.出入公共場所儘量戴口罩', 'C.若白血球數目太低，可多吃剝皮的水果補充維生素', 'D.若皮膚或眼白變黃、食慾變差，則趕快就醫'], ans:[0], expl:'本題答案為A（錯誤選項）。B型肝炎帶原者接受化療期間，肝功能較脆弱，應避免使用未經證實的偏方或保肝藥物，以免加重肝臟負擔或與治療產生交互作用，「採用親友偏方」是不恰當且具風險的建議，此為本題錯誤之處。B化療期間白血球易低下，出入公共場所戴口罩以預防感染，正確。C嗜中性白血球低下期間宜採低菌飲食，水果去皮可降低感染風險，正確。D皮膚眼白變黃、食慾變差可能提示肝炎急性發作或肝功能惡化，應儘速就醫，正確。'},
{n:1160, no:40, subj:'腫瘤血液', q:'有關病毒感染與罹患癌症相關性之敘述，下列何者錯誤？', opts:['A.A 型肝炎病毒導致肝癌', 'B.EB 病毒導致鼻咽癌', 'C.巨細胞病毒導致子宮頸癌', 'D.幽門螺旋桿菌導致胃癌'], ans:[0], expl:'本題答案為A（錯誤選項）。A型肝炎病毒感染為急性、通常可自行痊癒之病毒感染，並不會演變為慢性肝炎，故與肝癌無直接因果關係，此與B型、C型肝炎病毒（會導致慢性感染並顯著增加肝癌風險）不同，是護理及公共衛生教學中重要的鑑別概念，此為本題錯誤之處。B EB病毒與鼻咽癌之相關性已為醫學實證所支持，正確。C、D分別為子宮頸癌與胃癌相關致病原之敘述，官方答案歸類為正確選項。'},
{n:1161, no:41, subj:'其他', q:'有關燒傷病人給與靜脈滴注「H2 受體阻斷劑」類藥物（如 tagamet）之目的，下列何者正確？', opts:['A.刺激腸蠕動', 'B.預防低血容積', 'C.預防壓力性潰瘍', 'D.預防腎損傷'], ans:[2], expl:'本題答案為C。燒傷病人因生理壓力狀態易誘發壓力性潰瘍（如Curling\'s ulcer），靜脈滴注H2受體阻斷劑（如tagamet/cimetidine）可抑制胃酸分泌，達到預防壓力性潰瘍之目的，是燒傷急性期常規預防性用藥的重要教學重點。A、B、D皆非H2受體阻斷劑之主要藥理作用機轉。'},
{n:1162, no:42, subj:'其他', q:'有關燒傷水療法之敘述，下列何者錯誤？', opts:['A.水療池的水溫通常維持在 26.6～29.4℃', 'B.水療池中可加入 Beta-iodine，以抑制細菌生長', 'C.水療池中可加入食鹽，以補充流失的體液', 'D.水療法可以降低感染以及減少瘢痕形成'], ans:[0], expl:'本題答案為A（錯誤選項）。燒傷水療池水溫應維持在接近體溫之溫水範圍（一般教學建議約37℃上下），以避免病人因體表燒傷、體溫調節能力受損而併發低體溫，題述26.6～29.4℃明顯偏低，此為本題錯誤之處。B水療池加入Beta-iodine可抑制細菌生長、預防感染，正確。C加入食鹽有助補充經燒傷創面流失之電解質，正確。D水療法可協助清創、降低感染並減少疤痕攣縮形成，正確。'},
{n:1163, no:43, subj:'其他', q:'王先生從火災現場被救出，評估發現其鼻毛燒焦、聲音嘶啞、喘鳴聲、碳粒痰、呼吸有燒焦味，下列何者為王先生最可能的診斷？', opts:['A.一氧化碳中毒', 'B.電燒傷', 'C.吸入性灼傷', 'D.化學性灼傷'], ans:[2], expl:'本題答案為C。鼻毛燒焦、聲音嘶啞、喘鳴聲、碳粒痰、呼吸有燒焦味，是吸入性灼傷（吸入性呼吸道損傷）的經典臨床表徵組合，提示上呼吸道及氣管黏膜因熱及煙霧吸入而受損，需高度警覺呼吸道阻塞風險並及早評估插管必要性。A一氧化碳中毒主要表現為頭痛、意識改變、皮膚呈櫻桃紅等缺氧相關症狀，並非以聲音嘶啞、碳粒痰等呼吸道局部徵象為主要表現。B、D電燒傷及化學性灼傷與火場煙霧吸入情境不符。'},
{n:1164, no:44, subj:'其他', q:'有關焦痂切開術的敘述，下列何者正確？', opts:['A.適用於環形燒傷（circumferential burns），切開時無需麻醉', 'B.適用於輻射性燒傷（radiation burns），切開時需要麻醉', 'C.為了減壓而切開傷口，故切開後的傷口不宜包紮', 'D.若焦痂切開術後仍無法改善組織灌流時，可進一步執行筋膜切開術'], ans:[3], expl:'本題答案為D。若焦痂切開術後肢體組織灌流仍未獲得改善（表示深層肌肉筋膜腔室壓力仍過高），需進一步執行筋膜切開術（fasciotomy）以徹底減壓，此為環形燒傷合併疑似腔室症候群處置之標準漸進步驟。焦痂切開術主要適用於因環狀焦痂造成外部壓迫、影響肢體或胸廓灌流及通氣的情況，其餘選項在焦痂切開術之麻醉需求、適應症及術後傷口處置細節上，與臨床標準做法有所出入。'},
{n:1165, no:45, subj:'其他', q:'有關燒傷病人的緊急處理措施 5 步驟之敘述，下列何者錯誤？', opts:['A.沖：以流動的冷水沖患部', 'B.脫：用剪刀移除衣物，若衣物與傷口沾黏，勿強行脫除', 'C.泡：將患部泡在冰水中降溫，將餘熱去除減輕疼痛感', 'D.蓋：以乾淨的衣物、毛毯、紗布等覆蓋，保存體溫且避免污染傷口'], ans:[2], expl:'本題答案為C（錯誤選項）。燒傷急救「沖脫泡蓋送」五步驟中，「泡」步驟應以「冷水」（非冰水）持續浸泡降溫，若使用冰水，反而可能造成血管過度收縮、加重組織缺血損傷，甚至誘發低體溫，尤其大面積燒傷病人更應避免，此為本題錯誤之處。A以流動冷水沖洗患部正確。B使用剪刀移除衣物，沾黏傷口處不強行剝除，正確。D以乾淨物品覆蓋創面以保溫並避免污染，正確。'},
{n:1166, no:46, subj:'其他', q:'有關後天免疫之敘述，下列何者錯誤？', opts:['A.是一種經由與特定病原體接觸後，產生能識別並針對特定病原體啟動的免疫反應', 'B.主動性後天免疫是人體接觸病原體後，製造抗體或淋巴球而產生的免疫能力', 'C.注射含抗體的血清或免疫球蛋白是屬於主動性後天免疫', 'D.經母體胎盤傳給胎兒或嬰兒，經由母乳獲得之免疫力屬於被動性後天免疫'], ans:[2], expl:'本題答案為C（錯誤選項）。注射含現成抗體的血清或免疫球蛋白，抗體並非由病人自身免疫系統產生，屬於「被動性」後天免疫，而非主動性後天免疫，此為本題錯誤之處，是免疫學主動／被動免疫分類的基本概念。A後天免疫確實是接觸特定病原體後產生針對性免疫反應，正確。B主動性後天免疫確實是由人體自行製造抗體或致敏淋巴球而來，正確。D經胎盤或母乳獲得之抗體屬於被動性後天免疫，正確。'},
{n:1167, no:47, subj:'骨骼肌肉', q:'下列何者為自體免疫血清反應之實驗室檢查？', opts:['A.紅血球沉降率', 'B.抗核抗體（ANA）', 'C.滑膜液', 'D.C 反應蛋白質'], ans:[1], expl:'本題答案為B。抗核抗體（ANA）是評估全身性自體免疫疾病（如全身性紅斑性狼瘡）最具代表性的自體免疫血清學檢查項目。A紅血球沉降率（ESR）與D C反應蛋白（CRP）皆為非特異性發炎指標，並非專屬自體免疫血清反應之檢查。C滑膜液分析屬於關節液檢查，非血清免疫學檢驗項目。'},
{n:1168, no:48, subj:'骨骼肌肉', q:'有關類風溼性關節炎流行病學之敘述，下列何者錯誤？', opts:['A.男性的發生率是女性的 3 倍', 'B.30～50 歲是發生的高峰期', 'C.冬天的發生率高於夏天', 'D.可能發生於 80 歲的老人'], ans:[0], expl:'本題答案為A（錯誤選項）。類風溼性關節炎的流行病學特徵是女性發生率明顯高於男性（約為男性的2～3倍），與題述「男性是女性的3倍」恰好相反，此為本題錯誤之處。B 30～50歲確為好發高峰期，正確。C氣候寒冷潮濕（冬季）常使症狀加劇，此為教學上常見之關聯性敘述，正確。D類風溼性關節炎雖好發於中年，但高齡族群（如80歲）仍可能發病，正確。'},
{n:1169, no:49, subj:'其他', q:'HIV 抗體試驗呈陽性，且 T4 細胞數目為 650 cells/mm3、占所有淋巴球之 35%的病人，最可能處在HIV 疾病那一期？', opts:['A.空窗期', 'B.潛伏期', 'C.急性感染期', 'D.伺機性感染期'], ans:[1], expl:'本題答案為B。此病人HIV抗體檢驗已呈陽性（表示已度過空窗期），且T4（CD4）細胞數目650 cells/mm3仍屬相對保留範圍（尚未降至伺機性感染好發之200以下），符合HIV感染「潛伏期（臨床無症狀期）」的表現，此階段病人可能無明顯症狀，但病毒持續在體內複製。A空窗期病人抗體檢驗應為陰性，與題述抗體陽性不符。C急性感染期CD4數目常呈短暫下降，且此時期抗體多尚未轉為陽性。D伺機性感染期CD4數目通常已顯著降低（多低於200），與題述650不符。'},
{n:1170, no:50, subj:'呼吸系統', q:'評估右下肺葉時叩診出現濁音及聽診時呼吸音減弱，胸部 X 光檢查結果右側肋膜橫膈角呈鈍角，下列何者為病人最可能之診斷？', opts:['A.右下肺葉肺炎', 'B.右側氣胸', 'C.右側肋膜積水', 'D.右下肺葉腫瘤'], ans:[2], expl:'本題答案為C。右下肺葉叩診濁音、聽診呼吸音減弱，加上胸部X光顯示肋膜橫膈角變鈍（costophrenic angle blunting），是肋膜腔積水的經典三合一診斷表現。A肺炎典型會有呼吸音「增強」（支氣管呼吸音）及囉音，而非呼吸音減弱。B氣胸叩診應為過度共鳴音（非濁音），且呼吸音消失而非單純減弱。D單純肺腫瘤較不會直接造成肋膜橫膈角變鈍此一積液特徵性表現。'},
{n:1171, no:51, subj:'呼吸系統', q:'肺栓塞病人於血栓形成後 72 小時內，可給與下列何種藥物以快速溶解血塊？', opts:['A.aspirin', 'B.heparin', 'C.streptokinase', 'D.warfarin'], ans:[2], expl:'本題答案為C。streptokinase為血栓溶解劑（thrombolytic），可直接活化纖維蛋白溶解系統，快速溶解已形成之血栓，適用於發生後72小時內之嚴重肺栓塞。A aspirin為抗血小板藥物，並無溶解血塊之作用。B heparin、D warfarin皆屬抗凝血劑，作用在「預防新血栓形成或延展」，並不能主動溶解已存在之血塊。'},
{n:1172, no:52, subj:'呼吸系統', q:'肺栓塞病人使用肝素以阻止新的血塊形成，通常須維持部分凝血活酶時間（aPTT）為正常值的多少倍？', opts:['A.1.0～1.4', 'B.1.5～2.5', 'C.2.6～3.5', 'D.3.6～4.5'], ans:[1], expl:'本題答案為B。使用heparin治療肺栓塞時，須監測部分凝血活酶時間（aPTT），並將其維持在正常值的1.5～2.5倍，作為抗凝治療有效且相對安全的治療範圍，此為臨床藥物學重要監測數值。'},
{n:1173, no:53, subj:'呼吸系統', q:'肺葉切除術後，常放置兩支胸管引流，下列敘述何者正確？', opts:['A.一支置於腋中線的第二肋間引流液體，另一支置於胸前第八及第九肋間處引流肋膜腔下方的空氣', 'B.一支置於腋中線的第二肋間引流空氣，另一支置於胸前第八及第九肋間處引流肋膜腔下方的液體', 'C.一支置於胸前的第二肋間引流空氣，另一支置於腋中線第八及第九肋間處引流肋膜腔下方的液體', 'D.一支置於胸前的第二肋間引流液體，另一支置於腋中線第八及第九肋間處引流肋膜腔下方的空氣'], ans:[2], expl:'本題答案為C。胸腔手術後放置雙胸管之原理為「氣體上升、液體下沉」：置於胸前（前側）第二肋間的胸管用以引流上方肋膜腔內殘留空氣，另一支置於腋中線第八、九肋間（較低位置）的胸管則用以引流肋膜腔下方積聚之液體，此為術後胸管留置位置與功能對應之經典教學重點。'},
{n:1174, no:54, subj:'呼吸系統', q:'當進行肺部聽診時，可經由聽診器清楚的聽到病人所說的話，下列何者為此項檢查之結果？', opts:['A.羊語音', 'B.支氣管語音', 'C.耳語樣的胸語音', 'D.摩擦音'], ans:[1], expl:'本題答案為B。當清楚聽到病人說話聲音經由聽診器傳導出來（音量與清晰度皆增加），稱為支氣管語音（bronchophony），常見於肺部實質化（consolidation）區域，因實質組織較能有效傳導聲音。A羊語音（egophony）是特殊的「E聲轉A聲」音質改變，非單純聲音變清楚。C耳語樣胸語音（whispered pectoriloquy）是指「耳語聲」被清楚聽到，與題述之正常說話聲音清晰傳導不同。D摩擦音為肋膜摩擦所致的異常呼吸附加音，與語音傳導無關。'},
{n:1175, no:55, subj:'呼吸系統', q:'右肺葉切除術後病人的姿勢擺位，下列何者最適當？', opts:['A.左或右側臥', 'B.平躺或高坐臥', 'C.平躺或右側臥', 'D.左側臥或半坐臥'], ans:[3], expl:'本題答案為D。右肺葉切除術後，應避免讓病人長時間平躺於「手術側（右側）」，以利殘餘肺組織充分擴張及減少縫合處張力，故建議採左側臥（健側在下）或半坐臥姿勢，兼顧肺擴張與呼吸舒適。A「左或右側臥」因包含手術患側臥姿，並不適當。B、C選項未能同時排除患側臥姿之風險，故不如D完整適當。'},
{n:1176, no:56, subj:'呼吸系統', q:'下列何者為支氣管擴張症最主要的病因？', opts:['A.細菌感染', 'B.過敏反應', 'C.遺傳', 'D.老化'], ans:[0], expl:'本題答案為A。支氣管擴張症最主要且最常見的致病原因是反覆的細菌性呼吸道感染，感染造成支氣管壁反覆發炎、破壞其結構支撐力，導致管腔不可逆之擴張變形。B過敏反應、C遺傳性疾病（如囊狀纖維化）及D老化雖可能與部分病例有關，但均非其最主要、最常見的致病原因。'},
{n:1177, no:57, subj:'呼吸系統', q:'有關呼吸困難之徵象，下列何者最不常見？', opts:['A.端坐呼吸', 'B.噘嘴式呼吸', 'C.使用胸鎖乳突肌', 'D.咳血'], ans:[3], expl:'本題答案為D。咳血雖可能伴隨某些呼吸道疾病出現，但並非呼吸困難本身的常見伴隨徵象或代償機轉表現，四個選項中相對最不常見。A端坐呼吸、B噘嘴式呼吸、C使用胸鎖乳突肌等呼吸輔助肌，皆是病人因呼吸困難而產生的典型代償性表現，臨床上相當常見。'},
{n:1178, no:58, subj:'泌尿系統', q:'成人在正常飲水狀況下，日間平均解尿次數超過 8 次之現象，下列何者正確？', opts:['A.解尿困難', 'B.頻尿', 'C.夜尿', 'D.尿失禁'], ans:[1], expl:'本題答案為B。在正常飲水狀況下，日間平均解尿次數超過8次，稱為頻尿（urinary frequency）。A解尿困難是指排尿費力、不順暢等排尿障礙，非關次數。C夜尿是指「夜間」因尿意而醒來解尿之現象，與題述「日間」不符。D尿失禁是指不自主漏尿，與解尿「次數」增加為不同概念。'},
{n:1179, no:59, subj:'泌尿系統', q:'下列何項實驗室檢查結果最能顯示腎臟功能受損？', opts:['A.血中尿素氮升高', 'B.血清肌酐酸升高', 'C.尿中鈉離子升高', 'D.尿中鈣離子升高'], ans:[1], expl:'本題答案為B。血清肌酐酸（creatinine）主要由腎絲球過濾排出，較不受飲食、水分攝取及腸胃道出血等非腎因素干擾，是評估腎功能最具特異性與代表性的實驗室指標。A血中尿素氮（BUN）易受飲食蛋白質攝取、脫水、腸胃道出血等因素影響而上升，特異性較肌酐酸低。C、D尿中電解質變化並非評估整體腎功能受損程度的主要指標。'},
{n:1180, no:60, subj:'呼吸系統', q:'教導慢性阻塞性肺疾病病人採用橫膈式呼吸之預期效果，下列何者正確？', opts:['A.減少潮氣容積', 'B.減少肺泡通氣', 'C.增加呼吸速率', 'D.增加活動耐力'], ans:[3], expl:'本題答案為D。橫膈式呼吸訓練可強化橫膈肌之使用效率，改善通氣效能、減少呼吸功，長期規律訓練有助於提升病人日常活動耐受度，此為COPD肺部復健的重要目標之一。A橫膈式呼吸目的是「增加」而非減少潮氣容積，使呼吸更深而有效。B目標是改善並增加肺泡有效通氣，而非減少。C此呼吸訓練著重放慢呼吸速率、延長吐氣時間，而非增加呼吸速率。'},
{n:1181, no:61, subj:'泌尿系統', q:'尿流速之檢查結果，最大尿流速為 8 mL/秒，下列何者為最可能之診斷？', opts:['A.急性腎絲球腎炎', 'B.前列腺肥大', 'C.腎病症候群', 'D.急性尿路感染'], ans:[1], expl:'本題答案為B。正常最大尿流速多在15～20 mL/秒以上，本題僅8 mL/秒，明顯偏低，提示下泌尿道出口阻塞，中老年男性最常見原因為前列腺肥大（BPH）壓迫尿道所致。A急性腎絲球腎炎主要影響過濾功能與蛋白尿血尿，非典型造成尿流速下降。C腎病症候群為腎絲球通透性異常導致大量蛋白尿，非出口阻塞問題。D急性尿路感染主要表現為頻尿、灼熱感，非以尿流速降低為特徵。'},
{n:1182, no:62, subj:'泌尿系統', q:'情境：蔡先生因急性腎衰竭而住院。對於蔡先生在急診室測得的動脈血氧氣體分析結果：pH 7.25、PaCO2 31 mmHg、HCO3- 18 mEq/L 之判讀，下列何者正確？', opts:['A.呼吸性酸中毒', 'B.部分代償性呼吸性酸中毒', 'C.代謝性酸中毒', 'D.部分代償性代謝性酸中毒'], ans:[3], expl:'情境：蔡先生因急性腎衰竭而住院。本題答案為D。判讀：pH 7.25（酸性，正常7.35～7.45）；PaCO2 31 mmHg（偏低，正常35～45）；HCO3- 18 mEq/L（偏低，正常22～26）。因pH仍未回到正常範圍，代表代償尚未完全；HCO3-偏低為原發問題（代謝性酸中毒），PaCO2偏低為呼吸系統代償性過度換氣所致，故判讀為部分代償性代謝性酸中毒。'},
{n:1183, no:63, subj:'泌尿系統', q:'情境：蔡先生因急性腎衰竭而住院。改善其酸鹼不平衡問題最有效的措施，下列何者正確？', opts:['A.給予紙袋罩住口鼻', 'B.注射 NaHCO3', 'C.補充 NH4Cl', 'D.使用人工呼吸器'], ans:[1], expl:'情境：蔡先生因急性腎衰竭而住院。本題答案為B。此病人的原發問題為代謝性酸中毒（HCO3-不足），直接靜脈注射NaHCO3可立即補充缺乏的鹼儲備，是矯正代謝性酸中毒最直接有效的方式。A紙袋罩口鼻為處理呼吸性鹼中毒（換氣過度）之方法，方向不符。C NH4Cl屬酸化劑，臨床用於矯正代謝性「鹼」中毒，若用於本個案將使酸中毒惡化。D呼吸器可調整換氣量影響PaCO2，但無法矯正原發之代謝性（HCO3-）問題，非最有效方式。'},
{n:1184, no:64, subj:'泌尿系統', q:'情境：蔡先生因急性腎衰竭而住院。蔡先生目前正處於少尿期，其生化檢驗可能產生的變化，不包括下列何者？', opts:['A.serum creatinine 上升', 'B.BUN 上升', 'C.血鉀上升', 'D.血磷下降'], ans:[3], expl:'情境：蔡先生因急性腎衰竭而住院。本題答案為D。急性腎衰竭少尿期因腎臟排磷功能受損，血磷應「上升」（高血磷）而非下降，此為本題「不包括」之錯誤選項。A血清肌酐酸上升、B BUN上升、C血鉀上升，皆為少尿期腎臟排除含氮廢物及電解質能力下降之典型生化變化，正確會發生。'},
{n:1185, no:65, subj:'泌尿系統', q:'情境：蔡先生因急性腎衰竭而住院。蔡先生主訴噁心、食慾不振，昨日嘔吐量約 150 c.c./天，排尿量 360 c.c./天，血清鉀 6.8 mEq/L，下列處置何者錯誤？', opts:['A.液體攝入量應限制在 510 c.c./天', 'B.給予 furosemide（lasix）引發利尿', 'C.給予 kayexalate 降低血鉀濃度', 'D.應採高熱量、低蛋白、低鹽飲食'], ans:[0], expl:'情境：蔡先生因急性腎衰竭而住院。本題答案為A（錯誤選項）。少尿期液體攝入量計算原則為：前一天總排出量（尿量＋其他測得之流失，如嘔吐、腹瀉）＋不可測之流失量（通常估計約500～600 c.c.），故應為360（尿量）＋150（嘔吐）＋500（不可測）＝約1,010 c.c.，而非題述之510 c.c.，此計算結果錯誤，為本題所指之錯誤處置。B血鉀高達6.8 mEq/L已達危險值，給予furosemide促進利尿為合理處置。C給予kayexalate可經腸道排除鉀離子、降低血鉀，為處理高血鉀之標準方法。D少尿期飲食原則為高熱量、低蛋白（減少含氮廢物產生）、低鹽，正確。'},
{n:1186, no:66, subj:'泌尿系統', q:'有關腎盂腎炎的敘述，下列何者錯誤？', opts:['A.糖尿病、尿路結石是其危險因子', 'B.C 反應蛋白質（CRP）值會增高', 'C.會有肋骨脊柱角處疼痛', 'D.急性期時應限制液體攝取量'], ans:[3], expl:'本題答案為D（錯誤選項）。腎盂腎炎急性期應「鼓勵多攝取水分」，以增加尿液沖刷尿路、幫助排除細菌並預防脫水（尤其發燒時體液消耗增加），而非限制液體攝取，此為本題錯誤之處。A糖尿病與尿路結石確為泌尿道感染之危險因子，正確。B CRP屬發炎指標，感染時會上升，正確。C肋骨脊柱角（CVA）壓痛／叩痛是腎盂腎炎的經典身體評估發現，正確。'},
{n:1187, no:67, subj:'內分泌系統', q:'有關糖尿病酮酸中毒（DKA）之處置，下列何者錯誤？', opts:['A.建立靜脈輸液，給予 0.9%生理食鹽水', 'B.皮下注射大劑量短效胰島素', 'C.當血糖降至 300 mg/dL，應補充葡萄糖溶液', 'D.監測血中鉀離子濃度變化'], ans:[1], expl:'本題答案為B（錯誤選項）。糖尿病酮酸中毒（DKA）的胰島素治療原則是以「低劑量、持續性靜脈輸注」給予短效胰島素，而非皮下注射大劑量胰島素，因DKA病人組織灌流差，皮下吸收不穩定，且大劑量恐使血糖與滲透壓急速變化，增加腦水腫等風險，此為本題錯誤之處。A建立靜脈輸液給予生理食鹽水為DKA處置第一優先，正確。C當血糖降至約250～300 mg/dL時應開始輸注含糖溶液，避免血糖降得過快且可持續胰島素治療至酮症解除，正確。D胰島素治療會使鉀離子快速移入細胞內，須密切監測血鉀變化以防低血鉀，正確。'},
{n:1188, no:68, subj:'內分泌系統', q:'下列何種內分泌機能低下會造成黏液性水腫？', opts:['A.甲狀腺', 'B.副甲狀腺', 'C.腎上腺皮質', 'D.腦下垂體前葉'], ans:[0], expl:'本題答案為A。黏液性水腫（myxedema）是嚴重甲狀腺機能低下的典型表現，因黏多醣蛋白複合物堆積於皮下組織，造成非凹陷性水腫，是甲狀腺功能低下最經典且specific之臨床名詞。'},
{n:1189, no:69, subj:'內分泌系統', q:'有關甲狀腺切除後病人的護理措施，下列何者正確？①注意有無聲音嘶啞 ②禁止深呼吸、咳嗽運動 ③喝溫開水減輕傷口不適 ④觀察口部刺麻感', opts:['A.①②', 'B.①④', 'C.②③', 'D.③④'], ans:[1], expl:'本題答案為B（①④）。①甲狀腺切除術中可能損傷喉返神經，故須密切觀察聲音是否嘶啞。④手術可能誤傷或影響鄰近副甲狀腺功能，造成低血鈣，口部及肢端刺麻感是低血鈣手足抽搐（tetany）的早期警訊，兩者皆為術後最重要之併發症監測重點。②術後應「鼓勵」深呼吸咳嗽運動以預防肺部合併症，而非禁止。③喝溫開水並非本手術術後傷口不適的標準指導措施。'},
{n:1190, no:70, subj:'內分泌系統', q:'長期口服或注射類固醇病人最可能出現的副作用，下列何者正確？', opts:['A.低血鈉', 'B.高血糖', 'C.高血鉀', 'D.低血壓'], ans:[1], expl:'本題答案為B。長期使用類固醇（糖皮質素）會促進肝醣新生並降低周邊組織對胰島素的敏感度，導致高血糖，是類固醇治療最常見且需長期監測之副作用。A、C類固醇因具輕度礦皮質素作用，傾向造成「鈉滯留、血鉀降低」，與題述之低血鈉、高血鉀方向相反。D類固醇造成水鈉滯留，傾向使血壓「上升」而非降低。'},
{n:1191, no:71, subj:'內分泌系統', q:'有關副甲狀腺機能亢進病人之護理指導，下列何者正確？', opts:['A.鼓勵攝取乳製品', 'B.鼓勵攝取高鈣食物', 'C.鼓勵攝取低纖維食物', 'D.鼓勵攝取蔓越莓製品'], ans:[3], expl:'本題答案為D。副甲狀腺機能亢進造成高血鈣，增加腎臟形成鈣化結石之風險，鼓勵攝取蔓越莓製品有助於酸化尿液、維護泌尿道健康，降低泌尿道感染與結石相關併發症風險，為此類病人合理之飲食指導。A、B鼓勵攝取乳製品或高鈣食物皆會使血鈣進一步升高，不適當。C高血鈣易合併腸胃蠕動變慢、便秘，應鼓勵攝取「高纖維」飲食以改善便秘，而非低纖維飲食，不適當。'},
{n:1192, no:72, subj:'泌尿系統', q:'有關代謝性酸中毒的症狀，下列何者正確？', opts:['A.出汗、口乾', 'B.頭痛、意識遲鈍', 'C.呼吸速率變慢', 'D.周邊血管收縮'], ans:[1], expl:'本題答案為B。代謝性酸中毒因血液氫離子濃度上升，影響中樞神經系統functions，可出現頭痛、意識遲鈍甚至嗜睡等表現，是臨床上需警覺的神經學徵象。A出汗、口乾非其典型或特異性表現。C代謝性酸中毒會誘發「庫斯莫氏呼吸（Kussmaul breathing）」，即呼吸「加快、加深」以代償性排出CO2，而非呼吸速率變慢，方向相反。D酸中毒對周邊血管多呈擴張效應而非收縮。'},
{n:1193, no:73, subj:'內分泌系統', q:'有關下視丘之敘述，下列何者正確？', opts:['A.位於腦下垂體之下，是間腦的一小部分，受到蝶骨蝶鞍部分的保護', 'B.會分泌調節因子來刺激或抑制腦下垂體後葉激素的分泌', 'C.下視丘分泌的調節因子直接由血管叢送達目的地', 'D.下視丘藉發出的神經衝動來控制腦下垂體前葉的激素分泌'], ans:[2], expl:'本題答案為C。下視丘分泌之釋放（或抑制）因子，經由「下視丘—腦下垂體門脈系統」（一種特化的血管叢）直接運送至腦下垂體前葉，調控其荷爾蒙分泌，此為下視丘對腦下垂體「前葉」的調控機轉。A解剖位置錯誤：下視丘位於腦下垂體「上方」，並非下方。B下視丘所分泌之釋放因子是作用於腦下垂體「前葉」而非後葉。D控制腦下垂體前葉分泌的是體液性（血管門脈系統）機轉，並非直接神經衝動；神經衝動直接調控的是腦下垂體「後葉」（經由下視丘神經核之軸突運輸ADH與催產素）。'},
{n:1194, no:74, subj:'內分泌系統', q:'有關水分剝削試驗（Water Deprivation Test）之敘述，下列何者錯誤？', opts:['A.主要用來診斷尿崩症', 'B.病人限制飲水後，每小時採血液與尿液檢體', 'C.檢測檢體中滲透壓、鈣離子與鉀離子濃度', 'D.試驗期間需觀察病人的生命徵象、尿量、血中滲透壓與體重變化'], ans:[2], expl:'本題答案為C（錯誤選項）。水分剝削試驗主要監測項目為血清與尿液之「滲透壓」（及尿比重）變化，藉此判斷腎臟濃縮尿液能力，並非檢測鈣離子與鉀離子濃度，此為本題錯誤之處。A此試驗主要用於診斷尿崩症，正確。B限水期間確實需每小時採檢血液與尿液檢體以監測變化，正確。D試驗過程中須密切觀察生命徵象、尿量、血中滲透壓及體重變化（體重下降可提示脫水程度，作為終止試驗之依據），正確。'},
{n:1195, no:75, subj:'其他', q:'病人發生休克時對肝臟系統之影響不包括下列何者？', opts:['A.早期出現血中葡萄糖增加', 'B.漸進期出現代謝性鹼中毒', 'C.漸進期出現乳酸轉換下降', 'D.漸進期出現血中葡萄糖下降'], ans:[1], expl:'本題答案為B（不包括之錯誤選項）。休克進入漸進期（失代償期）後，因組織灌流持續不足、無氧代謝增加乳酸堆積，會造成「代謝性酸中毒」，而非代謝性鹼中毒，此為本題錯誤之處。A休克早期因壓力荷爾蒙（如兒茶酚胺、皮質醇）作用促進肝醣分解，血糖會上升，正確。C隨肝臟灌流惡化，其代謝、轉換乳酸的能力下降，正確。D漸進期肝醣儲備耗盡且肝功能受損，血糖最終會轉為下降，正確。'},
{n:1196, no:76, subj:'其他', q:'有關食物中毒之敘述，下列何者錯誤？', opts:['A.食物中毒多指食用遭細菌污染之食物或誤食野生蕈造成', 'B.葡萄球菌中毒是最常見之食物中毒', 'C.食物中毒之症狀嚴重度與食入污染物的量與內毒素含量有正相關', 'D.處理食物中毒休克病人時，應最先了解是何種食物導致病人出現腹瀉與脫水'], ans:[3], expl:'本題答案為D（錯誤選項）。處理食物中毒合併休克之病人時，應以「立即穩定生命徵象、積極輸液復甦」為第一優先，而非先花時間確認致病食物種類，找出致病源屬於後續公共衛生調查範疇，此為本題錯誤之處（處置優先順序錯置）。A食物中毒多因食用遭細菌污染食物或誤食毒菇所致，正確。B金黃色葡萄球菌毒素為最常見的食物中毒原因之一（潛伏期短、以嘔吐為主），正確。C中毒症狀嚴重度與攝入污染物之量及毒素濃度呈正相關，符合一般毒理學原則，正確。'},
{n:1197, no:77, subj:'其他', q:'2015 年修改「成人生存之鏈」，其中醫院內心臟停止的照護途徑不包括下列何者？', opts:['A.立即確認心臟停止並啟動緊急應變系統', 'B.立即進行高品質 CPR', 'C.進行快速去顫', 'D.基礎及高級緊急醫療服務'], ans:[3], expl:'本題答案為D（不包括之錯誤選項）。緊急醫療服務（EMS）啟動與到院前處置，屬於「到院前（社區）生存之鏈」的環節，病人已在「院內」發生心臟停止時，不需再經由EMS系統介入，故此項不屬於院內心臟停止照護途徑，為本題正確答案。A立即確認心臟停止並啟動應變系統、B立即執行高品質CPR、C快速去顫，皆為2015年更新版生存之鏈中，院內心臟停止照護途徑之核心環節。'},
{n:1198, no:78, subj:'心臟血管', q:'有關自動體外心臟去顫器（AED）之敘述，下列何者錯誤？', opts:['A.政府立法於公共場所設置 AED 以即時搶救病人，同時讓施救者受到免責之保障', 'B.使用時機為病人出現心室纖維顫動或是無脈搏心室心搏過速', 'C.使用時有整流與去顫兩種功能', 'D.具有語音提示正確操作機器步驟之功能'], ans:[2], expl:'本題答案為C（錯誤選項）。自動體外心臟去顫器（AED）僅具備「去顫（defibrillation）」單一電擊功能，用於矯正心室纖維顫動或無脈搏心室頻脈等致命性心律不整，並不具備需要與心跳週期同步之「整流（心臟整流術）」功能，此為本題錯誤之處。A政府立法於公共場所廣設AED，並給予善意施救者(好心人)免責法律保障，符合台灣現行相關法規，正確。B AED適應症確為心室纖維顫動或無脈搏性心室頻脈，正確。D AED具備語音指引功能，協助非專業人員正確操作，正確。'},
{n:1199, no:79, subj:'其他', q:'有關霍亂的症狀與治療之敘述，下列何者錯誤？', opts:['A.霍亂弧菌不會進入血管引起菌血症', 'B.會有嚴重腹瀉、噁心、嘔吐及發燒', 'C.要適當補充電解質液體以矯正酸中毒、脫水及低血鉀', 'D.主以四環黴素（tetracycline）縮短病程及降低腹瀉的嚴重度'], ans:[1], expl:'本題答案為B（錯誤選項）。霍亂的典型臨床表現是大量「米湯樣」水瀉合併嘔吐，但一般並不會伴隨顯著發燒，此點可與其他伴隨發燒的細菌性腸胃炎作鑑別，題述「及發燒」的敘述並不符合霍亂之典型臨床表現，此為本題錯誤之處。A霍亂弧菌作用機轉為分泌腸毒素於腸黏膜局部致病，並不會侵入血液造成菌血症，正確。C大量水瀉可迅速造成脫水、代謝性酸中毒及低血鉀，故積極的電解質及輸液矯正為治療重點，正確。D四環黴素等抗生素可作為輔助治療，縮短病程並減少排菌量，正確。'},
{n:1200, no:80, subj:'呼吸系統', q:'有關嚴重急性呼吸道症候群（SARS）之臨床症狀，不包括下列何者？', opts:['A.肌肉痛', 'B.發病期常見肺部鈣化合併胸部 X 光異常', 'C.發病後 3～7 天即進入下呼吸道期，出現沒有痰的乾咳或血氧過低', 'D.在早期肌酸磷酸激酶（CPK）與肝轉胺酶（hepatic transaminase）會升高'], ans:[1], expl:'本題答案為B（不包括之錯誤選項）。SARS急性期胸部X光典型變化為「毛玻璃樣（ground-glass）浸潤或實質化」病灶，並非肺部鈣化，鈣化多見於陳舊性肉芽腫病灶（如已癒合之肺結核），與SARS急性病程不符，此為本題錯誤之處。A肌肉痛為SARS前驅期常見症狀，正確。C發病後3～7天進入下呼吸道期，出現不具痰之乾咳及低血氧，符合SARS典型病程分期，正確。D早期CPK及肝轉胺酶上升為SARS病人常見之實驗室異常，正確。'},];QS.forEach(n=>{n.exam=n.n<=50?"115-1":n.n<=100?"114-2":n.n<=150?"114-1":n.n<=200?"113-3":n.n<=250?"113-2":n.n<=300?"113-1":n.n<=350?"112-3":n.n<=430?"112-2":n.n<=510?"112-1":n.n<=560?"114-3":n.n<=640?"111-2":n.n<=720?"111-1":n.n<=800?"110-2":n.n<=880?"110-1":n.n<=960?"109-1":n.n<=1040?"109-2":n.n<=1120?"108-1":"108-2",n.course=EXAM_COURSE[n.exam]||"medsurg"});
const QS_PSYCH_108_1=[
{n:1201,no:1,subj:'精神復健與社區精神衛生',q:'世界衛生組織強調對精神病人基本人權的尊重，下列何者正確？',opts:['A.病人應有權利在社區，而非機構化照顧','B.全球心理衛生治療的趨勢是從急性醫院轉換為慢性機構療養','C.精神生物醫學的進步，藥物治療的成效佳，故不需要心理社會的整合性照護','D.慢性精神病人宜在偏遠地區的療養機構接受治療與安置'],ans:[0],expl:'本題答案為A。WHO自1970年代起即倡議去機構化（deinstitutionalization），強調精神病人應享有在社區中生活、接受照顧的權利，而非被長期收容於機構，此為對病人基本人權（自主、尊嚴、社會參與）的尊重，敘述正確（A✓，本題答案）。全球趨勢是從機構式照顧「轉向」社區式照顧，而非從急性醫院轉為慢性機構療養，方向恰好相反，此敘述有誤（B✗）；精神藥物學的進步並不能取代心理社會整合性照護，生理—心理—社會（biopsychosocial）模式仍是精神科照護的核心，此敘述有誤（C✗）；將慢性病人安置於偏遠療養機構違背去機構化與社區融入之人權精神，此敘述有誤（D✗）。'},
{n:1202,no:2,subj:'心理病理與治療理論',q:'關於心理防衛機轉（defense mechanism），「把自己無法接受的想法與情緒，推給其他人，認為是別人擁有這樣的想法，而不是他自己。」指的是下列何種心理防衛機轉？',opts:['A.合理化（rationalization）','B.壓抑（suppression）','C.反向行為（reaction formation）','D.投射（projection）'],ans:[3],expl:'本題答案為D。投射（projection）係指個體將自己無法接受的想法、情緒或衝動，歸咎、轉嫁到他人身上，認為是別人擁有這些想法而非自己，題幹描述完全符合投射之定義（D✓，本題答案）。合理化是為自己的行為或想法找一個看似合理、可被接受的理由以掩飾真正動機，並非將想法歸咎他人，此敘述不符（A✗）；壓抑是有意識地將不悅的想法或衝動暫時擱置、不去想它，屬於意識層面的自我控制，並非歸咎他人，此敘述不符（B✗）；反向行為是表現出與內心真實想法相反的態度或行為（如內心厭惡卻表現熱情），亦非將想法歸咎他人，此敘述不符（C✗）。'},
{n:1203,no:3,subj:'心理病理與治療理論',q:'服役的林先生對軍中訓練的要求一直無法達成，常出現失眠、肚子痛等現象。某日要出外打靶的早上，林先生突然雙腳麻痺無法站立，緊急送醫並無發現任何異常的病理報告，因此轉介精神科治療，下列何者為林先生使用的心理防衛機轉？',opts:['A.退化','B.轉化','C.否定','D.昇華'],ans:[1],expl:'本題答案為B。轉化（conversion）係指心理衝突或壓力，在沒有器質性病理基礎的情況下，轉換為感覺或運動功能的身體症狀，題幹中林先生因無法承受訓練壓力（欲逃避打靶），在檢查無任何異常病理報告下突發雙腳麻痺無法站立，正是典型的轉化症表現，藉此身體症狀逃避其無法面對的壓力情境（B✓，本題答案）。退化是遇壓力時表現出較幼稚、回到早期發展階段的行為模式，與題幹之肢體麻痺無關，此敘述不符（A✗）；否定是拒絕承認或面對令人痛苦的事實或現實，題幹並非否認某個事實，此敘述不符（C✗）；昇華是將不被接受的衝動，轉化為社會可接受、甚至具建設性的行為（如將攻擊衝動轉為運動競賽），與題幹情境不符（D✗）。'},
{n:1204,no:4,subj:'心理病理與治療理論',q:'有關佩普洛（Peplau）概念的敘述，下列何者正確？①護病關係的介紹期、認同期、工作期及結束期，是重疊及連接的　②強調護理人員使用治療性人際溝通技巧和病人建立關係　③協助病人將現在的經驗與其他經驗統合　④透過轉移關係來幫助病人了解自己',opts:['A.①②③','B.②③④','C.①③④','D.①②④'],ans:[3],expl:'本題答案為D。Peplau人際關係理論將護病關係分為介紹期、認同期、工作期、結束期四階段，且明確指出此四階段彼此重疊、連續進行而非截然分割，此敘述正確（①✓）；其理論核心即強調護理人員運用治療性人際溝通技巧，逐步與病人建立信任的治療性關係，此敘述正確（②✓）；Peplau理論中亦運用精神分析取向之轉移關係（transference）概念，作為協助病人透過與護理人員的互動更了解自己感受與行為模式的治療工具，此敘述正確（④✓），故①②④皆正確，本題答案為D。至於「協助病人將現在的經驗與其他經驗統合」（③），並非Peplau四階段理論中被特別強調之定義性特徵，其理論重點在於護病關係「歷程」本身的治療性運用，而非經驗統合，此敘述較不適切（③✗，此為本題唯一錯誤敘述，故排除含③之選項A、C）。'},
{n:1205,no:5,subj:'治療性溝通技巧',q:'李小姐已住院一個月和護理師會談提到：「一直以來只相信自己，也獨力把自己照顧得很好。」護理師回應表示：「你認為自己把自己照顧得很好，最近半年出現多次割腕的狀況是發生什麼狀況？」此回應是屬於何種治療性溝通技巧？',opts:['A.提出懷疑（voicing doubt）','B.鼓勵比較（encouraging comparison）','C.面質（confrontation）','D.鼓勵評價（encouraging evaluation）'],ans:[2],expl:'本題答案為C。面質（confrontation）是護理人員指出病人言語敘述與客觀觀察／行為事實之間的落差或矛盾，藉此協助病人正視問題。題幹中護理師點出李小姐「自認照顧自己很好」與「近半年多次割腕」兩者間的矛盾，正是面質技巧的運用（C✓，本題答案）。提出懷疑是護理師直接表達對病人所述內容真實性的懷疑（如：「我很懷疑事情真的是這樣」），並非指出前後矛盾，此敘述不符（A✗）；鼓勵比較是引導病人比較不同人事物或情境之間的異同以獲得領悟，題幹並無比較性引導，此敘述不符（B✗）；鼓勵評價是請病人對某人事物的價值或品質做出評斷，題幹並非要求評價，此敘述不符（D✗）。'},
{n:1206,no:6,subj:'心理病理與治療理論',q:'「一朝被蛇咬，十年怕草繩」此例子可以運用下列何種理論說明焦慮反應的產生？',opts:['A.心理分析','B.學習','C.認知','D.人際'],ans:[1],expl:'本題答案為B。學習理論（尤其是古典制約）主張中性刺激（草繩）若曾與令人恐懼的刺激（蛇咬）同時出現並產生連結，日後單獨接觸中性刺激也會誘發相同的恐懼／焦慮反應，「一朝被蛇咬，十年怕草繩」正是古典制約下條件化恐懼反應的經典例證（B✓，本題答案）。心理分析理論將焦慮歸因於潛意識衝動與超我（superego）之間的內在衝突，並非刺激—反應的制約連結，與題幹例子不符（A✗）；認知理論主張焦慮源自個體對情境的錯誤或扭曲之認知評價，題幹例子強調的是「制約學習」而非認知評價歷程，此敘述不符（C✗）；人際理論（如Sullivan）將焦慮歸因於人際互動中對他人評價、關係品質的知覺，與題幹例子之制約機制無關，此敘述不符（D✗）。'},
{n:1207,no:7,subj:'生理治療與物質濫用',q:'何先生因準備進行電氣痙攣療法（electroconvulsive therapy, ECT）而顯焦慮，護理師和其討論並提供相關護理指導，下列何者正確？①治療後有暫時的記憶力喪失　②治療前要先拿下活動假牙　③治療前會給予注射Demerol藥物　④治療清醒後可照常參與病房活動',opts:['A.①②③','B.①②④','C.①③④','D.②③④'],ans:[1],expl:'本題答案為B。ECT誘發之全身性癲癇發作常合併暫時性的順行性／逆行性記憶力障礙，此為ECT常見、可預期之副作用，此敘述正確（①✓）；治療前為預防痙攣發作時活動假牙鬆脫造成呼吸道阻塞或誤吸，應於術前取下活動假牙，此為標準術前護理措施，此敘述正確（②✓）；病人於治療清醒、意識及定向感恢復穩定後，即可如常參與病房作息活動，此敘述正確（④✓），故①②④皆正確，本題答案為B。至於術前用藥（③），ECT標準前置給藥為全身麻醉藥物合併肌肉鬆弛劑，並常規給予抗膽鹼藥物（如Atropine或Glycopyrrolate）以減少分泌物及預防心搏過緩，並非常規注射Demerol（麻醉性止痛劑），此敘述有誤（③✗，此為唯一錯誤敘述，故排除含③之選項A、C）。'},
{n:1208,no:8,subj:'心理病理與治療理論',q:'精神科病房特別重視治療性環境之營造，有關環境治療之原則，下列何者正確？①設施兼具人性化與家庭化　②活動設計宜達整體一致性　③讓病人有機會參與環境的決策　④工作人員成為病人的角色模範',opts:['A.①②③','B.①②④','C.①③④','D.②③④'],ans:[2],expl:'本題答案為C。治療性環境（milieu therapy）強調病房設施應具人性化與家庭化的溫馨感，減少機構化、去人性化的氛圍，此敘述正確（①✓）；治療性環境重視賦權（empowerment），應讓病人有機會參與病房環境及活動相關決策，以增進其自主感與責任感，此敘述正確（③✓）；工作人員於病房中的言行本身即具示範作用，應以身作則成為病人可仿效的角色模範，此敘述正確（④✓），故①③④皆正確，本題答案為C。至於「活動設計宜達整體一致性」（②），治療性環境之活動安排實務上應依病人個別需求與功能程度彈性設計、因人而異，而非強調全面一致，過度追求一致性反而忽略個別化原則，此敘述有誤（②✗，此為唯一錯誤敘述，故排除含②之選項A、B、D）。'},
{n:1209,no:9,subj:'心理病理與治療理論',q:'周護理師為避免影響到病房的安寧，會去遏止正在嬉鬧的兩位病友，當病友安靜後會獲得護理師的稱讚，有關行為治療的原則中對周護理師的護理行為敘述，下列何者正確？',opts:['A.正向增強','B.負向增強','C.相互抑制','D.連鎖策略'],ans:[0],expl:'本題答案為A。正向增強（positive reinforcement）係指在個體表現出目標行為（安靜下來）後，立即給予一個正向刺激（稱讚），以提高該行為未來再度發生的機率，題幹中護理師於病友安靜後給予稱讚，正是正向增強的應用（A✓，本題答案）。負向增強是指移除一個令人不悅的刺激以增加目標行為出現頻率，題幹並未移除任何嫌惡刺激，而是「給予」稱讚，此敘述不符（B✗）；相互抑制是將引發焦慮的刺激與一個不相容的放鬆反應配對出現，藉此削弱焦慮反應，與題幹之獎勵安靜行為無關，此敘述不符（C✗）；連鎖策略是將複雜行為拆解為一連串連續步驟，逐步教導完成，題幹並未涉及行為拆解步驟，此敘述不符（D✗）。'},
{n:1210,no:10,subj:'思覺失調症與精神病症狀',q:'李先生因思覺失調症而住院治療2週，每次母親來訪就吵著要回家，致使母親生氣地說：「再吵就不來看你了！」使得李先生擔心母親不要他了，而反覆至護理站詢問。護理師提供有關家庭互動之護理措施，下列何者正確？①利用症狀作處理　②適當支持和教導　③著重現在情境的互動　④採用家屬的方法',opts:['A.①②③','B.①②④','C.①③④','D.②③④'],ans:[0],expl:'本題答案為A。護理人員可將李先生反覆詢問的行為（症狀性表現）作為切入點，藉此了解並處理其背後的分離焦慮，此敘述正確（①✓）；護理人員宜同時對病人與母親提供適當之情緒支持，並教導母親較具治療性的溝通方式（如避免以「不來看你」作為威脅），此敘述正確（②✓）；家庭互動介入應著重當下（here-and-now）親子互動情境的處理與示範，而非追溯過去，此敘述正確（③✓），故①②③皆正確，本題答案為A。至於「採用家屬的方法」（④），母親目前以生氣、威脅不來探視作為因應方式，此方法本身即為需要護理人員介入教導改善的不良互動模式，並非護理措施應直接沿用、採納的方法，此敘述有誤（④✗，此為唯一錯誤敘述，故排除含④之選項B、C、D）。'},
{n:1211,no:11,subj:'生理治療與物質濫用',q:'有關光照療法的作用機轉之敘述，下列何者最適當？',opts:['A.經由黏膜對光的照射','B.經由皮膚對光的照射','C.經由眼睛對光的照射','D.經由肢體對光的照射'],ans:[2],expl:'本題答案為C。光照療法（light therapy）之作用機轉是經由視網膜感光細胞接收光線刺激，訊號傳遞至下視丘視叉上核（suprachiasmatic nucleus），進而調節生理時鐘及褪黑激素分泌，常用於季節性情緒障礙、憂鬱症之輔助治療，故其作用途徑為經由眼睛對光的照射（C✓，本題答案）。光照療法並非經由黏膜、皮膚或肢體吸收光線產生療效，此三者皆非其作用機轉，故A、B、D均不適當（A✗、B✗、D✗）。'},
{n:1212,no:12,subj:'心理病理與治療理論',q:'下列何者符合環境治療的原則？',opts:['A.老人住院病房牆壁與地板宜採對比色，以防跌倒','B.精神科病房的保護室宜採用鮮紅的顏色，以幫助情緒壓抑的病人有宣洩管道','C.精神科病房須嚴格限制病人保有私人物品，以維護病人安全','D.精神科病房宜增加競爭活動，以幫助暴力病人有宣洩管道'],ans:[0],expl:'本題答案為A。老年病人視覺深度知覺較差，病房牆壁與地板採對比色可協助辨識地面邊界高低落差，有效降低跌倒風險，符合環境治療兼顧安全與功能之原則（A✓，本題答案）。保護室宜採用柔和、低刺激之色調以協助病人穩定情緒，鮮紅色屬高度刺激性色彩，反而可能增加躁動不安，並不適合作為情緒宣洩管道，此敘述有誤（B✗）；環境治療強調常態化與尊重病人自主權，應依個別風險評估決定物品限制，而非一律嚴格限制所有病人保有私人物品，此敘述過於絕對，有誤（C✗）；競爭性活動易誘發挫折與攻擊傾向病人的情緒波動，對暴力傾向病人而言反而增加激動風險，並非適當之宣洩管道，此敘述有誤（D✗）。'},
{n:1213,no:13,subj:'思覺失調症與精神病症狀',q:'情況題：張先生因攻擊行為而被家人帶來住院，入院第2天突然出手攻擊鄰床病友，護理人員和張先生會談時，張先生表示：「他是被派來要殺我的，我很害怕！」，依此情況回答第13題至第14題。護理人員對張先生之精神症狀評估，下列何項正確？',opts:['A.誇大妄想','B.被害妄想','C.關係妄想','D.控制妄想'],ans:[1],expl:'本題答案為B。被害妄想（persecutory delusion）係指病人堅信有人或某股勢力意圖傷害、迫害自己，題幹中張先生堅信鄰床病友「被派來要殺我」，正是典型的被害妄想內容，並因此產生攻擊性防衛行為（B✓，本題答案）。誇大妄想是堅信自己擁有超乎常人的特殊能力、地位或財富，與題幹之被害恐懼內容不符（A✗）；關係妄想是將周遭無關的事件、言語過度解讀為與自己有特殊關聯，題幹並非此類過度連結解讀，此敘述不符（C✗）；控制妄想是堅信自己的思想、情緒或行為受到外力操控，題幹並無此描述，此敘述不符（D✗）。'},
{n:1214,no:14,subj:'思覺失調症與精神病症狀',q:'承上題，護理人員對張先生的攻擊行為，在初期建立治療性關係過程中，給予的護理措施，下列何項正確？',opts:['A.提供結構性的治療環境','B.鼓勵病人參加支持團體','C.提供現實感並重建認知','D.鼓勵使用建設性因應機轉'],ans:[0],expl:'本題答案為A。對於具攻擊行為傾向、處於治療關係建立初期的病人，提供具可預測性、規律性的結構化治療環境，有助於降低病人因不確定感所致之焦慮與激動，為建立信任關係之基礎，此為初期最優先之措施（A✓，本題答案）。鼓勵參加支持團體需要病人具備一定程度之情緒穩定與人際互動能力，對剛入院、仍有攻擊行為之病人而言時機尚早，並非初期關係建立階段之優先措施，此敘述不適當（B✗）；提供現實感、重建認知較適用於處理病人之妄想或混亂認知本身，並非建立初期信任關係之首要介入重點，此敘述不適當（C✗）；鼓勵使用建設性因應機轉屬於較後期、病人情緒稍穩定後可進行之教育性介入，並非初期關係建立之優先措施，此敘述不適當（D✗）。'},
{n:1215,no:15,subj:'情緒障礙與危機處理',q:'王先生，思覺失調症，與護理師談及母親於去年辭世，隨即哈哈大笑表示很思念她。此時王先生的情緒表現最有可能為下列何者？',opts:['A.情感淡漠','B.矛盾情感','C.過度欣快','D.情感低落'],ans:[1],expl:'本題答案為B。矛盾情感（ambivalence）係指個體對同一對象同時存在兩種互相矛盾、對立的情緒或態度。題幹中王先生談及母親已於去年辭世（內容上仍表達「很思念她」，屬依戀、悲傷一致之情感內容），卻同時伴隨哈哈大笑（外顯情感表現卻是歡快的），對同一對象（母親）同時呈現「思念、悲傷」與「歡笑」兩種矛盾並存的情感反應，符合矛盾情感之定義（B✓，本題答案）。過度欣快是指情緒表現呈現與情境不相稱的單純過度歡愉，並未特別強調同時存在另一種矛盾對立的情緒內容，與題幹「思念」與「大笑」並存之矛盾性不如B選項貼切，此敘述較不適切（C✗）；情感淡漠是指情緒表達平板、幾乎沒有情緒反應，與題幹中王先生表現出大笑之強烈反應不符（A✗）；情感低落表現為憂鬱、消沉外顯情緒，與題幹之大笑表現方向相反，此敘述不符（D✗）。'},
{n:1216,no:16,subj:'思覺失調症與精神病症狀',q:'剛入院的思覺失調症病人躲在病房角落，深信將有大批警力要捉捕他入獄。此時最適當的護理措施為下列何者？',opts:['A.澄清只是精神症狀並不是真的','B.保證警察不會進入病房','C.接受病人此情境下的感受','D.鼓勵詳細描述妄想情境'],ans:[2],expl:'本題答案為C。面對急性期妄想病人，護理原則是先接納、同理病人當下真實感受到的恐懼情緒，而非直接處理妄想內容本身，此舉有助於建立信任並降低病人焦慮，為此情境下最適當之立即介入（C✓，本題答案）。直接指出「這只是精神症狀、不是真的」屬於直接否定病人的妄想信念，容易增加病人的不信任與防衛，並非急性期建立關係之適當作法（A✗）；保證警察不會進入病房屬於護理人員無法確實掌控之過度承諾（false reassurance），一旦承諾未能兌現將嚴重損害治療信任關係，此敘述不適當（B✗）；鼓勵詳述妄想內容可能使病人更深陷、反覆強化妄想細節，並非治療性作法，此敘述不適當（D✗）。'},
{n:1217,no:17,subj:'思覺失調症與精神病症狀',q:'許小姐住院3週後自言自語頻繁，持續在床上大聲怒罵叫旁人走開，但是身邊並無其他人。用餐時間護理師叫喚許小姐多次，她才抬頭回應有人在旁一直說她的不是。此情況下，護理師最適當的護理處置為下列何者？',opts:['A.與醫療團隊討論，考慮調整用藥','B.提供現實治療','C.需立即進入保護隔離室','D.鼓勵參加團體活動轉移注意力'],ans:[0],expl:'本題答案為A。許小姐住院3週後幻聽症狀（自言自語、對空叫罵、對周遭刺激反應遲鈍）未見改善反而持續存在並干擾進食等日常功能，顯示現行治療成效不佳，護理人員應與醫療團隊共同討論、評估是否需調整藥物治療方案，此為此情況下最適當之處置（A✓，本題答案）。單純提供現實治療對於持續、未受控制之活躍幻聽症狀而言效果有限，並非此時最優先之處置（B✗）；題幹並未顯示許小姐有立即危及自己或他人安全之行為，尚不需立即進入保護隔離室，此處置過度且不適當（C✗）；鼓勵參加團體活動轉移注意力對持續活躍之幻聽症狀效果有限，且無法處理根本問題，並非最適當之處置（D✗）。'},
{n:1218,no:18,subj:'思覺失調症與精神病症狀',q:'思覺失調症病人出現話少表情淡漠，不願參加慢性病房團體活動，整日躺床，前述狀況最可能為下列何種症狀？',opts:['A.幻聽症狀干擾','B.負性症狀表現','C.思考障礙','D.怪異行為'],ans:[1],expl:'本題答案為B。話少（alogia）、表情淡漠（affective flattening）、社交退縮不願參與活動（social withdrawal）、整日躺床缺乏動機（avolition），皆為思覺失調症負性症狀（negative symptoms）之典型表現，此敘述正確（B✓，本題答案）。題幹並未描述病人有對聲音刺激做出回應等幻聽相關行為，此敘述不符（A✗）；思考障礙主要表現為言語脫序、邏輯鬆散或語無倫次等思考形式異常，與題幹描述之退縮、少動不符（C✗）；怪異行為指外顯之奇特動作或姿勢，題幹並未描述此類行為，此敘述不符（D✗）。'},
{n:1219,no:19,subj:'情緒障礙與危機處理',q:'劉先生因患憂鬱症，住院期間不言不語，不吃不喝，護理人員與其會談時，劉先生都閉口不說話，最合適的護理措施為下列何者？',opts:['A.鼓勵劉先生下床參與病房作息','B.短暫而多次的陪伴劉先生','C.安排住多人的病房以增加外界刺激','D.多探詢病人的心情與感受'],ans:[1],expl:'本題答案為B。對於嚴重退縮、緘默不語之憂鬱症病人，護理人員宜採「短暫而多次」的陪伴方式，以病人可承受之程度給予陪伴與支持，同時傳遞護理人員的關心與可及性（availability），而不勉強病人立即互動，此為最合適之措施（B✓，本題答案）。強迫或鼓勵重度退縮病人立即下床參與作息，可能超出其目前承受能力，並非優先措施（A✗）；安排多人病房以增加外界刺激，對於高度退縮、極需低度刺激環境之憂鬱病人反而可能造成負荷過重，並不適當（C✗）；對於閉口不語之病人持續多加探詢心情感受，病人往往難以回應，效果有限，並非此階段最合適之作法（D✗）。'},
{n:1220,no:20,subj:'治療性溝通技巧',q:'承上題，護理人員對劉先生的溝通內容，下列何者最適宜？',opts:['A.你有很多值得活下去的理由，願不願意跟我分享有那些理由呢','B.我在這裡陪你，你隨時都可以決定願不願意跟我分享','C.人生其實有很多無奈，希望你早日想通','D.我希望你可以接受我的建議'],ans:[1],expl:'本題答案為B。此回應表達護理人員願意陪伴、且尊重病人決定是否及何時開口分享的自主權，不施加壓力，符合對嚴重退縮憂鬱病人之治療性溝通原則（B✓，本題答案）。「你有很多值得活下去的理由」帶有預設立場及說服意味，可能與病人當下的真實感受不符，容易顯得不被理解，此敘述不適宜（A✗）；「希望你早日想通」帶有評價與催促意味，屬於忽略病人感受的陳腔濫調式安慰，並非治療性溝通，此敘述不適宜（C✗）；「希望你可以接受我的建議」屬於指導性、強加意見的溝通方式，並非以病人為中心之治療性溝通，此敘述不適宜（D✗）。'},
{n:1221,no:21,subj:'治療性溝通技巧',q:'朱小姐，憂鬱症，會談時頻頻責備自己不是一個稱職的母親，說：「我的小孩一定覺得我很糟，會看不起我這個母親。」請問當朱小姐向護理人員做此反應時，護理人員運用認知治療回應朱小姐，下列何者較適宜？',opts:['A.世界上的媽媽都是好媽媽','B.有什麼情況，讓你有這種想法','C.想這些都沒用，應該想想要怎樣彌補他們','D.你真那麼糟嗎'],ans:[1],expl:'本題答案為B。認知治療的核心技巧之一為引導病人檢視、探索自動化負向想法背後的證據與來源，「有什麼情況，讓你有這種想法」正是以蘇格拉底式提問（guided discovery）引導朱小姐檢視此負向信念之依據，屬於認知治療取向的回應（B✓，本題答案）。「世界上的媽媽都是好媽媽」屬空泛的直接反駁與保證，並未引導病人檢視自身想法之來源，不符合認知治療技巧（A✗）；「想這些都沒用，應該想想要怎樣彌補他們」帶有否定病人感受、轉而要求行動之意味，並非探索認知的治療性回應（C✗）；「你真那麼糟嗎」帶有質疑、對質意味，容易使病人感到不被理解，並非認知治療引導技巧（D✗）。'},
{n:1222,no:22,subj:'情緒障礙與危機處理',q:'張同學情緒低落，母親偷看她的日記發現有輕生的念頭，送醫院接受治療，住院期間，對於他人的接近感到厭煩，對於病房活動參與不積極，常待在房間，不願到大廳活動，下列那一項短期目標較適當？',opts:['A.可以與護理人員討論改善人際關係的方法','B.可以分析自己人際關係的優缺點','C.能主動與同室病友打招呼','D.在護理人員陪伴下願意到大廳走動'],ans:[3],expl:'本題答案為D。短期目標之設定應依病人目前功能狀態，採漸進、可達成之小步驟。張同學目前對他人接近感到厭煩、不願離開房間，「在護理人員陪伴下願意到大廳走動」僅要求病人在有支持陪伴下跨出一小步，符合現階段可行、漸進之短期目標原則（D✓，本題答案）。「討論改善人際關係的方法」與「分析自己人際關係的優缺點」皆屬較高層次的自我覺察與洞察目標，需要病人具備一定參與動機與認知投入，對目前迴避人群的張同學而言時機過早，屬中長期目標（A✗、B✗）；「主動與同室病友打招呼」所需之社交主動性，仍高於在陪伴下走動之要求，對目前迴避社交的張同學而言難度較高，非最適合之短期目標（C✗）。'},
{n:1223,no:23,subj:'情緒障礙與危機處理',q:'魏小姐，32歲，憂鬱症，第2次入院，今早護理人員與家屬會談時，家屬無奈表示，對於魏小姐的病很不能諒解，認為她是不願承受壓力，逃避壓力才會裝病，整天無病呻吟，全家人為了照顧她，都搞得生活大亂，護理人員對於家屬的抱怨，下列何種回應較適當？',opts:['A.她的病需要被照顧，等她病好了，你們家就會恢復正常了','B.了解做為家屬的負擔，但也需要持續她的治療','C.這次醫師已經幫她改藥了，病情應該可以控制住','D.這是憂鬱症的症狀，不要給她壓力，症狀很快就緩解了'],ans:[1],expl:'本題答案為B。護理人員面對照顧負荷沉重、且對疾病存有誤解（認為是「裝病」）的家屬，應同時做到同理其身為照顧者的辛勞與負擔，並持續傳達病人仍需接受完整治療的重要性，此回應兼顧情感支持與衛教立場，最為適當（B✓，本題答案）。「等她病好了，生活就會恢復正常」屬過度簡化、忽略家屬當下真實負擔與情緒的空泛保證（A✗）；「醫師已經改藥，病情應該可以控制住」對疾病病程做出過度樂觀、無法保證的臆測，且未回應家屬對疾病本質的誤解與情緒負擔（C✗）；「症狀很快就緩解」同樣是不切實際的過度保證，憂鬱症病程並非皆能迅速緩解，且未澄清家屬「裝病」之錯誤認知，此回應不適當（D✗）。'},
{n:1224,no:24,subj:'情緒障礙與危機處理',q:'游先生，雙相情緒障礙症病人，在病房看到一位思覺失調症病人因手抖而掉藥物到地上，游先生認為這是病友的拒藥行為，大聲要求護理人員處理此病友的拒藥行為。針對此情況，護理人員最適宜的處理為下列何者？',opts:['A.鼓勵游先生說出其過去拒藥的經驗','B.先了解掉藥病人的狀況，並將游先生帶開轉移其注意力','C.告訴游先生，這不關他的事','D.以平靜的口吻告訴游先生藥物再補給就好了'],ans:[1],expl:'本題答案為B。此情況涉及兩位病人：其一為手抖掉藥、可能有藥物副作用（如錐體外徑症狀）需評估之病人，其二為情緒激動、要求介入的游先生。護理人員應先了解掉藥病人的實際狀況（是否為手抖等副作用而非故意拒藥），同時將游先生帶開、轉移其注意力以緩和其激動情緒，此為兼顧雙方需求之最適宜處理（B✓，本題答案）。鼓勵游先生分享過去拒藥經驗與當下情境無關，無助於化解當下狀況，此回應不適當（A✗）；直接告知「這不關他的事」帶有否定與忽視意味，容易使游先生更加不滿，並非適當之處置（C✗）；僅以平淡口吻告知補藥即可，未處理游先生激動情緒亦未評估掉藥病人是否有藥物副作用問題，處置並不完整（D✗）。'},
{n:1225,no:25,subj:'生理治療與物質濫用',q:'吳先生服用古柯鹼過量，出現血壓上升呼吸不規則的中毒症狀而求醫，下列何項護理措施為最優先考量？',opts:['A.鼓勵病人以語言方式表達內在感受','B.維持生命徵象的穩定','C.觀察戒斷症狀','D.給予衛生教育'],ans:[1],expl:'本題答案為B。吳先生現處於古柯鹼急性中毒狀態，已出現血壓上升、呼吸不規則等生理危急徵象，依急救之ABC原則及Maslow需求層級，維持生命徵象穩定、確保生理安全為此刻絕對優先之護理措施（B✓，本題答案）。鼓勵語言表達內在感受屬心理社會層面之介入，於病人生理狀況尚未穩定前並非優先考量（A✗）；觀察戒斷症狀適用於中毒後續或停藥階段之評估，並非此刻急性中毒生理不穩定時的首要措施（C✗）；衛生教育屬於病情穩定後方可進行之介入，於急性生理危急期並非優先措施（D✗）。'},
{n:1226,no:26,subj:'心理病理與治療理論',q:'人格障礙症病人無法感受症狀所帶來的痛苦，所以病人極少認為有治療的必要，一般都是性格問題導致生活適應上產生障礙，才會到精神科求診，因此治療重點包括下列何者？①改變病人個性本質　②改善導致其困擾之症狀　③給予情緒支持　④增進病人適應生活及適應環境的能力',opts:['A.①②③','B.①②④','C.①③④','D.②③④'],ans:[3],expl:'本題答案為D。人格障礙症治療之務實目標，在於改善其性格所導致之困擾症狀（②✓）、提供情緒支持（③✓），並增進其對生活與環境的適應能力（④✓），此三者皆為臨床上可行、合理之治療重點，故②③④正確，本題答案為D。至於「改變病人個性本質」（①），人格特質屬長期穩定、根深蒂固之行為與思考模式，臨床治療目標並非、也難以從根本改變病人的人格本質，而是聚焦於功能與適應之改善，此敘述不切實際、有誤（①✗，此為唯一錯誤敘述，故排除含①之選項A、B）。'},
{n:1227,no:27,subj:'心理病理與治療理論',q:'照護妄想型人格障礙症病人，為使病人至少可以信任一些人的態度，其治療首重下列何者？',opts:['A.評估病人自殺意念','B.引導病人注意自己的行為','C.建立治療性人際關係','D.協助病人認知合作及妥協的重要性'],ans:[2],expl:'本題答案為C。妄想型人格障礙症病人核心特徵為對他人普遍抱持不信任與猜疑，故照護此類病人之治療首重建立穩定、一致、可信賴的治療性人際關係，唯有建立基本信任後，其他介入方能有效推展，此為最優先之治療重點（C✓，本題答案）。評估自殺意念雖為精神科常規評估項目，但並非此類病人為建立信任所首重之治療重點，題幹並未提及自殺相關線索（A✗）；引導病人注意自己的行為與協助病人認知合作及妥協的重要性，皆屬於已建立基本信任關係後方能推展的後續治療目標，並非「首重」的第一步（B✗、D✗）。'},
{n:1228,no:28,subj:'心理病理與治療理論',q:'邊緣型人格障礙症病人有挑撥與討好的人際互動、情緒及明顯的衝動，最適宜的護理措施為下列何者？',opts:['A.建立良好的治療性人際關係','B.避免被病人操縱','C.與病人訂契約保證不自殺','D.教導認識社會心理壓力'],ans:[1],expl:'本題答案為B。邊緣型人格障礙症病人典型表現為分裂（splitting）機轉下之挑撥、討好等操縱性人際互動模式，護理人員應針對此特定行為模式，維持一致、清楚的界限，避免被病人的操縱行為影響治療團隊之一致性，此為最切合題幹所述行為模式之護理措施（B✓，本題答案）。建立治療性人際關係雖為精神科照護之普遍原則，但未能針對題幹所強調之「挑撥與討好、操縱」行為特徵提出具體對應措施，較不具針對性（A✗）；題幹並未提及自殺相關議題，訂立不自殺契約與題幹情境無直接關聯（C✗）；教導認識社會心理壓力亦非針對題幹所述操縱性人際模式之直接對應措施（D✗）。'},
{n:1229,no:29,subj:'生理治療與物質濫用',q:'有關Methylphenidate（Ritalin）的敘述，下列何者錯誤？',opts:['A.改善病童的過動與衝動','B.容易有食慾不振的問題','C.最適合的服藥時間是傍晚至夜間','D.可以在寒暑假或放假時暫停服藥'],ans:[2],expl:'本題答案為C（此為錯誤敘述）。Methylphenidate屬中樞神經興奮劑，服用後具提神、興奮作用，若於傍晚至夜間服用容易導致失眠、影響夜間睡眠，故臨床上多建議於白天（如晨間、上學前）服用，「最適合傍晚至夜間服藥」之敘述有誤，為本題答案（C✗，本題所選之錯誤敘述）。Methylphenidate確實可有效改善注意力不足過動症病童之過動與衝動症狀，此敘述正確（A為正確敘述）；食慾不振（食慾抑制）為中樞神經興奮劑常見之副作用，此敘述正確（B為正確敘述）；臨床上確實可視情況於寒暑假、非上學期間安排藥物假期（drug holiday），以減少長期用藥對食慾與生長之影響，此敘述正確（D為正確敘述）。'},
{n:1230,no:30,subj:'老年精神與失智照護',q:'對於失智症病人的護理措施，下列何者正確？',opts:['A.環境儘量多樣化，以增加刺激','B.若病人夜裡睡眠紊亂，白天時調暗燈光，讓病人補充睡眠','C.儘量安排不同護理人員照顧，以增加病人對護理人員的熟悉','D.鼓勵家屬自家中帶熟悉的物品置於病人的房間，並儘量不更動擺設'],ans:[3],expl:'本題答案為D。失智症病人對環境改變的適應力差，熟悉的物品與固定不變的擺設可降低其定向感混亂與不安全感，為失智症照護之重要原則，此敘述正確（D✓，本題答案）。失智症病人宜維持環境穩定、避免過度多樣化的刺激，以免造成困惑與焦慮，此敘述有誤（A✗）；若夜間睡眠紊亂，白天應維持適度光線與活動以強化日夜節律區辨（避免日夜顛倒加劇），而非調暗燈光讓病人白天補眠，此敘述有誤（B✗）；失智症病人宜由固定、熟悉的照顧者持續照顧以建立信任與降低混亂，而非經常更換不同護理人員，此敘述有誤（C✗）。'},
{n:1231,no:31,subj:'老年精神與失智照護',q:'有關老年精神病人的護理評估原則，下列何者正確？',opts:['A.老年病人記性差，不論時間長短，收集資料宜一次完成','B.老年病人愛回顧過去生命經驗，基於此時此刻原則，此部分資料不須收集','C.老年病人對問題反應很慢或無法適當回答，可以改變問法試試看','D.老年病人因為記憶力和判斷力都不好，因此僅以家屬所敘述為主'],ans:[2],expl:'本題答案為C。老年病人因認知處理速度或感官功能改變，對問題反應較慢或難以適當回答時，護理人員應有耐心地嘗試調整問法（如簡化用語、放慢速度、改用不同角度提問），以利獲取正確評估資料，此為合宜、彈性之評估原則（C✓，本題答案）。老年病人易因體力、專注力限制而疲累，資料收集宜採多次、較短時段進行，而非堅持一次完成，此敘述有誤（A✗）；生命回顧（life review）本身即為具治療價值之老年心理評估與介入方式，不應以「此時此刻原則」為由排除收集，此敘述有誤（B✗）；不應僅因老年而預設病人記憶力、判斷力必然不佳，逕自捨棄病人本身之主觀陳述，仍應以病人自述為評估之重要依據，此敘述過於武斷，有誤（D✗）。'},
{n:1232,no:32,subj:'精神復健與社區精神衛生',q:'李小姐參加復健商店的工作訓練，此為第幾級的預防概念？',opts:['A.第一級預防','B.第二級預防','C.第三級預防','D.第四級預防'],ans:[2],expl:'本題答案為C。復健商店之工作訓練，係針對已罹病、症狀穩定之病人，協助其恢復生活與職業功能、預防失能惡化及促進社會復健，屬三段預防中之第三級預防（復健期）範疇，此敘述正確（C✓，本題答案）。第一級預防著重於疾病發生前之健康促進與特殊保護，與已進行職能復健訓練之情境不符（A✗）；第二級預防著重於疾病之早期發現與早期治療，亦與已進入復健訓練階段之情境不符（B✗）；第四級預防之概念著重於避免不必要的醫療介入或過度醫療化，與題幹之職能復健訓練性質不符（D✗）。'},
{n:1233,no:33,subj:'精神復健與社區精神衛生',q:'慢性精神病人參與庇護性工場活動之訓練目的，下列何者正確？',opts:['A.增強面對高壓力情境的工作技能','B.提供工作態度和工作能力的訓練','C.做為競爭性工作的基礎','D.達到自給自足的收入'],ans:[1],expl:'本題答案為B。庇護性工場提供低壓力、支持性的工作環境，其主要目的在於協助慢性精神病人建立基本的工作態度（如出勤、配合度）與工作能力，作為職能復健過程的一環，此敘述正確（B✓，本題答案）。庇護性工場之工作環境設計原則是降低壓力、提供支持，並非用以訓練面對高壓力情境的能力，此敘述有誤（A✗）；庇護性工場屬過渡性、支持性就業安排，並非直接以競爭性職場為訓練基礎或目標，此敘述並非其直接訓練目的，有誤（C✗）；庇護性工場之收入通常屬象徵性或補助性質，並非以達到自給自足收入為其訓練目的，此敘述有誤（D✗）。'},
{n:1234,no:34,subj:'精神復健與社區精神衛生',q:'社區精神衛生護理師的主要角色功能，下列何者正確？',opts:['A.不可單獨在社區進行團體諮詢活動','B.宜促進病人與醫療人員之間的訊息溝通與聯繫','C.擬定護理計畫需以功利成效為導向','D.發現心理困擾者須宣導藥物治療的優先性'],ans:[1],expl:'本題答案為B。社區精神衛生護理師之核心角色之一即為病人、家屬與醫療團隊之間的橋梁，促進三方訊息溝通與聯繫，確保照護之連續性，此敘述正確（B✓，本題答案）。社區精神衛生護理師具備獨立在社區執行團體諮詢等專業活動之能力與職責，並非不可單獨進行，此敘述有誤（A✗）；護理計畫之擬定應以病人整體需求與福祉為核心，而非狹隘地以功利成效為導向，此敘述有誤（C✗）；面對心理困擾者，社區精神衛生護理應採生理心理社會之整合性照護與轉介，而非僅宣導藥物治療優先，此敘述過於偏頗，有誤（D✗）。'},
{n:1235,no:35,subj:'精神復健與社區精神衛生',q:'有關以社區為基礎的精神醫學治療模式，下列何者正確？',opts:['A.強調在醫院中持續復健治療','B.適合急性期精神病人','C.較適合症狀穩定的病人','D.主要由醫事人員所主導'],ans:[2],expl:'本題答案為C。以社區為基礎之精神醫學治療模式，適用對象為病情已趨穩定、可於社區環境中維持功能並接受支持性照護的病人，此敘述正確（C✓，本題答案）。此模式強調將照護場域由醫院轉移至社區，而非強調持續留在醫院中復健，此敘述方向相反，有誤（A✗）；急性期病人症狀不穩定，通常需要住院或密集醫療介入，並不適合以社區為基礎之治療模式，此敘述有誤（B✗）；社區精神醫學模式強調多專業團隊與病人、家屬、社區資源之共同參與合作，並非僅由醫事人員主導，此敘述有誤（D✗）。'},
{n:1236,no:36,subj:'情緒障礙與危機處理',q:'有關危機處置的技巧，下列何者正確？',opts:['A.危機處置必須以長期漸進的問題解決為目的','B.宣洩是指病人談到所關切的事，產生情感釋放與減輕壓力的功能','C.會談中宜阻止病人哭泣，以特殊情境進入事件中','D.澄清是指影響病人去接受某個信念或想法'],ans:[1],expl:'本題答案為B。宣洩（ventilation/catharsis）係指協助病人談論其所關切、困擾之事件，藉由情感的表達與釋放以減輕內在壓力，此為危機處置常用且重要之技巧，敘述正確（B✓，本題答案）。危機處置著重於「短期、立即」的問題處理與情緒穩定，而非以長期漸進的問題解決為目的，此敘述有誤（A✗）；會談中若病人出現哭泣等情緒反應，應予以接納並提供空間讓其抒發，而非加以阻止，此敘述有誤（C✗）；澄清（clarification）技巧是協助病人釐清、具體化自己原本模糊的想法或感受，而非護理人員影響病人去接受特定信念，此敘述定義有誤（D✗）。'},
{n:1237,no:37,subj:'情緒障礙與危機處理',q:'有關自殺防治策略的說明，下列何者正確？',opts:['A.自殺防治策略主要分為3個主要層面擬定方案，分為區域性（localization）、選擇性（selection）、指標性（indicator）策略','B.自殺防治之推行，與心理衛生體系及社會安全體系功能之充分發揮密切相關','C.選擇性自殺防治策略之標的為全體民眾，涵蓋導正媒體、減少致命性物品之可近性、降低自殺與精神疾病的社會污名化程度','D.指標性自殺防治以高風險群為對象，包括憂鬱症共同照護體系之推行'],ans:[1],expl:'本題答案為B。自殺防治為跨體系之公共衛生議題，其成效有賴心理衛生體系（如精神醫療、諮商資源）與社會安全體系（如社福、警政、教育等）功能之充分發揮與相互配合，此敘述正確、涵蓋範圍最為適切（B✓，本題答案）。國際上自殺防治三層次策略之標準名稱為全面性（universal）、選擇性（selective）、指標性（indicated）策略，「區域性（localization）」並非標準分類名稱，此敘述用詞有誤（A✗）；「標的為全體民眾」實為全面性（universal）策略之定義，而非選擇性策略（選擇性策略之標的應為具共同風險因子之特定次族群），此敘述將全面性策略誤植為選擇性策略，有誤（C✗）；指標性策略之標的應為已出現早期徵兆或症狀之特定「個案」（如已診斷憂鬱症者），而「高風險群」一詞較貼近選擇性策略之定義，此敘述之分類界定不夠精確，有誤（D✗）。'},
{n:1238,no:38,subj:'思覺失調症與精神病症狀',q:'王先生因自傷傷人而由警消單位帶入強制住院，進病房後因出院需求未獲滿足立即舉起椅子砸向護理站，有關照護措施，下列何者正確？',opts:['A.護理師可立即自行予以約束協助王先生控制情緒','B.護理師應無論王先生的情緒狀態，先依醫囑給予王先生藥物注射，再協助控制躁動情緒','C.護理師應先評估王先生的反應，維持安全適當位置並進行自我防護準備','D.護理師應立即滿足王先生的需求，以緩解情緒'],ans:[2],expl:'本題答案為C。面對突發攻擊行為，護理處置的第一步應為評估病人當下反應與危險程度、確保自身與周遭人員位於安全適當位置，並做好自我防護準備，此為危機處置之標準流程與優先原則（C✓，本題答案）。約束涉及病人人身自由限制，應依機構規範與團隊評估後執行，並非護理師可單獨、立即自行決定執行，此敘述不適當（A✗）；給藥仍須先評估病人當下狀態以判斷是否符合醫囑使用時機與必要性，而非「無論情緒狀態」皆一律先給藥，此敘述過於絕對，有誤（B✗）；立即滿足病人不合理之需求以換取情緒緩解，反而可能強化其以攻擊行為達成目的之不良行為模式，並非適當之處置原則（D✗）。'},
{n:1239,no:39,subj:'其他',q:'關於自閉症類群障礙症（原為自閉性疾患）的描述，下列何者正確？',opts:['A.喜歡玩車子的輪子之儀式化行為','B.喜歡主動參與「扮家家酒」的遊戲','C.堅持每天走固定的路線回家之儀式化行為','D.對感官刺激反應過強的仿說言語'],ans:[2],expl:'本題答案為C。堅持固定路線、儀式化及不容改變的行為模式，是DSM-5診斷準則中「侷限、重複的行為模式」之典型且常被引用之例證，符合自閉症類群障礙症的核心特徵（C✓，本題答案）。喜歡把玩物品局部（如車輪）雖亦可見於部分自閉症類群障礙症孩童，但並非教科書上用以定義「儀式化、堅持一致」此一核心特徵最具代表性之典型描述（A✗，較不具代表性）；自閉症類群障礙症孩童典型表現為象徵性／假扮遊戲（如扮家家酒）發展遲緩或缺乏興趣參與，而非主動喜歡參與此類遊戲，此敘述與臨床特徵相反，有誤（B✗）；仿說（echolalia）為語言溝通層面之特徵，與「對感官刺激反應過強」分屬不同面向，兩者混合成單一敘述並不精確，此敘述有誤（D✗）。'},
{n:1240,no:40,subj:'情緒障礙與危機處理',q:'許小姐被家人送來急診，醫師在病歷上寫許小姐有自殺企圖（suicide attempt），下列何項屬於自殺企圖的評估？',opts:['A.許小姐表示有想死的念頭，但是還沒有想到要怎麼進行','B.許小姐正在寫遺書','C.許小姐要求男朋友來急診探望，不然要自殺','D.許小姐有藥物過量且手腕上有自己割傷的傷口'],ans:[3],expl:'本題答案為D。自殺企圖（suicide attempt）係指已實際採取具潛在致命性之自傷行為，題幹中許小姐已出現藥物過量並合併手腕自行割傷之實際傷害行為，符合自殺企圖之定義（D✓，本題答案）。表示有想死念頭但尚無具體計畫，僅屬於自殺意念（suicidal ideation），尚未有實際行動，並非自殺企圖（A✗）；書寫遺書屬於自殺準備（preparation）階段之行為表徵，尚未產生實際自傷行動，並非自殺企圖本身（B✗）；以自殺要脅他人滿足要求（如要求男友來探視），屬於自殺威脅（threat），是一種語言性的表達與要脅，並未實際採取自傷行動，並非自殺企圖（C✗）。'},
{n:1241,no:41,subj:'社區衛生與流行病學',q:'在聯合國所提出的2030永續發展目標（Sustainable Development Goals, SDGs）中，社區護理人員可提供下列那一項專業貢獻？',opts:['A.消除極端貧窮與飢餓','B.促進性別平等','C.改善弱勢易感族群健康','D.確保環境的永續性'],ans:[2],expl:'本題答案為C。社區護理人員之核心專業能力與職責聚焦於健康照護領域，故其在SDGs中最直接、最能發揮專業貢獻之處，即為透過健康篩檢、家訪、衛教與轉介等專業服務，改善弱勢與易感族群（如獨居長者、身心障礙者、新住民等）之健康狀況，此敘述最切合護理專業角色（C✓，本題答案）。消除貧窮飢餓、促進性別平等、確保環境永續性等雖亦為SDGs重要目標，但主要仰賴經濟、社會、環境等政策與跨部門合作，並非社區護理人員專業領域可直接、優先貢獻之項目，此三者相對而言並非護理專業之核心貢獻範疇（A✗、B✗、D✗）。'},
{n:1242,no:42,subj:'社區衛生與流行病學',q:'我國全民健康保險採全民強制納保制度，可能導致被保險者傾向過度使用醫療服務所造成的問題稱為下列何者？',opts:['A.逆選擇（adverse selection）','B.道德危害（moral hazard）','C.權益危害（right hazard）','D.自由選擇（free option）'],ans:[1],expl:'本題答案為B。道德危害（moral hazard）係指因保險提供財務保障、就醫成本降低，導致被保險者傾向過度使用醫療服務之現象，此為保險制度下常見之經濟行為問題，敘述正確（B✓，本題答案）。逆選擇是指高風險族群更傾向投保、而低風險族群傾向不投保，導致保險池風險結構失衡之現象，屬於「投保前」的資訊不對稱問題，與題幹描述之「投保後過度使用」不同，此敘述不符（A✗）；「權益危害」並非公共衛生或保險經濟學之標準專有名詞，此選項不適用（C✗）；「自由選擇」亦非用以描述此現象之專有名詞，與題幹描述之過度使用行為無關（D✗）。'},
{n:1243,no:43,subj:'老年精神與失智照護',q:'為服務轄區之失智長者，下列何種指標最適合作為規劃社區關懷據點數目的依據？',opts:['A.發生率','B.盛行率','C.死亡率','D.致死率'],ans:[1],expl:'本題答案為B。盛行率（prevalence）反映特定時間點轄區內「現有」失智症案例之總數，最能直接對應規劃社區關懷據點等服務量能所需之實際服務對象人數，為服務資源規劃最適合之依據（B✓，本題答案）。發生率（incidence）反映特定期間「新發生」之病例數，較適合用於評估疾病預防成效或病因研究，並非直接對應現有服務量能需求的最適指標（A✗）；死亡率與致死率分別反映死亡的發生情形與疾病嚴重度，皆非用以規劃社區照顧服務據點數目之直接依據（C✗、D✗）。'},
{n:1244,no:44,subj:'社區衛生與流行病學',q:'每年6～8月藉由殺蟲劑的噴灑以防止登革熱的傳染，是屬於那一種傳染病防治的策略？',opts:['A.消滅致病原','B.減少傳染原的傳染力','C.傳播媒介的控制','D.增加宿主的免疫力'],ans:[2],expl:'本題答案為C。登革熱經由病媒蚊（傳播媒介）叮咬傳播，噴灑殺蟲劑之目的在於撲殺病媒蚊、阻斷傳播途徑，屬於「傳播媒介的控制」策略，敘述正確（C✓，本題答案）。消滅致病原是指直接針對登革熱病毒本身進行清除，噴灑殺蟲劑係作用於蚊蟲而非病毒本身，此敘述不符（A✗）；減少傳染原的傳染力是針對已感染之傳染來源（如病人）降低其散播病原的能力，與噴灑殺蟲劑滅蚊之目標對象不同，此敘述不符（B✗）；增加宿主的免疫力是指提升易感族群本身的抵抗力（如疫苗接種），登革熱目前尚無普遍施打之常規疫苗，噴灑殺蟲劑亦非作用於宿主免疫力，此敘述不符（D✗）。'},
{n:1245,no:45,subj:'預防醫學與健康促進',q:'當PM2.5指數過高時，社區衛生護理人員衛教社區居民外出需戴口罩，此作法乃三段五級預防模式的那一項？',opts:['A.健康促進','B.特殊保護','C.早期治療','D.限制殘障'],ans:[1],expl:'本題答案為B。針對已知特定環境危害（PM2.5空氣污染）教導居民配戴口罩以直接阻絕暴露，屬於「特殊保護」措施，即針對特定危害因子所採取之具體防護行動，敘述正確（B✓，本題答案）。健康促進著重於一般性、非針對特定危害之整體健康生活型態促進（如均衡飲食、規律運動），並非針對PM2.5此一特定危害的直接防護措施，此敘述不符（A✗）；早期治療屬於次段預防，針對疾病已發生後之早期發現與治療，與尚未致病前之防護行為不同，此敘述不符（C✗）；限制殘障屬於三段預防中之處置，用於疾病已造成失能後之限制惡化，與題幹之預防性戴口罩行為無關，此敘述不符（D✗）。'},
{n:1246,no:46,subj:'社區衛生與流行病學',q:'多重抗藥性肺結核（MDR-TB）的逐漸增加，目前WHO在肺結核治療大力推動的方法為下列何者？',opts:['A.DOTS（Directly-Observed Treatment, Short-course）','B.IDOTS（Indirectly-Observed Treatment, Short-course）','C.DOTL（Directly-Observed Treatment, Long-course）','D.IDOTL（Indirectly-Observed Treatment, Long-course）'],ans:[0],expl:'本題答案為A。WHO自1990年代起大力推動「直接觀察治療、短程療法」（DOTS）策略，透過醫護人員或指定人員親自監督病人服藥，以確保服藥完整性、降低中斷治療與抗藥性產生之風險，為全球肺結核（含多重抗藥性肺結核）防治之核心推動策略，敘述正確（A✓，本題答案）。B、C、D選項中之「間接觀察（Indirectly-Observed）」或「長程療法（Long-course）」皆非WHO所推動之標準策略名稱，均屬混淆或杜撰之選項，並不正確（B✗、C✗、D✗）。'},
{n:1247,no:47,subj:'預防醫學與健康促進',q:'下列何種案例是屬於三段五級預防模式中第二段預防工作？',opts:['A.45歲的婦女加強鈣質攝取','B.班上同學被診斷為開放性肺結核，而自己去接受胸部X光篩檢','C.中風病人經急性醫療服務後，接受復健治療','D.每個人應每年接受體檢'],ans:[1],expl:'本題答案為B。因班上同學確診開放性肺結核而主動接受胸部X光篩檢，屬於因明確暴露史所觸發之針對性早期篩檢與早期發現，符合第二段預防（早期診斷、早期治療）之定義，敘述正確（B✓，本題答案）。45歲婦女加強鈣質攝取，屬於預防骨質疏鬆之特殊保護措施，為第一段（初段）預防範疇，此敘述不符（A✗）；中風病人於急性期後接受復健治療，目的在恢復功能、限制殘障，屬於第三段（後段）預防範疇，此敘述不符（C✗）；「每個人應每年接受體檢」為未針對特定暴露或風險之泛用性建議，雖廣義上與篩檢有關，但不若B選項具有明確之風險觸發情境，作為第二段預防之典型例證，B選項更為切題（D✗，較不具代表性）。'},
{n:1248,no:48,subj:'社區衛生與流行病學',q:'透過走街評估社區防火巷是否通暢、滅火器及消防栓是否可使用，主要是為了了解社區的那一層面？',opts:['A.溝通系統','B.經濟狀況','C.安全系統','D.福利系統'],ans:[2],expl:'本題答案為C。防火巷通暢與否、滅火器及消防栓可用性，皆屬社區消防與公共安全設施範疇，走街評估此類項目是為了解社區之「安全系統」層面，敘述正確（C✓，本題答案）。溝通系統關注社區內部訊息傳遞管道（如廣播、公告欄），福利系統關注社福資源與服務，經濟狀況關注產業與所得，皆與消防安全設施之評估內容不符（A✗、B✗、D✗）。'},
{n:1249,no:49,subj:'預防醫學與健康促進',q:'有關衛生教育方法的描述，下列何者錯誤？',opts:['A.示範教學法及反覆練習有助於成員學習正確的技能','B.運用角色扮演時，教育者須能接受學習者在角色扮演過程中的角色反應','C.個別指導常用於教導個案技術的學習','D.團體動力法強調運用團體壓力促使成員皆須表達意見'],ans:[3],expl:'本題答案為D（此為錯誤敘述）。團體動力法是運用團體成員間自然的互動歷程，促進成員自發性參與討論與相互學習，而非以「團體壓力」強迫每位成員都必須表達意見，此種強制表達之敘述扭曲了團體動力法之精神，為本題所選之錯誤敘述（D✗，本題答案）。示範教學法搭配反覆練習，確實有助於學習者正確掌握操作性技能，此敘述正確（A為正確敘述）；運用角色扮演時，教育者本即須具備接納學習者於扮演過程中各種角色反應之能力，此敘述正確（B為正確敘述）；個別指導因應個案獨特需求進行一對一技術教學，確為常用之教學方式，此敘述正確（C為正確敘述）。'},
{n:1250,no:50,subj:'社區衛生與流行病學',q:'依據臺灣地區的用水標準，適用於一級公共給水的河川生化需氧量（Biochemical Oxygen Demand, BOD）標準為何？',opts:['A.1 ppm以下','B.1～2 ppm','C.3～4 ppm','D.4 ppm以上'],ans:[0],expl:'本題答案為A。依臺灣地表水體分類標準，適用於一級公共給水（即可作為飲用水源、僅需簡易處理即可供水）之河川水質，其生化需氧量（BOD）標準訂為1 ppm以下，水質要求最為嚴格，敘述正確（A✓，本題答案）。1～2 ppm、3～4 ppm、4 ppm以上等數值，皆已超出一級公共給水之嚴格標準，較適用於等級較低（水質要求相對寬鬆）之用水分類，並非一級公共給水之標準，此三者皆不正確（B✗、C✗、D✗）。'},
{n:1251,no:51,subj:'預防醫學與健康促進',q:'王先生，62歲，1個月前檢查三酸甘油脂為250 mg/dL，血壓142/92 mmHg，飯前血糖96 mg/dL；王先生具有的心血管疾病危險因子中，下列何者錯誤？',opts:['A.男性','B.大於60歲','C.血脂過高','D.飯前血糖過高'],ans:[3],expl:'本題答案為D（此為錯誤敘述）。正常飯前（空腹）血糖標準為低於100 mg/dL，王先生之飯前血糖96 mg/dL仍屬正常範圍，並未達到血糖偏高或糖尿病前期之標準，故「飯前血糖過高」之敘述並不成立，為本題所選之錯誤敘述（D✗，本題答案）。男性本身即為心血管疾病之非可改變性危險因子之一，此敘述正確（A為正確敘述）；年齡大於60歲亦為心血管疾病重要危險因子，此敘述正確（B為正確敘述）；三酸甘油脂250 mg/dL已高於正常值（<150 mg/dL），屬血脂過高，為心血管疾病危險因子，此敘述正確（C為正確敘述）。'},
{n:1252,no:52,subj:'社區衛生與流行病學',q:'為提升新移民婦女之照護品質，社區衛生護理人員最需要加強何種照護能力？',opts:['A.伙伴關係的能力（partnership）','B.成為健康代言人（advocate）','C.多國語言能力（linguistic competence）','D.文化照護能力（culture competence）'],ans:[3],expl:'本題答案為D。文化照護能力（cultural competence）涵蓋對不同文化背景者之信念、價值觀、生活習慣與健康行為之理解與尊重，是提供跨文化照護（如新移民婦女照護）最核心且全面之能力，優先於單一語言能力或特定角色功能，敘述最為適切（D✓，本題答案）。伙伴關係能力與健康代言人角色雖亦為護理專業重要能力，但並非提升「新移民」照護品質時最關鍵、最具針對性之核心能力（A✗、B✗）；語言能力雖有助於溝通，但僅為文化照護能力之其中一環，若缺乏對文化脈絡的整體理解，單有語言能力仍難以提供適切照護，故文化照護能力較語言能力更為根本、全面（C✗）。'},
{n:1253,no:53,subj:'社區衛生與流行病學',q:'為促進新住民及其子女之健康而辦理的相關政策，下列何者錯誤？',opts:['A.成立新住民支持團體','B.加強辦理新住民子女之兒童發展篩檢工作','C.新住民子女有發展遲緩者，提供早期療育服務','D.成立國際小學，提供雙語教育'],ans:[3],expl:'本題答案為D（此為錯誤敘述）。成立國際小學提供雙語教育屬於教育體系之學制規劃，並非現行以健康促進與照護為核心之新住民及其子女健康政策範疇，與題幹所問之「促進健康」政策性質不符，為本題所選之錯誤敘述（D✗，本題答案）。成立新住民支持團體有助於提供情緒支持與資訊交流，為常見且合宜之政策措施，此敘述正確（A為正確敘述）；加強兒童發展篩檢有助於早期發現新住民子女之發展問題，此敘述正確（B為正確敘述）；對於篩檢出發展遲緩之新住民子女提供早期療育服務，為銜接篩檢後之合宜介入措施，此敘述正確（C為正確敘述）。'},
{n:1254,no:54,subj:'社區衛生與流行病學',q:'依據勞工健康保護規則，有關事業單位急救人員之安排，下列何者正確？',opts:['A.每100位員工須安排1位急救人員','B.每一輪班次至少要有1位急救人員','C.急救人員必須由醫護人員擔任','D.急救人員必須每年考試換證照'],ans:[1],expl:'本題答案為B。依勞工健康保護規則規定，事業單位應使每一輪班次之勞工工作時間內，至少有1名急救人員在場，以確保職場急救量能，敘述正確（B✓，本題答案）。急救人員之配置人數規定並非以「每100位員工1人」之比例計算，此敘述不符法規實際規定（A✗）；急救人員經完成規定之急救訓練課程即可擔任，並不要求須由醫護人員擔任，此敘述有誤（C✗）；急救人員資格證明亦無須每年重新考試換發證照之規定，此敘述有誤（D✗）。'},
{n:1255,no:55,subj:'老年精神與失智照護',q:'有關老人居家生活環境的設計，下列何者錯誤？',opts:['A.浴室的門以採內拉式為佳','B.樓梯宜加裝欄杆','C.不宜用藍、綠色等藝術燈光','D.夜晚宜預留小夜燈'],ans:[0],expl:'本題答案為A（此為錯誤敘述）。為預防老人於浴室內跌倒後阻塞門口、導致外部人員無法即時入內救援，浴室門宜設計為「外開式」，而非內拉（向內開）式，以利跌倒發生時仍可由外開啟門扇進行救援，此為老人居家安全設計之重要原則，「內拉式為佳」之敘述與安全原則相反，為本題所選之錯誤敘述（A✗，本題答案）。樓梯加裝欄杆有助於防止老人上下樓梯時跌倒，此敘述正確（B為正確敘述）；藍、綠等偏冷色調之藝術燈光可能影響老人視覺辨識與情緒穩定，不宜使用，此敘述正確（C為正確敘述）；夜晚預留小夜燈有助於老人夜間起身如廁時看清環境、預防跌倒，此敘述正確（D為正確敘述）。'},
{n:1256,no:56,subj:'社區衛生與流行病學',q:'有關全民健康保險的敘述，下列何者正確？①是一種社會保險制度　②其基本理念不包含危險共同分擔　③就診時需繳付部分負擔費用　④納保率超過99%，醫療院所特約率超過九成　⑤其主要財源來自公益彩券及菸品健康福利捐',opts:['A.①③④','B.①④⑤','C.②③④','D.②③⑤'],ans:[0],expl:'本題答案為A。全民健康保險本質為一種社會保險制度，具強制納保、量能負擔等社會保險特性，此敘述正確（①✓）；就醫時確實須依規定繳付部分負擔費用，此敘述正確（③✓）；我國全民健保納保率確實已超過99%，特約醫療院所比率亦超過九成，此敘述正確（④✓），故①③④皆正確，本題答案為A。至於「其基本理念不包含危險共同分擔」（②），危險（風險）共同分擔正是保險制度（包含社會保險）之核心基本理念，全民健保自然亦包含此理念，此敘述有誤（②✗）；全民健保之主要財源來自被保險人、投保單位及政府依比例繳納之保險費，而非公益彩券或菸品健康福利捐（菸捐僅為補充性財源之一，並非主要財源，公益彩券收入亦非健保財源），此敘述有誤（⑤✗，②⑤皆錯，故排除含②或⑤之選項B、C、D）。'},
{n:1257,no:57,subj:'社區衛生與流行病學',q:'有關臺灣公共衛生照護重點的變遷順序，下列何者正確？①家庭計畫　②婦幼衛生　③人口老化　④傳染病防治',opts:['A.①④③②','B.②①④③','C.④①②③','D.④②①③'],ans:[3],expl:'本題答案為D。臺灣公共衛生發展歷程大致依序為：二次大戰後首重傳染病防治（控制急性傳染病流行），隨後推展婦幼衛生工作（改善孕產婦與嬰幼兒健康），繼而積極推動家庭計畫（人口控制與生育調節政策），近數十年因少子化與平均餘命延長，人口老化議題方成為當前公共衛生之重要課題，其順序為傳染病防治→婦幼衛生→家庭計畫→人口老化，即④②①③，本題答案為D。其餘排列組合順序均與臺灣公共衛生政策實際發展之時序不符（A✗、B✗、C✗）。'},
{n:1258,no:58,subj:'婦幼衛生',q:'下列何項統計數值為決定家庭計畫推展之依據？',opts:['A.一般生育率（General Fertility Rate, GFR）','B.粗出生率（Crude Birth Rate, CBR）','C.年齡別生育率（Age-Specific Fertility Rate, ASFR）','D.總生育率（Total Fertility Rate, TFR）'],ans:[2],expl:'本題答案為C。年齡別生育率（ASFR）可呈現不同年齡層婦女之生育率分布狀況，有助於精確掌握各年齡族群之生育需求與趨勢，進而針對特定年齡層規劃家庭計畫資源與介入措施，為推展家庭計畫最具實務參考價值之統計依據（C✓，本題答案）。粗出生率僅反映總人口中之出生數比率，未考量年齡結構差異，資訊較為粗略（B✗）；一般生育率雖已排除非生育年齡人口，仍屬單一整體指標，缺乏年齡層級之細緻資訊（A✗）；總生育率反映平均每位婦女一生中之預期生育子女數，屬總結性指標，較適合用於評估整體人口趨勢，而非作為擬定分齡家庭計畫措施之直接依據，故均不如年齡別生育率適切（D✗）。'},
{n:1259,no:59,subj:'婦幼衛生',q:'有關梅毒的敘述，下列何者正確？①晚期梅毒傳染性較強　②性行為是主要傳染途徑　③孕期35週需接受梅毒篩檢　④孕期感染梅毒，胎兒可經垂直傳染罹患先天性梅毒',opts:['A.①②','B.①③','C.②④','D.③④'],ans:[2],expl:'本題答案為C。性行為（尤其是無防護性行為）確為梅毒之主要傳染途徑，此敘述正確（②✓）；孕婦若感染梅毒，梅毒螺旋體可經胎盤垂直傳染給胎兒，導致先天性梅毒，此敘述正確（④✓），故②④正確，本題答案為C。事實上，梅毒之傳染力以「早期」（一期、二期）最強，晚期（晚期潛伏期、三期）傳染力已明顯降低，「晚期梅毒傳染性較強」之敘述與實際情形相反，有誤（①✗）；我國孕婦產檢之梅毒篩檢係安排於「懷孕早期」（第一次產檢時）進行，以利及早發現及治療，而非等到孕期35週才篩檢，此敘述有誤（③✗，①③皆錯，故排除含①或③之選項A、B、D）。'},
{n:1260,no:60,subj:'社區衛生與流行病學',q:'根據Donabedian（1982）提出的結構（structure）、過程（process）、結果（outcome）概念進行社區健康方案的評值，下列何者正確？',opts:['A.保存每次方案進行的紀錄屬於結構評值','B.了解社區居民對健康知識或態度的改變屬於過程評值','C.了解方案運用的人力與資源是否適當屬於過程評值','D.了解社區居民的罹病率及死亡率屬於結果評值'],ans:[3],expl:'本題答案為D。罹病率與死亡率屬於健康方案介入後之最終健康結果指標，符合「結果評值」（outcome evaluation）之定義，敘述正確（D✓，本題答案）。保存方案執行紀錄屬於方案「執行過程」中所產生之文件記錄，較貼近過程評值之範疇，而非結構評值（結構評值應指方案執行「前」既有之人力、設備、資源等條件），此敘述歸類有誤（A✗）；社區居民健康知識或態度的改變，屬於方案介入後之初期／中介成效，較適合歸類為結果評值（尤其是短期結果），而非過程評值，此敘述歸類有誤（B✗）；了解人力與資源是否適當，本質上是評估方案執行「所具備」之資源條件是否充足合宜，應歸類為結構評值，而非過程評值，此敘述歸類有誤（C✗）。'},
{n:1261,no:61,subj:'社區衛生與流行病學',q:'社區讓個人在不同發展階段和過程中不斷學習，發展新的知識、信念、行為模式與價值觀等，屬於Warren（1972）所提出的那一項社區功能？',opts:['A.社會參與','B.社會教育','C.社會化','D.相互支援'],ans:[2],expl:'本題答案為C。社會化（socialization）係指社區將其知識、信念、行為規範與價值觀等，傳遞給不同發展階段之個人，使其習得並融入社會，題幹描述完全符合社會化功能之定義，敘述正確（C✓，本題答案）。社會參與著重於個人參與社區公共事務、團體活動之程度，並非知識價值觀之傳遞學習過程，此敘述不符（A✗）；「社會教育」並非Warren所提出社區功能之標準名稱（Warren所提出者為社會化、社會控制、社會參與、相互支援、生產分配消費等功能），此選項不適用（B✗）；相互支援著重於社區成員間於危難或需要時提供彼此支持協助，並非知識價值觀傳遞學習之功能，此敘述不符（D✗）。'},
{n:1262,no:62,subj:'社區衛生與流行病學',q:'下列那一種方法較不適宜用來收集社區的價值觀、民族性與特殊文化等資料？',opts:['A.訪談','B.擋風玻璃式調查','C.德菲研究法（Delphi method）','D.問卷調查'],ans:[2],expl:'本題答案為C。德菲研究法（Delphi method）是透過多回合匿名專家問卷，逐步收斂專家意見以達成共識之研究方法，其設計目的在於彙整「專家」意見而非直接收集社區居民本身之價值觀、民族性與生活文化資料，故較不適宜用於此類資料之收集（C✓，本題答案，即最不適宜之方法）。訪談可深入了解居民個人觀點與文化脈絡，屬適宜方法（A✗，屬適宜方法故非本題答案）；擋風玻璃式調查（windshield survey）為社區評估常用之觀察性方法，可初步了解社區環境與生活樣貌，屬適宜方法（B✗）；問卷調查可大量收集居民對特定議題之看法與態度，亦屬適宜方法（D✗）。'},
{n:1263,no:63,subj:'社區衛生與流行病學',q:'了解社區的圖書館數量、里民使用圖書館的頻率與對圖書館資源的滿意度等資訊，是屬於下列那一個次系統？',opts:['A.物理環境','B.健康及社會服務','C.教育','D.溝通'],ans:[2],expl:'本題答案為C。圖書館屬於教育資源之一環，其數量、使用頻率與滿意度等資訊，皆反映社區「教育」次系統之現況，敘述正確（C✓，本題答案）。物理環境次系統關注地理、建築、自然環境等硬體條件，並非圖書館使用行為本身（A✗）；健康及社會服務次系統關注醫療與社福資源，與圖書館教育資源性質不同（B✗）；溝通次系統關注社區內部訊息傳遞管道（如媒體、佈告欄），並非圖書館此類教育資源之使用評估（D✗）。'},
{n:1264,no:64,subj:'預防醫學與健康促進',q:'有關健康促進介入措施之敘述，下列何者正確？',opts:['A.社區賦權主要是一種由上而下的策略，可以透過協助民眾發現問題，進而加以解決','B.國家所推動的騎機車戴安全帽是屬於社區賦權策略','C.正向健康行為可以透過健康政策、支持性環境與教育活動來達成','D.社會改變是由下而上的改變策略，適合人數較多的情境'],ans:[2],expl:'本題答案為C。依渥太華憲章（Ottawa Charter）健康促進行動綱領，正向健康行為之達成需仰賴健全的健康政策、支持性環境之營造，以及健康教育活動等多元策略的整合運用，此敘述正確、完整（C✓，本題答案）。社區賦權（community empowerment）本質是由下而上（bottom-up），由社區居民自主發覺並解決自身問題，而非由上而下推動，此敘述方向有誤（A✗）；國家強制推動騎機車戴安全帽屬於由上而下的健康公共政策（法規強制）策略，並非社區賦權（由下而上）策略，此敘述歸類有誤（B✗）；社會改變（如立法、政策）策略多屬由上而下、適用於大規模人口情境，而由下而上之賦權策略則較適用於人數較少之社區情境，此敘述之方向與適用情境敘述相反，有誤（D✗）。'},
{n:1265,no:65,subj:'預防醫學與健康促進',q:'學校提供足夠的飲水機，以利推動多喝白開水活動，此策略是屬於健康促進的何種策略？',opts:['A.提供適切的健康服務','B.提供完善健康教學','C.擬定有效的健康政策','D.創造支持性的健康環境'],ans:[3],expl:'本題答案為D。學校透過增設飲水機等物理環境設施，使多喝白開水之健康行為更容易被落實，屬於營造有利健康行為產生之支持性環境，敘述正確（D✓，本題答案）。健康服務通常指醫療照護或篩檢等服務提供，並非硬體環境設施之建置（A✗）；健康教學著重於知識與觀念的傳授，題幹描述之飲水機提供並非教學活動（B✗）；健康政策通常指制度性規範或法規之訂定，題幹描述之飲水機屬環境設施而非政策本身，此敘述不符（C✗）。'},
{n:1266,no:66,subj:'預防醫學與健康促進',q:'王先生已經規律運動7個月，最近常覺得懶懶的不太想動。如果要讓王先生能持續維持運動，依據階段改變理論可以善用下列何種策略？',opts:['A.意識覺醒','B.情感喚起','C.環境再評價','D.增強管理'],ans:[3],expl:'本題答案為D。王先生已規律運動達7個月，屬跨理論模式（transtheoretical model）中之行動期或維持期，此階段最適合運用「增強管理」策略，透過給予獎勵、正向回饋等方式強化其持續運動之動機與行為，敘述正確（D✓，本題答案）。意識覺醒、情感喚起、環境再評價等改變方法，較適用於病人尚處於無意圖期或沉思期，用以提升其改變動機與認知準備度，並非用以維持已建立行為之策略，與王先生目前已規律運動之階段不符（A✗、B✗、C✗）。'},
{n:1267,no:67,subj:'社區衛生與流行病學',q:'社區衛生護理人員今天預計至下列4個家庭進行訪視，請問安排行程時，那個個案家庭的訪視應排在本日行程最後？',opts:['A.社區篩檢時膽固醇值220 mg/dL的吳女士','B.獨居，血壓值140/92 mmHg的李老先生','C.產後3天剛出院的新住民阮氏女士','D.至東南亞旅遊返國後疑似有登革熱的周先生'],ans:[3],expl:'本題答案為D。依據感染管制原則，居家訪視行程安排時，具傳染性疾病疑慮之個案（如疑似登革熱）應安排於當日「最後」一站訪視，以避免護理人員成為病媒或帶原之媒介，將可能之病原（或病媒蚊）自該戶攜帶至其後續訪視之其他個案家中，造成交叉感染風險，此為訪視排序之重要感染管制考量（D✓，本題答案）。膽固醇偏高之吳女士、血壓偏高獨居之李老先生，皆屬慢性病追蹤個案，病情相對穩定，並無傳染性疑慮，可安排於當日較早時段訪視（A✗、B✗）；產後3天剛出院之新住民阮氏女士，因產褥期照護具時效性（觀察產後併發症、哺乳與新生兒照顧指導等），需及早訪視介入，亦不適合排於最後（C✗）。'},
{n:1268,no:68,subj:'社區衛生與流行病學',q:'李先生重度失能，意識清楚，使用存留導尿管。近日僱用一位首次到臺灣的外籍看護工，執行居家照顧，社區衛生護理人員家訪時，想了解外籍看護工執行導尿管護理狀況，下列何種評估方式最為適切？',opts:['A.請外籍看護工說明導尿管護理流程','B.觀察外籍看護工實際導尿管護理流程','C.用護理技術核對表由家屬評核','D.詢問李先生外籍看護工執行狀況'],ans:[1],expl:'本題答案為B。直接觀察外籍看護工實際執行導尿管護理之操作過程，可最準確評估其實際技術熟練度與正確性，遠較口頭陳述或間接詢問更具客觀性與可信度，為評估技術性照護能力之黃金標準方法，敘述最為適切（B✓，本題答案）。僅請看護工口頭說明流程，可能因語言隔閡或知行落差，無法反映其實際操作是否正確，此方法不夠直接客觀（A✗）；由家屬使用護理技術核對表評核，家屬通常缺乏專業護理知識，難以準確判斷操作正確性，此方法不夠可靠（C✗）；詢問病人李先生對看護工執行狀況之主觀印象，亦非直接、客觀之技術評估方式，此方法不夠精確（D✗）。'},
{n:1269,no:69,subj:'社區衛生與流行病學',q:'喪偶的方女士帶著兒子，與離婚且育有一女的袁先生結婚，他們的家庭是屬於下列那種家庭類型？',opts:['A.雙人核心家庭（dyadic nuclear family）','B.雙核心家庭（binuclear family）','C.混合家庭（blended family）','D.家族網（kin network）'],ans:[2],expl:'本題答案為C。混合家庭（blended family）係指雙方皆帶著各自前一段婚姻所生子女，再組成新家庭之型態，題幹中方女士帶兒子、袁先生帶女兒再婚組成新家庭，完全符合混合家庭之定義，敘述正確（C✓，本題答案）。雙人核心家庭是指僅有夫妻二人、無子女同住之家庭型態，與題幹中雙方皆有子女之情形不符（A✗）；雙核心家庭通常指離婚後子女往來於父母雙方各自建立之家庭間的型態，與題幹描述之再婚組成新家庭情境不同（B✗）；家族網係指以血緣或姻親關係連結、跨越多個家戶之廣泛親屬支持網絡概念，並非用以描述題幹此種再婚混合家庭之核心結構型態（D✗）。'},
{n:1270,no:70,subj:'預防醫學與健康促進',q:'健康體能的4大要素，下列何者正確？①心肺耐力　②平衡力　③肌力與肌耐力　④柔軟度　⑤身體組成',opts:['A.①②③④','B.①②④⑤','C.①③④⑤','D.②③④⑤'],ans:[2],expl:'本題答案為C。健康體能（health-related fitness）之四大要素為心肺耐力（①）、肌力與肌耐力（③）、柔軟度（④）及身體組成（⑤），此四者共同構成評估個人整體健康與生活功能所需之體能要素，故①③④⑤正確，本題答案為C。至於「平衡力」（②），平衡能力屬於「運動體能」（skill-related fitness，或稱競技體能）之要素範疇（其餘尚包括敏捷性、反應時間、協調性、速度、爆發力），而非健康體能四大要素之一，此敘述有誤（②✗，此為唯一錯誤項目，故排除含②之選項A、B、D）。'},
{n:1271,no:71,subj:'老年精神與失智照護',q:'83歲獨居、輕度中風、使用助行器的黃老太太，ADL 80分，下列那些資源較適合提供給她？①護理之家　②送餐服務　③居家服務　④居家營養師',opts:['A.①②','B.②③','C.③④','D.①④'],ans:[1],expl:'本題答案為B。黃老太太ADL評分達80分，屬功能狀況相對良好、僅需部分協助之獨居長者，送餐服務可解決其獨居備餐之不便與營養攝取問題，居家服務可協助其日常生活及環境安全維護等需求，二者皆切合其現況所需，此敘述正確（②③✓），本題答案為B。護理之家屬機構式照護，適用於功能狀況較差、需高密度專業照護之個案，以黃老太太目前ADL 80分之較佳功能狀況而言，尚不需入住機構，此選項並不適合（①✗）；居家營養師之介入通常針對有特定營養問題或特殊飲食需求之個案，題幹並未顯示黃老太太有此類特殊需求，並非現階段最優先切合之資源（④✗，①④皆不適合，故排除含①或④之選項A、C、D）。'},
{n:1272,no:72,subj:'預防醫學與健康促進',q:'為了提升學童養成口腔衛生之習慣，學校衛生護理師應用PRECEDE-PROCEED模式，下列何者屬於增強因素（reinforcing factors）？①牙醫到校檢查學童口腔衛生　②布告欄張貼有口腔衛生海報　③媽媽讚賞學童餐後刷牙的行為　④老師給予餐後潔牙學童好寶寶點數',opts:['A.①②','B.②③','C.③④','D.①④'],ans:[2],expl:'本題答案為C。增強因素（reinforcing factors）係指行為發生「之後」所獲得之回饋、獎勵或他人反應，用以強化該行為持續出現，媽媽讚賞學童刷牙行為（③）與老師給予好寶寶點數（④）皆屬行為發生後之正向回饋，符合增強因素之定義，故③④正確，本題答案為C。牙醫到校檢查口腔衛生（①），屬提供服務資源以利行為執行之「使能因素」（enabling factors），並非行為後之回饋強化，此敘述歸類有誤（①✗）；布告欄張貼衛教海報（②），屬提供知識、建立態度動機之「傾向因素」（predisposing factors），亦非行為後之增強回饋，此敘述歸類有誤（②✗，①②皆非增強因素，故排除含①或②之選項A、B、D）。'},
{n:1273,no:73,subj:'社區衛生與流行病學',q:'有關學校健康環境的建立與維護之敘述，下列何者正確？',opts:['A.飲水機濾心應每半年更換一次','B.教室桌子高度約為身高之7分之2','C.教室黑板照度至少應維持350米燭光以上','D.教室噪音響度以不超過80分貝為原則'],ans:[0],expl:'本題答案為A。學校飲用水設備之濾心依現行學校飲用水設備維護管理規範，建議定期（約每半年）更換，以維持飲水水質安全，此敘述符合學校飲用水衛生管理之一般原則（A✓，本題答案）。教室桌椅高度應依學童身高比例個別化配置，惟B選項所述之特定比例數值並非學校衛生環境標準中被普遍引用之正確數據，此敘述不正確（B✗）；教室黑板照度、教室噪音容許分貝數，各國及我國相關學校衛生法規標準另有明確規範數值，C、D選項所列之數值與現行標準並不相符，此二敘述不正確（C✗、D✗）。'},
{n:1274,no:74,subj:'社區衛生與流行病學',q:'有關職業衛生護理人員需具備的主要角色與能力之敘述，下列何者錯誤？',opts:['A.員工健康管理與促進，包含安排各項勞工健檢','B.進行勞工作業環境測定，並將結果通報環安人員，進行現場作業改善','C.按主管機關的法令規範，適度調整業務','D.與主管或相關部門溝通協調，包括業務相關經費或配工'],ans:[1],expl:'本題答案為B（此為錯誤敘述）。勞工作業環境之測定（如噪音、粉塵、化學物質濃度等物理化學性測定）屬工業衛生技師／作業環境測定人員之專業職掌，職業衛生護理人員之角色核心在於員工健康管理、健康監測與跨部門溝通協調，而非親自執行作業環境測定工作，此敘述將環境測定歸為護理人員之角色，並不精確，為本題所選之錯誤敘述（B✗，本題答案）。員工健康管理與促進、安排勞工健檢，確為職業衛生護理人員之核心職責，此敘述正確（A為正確敘述）；依主管機關法令規範適度調整業務，亦為職業衛生護理人員應具備之能力，此敘述正確（C為正確敘述）；與主管及相關部門溝通協調業務經費或配工事宜，亦屬其角色功能之一，此敘述正確（D為正確敘述）。'},
{n:1275,no:75,subj:'老年精神與失智照護',q:'下列何者不是臺灣老年人口成長的因素？',opts:['A.社會經濟水準的提升','B.醫療科技的進步','C.全球化風潮的影響','D.公共衛生水準的提升'],ans:[2],expl:'本題答案為C（此為非成長因素之敘述）。全球化風潮主要涉及經濟、資訊與文化之跨國流動，並非直接驅動人口老化（平均餘命延長、死亡率下降）之公共衛生或醫療因素，與臺灣老年人口成長並無直接關聯，為本題所選之非成長因素（C✗，本題答案）。社會經濟水準提升有助於改善整體營養與生活條件，延長平均壽命，為老年人口成長之因素之一，此敘述為正確之成長因素（A為成長因素）；醫療科技進步可有效延長壽命、降低死亡率，亦為老年人口成長之重要因素，此敘述為正確之成長因素（B為成長因素）；公共衛生水準提升（如傳染病防治、環境衛生改善）大幅降低死亡率，同為老年人口成長之關鍵因素，此敘述為正確之成長因素（D為成長因素）。'},
{n:1276,no:76,subj:'社區衛生與流行病學',q:'有關出院準備服務的描述，下列何者錯誤？',opts:['A.可達到提供持續性照護的目的','B.以個案為中心的轉銜機制','C.適用於病情穩定確定出院時進行','D.利用高危險篩檢表找出需服務的個案'],ans:[2],expl:'本題答案為C（此為錯誤敘述）。出院準備服務應自病人「入院初期」即開始評估與規劃，及早辨識具出院照護需求之高危險個案並提前介入，而非等到病情穩定、確定出院時才臨時進行，「適用於病情穩定確定出院時進行」之敘述與出院準備服務應及早介入之原則相反，為本題所選之錯誤敘述（C✗，本題答案）。出院準備服務之目的即在銜接住院與返家後之照護，達到持續性照護之目標，此敘述正確（A為正確敘述）；此服務強調以個案需求為核心，規劃返家或轉介之銜接機制，此敘述正確（B為正確敘述）；透過高危險篩檢表及早找出有出院準備服務需求之個案，亦為此服務之標準作業方式，此敘述正確（D為正確敘述）。'},
{n:1277,no:77,subj:'社區衛生與流行病學',q:'有關流行病學的敘述，下列何者正確？',opts:['A.是精準醫學中的一門學科','B.是研究族群健康狀態、疾病分布狀況及致病因子的一門學科','C.探討三W（What、Where、Who）的分析','D.分析性流行病學主要是探討「引起疾病的生理性原因」'],ans:[1],expl:'本題答案為B。流行病學係研究族群（而非個別病人）之健康狀態、疾病於人、時、地之分布情形，以及探討致病相關因子之學科，此為流行病學之標準經典定義，敘述正確（B✓，本題答案）。流行病學是公共衛生之基礎核心學科，其發展早於「精準醫學」概念，二者並非從屬關係，此敘述有誤（A✗）；描述流行病學經典探討之三要素為人（Who）、地（Where）、時（When），而非「What」，此敘述用詞有誤（C✗）；分析性流行病學旨在探討疾病與暴露因子（可涵蓋生理、行為、環境、社會等多面向）之因果關聯，並不侷限於「生理性原因」，此敘述過於狹隘，有誤（D✗）。'},
{n:1278,no:78,subj:'婦幼衛生',q:'有關我國的婦幼衛生照護指標，下列何者錯誤？',opts:['A.2020年30～69歲婦女3年內曾接受子宮頸癌篩檢率維持70%','B.2025年45～69歲婦女2年內曾接受乳癌篩檢率達70%','C.2025年人類乳突病毒疫苗接種推廣至小五女生接種率100%','D.2020年高危險群孕婦接受產前遺傳診斷之異常追蹤率提升至98%'],ans:[2],expl:'本題答案為C（此為錯誤敘述）。任何大型公共衛生疫苗接種計畫，實務上皆難以達到「100%」之絕對接種率（受個人意願、健康狀況、家長同意與否等因素影響，恆無法完全涵蓋所有對象），以「100%接種率」作為政策目標數據之敘述並不切實際，為本題所選之錯誤敘述（C✗，本題答案）。A、B、D選項所列之子宮頸癌篩檢率、乳癌篩檢率、產前遺傳診斷異常追蹤率等，皆為相對合理、且確為政策文件中常見引用之具體目標百分比數值，此三者敘述正確（A、B、D為正確敘述）。'},
{n:1279,no:79,subj:'預防醫學與健康促進',q:'有關慢性病的敘述，下列何者最正確？①僅好發於高齡群體　②潛伏期長須終生控制　③需要密集的醫療照護　④常殘留殘障或機能不全',opts:['A.①②','B.②③','C.②④','D.①④'],ans:[2],expl:'本題答案為C。多數慢性病具潛伏期長、病程緩慢進展之特性，一旦罹病往往需終生持續控制管理，此敘述正確（②✓）；慢性病病程中常伴隨器官功能逐漸退化，可能造成不同程度之殘障或機能不全後遺症，此敘述正確（④✓），故②④正確，本題答案為C。慢性病可發生於各年齡層（含兒童與青壯年，如第一型糖尿病、先天性心臟病等），並非僅好發於高齡族群，此敘述過於絕對，有誤（①✗）；多數慢性病之日常管理著重於「持續性」而非「密集性」醫療照護（如定期門診追蹤、自我照顧管理即可），僅少數急性惡化期才需密集醫療介入，「需要密集的醫療照護」作為慢性病之普遍特性敘述並不精確，有誤（③✗，①③皆錯，故排除含①或③之選項A、B、D）。'},
{n:1280,no:80,subj:'預防醫學與健康促進',q:'有關社區衛生護理人員提供代謝症候群個案的飲食衛教，下列何者錯誤？',opts:['A.少鹽、少油','B.少吃澱粉高的食物，每日控制不超過6公克','C.多吃含高纖維的食物','D.避免空腹飲酒'],ans:[1],expl:'本題答案為B（此為錯誤敘述）。「每日控制不超過6公克」屬每日鹽（鈉）攝取量之衛教建議數值，若將此極低之公克數套用於「澱粉類（主食）攝取量」之衛教建議，數值明顯不合理且遠低於人體所需基本熱量來源之攝取範圍，此敘述將鹽份限制數值誤植於澱粉攝取衛教，為本題所選之錯誤敘述（B✗，本題答案）。少鹽、少油為代謝症候群飲食衛教之基本正確原則，此敘述正確（A為正確敘述）；多攝取高纖維食物有助於血糖血脂控制及腸胃道健康，為正確之衛教內容（C為正確敘述）；空腹飲酒易加重血糖波動及腸胃刺激，衛教應建議避免空腹飲酒，此敘述正確（D為正確敘述）。'}
];
